#!/usr/bin/env python3
"""The ER-2 guard (RT-7), blocking, on lib/shellscan.py. See worktree-guard.sh for the rules."""
import json, os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "lib"))
import shellscan, paddockpaths


NAME = "worktree-guard"
MAIN = paddockpaths.main_checkout()  # None when it cannot be derived: git writes by agents are then refused

WRITES = {"checkout", "switch", "commit", "merge", "rebase", "reset", "push", "cherry-pick", "revert", "am", "pull",
          "restore", "clean", "stash", "update-ref"}
BRANCH_W = {"-D", "-d", "-m", "-M", "--delete", "--move", "--force", "-f", "-C", "-c", "--copy"}
TAG_RO = {"-l", "--list", "-n", "-v", "--contains", "--points-at", "--no-contains", "--merged", "--no-merged"}
WT_W = {"remove", "prune", "move", "repair"}


def norm(p):
    return os.path.realpath(p).casefold()


def in_main(d):
    if MAIN is None:
        return True
    d, m = norm(d), norm(MAIN)
    return d == m or d.startswith(m + os.sep)


def short_n(args):
    """`-n` among a commit's short flags (`-n`, `-nm`, `-anm`); letters after one that takes a value (-m, -F, -C, -c, -t) are
    that value, not flags."""
    for a in args:
        if a.startswith("-") and not a.startswith("--") and len(a) > 1:
            for ch in a[1:]:
                if ch == "n":
                    return True
                if ch in "mFCctSu":
                    break
    return False


def is_write(sub, args):
    if sub in WRITES:
        return True
    if sub == "branch":
        return any(a in BRANCH_W for a in args)
    if sub == "tag":
        return bool(args) and not any(a in TAG_RO for a in args)
    if sub == "worktree":
        return bool(args) and args[0] in WT_W
    return False


# An allow-list: a subagent's `git config` that names `paddock` passes only as a lookup (these flags, the get/list subcommands, or one
# bare key). Every other option (-z, --includes, --show-scope, --fixed-value ...) only modifies a read or a write, so it decides nothing.
CONFIG_LOOKUP_FLAGS = {"--get", "--get-all", "--get-regexp", "--get-urlmatch", "--list", "-l"}
CONFIG_WRITE_FLAGS = {"--unset", "--unset-all", "--add", "--replace-all", "--rename-section", "--remove-section", "--edit", "-e"}
CONFIG_SCOPE = {"--local", "--global", "--system", "--worktree", "--file", "-f", "--blob"}


CONFIG_VALUE_OPTIONS = ("--file", "-f", "--blob", "--type", "-t", "--default", "--comment")


def _config_positionals(args):
    """The arguments of `git config` that are not options or the values of options that take one (`--file x`, `-f x`; the
    joined `--file=x` starts with a dash and is skipped as an option)."""
    out, skip = [], False
    for a in args:
        if skip:
            skip = False
        elif a in CONFIG_VALUE_OPTIONS:
            skip = True
        elif not a.startswith("-"):
            out.append(a)
    return out


def config_write(args, key_pred):
    """True when `git config <args>` writes a key `key_pred` accepts (a lower-cased name; `--edit` counts for every predicate);
    lookups (`--get`, `get`, `--list`, one bare key) are False."""
    if not args:
        return False
    keys = _config_positionals(args)
    sub = None
    if keys and keys[0] in ("get", "list", "set", "unset", "rename-section", "remove-section", "edit"):
        sub, keys = keys[0], keys[1:]
    names_key = any(key_pred(k.lower()) for k in keys[:1])
    if not names_key and not (sub == "edit" or "--edit" in args or "-e" in args):
        return False
    if sub in ("get", "list"):
        return False
    if sub in ("set", "unset", "rename-section", "remove-section", "edit"):
        return True
    if any(a in CONFIG_WRITE_FLAGS for a in args):
        return True
    if any(a in CONFIG_LOOKUP_FLAGS for a in args):
        return False
    # `git config <key> <value>` writes; `git config <key>` reads. The type options (--type, --bool, ...) only canonicalise.
    return len(keys) >= 2


def paddock_config_write(args):
    """True when `git config <args>` writes a `paddock.*` key or the `paddock` section (the shared common config that names the
    machine's dev folders, docs/dev-setup.md)."""
    return config_write(args, lambda k: k == "paddock" or k.startswith("paddock."))


def hooks_path_write(args):
    """True when `git config <args>` writes or unsets `core.hooksPath`, which switches every hook off like `--no-verify`."""
    return config_write(args, lambda k: k == HOOKS_PATH)


def closes_with_exit(cmds, cmd):
    """True when what follows `cd X ||` stops the script: `exit`/`return`, alone or inside a { ...; } group."""
    nxt = cmds[cmd.idx + 1] if cmd.idx + 1 < len(cmds) else None
    if nxt is None:
        return False
    depth = nxt.opens
    if nxt.argv[:1] in (["exit"], ["return"]):
        return True
    if depth == 0:
        return False
    for c in cmds[nxt.idx + 1:]:
        if c.argv[:1] in (["exit"], ["return"]):
            return True
        depth += c.opens
        if c.words[:1] == ["}"]:
            depth -= 1
            if depth <= 0:
                return False
    return False


HOOKS_PATH = "core.hookspath"
# The commands whose hooks run (or whose result is a commit): a config override on one of them can point git at other hooks.
OVERRIDE_SUBS = ("commit", "push", "merge", "cherry-pick", "rebase", "am", "revert")
# git options and environment variables that change which config (and so which hooks, identity or repository) a command reads.
CONFIG_OPTIONS = ("-c", "--config-env", "--exec-path", "--git-dir")
CONFIG_ENV = {"GIT_CONFIG_GLOBAL", "GIT_CONFIG_SYSTEM", "GIT_CONFIG_NOSYSTEM", "GIT_CONFIG_COUNT", "GIT_CONFIG_PARAMETERS",
              "HOME", "XDG_CONFIG_HOME", "GIT_DIR", "GIT_EXEC_PATH"}
CONFIG_ENV_PREFIXES = ("GIT_CONFIG_KEY_", "GIT_CONFIG_VALUE_")


def config_override(c):
    """What overrides git's configuration for this command (any `-c`, `--config-env`, `--exec-path`, `--git-dir`, or an
    environment variable of CONFIG_ENV), or None. An outcome rule, not a list of spellings: every override of the config of a
    commit, push, merge, cherry-pick, rebase, am or revert can switch the hooks off."""
    a = c.argv
    k = 1
    while k < len(a) and a[k].startswith("-") and a[k] != "--":
        if a[k] == "-c" or a[k].split("=", 1)[0] in CONFIG_OPTIONS:
            return "git %s" % " ".join(a[k:k + 2] if a[k] in shellscan._GIT_OPT_ARG else a[k:k + 1])
        k += 2 if a[k] in shellscan._GIT_OPT_ARG else 1
    for e in c.env:
        name = e.partition("=")[0]
        if name in CONFIG_ENV or name.startswith(CONFIG_ENV_PREFIXES):
            return "the environment variable %s" % name
    return None


def decide(data):
    if data.get("tool_name") != "Bash":
        return None
    text = (data.get("tool_input") or {}).get("command") or ""
    is_agent = bool(data.get("agent_id"))
    cmds = shellscan.scan(text, data.get("cwd"))
    pending_commit, chain_has_commit = False, False   # a commit whose failure would not stop a later push
    for c in cmds:
        g0 = shellscan.git_invocation(c)
        if g0 and not c.cond:
            if g0[1] == "push" and pending_commit and not chain_has_commit:
                return ("Blocked: `git push` follows a `git commit` that is not joined to it by `&&` (the commit-msg hook can "
                        "reject the commit and the push still runs; that happened twice on 2026-11-12). Next step: write "
                        "`git commit ... && git push`, or `git commit ... || exit 1; git push`.")
            if g0[1] == "commit" and not c.set_e:
                pending_commit, chain_has_commit = True, True
                if c.term == "||" and closes_with_exit(cmds, c):
                    pending_commit = False
        if c.term in (";", "\n", "&"):
            chain_has_commit = False
        if c.is_cd and not c.cond and not c.nested:
            tgt = c.cd_target
            if c.term in (";", "\n") and not c.set_e and shellscan.next_cmd(cmds, c) is not None:
                return ("Blocked: `cd %s` is followed by `%s` and more commands (unguarded cd): if the cd fails, the rest "
                        "runs in the wrong folder (on 2026-11-10 that merged into the main checkout's main). Next step: "
                        "write `cd %s && ...` (or `cd %s || exit 1; ...`), or work in your own worktree with absolute "
                        "paths and `git -C`." % (tgt, "newline" if c.term == "\n" else ";", tgt, tgt))
            if c.term == "||" and not c.set_e and not closes_with_exit(cmds, c):
                return ("Blocked: `cd %s || ...` does not stop when the cd fails (unguarded cd). Next step: `cd %s && ...`,"
                        " or `cd %s || exit 1; ...`." % (tgt, tgt, tgt))
        g = shellscan.git_invocation(c)
        if not g:
            continue
        eff, sub, args = g
        if is_agent:
            ov = config_override(c) if sub in OVERRIDE_SUBS else None
            if ov:
                return ("Blocked (ER-39, hooks are never bypassed): `git %s` with a config override (%s). Any override of git's "
                        "configuration can point git at other hooks (core.hooksPath, include.path, another HOME or "
                        "GIT_CONFIG_GLOBAL) and skips lefthook like --no-verify. Next step: run it without the override; if a "
                        "hook fails, fix the hook (or cherry-pick its fix) or stop and report." % (sub, ov))
        if is_agent and sub in OVERRIDE_SUBS:
            bypass = [e for e in c.env if e.split("=", 1)[0] in ("LEFTHOOK_EXCLUDE",) or e in ("LEFTHOOK=0", "LEFTHOOK=false")]
            if bypass or (sub in ("commit", "push") and "--no-verify" in args) or (sub == "commit" and short_n(args)):
                return ("Blocked: git hooks are bypassed (%s). Hooks must pass: cherry-pick the hook fix or stop and report "
                        "(no bypass)." % (bypass[0] if bypass else "--no-verify"))
        if is_agent and sub == "config" and hooks_path_write(args) and not paddock_config_write(args):
            return ("Blocked (ER-39, hooks are never bypassed): `git config` writes or unsets core.hooksPath, which points git at "
                    "other hooks and skips lefthook like --no-verify. Next step: leave it; if a hook fails, fix the hook or stop "
                    "and report. Reading it (`git config --get core.hooksPath`) is fine.")
        if is_agent and sub == "config" and paddock_config_write(args):
            return ("Blocked: `git config` writes a `paddock.*` key by a subagent. It lives in the common config every worktree "
                    "shares and moves the dev, VM, lock and disk folders for everyone (docs/dev-setup.md, \"Where things "
                    "live\"). Next step: stop and ask the coordinator; read it with `git config --get` or `./dev places`.")
        if not is_write(sub, args):
            continue
        if c.after_cd_chain:
            return ("Blocked: `git %s` runs after a `cd X && ...` chain ended by `;` or a newline (unguarded cd): if "
                    "the cd failed, it runs in the wrong folder. Next step: keep it in the chain (`cd X && ... && git %s`)"
                    ", or use `git -C <worktree> %s`." % (sub, sub, sub))
        if is_agent and MAIN is None:
            return ("Blocked: `git %s` by a subagent, and the main checkout could not be derived from git (CLAUDE_PROJECT_DIR "
                    "is not in a git checkout), so the ER-2 check cannot run. Next step: run from the repository, or set "
                    "WORKTREE_GUARD_MAIN to the main checkout's path." % sub)
        if is_agent and eff and in_main(eff):
            return ("Blocked: `git %s` in the main checkout (%s) by a subagent. The main checkout stays on `main` for "
                    "the coordinator's fast-forwards (ER-2). Next step: do it in your own worktree (`./dev worktree add` "
                    "and claim it), with `cd <worktree> && git ...` or `git -C <worktree> ...`." % (sub, MAIN))
    return None


def main():
    try:
        data = json.load(sys.stdin)
        reason = decide(data)
    except shellscan.TooBig as e:
        shellscan.warn(NAME, "command too large to scan (%s)" % e)
        return
    except Exception as e:  # never fail closed
        shellscan.warn(NAME, "could not read the input (%s)" % e)
        return
    if reason:
        print(shellscan.deny_json(reason))


if __name__ == "__main__":
    main()

//! Opening a diagnostics report (the zip "Report a problem" and `--export-diagnostics` write) as a
//! diagnostics workspace instead of a plain archive.
//!
//! [`divert`] runs before every open (File ▸ Open, drag and drop, the command line all go through
//! `open_paths`): a zip whose `manifest.json` says `debrief-diagnostics` ([`detect`]) has only its logs
//! (Debrief's, the activity log, each child process's) copied out, within the archive limits of
//! `debrief_core::archive`, into `<data>/diagnostics-reports/<name>-<hash>/logs`, and that folder is opened
//! instead, so each log is a source with its own timeline lane and imports through the usual importers.
//! The JSON files are never imported as events: [`read_view`] reads them (bounded, typed) into the
//! "Diagnostics report" panel's [`DiagnosticsReportView`], and snapshot images are read from the zip on
//! demand. Nothing in the zip is ever executed. A malformed, oversized or newer manifest opens the zip as
//! a plain archive and leaves a notice for the window.
//!
//! Commands: `diagnostics_report`, `diagnostics_report_image`.

use super::manifest::{self, FileKind, Manifest, ManifestError, ManifestFile, MANIFEST_NAME};
use crate::activity::Breadcrumb;
use crate::windows::CurrentWindow;
use crate::{err, CmdResult};
use debrief_ipc::child_log::ProcessSummary;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashMap;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use tauri::{AppHandle, Manager, Runtime};

/// Folder (under Debrief's data folder) of the logs copied out of opened reports.
pub const REPORTS_DIR: &str = "diagnostics-reports";
/// Copied-out reports kept (the oldest are removed).
pub const KEEP_EXTRACTED: usize = 8;
/// Largest JSON file of a report read for the panel.
pub const MAX_JSON: u64 = 4 << 20;
/// Largest text file (steps, description) read.
pub const MAX_TEXT: u64 = 1 << 20;
/// Most snapshots, processes, steps and breadcrumbs shown.
pub const MAX_SNAPSHOTS: usize = 50;
pub const MAX_PROCESSES: usize = 512;
pub const MAX_STEPS: usize = 1000;
pub const MAX_BREADCRUMBS: usize = 1000;
/// Longest snapshot message or reason kept (characters).
const MAX_FIELD: usize = 4000;
/// The file next to the copied-out logs that names the zip they came from.
const SOURCE_FILE: &str = "source.json";

use crate::sync::lock;

/// The manifest as the panel shows it.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct ManifestView {
    pub schema_version: u32,
    pub debrief_version: String,
    pub commit: String,
    pub created_at: String,
    pub files: Vec<ManifestFile>,
}

/// One error snapshot of a report (its image comes from `diagnostics_report_image`).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct ReportSnapshot {
    pub id: String,
    #[serde(default)]
    pub created_at: String,
    #[serde(default)]
    pub reason: String,
    #[serde(default)]
    pub message: String,
    #[serde(default)]
    pub view: Option<String>,
    #[serde(default)]
    pub mime: String,
    #[serde(default)]
    pub bytes: u64,
    /// Whether the zip holds this snapshot's screenshot (a report leaves them out unless the user ticked the box); set from the
    /// manifest when the report is read.
    #[serde(default, skip_deserializing)]
    pub has_image: bool,
    #[serde(default)]
    pub steps: Vec<String>,
    #[serde(default)]
    pub breadcrumbs: Vec<Breadcrumb>,
}

/// An opened report, read-only (see `app/src/app/diagnostics/diagnostics-report.types.ts`).
#[derive(Debug, Clone, Serialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct DiagnosticsReportView {
    pub name: String,
    pub manifest: ManifestView,
    pub system_info: Value,
    pub processes: Vec<ProcessSummary>,
    pub steps: Vec<String>,
    pub breadcrumbs: Vec<Breadcrumb>,
    pub snapshots: Vec<ReportSnapshot>,
    pub session_recovery: Option<Value>,
    pub description: Option<String>,
    pub unreadable: Vec<String>,
}

/// What `diagnostics_report` returns.
#[derive(Debug, Clone, Serialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct DiagnosticsReportState {
    pub report: Option<DiagnosticsReportView>,
    pub notice: Option<String>,
}

/// What a zip turned out to be.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Detected {
    /// Not a diagnostics report (or not a zip): opened as usual.
    Plain,
    Report(Manifest),
    /// It looks like one but cannot be read as one: opened as a plain archive, with this notice.
    Fallback(String),
}

fn display_name(path: &Path) -> String {
    path.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default()
}

fn fallback_notice(path: &Path, why: &str) -> String {
    format!("{} was opened as a plain archive: {why}.", display_name(path))
}

/// One entry of the zip, at most `cap` bytes (by its declared and its actual size).
fn read_entry<R: Read + std::io::Seek>(zip: &mut zip::ZipArchive<R>, name: &str, cap: u64) -> Result<Vec<u8>, String> {
    let entry = zip.by_name(name).map_err(|_| format!("{name} is missing"))?;
    if entry.size() > cap {
        return Err(format!("{name} is larger than {} KB", cap / 1024));
    }
    let mut out = Vec::new();
    entry
        .take(cap + 1)
        .read_to_end(&mut out)
        .map_err(|e| format!("{name} cannot be read ({e})"))?;
    if out.len() as u64 > cap {
        return Err(format!("{name} is larger than {} KB", cap / 1024));
    }
    Ok(out)
}

fn open_zip(path: &Path) -> Result<zip::ZipArchive<std::fs::File>, String> {
    let f = std::fs::File::open(path).map_err(|e| format!("cannot be read ({})", e.kind()))?;
    zip::ZipArchive::new(f).map_err(|_| "is not a valid zip archive".to_string())
}

/// Whether `path` is a diagnostics report. Reads the zip's directory and its manifest only.
pub fn detect(path: &Path) -> Detected {
    let mut magic = [0u8; 4];
    let is_zip = std::fs::File::open(path).and_then(|mut f| f.read_exact(&mut magic)).is_ok() && debrief_core::archive::is_zip(&magic);
    if !is_zip {
        return Detected::Plain;
    }
    let Ok(mut zip) = open_zip(path) else { return Detected::Plain };
    let bytes = match read_entry(&mut zip, MANIFEST_NAME, manifest::MAX_MANIFEST_BYTES) {
        Ok(b) => b,
        Err(_) if zip.index_for_name(MANIFEST_NAME).is_none() => return Detected::Plain,
        Err(_) => return Detected::Fallback(fallback_notice(path, &ManifestError::TooLarge.to_string())),
    };
    match manifest::parse(&bytes) {
        Ok(m) => Detected::Report(m),
        Err(ManifestError::OtherKind) => Detected::Plain,
        // A manifest of some other program that is not even JSON.
        Err(ManifestError::Malformed(_)) if !String::from_utf8_lossy(&bytes).contains(manifest::MANIFEST_KIND) => Detected::Plain,
        Err(e) => Detected::Fallback(fallback_notice(path, &e.to_string())),
    }
}

/// `<stem>-<hash>`: one folder per zip (its canonical path, size and time).
fn folder_key(path: &Path) -> String {
    use std::hash::{Hash, Hasher};
    let canon = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
    let meta = std::fs::metadata(&canon).ok();
    let mut h = std::collections::hash_map::DefaultHasher::new();
    canon.hash(&mut h);
    meta.as_ref().map(|m| m.len()).hash(&mut h);
    meta.and_then(|m| m.modified().ok())
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs())
        .hash(&mut h);
    let stem = path.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
    format!("{}-{:016x}", debrief_ipc::child_log::log_name(&stem), h.finish())
}

/// Removes all but the newest [`KEEP_EXTRACTED`] copied-out reports (never `keep`). Never fails.
fn prune(reports_dir: &Path, keep: &Path) {
    let Ok(rd) = std::fs::read_dir(reports_dir) else { return };
    let mut dirs: Vec<(std::time::SystemTime, PathBuf)> = rd
        .flatten()
        .filter(|e| e.file_type().is_ok_and(|t| t.is_dir()) && e.path() != keep)
        .filter_map(|e| Some((e.metadata().ok()?.modified().ok()?, e.path())))
        .collect();
    dirs.sort_by_key(|d| std::cmp::Reverse(d.0));
    for (_, d) in dirs.into_iter().skip(KEEP_EXTRACTED.saturating_sub(1)) {
        let _ = std::fs::remove_dir_all(d);
    }
}

/// Copies the report's logs out of the zip into `reports_dir/<key>/logs` and returns that folder.
pub fn extract_logs(zip_path: &Path, m: &Manifest, reports_dir: &Path) -> Result<PathBuf, String> {
    let root = reports_dir.join(folder_key(zip_path));
    let _ = std::fs::remove_dir_all(&root);
    let logs = root.join("logs");
    std::fs::create_dir_all(&logs).map_err(|e| format!("cannot prepare {} ({e})", logs.display()))?;
    let mut zip = open_zip(zip_path)?;
    let mut total = 0u64;
    let mut copied = 0usize;
    for f in m.files.iter().filter(|f| f.kind.is_log() && f.name.starts_with("logs/")) {
        let data = read_entry(&mut zip, &f.name, debrief_core::archive::MAX_ENTRY_BYTES)?;
        total += data.len() as u64;
        if total > debrief_core::archive::MAX_ARCHIVE_BYTES {
            return Err(format!(
                "its logs expand to more than {} MiB",
                debrief_core::archive::MAX_ARCHIVE_BYTES >> 20
            ));
        }
        if data.is_empty() {
            continue;
        }
        // The name is a validated relative path (see `manifest::safe_name`).
        let target = root.join(&f.name);
        if let Some(parent) = target.parent() {
            std::fs::create_dir_all(parent).map_err(|e| format!("cannot prepare {} ({e})", parent.display()))?;
        }
        std::fs::write(&target, &data).map_err(|e| format!("cannot write {} ({e})", target.display()))?;
        copied += 1;
    }
    if copied == 0 {
        let _ = std::fs::remove_dir_all(&root);
        return Err("it contains no logs".into());
    }
    let source = serde_json::json!({ "zip": zip_path.canonicalize().unwrap_or_else(|_| zip_path.to_path_buf()) });
    let _ = std::fs::write(root.join(SOURCE_FILE), source.to_string());
    prune(reports_dir, &root);
    Ok(logs)
}

fn cut(s: String, max: usize) -> String {
    if s.chars().count() <= max {
        s
    } else {
        let mut t: String = s.chars().take(max).collect();
        t.push('…');
        t
    }
}

/// Reads the panel's data from the zip: every file is optional, bounded and parsed into its type; what
/// cannot be read is listed in `unreadable`.
pub fn read_view(zip_path: &Path, m: &Manifest) -> DiagnosticsReportView {
    let mut unreadable = Vec::new();
    let mut zip = open_zip(zip_path).map_err(|e| unreadable.push(format!("the zip {e}"))).ok();
    let mut text = |kind: FileKind, cap: u64, unreadable: &mut Vec<String>| -> Option<String> {
        let f = m.of_kind(kind).next()?;
        let z = zip.as_mut()?;
        match read_entry(z, &f.name, cap) {
            Ok(b) => Some(String::from_utf8_lossy(&b).into_owned()),
            Err(e) => {
                unreadable.push(e);
                None
            }
        }
    };
    fn json<T: serde::de::DeserializeOwned>(name: &str, t: Option<String>, unreadable: &mut Vec<String>) -> Option<T> {
        let t = t?;
        match serde_json::from_str(&t) {
            Ok(v) => Some(v),
            Err(_) => {
                unreadable.push(format!("{name} is not valid"));
                None
            }
        }
    }
    let system_info = json::<Value>(
        "system-info.json",
        text(FileKind::SystemInfo, MAX_JSON, &mut unreadable),
        &mut unreadable,
    )
    .map(|v| super::without_secrets(&v))
    .unwrap_or(Value::Null);
    let mut processes: Vec<ProcessSummary> = json(
        "processes.json",
        text(FileKind::Processes, MAX_JSON, &mut unreadable),
        &mut unreadable,
    )
    .unwrap_or_default();
    processes.truncate(MAX_PROCESSES);
    let mut breadcrumbs: Vec<Breadcrumb> = json(
        "breadcrumbs.json",
        text(FileKind::Breadcrumbs, MAX_JSON, &mut unreadable),
        &mut unreadable,
    )
    .unwrap_or_default();
    breadcrumbs.truncate(MAX_BREADCRUMBS);
    let steps: Vec<String> = text(FileKind::Steps, MAX_TEXT, &mut unreadable)
        .map(|t| {
            t.lines()
                .filter(|l| !l.trim().is_empty())
                .take(MAX_STEPS)
                .map(|l| cut(l.to_string(), MAX_FIELD))
                .collect()
        })
        .unwrap_or_default();
    let session_recovery = json::<Value>(
        "session-recovery.json",
        text(FileKind::SessionRecovery, MAX_JSON, &mut unreadable),
        &mut unreadable,
    );
    let description = text(FileKind::Description, MAX_TEXT, &mut unreadable)
        .map(|d| cut(d.trim().to_string(), super::MAX_DESCRIPTION))
        .filter(|d| !d.is_empty());
    let mut snapshots = Vec::new();
    for f in m.of_kind(FileKind::SnapshotDetails).take(MAX_SNAPSHOTS) {
        let Some(z) = zip.as_mut() else { break };
        let parsed = read_entry(z, &f.name, MAX_JSON)
            .and_then(|b| serde_json::from_slice::<ReportSnapshot>(&b).map_err(|_| format!("{} is not valid", f.name)));
        match parsed {
            Ok(mut s) if crate::snapshots::is_valid_id(&s.id) => {
                s.reason = cut(s.reason, MAX_FIELD);
                s.message = cut(s.message, MAX_FIELD);
                s.view = s.view.map(|v| cut(v, MAX_FIELD));
                s.steps.truncate(MAX_STEPS);
                s.breadcrumbs.truncate(MAX_BREADCRUMBS);
                s.has_image = snapshot_image(m, &s.id).is_some();
                snapshots.push(s);
            }
            Ok(_) => unreadable.push(format!("{} has an invalid id", f.name)),
            Err(e) => unreadable.push(e),
        }
    }
    DiagnosticsReportView {
        name: display_name(zip_path),
        manifest: ManifestView {
            schema_version: m.schema_version,
            debrief_version: m.debrief_version.clone(),
            commit: m.commit.clone(),
            created_at: m.created_at.clone(),
            files: m.files.iter().filter(|f| f.kind != FileKind::Other).cloned().collect(),
        },
        system_info,
        processes,
        steps,
        breadcrumbs,
        snapshots,
        session_recovery,
        description,
        unreadable,
    }
}

/// The manifest entry of a snapshot's screenshot, when the zip holds one.
fn snapshot_image<'a>(m: &'a Manifest, id: &str) -> Option<&'a ManifestFile> {
    m.of_kind(FileKind::Snapshot)
        .find(|f| f.name == format!("snapshots/{id}.png") || f.name == format!("snapshots/{id}.jpg"))
}

/// One snapshot image of the report as a `data:` URL (PNG or JPEG only, at most the snapshot size limit).
pub fn read_image(zip_path: &Path, m: &Manifest, id: &str) -> Result<String, String> {
    if !crate::snapshots::is_valid_id(id) {
        return Err("invalid snapshot id".into());
    }
    let f = snapshot_image(m, id).ok_or("this report has no screenshot for that snapshot")?;
    let bytes = read_entry(&mut open_zip(zip_path)?, &f.name, crate::snapshots::MAX_IMAGE_BYTES as u64)?;
    let mime = if bytes.starts_with(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]) {
        "image/png"
    } else if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
        "image/jpeg"
    } else {
        return Err("the snapshot is not a PNG or JPEG image".into());
    };
    Ok(format!(
        "data:{mime};base64,{}",
        base64::Engine::encode(&base64::engine::general_purpose::STANDARD, bytes)
    ))
}

/// A report opened in a window.
#[derive(Debug, Clone)]
pub struct Opened {
    pub zip: PathBuf,
    pub manifest: Manifest,
    pub view: DiagnosticsReportView,
    /// The folder of its copied-out logs (opened as the workspace's sources).
    pub logs: PathBuf,
}

/// What [`divert_in`] did with a list of paths.
#[derive(Debug, Default)]
pub struct Diverted {
    pub paths: Vec<String>,
    /// The last report among them.
    pub opened: Option<Opened>,
    pub notices: Vec<String>,
}

/// Replaces each diagnostics report among `paths` by the folder of its logs (see the module docs).
pub fn divert_in(reports_dir: &Path, paths: Vec<String>) -> Diverted {
    let mut out = Diverted::default();
    for p in paths {
        let path = PathBuf::from(&p);
        if !path.is_file() {
            out.paths.push(p);
            continue;
        }
        match detect(&path) {
            Detected::Plain => out.paths.push(p),
            Detected::Fallback(notice) => {
                out.notices.push(notice);
                out.paths.push(p);
            }
            Detected::Report(m) => match extract_logs(&path, &m, reports_dir) {
                Ok(logs) => {
                    out.paths.push(logs.to_string_lossy().into_owned());
                    out.opened = Some(Opened {
                        view: read_view(&path, &m),
                        zip: path,
                        manifest: m,
                        logs,
                    });
                }
                Err(e) => {
                    out.notices.push(fallback_notice(&path, &e));
                    out.paths.push(p);
                }
            },
        }
    }
    out
}

/// The reports opened per window, and notices not yet shown. Managed on first use.
#[derive(Default)]
pub struct OpenedReports {
    opened: Mutex<HashMap<String, Arc<Opened>>>,
    notices: Mutex<HashMap<String, String>>,
}

fn reports<R: Runtime>(app: &AppHandle<R>) -> tauri::State<'_, OpenedReports> {
    if app.try_state::<OpenedReports>().is_none() {
        app.manage(OpenedReports::default());
    }
    app.state::<OpenedReports>()
}

/// A window closed: the report it opened and its pending notice go with it.
pub fn forget_window<R: Runtime>(app: &AppHandle<R>, window: &str) {
    let state = reports(app);
    lock(&state.opened).remove(window);
    lock(&state.notices).remove(window);
}

/// Called by `open_paths` before opening: diagnostics reports become the folders of their logs, and the
/// window remembers the report for its panel. Never fails: anything unexpected opens the paths as given.
pub async fn divert<R: Runtime>(app: &AppHandle<R>, window: &str, paths: Vec<String>) -> Vec<String> {
    let Ok(data) = crate::app_dirs::data(app) else { return paths };
    let given = paths.clone();
    let done = tauri::async_runtime::spawn_blocking(move || divert_in(&data.join(REPORTS_DIR), paths)).await;
    let Ok(done) = done else { return given };
    let state = reports(app);
    if let Some(n) = done.notices.last() {
        log::warn!(Notices = done.notices.len() as u64; "A zip that looked like a diagnostics report was opened as a plain archive");
        lock(&state.notices).insert(window.to_string(), n.clone());
    }
    if let Some(o) = done.opened {
        // Counts only: names stay out of the log.
        log::info!(Files = o.manifest.files.len() as u64, Processes = o.view.processes.len() as u64; "Diagnostics report opened");
        lock(&state.opened).insert(window.to_string(), Arc::new(o));
    }
    done.paths
}

/// The copied-out report a workspace source belongs to: `<reports>/<key>/logs/...` → `<reports>/<key>`.
fn report_root_of(source: &Path) -> Option<PathBuf> {
    let mut cur = source.parent();
    while let Some(dir) = cur {
        if dir.file_name().is_some_and(|n| n == "logs")
            && dir
                .parent()
                .and_then(|p| p.parent())
                .and_then(|p| p.file_name())
                .is_some_and(|n| n == REPORTS_DIR)
        {
            return dir.parent().map(Path::to_path_buf);
        }
        cur = dir.parent();
    }
    None
}

/// The report behind a restored workspace (after a restart): found from its sources' folder, read again
/// from the zip it came from when that still exists.
fn recover(sources: &[String]) -> Option<Opened> {
    let root = sources.iter().find_map(|s| report_root_of(Path::new(s)))?;
    let meta = std::fs::metadata(root.join(SOURCE_FILE)).ok()?;
    if meta.len() > 64 * 1024 {
        return None;
    }
    let v: Value = serde_json::from_str(&std::fs::read_to_string(root.join(SOURCE_FILE)).ok()?).ok()?;
    let zip = PathBuf::from(v.get("zip")?.as_str()?);
    match detect(&zip) {
        Detected::Report(m) => Some(Opened {
            view: read_view(&zip, &m),
            zip,
            manifest: m,
            logs: root.join("logs"),
        }),
        _ => None,
    }
}

/// The calling window's report, while its workspace still shows that report's logs, and a notice left by
/// the last open (shown once).
#[tauri::command]
pub async fn diagnostics_report<R: Runtime>(app: AppHandle<R>, state: CurrentWindow) -> CmdResult<DiagnosticsReportState> {
    let sources: Vec<String> = crate::workspace_commands::summary_of(&state)
        .await?
        .sources
        .into_iter()
        .map(|s| s.path)
        .collect();
    let label = state.label().to_string();
    let reports = reports(&app);
    let notice = lock(&reports.notices).remove(&label);
    let current = lock(&reports.opened).get(&label).cloned();
    let current = match current {
        Some(o) if sources.iter().any(|s| Path::new(s).starts_with(&o.logs)) => Some(o),
        _ => {
            let found = tauri::async_runtime::spawn_blocking(move || recover(&sources)).await.map_err(err)?;
            let mut opened = lock(&reports.opened);
            match found {
                Some(o) => {
                    let o = Arc::new(o);
                    opened.insert(label.clone(), o.clone());
                    Some(o)
                }
                None => {
                    opened.remove(&label);
                    None
                }
            }
        }
    };
    Ok(DiagnosticsReportState {
        report: current.map(|o| o.view.clone()),
        notice,
    })
}

/// One snapshot image of the calling window's report, as a `data:` URL.
#[tauri::command]
pub async fn diagnostics_report_image<R: Runtime>(app: AppHandle<R>, state: CurrentWindow, id: String) -> CmdResult<String> {
    let opened = lock(&reports(&app).opened)
        .get(state.label())
        .cloned()
        .ok_or("no diagnostics report is open in this window")?;
    crate::error::lift(
        tauri::async_runtime::spawn_blocking(move || read_image(&opened.zip, &opened.manifest, &id))
            .await
            .map_err(err)?,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::activity::report::tests::{inputs_in, temp};
    use std::io::Write;

    fn report_zip(d: &Path) -> PathBuf {
        let mut inputs = inputs_in(d);
        // The tests open the snapshot's image, which a report holds only when asked for.
        inputs.include_screenshots = true;
        let out = d.join("debrief-diagnostics-test.zip");
        crate::activity::report::write(&inputs, "It froze", &out).unwrap();
        out
    }

    fn zip_with(d: &Path, name: &str, files: &[(&str, &[u8])]) -> PathBuf {
        let p = d.join(name);
        let mut z = zip::ZipWriter::new(std::fs::File::create(&p).unwrap());
        for (n, data) in files {
            z.start_file(*n, zip::write::SimpleFileOptions::default()).unwrap();
            z.write_all(data).unwrap();
        }
        z.finish().unwrap();
        p
    }

    #[test]
    fn a_written_report_opens_as_a_diagnostics_workspace() {
        let d = temp("open-roundtrip");
        let zip = report_zip(&d);
        let Detected::Report(m) = detect(&zip) else {
            panic!("not detected")
        };
        let done = divert_in(
            &d.join(REPORTS_DIR),
            vec![
                zip.to_string_lossy().into_owned(),
                d.join("other.log").to_string_lossy().into_owned(),
            ],
        );
        assert!(done.notices.is_empty(), "{:?}", done.notices);
        let o = done.opened.unwrap();
        assert_eq!(done.paths[0], o.logs.to_string_lossy());
        assert!(done.paths[1].ends_with("other.log"));
        // Only logs were copied out.
        assert!(o.logs.join("debrief.log").is_file() && o.logs.join("activity.log").is_file());
        assert!(!o.logs.join("../system-info.json").exists());
        assert_eq!(report_root_of(&o.logs.join("debrief.log")).unwrap(), o.logs.parent().unwrap());
        // The panel's data.
        let v = &o.view;
        assert_eq!(v.name, "debrief-diagnostics-test.zip");
        assert_eq!(v.description.as_deref(), Some("It froze"));
        assert_eq!(v.steps, ["1. Opened files from the menu", "2. Applied query from the menu"]);
        assert_eq!(v.breadcrumbs.len(), 2);
        assert_eq!(v.snapshots.len(), 1);
        assert!(v.snapshots[0].has_image, "the zip holds the screenshot");
        assert_eq!(v.system_info["plugins"][0]["id"], "net.decryptology.web");
        assert!(v.unreadable.is_empty(), "{:?}", v.unreadable);
        assert_eq!(v.manifest.files.len(), m.files.len());
        let img = read_image(&zip, &m, &v.snapshots[0].id).unwrap();
        assert!(img.starts_with("data:image/png;base64,"));
        assert!(read_image(&zip, &m, "../x").is_err());
        assert!(read_image(&zip, &m, "20261017T083000123-1a2b3c4d").is_err());
        // After a restart the report is found again from the workspace's sources.
        let again = recover(&[o.logs.join("debrief.log").to_string_lossy().into_owned()]).unwrap();
        assert_eq!(again.view, o.view);
        assert!(recover(&[d.join("x.log").to_string_lossy().into_owned()]).is_none());
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn a_report_saved_without_screenshots_says_so_instead_of_failing_to_load_one() {
        let d = temp("open-no-image");
        let inputs = inputs_in(&d);
        assert!(!inputs.include_screenshots, "off by default");
        let zip = d.join("debrief-diagnostics-no-image.zip");
        crate::activity::report::write(&inputs, "", &zip).unwrap();
        let Detected::Report(m) = detect(&zip) else {
            panic!("not detected")
        };
        let v = read_view(&zip, &m);
        assert_eq!(v.snapshots.len(), 1);
        assert!(!v.snapshots[0].has_image);
        assert!(read_image(&zip, &m, &v.snapshots[0].id).unwrap_err().contains("no screenshot"));
        let json = serde_json::to_value(&v.snapshots[0]).unwrap();
        assert_eq!(json["hasImage"], false);
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn other_zips_and_bad_manifests_fall_back_to_a_plain_archive() {
        let d = temp("open-fallback");
        let good = serde_json::to_vec(&Manifest::new("1".into(), "c".into(), "t".into(), vec![])).unwrap();
        let newer = String::from_utf8(good.clone())
            .unwrap()
            .replace("\"schemaVersion\":1", "\"schemaVersion\":99");
        let plain = zip_with(&d, "plain.zip", &[("a.log", b"x")]);
        let bundle = zip_with(&d, "bundle.zip", &[("manifest.json", b"{\"kind\":\"debrief-bundle\"}")]);
        let alien = zip_with(&d, "alien.zip", &[("manifest.json", b"<xml/>")]);
        let broken = zip_with(&d, "broken.zip", &[("manifest.json", b"{\"kind\":\"debrief-diagnostics\",")]);
        let future = zip_with(&d, "future.zip", &[("manifest.json", newer.as_bytes())]);
        let huge_manifest = vec![b' '; manifest::MAX_MANIFEST_BYTES as usize + 10];
        let huge = zip_with(&d, "huge.zip", &[("manifest.json", &huge_manifest)]);
        let empty = zip_with(&d, "empty.zip", &[("manifest.json", &good)]);
        std::fs::write(d.join("text.zip"), "not a zip").unwrap();
        assert_eq!(detect(&plain), Detected::Plain);
        assert_eq!(detect(&bundle), Detected::Plain);
        assert_eq!(detect(&alien), Detected::Plain);
        assert_eq!(detect(&d.join("text.zip")), Detected::Plain);
        assert_eq!(detect(&d.join("missing.zip")), Detected::Plain);
        for (zip, want) in [(&broken, "not valid"), (&future, "newer Debrief"), (&huge, "larger than")] {
            match detect(zip) {
                Detected::Fallback(n) => assert!(n.contains(want) && n.contains("plain archive"), "{n}"),
                other => panic!("{other:?}"),
            }
        }
        // A report without logs, or a newer one: opened as given, with a notice.
        let done = divert_in(
            &d.join(REPORTS_DIR),
            vec![empty.to_string_lossy().into_owned(), future.to_string_lossy().into_owned()],
        );
        assert!(done.opened.is_none());
        assert_eq!(done.paths.len(), 2);
        assert_eq!(done.notices.len(), 2);
        assert!(done.notices[0].contains("no logs"), "{:?}", done.notices);
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn oversized_and_malformed_files_are_listed_not_fatal() {
        let d = temp("open-bad-files");
        let files = vec![
            ManifestFile {
                name: "logs/debrief.log".into(),
                kind: FileKind::Log,
                bytes: 3,
            },
            ManifestFile {
                name: "processes.json".into(),
                kind: FileKind::Processes,
                bytes: 1,
            },
            ManifestFile {
                name: "system-info.json".into(),
                kind: FileKind::SystemInfo,
                bytes: 1,
            },
            ManifestFile {
                name: "snapshots/bad.json".into(),
                kind: FileKind::SnapshotDetails,
                bytes: 1,
            },
            ManifestFile {
                name: "breadcrumbs.json".into(),
                kind: FileKind::Breadcrumbs,
                bytes: 1,
            },
        ];
        let m = serde_json::to_vec(&Manifest::new("1".into(), "c".into(), "t".into(), files)).unwrap();
        let big = vec![b'['; MAX_JSON as usize + 1];
        let zip = zip_with(
            &d,
            "r.zip",
            &[
                ("manifest.json", &m),
                ("logs/debrief.log", b"{}\n"),
                ("processes.json", b"not json"),
                ("system-info.json", &big),
                ("snapshots/bad.json", b"{\"id\":\"../../x\"}"),
            ],
        );
        let Detected::Report(m) = detect(&zip) else { panic!() };
        let v = read_view(&zip, &m);
        assert!(v.processes.is_empty() && v.system_info.is_null() && v.snapshots.is_empty());
        let all = v.unreadable.join(" | ");
        assert!(all.contains("processes.json is not valid"), "{all}");
        assert!(all.contains("system-info.json is larger than"), "{all}");
        assert!(all.contains("invalid id"), "{all}");
        assert!(all.contains("breadcrumbs.json is missing"), "{all}");
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn copied_out_reports_are_pruned() {
        let d = temp("open-prune");
        let reports = d.join(REPORTS_DIR);
        for i in 0..(KEEP_EXTRACTED + 3) {
            std::fs::create_dir_all(reports.join(format!("old-{i}"))).unwrap();
        }
        let zip = report_zip(&d);
        let Detected::Report(m) = detect(&zip) else { panic!() };
        let logs = extract_logs(&zip, &m, &reports).unwrap();
        let left = std::fs::read_dir(&reports).unwrap().count();
        assert_eq!(left, KEEP_EXTRACTED);
        assert!(logs.is_dir());
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn commands_serve_the_windows_report() {
        let d = temp("open-cmd");
        let zip = report_zip(&d);
        let app = crate::test_support::test_app(None);
        let handle = app.handle().clone();
        let paths = tauri::async_runtime::block_on(divert(&handle, crate::windows::MAIN, vec![zip.to_string_lossy().into_owned()]));
        assert!(paths[0].ends_with("logs"), "{paths:?}");
        let win = crate::test_support::main_window(&app);
        // The workspace does not show the report's logs yet: no report.
        let st = tauri::async_runtime::block_on(diagnostics_report(handle.clone(), win)).unwrap();
        assert!(st.report.is_none());
        let win = crate::test_support::main_window(&app);
        crate::test_support::import(&win, &[PathBuf::from(&paths[0])]);
        let st = tauri::async_runtime::block_on(diagnostics_report(handle.clone(), crate::test_support::main_window(&app))).unwrap();
        let report = st.report.unwrap();
        assert!(report.processes.is_empty());
        let id = report.snapshots[0].id.clone();
        let img =
            tauri::async_runtime::block_on(diagnostics_report_image(handle.clone(), crate::test_support::main_window(&app), id)).unwrap();
        assert!(img.starts_with("data:image/png"));
        // A bad zip leaves a notice, shown once.
        let bad = zip_with(
            &d,
            "bad.zip",
            &[("manifest.json", b"{\"kind\":\"debrief-diagnostics\",\"schemaVersion\":5}")],
        );
        tauri::async_runtime::block_on(divert(&handle, crate::windows::MAIN, vec![bad.to_string_lossy().into_owned()]));
        let st = tauri::async_runtime::block_on(diagnostics_report(handle.clone(), crate::test_support::main_window(&app))).unwrap();
        assert!(st.notice.unwrap().contains("newer Debrief"));
        let st = tauri::async_runtime::block_on(diagnostics_report(handle.clone(), crate::test_support::main_window(&app))).unwrap();
        assert!(st.notice.is_none());
        std::fs::remove_dir_all(d).unwrap();
    }

    /// A closed window's report and notice go with it (they used to stay for the app's lifetime).
    #[test]
    fn a_closed_window_forgets_its_report() {
        let app = crate::test_support::test_app(None);
        let state = reports(app.handle());
        lock(&state.notices).insert("w-4".into(), "n".into());
        lock(&state.notices).insert("main".into(), "kept".into());
        crate::window_scoped::destroyed(app.handle(), "w-4");
        assert!(!lock(&state.notices).contains_key("w-4"));
        assert!(lock(&state.notices).contains_key("main"));
    }
}

//! Commands of the "Collection schedules" and "Runs" views: load, validate
//! and save `debrief-agent.toml` (validation is the agent library's), the
//! editor's schema, the runs in the configured output folder, one run's
//! manifest, and opening a run's folder in a new window. The logic is in
//! plain functions over explicit folders so it is testable without Tauri;
//! the commands only resolve the app's default folders.

use crate::paths::WindowGrants;
use crate::{err, CmdResult};
use debrief_agent::config::{describe, MAX_CONFIG_BYTES};
use debrief_agent::run::{is_run_name, list_runs, read_manifest, RunManifest, RunSummary};
use debrief_agent::schema::{schema, AgentSchema};
use debrief_agent::{AgentConfig, AgentConfigFile, Issue};
use debrief_core::overwrite::check_overwrite;
use serde::Serialize;
use std::path::{Path, PathBuf};
use tauri::{AppHandle, Runtime};

/// File name of the config in the app's config folder (the default).
pub const CONFIG_NAME: &str = "debrief-agent.toml";
/// Most runs returned to the UI.
const MAX_RUNS: usize = 2000;

/// A config document as the editor sees it.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AgentConfigDoc {
    pub path: String,
    /// False: `config` is a starter document, not yet saved.
    pub exists: bool,
    /// `None` when the file exists but cannot be read (see `issues`).
    pub config: Option<AgentConfigFile>,
    pub issues: Vec<Issue>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RunsListing {
    pub output_dir: String,
    pub runs: Vec<RunSummary>,
    /// Runs left out beyond the limit.
    pub truncated: usize,
}

/// The app's folders the commands default to.
pub struct Dirs {
    pub config: PathBuf,
    pub output: PathBuf,
}

fn dirs<R: Runtime>(app: &AppHandle<R>) -> CmdResult<Dirs> {
    let config = crate::app_dirs::config(app).map_err(err)?;
    let output = crate::app_dirs::data(app).map_err(err)?.join("agent").join("runs");
    Ok(Dirs { config, output })
}

/// The config path: the user's choice (a `.toml` file in an existing folder,
/// canonicalised) or the default in the app's config folder.
pub fn resolve_path(path: Option<&str>, dirs: &Dirs) -> CmdResult<PathBuf> {
    let Some(p) = path.map(str::trim).filter(|p| !p.is_empty()) else {
        return Ok(dirs.config.join(CONFIG_NAME));
    };
    crate::error::lift(crate::paths::output_file(p, &["toml"]).map_err(|e| format!("agent config: {e}")))
}

fn base_of(path: &Path) -> &Path {
    path.parent().unwrap_or(Path::new("."))
}

pub fn load_doc(path: Option<&str>, dirs: &Dirs) -> CmdResult<AgentConfigDoc> {
    let path = resolve_path(path, dirs)?;
    let path_s = path.to_string_lossy().into_owned();
    if !path.exists() {
        return Ok(AgentConfigDoc {
            path: path_s,
            exists: false,
            config: Some(AgentConfigFile::starter(&dirs.output.to_string_lossy())),
            issues: Vec::new(),
        });
    }
    Ok(match AgentConfigFile::load(&path) {
        Ok(file) => {
            let issues = file.validate(base_of(&path)).err().unwrap_or_default();
            AgentConfigDoc {
                path: path_s,
                exists: true,
                config: Some(file),
                issues,
            }
        }
        Err(issues) => AgentConfigDoc {
            path: path_s,
            exists: true,
            config: None,
            issues,
        },
    })
}

pub fn validate_doc(path: Option<&str>, config: &AgentConfigFile, dirs: &Dirs) -> CmdResult<Vec<Issue>> {
    let path = resolve_path(path, dirs)?;
    Ok(config.validate(base_of(&path)).err().unwrap_or_default())
}

/// Saves a valid config (atomically). An invalid one is not written: its issues are returned.
/// An existing file is replaced only with `overwrite` (else the `FILE_EXISTS` error the UI
/// confirms); its comments and layout are kept, only changed values are rewritten.
pub fn save_doc(path: Option<&str>, config: &AgentConfigFile, overwrite: bool, dirs: &Dirs) -> CmdResult<Vec<Issue>> {
    let path = resolve_path(path, dirs)?;
    if let Err(issues) = config.validate(base_of(&path)) {
        return Ok(issues);
    }
    check_overwrite(&path, overwrite)?;
    let text = match existing_text(&path)? {
        // A file that is not TOML (any more) is replaced by a fresh document.
        Some(existing) => config.to_toml_over(&existing).or_else(|_| fresh_text(config))?,
        None => fresh_text(config)?,
    };
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(err)?;
    }
    let tmp = path.with_extension("toml.tmp");
    std::fs::write(&tmp, text).map_err(err)?;
    std::fs::rename(&tmp, &path).map_err(err)?;
    Ok(Vec::new())
}

/// A new file: a header and every key.
fn fresh_text(config: &AgentConfigFile) -> CmdResult<String> {
    let header = "# debrief-agent configuration, saved by Debrief. See `debrief-agent print-example` for every key.\n\n";
    Ok(format!("{header}{}", config.to_toml()?))
}

/// The text of the file being replaced; `None` when there is none, or it is too large or not
/// text (it is then replaced by a fresh document).
fn existing_text(path: &Path) -> CmdResult<Option<String>> {
    if !std::fs::metadata(path).is_ok_and(|m| m.len() <= MAX_CONFIG_BYTES) {
        return Ok(None);
    }
    crate::error::lift(
        std::fs::read(path)
            .map(|bytes| String::from_utf8(bytes).ok())
            .map_err(|e| format!("cannot read {}: {e}", path.display())),
    )
}

fn load_valid(path: Option<&str>, dirs: &Dirs) -> CmdResult<AgentConfig> {
    let path = resolve_path(path, dirs)?;
    if !path.exists() {
        return Err(crate::CmdError::from(format!(
            "{} does not exist yet; save the schedules first",
            path.display()
        )));
    }
    crate::error::lift(AgentConfig::load(&path).map_err(|i| describe(&i)))
}

pub fn runs(path: Option<&str>, dirs: &Dirs) -> CmdResult<RunsListing> {
    let cfg = load_valid(path, dirs)?;
    let mut runs = list_runs(&cfg.output_dir);
    let truncated = runs.len().saturating_sub(MAX_RUNS);
    runs.truncate(MAX_RUNS);
    Ok(RunsListing {
        output_dir: cfg.output_dir.to_string_lossy().into_owned(),
        runs,
        truncated,
    })
}

/// A run folder of the configured output, by id (no path tricks).
pub fn run_dir(path: Option<&str>, run_id: &str, dirs: &Dirs) -> CmdResult<PathBuf> {
    if !is_run_name(run_id) || run_id.contains(['/', '\\']) || run_id.contains("..") {
        return Err(crate::CmdError::from(format!("\"{run_id}\" is not a run")));
    }
    let cfg = load_valid(path, dirs)?;
    let dir = cfg.output_dir.join(run_id);
    if !dir.is_dir() {
        return Err(crate::CmdError::from(format!("the run {run_id} no longer exists")));
    }
    Ok(dir)
}

pub fn manifest(path: Option<&str>, run_id: &str, dirs: &Dirs) -> CmdResult<RunManifest> {
    crate::error::lift(read_manifest(&run_dir(path, run_id, dirs)?))
}

/// The user's config path checked against the window's grants (`None`: the default in Debrief's config
/// folder, which needs none). Reading accepts a file chosen to open or to save (a new one).
fn granted(grants: &WindowGrants, path: Option<String>, access: crate::paths::Access) -> CmdResult<Option<String>> {
    let Some(p) = path.filter(|p| !p.trim().is_empty()) else {
        return Ok(None);
    };
    let g = match access {
        crate::paths::Access::Read => grants.read_or_write(&p, &["toml"]),
        crate::paths::Access::Write => grants.write(&p, &["toml"]),
    }
    .map_err(|e| format!("agent config: {e}"))?;
    Ok(Some(g.path().to_string_lossy().into_owned()))
}

#[tauri::command]
pub async fn agent_schema() -> AgentSchema {
    schema()
}

/// Loads the config the user opened; the editor may save it back to the same file.
#[tauri::command]
pub async fn agent_config_load<R: Runtime>(app: AppHandle<R>, grants: WindowGrants, path: Option<String>) -> CmdResult<AgentConfigDoc> {
    let d = dirs(&app)?;
    let path = granted(&grants, path, crate::paths::Access::Read)?;
    if let Some(p) = &path {
        let _ = grants.grant(Path::new(p), crate::paths::Access::Write, crate::paths::GrantSource::Dialog);
    }
    tauri::async_runtime::spawn_blocking(move || load_doc(path.as_deref(), &d))
        .await
        .map_err(err)?
}

#[tauri::command]
pub async fn agent_config_validate<R: Runtime>(
    app: AppHandle<R>,
    grants: WindowGrants,
    path: Option<String>,
    config: AgentConfigFile,
) -> CmdResult<Vec<Issue>> {
    let d = dirs(&app)?;
    let path = granted(&grants, path, crate::paths::Access::Read)?;
    tauri::async_runtime::spawn_blocking(move || validate_doc(path.as_deref(), &config, &d))
        .await
        .map_err(err)?
}

/// Saves the config; an existing file only with `overwrite` (the editor's own file, or confirmed).
#[tauri::command]
pub async fn agent_config_save<R: Runtime>(
    app: AppHandle<R>,
    grants: WindowGrants,
    path: Option<String>,
    config: AgentConfigFile,
    overwrite: Option<bool>,
) -> CmdResult<Vec<Issue>> {
    let d = dirs(&app)?;
    let path = granted(&grants, path, crate::paths::Access::Write)?;
    let overwrite = overwrite.unwrap_or(false);
    tauri::async_runtime::spawn_blocking(move || save_doc(path.as_deref(), &config, overwrite, &d))
        .await
        .map_err(err)?
}

#[tauri::command]
pub async fn agent_runs<R: Runtime>(app: AppHandle<R>, grants: WindowGrants, path: Option<String>) -> CmdResult<RunsListing> {
    let d = dirs(&app)?;
    let path = granted(&grants, path, crate::paths::Access::Read)?;
    tauri::async_runtime::spawn_blocking(move || runs(path.as_deref(), &d))
        .await
        .map_err(err)?
}

#[tauri::command]
pub async fn agent_run_manifest<R: Runtime>(
    app: AppHandle<R>,
    grants: WindowGrants,
    path: Option<String>,
    run_id: String,
) -> CmdResult<RunManifest> {
    let d = dirs(&app)?;
    let path = granted(&grants, path, crate::paths::Access::Read)?;
    tauri::async_runtime::spawn_blocking(move || manifest(path.as_deref(), &run_id, &d))
        .await
        .map_err(err)?
}

/// Opens a run's folder in a new Debrief window (the window manager's usual path).
#[tauri::command]
pub async fn agent_open_run<R: Runtime>(
    app: AppHandle<R>,
    grants: WindowGrants,
    path: Option<String>,
    run_id: String,
) -> CmdResult<String> {
    let path = granted(&grants, path, crate::paths::Access::Read)?;
    let dir = run_dir(path.as_deref(), &run_id, &dirs(&app)?)?;
    crate::error::lift(crate::window_manager::open_new(&app, vec![dir.to_string_lossy().into_owned()]).map_err(err))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_support::Now as _;
    use crate::test_support::TempDir;
    use debrief_agent::run::{create_run_dir, write_manifest, RunReason};

    fn dirs_in(t: &TempDir) -> Dirs {
        Dirs {
            config: t.0.join("config"),
            output: t.0.join("runs"),
        }
    }

    #[test]
    fn starter_save_load_and_validation() {
        let t = TempDir::new("agent-cfg");
        let d = dirs_in(&t);
        let doc = load_doc(None, &d).unwrap();
        assert!(!doc.exists);
        assert!(doc.path.ends_with(CONFIG_NAME));
        let mut cfg = doc.config.unwrap();
        assert_eq!(cfg.agent.output_dir, d.output.to_string_lossy());
        assert!(validate_doc(None, &cfg, &d).unwrap().is_empty());
        assert!(save_doc(None, &cfg, false, &d).unwrap().is_empty());
        let saved = std::fs::read_to_string(d.config.join(CONFIG_NAME)).unwrap();
        assert!(saved.starts_with("# debrief-agent configuration"));
        let doc = load_doc(None, &d).unwrap();
        assert!(doc.exists && doc.issues.is_empty());
        assert_eq!(doc.config.as_ref(), Some(&cfg));

        // An invalid document is not saved; its issues come back with paths.
        cfg.schedules[0].cron = Some("99 * * * *".into());
        let issues = save_doc(None, &cfg, true, &d).unwrap();
        assert_eq!(issues[0].path, "schedules[0].cron");
        assert_eq!(validate_doc(None, &cfg, &d).unwrap(), issues);
        assert_eq!(
            load_doc(None, &d).unwrap().config.unwrap().schedules[0].cron.as_deref(),
            Some("0 2 * * *")
        );

        // A corrupt file loads with its problem and no document; an invalid one with both.
        std::fs::write(d.config.join(CONFIG_NAME), "version = ").unwrap();
        let doc = load_doc(None, &d).unwrap();
        assert!(doc.config.is_none() && !doc.issues.is_empty());
        std::fs::write(d.config.join(CONFIG_NAME), "version = 1").unwrap();
        let doc = load_doc(None, &d).unwrap();
        assert!(doc.config.is_some() && doc.issues[0].path == "agent.outputDir");
    }

    #[test]
    fn an_existing_config_is_replaced_only_when_confirmed_and_keeps_its_comments() {
        use debrief_core::overwrite::FILE_EXISTS_SUFFIX;
        let t = TempDir::new("agent-overwrite");
        let d = dirs_in(&t);
        let file = d.config.join(CONFIG_NAME);
        std::fs::create_dir_all(&d.config).unwrap();
        let mine = format!(
            "# My schedules -- do not lose this.\nversion = 1\n\n[agent]\n# where runs go\noutputDir = {:?}\ntickSecs = 15 # check often\n\n[[schedules]]\nname = \"nightly\"\ncron = \"0 2 * * *\"\n  [[schedules.actions]]\n  kind = \"collect\"\n",
            d.output.to_string_lossy()
        );
        std::fs::write(&file, &mine).unwrap();
        let mut cfg = load_doc(None, &d).unwrap().config.unwrap();
        cfg.agent.tick_secs = 60;
        // Not confirmed: refused with the error the UI asks about; the file is untouched.
        let e = save_doc(None, &cfg, false, &d).unwrap_err();
        assert_eq!(e, crate::error::file_exists(format!("{}{FILE_EXISTS_SUFFIX}", file.display())));
        assert_eq!(std::fs::read_to_string(&file).unwrap(), mine);
        // An invalid document is reported before asking.
        let mut bad = cfg.clone();
        bad.agent.tick_secs = 0;
        assert_eq!(save_doc(None, &bad, false, &d).unwrap()[0].path, "agent.tickSecs");
        // Confirmed: only the changed value is rewritten; comments and left-out defaults stay.
        assert!(save_doc(None, &cfg, true, &d).unwrap().is_empty());
        let saved = std::fs::read_to_string(&file).unwrap();
        assert_eq!(saved, mine.replace("tickSecs = 15", "tickSecs = 60"));
        assert_eq!(load_doc(None, &d).unwrap().config.unwrap(), cfg);

        // A file that is not TOML (or not text, or too large) is replaced by a fresh document.
        for junk in [
            b"version = ".to_vec(),
            vec![0xff, 0xfe, 0x00],
            vec![b'#'; MAX_CONFIG_BYTES as usize + 1],
        ] {
            std::fs::write(&file, junk).unwrap();
            assert!(save_doc(None, &cfg, true, &d).unwrap().is_empty());
            let saved = std::fs::read_to_string(&file).unwrap();
            assert!(saved.starts_with("# debrief-agent configuration"), "{saved}");
            assert_eq!(load_doc(None, &d).unwrap().config.unwrap(), cfg);
        }
        // A folder in the way cannot be read.
        std::fs::remove_file(&file).unwrap();
        std::fs::create_dir(&file).unwrap();
        assert!(save_doc(None, &cfg, true, &d).unwrap_err().contains("cannot read"));
    }

    #[test]
    fn paths_are_checked() {
        let t = TempDir::new("agent-paths");
        let d = dirs_in(&t);
        assert_eq!(resolve_path(Some("  "), &d).unwrap(), d.config.join(CONFIG_NAME));
        assert!(resolve_path(Some(&t.0.join("x.txt").to_string_lossy()), &d)
            .unwrap_err()
            .contains(".toml"));
        assert!(resolve_path(Some("x.toml"), &d).unwrap_err().contains("absolute"));
        assert!(resolve_path(Some(&t.0.join("no/such/dir/x.toml").to_string_lossy()), &d)
            .unwrap_err()
            .contains("does not exist"));
        assert!(resolve_path(Some("a\0.toml"), &d).is_err());
        let p = t.0.join("mine.toml");
        assert_eq!(
            resolve_path(Some(p.to_str().unwrap()), &d).unwrap(),
            crate::paths::plain(std::fs::canonicalize(&t.0).unwrap()).join("mine.toml")
        );
    }

    #[test]
    fn runs_and_manifests() {
        let t = TempDir::new("agent-runs");
        let d = dirs_in(&t);
        assert!(runs(None, &d).unwrap_err().contains("save the schedules first"));
        save_doc(None, &AgentConfigFile::starter(&d.output.to_string_lossy()), false, &d).unwrap();
        assert!(runs(None, &d).unwrap().runs.is_empty());
        let now = jiff::Timestamp::now();
        let (id, dir) = create_run_dir(&d.output, "nightly", now).unwrap();
        write_manifest(&dir, &RunManifest::start(&id, "nightly", RunReason::Manual, now)).unwrap();
        let listing = runs(None, &d).unwrap();
        assert_eq!(listing.runs.len(), 1);
        assert_eq!(listing.truncated, 0);
        assert_eq!(manifest(None, &id, &d).unwrap().schedule, "nightly");
        assert!(manifest(None, "../etc", &d).unwrap_err().contains("not a run"));
        assert!(manifest(None, "20260101-000000-gone", &d).unwrap_err().contains("no longer exists"));
        // An invalid saved config is reported.
        std::fs::write(d.config.join(CONFIG_NAME), "version = 1").unwrap();
        assert!(runs(None, &d).unwrap_err().contains("agent.outputDir"));
        assert_eq!(agent_schema().now().version, debrief_agent::CONFIG_VERSION);
    }
}

