    assert_eq!(code(ipc(&main, "ai_knowledge_export", export.clone()).unwrap_err()), "notGranted");
    grant(&app, &out, crate::paths::Access::Write);
    ipc(&main, "ai_knowledge_export", export.clone()).unwrap();
