                        }
                    ),
                    "{action:?}: {phase:?}"
                );
                assert!(gone(pid), "{action:?}: no process is left");
                assert!(removed(&dir), "{action:?}: no profile is left");
                let (_, pid2) = research_step(&r);
                assert_ne!(pid, pid2, "{action:?}");
                r.renderers.kill_all();
