        let dir = TempDir::new("open-source-file");
        crate::paths::allow_under(app.handle(), crate::windows::MAIN, &dir.0);
        let folder = dir.0.clone();
        let archives = samples().join("archives").join("notify01");
        for f in ["app.log.3.gz", "notify01-logs-20261014.zip"] {
            std::fs::copy(archives.join(f), folder.join(f)).unwrap();
        }
        std::fs::write(
            folder.join("plain.log"),
            "2026-10-14 10:00:00 [INF] started\n2026-10-14 10:00:01 [ERR] failed\n",
        )
        .unwrap();
        let summary = ipc(&main, "open_paths", json!({ "paths": [folder.to_string_lossy()] })).unwrap();
        let sources = summary["sources"].as_array().unwrap();
        let by_kind = |kind: &str| {
            sources
                .iter()
                .find(|s| s["fileKind"] == kind)
                .unwrap_or_else(|| panic!("no {kind} source"))["id"]
                .clone()
        };
        let open = |w: &tauri::WebviewWindow<tauri::test::MockRuntime>, body| ipc(w, "open_source_file", json!({ "request": body }));
        let err = |r: Result<serde_json::Value, serde_json::Value>| r.unwrap_err()["message"].as_str().unwrap_or_default().to_string();

        let text = by_kind("text");
        assert_eq!(
            open(&main, json!({ "sourceId": text, "action": "openAtLine", "line": 2 })).unwrap()["path"]
                .as_str()
                .map(|p| p.ends_with(".log")),
            Some(true)
        );
        assert_eq!(
            open(&main, json!({ "sourceId": text, "action": "reveal" })).unwrap()["with"],
            "fileManager"
        );

        let member = by_kind("archiveMember");
        assert!(err(open(&main, json!({ "sourceId": member, "action": "open" }))).contains("inside the archive"));
        assert!(open(&main, json!({ "sourceId": member, "action": "reveal" })).unwrap()["path"]
            .as_str()
            .unwrap()
            .ends_with(".zip"));
        let gz = by_kind("compressed");
        assert!(err(open(&main, json!({ "sourceId": gz, "action": "openAtLine", "line": 1 }))).contains("no line to jump to"));

        assert!(err(open(&main, json!({ "sourceId": 999, "action": "open" }))).contains("no longer open"));
        // Another window has its own sources: the ids of this one mean nothing there.
        let other = window(&app, "w-2");
        assert!(err(open(&other, json!({ "sourceId": text, "action": "open" }))).contains("no longer open"));
        // A removed source is no longer reachable.
        ipc(&main, "remove_source", json!({ "sourceId": text })).unwrap();
        assert!(err(open(&main, json!({ "sourceId": text, "action": "reveal" }))).contains("no longer open"));
        // No path is accepted from the webview.
        assert!(open(
            &main,
            json!({ "sourceId": member, "action": "open", "path": "C:/Windows/notepad.exe" })
        )
        .is_err());
    }
}

//! The jobs commands through the real IPC path (`tauri::test`), with the test app's manual clock: the
//! pane's list and events, the tray mirror, Cancel, Retry, View (results, revealing files), the history
//! saved with the project, window ownership, and messages for finished jobs.

use super::*;
use crate::test_support::{samples, test_app_with_commands, window, TempDir, TestClock};
use crate::tools::tests::ipc;
use serde_json::json;
use std::sync::mpsc;
use tauri::test::MockRuntime;
use tauri::Listener;

fn clock(app: &tauri::App<MockRuntime>) -> Arc<ManualClock> {
    app.state::<TestClock>().0.clone()
}

fn jobs(app: &tauri::App<MockRuntime>) -> Jobs {
    app.state::<Jobs>().inner().clone()
}

type Release = mpsc::Sender<Result<Option<JobResult>, String>>;

/// An export job of `window` that runs until the test releases it with a result.
fn gated_export(app: &tauri::App<MockRuntime>, window: &str, title: &str) -> (JobId, Release) {
    let spec = JobSpec::new(JobKind::Export, title)
        .window(window)
        .retry_with(json!({"op": "export"}));
    gated_spec(app, spec)
}

/// A job of `spec` that runs until the test releases it with a result.
fn gated_spec(app: &tauri::App<MockRuntime>, spec: JobSpec) -> (JobId, Release) {
    let (tx, rx) = mpsc::channel::<Result<Option<JobResult>, String>>();
    let rx = Mutex::new(rx);
    let id = spawn(
        app.handle(),
        spec,
        Controls::default(),
        move |ctx: &JobCtx| -> Result<Done<()>, String> {
            loop {
                if ctx.is_cancelled() {
                    return Err("cancelled".into());
                }
                match rx.lock().unwrap().recv_timeout(std::time::Duration::from_millis(5)) {
                    Ok(Ok(r)) => {
                        let d = Done::new(());
                        return Ok(match r {
                            Some(r) => d.with_result(r),
                            None => d,
                        });
                    }
                    Ok(Err(e)) => return Err(e),
                    Err(mpsc::RecvTimeoutError::Timeout) => {}
                    Err(_) => return Err("gone".into()),
                }
            }
        },
    )
    .unwrap();
    (id, tx)
}

fn listed(main: &tauri::WebviewWindow<MockRuntime>) -> Vec<Value> {
    ipc(main, "jobs_list", json!({})).unwrap()["jobs"].as_array().unwrap().clone()
}

/// The spec the producers of an AI request build (the button, the menu and the palette all go through it), in store `store`.
fn ai_spec(request: crate::ai::requests::AiRequest, window: &str, store: u64) -> JobSpec {
    request.spec(window, Some(crate::engine::StoreId::for_test(store)))
}

/// H11 (docs/research/2026-10-28-cpu-memory.md): Summarize from the button, the menu and the palette each queued a job. A
/// request that is already queued or running gives the same job, not a second one.
#[test]
fn two_identical_requests_give_one_job() {
    use crate::ai::requests::AiRequest::Summarize;
    let app = test_app_with_commands(None);
    let summarize = |from, to| ai_spec(Summarize { from, to }, "main", 1);
    let (first, _release_first) = gated_spec(&app, summarize(0, 10));
    let (second, _release_second) = gated_spec(&app, summarize(0, 10));
    assert_eq!(
        first,
        second,
        "the same request twice queued {} jobs",
        jobs(&app).find_active(|_| true).len()
    );
    // Another range is another request.
    let (other, _release_other) = gated_spec(&app, summarize(0, 11));
    assert_ne!(first, other);
}

/// Explain (by event) and Root causes are keyed like Summarize; a different event, window or project is another job.
#[test]
fn explain_and_root_causes_merge_per_event_window_and_project() {
    use crate::ai::requests::AiRequest::{Explain, RootCauses};
    let app = test_app_with_commands(None);
    let (explain, _r1) = gated_spec(&app, ai_spec(Explain { record_id: 5 }, "main", 1));
    let (again, _r2) = gated_spec(&app, ai_spec(Explain { record_id: 5 }, "main", 1));
    assert_eq!(explain, again, "the same event twice");
    let (other_event, _r3) = gated_spec(&app, ai_spec(Explain { record_id: 6 }, "main", 1));
    assert_ne!(explain, other_event);
    let (root, _r4) = gated_spec(&app, ai_spec(RootCauses, "main", 1));
    let (root_again, _r5) = gated_spec(&app, ai_spec(RootCauses, "main", 1));
    assert_eq!(root, root_again, "root causes twice");
    // The same ask in another window is that window's own job.
    let (other_window, _r6) = gated_spec(&app, ai_spec(RootCauses, "w-2", 1));
    assert_ne!(root, other_window);
}

/// The window now holds another project (another store): its request never joins the old project's job.
