    #[test]
    fn sessions_per_window_survive_a_crash() {
        let d = temp("sessions");
        let store = SessionStore::new(d.clone());
        store.rotate();
        assert!(store.recovered().is_empty() && store.last_session(MAIN).is_none());
        store.save(MAIN, &project("main 1")).unwrap();
        store.save("w-2", &project("second")).unwrap();
        store.save("w-3", &project("third")).unwrap();
        store.save("w-2", &project("second, later")).unwrap();
        // The user closes w-3: it is not restored.
        store.forget("w-3");
        store.forget("w-3");
        assert!(store.save("../evil", &project("x")).is_err());
        store.forget("../evil");

        // Next start (after a crash): the previous run's windows are recovered.
        let next = SessionStore::new(d.clone());
        next.rotate();
        let recovered = next.recovered();
        let labels: Vec<&str> = recovered.iter().map(|(l, _)| l.as_str()).collect();
        assert_eq!(labels, ["main", "w-2"]);
        assert_eq!(name_of(&recovered[1].1), "second, later");
        // Main offers the recovered session until it saves its own.
        assert_eq!(name_of(&next.last_session(MAIN).unwrap()), "main 1");
        assert!(next.last_session("w-9").is_none());
        next.save(MAIN, &project("main 2")).unwrap();
        assert_eq!(name_of(&next.last_session(MAIN).unwrap()), "main 2");
        // The recovered copy is not overwritten by the new run.
        assert_eq!(name_of(&next.recovered()[0].1), "main 1");
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn sessions_tolerate_corrupt_files() {
        let d = temp("corrupt");
        std::fs::create_dir_all(&d).unwrap();
        let store = SessionStore::new(d.clone());
        store.rotate();
        assert!(store.recovered().is_empty());

        // A corrupt manifest: the session folders are listed instead.
        store.save("w-4", &project("four")).unwrap();
        store.save(MAIN, &project("main")).unwrap();
        std::fs::write(d.join(SESSIONS_DIR).join(MANIFEST), "{ not json").unwrap();
        std::fs::create_dir_all(d.join(SESSIONS_DIR).join("w-5")).unwrap(); // no session file in it
        store.rotate();
        let labels: Vec<String> = store.recovered().into_iter().map(|(l, _)| l).collect();
        assert_eq!(labels, ["main", "w-4"]);
        // A manifest naming a missing or invalid window lists only real sessions.
        std::fs::write(
            d.join(RECOVERED_DIR).join(MANIFEST),
            r#"{"version":2,"windows":["main","gone","../x"]}"#,
        )
        .unwrap();
        assert_eq!(store.recovered().len(), 1);
        std::fs::remove_dir_all(d).unwrap();
        // No folder at all: nothing, and nothing fails.
        let none = SessionStore::new(temp("none").join("missing"));
        assert!(none.recovered().is_empty());
    }

    #[test]
    fn session_commands_per_window() {
        use crate::test_support::{block, main_window, samples, test_app, window};
        use tauri::Manager;
        let d = temp("session-cmds");
        // A previous run with two windows that crashed.
        {
            let store = SessionStore::new(d.clone());
            store.rotate();
            store.save(MAIN, &project("main")).unwrap();
            store.save("w-2", &project("second")).unwrap();
            // A process that no longer exists.
            std::fs::write(d.join(MARKER), r#"{"version":1,"pid":4000000000,"startedAt":1}"#).unwrap();
        }
        let app = test_app(None);
        app.manage(Lifecycle::begin(Some(d.clone()), false));
        let h = app.handle().clone();
        window(&app, MAIN);
        let grants = |label: &str| crate::paths::WindowGrants::of(&h, label);
        let life = || app.state::<Lifecycle>();
        let status = app_status(main_window(&app), life()).now().unwrap();
        assert!(status.previous_crash && status.session_available);
        // The About window shows this: the Cargo version of the build, release-shaped (major.minor.patch), never a placeholder.
        let parts: Vec<&str> = status.version.split(['.', '-']).collect();
        assert!(
            parts.len() >= 3 && parts[..3].iter().all(|p| !p.is_empty() && p.bytes().all(|b| b.is_ascii_digit())),
            "{}",
            status.version
        );
        assert_eq!(status.version, env!("CARGO_PKG_VERSION"));
        // Another window does not offer crash recovery.
        let w2 = crate::windows::CurrentWindow::of(&h, "w-7").unwrap();
        let other = app_status(w2.clone(), life()).now().unwrap();
        assert!(!other.previous_crash && !other.session_available);
        assert!(last_session(w2.clone(), grants("w-7"), life()).now().unwrap().is_none());
        assert!(last_session(main_window(&app), grants(MAIN), life())
            .now()
            .unwrap()
            .unwrap()
            .ends_with(SESSION_FILE));

        // Restoring reopens the other window with its session queued, once.
        assert_eq!(
            tauri::async_runtime::block_on(restore_windows(h.clone(), main_window(&app), life())).unwrap(),
            1
        );
        assert_eq!(
            tauri::async_runtime::block_on(restore_windows(h.clone(), main_window(&app), life())).unwrap(),
            0
        );
        let restored = crate::windows::CurrentWindow::of(&h, "w-2").unwrap().take_pending();
        assert_eq!(restored.len(), 1);
        assert_eq!(name_of(Path::new(&restored[0])), "second");

        // Autosave of this run, per window.
        crate::paths::allow_under(&h, MAIN, &samples());
        let csv = samples().join("csv").to_string_lossy().into_owned();
        crate::test_support::finished(
            &app,
            block(crate::workspace_commands::open_paths(h.clone(), main_window(&app), vec![csv])),
        )
        .unwrap()
        .json();
        save_session(
            main_window(&app),
            life(),
            serde_json::json!({ "k": 1 }),
            Some(vec![serde_json::json!({"id": "r"}), Value::Null]),
        )
        .now()
        .unwrap();
        save_session(w2.clone(), life(), Value::Null, None).now().unwrap();
        let saved = ProjectFile::load(
            &last_session(main_window(&app), grants(MAIN), life())
                .now()
                .unwrap()
                .map(PathBuf::from)
                .unwrap(),
        )
        .unwrap();
        assert_eq!((saved.sources.len(), saved.ui["k"].as_i64()), (1, Some(1)));
        assert_eq!(saved.reports.len(), 1, "an unreadable report is left out of the autosave");
        assert!(last_session(w2, grants("w-7"), life()).now().unwrap().is_some());
        life().forget_session("w-7");
        // Without a data folder sessions are off.
        let app2 = test_app(None);
        app2.manage(Lifecycle::begin(None, false));
        save_session(main_window(&app2), app2.state::<Lifecycle>(), Value::Null, None)
            .now()
            .unwrap();
        assert_eq!(
            tauri::async_runtime::block_on(restore_windows(
                app2.handle().clone(),
                main_window(&app2),
                app2.state::<Lifecycle>()
            ))
            .unwrap(),
            0
        );
        app2.state::<Lifecycle>().forget_session(MAIN);
        std::fs::remove_dir_all(d).unwrap();
    }
}

//! Notes through their commands (ADR 0021): anchors filled and checked by the engine, typed refusals, the record
//! saved with a project and restored in another window with every anchor resolving (the event in the project's
//! store, the image from the project's copy after the original is gone), and the AI's notes file.

use super::commands::*;
use crate::test_support::{block, main_window, samples, test_app, TempDir};
use crate::windows::CurrentWindow;
use crate::ErrorCode;
use debrief_notes::context::Focus;
use debrief_notes::{Anchor, NoteChange, NoteDraft, Region};
use serde_json::{json, Value};
use tauri::test::MockRuntime;

fn draft(v: Value) -> NoteDraft {
    serde_json::from_value(v).unwrap()
}

fn add(w: CurrentWindow, v: Value) -> crate::CmdResult<debrief_notes::Note> {
    block(notes_add(w, draft(v)))
}

fn copy_dir(from: &std::path::Path, to: &std::path::Path) {
    std::fs::create_dir_all(to).unwrap();
    for f in std::fs::read_dir(from).unwrap().flatten() {
        if f.path().is_dir() {
            copy_dir(&f.path(), &to.join(f.file_name()));
        } else {
            std::fs::copy(f.path(), to.join(f.file_name())).unwrap();
        }
    }
}

/// A test app whose main window opened a copy of the log4net samples and a 40×20 screenshot next to them.
fn workspace(tag: &str) -> (TempDir, tauri::App<MockRuntime>, std::path::PathBuf) {
    let dir = TempDir::new(tag);
    let logs = dir.0.join("logs");
    copy_dir(&samples().join("log4net"), &logs);
    let png = logs.join("screen.png");
    std::fs::write(&png, crate::activity::report::sample::png(40, 20, |x, _| [x as u8 * 6, 0, 0])).unwrap();
    let app = test_app(Some(dir.0.join("profiles")));
    crate::paths::allow_under(app.handle(), "main", &dir.0);
    let opened = crate::test_support::finished(
        &app,
        block(crate::workspace_commands::open_paths(
            app.handle().clone(),
            main_window(&app),
            vec![logs.to_string_lossy().into_owned()],
        )),
    )
    .unwrap();
    assert!(opened["total"].as_u64().unwrap() > 0);
    (dir, app, png)
}

fn first_event(app: &tauri::App<MockRuntime>) -> u64 {
    main_window(app).engine.store().unwrap().ids_at(0, 1).unwrap()[0].0
}

fn grants(app: &tauri::App<MockRuntime>, label: &str) -> crate::paths::WindowGrants {
    crate::paths::WindowGrants::of(app.handle(), label)
}

#[test]
fn anchors_are_filled_and_checked_by_the_engine() {
    let (_dir, app, _png) = workspace("notes-anchors");
    let id = first_event(&app);
    // The webview's excerpt is not trusted: the engine takes the event's own.
    let n = add(main_window(&app), json!({"anchor": {"kind": "event", "eventId": id, "excerpt": "forged"}, "text": "Look **here**", "tags": ["Disk"], "severity": "problem"})).unwrap();
    let Anchor::Event { excerpt, ts, source, .. } = &n.anchor else {
        panic!("{n:?}")
    };
    assert!(excerpt != "forged" && !excerpt.is_empty() && ts.is_some() && !source.is_empty());
    assert_eq!((n.id.as_str(), n.tags[0].as_str()), ("n1", "disk"));
    assert_eq!(n.author, super::author().chars().take(64).collect::<String>());
    // Typed refusals.
    let code = |r: crate::CmdResult<debrief_notes::Note>| r.unwrap_err().code;
    assert_eq!(
        code(add(
            main_window(&app),
            json!({"anchor": {"kind": "event", "eventId": u32::MAX}, "text": "x"})
        )),
        ErrorCode::NotFound
    );
    assert_eq!(
        code(add(
            main_window(&app),
            json!({"anchor": {"kind": "range", "from": 5, "to": 1}, "text": "x"})
        )),
        ErrorCode::Invalid
    );
    assert_eq!(
        code(add(main_window(&app), json!({"anchor": {"kind": "project"}, "text": " "}))),
        ErrorCode::Invalid
    );
    assert_eq!(
        code(add(
            main_window(&app),
            json!({"anchor": {"kind": "source", "path": "/not/listed.log"}, "text": "x"})
        )),
        ErrorCode::Invalid
    );
    let unopened = json!({"anchor": {"kind": "image", "image": {"key": debrief_notes::image_key(b"never"), "name": "x.png", "width": 4, "height": 4}, "regions": [{"x": 0, "y": 0, "w": 1, "h": 1}]}, "text": "x"});
    assert_eq!(code(add(main_window(&app), unopened)), ErrorCode::NotFound);
    let big = "x".repeat(debrief_notes::MAX_TEXT_BYTES + 1);
    assert_eq!(
        code(add(main_window(&app), json!({"anchor": {"kind": "project"}, "text": big}))),
        ErrorCode::Limit
    );
    // Sources of the workspace, changes and removal.
    let summary = crate::test_support::store_summary(&main_window(&app));
    let path = summary.sources[0].path.clone();
    let s = add(
        main_window(&app),
        json!({"anchor": {"kind": "source", "path": path}, "text": "rotated hourly"}),
    )
    .unwrap();
    let change = NoteChange {
        text: Some("rotated daily".into()),
        ..NoteChange::default()
    };
    assert_eq!(
        block(notes_update(main_window(&app), s.id.clone(), change)).unwrap().text,
        "rotated daily"
    );
    let regions = NoteChange {
        regions: Some(vec![Region { x: 0, y: 0, w: 1, h: 1 }]),
        ..NoteChange::default()
    };
    assert_eq!(
        block(notes_update(main_window(&app), s.id.clone(), regions)).unwrap_err().code,
        ErrorCode::Invalid
    );
    assert!(block(notes_remove(main_window(&app), s.id.clone())).unwrap());
    assert_eq!(block(notes_remove(main_window(&app), s.id)).unwrap_err().code, ErrorCode::NotFound);
    let list = block(notes_list(main_window(&app))).unwrap();
    assert_eq!((list.notes.len(), list.notes[0].resolved, list.max_regions), (1, true, 16));
}

#[test]
fn image_regions_are_checked_against_the_image_and_kept_in_the_project() {
    let (_dir, app, png) = workspace("notes-images");
    // Listed in the Explorer (an unrecognised file of the opened folder): opens without a dialog.
    let img = block(notes_image_open(
        main_window(&app),
        grants(&app, "main"),
        png.to_string_lossy().into_owned(),
    ))
    .unwrap();
    assert_eq!((img.width, img.height, img.key.len()), (40, 20, 64));
    assert!(img.data_url.starts_with("data:image/"));
    let region = |x: u32, w: u32| json!({"anchor": {"kind": "image", "image": {"key": img.key, "name": "forged", "width": 4000, "height": 4000}, "regions": [{"x": x, "y": 0, "w": w, "h": 10}]}, "text": "error banner"});
    // The engine's size, not the webview's: a region beyond 40 px wide is outside.
    assert_eq!(add(main_window(&app), region(30, 20)).unwrap_err().code, ErrorCode::Invalid);
    let n = add(main_window(&app), region(5, 10)).unwrap();
    let Anchor::Image { image, .. } = &n.anchor else { panic!() };
    assert_eq!((image.name.as_str(), image.width), ("screen.png", 40));
    let store_dir = main_window(&app).engine.store().unwrap().store_dir();
    assert!(
        super::images::find_copy(&store_dir, &img.key).is_some(),
        "the clean copy is in the project"
    );
    assert_eq!(block(notes_image_get(main_window(&app), img.key.clone())).unwrap().key, img.key);
    assert_eq!(
        block(notes_image_get(main_window(&app), "nope".into())).unwrap_err().code,
        ErrorCode::NotFound
    );
    // Files that are not images, or not chosen, are refused.
    let other = crate::test_support::scratch_dir("notes-not-chosen").join("other.png");
    std::fs::write(&other, b"x").unwrap();
    assert!(block(notes_image_open(
        main_window(&app),
        grants(&app, "main"),
        other.to_string_lossy().into_owned()
    ))
    .is_err());
    let fake = png.with_file_name("fake.png");
    std::fs::write(&fake, b"not a png").unwrap();
    assert_eq!(
        block(notes_image_open(
            main_window(&app),
            grants(&app, "main"),
            fake.to_string_lossy().into_owned()
        ))
        .unwrap_err()
        .code,
        ErrorCode::Invalid
    );
}

/// Notes are saved with the project and restored in another window: the event anchor resolves in the project's
/// store and the image opens from the project's copy, without the original files.
#[test]
fn anchors_resolve_after_reopening_a_project() {
    let (dir, app, png) = workspace("notes-project");
    let id = first_event(&app);
    add(
        main_window(&app),
        json!({"anchor": {"kind": "event", "eventId": id}, "text": "first failure"}),
    )
    .unwrap();
    add(
        main_window(&app),
        json!({"anchor": {"kind": "range", "from": 1, "to": 2}, "text": "outage"}),
    )
    .unwrap();
    let img = block(notes_image_open(
        main_window(&app),
        grants(&app, "main"),
        png.to_string_lossy().into_owned(),
    ))
    .unwrap();
    add(main_window(&app), json!({"anchor": {"kind": "image", "image": {"key": img.key, "name": "", "width": 1, "height": 1}, "regions": [{"x": 1, "y": 1, "w": 5, "h": 5}]}, "text": "red bar"})).unwrap();
    let record = serde_json::to_value(block(notes_record(main_window(&app))).unwrap()).unwrap();
    assert_eq!(record["version"], 1);
    let file = dir.0.join("incident.debriefz").to_string_lossy().into_owned();
    crate::test_support::finished(
        &app,
        block(crate::workspace_commands::save_project(
            app.handle().clone(),
            main_window(&app),
            grants(&app, "main"),
            Default::default(),
            file.clone(),
            "Incident".into(),
            json!({ "notes": record }),
            None,
            None,
        )),
    )
    .unwrap();
    std::fs::remove_dir_all(dir.0.join("logs")).unwrap();
    crate::paths::allow_under(app.handle(), "w-2", &dir.0);
    let w2 = || CurrentWindow::of(app.handle(), "w-2").unwrap();
    let opened = crate::test_support::finished(
        &app,
        block(crate::workspace_commands::open_project(
            app.handle().clone(),
            w2(),
            grants(&app, "w-2"),
            Default::default(),
            file,
        )),
    )
    .unwrap();
    let restored = block(notes_restore(w2(), Some(opened["ui"]["notes"].clone()))).unwrap();
    assert_eq!((restored.count, restored.warning), (3, None));
    let list = block(notes_list(w2())).unwrap();
    assert!(list.notes.iter().all(|n| n.resolved), "{:?}", list.notes);
    let back = block(notes_image_get(w2(), img.key.clone())).unwrap();
    assert_eq!(
        (back.width, back.height, back.path),
        (40, 20, None),
        "the original's size, from the project's copy"
    );
    // A note on an event the store does not have says so instead of disappearing.
    let mut v = opened["ui"]["notes"].clone();
    v["notes"][0]["anchor"]["eventId"] = json!(u32::MAX);
    block(notes_restore(w2(), Some(v))).unwrap();
    assert!(!block(notes_list(w2())).unwrap().notes[0].resolved);
    // Damaged and newer records restore nothing and say why; none clears.
    let r = block(notes_restore(w2(), Some(json!({"version": 99})))).unwrap();
    assert!(r.count == 0 && r.warning.unwrap().contains("newer"));
    assert_eq!(block(notes_restore(w2(), None)).unwrap(), NotesRestore { count: 0, warning: None });
}

#[test]
fn the_ai_reads_the_notes_as_a_knowledge_file_focused_first() {
    let mut set = debrief_notes::NoteSet::default();
    assert!(super::ai_file(&set, &Focus::default()).is_none());
    for (anchor, text) in [(Anchor::Instant { at: 10 }, "early"), (Anchor::Instant { at: 500 }, "focused")] {
        let d = NoteDraft {
            anchor,
            text: text.into(),
            tags: None,
            severity: None,
        };
        set.add(&d, "", 0).unwrap();
    }
    let f = super::ai_file(
        &set,
        &Focus {
            range: Some((400, 600)),
            ..Focus::default()
        },
    )
    .unwrap();
    assert_eq!((f.id.as_str(), f.name.as_str()), (super::NOTES_KNOWLEDGE_ID, "Notes"));
    assert!(f.text.find("focused").unwrap() < f.text.find("early").unwrap());
}

//! Generic dispatch of plugin tools (ADR 0002): `tools_list` lists the tools
//! of the calling window's plugins with their availability, and
//! `tool_invoke { tool, op, args }` runs one operation. The shell knows no
//! tool: arguments are validated by the host against the tool's schema, and
//! the call runs under the plugin's guard and the operation's time budget.
//!
//! Background work a tool reports goes through [`ShellTasks`]: what runs until
//! stopped (the process monitor, a PerfMon collector set) is listed in
//! [`BackgroundTasks`] (tray, status bar); a collection that ends by itself (a
//! diagnostics collection) is a collection job (one at a time; a second one is
//! stopped with a reason). Stopping either calls the tool back through the same host.

use crate::background::{BackgroundTasks, TaskKind, TaskSpec};
use crate::windows::CurrentWindow;
use crate::{AppState, CmdResult, State};
use debrief_core::plugin::tools::{TaskSink, ToolCtx, ToolEntry, ToolError, ToolHost, ToolTask, MAX_ID_LEN};
use serde_json::Value;
use std::path::PathBuf;
use std::sync::Arc;
use tauri::{AppHandle, Manager, Runtime};

/// Lists background work of tools in [`BackgroundTasks`]; its stop action
/// calls [`ToolHost::stop`].
pub(crate) struct ShellTasks<R: Runtime> {
    app: AppHandle<R>,
    host: ToolHost,
    data_dir: Option<PathBuf>,
}

impl<R: Runtime> Clone for ShellTasks<R> {
    fn clone(&self) -> Self {
        ShellTasks {
            app: self.app.clone(),
            host: self.host.clone(),
            data_dir: self.data_dir.clone(),
        }
    }
}

impl<R: Runtime> ShellTasks<R> {
    /// The context a call of `host` gets.
    pub(crate) fn context(app: &AppHandle<R>, host: &ToolHost) -> ToolCtx {
        let data_dir = crate::app_dirs::data(app).ok();
        let sink = ShellTasks {
            app: app.clone(),
            host: host.clone(),
            data_dir: data_dir.clone(),
        };
        ToolCtx::new(data_dir, Arc::new(sink))
    }

    fn tasks(&self) -> Option<tauri::State<'_, BackgroundTasks>> {
        self.app.try_state::<BackgroundTasks>()
    }
}

/// The collection jobs of tool tasks, by task id: the job ends when the tool reports the task finished.
#[derive(Default)]
/// Each entry keeps the task's kind hint: one task per hint runs at a time (a second diagnostics collection is
/// stopped), while tasks of different tools (a collection and a .NET capture) may run together.
struct CollectionJobs(std::sync::Mutex<std::collections::HashMap<String, CollectionJob>>);

/// A collection job: its id, the sender that ends it, and the task's kind hint.
type CollectionJob = (crate::jobs::JobId, std::sync::mpsc::Sender<()>, String);

impl CollectionJobs {
    fn lock(&self) -> std::sync::MutexGuard<'_, std::collections::HashMap<String, CollectionJob>> {
        crate::sync::lock(&self.0)
    }
}

/// Whether a tool task runs until stopped (a background task) rather than ending by itself (a job).
fn is_service(hint: &str) -> bool {
    matches!(hint, "process-monitor" | "perfmon")
}

impl<R: Runtime> ShellTasks<R> {
    fn stop_task(&self, tool: &str, id: &str) -> anyhow::Result<()> {
        let ctx = ToolCtx::new(self.data_dir.clone(), Arc::new(self.clone()));
        self.host.stop(tool, id, &ctx).map_err(anyhow::Error::from)
    }

    /// Lists a collection as a collection job, or stops it when another of the same kind runs.
    fn track_collection(&self, tool: &str, task: &ToolTask) {
        let Some(jobs) = self.app.try_state::<crate::jobs::Jobs>() else {
            return;
        };
        if self.app.try_state::<CollectionJobs>().is_none() {
            self.app.manage(CollectionJobs::default());
        }
        let Some(registry) = self.app.try_state::<CollectionJobs>() else {
            return;
        };
        if task.kind != CAPTURE_HINT && registry.lock().values().any(|(_, _, hint)| *hint == task.kind) {
            log::warn!(Tool = tool; "A second collection was stopped: one of each kind runs at a time");
            let (sink, tool, id) = (self.clone(), tool.to_string(), task.id.clone());
            // Off the caller's thread: stopping may run a system tool.
            let _ = std::thread::Builder::new().name("debrief-tool-stop".into()).spawn(move || {
                if let Err(e) = sink.stop_task(&tool, &id) {
                    log::warn!(Tool = tool.as_str(); "could not stop the second collection: {e:#}");
                }
            });
            return;
        }
        let (tx, rx) = std::sync::mpsc::channel::<()>();
        let mut spec = crate::jobs::JobSpec::new(job_kind(&task.kind), task.label.clone());
        if !task.stoppable {
            spec = spec.not_cancellable();
        }
        let (sink, t, id) = (self.clone(), tool.to_string(), task.id.clone());
        let controls = crate::jobs::Controls::cancel(move || {
            if let Err(e) = sink.stop_task(&t, &id) {
                log::warn!(Tool = t.as_str(); "could not stop the collection: {e:#}");
            }
        });
        let rx = std::sync::Mutex::new(rx);
        match jobs.submit_work(spec, controls, move |_| {
            // The tool says when it is done (or the sender goes with Debrief).
            let _ = crate::sync::lock(&rx).recv();
            crate::jobs::queue::JobEnd::Done(None)
        }) {
            Ok(job) => {
                registry.lock().insert(task.id.clone(), (job, tx, task.kind.clone()));
            }
            Err(e) => log::warn!(Tool = tool; "collection not listed as a job: {e}"),
        }
    }
}

/// The job kind of a tool task that ends by itself: profiler captures (hint `capture`) run several at once;
/// everything else is a collection.
fn job_kind(hint: &str) -> crate::jobs::JobKind {
    match hint {
        CAPTURE_HINT => crate::jobs::JobKind::Capture,
        _ => crate::jobs::JobKind::Collection,
    }
}

/// The task kind hint of profiler captures.
const CAPTURE_HINT: &str = "capture";

/// The tray icon of a tool's task kind hint.
fn task_kind(hint: &str) -> TaskKind {
    match hint {
        "process-monitor" => TaskKind::ProcessMonitor,
        "perfmon" => TaskKind::Perfmon,
        _ => TaskKind::Other,
    }
}

impl<R: Runtime> TaskSink for ShellTasks<R> {
    fn started(&self, tool: &str, task: &ToolTask) {
        if !is_service(&task.kind) {
            return self.track_collection(tool, task);
        }
        let Some(tasks) = self.tasks() else { return };
        let stop: Option<crate::background::StopFn> = task.stoppable.then(|| {
            let (sink, tool, id) = (self.clone(), tool.to_string(), task.id.clone());
            let stop: crate::background::StopFn = Arc::new(move || {
                let ctx = ToolCtx::new(sink.data_dir.clone(), Arc::new(sink.clone()));
                sink.host.stop(&tool, &id, &ctx).map_err(anyhow::Error::from)
            });
            stop
        });
        let spec = TaskSpec {
            id: task.id.clone(),
            label: task.label.clone(),
            kind: task_kind(&task.kind),
            window: None,
        };
        if let Err(e) = tasks.register(spec, stop) {
            log::warn!(Tool = tool; "could not list background work: {e:#}");
        }
    }

    fn progress(&self, _tool: &str, task: &str, fraction: Option<f32>) {
        let job = self
            .app
            .try_state::<CollectionJobs>()
            .and_then(|r| r.lock().get(task).map(|(id, _, _)| *id));
        match (job, self.app.try_state::<crate::jobs::Jobs>()) {
            (Some(id), Some(jobs)) => jobs.report(
                id,
                crate::jobs::JobProgress {
                    fraction,
                    ..Default::default()
                },
            ),
            _ => {
                if let Some(tasks) = self.tasks() {
                    tasks.set_progress(task, fraction);
                }
            }
        }
    }

    fn finished(&self, _tool: &str, task: &str) {
        if let Some((_, done, _)) = self.app.try_state::<CollectionJobs>().and_then(|r| r.lock().remove(task)) {
            let _ = done.send(());
            return;
        }
        if let Some(tasks) = self.tasks() {
            tasks.remove(task);
        }
    }
}

/// A tool error as the command's error: its kind is the code (missing rights and programs are typed by the
/// tool, see `ToolFailure`); a missing tool says what the user can do.
fn missing(error: ToolError, safe_mode: bool) -> crate::CmdError {
    use crate::{CmdError, ErrorCode};
    match error {
        ToolError::UnknownTool(tool) if safe_mode => CmdError::unavailable(format!(
            "\"{tool}\" is not available in safe mode (plugins are off); restart normally to use it"
        )),
        ToolError::UnknownTool(tool) => CmdError::not_found(format!(
            "no installed plugin provides the tool \"{tool}\" (is the System tools plugin disabled in the Plugins panel?)"
        ))
        .in_outage_of(crate::health::hub::PLUGINS),
        e @ ToolError::UnknownOp { .. } => CmdError::not_found(e.to_string()),
        e @ ToolError::InvalidArgs { .. } => CmdError::invalid(e.to_string()).field("args"),
        e @ ToolError::PathRefused { .. } => {
            CmdError::new(ErrorCode::NotGranted, e.to_string()).hint("Choose the file or folder with the dialog first.")
        }
        ToolError::Unsupported(m) => CmdError::new(ErrorCode::Unsupported, m),
        ToolError::Denied(m) => CmdError::new(ErrorCode::Denied, m).hint("Restart Debrief as administrator, then try again."),
        ToolError::Missing(m) => CmdError::new(ErrorCode::Missing, m),
        ToolError::Failed(m) => CmdError::failed(m),
    }
}

/// Runs `tool`'s `op` for the calling window, off the UI thread.
pub(crate) async fn invoke<R: Runtime>(
    app: &AppHandle<R>,
    window: &CurrentWindow,
    safe_mode: bool,
    tool: &str,
    op: &str,
    args: Value,
) -> CmdResult<Value> {
    if tool.len() > MAX_ID_LEN || op.len() > MAX_ID_LEN {
        return Err("tool and operation names are at most 64 characters".into());
    }
    let host = window.tools();
    // Path arguments must be what this window's user chose (ADR 0016 grants, checked by the tool host).
    let grants = crate::paths::WindowGrants::of(app, window.label());
    let ctx = ShellTasks::context(app, &host).with_paths(Arc::new(grants));
    let (tool, op) = (tool.to_string(), op.to_string());
    tauri::async_runtime::spawn_blocking(move || {
        host.invoke(&tool, &op, args, &ctx).map_err(|e| {
            log_failure(&tool, &op, &e);
            missing(e, safe_mode)
        })
    })
    .await
    .map_err(crate::err)?
}

/// Longest tool error text logged (its tail: an external program's stderr ends with the cause).
const MAX_ERROR_LOG: usize = 1024;

/// The last `max` bytes of `text` (at a character boundary), marked when cut.
fn tail(text: &str, max: usize) -> String {
    if text.len() <= max {
        return text.to_string();
    }
    let mut start = text.len() - max;
    while !text.is_char_boundary(start) {
        start += 1;
    }
    format!("…{}", &text[start..])
}

/// Logs a failed tool operation: bad requests and unavailable tools at Warning, failures of the tool or
/// of the external program it runs (exit code, timeout, stderr) at Error; missing rights or programs at Warning.
/// The text is redacted and bounded.
fn log_failure(tool: &str, op: &str, e: &ToolError) {
    let full = crate::activity::privacy::redact(&e.to_string());
    let timeout = full.contains("did not finish within") || full.contains("timed out");
    let message = tail(&full, MAX_ERROR_LOG);
    let kind = match e {
        ToolError::UnknownTool(_) => "unknown-tool",
        ToolError::UnknownOp { .. } => "unknown-op",
        ToolError::Unsupported(_) => "unsupported",
        ToolError::InvalidArgs { .. } => "invalid-args",
        ToolError::PathRefused { .. } => "path-refused",
        ToolError::Failed(_) => "failed",
        ToolError::Denied(_) => "denied",
        ToolError::Missing(_) => "missing",
    };
    // Missing rights and programs are the user's to fix (warnings); other failures are errors.
    if matches!(e, ToolError::Failed(_)) {
        log::error!(Tool = tool, Op = op, ErrorKind = kind, Timeout = timeout, Error = message.as_str(); "Tool {tool} {op} failed");
    } else {
        log::warn!(Tool = tool, Op = op, ErrorKind = kind, Timeout = timeout, Error = message.as_str(); "Tool {tool} {op} failed");
    }
}

/// Runs one operation of a plugin tool: `{ tool, op, args }`. `args` is
/// validated against the operation's schema (see `tools_list`).
#[tauri::command]
pub async fn tool_invoke<R: Runtime>(
    app: AppHandle<R>,
    window: CurrentWindow,
    state: State<'_, AppState>,
    tool: String,
    op: String,
    args: Option<Value>,
) -> CmdResult<Value> {
    let result = invoke(&app, &window, state.safe_mode, &tool, &op, args.unwrap_or(Value::Null)).await?;
    // What a tool wrote (a collected bundle, an event-log capture folder, a dump) may be opened from this window.
    crate::paths::grant_read_all(&app, window.label(), &tool_outputs(&result), crate::paths::GrantSource::Output);
    Ok(result)
}

/// The files and folders a tool reports it wrote: the top-level `bundle`, `dir`, `path` and `file` of its result and
/// the paths listed in `outputs` (the tool output contract; plugin code, not the webview, names them).
pub(crate) fn tool_outputs(result: &Value) -> Vec<PathBuf> {
    let listed = result
        .get("outputs")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str);
    ["bundle", "dir", "path", "file"]
        .iter()
        .filter_map(|k| result.get(*k).and_then(Value::as_str))
        .chain(listed)
        .filter(|p| crate::paths::parse(p).is_ok())
        .map(PathBuf::from)
        .collect()
}

/// The tools of the calling window's plugins, with their availability
/// (unsupported platform or inactive/quarantined plugin, with the reason).
/// Empty in safe mode.
#[tauri::command]
pub async fn tools_list(window: CurrentWindow) -> Vec<ToolEntry> {
    window.tools().list()
}

/// Whether `tool`'s `op` is declared a pollable status operation.
fn is_poll_op(window: &CurrentWindow, tool: &str, op: &str) -> bool {
    window
        .tools()
        .list()
        .iter()
        .find(|t| t.info.id == tool)
        .is_some_and(|t| t.info.ops.iter().any(|o| o.name == op && o.poll))
}

/// Runs a tool's read-only status operation (declared with `OpSpec::polling`): what a dialog polls while
/// work runs. Quiet in the activity log; any other operation is refused (use `tool_invoke`).
#[tauri::command]
pub async fn tool_poll<R: Runtime>(
    app: AppHandle<R>,
    window: CurrentWindow,
    state: State<'_, AppState>,
    tool: String,
    op: String,
    args: Option<Value>,
) -> CmdResult<Value> {
    if !is_poll_op(&window, &tool, &op) {
        return Err(crate::CmdError::invalid(format!(
            "\"{tool}\" \"{op}\" is not a status operation; call it with tool_invoke"
        )));
    }
    let result = invoke(&app, &window, state.safe_mode, &tool, &op, args.unwrap_or(Value::Null)).await?;
    crate::paths::grant_read_all(&app, window.label(), &tool_outputs(&result), crate::paths::GrantSource::Output);
    Ok(result)
}

/// The job of a running tool task (a capture, a collection), so the UI cancels it with `jobs_cancel`: Jobs
/// are the one cancel authority. `None` when the task has no job (it ended, or runs as a background task).
#[tauri::command]
pub async fn tool_task_job<R: Runtime>(app: AppHandle<R>, task: String) -> CmdResult<Option<u64>> {
    if task.len() > MAX_ID_LEN {
        return Err(crate::CmdError::invalid("task ids are at most 64 characters").field("task"));
    }
    Ok(app
        .try_state::<CollectionJobs>()
        .and_then(|r| r.lock().get(&task).map(|(id, _, _)| id.0)))
}

#[cfg(test)]
pub(crate) mod tests {
    /// The error a command returns for a tool no plugin provides.
    pub(crate) fn missing_tool_error(tool: &str) -> crate::CmdError {
        super::missing(super::ToolError::UnknownTool(tool.to_string()), false)
    }

    use super::*;
    use crate::test_support::{test_app_with_commands, window};
    use serde_json::json;
    use tauri::test::MockRuntime;

    /// Invokes a command through the real IPC path; `Err` carries the rejection.
    pub fn ipc(w: &tauri::WebviewWindow<MockRuntime>, cmd: &str, body: Value) -> Result<Value, Value> {
        use tauri::ipc::{CallbackFn, InvokeBody, InvokeResponseBody};
        use tauri::test::{get_ipc_response, INVOKE_KEY};
        use tauri::webview::InvokeRequest;
        let res = get_ipc_response(
            w,
            InvokeRequest {
                cmd: cmd.into(),
                callback: CallbackFn(0),
                error: CallbackFn(1),
                url: crate::test_support::ipc_url(),
                body: InvokeBody::Json(body),
                headers: Default::default(),
                invoke_key: INVOKE_KEY.to_string(),
            },
        );
        let reply = res.map(|body| match body {
            InvokeResponseBody::Json(s) => serde_json::from_str::<Value>(&s).unwrap(),
            InvokeResponseBody::Raw(_) => Value::Null,
        });
        crate::test_support::settle(w, cmd, reply)
    }

    /// Like [`ipc`], with the UI's operation id in the IPC header.
    pub fn ipc_op(w: &tauri::WebviewWindow<MockRuntime>, cmd: &str, body: Value, op: &str) -> Result<Value, Value> {
        use tauri::ipc::{CallbackFn, InvokeBody, InvokeResponseBody};
        use tauri::test::{get_ipc_response, INVOKE_KEY};
        let mut headers = tauri::http::HeaderMap::new();
        headers.insert(crate::activity::OP_HEADER, op.parse().unwrap());
        let res = get_ipc_response(
            w,
            tauri::webview::InvokeRequest {
                cmd: cmd.into(),
                callback: CallbackFn(0),
                error: CallbackFn(1),
                url: crate::test_support::ipc_url(),
                body: InvokeBody::Json(body),
                headers,
                invoke_key: INVOKE_KEY.to_string(),
            },
        );
        let reply = res.map(|body| match body {
            InvokeResponseBody::Json(s) => serde_json::from_str::<Value>(&s).unwrap(),
            InvokeResponseBody::Raw(_) => Value::Null,
        });
        crate::test_support::settle(w, cmd, reply)
    }

    /// The domain events captured since `test_capture` (needs its guard held).
    pub fn domain_events() -> Vec<crate::activity::Captured> {
        crate::activity::captured()
            .into_iter()
            .filter(|c| c.props.get("Kind").is_some_and(|k| k == "domain"))
            .collect()
    }

    /// The one domain event `event` of operation `op`.
    pub fn domain_event(event: &str, op: &str) -> crate::activity::Captured {
        let all = domain_events();
        all.iter()
            .find(|c| c.props["Operation"] == event && c.props.get("OperationId").is_some_and(|o| o == op))
            .cloned()
            .unwrap_or_else(|| panic!("no {event} for {op} in {all:?}"))
    }

    #[test]
    fn tools_are_listed_and_invoked_through_ipc() {
        let app = test_app_with_commands(None);
        let main = window(&app, "main");
        let all = ipc(&main, "tools_list", json!({})).unwrap();
        // Other built-in plugins contribute tools too (the native profiler); these are the System tools.
        assert!(all.as_array().unwrap().iter().any(|t| t["id"] == "native-profiler"));
        let listed: Vec<Value> = all
            .as_array()
            .unwrap()
            .iter()
            .filter(|t| t["plugin"] == "net.decryptology.tools")
            .cloned()
            .collect();
        let ids: Vec<&str> = listed.iter().map(|t| t["id"].as_str().unwrap()).collect();
        assert_eq!(
            ids,
            [
                "perfmon.templates",
                "perfmon.sets",
                "process-monitor",
                "event-log-follower",
                "diagnostics",
                "elevation"
            ]
        );
        let sets = &listed[1];
        assert_eq!(sets["plugin"], "net.decryptology.tools");
        assert_eq!(sets["needsElevation"], true);
        #[cfg(not(windows))]
        assert_eq!(sets["availability"]["state"], "unsupported");
        assert_eq!(listed[0]["availability"]["state"], "available");

        let presets = ipc(&main, "tool_invoke", json!({ "tool": "perfmon.templates", "op": "presets" })).unwrap();
        assert!(presets.as_array().unwrap().iter().any(|p| p["id"] == "memory"));
        let status = ipc(
            &main,
            "tool_invoke",
            json!({ "tool": "process-monitor", "op": "status", "args": {} }),
        )
        .unwrap();
        assert_eq!(status["running"], false);
        // Schema errors, unknown tools and operations are rejections with a message.
        let bad = ipc(
            &main,
            "tool_invoke",
            json!({ "tool": "perfmon.templates", "op": "generate", "args": { "template": 3 } }),
        );
        assert_eq!(
            bad.unwrap_err()["message"],
            json!("perfmon.templates generate: args.template must be an object, not a number")
        );
        let unknown = ipc(&main, "tool_invoke", json!({ "tool": "nope", "op": "x" })).unwrap_err();
        assert!(
            unknown["message"].as_str().unwrap().contains("is the System tools plugin disabled"),
            "{unknown}"
        );
        let op = ipc(&main, "tool_invoke", json!({ "tool": "elevation", "op": "dance" })).unwrap_err();
        assert!(op["message"].as_str().unwrap().contains("has no operation \"dance\""), "{op}");
        let long = ipc(&main, "tool_invoke", json!({ "tool": "x".repeat(65), "op": "x" })).unwrap_err();
        assert!(long["message"].as_str().unwrap().contains("at most 64"), "{long}");
        #[cfg(not(windows))]
        {
            let e = ipc(
                &main,
                "tool_invoke",
                json!({ "tool": "perfmon.sets", "op": "outputs", "args": { "name": "Debrief" } }),
            )
            .unwrap_err();
            assert!(e["message"].as_str().unwrap().contains("only available on Windows"), "{e}");
        }
    }

