    /// The test form of the answers with a guard of `guard`: the judge never calls the browser stuck, only the guard ends.
    #[cfg(unix)]
    fn judged(guard: Duration) -> Answers {
        Answers::Judged {
            patience: Patience {
                spin: Duration::MAX,
                idle: Duration::MAX,
                hang_guard: Duration::MAX,
                ..Patience::default()
            },
            guard,
        }
