//! `.debriefproj` workspace files: which files are open, which were removed, the
//! profile, and the UI's own state (filters, zoom history, layout, bookmarks,
//! notes...), which the engine stores without interpreting. Debrief writes them for
//! its own sessions (with the store folder to reopen), the activity log and
//! unpacked bundles; projects users save are `.debriefz` archives of their store
//! ([`crate::package`], ADR 0014 §6).
//!
//! Paths inside the project's folder are stored relative to it, so a project
//! folder can be moved or shared with its logs.
//!
//! Version 2 is the only one written; newer files are refused.

use crate::skew::ClockOffsets;
use anyhow::{anyhow, Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::path::{Component, Path, PathBuf};

/// Current project format version. Newer files are refused.
pub const PROJECT_VERSION: u32 = 2;

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ProjectFile {
    pub version: u32,
    pub name: String,
    /// Opened files and folders.
    pub sources: Vec<String>,
    /// Files removed from the workspace (kept out of folder scans).
    #[serde(default)]
    pub removed: Vec<String>,
    /// The profile, as TOML.
    pub profile: String,
    /// UI state, opaque to the engine.
    #[serde(default)]
    pub ui: Value,
    /// Clock-skew offsets (ms) by source path.
    #[serde(default, skip_serializing_if = "ClockOffsets::is_empty")]
    pub clock: ClockOffsets,
    /// The store folder holding these files' events (an autosaved session): reopened instead of importing
    /// the files again when it is still there.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub store: Option<String>,
    /// Incident reports; one that cannot be read is skipped, not fatal.
    #[serde(
        default,
        skip_serializing_if = "Vec::is_empty",
        deserialize_with = "crate::report::tolerant_reports"
    )]
    pub reports: Vec<crate::report::Report>,
}

impl ProjectFile {
    /// Writes the project; absolute paths under the project's folder become relative.
    pub fn save(&self, path: &Path) -> Result<()> {
        let base = base_dir(path)?;
        let mut stored = self.clone();
        stored.version = PROJECT_VERSION;
        stored.sources = self.sources.iter().map(|p| relativize(&base, p)).collect();
        stored.removed = self.removed.iter().map(|p| relativize(&base, p)).collect();
        stored.clock = self.clock.map_keys(|p| relativize(&base, p));
        let json = serde_json::to_string_pretty(&stored)?;
        std::fs::write(path, json).with_context(|| format!("cannot write {}", path.display()))
    }

    /// Reads a project and resolves its paths against the project's folder.
    pub fn load(path: &Path) -> Result<ProjectFile> {
        let text = std::fs::read_to_string(path).with_context(|| format!("cannot read {}", path.display()))?;
        let mut p: ProjectFile = serde_json::from_str(&text).with_context(|| format!("{} is not a Debrief project", path.display()))?;
        if p.version > PROJECT_VERSION {
            return Err(anyhow!(
                "this project was saved by a newer Debrief (format {}); please update Debrief",
                p.version
            ));
        }
        let base = base_dir(path)?;
        p.sources = p.sources.iter().map(|s| resolve(&base, s)).collect();
        p.removed = p.removed.iter().map(|s| resolve(&base, s)).collect();
        p.clock = p.clock.map_keys(|s| resolve(&base, s)).sanitized();
        Ok(p)
    }
}

fn base_dir(project: &Path) -> Result<PathBuf> {
    let parent = project.parent().filter(|p| !p.as_os_str().is_empty()).unwrap_or(Path::new("."));
    std::fs::canonicalize(parent).with_context(|| format!("folder of {} does not exist", project.display()))
}

/// Archive entries ("x.zip!/a.log") keep their entry suffix untouched.
fn split_entry(p: &str) -> (&str, Option<&str>) {
    match p.split_once(crate::archive::ENTRY_SEPARATOR) {
        Some((f, e)) => (f, Some(e)),
        None => (p, None),
    }
}

fn join_entry(file: String, entry: Option<&str>) -> String {
    match entry {
        Some(e) => format!("{file}{}{e}", crate::archive::ENTRY_SEPARATOR),
        None => file,
    }
}

fn relativize(base: &Path, p: &str) -> String {
    let (file, entry) = split_entry(p);
    let rel = Path::new(file).strip_prefix(base).ok().map(|r| {
        if r.as_os_str().is_empty() {
            ".".to_string()
        } else {
            r.to_string_lossy().replace('\\', "/")
        }
    });
    join_entry(rel.unwrap_or_else(|| file.to_string()), entry)
}

fn resolve(base: &Path, p: &str) -> String {
    let (file, entry) = split_entry(p);
    let path = Path::new(file);
    let abs = if path.is_absolute() {
        path.to_path_buf()
    } else {
        normalize(&base.join(path))
    };
    join_entry(abs.to_string_lossy().into_owned(), entry)
}

/// Removes `.` and `..` without touching the file system.
fn normalize(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn round_trips_with_relative_paths() {
        let dir_scratch = tempfile::tempdir().unwrap();
        let dir = dir_scratch.path().join(format!("debrief-project-{}", std::process::id()));
        std::fs::create_dir_all(dir.join("logs")).unwrap();
        let dir = std::fs::canonicalize(dir).unwrap();
        let file = dir.join("incident.debriefproj");
        let elsewhere = if cfg!(windows) { "C:\\other\\x.log" } else { "/other/x.log" };
        let p = ProjectFile {
            version: 0,
            name: "Incident".into(),
            sources: vec![
                dir.join("logs").to_string_lossy().into_owned(),
                dir.to_string_lossy().into_owned(),
                elsewhere.into(),
                format!("{}!/web01/app.log", dir.join("logs/bundle.zip").display()),
            ],
            removed: vec![dir.join("logs/old.log").to_string_lossy().into_owned()],
            profile: "name = 'P'".into(),
            ui: json!({ "query": { "text": "timeout" } }),
            clock: serde_json::from_value(json!({ dir.join("logs/a.log").to_string_lossy(): 2350, elsewhere: -100 })).unwrap(),
            store: None,
            reports: vec![],
        };
        p.save(&file).unwrap();
        let stored: Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
        assert_eq!(stored["version"], PROJECT_VERSION);
        assert_eq!(stored["sources"], json!(["logs", ".", elsewhere, "logs/bundle.zip!/web01/app.log"]));
        assert_eq!(stored["removed"], json!(["logs/old.log"]));
        assert_eq!(stored["clock"], json!({ "logs/a.log": 2350, elsewhere: -100 }));

        let back = ProjectFile::load(&file).unwrap();
        assert_eq!(back.sources[0], dir.join("logs").to_string_lossy());
        assert_eq!(back.sources[1], dir.to_string_lossy());
        assert_eq!(back.sources[2], elsewhere);
        assert!(back.sources[3].ends_with("bundle.zip!/web01/app.log"));
        assert_eq!(back.ui["query"]["text"], "timeout");
        assert_eq!(back.clock, p.clock);
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn drops_bad_offsets() {
        let dir_scratch = tempfile::tempdir().unwrap();
        let dir = dir_scratch.path().join(format!("debrief-project-offsets-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let v2 = dir.join("v2.debriefproj");
        std::fs::write(
            &v2,
            r#"{"version": 2, "name": "x", "sources": [], "profile": "", "clock": {"a.log": 5, "b.log": 99999999999999}}"#,
        )
        .unwrap();
        let p = ProjectFile::load(&v2).unwrap();
        let base = std::fs::canonicalize(&dir).unwrap();
        assert_eq!(p.clock.iter().count(), 1);
        assert_eq!(p.clock.get(&base.join("a.log").to_string_lossy()), 5);
        // Saving without offsets leaves the key out.
        ProjectFile::default().save(&v2).unwrap();
        assert!(!std::fs::read_to_string(&v2).unwrap().contains("clock"));
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn rejects_newer_and_invalid_files() {
        let dir_scratch = tempfile::tempdir().unwrap();
        let dir = dir_scratch.path().join(format!("debrief-project-bad-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let newer = dir.join("newer.debriefproj");
        std::fs::write(&newer, r#"{"version": 99, "name": "x", "sources": [], "profile": ""}"#).unwrap();
        assert!(ProjectFile::load(&newer).unwrap_err().to_string().contains("newer Debrief"));
        let junk = dir.join("junk.debriefproj");
        std::fs::write(&junk, "not json").unwrap();
        assert!(ProjectFile::load(&junk).unwrap_err().to_string().contains("not a Debrief project"));
        assert!(ProjectFile::load(&dir.join("missing.debriefproj")).is_err());
        let p = ProjectFile {
            version: 1,
            name: "x".into(),
            sources: vec![],
            removed: vec![],
            profile: String::new(),
            ui: Value::Null,
            clock: ClockOffsets::default(),
            store: None,
            reports: vec![],
        };
        assert!(p.save(&dir.join("no/such/dir/x.debriefproj")).is_err());
        std::fs::remove_dir_all(&dir).unwrap();
        assert_eq!(normalize(Path::new("/a/./b/../c")), PathBuf::from("/a/c"));
        assert_eq!(normalize(Path::new("./a/../b")), PathBuf::from("b"));
        assert!(base_dir(Path::new("relative.debriefproj")).is_ok());
    }
}

use super::*;
use crate::condition::{CondValue, ConditionCfg};
use crate::model::{Level, Record};
use crate::pipeline::StepCfg;
use crate::profile::{ExtractCfg, MarkerCfg};
use crate::{Profile, Workspace, DEFAULT_PROFILE_TOML};
use serde_json::json;
use std::collections::BTreeMap;

fn ev(i: usize, ts: i64, level: Level, msg: &str, fields: serde_json::Value) -> Sample {
    let mut rec = Record::new(i as u32 + 1);
    rec.id = i as u32;
    rec.ts = Some(ts);
    rec.level = level;
    rec.message = msg.into();
    if let serde_json::Value::Object(m) = fields {
        rec.fields = m;
    }
    Sample {
        rec,
        source_name: "app.log".into(),
        markers: vec![],
        lane: "app.log".into(),
        group: 0,
    }
}

fn info(i: usize, msg: &str, fields: serde_json::Value) -> Sample {
    ev(i, 1_000 * i as i64, Level::Information, msg, fields)
}

// ---- instance key ----

#[test]
fn the_machine_beats_categories_ids_and_single_values() {
    let mut events = Vec::new();
    for i in 0..200 {
        events.push(info(
            i,
            "Handled",
            json!({
                "MachineName": format!("WEB0{}", i % 3),
                "SourceContext": format!("Ctx{}", i % 5),
                "RequestId": format!("r{i}"),
                "Environment": "Production",
                "ProcessId": 1000 + (i % 6),
            }),
        ));
    }
    let fields = field_summaries(&events);
    let c = instance_candidates(&events, &fields, &[]);
    assert_eq!(c[0].field, "MachineName");
    assert_eq!(c[0].lanes, 3);
    // A category (SourceContext), unique ids and a constant are never keys.
    assert!(c
        .iter()
        .all(|c| !["SourceContext", "RequestId", "Environment"].contains(&c.field.as_str())));
    // A process id is a key candidate (by its name), below the machine.
    assert!(c.iter().any(|c| c.field == "ProcessId"));
}

#[test]
fn too_many_lanes_or_too_little_coverage_is_no_key() {
    let events: Vec<Sample> = (0..300)
        .map(|i| {
            info(
                i,
                "x",
                if i < 50 {
                    json!({"Host": format!("h{}", i % 2)})
                } else {
                    json!({"Node": format!("n{i}")})
                },
            )
        })
        .collect();
    let fields = field_summaries(&events);
    assert!(instance_candidates(&events, &fields, &[]).is_empty());
}

#[test]
fn an_instance_named_in_the_messages_is_extracted() {
    let events: Vec<Sample> = (0..100)
        .map(|i| info(i, &format!("worker-{} picked up job {i}", i % 4), json!({})))
        .collect();
    let fields = field_summaries(&events);
    let c = instance_candidates(&events, &fields, &[]);
    let w = c.iter().find(|c| c.field == "Worker").expect("a worker key");
    assert_eq!(w.lanes, 4);
    let KeyOrigin::Message { regex } = &w.origin else {
        panic!("{:?}", w.origin)
    };
    let re = regex::Regex::new(regex).unwrap();
    assert_eq!(&re.captures("worker-3 picked up").unwrap()["Worker"], "3");
}

#[test]
fn field_kinds_and_ranges() {
    let events = vec![
        info(0, "a", json!({"n": 1, "b": true, "t": "x", "m": 1})),
        info(1, "b", json!({"n": 5, "b": false, "t": "y", "m": "z"})),
    ];
    let f = field_summaries(&events);
    let get = |n: &str| f.iter().find(|x| x.name == n).unwrap();
    assert_eq!(get("n").kind, FieldKind::Number);
    assert_eq!((get("n").min, get("n").max), (Some(1.0), Some(5.0)));
    assert_eq!(get("b").kind, FieldKind::Bool);
    assert_eq!(get("t").kind, FieldKind::Text);
    assert_eq!(get("m").kind, FieldKind::Mixed);
    assert_eq!(get("t").coverage, 1.0);
}

