//! The one child loop (ADR 0017 §2, §5): a child process' `main` calls [`child_main`], which
//!
//! 1. reads its [`Bootstrap`] (one JSON line on stdin, or the file `--debrief-bootstrap <file>` names for an elevated
//!    child, which has no stdin pipe);
//! 2. connects to the host and authenticates;
//! 3. locks itself down ([`crate::sandbox::lockdown`]) before it handles anything;
//! 4. answers the host's calls with its handler until the connection closes, then returns (the process exits).
//!
//! A child also ends when its stdin closes (the host died); nothing is left behind. It ends through **one** exit: the
//! [`lifeline`] closes the connection, `main` returns and is the only `exit` (Rust guards two `exit`s only on Linux; on
//! macOS two threads ran the `atexit` handlers and DuckDB's static destructors together, and the store worker crashed).

use crate::elevation::{take_bootstrap, BOOTSTRAP_FLAG};
use crate::frame::ProtocolVersion;
use crate::launch::Bootstrap;
use crate::link::Token;
use crate::peer::{Handler, Peer, PeerOptions};
use std::io::{self, BufRead, Read};
use std::sync::{Arc, Condvar, Mutex};
use std::time::Duration;

/// What a child's exit phase may take once its host is gone or stops it: the child's own stop budget. The parent waits at
/// least this plus [`STOP_MARGIN`] before it kills the child (`process::KILL_GRACE`), so a child that stops within its
/// budget is never killed in the middle of it.
pub const STOP_BUDGET: Duration = Duration::from_millis(1250);

/// Covers the parent's kill and reap, and a child's last log lines, on top of [`STOP_BUDGET`].
pub const STOP_MARGIN: Duration = Duration::from_millis(250);

/// Who ends the process: the child's `main` (past the connection) or, after a bound, the lifeline. One claim wins, under
/// one lock, so the two never both run an exit.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Exit {
    Serving,
    MainExiting,
    LifelineExiting,
}

struct Phase {
    state: Mutex<Exit>,
    wake: Condvar,
}

static PHASE: Phase = Phase {
    state: Mutex::new(Exit::Serving),
    wake: Condvar::new(),
};

impl Phase {
    #[cfg(test)]
    fn new() -> Phase {
        Phase {
            state: Mutex::new(Exit::Serving),
            wake: Condvar::new(),
        }
    }

    /// `main` claims the exit; false when the lifeline claimed it first (this `main` must then park: the lifeline ends the
    /// process).
    fn claim_main(&self) -> bool {
        let mut st = self.state.lock().unwrap_or_else(|p| p.into_inner());
        if *st == Exit::LifelineExiting {
            return false;
        }
        *st = Exit::MainExiting;
        self.wake.notify_all();
        true
    }

    /// Waits at most `max` for `main` to claim the exit; if it has not by then, the lifeline claims it and this says true.
    fn claim_fallback(&self, max: Duration) -> bool {
        let g = self.state.lock().unwrap_or_else(|p| p.into_inner());
        let mut g = self
            .wake
            .wait_timeout_while(g, max, |st| *st == Exit::Serving)
            .map(|(g, _)| g)
            .unwrap_or_else(|p| p.into_inner().0);
        if *g == Exit::Serving {
            *g = Exit::LifelineExiting;
            return true;
        }
        false
    }
}

/// Says that this child's exit phase has begun: its `main` is past the connection and ends the process itself. A child
/// whose `main` calls [`child_main`] never calls this (it does); one that serves by [`connect_speaking`] and
/// [`lifeline_closing`] calls it when its own `wait_closed` returns. If the lifeline's fallback already took the exit
/// (a `main` that was too late), this waits at most [`STOP_MARGIN`] for the lifeline to end the process, then ends it itself.
pub fn exit_phase_begun() {
    begin_exit(&PHASE, STOP_MARGIN, || end_without_destructors(0));
}

/// `main`'s claim on `phase`; when the lifeline's fallback holds it, see [`main_lost_claim`].
fn begin_exit(phase: &Phase, wait: Duration, end: impl FnOnce()) {
    if !phase.claim_main() {
        main_lost_claim(wait, end);
    }
}

/// A `main` that finds the lifeline's fallback already took the exit: waits at most `wait` for the lifeline to end the
/// process, then calls `end` itself (never parks for good: the lifeline may have died, and this `main` holds what the child
/// holds).
fn main_lost_claim(wait: Duration, end: impl FnOnce()) {
    std::thread::park_timeout(wait);
    end();
}

/// Largest bootstrap line read from stdin.
const MAX_BOOTSTRAP: u64 = 64 * 1024;

/// Reads the bootstrap line from `input`.
pub fn read_bootstrap(input: impl Read) -> io::Result<Bootstrap> {
    let mut line = String::new();
    io::BufReader::new(input.take(MAX_BOOTSTRAP)).read_line(&mut line)?;
    serde_json::from_str(line.trim()).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("bad bootstrap: {e}")))
}

/// Where the bootstrap comes from: `--debrief-bootstrap <file>` among `args` (an elevated child), else stdin.
pub fn bootstrap_file(args: &[String]) -> Option<std::path::PathBuf> {
    args.iter()
        .position(|a| a == BOOTSTRAP_FLAG)
        .and_then(|i| args.get(i + 1))
        .map(std::path::PathBuf::from)
}

/// A child process' `main`; see the module docs. `label` names the host in messages ("Debrief"); `make` builds the
/// handler once the bootstrap is known (it may look at [`Bootstrap::role`]).
pub fn child_main(label: &str, make: impl FnOnce(&Bootstrap) -> Arc<dyn Handler>) -> io::Result<()> {
    child_main_speaking(label, ProtocolVersion::UNVERSIONED, make)
}

/// [`child_main`] for a child that speaks a versioned protocol (a plugin): `protocol` is sent in the handshake, and
/// a host that cannot serve it refuses the connection with a message saying which side to update.
pub fn child_main_speaking(label: &str, protocol: ProtocolVersion, make: impl FnOnce(&Bootstrap) -> Arc<dyn Handler>) -> io::Result<()> {
    child_main_then(label, protocol, make, |_, _| {})
}

/// [`child_main_speaking`] that runs `connected` once the connection is up and the child is locked down (e.g. to
/// start forwarding the child's own standard error over the connection).
pub fn child_main_then(
    label: &str,
    protocol: ProtocolVersion,
    make: impl FnOnce(&Bootstrap) -> Arc<dyn Handler>,
    connected: impl FnOnce(&Bootstrap, &Peer),
) -> io::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let elevated = bootstrap_file(&args);
    let bootstrap = match &elevated {
        Some(file) => take_bootstrap(file)?,
        None => read_bootstrap(io::stdin().lock())?,
    };
    let peer = connect_speaking(&bootstrap, elevated.is_some(), label, protocol, make)?;
    connected(&bootstrap, &peer);
    if elevated.is_none() {
        // Started after the lockdown, like every thread of a child (see `connect_and_lock_down`).
        lifeline_closing(&peer);
    }
    peer.wait_closed(None);
    exit_phase_begun();
    Ok(())
}

/// The lifeline of a child that has no connection yet (or none to close): when the host closes stdin (or dies), exit at
/// once. Once the peer is up use [`lifeline_closing`]: two threads in `exit` crashed the store worker.
pub fn lifeline() {
    std::thread::spawn(|| {
        wait_stdin_closed(io::stdin());
        // `exit` runs no destructors: remove the endpoints of children this process was still starting.
        crate::endpoint::remove_live();
        std::process::exit(0);
    });
}

/// The lifeline of a child whose connection is up: when the host closes stdin (or dies) it **closes the connection**, so
/// the child's `main` (past `wait_closed`) is the only exit. If the exit phase has not begun within
/// [`STOP_BUDGET`] plus [`STOP_MARGIN`] (a `main` that hangs would keep the store's database lock), it ends the
/// process itself. Call [`exit_phase_begun`] from a `main` that does not go through [`child_main`].
pub fn lifeline_closing(peer: &Peer) {
    let peer = peer.clone();
    std::thread::spawn(move || {
        wait_stdin_closed(io::stdin());
        let end = || end_without_destructors(0);
        lifeline_end(&peer, &PHASE, LIFELINE_WAIT, &mut io::stderr(), end);
    });
}

/// Ends this process at once without running `atexit` handlers or static destructors (`_exit`, `TerminateProcess` on
/// itself): for a child whose exit phase overran, where running the C++ static destructors under a thread still inside
/// native code is what crashed the store worker. Stdio is not flushed: the caller logs first.
#[cfg(unix)]
#[rustfmt::skip]
pub fn end_without_destructors(code: i32) -> ! { /* SAFETY: `_exit` takes no pointers and never returns. */ unsafe { libc::_exit(code) } }

/// [`end_without_destructors`] on Windows (`TerminateProcess` on this process).
#[cfg(windows)]
pub fn end_without_destructors(code: i32) -> ! {
    use windows::Win32::System::Threading::{GetCurrentProcess, TerminateProcess};
    // SAFETY: the pseudo-handle of this process; `TerminateProcess` notifies no DLL, so no detach code can wait on a
    // thread that was cut short.
    unsafe {
        // conformance: pid-kill — this process itself (`GetCurrentProcess`), not a pid read earlier
        let _ = TerminateProcess(GetCurrentProcess(), code as u32);
    }
    std::process::abort()
}

fn wait_stdin_closed(mut stdin: impl Read) {
    let mut sink = [0u8; 256];
    while matches!(stdin.read(&mut sink), Ok(n) if n > 0) {}
}

/// What the lifeline does once stdin is closed: close `peer`, wait for `main` to claim the exit, and if it does not within
/// the child's stop budget plus margin, say so on `err` and `end` the process.
fn lifeline_end(peer: &Peer, phase: &Phase, wait: Duration, err: &mut dyn io::Write, end: impl FnOnce()) {
    close_then_end(peer, phase, wait, || end_after_fallback(err, end));
}

/// The last steps of the lifeline's fallback: say why and remove the endpoints of children this process was still starting
/// (`exit` runs no destructors), then `end`. Nothing before `end` may stop it: a broken stderr (the host is gone) or a
/// writer that panics must not keep the process alive, holding what the child holds (the store's database lock).
fn end_after_fallback(err: &mut dyn std::io::Write, end: impl FnOnce()) {
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _ = writeln!(
            err,
            "the exit phase did not begin within {} ms of the host going away; ending the process (exit code 0)",
            (STOP_BUDGET + STOP_MARGIN).as_millis()
        );
        crate::endpoint::remove_live();
    }));
    end();
}

/// How long the lifeline waits for `main` to claim the exit after the host went away.
const LIFELINE_WAIT: Duration = STOP_BUDGET.saturating_add(STOP_MARGIN);

/// Closes `peer`, then waits at most `wait` for `phase` to begin; `fallback` runs when it does not.
fn close_then_end(peer: &Peer, phase: &Phase, wait: Duration, fallback: impl FnOnce()) {
    // Endpoints of children this process was still starting: `main`'s exit runs no destructors for them either.
    crate::endpoint::remove_live();
    peer.close();
    if phase.claim_fallback(wait) {
        fallback();
    }
}

/// Steps 2–4 of [`child_main`]: connect, lock down, serve. Returns the running peer.
pub fn connect_and_lock_down(
    bootstrap: &Bootstrap,
    elevated: bool,
    label: &str,
    make: impl FnOnce(&Bootstrap) -> Arc<dyn Handler>,
) -> io::Result<Peer> {
    connect_speaking(bootstrap, elevated, label, ProtocolVersion::UNVERSIONED, make)
}

/// [`connect_and_lock_down`] for a child that speaks `protocol`.
pub fn connect_speaking(
    bootstrap: &Bootstrap,
    elevated: bool,
    label: &str,
    protocol: ProtocolVersion,
    make: impl FnOnce(&Bootstrap) -> Arc<dyn Handler>,
) -> io::Result<Peer> {
    let token =
        Token::from_hex(&bootstrap.token).ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "bad token in the bootstrap"))?;
    let stream = handshake_then_lock_down(bootstrap, &token, elevated, label, protocol)?;
    let handler = make(bootstrap);
    let mut opts = PeerOptions::new(label);
    opts.max_frame = bootstrap.max_frame;
    let rt = crate::runtime::shared().map_err(io::Error::other)?;
    Ok(Peer::start(stream, handler, opts, rt.handle()))
}

/// Unix: landlock restricts only the thread that locks down and the threads it starts afterwards, so the IPC
/// runtime's threads (which run the handler) must start after the lockdown. The handshake runs on a short-lived
/// thread of its own, with a single-threaded runtime, and is over before the lockdown; the stream then moves to
/// the shared runtime.
#[cfg(unix)]
fn handshake_then_lock_down(
    bootstrap: &Bootstrap,
    token: &Token,
    elevated: bool,
    label: &str,
    protocol: ProtocolVersion,
) -> io::Result<Box<dyn crate::peer::Duplex>> {
    let (stream, tid) = std::thread::scope(|s| {
        s.spawn(|| -> io::Result<(std::os::unix::net::UnixStream, u32)> {
            let tid = current_tid();
            let rt = tokio::runtime::Builder::new_current_thread().enable_all().build()?;
            let stream = rt
                .block_on(crate::link::platform_handshake(&bootstrap.address, token, label, protocol))
                .map_err(|e| io::Error::other(e.to_string()))?;
            Ok((stream.into_std()?, tid))
        })
        .join()
        .map_err(|_| io::Error::other("the handshake thread panicked"))?
    })?;
    // `join` returns when the thread's user code is over, but the kernel lists its task until it is torn down: landlock's
    // count of threads that predate the lockdown would take that exiting task for a thread that escapes it.
    // A task that outlives the bound is a thread that really runs on: the lockdown then reports it, as it should.
    wait_task_gone(tid, TASK_GONE_BOUND);
    lock_down(bootstrap, elevated)?;
    // `from_std` registers with the reactor of the runtime entered: the shared one, started now.
    let _g = crate::runtime::shared().map_err(io::Error::other)?.enter();
    Ok(Box::new(tokio::net::UnixStream::from_std(stream)?))
}

/// How long to wait for a joined thread's task to leave the kernel's list; it is gone within microseconds, the bound
/// only keeps a broken `/proc` from stalling the child.
#[cfg(unix)]
const TASK_GONE_BOUND: Duration = Duration::from_secs(2);

/// The kernel's id of the calling thread (the name its task has in `/proc/self/task`); 0 where there is none.
#[cfg(unix)]
fn current_tid() -> u32 {
    #[cfg(target_os = "linux")]
    {
        // SAFETY: `gettid` takes no arguments and cannot fail.
        u32::try_from(unsafe { libc::syscall(libc::SYS_gettid) }).unwrap_or(0)
    }
    #[cfg(not(target_os = "linux"))]
    {
        0
    }
}

/// Waits (at most `bound`) until thread `tid` of this process has left `/proc/self/task`; true when it has. Nothing to
/// wait for (true) where there is no such directory or for tid 0. Giving up is logged on stderr, the child's log.
#[cfg(unix)]
fn wait_task_gone(tid: u32, bound: Duration) -> bool {
    if tid == 0 {
        return true;
    }
    let path = std::path::PathBuf::from(format!("/proc/self/task/{tid}"));
    let started = std::time::Instant::now();
    let gone = wait_until(|| !path.exists(), bound);
    if !gone {
        eprintln!(
            "the handshake thread {tid} was still listed after {} ms: the lockdown will count it as a thread that escapes it",
            started.elapsed().as_millis()
        );
    }
    gone
}

/// Polls `done` until it is true or `bound` has passed; true when it was met. The wait is on the condition: a short
/// pause between looks only spares the CPU, it never decides the outcome.
#[cfg(unix)]
fn wait_until(mut done: impl FnMut() -> bool, bound: Duration) -> bool {
    let end = std::time::Instant::now() + bound;
    let mut looks = 0u32;
    loop {
        if done() {
            return true;
        }
        if std::time::Instant::now() >= end {
            return false;
        }
        looks += 1;
        if looks <= 64 {
            std::thread::yield_now();
        } else {
            std::thread::sleep(Duration::from_micros(200));
        }
    }
}

/// Windows: the lowered integrity level and the job hold for every thread of the process.
#[cfg(not(unix))]
fn handshake_then_lock_down(
    bootstrap: &Bootstrap,
    token: &Token,
    elevated: bool,
    label: &str,
    protocol: ProtocolVersion,
) -> io::Result<Box<dyn crate::peer::Duplex>> {
    let (address, token, label_owned) = (bootstrap.address.clone(), token.clone(), label.to_string());
    let stream = crate::runtime::run(async move { crate::link::handshake_speaking(&address, &token, &label_owned, protocol).await })
        .map_err(io::Error::other)?
        .map_err(|e| io::Error::other(e.to_string()))?;
    lock_down(bootstrap, elevated)?;
    Ok(stream)
}

/// Nothing has been read from the host yet but the handshake: lock down before the first request.
fn lock_down(bootstrap: &Bootstrap, elevated: bool) -> io::Result<()> {
    let notes = crate::sandbox::lockdown(&bootstrap.sandbox, elevated).map_err(|e| io::Error::other(format!("cannot lock down: {e}")))?;
    // On stderr, so the child's log has them (a gap as a Warning): never less sandboxed without saying so.
    for n in notes {
        eprintln!("{}", n.log_line());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn a_peer() -> Peer {
        let (x, _y) = tokio::io::duplex(1 << 16);
        let rt = crate::runtime::shared().unwrap();
        Peer::start(x, Arc::new(crate::peer::NoCalls), PeerOptions::new("test"), rt.handle())
    }

    #[test]
    fn the_lifeline_closes_the_peer_and_leaves_the_exit_to_main_once_the_phase_begins() {
        let peer = a_peer();
        let phase = Arc::new(Phase::new());
        let t = {
            let (peer, phase) = (peer.clone(), phase.clone());
            std::thread::spawn(move || {
                let mut said = Vec::new();
                lifeline_end(&peer, &phase, LIFELINE_WAIT, &mut said, || panic!("took"));
                said
            })
        };
        // `main` sees the connection close and begins the phase.
        assert!(peer.wait_closed(Some(Duration::from_secs(30))));
        assert!(phase.claim_main());
        assert!(t.join().unwrap().is_empty(), "the lifeline left the exit to main and said nothing");
    }

    #[test]
    fn the_lifeline_says_why_and_ends_when_main_never_claims_the_exit() {
        let peer = a_peer();
        let (mut said, mut ended) = (Vec::new(), false);
        let wait = Duration::from_millis(30);
        lifeline_end(&peer, &Phase::new(), wait, &mut said, || ended = true);
        assert!(ended && String::from_utf8(said).unwrap().contains("did not begin"));
    }

    #[test]
    fn a_main_that_lost_the_claim_goes_through_begin_exit() {
        let phase = Phase::new();
        assert!(phase.claim_fallback(Duration::ZERO));
        let mut ended = false;
        begin_exit(&phase, Duration::from_millis(30), || ended = true);
        assert!(ended, "a main that lost the claim ends the process itself");
        let mut kept = false;
        begin_exit(&Phase::new(), Duration::from_millis(30), || kept = true);
        assert!(!kept, "a main that wins the claim does not");
    }

    struct Broken;
    impl io::Write for Broken {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            Err(io::ErrorKind::BrokenPipe.into())
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    struct Panicking;
    impl io::Write for Panicking {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            panic!("a writer that panics")
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    #[test]
    fn the_fallback_ends_the_process_whatever_its_message_does() {
        let mut said = Vec::new();
        let mut ended = 0;
        end_after_fallback(&mut said, || ended += 1);
        assert_eq!((ended, String::from_utf8(said).unwrap().contains("did not begin")), (1, true));
        // The host is gone: a broken pipe, and a writer that panics, still end it.
        end_after_fallback(&mut Broken, || ended += 1);
        end_after_fallback(&mut Panicking, || ended += 1);
        assert_eq!(ended, 3);
        io::Write::flush(&mut Broken).unwrap();
        io::Write::flush(&mut Panicking).unwrap();
    }

    #[test]
    fn a_main_that_lost_the_claim_ends_the_process_within_the_bound() {
        // On a thread, so a `main` that parked for good fails this test instead of hanging it.
        let (done, ended) = std::sync::mpsc::channel();
        std::thread::spawn(move || main_lost_claim(Duration::from_millis(30), || done.send(()).unwrap()));
        assert!(
            ended.recv_timeout(paddock_testkit::HANG_GUARD).is_ok(),
            "the late main did not end the process"
        );
    }

    #[test]
    fn the_lifeline_ends_the_process_itself_when_the_phase_never_begins() {
        let peer = a_peer();
        let phase = Phase::new();
        let mut ended = false;
        close_then_end(&peer, &phase, Duration::from_millis(50), || ended = true);
        assert!(peer.is_closed(), "it closed the peer first");
        assert!(ended, "after the bound it falls back to ending the process");
        // A `main` that comes late finds the exit taken: it must park, never run a second exit.
        assert!(!phase.claim_main(), "the lifeline owns the exit now");
    }

    #[cfg(unix)]
    #[test]
    fn wait_until_meets_its_condition_or_gives_up_at_the_bound() {
        let mut looks = 0;
        assert!(wait_until(
            || {
                looks += 1;
                looks == 3
            },
            Duration::from_secs(30)
        ));
        assert_eq!(looks, 3);
        assert!(!wait_until(|| false, Duration::from_millis(20)));
        // A tid that never existed, or none at all, is already gone.
        assert!(wait_task_gone(0, Duration::from_secs(30)));
        assert!(wait_task_gone(u32::MAX, Duration::from_secs(30)));
    }

    /// A thread that is still running stays listed: the wait gives up at the bound and says so.
    #[cfg(target_os = "linux")]
    #[test]
    fn a_live_thread_is_not_waited_for_beyond_the_bound() {
        let (tid_tx, tid_rx) = std::sync::mpsc::channel();
        let (stop_tx, stop_rx) = std::sync::mpsc::channel::<()>();
        let t = std::thread::spawn(move || {
            tid_tx.send(current_tid()).unwrap();
            let _ = stop_rx.recv();
        });
        let tid = tid_rx.recv().unwrap();
        assert!(!wait_task_gone(tid, Duration::from_millis(20)));
        stop_tx.send(()).unwrap();
        t.join().unwrap();
    }

    /// The race behind a lockdown that reported "1 thread(s) started before the lockdown": a joined thread still
    /// listed in `/proc/self/task` (about one run in five on a loaded Linux machine).
    #[cfg(target_os = "linux")]
    #[test]
    fn a_joined_thread_leaves_the_task_list_once_waited_for() {
        for i in 0..300 {
            let tid = std::thread::spawn(current_tid).join().unwrap();
            assert_ne!(tid, 0);
            assert!(wait_task_gone(tid, TASK_GONE_BOUND));
            assert!(
                !std::path::Path::new(&format!("/proc/self/task/{tid}")).exists(),
                "round {i}: thread {tid} is still listed"
            );
        }
    }

    #[test]
    fn the_bootstrap_comes_from_stdin_or_a_named_file() {
        let b = Bootstrap {
            address: "a".into(),
            token: "t".into(),
            sandbox: Default::default(),
            max_frame: 1024,
            role: String::new(),
        };
        let line = format!("{}\nrest", serde_json::to_string(&b).unwrap());
        assert_eq!(read_bootstrap(line.as_bytes()).unwrap(), b);
        assert_eq!(read_bootstrap(&b"nope\n"[..]).unwrap_err().kind(), io::ErrorKind::InvalidData);
        let long = format!("{{\"address\":\"{}\"}}\n", "a".repeat(70_000));
        assert!(read_bootstrap(long.as_bytes()).is_err());
        let args: Vec<String> = ["x", "--plugin", "p", BOOTSTRAP_FLAG, "/tmp/b.json"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(bootstrap_file(&args), Some("/tmp/b.json".into()));
        assert_eq!(bootstrap_file(&args[..4]), None);
        assert_eq!(bootstrap_file(&[]), None);
    }
}

//! Windows: starting a child inside an AppContainer ([`crate::sandbox::Containment::Launcher`], ADR 0027), so a
//! binary Debrief did not build is confined before its first instruction:
//!
//! - the AppContainer (one profile per name, created on first use) has no access to the user's files, registry or
//!   objects except what is granted to its SID: the folders the spec names ([`grant`]) and the host's pipe;
//! - network access only through the `internetClient` / `privateNetworkClientServer` capabilities, given when the
//!   sandbox allows the network;
//! - the process is created suspended, put into its job object (memory, CPU and child-process limits, killed with
//!   Debrief) and only then resumed, so it cannot start anything before the job holds it;
//! - it inherits exactly two handles (its stdin pipe, its stderr pipe) and an environment built from the spec.

use crate::job::{JobGuard, JobLimits};
use crate::process::SpawnSpec;
use std::fs::File;
use std::io;
use std::os::windows::ffi::OsStrExt;
use std::os::windows::io::FromRawHandle;
use std::os::windows::process::ExitStatusExt;
use std::path::Path;
use std::process::ExitStatus;
use windows::core::{w, HRESULT, PCWSTR, PWSTR};
use windows::Win32::Foundation::{
    CloseHandle, LocalFree, SetHandleInformation, GENERIC_ALL, GENERIC_EXECUTE, GENERIC_READ, HANDLE, HANDLE_FLAGS, HANDLE_FLAG_INHERIT,
    HLOCAL, WAIT_OBJECT_0,
};
use windows::Win32::Security::Authorization::{
    ConvertSidToStringSidW, ConvertStringSidToSidW, GetNamedSecurityInfoW, SetEntriesInAclW, SetNamedSecurityInfoW, EXPLICIT_ACCESS_W,
    GRANT_ACCESS, NO_MULTIPLE_TRUSTEE, SE_FILE_OBJECT, TRUSTEE_IS_SID, TRUSTEE_IS_WELL_KNOWN_GROUP, TRUSTEE_W,
};
use windows::Win32::Security::Isolation::{
    CreateAppContainerProfile, DeleteAppContainerProfile, DeriveAppContainerSidFromAppContainerName,
};
use windows::Win32::Security::{
    FreeSid, ACL, DACL_SECURITY_INFORMATION, PSECURITY_DESCRIPTOR, PSID, SECURITY_ATTRIBUTES, SECURITY_CAPABILITIES, SID_AND_ATTRIBUTES,
    SUB_CONTAINERS_AND_OBJECTS_INHERIT,
};
use windows::Win32::System::Pipes::CreatePipe;
use windows::Win32::System::Threading::{
    CreateProcessW, DeleteProcThreadAttributeList, GetExitCodeProcess, InitializeProcThreadAttributeList, ResumeThread, TerminateProcess,
    UpdateProcThreadAttribute, WaitForSingleObject, BELOW_NORMAL_PRIORITY_CLASS, CREATE_NO_WINDOW, CREATE_SUSPENDED,
    CREATE_UNICODE_ENVIRONMENT, EXTENDED_STARTUPINFO_PRESENT, LPPROC_THREAD_ATTRIBUTE_LIST, PROCESS_CREATION_FLAGS, PROCESS_INFORMATION,
    PROC_THREAD_ATTRIBUTE_HANDLE_LIST, PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES, STARTF_USESTDHANDLES, STARTUPINFOEXW, STARTUPINFOW,
};

/// `HRESULT_FROM_WIN32(ERROR_ALREADY_EXISTS)`.
const ALREADY_EXISTS: HRESULT = HRESULT(0x800700B7_u32 as i32);
/// `SE_GROUP_ENABLED`.
const SE_GROUP_ENABLED: u32 = 0x4;
/// The capabilities that open the network to an AppContainer: `internetClient`, `privateNetworkClientServer`.
const NETWORK_CAPABILITIES: [&str; 2] = ["S-1-15-3-1", "S-1-15-3-3"];

fn wide(s: impl AsRef<std::ffi::OsStr>) -> Vec<u16> {
    s.as_ref().encode_wide().chain(std::iter::once(0)).collect()
}

/// A SID allocated by the system, freed on drop.
struct Sid {
    psid: PSID,
    /// `FreeSid` (container SIDs) or `LocalFree` (converted string SIDs).
    local: bool,
}

impl Drop for Sid {
    fn drop(&mut self) {
        // SAFETY: the SID was allocated by the call named in `local` and is freed once.
        unsafe {
            if self.local {
                let _ = LocalFree(Some(HLOCAL(self.psid.0)));
            } else {
                let _ = FreeSid(self.psid);
            }
        }
    }
}

fn string_sid(text: &str) -> io::Result<Sid> {
    let mut psid = PSID::default();
    let w = wide(text);
    // SAFETY: `w` is NUL-terminated and outlives the call; the SID is freed by `Sid`.
    unsafe { ConvertStringSidToSidW(PCWSTR(w.as_ptr()), &mut psid) }.map_err(|e| io::Error::other(format!("SID {text}: {e}")))?;
    Ok(Sid { psid, local: true })
}

/// An AppContainer profile (created on first use, then reused by name).
pub struct Container {
    sid: Sid,
    /// The SID as `S-1-15-2-...`, for security descriptors.
    pub sid_string: String,
}

// SAFETY: the SID is plain memory owned by this value and only read.
unsafe impl Send for Container {}
// SAFETY: as above; nothing mutates the SID.
unsafe impl Sync for Container {}

impl Container {
    /// The container named `name` (see [`crate::sandbox::Containment::valid_name`]).
    pub fn open(name: &str) -> io::Result<Container> {
        if !crate::sandbox::Containment::valid_name(name) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("\"{name}\" is not a valid container name"),
            ));
        }
        let w = wide(name);
        // Profiles are created one at a time: two creations of one name at once fail with a misleading error.
        static CREATING: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let _one = CREATING.lock().unwrap_or_else(|p| p.into_inner());
        let mut attempt = 0;
        let psid = loop {
            attempt += 1;
            // SAFETY: NUL-terminated strings that outlive the calls; the returned SID is freed by `Sid`.
            let created = unsafe { CreateAppContainerProfile(PCWSTR(w.as_ptr()), PCWSTR(w.as_ptr()), w!("A Debrief plugin"), None) };
            match created {
                Ok(sid) => break sid,
                // SAFETY: as above.
                Err(e) if e.code() == ALREADY_EXISTS => match unsafe { DeriveAppContainerSidFromAppContainerName(PCWSTR(w.as_ptr())) } {
                    Ok(sid) => break sid,
                    Err(e) => return Err(io::Error::other(format!("AppContainer {name}: {e}"))),
                },
                // Another process may be creating the same profile right now: try again shortly.
                Err(_) if attempt < 5 => std::thread::sleep(std::time::Duration::from_millis(100 * attempt)),
                Err(e) => return Err(io::Error::other(format!("cannot create the AppContainer {name}: {e}"))),
            }
        };
        let sid = Sid { psid, local: false };
        let mut text = PWSTR::null();
        // SAFETY: a valid SID; the string is freed below.
        let sid_string = unsafe {
            ConvertSidToStringSidW(sid.psid, &mut text).map_err(|e| io::Error::other(e.to_string()))?;
            let s = text.to_string().unwrap_or_default();
            let _ = LocalFree(Some(HLOCAL(text.0 as *mut _)));
            s
        };
        Ok(Container { sid, sid_string })
    }

    /// Deletes the container profile named `name` (when its plugin is removed); a missing profile is not an error.
    pub fn delete(name: &str) -> io::Result<()> {
        if !crate::sandbox::Containment::valid_name(name) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("\"{name}\" is not a valid container name"),
            ));
        }
        let w = wide(name);
        // SAFETY: a NUL-terminated string that outlives the call.
        unsafe { DeleteAppContainerProfile(PCWSTR(w.as_ptr())) }.map_err(|e| io::Error::other(format!("AppContainer {name}: {e}")))
    }

    /// Lets the container read and execute (or, with `write`, change) `path` and everything below it.
    pub fn grant(&self, path: &Path, write: bool) -> io::Result<()> {
        let name = wide(path);
        let mut dacl: *mut ACL = std::ptr::null_mut();
        let mut sd = PSECURITY_DESCRIPTOR::default();
        // SAFETY: Win32 calls with valid pointers; the descriptor and the new ACL are freed below.
        unsafe {
            let err = GetNamedSecurityInfoW(
                PCWSTR(name.as_ptr()),
                SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION,
                None,
                None,
                Some(&mut dacl),
                None,
                &mut sd,
            );
            if err.is_err() {
                return Err(io::Error::other(format!(
                    "cannot read the permissions of {}: {err:?}",
                    path.display()
                )));
            }
            let rights = if write { GENERIC_ALL.0 } else { GENERIC_READ.0 | GENERIC_EXECUTE.0 };
            let entry = EXPLICIT_ACCESS_W {
                grfAccessPermissions: rights,
                grfAccessMode: GRANT_ACCESS,
                grfInheritance: SUB_CONTAINERS_AND_OBJECTS_INHERIT,
                Trustee: TRUSTEE_W {
                    pMultipleTrustee: std::ptr::null_mut(),
                    MultipleTrusteeOperation: NO_MULTIPLE_TRUSTEE,
                    TrusteeForm: TRUSTEE_IS_SID,
                    TrusteeType: TRUSTEE_IS_WELL_KNOWN_GROUP,
                    ptstrName: PWSTR(self.sid.psid.0 as *mut u16),
                },
            };
            let mut new_acl: *mut ACL = std::ptr::null_mut();
            let err = SetEntriesInAclW(Some(&[entry]), Some(dacl), &mut new_acl);
            let result = if err.is_err() {
                Err(io::Error::other(format!(
                    "cannot extend the permissions of {}: {err:?}",
                    path.display()
                )))
            } else {
                let err = SetNamedSecurityInfoW(
                    PCWSTR(name.as_ptr()),
                    SE_FILE_OBJECT,
                    DACL_SECURITY_INFORMATION,
                    None,
                    None,
                    Some(new_acl),
                    None,
                );
                if err.is_err() {
                    Err(io::Error::other(format!(
                        "cannot grant the plugin access to {}: {err:?}",
                        path.display()
                    )))
                } else {
                    Ok(())
                }
            };
            if !new_acl.is_null() {
                let _ = LocalFree(Some(HLOCAL(new_acl as *mut _)));
            }
            let _ = LocalFree(Some(HLOCAL(sd.0)));
            result
        }
    }
}

/// An owned process handle.
struct Handle(HANDLE);

// SAFETY: process handles may be used from any thread.
unsafe impl Send for Handle {}
// SAFETY: the calls made through a shared reference (wait, exit code, terminate) are thread-safe.
unsafe impl Sync for Handle {}

impl Drop for Handle {
    fn drop(&mut self) {
        if !self.0.is_invalid() && !self.0 .0.is_null() {
            // SAFETY: owned handle, closed once.
            unsafe {
                let _ = CloseHandle(self.0);
            }
        }
    }
}

/// A process started in a container.
pub struct Contained {
    process: Handle,
    pid: u32,
}

impl Contained {
    pub fn id(&self) -> u32 {
        self.pid
    }

    pub fn try_wait(&self) -> io::Result<Option<ExitStatus>> {
        // SAFETY: a valid process handle.
        unsafe {
            if WaitForSingleObject(self.process.0, 0) != WAIT_OBJECT_0 {
                return Ok(None);
            }
            let mut code = 0u32;
            GetExitCodeProcess(self.process.0, &mut code).map_err(|e| io::Error::other(e.to_string()))?;
            Ok(Some(ExitStatus::from_raw(code)))
        }
    }

    pub fn kill(&self) -> io::Result<()> {
        // SAFETY: a valid process handle; terminating an exited process fails harmlessly.
        // conformance: pid-kill — a process handle we own (the process object cannot be handed on while it is open)
        match unsafe { TerminateProcess(self.process.0, 1) } {
            Ok(()) => Ok(()),
            Err(_) if self.try_wait()?.is_some() => Ok(()),
            Err(e) => Err(io::Error::other(e.to_string())),
        }
    }

    pub fn wait(&self) -> io::Result<ExitStatus> {
        // SAFETY: a valid process handle.
        unsafe {
            let _ = WaitForSingleObject(self.process.0, u32::MAX);
        }
        self.try_wait()?.ok_or_else(|| io::Error::other("the process did not exit"))
    }

    /// The process handle (for the job object).
    pub fn raw(&self) -> HANDLE {
        self.process.0
    }
}

/// What [`spawn`] started.
pub struct Started {
    pub child: Contained,
    pub stdin: File,
    pub stderr: Option<File>,
    pub job: JobGuard,
}

/// One argument quoted for `CommandLineToArgvW` (the MSVC runtime's rules).
fn quote(arg: &str, out: &mut String) {
    if !arg.is_empty() && !arg.chars().any(|c| matches!(c, ' ' | '\t' | '\n' | '\u{b}' | '"')) {
        out.push_str(arg);
        return;
    }
    out.push('"');
    let mut backslashes = 0usize;
    for c in arg.chars() {
        match c {
            '\\' => backslashes += 1,
            '"' => {
                out.extend(std::iter::repeat_n('\\', backslashes * 2 + 1));
                out.push('"');
                backslashes = 0;
            }
            _ => {
                out.extend(std::iter::repeat_n('\\', backslashes));
                out.push(c);
                backslashes = 0;
            }
        }
    }
    out.extend(std::iter::repeat_n('\\', backslashes * 2));
    out.push('"');
}

/// The command line of `spec` (program first).
pub fn command_line(spec: &SpawnSpec) -> String {
    let mut line = String::new();
    quote(&spec.exe.to_string_lossy(), &mut line);
    for a in &spec.args {
        line.push(' ');
        quote(a, &mut line);
    }
    line
}

/// Variables Windows needs to create an AppContainer process (it moves the container's profile folders below
/// them); they name folders, not secrets.
const CONTAINER_ENV: &[&str] = &["USERPROFILE", "LOCALAPPDATA", "APPDATA"];

/// The environment block of `spec`: the kept variables of this process, [`CONTAINER_ENV`] and the spec's own
/// (later ones win, names compared without case), sorted, `K=V<NUL>...<NUL><NUL>`.
fn environment(spec: &SpawnSpec) -> Vec<u16> {
    let mut vars: Vec<(String, String)> = Vec::new();
    let mut set = |k: &str, v: String| {
        vars.retain(|(have, _)| !have.eq_ignore_ascii_case(k));
        vars.push((k.to_string(), v));
    };
    for k in spec.keep_env.iter().chain(CONTAINER_ENV) {
        if let Ok(v) = std::env::var(k) {
            set(k, v);
        }
    }
    for (k, v) in &spec.env {
        set(k, v.clone());
    }
    vars.sort_by_key(|(k, _)| k.to_ascii_uppercase());
    let mut block: Vec<u16> = Vec::new();
    for (k, v) in vars {
        block.extend(format!("{k}={v}").encode_utf16());
        block.push(0);
    }
    if block.is_empty() {
        block.push(0);
    }
    block.push(0);
    block
}

fn pipe(inherit_read: bool) -> io::Result<(HANDLE, HANDLE)> {
    let sa = SECURITY_ATTRIBUTES {
        nLength: std::mem::size_of::<SECURITY_ATTRIBUTES>() as u32,
        lpSecurityDescriptor: std::ptr::null_mut(),
        bInheritHandle: true.into(),
    };
    let (mut r, mut w) = (HANDLE::default(), HANDLE::default());
    // SAFETY: valid out pointers; the handles are owned by the caller.
    unsafe {
        CreatePipe(&mut r, &mut w, Some(&sa), 0).map_err(|e| io::Error::other(e.to_string()))?;
        // Only the child's end is inherited.
        let ours = if inherit_read { w } else { r };
        SetHandleInformation(ours, HANDLE_FLAG_INHERIT.0, HANDLE_FLAGS(0)).map_err(|e| io::Error::other(e.to_string()))?;
    }
    Ok((r, w))
}

fn close(h: HANDLE) {
    if !h.0.is_null() {
        // SAFETY: an owned handle, closed once.
        unsafe {
            let _ = CloseHandle(h);
        }
    }
}

/// Starts `spec` in `container` with `limits`, suspended until its job holds it. `stderr`: pipe its standard
/// error (else it has none). The working directory is the spec's (it must be one the container can read).
pub fn spawn(spec: &SpawnSpec, container: &Container, network: bool, limits: &JobLimits, stderr: bool) -> io::Result<Started> {
    let (in_r, in_w) = pipe(true)?;
    let (err_r, err_w) = if stderr {
        match pipe(false) {
            Ok(p) => p,
            Err(e) => {
                close(in_r);
                close(in_w);
                return Err(e);
            }
        }
    } else {
        (HANDLE::default(), HANDLE::default())
    };
    let result = spawn_with(spec, container, network, limits, in_r, err_w);
    close(in_r);
    close(err_w);
    match result {
        // SAFETY: the parent's ends are owned here and move into the files.
        Ok((child, job)) => Ok(Started {
            child,
            stdin: unsafe { File::from_raw_handle(in_w.0) },
            stderr: stderr.then(|| unsafe { File::from_raw_handle(err_r.0) }),
            job,
        }),
        Err(e) => {
            close(in_w);
            close(err_r);
            Err(e)
        }
    }
}

fn spawn_with(
    spec: &SpawnSpec,
    container: &Container,
    network: bool,
    limits: &JobLimits,
    stdin: HANDLE,
    stderr: HANDLE,
) -> io::Result<(Contained, JobGuard)> {
    let caps: Vec<Sid> = if network {
        NETWORK_CAPABILITIES.iter().map(|s| string_sid(s)).collect::<io::Result<_>>()?
    } else {
        Vec::new()
    };
    let mut cap_attrs: Vec<SID_AND_ATTRIBUTES> = caps
        .iter()
        .map(|c| SID_AND_ATTRIBUTES {
            Sid: c.psid,
            Attributes: SE_GROUP_ENABLED,
        })
        .collect();
    let capabilities = SECURITY_CAPABILITIES {
        AppContainerSid: container.sid.psid,
        Capabilities: if cap_attrs.is_empty() {
            std::ptr::null_mut()
        } else {
            cap_attrs.as_mut_ptr()
        },
        CapabilityCount: cap_attrs.len() as u32,
        Reserved: 0,
    };
    let handles: Vec<HANDLE> = [stdin, stderr].into_iter().filter(|h| !h.0.is_null()).collect();
    let mut size = 0usize;
    // SAFETY: the first call only reports the size of the list.
    let _ = unsafe { InitializeProcThreadAttributeList(None, 2, None, &mut size) };
    let mut buf = vec![0u8; size.max(64)];
    let list = LPPROC_THREAD_ATTRIBUTE_LIST(buf.as_mut_ptr() as *mut _);
    let mut cmd: Vec<u16> = command_line(spec).encode_utf16().chain(std::iter::once(0)).collect();
    let exe = wide(&spec.exe);
    let env = environment(spec);
    let cwd = spec.current_dir.as_ref().map(wide);
    let mut flags: PROCESS_CREATION_FLAGS = EXTENDED_STARTUPINFO_PRESENT | CREATE_SUSPENDED | CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT;
    if spec.below_normal_priority {
        flags |= BELOW_NORMAL_PRIORITY_CLASS;
    }
    let mut pi = PROCESS_INFORMATION::default();
    // SAFETY: every pointer refers to a local that outlives the calls; the attribute list is deleted below and the
    // process and thread handles are owned afterwards.
    unsafe {
        InitializeProcThreadAttributeList(Some(list), 2, None, &mut size).map_err(|e| io::Error::other(e.to_string()))?;
        let created = UpdateProcThreadAttribute(
            list,
            0,
            PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES as usize,
            Some(&capabilities as *const SECURITY_CAPABILITIES as *const _),
            std::mem::size_of::<SECURITY_CAPABILITIES>(),
            None,
            None,
        )
        .map_err(|e| windows::core::Error::new(e.code(), format!("security capabilities: {}", e.message())))
        .and_then(|()| {
            UpdateProcThreadAttribute(
                list,
                0,
                PROC_THREAD_ATTRIBUTE_HANDLE_LIST as usize,
                Some(handles.as_ptr() as *const _),
                handles.len() * std::mem::size_of::<HANDLE>(),
                None,
                None,
            )
            .map_err(|e| windows::core::Error::new(e.code(), format!("handle list: {}", e.message())))
        })
        .and_then(|()| {
            let si = STARTUPINFOEXW {
                StartupInfo: STARTUPINFOW {
                    cb: std::mem::size_of::<STARTUPINFOEXW>() as u32,
                    dwFlags: STARTF_USESTDHANDLES,
                    hStdInput: stdin,
                    hStdOutput: HANDLE::default(),
                    hStdError: stderr,
                    ..Default::default()
                },
                lpAttributeList: list,
            };
            CreateProcessW(
                PCWSTR(exe.as_ptr()),
                Some(PWSTR(cmd.as_mut_ptr())),
                None,
                None,
                true,
                flags,
                Some(env.as_ptr() as *const _),
                cwd.as_ref().map_or(PCWSTR::null(), |c| PCWSTR(c.as_ptr())),
                &si.StartupInfo,
                &mut pi,
            )
        });
        DeleteProcThreadAttributeList(list);
        created.map_err(|e| io::Error::other(format!("cannot start {} in its sandbox ({}): {e}", spec.label, spec.exe.display())))?;
    }
    let child = Contained {
        process: Handle(pi.hProcess),
        pid: pi.dwProcessId,
    };
    let thread = Handle(pi.hThread);
    // The job holds the process before it runs: no window in which it could start another program.
    let Some(job) = JobGuard::assign_handle(child.raw(), limits) else {
        let _ = child.kill();
        return Err(io::Error::other(format!("cannot put {} into its job object", spec.label)));
    };
    // SAFETY: the suspended main thread of the process just created.
    if unsafe { ResumeThread(thread.0) } == u32::MAX {
        let _ = child.kill();
        return Err(io::Error::other(format!("cannot resume {}", spec.label)));
    }
    drop(caps);
    Ok((child, job))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn command_lines_quote_like_the_msvc_runtime() {
        let mut s = SpawnSpec::new(r"C:\Program Files\x\p.exe", "p");
        s.args = vec!["--plugin".into(), "a b".into(), r#"q"uote"#.into(), r"tail\".into(), String::new()];
        assert_eq!(command_line(&s), r#""C:\Program Files\x\p.exe" --plugin "a b" "q\"uote" tail\ """#);
        let mut t = SpawnSpec::new("p", "p");
        t.args = vec![r"a\\b c\".into()];
        assert_eq!(command_line(&t), r#"p "a\\b c\\""#);
    }

    #[test]
    fn the_environment_block_holds_only_what_the_spec_names() {
        let mut s = SpawnSpec::new("p", "p");
        s.keep_env = &["SystemRoot", "SYSTEMROOT"];
        s.env = vec![("DEBRIEF_X".into(), "1".into()), ("systemroot".into(), "override".into())];
        let block = String::from_utf16(&environment(&s)).unwrap();
        assert!(block.ends_with("\0\0"));
        let vars: Vec<&str> = block.trim_end_matches('\0').split('\0').collect();
        assert!(vars.contains(&"DEBRIEF_X=1") && vars.contains(&"systemroot=override"), "{vars:?}");
        let upper = |v: &&str| v.to_ascii_uppercase();
        assert_eq!(vars.iter().filter(|v| upper(v).starts_with("SYSTEMROOT=")).count(), 1);
        let allowed = ["DEBRIEF_X=", "SYSTEMROOT=", "USERPROFILE=", "LOCALAPPDATA=", "APPDATA="];
        assert!(vars.iter().all(|v| allowed.iter().any(|k| upper(v).starts_with(k))), "{vars:?}");
        let mut sorted = vars.clone();
        sorted.sort_by_key(upper);
        assert_eq!(sorted, vars);
    }

    #[test]
    fn containers_are_created_reused_and_deleted() {
        assert!(Container::open("bad name").is_err());
        assert!(Container::open(&"x".repeat(65)).is_err());
        assert!(Container::delete("bad name").is_err());
        let name = "debrief.test.contain-unit";
        let a = Container::open(name).unwrap();
        let b = Container::open(name).unwrap();
        assert!(a.sid_string.starts_with("S-1-15-2-"));
        assert_eq!(a.sid_string, b.sid_string, "the same profile is reused");
        Container::delete(name).unwrap();
        // Deleting again: gone already, which is fine.
        let _ = Container::delete(name);
    }
}

//! Children that need administrator rights (ADR 0017 §7), e.g. ETW capture.
//!
//! [`decide`] is the launcher's pure decision. On Windows an elevated child is started with `ShellExecuteExW`
//! and the `runas` verb (the UAC prompt); it cannot get a stdin pipe, so its [`Bootstrap`] goes into a file in a
//! fresh private folder named on its command line (`--debrief-bootstrap <file>`), which the child reads and deletes.
//! The host's endpoint admits the Administrators group (the elevated child may run as another account), and the
//! host checks that the process that connected is the one `ShellExecuteExW` started, besides the token.
//! Elsewhere elevation is refused with a message ([`IpcError::Denied`]): Debrief has no setuid helper.

use crate::launch::Bootstrap;
use crate::process::SpawnSpec;
use crate::IpcError;

/// The command-line flag naming an elevated child's bootstrap file.
pub const BOOTSTRAP_FLAG: &str = "--debrief-bootstrap";

/// Whether a child needs administrator rights.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub enum Elevation {
    #[default]
    None,
    /// It must run elevated; `reason` is shown with the prompt's outcome ("ETW capture needs administrator rights").
    Required { reason: String },
}

/// How the launcher starts a child.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LaunchMode {
    /// A normal child process (with Debrief's rights: elevated already, or no elevation needed).
    Plain,
    /// Through the administrator prompt (Windows).
    RunAs,
}

/// The launcher's decision for this platform.
pub fn decide(elevation: &Elevation, elevated_now: bool) -> Result<LaunchMode, IpcError> {
    decide_on(elevation, elevated_now, cfg!(windows))
}

/// [`decide`] for a given platform (tests).
pub fn decide_on(elevation: &Elevation, elevated_now: bool, windows: bool) -> Result<LaunchMode, IpcError> {
    match elevation {
        Elevation::None => Ok(LaunchMode::Plain),
        Elevation::Required { .. } if elevated_now => Ok(LaunchMode::Plain),
        Elevation::Required { .. } if windows => Ok(LaunchMode::RunAs),
        Elevation::Required { reason } => Err(IpcError::Denied(format!(
            "{reason}; start Debrief with administrator rights (for example with sudo) to use it"
        ))),
    }
}

/// Whether this process runs with administrator rights (elevated token on Windows, euid 0 on Unix).
pub fn is_elevated() -> bool {
    platform::is_elevated()
}

/// A child started through the administrator prompt.
pub struct ElevatedProcess {
    #[cfg(windows)]
    inner: std::sync::Arc<platform::Handle>,
    pid: u32,
    label: String,
    /// The private folder of the bootstrap file (removed on drop; the child deletes the file itself).
    _dir: Option<TempDir>,
}

impl ElevatedProcess {
    pub fn pid(&self) -> u32 {
        self.pid
    }

    /// A probe for "has it exited, and how" usable from another thread.
    pub fn probe(&self) -> Box<dyn Fn() -> Option<String> + Send> {
        #[cfg(windows)]
        {
            let h = self.inner.clone();
            Box::new(move || h.exit_code().map(|c| format!("exit code {c}")))
        }
        #[cfg(not(windows))]
        Box::new(|| None)
    }

    pub fn exited(&self) -> bool {
        (self.probe())().is_some()
    }

    pub fn exit_text(&self) -> String {
        match (self.probe())() {
            Some(s) => format!("{} exited ({s})", self.label),
            None => format!("{} closed the connection", self.label),
        }
    }

    /// Ends it when Debrief may (it also exits when its connection closes).
    pub fn kill(&self) {
        #[cfg(windows)]
        self.inner.terminate();
    }
}

use tempfile::TempDir;

/// Writes `bootstrap` into a fresh private folder; returns the folder and the file.
fn write_bootstrap(bootstrap: &Bootstrap) -> Result<(TempDir, std::path::PathBuf), IpcError> {
    let fail = |e: std::io::Error| IpcError::Spawn(format!("cannot prepare the elevated start: {e}"));
    // A fresh private folder (random name, owner only), removed on drop: nothing another local user can plant.
    let dir = crate::scratch::private_tempdir("debrief-elevate-").map_err(fail)?;
    let file = dir.path().join("bootstrap.json");
    let json = serde_json::to_vec(bootstrap).map_err(|e| IpcError::Spawn(e.to_string()))?;
    std::fs::write(&file, json).map_err(fail)?;
    Ok((dir, file))
}

/// Reads and deletes an elevated child's bootstrap file (the child side).
pub fn take_bootstrap(file: &std::path::Path) -> std::io::Result<Bootstrap> {
    let text = std::fs::read(file)?;
    let _ = std::fs::remove_file(file);
    if text.len() > 64 * 1024 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "the bootstrap file is too large",
        ));
    }
    serde_json::from_slice(&text).map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, format!("bad bootstrap: {e}")))
}

/// One argument quoted for a Windows command line (the rules `CommandLineToArgvW` undoes).
pub fn quote_arg(arg: &str) -> String {
    if !arg.is_empty() && !arg.contains([' ', '\t', '\n', '\u{b}', '"']) {
        return arg.to_string();
    }
    let mut out = String::from('"');
    let mut backslashes = 0usize;
    for c in arg.chars() {
        match c {
            '\\' => backslashes += 1,
            '"' => {
                out.extend(std::iter::repeat_n('\\', backslashes * 2 + 1));
                out.push('"');
                backslashes = 0;
            }
            c => {
                out.extend(std::iter::repeat_n('\\', backslashes));
                out.push(c);
                backslashes = 0;
            }
        }
    }
    out.extend(std::iter::repeat_n('\\', backslashes * 2));
    out.push('"');
    out
}

/// Starts `spec`'s program through the administrator prompt with `bootstrap` (Windows only).
pub fn run_as(spec: &SpawnSpec, bootstrap: &Bootstrap) -> Result<ElevatedProcess, IpcError> {
    let (dir, file) = write_bootstrap(bootstrap)?;
    let mut args: Vec<String> = spec.args.clone();
    args.push(BOOTSTRAP_FLAG.into());
    args.push(file.to_string_lossy().into_owned());
    let params = args.iter().map(|a| quote_arg(a)).collect::<Vec<_>>().join(" ");
    platform::run_as(spec, &params).map(|(handle, pid)| {
        #[cfg(not(windows))]
        let () = handle;
        ElevatedProcess {
            #[cfg(windows)]
            inner: handle,
            pid,
            label: spec.label.clone(),
            _dir: Some(dir),
        }
    })
}

#[cfg(windows)]
mod platform {
    use crate::process::SpawnSpec;
    use crate::IpcError;
    use std::sync::Arc;
    use windows::core::{HSTRING, PCWSTR};
    use windows::Win32::Foundation::{CloseHandle, HANDLE, WAIT_OBJECT_0};
    use windows::Win32::Security::{GetTokenInformation, TokenElevation, TOKEN_ELEVATION, TOKEN_QUERY};
    use windows::Win32::System::Threading::{
        GetCurrentProcess, GetExitCodeProcess, GetProcessId, OpenProcessToken, TerminateProcess, WaitForSingleObject,
    };
    use windows::Win32::UI::Shell::{ShellExecuteExW, SEE_MASK_NOASYNC, SEE_MASK_NOCLOSEPROCESS, SHELLEXECUTEINFOW};
    use windows::Win32::UI::WindowsAndMessaging::SW_HIDE;

    pub fn is_elevated() -> bool {
        // SAFETY: plain Win32 calls on the current process' token with valid out pointers; the handle is closed.
        unsafe {
            let mut token = HANDLE::default();
            if OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &mut token).is_err() {
                return false;
            }
            let mut e = TOKEN_ELEVATION::default();
            let mut len = 0u32;
            let ok = GetTokenInformation(
                token,
                TokenElevation,
                Some(&mut e as *mut _ as *mut std::ffi::c_void),
                std::mem::size_of::<TOKEN_ELEVATION>() as u32,
                &mut len,
            )
            .is_ok();
            let _ = CloseHandle(token);
            ok && e.TokenIsElevated != 0
        }
    }

    /// The process handle `ShellExecuteExW` returned.
    pub struct Handle(HANDLE);

    // SAFETY: a process handle may be used and closed from any thread.
    unsafe impl Send for Handle {}
    // SAFETY: the calls made through a shared reference (wait, exit code, terminate) are thread-safe.
    unsafe impl Sync for Handle {}

    impl Handle {
        pub fn exit_code(&self) -> Option<u32> {
            // SAFETY: the handle is valid until `Drop`.
            unsafe {
                if WaitForSingleObject(self.0, 0) != WAIT_OBJECT_0 {
                    return None;
                }
                let mut code = 0u32;
                GetExitCodeProcess(self.0, &mut code).ok().map(|_| code)
            }
        }

        pub fn terminate(&self) {
            // SAFETY: as above; failure (no terminate right on an elevated process) is ignored: the child also
            // exits when its connection closes.
            unsafe {
                // conformance: pid-kill — a process handle we own (the process object cannot be handed on while it is open)
                let _ = TerminateProcess(self.0, 1);
            }
        }
    }

    impl Drop for Handle {
        fn drop(&mut self) {
            // SAFETY: closed once.
            unsafe {
                let _ = CloseHandle(self.0);
            }
        }
    }

    pub fn run_as(spec: &SpawnSpec, params: &str) -> Result<(Arc<Handle>, u32), IpcError> {
        const ERROR_CANCELLED: i32 = 1223;
        let verb = HSTRING::from("runas");
        let file = HSTRING::from(spec.exe.as_os_str());
        let params = HSTRING::from(params);
        let dir = spec.current_dir.as_ref().map(|d| HSTRING::from(d.as_os_str()));
        let mut info = SHELLEXECUTEINFOW {
            cbSize: std::mem::size_of::<SHELLEXECUTEINFOW>() as u32,
            fMask: SEE_MASK_NOCLOSEPROCESS | SEE_MASK_NOASYNC,
            lpVerb: PCWSTR(verb.as_ptr()),
            lpFile: PCWSTR(file.as_ptr()),
            lpParameters: PCWSTR(params.as_ptr()),
            lpDirectory: dir.as_ref().map(|d| PCWSTR(d.as_ptr())).unwrap_or(PCWSTR::null()),
            nShow: SW_HIDE.0,
            ..Default::default()
        };
        // SAFETY: every pointer in `info` refers to an HSTRING that outlives the call.
        match unsafe { ShellExecuteExW(&mut info) } {
            Ok(()) if !info.hProcess.is_invalid() => {
                // SAFETY: a valid process handle we own from now on.
                let pid = unsafe { GetProcessId(info.hProcess) };
                Ok((Arc::new(Handle(info.hProcess)), pid))
            }
            Ok(()) => Err(IpcError::Spawn(format!("{} started without a process handle", spec.label))),
            Err(e) if e.code().0 & 0xFFFF == ERROR_CANCELLED => Err(IpcError::Denied(format!(
                "{} needs administrator rights and the administrator prompt was declined",
                spec.label
            ))),
            Err(e) => Err(IpcError::Spawn(format!(
                "cannot start {} with administrator rights ({}): {e}",
                spec.label,
                spec.exe.display()
            ))),
        }
    }
}

#[cfg(not(windows))]
mod platform {
    use crate::process::SpawnSpec;
    use crate::IpcError;

    pub fn is_elevated() -> bool {
        // SAFETY: geteuid has no preconditions.
        unsafe { libc::geteuid() == 0 }
    }

    pub fn run_as(spec: &SpawnSpec, _params: &str) -> Result<((), u32), IpcError> {
        Err(IpcError::Denied(format!(
            "{} needs administrator rights; start Debrief with them to use it",
            spec.label
        )))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_launcher_decides_by_need_rights_and_platform() {
        let need = Elevation::Required {
            reason: "ETW capture needs administrator rights".into(),
        };
        assert_eq!(decide_on(&Elevation::None, false, true).unwrap(), LaunchMode::Plain);
        assert_eq!(decide_on(&Elevation::None, true, false).unwrap(), LaunchMode::Plain);
        assert_eq!(decide_on(&need, true, true).unwrap(), LaunchMode::Plain, "already elevated");
        assert_eq!(decide_on(&need, true, false).unwrap(), LaunchMode::Plain, "root on Unix");
        assert_eq!(decide_on(&need, false, true).unwrap(), LaunchMode::RunAs);
        match decide_on(&need, false, false) {
            Err(IpcError::Denied(m)) => assert!(m.starts_with("ETW capture needs administrator rights;"), "{m}"),
            other => panic!("{other:?}"),
        }
        assert!(!IpcError::Denied("x".into()).is_process_failure());
        // Whatever this test runs as, the probe answers.
        let _ = is_elevated();
    }

    #[test]
    fn arguments_are_quoted_for_command_line_to_argv() {
        assert_eq!(quote_arg("plain"), "plain");
        assert_eq!(quote_arg(""), "\"\"");
        assert_eq!(
            quote_arg("C:\\Program Files\\Debrief\\x.json"),
            "\"C:\\Program Files\\Debrief\\x.json\""
        );
        assert_eq!(quote_arg("a\"b"), "\"a\\\"b\"");
        assert_eq!(quote_arg("ends\\ with\\"), "\"ends\\ with\\\\\"");
        assert_eq!(quote_arg("q\\\"x y"), "\"q\\\\\\\"x y\"");
    }

    #[test]
    fn the_bootstrap_file_is_read_once_and_deleted() {
        let b = Bootstrap {
            address: "pipe".into(),
            token: "00".repeat(32),
            sandbox: crate::sandbox::SandboxSpec::locked(),
            max_frame: 4096,
            role: "elevated".into(),
        };
        let (dir, file) = write_bootstrap(&b).unwrap();
        assert!(file.starts_with(dir.path()));
        assert_eq!(take_bootstrap(&file).unwrap(), b);
        assert!(!file.exists(), "deleted after reading");
        assert!(take_bootstrap(&file).is_err());
        let folder = dir.path().to_path_buf();
        drop(dir);
        assert!(!folder.exists());
        // Garbage and oversized files are refused.
        let (dir, file) = write_bootstrap(&b).unwrap();
        std::fs::write(&file, b"nope").unwrap();
        assert_eq!(take_bootstrap(&file).unwrap_err().kind(), std::io::ErrorKind::InvalidData);
        std::fs::write(&file, vec![b' '; 70_000]).unwrap();
        assert!(take_bootstrap(&file).is_err());
        drop(dir);
    }

    #[cfg(not(windows))]
    #[test]
    fn elevation_is_refused_off_windows() {
        let spec = SpawnSpec::new("/bin/true", "the collector");
        let b = Bootstrap {
            address: "a".into(),
            token: String::new(),
            sandbox: Default::default(),
            max_frame: 1024,
            role: String::new(),
        };
        assert!(matches!(run_as(&spec, &b), Err(IpcError::Denied(_))));
    }
}

//! Starting a child process the supervisor owns: below-normal priority, no console window, a cleared
//! environment, killed with Debrief (a job object with KILL_ON_JOB_CLOSE on Windows, which also carries the
//! sandbox's limits; on Unix the child exits when its stdin, the lifeline, closes). [`crate::launch`] writes its
//! bootstrap to stdin and accepts its connection.

//!
//! With [`SpawnSpec::log`] the child's standard error is captured into its [`crate::child_log`] (with start
//! and exit lines); without it, standard error is discarded.

use crate::child_log::{self, ChildLog, ChildLogSpec, Exit};
use crate::memory_watch::{MemoryEvent, MemoryListener, MemoryWatch, Verdict};
use crate::IpcError;
use std::io::{BufRead, Read, Write};
use std::path::PathBuf;
use std::process::{Child, ExitStatus, Stdio};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

/// Longest piece of a child's standard error read as one line.
const MAX_STDERR_LINE: u64 = 8 * 1024;
/// How long the standard error reader waits for the OS to publish an exit status after end of output.
const EXIT_WAIT: Duration = Duration::from_secs(2);

/// Environment variables every child gets by default ([`SpawnSpec::keep_env`]): what the OS and the
/// runtime need, and the coverage profile path so instrumented test builds can report. Nothing else of
/// Debrief's environment (tokens, proxies, user variables) reaches a child unless it is named.
pub const KEPT_ENV: &[&str] = &[
    "PATH",
    "SystemRoot",
    "SYSTEMROOT",
    "windir",
    "TEMP",
    "TMP",
    "TMPDIR",
    "LANG",
    "LC_ALL",
    "RUST_BACKTRACE",
    "LLVM_PROFILE_FILE",
    "CARGO_LLVM_COV",
    "XDG_RUNTIME_DIR",
];

/// How long a child whose lifeline was cut may take to exit before it is killed: the child's own stop budget plus a
/// margin ([`crate::child::STOP_BUDGET`], [`crate::child::STOP_MARGIN`]). A grace shorter than the budget killed the store
/// worker in the middle of its exit; a child that stops sooner ends the wait with it.
pub const KILL_GRACE: Duration = crate::child::STOP_BUDGET.saturating_add(crate::child::STOP_MARGIN);

/// How to start a child.
#[derive(Debug, Clone)]
pub struct SpawnSpec {
    pub exe: PathBuf,
    pub args: Vec<String>,
    /// Extra environment.
    pub env: Vec<(String, String)>,
    /// The only variables of Debrief's environment the child inherits (default [`KEPT_ENV`]); every child
    /// starts from an empty environment plus these and `env`, so it learns nothing ambient.
    pub keep_env: &'static [&'static str],
    /// Working directory (default: inherited).
    pub current_dir: Option<PathBuf>,
    /// Names the process in messages: "the AI engine", "plugin \"x\"".
    pub label: String,
    /// Prefix of the private address (see [`PrivateEndpoint::create_named`]).
    pub endpoint_prefix: String,
    /// How long the child may take to connect ([`UNTIL_CONNECTED`]: until it connects or exits).
    pub connect_window: Duration,
    /// Run at below-normal priority so the analysis stays responsive.
    pub below_normal_priority: bool,
    /// Capture standard error into this child log (see [`crate::child_log`]); `None` discards it.
    pub log: Option<ChildLogSpec>,
    /// The child's sandbox: the launcher applies its job limits (Windows), the child the rest
    /// ([`crate::sandbox`]).
    pub sandbox: crate::sandbox::SandboxSpec,
    /// Hears what the memory watcher sees of a capped child (the warning at 80%, the stop, the peak at the end; see
    /// [`crate::memory_watch`]). Ignored without a memory cap.
    pub memory_listener: Option<MemoryListener>,
    /// The private socket the child connects to (Unix; set by [`crate::launch::launch`]): the one socket a contained
    /// macOS child's sandbox profile lets it reach.
    pub ipc_socket: Option<PathBuf>,
}

/// A connect window with no wall-clock end: the host waits until the child connects or exits. For tests, whose children
/// start late on a loaded machine: a fixed window then stopped a child that was still starting, and every restart
/// started late again (CI 7096). The test runner's hang detector, not a clock, ends a child that never connects.
pub const UNTIL_CONNECTED: Duration = Duration::MAX;

/// The product's connect window: how long a child may take to connect before the launch gives up (an exit ends the wait at once,
/// whatever this is). Tests that start a fresh binary use [`UNTIL_CONNECTED`] (ADR 0071); the product keeps this bound so a
/// child that is alive and never connects ends the launch instead of holding the supervisor's lock.
pub const DEFAULT_CONNECT_WINDOW: Duration = Duration::from_secs(15);

impl SpawnSpec {
    pub fn new(exe: impl Into<PathBuf>, label: impl Into<String>) -> SpawnSpec {
        SpawnSpec {
            exe: exe.into(),
            args: Vec::new(),
            env: Vec::new(),
            keep_env: KEPT_ENV,
            current_dir: None,
            label: label.into(),
            endpoint_prefix: crate::endpoint::prefix::DEFAULT.into(),
            connect_window: DEFAULT_CONNECT_WINDOW,
            below_normal_priority: true,
            log: None,
            sandbox: crate::sandbox::SandboxSpec::unrestricted(),
            memory_listener: None,
            ipc_socket: None,
        }
    }
}

/// The exit line of one child, written once (by whoever sees the exit first).
struct ExitNote {
    log: Arc<ChildLog>,
    pid: u32,
    written: AtomicBool,
    /// Debrief asked the child to stop: whatever its status, it was stopped by Debrief.
    stopping: AtomicBool,
}

impl ExitNote {
    fn write(&self, status: Option<ExitStatus>) {
        if self.written.swap(true, Ordering::SeqCst) {
            return;
        }
        let exit = if self.stopping.load(Ordering::SeqCst) {
            Exit::StoppedByDebrief
        } else {
            status.as_ref().map(Exit::of).unwrap_or(Exit::Unknown)
        };
        self.log.exited(Some(self.pid), exit);
    }
}

/// The OS process behind a [`ChildProcess`]: started by the standard library, or (a contained child on Windows) in
/// an AppContainer by [`crate::contain`].
enum OsChild {
    /// The child and, read right after the spawn (while no one could have reaped it), its identity.
    Std(Child, Option<paddock_proc::ProcessId>),
    #[cfg(windows)]
    Contained(crate::contain::Contained),
}

impl OsChild {
    fn id(&self) -> u32 {
        match self {
            OsChild::Std(c, _) => c.id(),
            #[cfg(windows)]
            OsChild::Contained(c) => c.id(),
        }
    }

    #[expect(
        clippy::disallowed_methods,
        reason = "the liveness check of a held child, reaping it if it ended; most callers look once or with the memory sample, but the exit note and the kill grace poll it (the try_wait class, to move to an event wait in the class fix)"
    )]
    fn try_wait(&mut self) -> std::io::Result<Option<ExitStatus>> {
        match self {
            OsChild::Std(c, _) => c.try_wait(),
            #[cfg(windows)]
            OsChild::Contained(c) => c.try_wait(),
        }
    }

    /// Ends the child's whole process group and tree (Unix: every child is the leader of its own group, see
    /// [`ChildProcess::spawn`]), so what it started (a grandchild of the worker) ends with it even when its
    /// own clean-up never runs. It goes by the child's identity ([`paddock_proc::kill_tree`]): a leader that was
    /// reaped and whose pid was handed on is left alone. Without an identity (its start time could not be read) a child
    /// that is not reaped yet is still ours: its group is ended through its pid (`unreaped`). On Windows the job object
    /// ends the tree too; the identity is the fallback when Windows gave the child no job.
    fn kill_group(&self, unreaped: bool) {
        match self {
            OsChild::Std(_, Some(id)) => {
                paddock_proc::kill_tree(*id);
            }
            OsChild::Std(c, None) if unreaped => paddock_proc::end_unreaped_group(c.id()),
            OsChild::Std(_, None) => {}
            // A contained child (Windows only) is in a job object that ends its tree.
            #[cfg(windows)]
            OsChild::Contained(_) => {}
        }
    }

    fn kill(&mut self) -> std::io::Result<()> {
        match self {
            OsChild::Std(c, _) => c.kill(),
            #[cfg(windows)]
            OsChild::Contained(c) => c.kill(),
        }
    }

    fn wait(&mut self) -> std::io::Result<ExitStatus> {
        match self {
            OsChild::Std(c, _) => c.wait(),
            #[cfg(windows)]
            OsChild::Contained(c) => c.wait(),
        }
    }
}

/// A job object on Windows; nothing elsewhere.
#[cfg(windows)]
type Job = Option<crate::job::JobGuard>;
#[cfg(not(windows))]
type Job = ();

/// A started child. Killed (and reaped) on drop.
pub struct ChildProcess {
    child: Arc<Mutex<Option<OsChild>>>,
    stdin: Mutex<Option<Box<dyn Write + Send>>>,
    pid: u32,
    label: String,
    exit_note: Option<Arc<ExitNote>>,
    /// The memory cap the host stopped the child over, once it did.
    over_memory: Arc<Mutex<Option<u64>>>,
    /// The most memory the watcher saw the child use (bytes; 0 when it is not watched).
    memory_peak: Arc<AtomicU64>,
    /// What the launcher could not enforce of its sandbox.
    sandbox_notes: Vec<crate::sandbox::Note>,
    _job: Job,
}

/// How often the host looks at the memory of a capped child.
pub const MEMORY_LOOK: Duration = Duration::from_millis(200);

/// "512 MB": a memory cap for messages.
fn megabytes(bytes: u64) -> String {
    format!("{} MB", bytes.div_ceil(1 << 20))
}

/// What the memory watcher of one child shares with its [`ChildProcess`].
struct Watched {
    pid: u32,
    child: Arc<Mutex<Option<OsChild>>>,
    over: Arc<Mutex<Option<u64>>>,
    peak: Arc<AtomicU64>,
    log: Option<Arc<ChildLog>>,
    label: String,
    listener: Option<MemoryListener>,
}

/// Watches the real memory (`paddock_proc::process_memory`: PSS, physical footprint or private working set, never the resident
/// size, which counts pages the allocator freed; rule 26) of the child `pid` and stops it once it uses more than `limit` (the memory cap of its
/// sandbox), the same way on every platform: rlimits and job commit limits count reservations and commitments that
/// allocators make up front (see `SandboxSpec::memory_limit`). Tells the listener at 80% of the cap, at the stop and
/// when the child ends ([`crate::memory_watch`]). Ends with the child.
fn watch_memory(limit: u64, w: Watched) {
    let spawned = std::thread::Builder::new().name("debrief-child-memory".into()).spawn(move || {
        let mut watch = MemoryWatch::new(limit);
        let mut last = 0;
        let tell = |e: MemoryEvent| {
            if let Some(l) = &w.listener {
                l.tell(&w.label, e);
            }
        };
        loop {
            std::thread::sleep(MEMORY_LOOK);
            let ended = lock(&w.child).as_mut().is_none_or(|c| matches!(c.try_wait(), Ok(Some(_))));
            if ended {
                return tell(MemoryEvent::Ended(watch.ended(last)));
            }
            last = paddock_proc::process_memory(w.pid).unwrap_or(0);
            let verdict = watch.observe(last);
            w.peak.store(watch.peak(), Ordering::Relaxed);
            match verdict {
                Verdict::Fine => {}
                Verdict::Warn(u) => tell(MemoryEvent::Warning(u)),
                Verdict::Stop(u) => {
                    *lock(&w.over) = Some(limit);
                    if let Some(l) = &w.log {
                        l.record(&child_log::ChildEvent::Note(format!(
                            "Stopped: it used {} of memory, more than its cap of {}",
                            megabytes(u.used),
                            megabytes(limit)
                        )));
                    }
                    if let Some(c) = lock(&w.child).as_mut() {
                        let _ = c.kill();
                    }
                    return tell(MemoryEvent::Stopped(u));
                }
            }
        }
    });
    drop(spawned);
}

fn lock<T>(m: &Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|p| p.into_inner())
}

/// Reads a child's standard error into its log until end of output, then records how it exited (unless
/// Debrief is already stopping it, which records that itself).
/// Test seam: the stderr readers of children logged under these names read their output but never record their exit, so a
/// test can stop a child whose exit nobody has noted yet (the order in which Debrief's stop and the reader race).
#[cfg(any(test, feature = "test-support"))]
static HELD_READERS: Mutex<Vec<String>> = Mutex::new(Vec::new());

/// Holds the exit-recording half of the stderr reader of every child logged under `name` started from now on (tests).
#[cfg(any(test, feature = "test-support"))]
pub fn hold_exit_reader(name: &str) {
    lock(&HELD_READERS).push(child_log::log_name(name));
}

fn reader_held(_name: &str) -> bool {
    #[cfg(any(test, feature = "test-support"))]
    return lock(&HELD_READERS).iter().any(|n| n == _name);
    #[cfg(not(any(test, feature = "test-support")))]
    false
}

fn capture_stderr(
    stderr: impl Read + Send + 'static,
    log: Arc<ChildLog>,
    child: Arc<Mutex<Option<OsChild>>>,
    note: Arc<ExitNote>,
    held: bool,
) {
    let spawned = std::thread::Builder::new().name("debrief-child-stderr".into()).spawn(move || {
        let mut r = std::io::BufReader::new(stderr);
        let mut line = Vec::new();
        loop {
            line.clear();
            match r.by_ref().take(MAX_STDERR_LINE).read_until(b'\n', &mut line) {
                Ok(0) | Err(_) => break,
                Ok(_) => log.output(&String::from_utf8_lossy(&line)),
            }
        }
        if held {
            return;
        }
        let deadline = std::time::Instant::now() + EXIT_WAIT;
        while std::time::Instant::now() < deadline {
            let status = match lock(&child).as_mut() {
                // Taken: Debrief is stopping it and records the exit.
                None => return,
                Some(c) => c.try_wait().ok().flatten(),
            };
            if let Some(s) = status {
                return note.write(Some(s));
            }
            std::thread::sleep(Duration::from_millis(20));
        }
    });
    // Without a thread the pipe is dropped with the closure: the child's writes fail instead of blocking.
    drop(spawned);
}

impl ChildProcess {
    /// Starts the program with a piped stdin (its lifeline), no stdout, and stderr captured into its child
    /// log when the spec names one (discarded otherwise). A spec whose sandbox is
    /// [`crate::sandbox::Containment::Launcher`] is contained before it runs any code.
    pub fn spawn(spec: &SpawnSpec) -> Result<ChildProcess, IpcError> {
        let fail = |e: String| {
            let msg = format!("cannot start {} ({}): {e}", spec.label, spec.exe.display());
            if let Some(l) = &spec.log {
                child_log::get(l).record(&child_log::ChildEvent::Note(format!("Could not start: {msg}")));
            }
            IpcError::Spawn(msg)
        };
        #[cfg(windows)]
        if let crate::sandbox::Containment::Launcher { name, read, write } = &spec.sandbox.containment {
            let container = crate::contain::Container::open(name).map_err(|e| fail(e.to_string()))?;
            for (paths, w) in [(read, false), (write, true)] {
                for p in paths {
                    container.grant(p, w).map_err(|e| fail(e.to_string()))?;
                }
            }
            let mut contained = spec.clone();
            // The container can only enter folders granted to it.
            if !read.iter().chain(write).any(|r| Some(r) == contained.current_dir.as_ref()) {
                contained.current_dir = read.first().cloned();
            }
            let limits = crate::job::JobLimits::of(spec);
            let started = crate::contain::spawn(&contained, &container, spec.sandbox.network, &limits, spec.log.is_some())
                .map_err(|e| fail(e.to_string()))?;
            let stderr = started.stderr.map(|f| Box::new(f) as Box<dyn Read + Send>);
            return Ok(ChildProcess::assemble(
                spec,
                OsChild::Contained(started.child),
                Some(Box::new(started.stdin)),
                stderr,
                Some(started.job),
            ));
        }
        let (exe, args) = launcher_command(spec);
        // The canonical constructor (no console window on Windows); the creation flags below add the priority.
        let mut cmd = paddock_proc::command(&exe);
        cmd.args(&args)
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(if spec.log.is_some() { Stdio::piped() } else { Stdio::null() });
        // The one clearing function: `keep_env` plus the restricting variables (ER-47).
        paddock_proc::clean_env(&mut cmd, spec.keep_env);
        cmd.envs(spec.env.iter().map(|(k, v)| (k, v)));
        if let Some(d) = &spec.current_dir {
            cmd.current_dir(d);
        }
        // Its own process group, so a kill reaches what it starts too (posix_spawn supports it; no `pre_exec`).
        #[cfg(unix)]
        std::os::unix::process::CommandExt::process_group(&mut cmd, 0);
        #[cfg(windows)]
        {
            use std::os::windows::process::CommandExt;
            // No console window; below-normal priority when asked.
            let priority = if spec.below_normal_priority { 0x0000_4000 } else { 0 };
            cmd.creation_flags(paddock_proc::CREATE_NO_WINDOW | priority);
        }
        #[cfg(target_os = "linux")]
        let report = match spec.sandbox.contained() {
            true => crate::sandbox::contain_before_exec(&mut cmd, &spec.sandbox, &spec.exe).map_err(fail)?,
            false => None,
        };
        let mut child = cmd.spawn().map_err(|e| fail(e.to_string()))?;
        #[cfg(target_os = "linux")]
        let sandbox_notes = report.map(|r| r.notes()).unwrap_or_default();
        #[cfg(not(target_os = "linux"))]
        let sandbox_notes: Vec<crate::sandbox::Note> = Vec::new();
        // Lowered from here rather than in a `pre_exec` hook: a hook forces fork+exec instead of
        // posix_spawn, and on macOS a concurrent fork can then inherit another spawn's exec-status pipe
        // and keep that spawn waiting forever.
        #[cfg(unix)]
        if spec.below_normal_priority {
            // SAFETY: setpriority takes plain integers and has no memory effects; it only lowers the
            // priority of our own child.
            unsafe {
                libc::setpriority(libc::PRIO_PROCESS, child.id() as libc::id_t, unix_nice(&spec.sandbox));
            }
        }
        #[cfg(windows)]
        let job = crate::job::JobGuard::assign(&child, &crate::job::JobLimits::of(spec));
        #[cfg(not(windows))]
        let job = ();
        let stdin = child.stdin.take().map(|s| Box::new(s) as Box<dyn Write + Send>);
        let stderr = child.stderr.take().map(|s| Box::new(s) as Box<dyn Read + Send>);
        let leader = paddock_proc::ProcessId::of(child.id());
        let mut process = ChildProcess::assemble(spec, OsChild::Std(child, leader), stdin, stderr, job);
        if let Some(log) = process.log() {
            for n in &sandbox_notes {
                log.record(&child_log::ChildEvent::Note(n.log_line()));
            }
        }
        process.sandbox_notes = sandbox_notes;
        Ok(process)
    }

    /// The bookkeeping of a started child: its log, its exit line and its standard error reader.
    fn assemble(
        spec: &SpawnSpec,
        child: OsChild,
        stdin: Option<Box<dyn Write + Send>>,
        stderr: Option<Box<dyn Read + Send>>,
        job: Job,
    ) -> ChildProcess {
        let pid = child.id();
        let child = Arc::new(Mutex::new(Some(child)));
        let over_memory = Arc::new(Mutex::new(None));
        let memory_peak = Arc::new(AtomicU64::new(0));
        let exit_note = spec.log.as_ref().map(|l| {
            let log = child_log::get(l);
            log.started(pid);
            let note = Arc::new(ExitNote {
                log: log.clone(),
                pid,
                written: AtomicBool::new(false),
                stopping: AtomicBool::new(false),
            });
            if let Some(err) = stderr {
                capture_stderr(err, log, child.clone(), note.clone(), reader_held(&l.name));
            }
            note
        });
        if let Some(limit) = spec.sandbox.memory_limit {
            watch_memory(
                limit,
                Watched {
                    pid,
                    child: child.clone(),
                    over: over_memory.clone(),
                    peak: memory_peak.clone(),
                    log: exit_note.as_ref().map(|n| n.log.clone()),
                    label: spec.label.clone(),
                    listener: spec.memory_listener.clone(),
                },
            );
        }
        ChildProcess {
            child,
            stdin: Mutex::new(stdin),
            pid,
            label: spec.label.clone(),
            exit_note,
            over_memory,
            memory_peak,
            sandbox_notes: Vec::new(),
            _job: job,
        }
    }

    /// The child's log, when its output is captured.
    pub fn log(&self) -> Option<&Arc<ChildLog>> {
        self.exit_note.as_ref().map(|n| &n.log)
    }

    /// From now on, however the child ends, Debrief stopped it.
    fn mark_stopping(&self) {
        if let Some(n) = &self.exit_note {
            n.stopping.store(true, Ordering::SeqCst);
        }
    }

    fn note_exit(&self, status: Option<ExitStatus>) {
        if let Some(n) = &self.exit_note {
            n.write(status);
        }
    }

    pub fn pid(&self) -> u32 {
        self.pid
    }

    /// The most memory the host's watcher saw the child use, in bytes (0 when it has no memory cap).
    pub fn memory_peak(&self) -> u64 {
        self.memory_peak.load(Ordering::Relaxed)
    }

    /// What the launcher could not enforce of the child's sandbox (Linux: the landlock status the child reported).
    pub fn sandbox_notes(&self) -> &[crate::sandbox::Note] {
        &self.sandbox_notes
    }

    /// Writes `value` as one JSON line to the child's stdin (its bootstrap).
    pub fn send_line<T: serde::Serialize>(&self, value: &T) -> Result<(), IpcError> {
        let line = serde_json::to_string(value).map_err(|e| IpcError::Protocol(e.to_string()))?;
        let wrote = lock(&self.stdin)
            .as_mut()
            .map(|s| s.write_all(format!("{line}\n").as_bytes()).and_then(|_| s.flush()));
        // The handshake is the first thing a child reads, so a failed write means it died while starting (one
        // that exits at once can break the pipe before Debrief writes).
        match wrote {
            Some(Ok(())) => Ok(()),
            _ => Err(IpcError::Died(match self.exit_soon() {
                Some(s) => format!("{} exited while starting ({s})", self.label),
                None => format!("{} closed the connection while starting", self.label),
            })),
        }
    }

    /// The exit status, if the child has exited.
    pub fn try_exit(&self) -> Option<ExitStatus> {
        lock(&self.child).as_mut().and_then(|c| c.try_wait().ok().flatten())
    }

    /// Whether the child has exited (or was killed).
    pub fn exited(&self) -> bool {
        lock(&self.child).as_mut().is_none_or(|c| matches!(c.try_wait(), Ok(Some(_))))
    }

    /// Describes how the child ended, waiting briefly for the OS to publish its exit status.
    pub fn exit_text(&self) -> String {
        if let Some(limit) = *lock(&self.over_memory) {
            return format!(
                "{} used more than its memory cap of {} and was stopped",
                self.label,
                megabytes(limit)
            );
        }
        match self.exit_soon() {
            Some(s) => format!("{} exited ({s})", self.label),
            None => format!("{} closed the connection", self.label),
        }
    }

    /// The exit status, waiting up to 200 ms for the OS to publish it.
    fn exit_soon(&self) -> Option<ExitStatus> {
        for _ in 0..20 {
            if let Some(s) = self.try_exit() {
                return Some(s);
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        None
    }

    /// Debrief begins to stop the child: an exit it already made on its own is recorded as its own (a crash stays a crash),
    /// and from now on however it ends is a stop by Debrief. Call it before anything that makes a well-behaved child exit
    /// (closing its connection or its lifeline): that exit can be seen at once, and must not read as the child's own
    /// (CI 7981: "exit code 0" logged for a child Debrief stopped).
    pub(crate) fn begin_stop(&self) {
        self.note_own_exit();
        self.mark_stopping();
    }

    /// Closes the child's stdin: a well-behaved child exits on its own (this is what happens when Debrief dies).
    pub fn close_lifeline(&self) {
        self.begin_stop();
        *lock(&self.stdin) = None;
    }

    /// A child that already ended on its own is recorded as such (crash or normal), before Debrief stops it.
    fn note_own_exit(&self) {
        if let Some(s) = self.try_exit() {
            self.note_exit(Some(s));
        }
    }

    /// Stops a child whose connection broke (a call failed as a process failure): it has most likely ended on its own, so the
    /// OS is given a moment to publish its exit, which is recorded as its own (a crash), before Debrief stops it.
    pub fn kill_after_failure(&self) {
        self.note_published_exit();
        self.kill();
    }

    /// Records the child's own exit, waiting up to 200 ms for the OS to publish it ([`ChildProcess::exit_soon`]): a child
    /// whose connection just broke has usually exited, but its status can lag the broken pipe. One still running is left to
    /// the stop that follows.
    pub(crate) fn note_published_exit(&self) {
        if let Some(s) = self.exit_soon() {
            self.note_exit(Some(s));
        }
    }

    /// Stops the child and reaps it: its lifeline is closed first and a well-behaved child exits at once
    /// (see [`crate::child::child_main`]); one that has not after [`KILL_GRACE`] is killed.
    pub fn kill(&self) {
        self.begin_stop();
        *lock(&self.stdin) = None;
        let taken = lock(&self.child).take();
        if let Some(mut c) = taken {
            let deadline = std::time::Instant::now() + KILL_GRACE;
            let mut ended = false;
            while std::time::Instant::now() < deadline {
                if matches!(c.try_wait(), Ok(Some(_))) {
                    ended = true;
                    break;
                }
                std::thread::sleep(Duration::from_millis(5));
            }
            // Whatever it started and left behind ends now too.
            c.kill_group(!ended);
            if !ended {
                let _ = c.kill();
                let _ = c.wait();
            }
            self.note_exit(None);
        }
    }

    /// Closes the lifeline and waits up to `grace` for the child to exit on its own; kills it after that.
    pub fn close(&self, grace: Duration) {
        self.close_lifeline();
        let deadline = std::time::Instant::now() + grace;
        while std::time::Instant::now() < deadline {
            if self.try_exit().is_some() {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        self.kill();
    }
}

impl Drop for ChildProcess {
    fn drop(&mut self) {
        self.kill();
    }
}

/// The program and arguments that start `spec`: the program itself, or on macOS for a contained child,
/// `sandbox-exec` with the sandbox profile in front of it. The contained program is named by its resolved path: the
/// profile cannot read the symlinks on the way (macOS' `/var` → `/private/var`), so exec through them is denied.
fn launcher_command(spec: &SpawnSpec) -> (PathBuf, Vec<String>) {
    #[cfg(target_os = "macos")]
    if let Some(profile) = crate::sandbox::launcher_profile(&spec.sandbox, &spec.exe, spec.ipc_socket.as_deref()) {
        let exe = std::fs::canonicalize(&spec.exe).unwrap_or_else(|_| spec.exe.clone());
        let mut args = vec!["-p".to_string(), profile, exe.to_string_lossy().into_owned()];
        args.extend(spec.args.iter().cloned());
        return (PathBuf::from("/usr/bin/sandbox-exec"), args);
    }
    (spec.exe.clone(), spec.args.clone())
}

/// The nice level of a below-normal child on Unix: 10, or 19 (the lowest) when its sandbox asks for a CPU share below
/// 100% (Unix has no hard CPU cap for one process, so a share only lowers the priority; ADR 0031 §1).
#[cfg_attr(not(unix), allow(dead_code))]
fn unix_nice(sandbox: &crate::sandbox::SandboxSpec) -> i32 {
    match sandbox.cpu_rate_percent {
        Some(p) if p < 100 => 19,
        _ => 10,
    }
}

/// Real memory of this process, in bytes (0 if unknown): `paddock_proc::process_memory`, not the resident size (rule 26). The
/// name and the `rss_bytes` wire fields predate that; they carry this figure.
pub fn current_rss_bytes() -> u64 {
    paddock_proc::process_memory(std::process::id()).unwrap_or(0)
}

#[cfg(test)]
mod tests {
    #[test]
    fn rss_is_reported() {
        assert!(super::current_rss_bytes() > 0);
    }

    /// Regression: a contained plugin in a folder reached through a symlink (macOS' temp folder) exited with
    /// `sandbox-exec`'s status 71, as its profile cannot read the symlink to exec the program through it.
    #[test]
    #[cfg(target_os = "macos")]
    fn a_contained_program_is_started_by_its_resolved_path() {
        let t = tempfile::tempdir().unwrap();
        let real = t.path().canonicalize().unwrap().join("real");
        std::fs::create_dir_all(real.join("bin")).unwrap();
        std::fs::write(real.join("bin/x"), b"").unwrap();
        let link = t.path().join("link");
        std::os::unix::fs::symlink(&real, &link).unwrap();
        let mut spec = super::SpawnSpec::new(link.join("bin/x"), "x");
        spec.sandbox = crate::sandbox::SandboxSpec {
            containment: crate::sandbox::Containment::Launcher {
                name: "debrief.plugin.x".into(),
                read: vec![link.clone()],
                write: Vec::new(),
            },
            ..crate::sandbox::SandboxSpec::locked()
        };
        let (program, args) = super::launcher_command(&spec);
        assert_eq!(program, std::path::Path::new("/usr/bin/sandbox-exec"));
        assert_eq!(args[2], real.join("bin/x").to_string_lossy());
    }

    #[test]
    fn a_cpu_share_below_100_lowers_the_unix_priority_further() {
        let mut s = crate::sandbox::SandboxSpec::unrestricted();
        assert_eq!(super::unix_nice(&s), 10);
        s.cpu_rate_percent = Some(100);
        assert_eq!(super::unix_nice(&s), 10);
        s.cpu_rate_percent = Some(50);
        assert_eq!(super::unix_nice(&s), 19);
    }

    /// Starts the fake worker `body` (a shell script) and takes the identity of the grandchild whose pid it wrote, as soon as
    /// the record is complete (`Ended` when the grandchild was already gone, never the process that got its pid next).
    #[cfg(unix)]
    fn start_fake_worker(d: &std::path::Path, body: &str) -> (super::ChildProcess, paddock_testkit_start::Recorded) {
        let pid_file = d.join("grandchild.pid");
        let script = d.join("worker.sh");
        paddock_testkit::exe::write_program(&script, body.replace("PIDFILE", &pid_file.display().to_string())).unwrap();
        let child = super::ChildProcess::spawn(&super::SpawnSpec::new(&script, "fake worker")).unwrap();
        let grandchild = paddock_testkit_start::recorded::read_pid_file(&pid_file, "the fake worker's child");
        (child, grandchild)
    }

    /// Fails unless `grandchild` is gone within a few seconds (a blind probe fails too: `has_ended` is false while the process
    /// table cannot be read), ending it by identity first, so a pid handed on is never signalled (rule 53, ER-14).
    #[cfg(unix)]
    fn assert_grandchild_ends(grandchild: paddock_testkit_start::Recorded) {
        let end = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while !grandchild.has_ended() {
            if std::time::Instant::now() >= end {
                if let Some(id) = grandchild.running() {
                    let _ = paddock_proc::end(id);
                }
                panic!("the grandchild (pid {}) was left behind", grandchild.pid());
            }
            std::thread::yield_now();
        }
    }

    /// A fake worker that starts a grandchild, ignores its lifeline and SIGTERM, and stays.
    #[cfg(unix)]
    const STAYING_WORKER: &str = "#!/bin/sh\ntrap '' TERM\nsleep 60 &\necho $! > 'PIDFILE'\nwhile :; do sleep 1; done\n";

    /// A child killed after its grace period takes what it started with it (a worker's own child, which on
    /// macOS has no parent-death signal and whose exit hook never runs under SIGKILL).
    #[cfg(unix)]
    #[test]
    fn a_child_killed_after_its_grace_takes_its_own_children_with_it() {
        let d = tempfile::tempdir().unwrap();
        let (child, grandchild) = start_fake_worker(d.path(), STAYING_WORKER);
        child.kill();
        assert_grandchild_ends(grandchild);
    }

    /// A child whose start time could not be read has no identity, but while it is not reaped it is still ours: its group
    /// is ended through its pid (the same arm as `paddock_proc::Supervised::kill`).
    #[cfg(unix)]
    #[test]
    fn a_child_without_an_identity_still_has_its_group_ended() {
        let d = tempfile::tempdir().unwrap();
        let (child, grandchild) = start_fake_worker(d.path(), STAYING_WORKER);
        if let Some(super::OsChild::Std(_, id)) = super::lock(&child.child).as_mut() {
            *id = None;
        }
        child.kill();
        assert_grandchild_ends(grandchild);
    }

    /// A leader that exits by itself and leaves a grandchild behind: the kill still ends the grandchild.
    #[cfg(unix)]
    #[test]
    fn a_leader_that_exited_by_itself_leaves_no_grandchild_after_the_kill() {
        let d = tempfile::tempdir().unwrap();
        let (child, grandchild) = start_fake_worker(d.path(), "#!/bin/sh\nsleep 60 &\necho $! > 'PIDFILE'\nexit 0\n");
        child.kill();
        assert_grandchild_ends(grandchild);
    }
}

//! Running and finished captures (app-wide within a process): start, stop,
//! cancel, status, and the watcher that finalises a capture that ended by
//! itself. Wire DTOs mirror `DotnetCaptureStatus` in the UI.

use crate::{Collector, DotnetError, Finished, Limits, Preset, ProcessInfo, Recording};
use serde::{Deserialize, Serialize};
use std::collections::VecDeque;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

/// Finished captures kept in the list.
const KEEP: usize = 50;
/// Longest recording a request may ask for.
pub const MAX_DURATION_SEC: u64 = 3600;

/// `DotnetCaptureState`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum State {
    Recording,
    Stopping,
    Done,
    Failed,
    Cancelled,
}

/// `DotnetCaptureRequest`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Request {
    pub pid: u32,
    pub kind: Preset,
    /// `None`: until stopped (a heap snapshot ends by itself).
    pub duration_sec: Option<u64>,
}

/// `DotnetCaptureStatus`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Status {
    pub id: String,
    pub pid: u32,
    pub process_name: String,
    pub kind: Preset,
    pub state: State,
    pub elapsed_ms: u64,
    pub bytes: u64,
    pub path: Option<String>,
    pub error: Option<String>,
    /// Whether the error is missing rights (the UI offers "Restart as administrator").
    pub needs_elevation: bool,
    pub truncated: bool,
    pub notes: Vec<String>,
}

struct Entry {
    status: Status,
    started: Instant,
    recording: Option<Box<dyn Recording>>,
}

/// The capture list.
pub struct Captures {
    collector: Arc<dyn Collector>,
    entries: Mutex<VecDeque<Entry>>,
    next: Mutex<u64>,
}

impl Captures {
    pub fn new(collector: Arc<dyn Collector>) -> Arc<Captures> {
        Arc::new(Captures {
            collector,
            entries: Mutex::new(VecDeque::new()),
            next: Mutex::new(1),
        })
    }

    pub fn collector(&self) -> &Arc<dyn Collector> {
        &self.collector
    }

    fn lock(&self) -> MutexGuard<'_, VecDeque<Entry>> {
        self.entries.lock().unwrap_or_else(|p| p.into_inner())
    }

    /// Every capture, newest first, with live sizes and times.
    pub fn list(&self) -> Vec<Status> {
        let mut g = self.lock();
        g.iter_mut().rev().map(refresh).collect()
    }

    /// One capture.
    pub fn get(&self, id: &str) -> Option<Status> {
        self.lock().iter_mut().find(|e| e.status.id == id).map(refresh)
    }

    /// Starts a capture into `dir`; refuses a second capture of one process.
    pub fn start(&self, req: Request, dir: &Path, limits: Limits) -> Result<Status, String> {
        if req.duration_sec.is_some_and(|d| d == 0 || d > MAX_DURATION_SEC) {
            return Err(format!("the duration must be between 1 and {MAX_DURATION_SEC} seconds"));
        }
        if self
            .lock()
            .iter()
            .any(|e| e.status.pid == req.pid && matches!(e.status.state, State::Recording | State::Stopping))
        {
            return Err(format!("process {} is already being recorded; stop that capture first", req.pid));
        }
        let info = self
            .collector
            .list_processes()
            .into_iter()
            .find(|p| p.pid == req.pid)
            .ok_or_else(|| format!("process {} is not a running .NET process (refresh the list)", req.pid))?;
        std::fs::create_dir_all(dir).map_err(|e| format!("cannot create the captures folder {}: {e}", dir.display()))?;
        let id = {
            let mut n = self.next.lock().unwrap_or_else(|p| p.into_inner());
            *n += 1;
            format!("dotnet-{}", *n - 1)
        };
        let path = dir.join(file_name(&info, req.kind, unix_secs()));
        let mut limits = limits;
        if let Some(d) = req.duration_sec {
            limits.max_duration = Duration::from_secs(d);
        }
        let mut status = Status {
            id: id.clone(),
            pid: info.pid,
            process_name: info.name.clone(),
            kind: req.kind,
            state: State::Recording,
            elapsed_ms: 0,
            bytes: 0,
            path: None,
            error: None,
            needs_elevation: false,
            truncated: false,
            notes: Vec::new(),
        };
        let recording = match self.collector.start(info.pid, req.kind, &path, limits) {
            Ok(r) => Some(r),
            Err(e) => {
                status.state = State::Failed;
                status.needs_elevation = matches!(e, DotnetError::Denied);
                status.error = Some(e.to_string());
                None
            }
        };
        let mut g = self.lock();
        g.push_back(Entry {
            status: status.clone(),
            started: Instant::now(),
            recording,
        });
        trim(&mut g);
        Ok(status)
    }

    /// Takes the recording of `id` and marks it stopping (or `None` when it is not running).
    fn take(&self, id: &str, state: State) -> Option<Box<dyn Recording>> {
        let mut g = self.lock();
        let e = g.iter_mut().find(|e| e.status.id == id)?;
        let r = e.recording.take()?;
        e.status.state = state;
        Some(r)
    }

    fn finish(&self, id: &str, result: Result<Finished, DotnetError>) -> Option<Status> {
        let mut g = self.lock();
        let e = g.iter_mut().find(|e| e.status.id == id)?;
        e.status.elapsed_ms = e.started.elapsed().as_millis() as u64;
        match result {
            Ok(f) => {
                e.status.state = State::Done;
                e.status.bytes = f.bytes;
                e.status.path = Some(f.path.to_string_lossy().into_owned());
                e.status.truncated = f.truncated;
                e.status.notes = f.notes;
            }
            Err(DotnetError::Cancelled) => e.status.state = State::Cancelled,
            Err(err) => {
                e.status.state = State::Failed;
                e.status.needs_elevation = matches!(err, DotnetError::Denied);
                e.status.error = Some(err.to_string());
            }
        }
        Some(e.status.clone())
    }

    /// Stops `id` (the file is kept and finished: rundown first). Unknown or finished: its status.
    pub fn stop(&self, id: &str) -> Result<Status, String> {
        match self.take(id, State::Stopping) {
            Some(r) => self.finish(id, r.stop()).ok_or_else(|| unknown(id)),
            None => self.get(id).ok_or_else(|| unknown(id)),
        }
    }

    /// Cancels `id`: stops at once and deletes the file.
    pub fn cancel(&self, id: &str) -> Result<Status, String> {
        match self.take(id, State::Stopping) {
            Some(r) => {
                r.cancel();
                self.finish(id, Err(DotnetError::Cancelled)).ok_or_else(|| unknown(id))
            }
            None => self.get(id).ok_or_else(|| unknown(id)),
        }
    }

    /// Finalises captures that ended by themselves (duration, heap walk done, target exited, size cap).
    /// Returns the ids it finished.
    pub fn reap(&self) -> Vec<String> {
        let ended: Vec<String> = self
            .lock()
            .iter()
            .filter(|e| e.recording.as_ref().is_some_and(|r| r.is_finished()))
            .map(|e| e.status.id.clone())
            .collect();
        for id in &ended {
            if let Some(r) = self.take(id, State::Stopping) {
                self.finish(id, r.stop());
            }
        }
        ended
    }

    /// Whether `id` still records.
    pub fn is_running(&self, id: &str) -> bool {
        self.lock().iter().any(|e| e.status.id == id && e.recording.is_some())
    }
}

fn unknown(id: &str) -> String {
    format!("there is no capture \"{id}\"")
}

fn refresh(e: &mut Entry) -> Status {
    if let Some(r) = &e.recording {
        e.status.bytes = r.bytes();
        e.status.elapsed_ms = r.elapsed().as_millis() as u64;
    }
    e.status.clone()
}

/// Drops the oldest finished captures beyond [`KEEP`].
fn trim(entries: &mut VecDeque<Entry>) {
    while entries.len() > KEEP {
        match entries.iter().position(|e| e.recording.is_none()) {
            Some(i) => {
                entries.remove(i);
            }
            None => break,
        }
    }
}

fn unix_secs() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_secs())
}

/// `Shop-1234-cpu-1792000000.nettrace` (names cleaned for the file system).
pub fn file_name(info: &ProcessInfo, kind: Preset, secs: u64) -> PathBuf {
    let stem: String = info
        .name
        .trim_end_matches(".exe")
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '_'
            }
        })
        .take(60)
        .collect();
    let kind = match kind {
        Preset::Cpu => "cpu",
        Preset::Allocations => "allocations",
        Preset::HeapSnapshot => "heap",
    };
    PathBuf::from(format!("{stem}-{}-{kind}-{secs}.nettrace", info.pid))
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use crate::process::Runtime;
    use crate::recording::ThreadRecording;
    use std::sync::atomic::{AtomicBool, Ordering};

    /// A collector with one process whose recordings write a few bytes until stopped.
    pub(crate) struct FakeCollector {
        pub deny: AtomicBool,
        /// Recordings end by themselves after this long.
        pub self_ending: Option<Duration>,
    }

    pub(crate) fn proc(pid: u32) -> ProcessInfo {
        ProcessInfo {
            pid,
            name: "Shop.exe".into(),
            command_line: None,
            runtime_version: Some(".NET 10.0.1".into()),
            arch: Some("x64".into()),
            runtime: Runtime::Core,
            needs_elevation: false,
        }
    }

    impl Collector for FakeCollector {
        fn list_processes(&self) -> Vec<ProcessInfo> {
            vec![proc(10), proc(11)]
        }

        fn start(&self, _pid: u32, _preset: Preset, out: &Path, limits: Limits) -> Result<Box<dyn Recording>, DotnetError> {
            if self.deny.load(Ordering::SeqCst) {
                return Err(DotnetError::Denied);
            }
            let out = out.to_path_buf();
            let o = out.clone();
            let ends = self.self_ending;
            let r = ThreadRecording::spawn("fake", out, move |ctl| {
                std::fs::write(&o, b"Nettrace").map_err(DotnetError::Io)?;
                ctl.set_bytes(8);
                let t = Instant::now();
                while !ctl.stopping() && t.elapsed() < limits.max_duration && ends.is_none_or(|d| t.elapsed() < d) {
                    std::thread::sleep(Duration::from_millis(5));
                }
                if ctl.cancelled() {
                    return Err(DotnetError::Cancelled);
                }
                Ok(Finished {
                    path: o,
                    bytes: 8,
                    truncated: false,
                    notes: vec!["n".into()],
                })
            })?;
            Ok(Box::new(r))
        }
    }

    pub(crate) fn fake(self_ending: Option<Duration>) -> Arc<FakeCollector> {
        Arc::new(FakeCollector {
            deny: AtomicBool::new(false),
            self_ending,
        })
    }

    fn req(pid: u32) -> Request {
        Request {
            pid,
            kind: Preset::Cpu,
            duration_sec: None,
        }
    }

    #[test]
    fn start_stop_cancel_and_list() {
        let dir = tempfile::tempdir().unwrap();
        let c = Captures::new(fake(None));
        let s = c.start(req(10), dir.path(), Limits::default()).unwrap();
        assert_eq!(s.state, State::Recording);
        assert_eq!(s.process_name, "Shop.exe");
        assert!(c
            .start(req(10), dir.path(), Limits::default())
            .unwrap_err()
            .contains("already being recorded"));
        assert!(c
            .start(req(99), dir.path(), Limits::default())
            .unwrap_err()
            .contains("not a running"));
        let bad = Request {
            duration_sec: Some(0),
            ..req(11)
        };
        assert!(c.start(bad, dir.path(), Limits::default()).is_err());
        assert!(c.is_running(&s.id));
        let done = c.stop(&s.id).unwrap();
        assert_eq!(done.state, State::Done);
        assert!(done.path.as_deref().is_some_and(|p| p.ends_with(".nettrace")));
        assert_eq!(done.notes, ["n"]);
        assert_eq!(c.stop(&s.id).unwrap().state, State::Done, "stopping twice is harmless");

        let s2 = c.start(req(11), dir.path(), Limits::default()).unwrap();
        let cancelled = c.cancel(&s2.id).unwrap();
        assert_eq!(cancelled.state, State::Cancelled);
        assert_eq!(c.list().len(), 2);
        assert_eq!(c.list()[0].id, s2.id, "newest first");
        assert!(c.stop("nope").is_err());
        assert!(c.cancel("nope").is_err());
        assert!(c.get("nope").is_none());
    }

    #[test]
    fn denied_starts_are_failed_captures_that_ask_for_elevation() {
        let dir = tempfile::tempdir().unwrap();
        let f = fake(None);
        f.deny.store(true, Ordering::SeqCst);
        let c = Captures::new(f);
        let s = c.start(req(10), dir.path(), Limits::default()).unwrap();
        assert_eq!(s.state, State::Failed);
        assert!(s.needs_elevation);
        assert!(s.error.unwrap().contains("administrator"));
        // A failed capture does not block a new one.
        assert!(c.start(req(10), dir.path(), Limits::default()).is_ok());
    }

    #[test]
    fn captures_that_end_by_themselves_are_reaped() {
        let dir = tempfile::tempdir().unwrap();
        let c = Captures::new(fake(Some(Duration::from_millis(20))));
        let s = c.start(req(10), dir.path(), Limits::default()).unwrap();
        let t = Instant::now();
        let mut reaped = Vec::new();
        while reaped.is_empty() && t.elapsed() < Duration::from_secs(5) {
            std::thread::sleep(Duration::from_millis(10));
            reaped = c.reap();
        }
        assert_eq!(reaped, std::slice::from_ref(&s.id));
        assert_eq!(c.get(&s.id).unwrap().state, State::Done);
        assert!(!c.is_running(&s.id));
    }

    #[test]
    fn the_list_is_bounded_and_names_are_safe() {
        let dir = tempfile::tempdir().unwrap();
        let f = fake(None);
        f.deny.store(true, Ordering::SeqCst);
        let c = Captures::new(f);
        for _ in 0..(KEEP + 10) {
            c.start(req(10), dir.path(), Limits::default()).unwrap();
        }
        assert_eq!(c.list().len(), KEEP);
        let mut p = proc(7);
        p.name = "My App/..\\x.exe".into();
        let n = file_name(&p, Preset::HeapSnapshot, 5);
        assert_eq!(n.to_str().unwrap(), "My_App____x-7-heap-5.nettrace");
        assert!(!n.to_str().unwrap().contains('/'));
        let json = serde_json::to_value(c.list()[0].clone()).unwrap();
        assert_eq!(json["state"], "failed");
        assert_eq!(json["kind"], "cpu");
        assert_eq!(json["needsElevation"], true);
        let r: Request = serde_json::from_value(serde_json::json!({"pid": 3, "kind": "heap", "durationSec": null})).unwrap();
        assert_eq!(r.kind, Preset::HeapSnapshot);
        assert!(serde_json::from_value::<Request>(serde_json::json!({"pid": 3, "kind": "x"})).is_err());
    }
}

//! The built-in plugins: one binary, `debrief-plugins`, serves each of them in its own process
//! (`debrief-plugins --plugin <id>`). At start the host asks the binary for every built-in's manifest once
//! (`debrief-plugins --manifests`, a short run that loads no file); each plugin's process then starts on first use.

use crate::process::{PluginProcess, PluginSpec};
use crate::remote::RemotePlugin;
use debrief_core::Plugin;
use debrief_plugin_api::manifest::Manifest;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

/// The flag that prints every built-in's manifest (a JSON array) and exits.
pub const MANIFESTS_FLAG: &str = "--manifests";
/// The flag that serves one built-in.
pub const PLUGIN_FLAG: &str = "--plugin";
/// Longest the manifest run may take.
const MANIFESTS_TIMEOUT: Duration = Duration::from_secs(30);
/// Largest manifest list read.
const MAX_MANIFESTS_BYTES: usize = 4 << 20;

/// File name of the plugins binary on this platform (as bundled: no target-triple suffix).
pub fn binary_name() -> &'static str {
    if cfg!(windows) {
        "debrief-plugins.exe"
    } else {
        "debrief-plugins"
    }
}

/// Where the bundled plugins binary lives: next to the application executable (Tauri puts `externalBin`
/// sidecars there). `DEBRIEF_PLUGINS` overrides it in a debug build only: a release build ignores it (and logs its name
/// once), because the environment must not decide which program runs, possibly elevated. A test binary (in cargo's
/// `deps` folder, or `build/<package>/<hash>/out` since cargo 1.100) finds the one cargo built in the profile folder.
pub fn default_binary() -> PathBuf {
    default_binary_with(cfg!(debug_assertions), std::env::var_os(PLUGINS_VAR))
}

/// The variable that names another plugins binary (development builds only).
pub const PLUGINS_VAR: &str = "DEBRIEF_PLUGINS";

/// [`default_binary`] for a given build mode and value of [`PLUGINS_VAR`].
fn default_binary_with(debug: bool, env: Option<std::ffi::OsString>) -> PathBuf {
    if let Some(p) = paddock_env::dev_override::resolve(debug, PLUGINS_VAR, env) {
        return PathBuf::from(p);
    }
    let dir = std::env::current_exe()
        .ok()
        .and_then(|e| e.parent().map(PathBuf::from))
        .unwrap_or_default();
    binary_in(&dir, debug)
}

fn binary_in(dir: &Path, debug: bool) -> PathBuf {
    let here = dir.join(binary_name());
    // A release build never guesses a program path: the plugins are beside the executable. A development build run as a test
    // program is in cargo's `deps` folder, or in `build/<package>/<hash>/out` since cargo 1.100: the plugins cargo built are
    // in the profile folder above either.
    match paddock_env::cargo_layout::profile_dir_of_dir(dir) {
        Some(profile) if debug && !here.exists() => profile.join(binary_name()),
        _ => here,
    }
}

/// Runs `exe --manifests` and reads the manifests it prints; every manifest is checked.
pub fn load_manifests(exe: &Path) -> Result<Vec<Manifest>, String> {
    load_manifests_within(exe, MANIFESTS_TIMEOUT)
}

/// [`load_manifests`] with another bound on the run (tests: a binary that never answers). The wait ends when the binary
/// exits (its output and exit are events, never polled: a poll's sleep was most of this short run, and under a throttled
/// process class a 20 ms sleep took about 93 ms); at the bound its whole tree is ended by identity and reaped (rule 53).
pub fn load_manifests_within(exe: &Path, bound: Duration) -> Result<Vec<Manifest>, String> {
    // The plugins binary is Debrief's own; it runs with a cleared environment and no stdin, without a console window.
    let mut cmd = paddock_proc::command(exe);
    cmd.arg(MANIFESTS_FLAG);
    paddock_proc::clean_env(&mut cmd, debrief_ipc::process::KEPT_ENV);
    // How it ended and how long it took is paddock_proc's `tool.run` line (a warning when it failed, with its error output).
    let limits = paddock_proc::Limits::new(bound).max_output(MAX_MANIFESTS_BYTES).stop_on_cap();
    let out = paddock_proc::run_bounded(cmd, limits).map_err(|e| match e {
        paddock_proc::RunError::NotFound(_) => format!("the plugins binary is missing ({}); reinstall Debrief", exe.display()),
        paddock_proc::RunError::Wait(..) => format!("the plugins could not be waited for ({}): {e}", exe.display()),
        _ => format!("cannot start the plugins ({}): {e}", exe.display()),
    })?;
    match out.outcome {
        paddock_proc::Outcome::Exited(status) if status.success() => {}
        paddock_proc::Outcome::Exited(status) => return Err(format!("the plugins could not describe themselves ({status})")),
        paddock_proc::Outcome::TimedOut => return Err("the plugins did not describe themselves in time".into()),
        paddock_proc::Outcome::OutputCap => {
            return Err(format!("the plugins wrote more than {} MiB", MAX_MANIFESTS_BYTES >> 20));
        }
    }
    let manifests: Vec<Manifest> = serde_json::from_slice(&out.stdout).map_err(|e| format!("the plugins' manifests are not valid: {e}"))?;
    for m in &manifests {
        m.check()?;
    }
    Ok(manifests)
}

/// The built-in plugins of this Debrief: their processes (one per plugin, shared by every window).
pub struct Builtins {
    processes: Vec<Arc<PluginProcess>>,
    /// Why the plugins are unavailable, when they are.
    problem: Option<String>,
}

impl Builtins {
    /// The built-ins `exe` serves, each granted what it asks for (they are first-party).
    pub fn load(exe: &Path) -> Builtins {
        Builtins::load_with(exe, |_| {})
    }

    /// Like [`Builtins::load`], with each plugin's start adjusted by `adjust` (tests: a connect window of
    /// [`debrief_ipc::process::UNTIL_CONNECTED`]).
    pub fn load_with(exe: &Path, adjust: impl Fn(&mut PluginSpec)) -> Builtins {
        match load_manifests(exe) {
            Ok(manifests) => Builtins::from_manifests_with(exe, manifests, adjust),
            Err(e) => {
                log::error!("Plugins unavailable: {e}");
                Builtins {
                    processes: Vec::new(),
                    problem: Some(e),
                }
            }
        }
    }

    /// Processes for `manifests` served by `exe`.
    pub fn from_manifests(exe: &Path, manifests: Vec<Manifest>) -> Builtins {
        Builtins::from_manifests_with(exe, manifests, |_| {})
    }

    /// [`Builtins::from_manifests`], each spec adjusted by `adjust`.
    pub fn from_manifests_with(exe: &Path, manifests: Vec<Manifest>, adjust: impl Fn(&mut PluginSpec)) -> Builtins {
        let processes = manifests
            .into_iter()
            .map(|m| {
                let mut spec = PluginSpec::new(exe, &m.id);
                spec.granted = m.permissions.iter().map(|p| p.permission).collect();
                adjust(&mut spec);
                PluginProcess::new(m, spec)
            })
            .collect();
        Builtins { processes, problem: None }
    }

    /// Adds an installed third-party plugin's process (ADR 0027); a built-in with the same id wins.
    pub fn add_installed(&mut self, process: Arc<PluginProcess>) -> Result<(), String> {
        if self.processes.iter().any(|p| p.id() == process.id()) {
            return Err(format!("plugin \"{}\" is already part of Debrief", process.id()));
        }
        self.processes.push(process);
        Ok(())
    }

    /// Settings ▸ Performance's limits for every plugin process here (from each one's next start).
    pub fn set_limits(&self, limits: &crate::PluginLimits) {
        for p in &self.processes {
            p.set_limits(limits.clone());
        }
    }

    /// No plugins (safe mode).
    pub fn none() -> Builtins {
        Builtins {
            processes: Vec::new(),
            problem: None,
        }
    }

    /// Why no plugin is available, when the plugins binary could not be used.
    pub fn problem(&self) -> Option<&str> {
        self.problem.as_deref()
    }

    /// One plugin per process, to install into a window's registry.
    pub fn plugins(&self) -> Vec<Arc<dyn Plugin>> {
        self.processes
            .iter()
            .map(|p| Arc::new(RemotePlugin::new(p.clone())) as Arc<dyn Plugin>)
            .collect()
    }

    pub fn process(&self, id: &str) -> Option<&Arc<PluginProcess>> {
        self.processes.iter().find(|p| p.id() == id)
    }

    pub fn processes(&self) -> &[Arc<PluginProcess>] {
        &self.processes
    }

    /// Starts every plugin's process in the background, so the first import does not wait for one.
    pub fn warm_up(&self) {
        for p in &self.processes {
            let p = p.clone();
            let _ = std::thread::Builder::new()
                .name("debrief-plugin-start".into())
                .spawn(move || p.warm_up());
        }
    }

    /// Stops every plugin process (on exit; they would also exit when Debrief does).
    pub fn shutdown(&self) {
        // Together: each stop may wait for its process (a hung one is killed after its grace), and one after the other two
        // hung plugins overran the worker's whole stop budget.
        std::thread::scope(|scope| {
            for p in &self.processes {
                scope.spawn(move || p.shutdown());
            }
        });
    }
}

#[cfg(test)]
