//! The disk test's scratch folder (ADR 0030 section 1): made by the agent inside a folder Dyno owns (the temp folder for the
//! system drive, `<mount>/.dyno-bench-<run>` for another drive), recorded with its identity before the child starts, and removed
//! when the kind ends, whatever the child did. If the agent itself dies mid-run, the next start removes a folder only when the
//! record's identity still matches what is on disk (rule 53: never by name alone, a name can be reused by someone else).
//! The scratch file inside is the runner's business and cannot outlive the child ([`dyno_bench::disk::scratch`]).

use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

/// Prefix of every folder this module makes, so cleanup refuses anything else.
pub const FOLDER_PREFIX: &str = ".dyno-bench-";

/// A folder the agent made and has not yet removed.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ScratchRecord {
    /// The folder.
    pub path: String,
    /// Its identity when it was made (device and inode; volume serial and file index on Windows).
    pub identity: String,
}

/// The records file next to the history.
pub fn records_file(history: &Path) -> PathBuf {
    history.with_file_name("bench-scratch.json")
}

/// A folder's identity, `None` when it cannot be read.
pub fn identity_of(path: &Path) -> Option<String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let m = std::fs::symlink_metadata(path).ok()?;
        Some(format!("{}:{}", m.dev(), m.ino()))
    }
    #[cfg(windows)]
    {
        let f = dyno_platform::fileid::file_facts(path).ok()?;
        Some(format!("{}:{}", f.volume, f.index))
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = path;
        None
    }
}

/// Reads the records; damage means none.
pub fn read_records(file: &Path) -> Vec<ScratchRecord> {
    std::fs::read_to_string(file)
        .ok()
        .and_then(|t| serde_json::from_str(&t).ok())
        .unwrap_or_default()
}

fn write_records(file: &Path, records: &[ScratchRecord]) -> std::io::Result<()> {
    if records.is_empty() {
        return match std::fs::remove_file(file) {
            Err(e) if e.kind() != std::io::ErrorKind::NotFound => Err(e),
            _ => Ok(()),
        };
    }
    std::fs::write(file, serde_json::to_string(records).map_err(std::io::Error::other)?)
}

/// Where the scratch folder of a drive goes: the system drive uses `scratch_root` (the temp folder: the volume the system
/// itself writes to; a Mac's root is read-only), any other drive its own hidden folder at its top.
pub fn folder_path(mount: &Path, is_system: bool, scratch_root: &Path, run_id: &str) -> PathBuf {
    let name = format!("{FOLDER_PREFIX}{run_id}");
    if is_system {
        scratch_root.join(name)
    } else {
        mount.join(name)
    }
}

/// A scratch folder that is removed, and forgotten, when it is dropped.
pub struct ScratchFolder {
    path: PathBuf,
    records: PathBuf,
}

impl ScratchFolder {
    /// Makes the folder (it must not exist) and records its identity before anything is written into it.
    pub fn create(path: &Path, records: &Path) -> std::io::Result<ScratchFolder> {
        std::fs::create_dir(path)?;
        let folder = ScratchFolder {
            path: path.to_path_buf(),
            records: records.to_path_buf(),
        };
        let Some(identity) = identity_of(path) else {
            // Cannot be recorded, so a crash could not be cleaned up by identity: do not start (the drop removes the folder).
            return Err(std::io::Error::other("the new scratch folder's identity cannot be read"));
        };
        let mut all = read_records(records);
        all.retain(|r| r.path != path.to_string_lossy());
        all.push(ScratchRecord {
            path: path.to_string_lossy().into_owned(),
            identity,
        });
        write_records(records, &all)?;
        Ok(folder)
    }

    /// Whether Dyno can create and remove a file here: asked before the run, so a permission prompt (macOS removable and network
    /// volumes) appears while the person is at the picker, never in the middle of a run.
    pub fn probe(&self) -> std::io::Result<()> {
        let f = self.path.join(".dyno-probe");
        std::fs::File::create_new(&f)?;
        std::fs::remove_file(&f)
    }

    /// The folder.
    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for ScratchFolder {
    fn drop(&mut self) {
        let removed = std::fs::remove_dir_all(&self.path);
        log::info!("dyno-agent: scratch folder removed: {}", removed.is_ok());
        if removed.is_ok() || !self.path.exists() {
            let mut all = read_records(&self.records);
            let before = all.len();
            all.retain(|r| r.path != self.path.to_string_lossy());
            if all.len() != before {
                let _ = write_records(&self.records, &all);
            }
        }
    }
}

/// At the agent's start: removes the folders an earlier agent left (it died mid-run) whose identity still matches their record,
/// and forgets every record. Returns what it removed, for the log.
pub fn cleanup_leftovers(records: &Path) -> Vec<String> {
    let all = read_records(records);
    let mut removed = Vec::new();
    for r in &all {
        let p = Path::new(&r.path);
        let ours = p.file_name().is_some_and(|n| n.to_string_lossy().starts_with(FOLDER_PREFIX))
            && identity_of(p).as_deref() == Some(r.identity.as_str());
        if ours && std::fs::remove_dir_all(p).is_ok() {
            removed.push(r.path.clone());
        } else if p.exists() {
            log::info!("dyno-agent: a scratch folder record does not match what is on disk; the folder is left alone");
        }
    }
    let _ = write_records(records, &[]);
    removed
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_system_drive_uses_the_scratch_root_and_another_drive_its_own_top_folder() {
        let root = Path::new("/tmp");
        assert_eq!(folder_path(Path::new("/"), true, root, "7"), Path::new("/tmp/.dyno-bench-7"));
        assert_eq!(
            folder_path(Path::new("/Volumes/USB"), false, root, "7"),
            Path::new("/Volumes/USB/.dyno-bench-7")
        );
    }

    #[test]
    fn a_folder_is_recorded_when_made_and_removed_and_forgotten_when_dropped() {
        let d = paddock_testkit::private_tempdir().unwrap();
        let rec = d.path().join("rec.json");
        let p = d.path().join(".dyno-bench-1");
        let f = ScratchFolder::create(&p, &rec).unwrap();
        assert!(p.is_dir());
        assert_eq!(read_records(&rec).len(), 1);
        f.probe().unwrap();
        assert_eq!(std::fs::read_dir(&p).unwrap().count(), 0, "the probe removes its file");
        drop(f);
        assert!(!p.exists());
        assert!(!rec.exists(), "no records left");
    }

    #[test]
    fn a_folder_that_exists_is_never_taken_over() {
        let d = paddock_testkit::private_tempdir().unwrap();
        let p = d.path().join(".dyno-bench-1");
        std::fs::create_dir(&p).unwrap();
        std::fs::write(p.join("theirs"), b"x").unwrap();
        assert!(ScratchFolder::create(&p, &d.path().join("rec.json")).is_err());
        assert!(p.join("theirs").exists());
    }

    #[test]
    fn restart_cleanup_removes_a_folder_whose_identity_matches() {
        let d = paddock_testkit::private_tempdir().unwrap();
        let rec = d.path().join("rec.json");
        let p = d.path().join(".dyno-bench-2");
        // The agent died: the folder and its record stay (forget = no drop).
        std::mem::forget(ScratchFolder::create(&p, &rec).unwrap());
        std::fs::write(p.join("leftover"), b"x").unwrap();
        assert_eq!(cleanup_leftovers(&rec), vec![p.to_string_lossy().into_owned()]);
        assert!(!p.exists());
        assert!(!rec.exists());
    }

    #[test]
    fn restart_cleanup_leaves_a_folder_whose_identity_does_not_match() {
        let d = paddock_testkit::private_tempdir().unwrap();
        let rec = d.path().join("rec.json");
        let p = d.path().join(".dyno-bench-3");
        std::mem::forget(ScratchFolder::create(&p, &rec).unwrap());
        // Someone removed it and made another folder under the same name: not ours any more.
        std::fs::remove_dir(&p).unwrap();
        std::fs::create_dir(&p).unwrap();
        std::fs::write(p.join("theirs"), b"x").unwrap();
        // The identity of a recreated directory can repeat on some file systems (the inode is reused): make the record unmistakably stale.
        let mut all = read_records(&rec);
        all[0].identity = "0:0".into();
        write_records(&rec, &all).unwrap();
        assert!(cleanup_leftovers(&rec).is_empty());
        assert!(p.join("theirs").exists());
        assert!(!rec.exists(), "the record is dropped either way");
    }

    #[test]
    fn restart_cleanup_refuses_a_name_that_is_not_ours_even_with_a_matching_identity() {
        let d = paddock_testkit::private_tempdir().unwrap();
        let rec = d.path().join("rec.json");
        let p = d.path().join("Documents");
        std::fs::create_dir(&p).unwrap();
        write_records(
            &rec,
            &[ScratchRecord {
                path: p.to_string_lossy().into_owned(),
                identity: identity_of(&p).unwrap(),
            }],
        )
        .unwrap();
        assert!(cleanup_leftovers(&rec).is_empty());
        assert!(p.is_dir());
    }

    #[test]
    fn damaged_records_mean_none() {
        let d = paddock_testkit::private_tempdir().unwrap();
        let rec = d.path().join("rec.json");
        std::fs::write(&rec, b"not json").unwrap();
        assert!(read_records(&rec).is_empty());
        assert!(cleanup_leftovers(&rec).is_empty());
    }
}

//! The large and duplicate file finder, as a job: walks a folder the user chose in parallel (bounded in files, depth and bytes
//! compared, never following links), then hashes only files that share a size, the heads first and the contents of those whose
//! heads agree, also in parallel. Every phase reports a growing count on its own scale and checks Cancel per entry and per
//! chunk; results come back in input order whatever the scheduling, so the answer does not depend on timing. It lists and
//! deletes nothing and builds its answer on the side: a cancelled scan leaves nothing behind.
//!
//! A folder on a dead network share can hold a `read_dir` or a `stat` inside the kernel for as long as the server is gone. The
//! work therefore runs on a thread of its own and the job waits for it with Cancel able to wake the wait: Cancel returns at once,
//! the thread is left to finish when the OS lets it, and its threads count on the host in the disk map's own per-host count
//! (`LiveWorkers`) until the call returns, so a host with four stuck threads gets no new search or scan.

use crate::disk::centre::{HostThreads, MAX_ABANDONED_PER_HOST};
use crate::disk::engine::{LiveGuard, LiveWorkers};
use dyno_core::extras::files::{
    duplicate_groups, largest, same_size_groups, FinderLimit, FinderMode, FinderQuery, FinderResult, LimitHit, Walked,
};
use dyno_core::time::Timestamp;
use paddock_jobs::{
    copy_hashed, par_map_ordered, par_walk, CancelReason, Decision, EntryKind, HashingWriter, JobContext, JobError, Phase, SymlinkPolicy,
    WalkOptions, Workers,
};
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::time::Duration;

/// The first bytes hashed to rule out most non-duplicates cheaply.
const HEAD: u64 = 64 * 1024;
/// How long the first look at the chosen folder may take before the search is refused (a dead share must not hold the job).
pub const STAT_LIMIT: Duration = Duration::from_secs(5);

/// What one scan may spend: the Settings `disk.finderFiles`, `finderDepth` and `finderHashGib` (their defaults when nobody changed them).
pub use dyno_core::extras::files::FinderLimits as Limits;

/// The folder as the finder will use it, or what to fix.
pub fn resolve_root(folder: &str) -> Result<PathBuf, String> {
    let p = Path::new(folder);
    if !p.is_absolute() {
        return Err("Give the full path of the folder.".into());
    }
    let root = std::fs::canonicalize(p).map_err(|e| format!("That folder cannot be opened ({e}). Choose another one."))?;
    if !root.is_dir() {
        return Err("Choose a folder, not a file.".into());
    }
    if root.parent().is_none() {
        return Err("Choose a folder, not a whole drive: a scan of everything takes too long and finds mostly system files.".into());
    }
    Ok(root)
}

/// [`resolve_root`] that gives up after `limit`: a dead share can hold the look at it for as long as the server is gone.
fn resolve_within(folder: &str, limit: Duration) -> Result<PathBuf, String> {
    let folder = folder.to_string();
    // The start of the search waits for it within a deadline: live work; the walk is bulk (rule 52).
    crate::disk::volumes::within(limit, dyno_platform::priority::ThreadRole::Live, move || resolve_root(&folder)).unwrap_or_else(|| {
        Err("That folder did not answer in time. Check that the drive or share is reachable, or choose another folder.".into())
    })
}

/// Which host a search reads and the threads of it that are stuck: a search Cancel abandoned while the OS still holds a call of
/// its keeps its threads counted on that host (the disk map's count, `LiveWorkers`) until the calls return, and a new search of a
/// host with [`MAX_ABANDONED_PER_HOST`] of them is refused.
pub struct Linger {
    host: String,
    live: Arc<LiveWorkers>,
    /// Stuck threads of the host when the search started.
    stuck: usize,
    /// The most that may be stuck before a search is refused.
    most: usize,
    /// How many threads this search reads with (they all count if it is abandoned: they are inside its walk).
    weight: usize,
}

impl Linger {
    /// The host's count as the disk map keeps it, for a search that reads with `threads` threads.
    pub fn of(host: HostThreads, threads: usize) -> Linger {
        Linger {
            host: host.host,
            live: host.live,
            stuck: host.abandoned,
            most: MAX_ABANDONED_PER_HOST,
            weight: threads.max(1),
        }
    }

    /// A count of its own and its own maximum (tests).
    pub fn counting(live: Arc<LiveWorkers>, stuck: usize, most: usize, weight: usize) -> Linger {
        Linger {
            host: "this computer".into(),
            live,
            stuck,
            most,
            weight,
        }
    }
}

/// Runs `work` on a thread of its own and waits for it; Cancel wakes the wait at once and abandons the thread (it ends when
/// the call it is stuck in returns, and it stops at its next cancel check). While it lingers, its `weight` threads count on the
/// host.
fn abandonable<T: Send + 'static>(
    ctx: &JobContext,
    linger: Linger,
    work: impl FnOnce(&JobContext) -> Result<T, JobError> + Send + 'static,
) -> Result<T, JobError> {
    if linger.stuck >= linger.most {
        return Err(JobError::Failed(format!(
            "{} still has {} reads that have not returned, so Dyno will not start another search there. Restarting Dyno clears it.",
            linger.host, linger.stuck
        )));
    }
    enum Wake<T> {
        Done(Result<T, JobError>),
        Cancelled,
    }
    let (tx, rx) = mpsc::channel::<Wake<T>>();
    // The guards of an abandoned search: taken when Cancel gives up on the thread, dropped when the thread ends.
    let held: Arc<Mutex<Option<Vec<LiveGuard>>>> = Arc::new(Mutex::new(Some(Vec::new())));
    let thread = {
        let (ctx, tx, held) = (ctx.clone(), tx.clone(), held.clone());
        std::thread::Builder::new().name("dyno-finder".into()).spawn(move || {
            lowered("search");
            let result = work(&ctx);
            // Over: whatever was counted for it comes off, and nothing may be counted afterwards.
            *held.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = None;
            let _ = tx.send(Wake::Done(result));
        })
    };
    if thread.is_err() {
        return Err(JobError::Failed("Dyno could not start the search.".into()));
    }
    let _wake = ctx.cancel_token().on_cancel(move || {
        let _ = tx.send(Wake::Cancelled);
    });
    match rx.recv() {
        Ok(Wake::Done(result)) => result,
        Ok(Wake::Cancelled) | Err(_) => {
            if let Some(guards) = held.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_mut() {
                guards.extend((0..linger.weight).map(|_| linger.live.enter()));
            }
            Err(JobError::Cancelled(ctx.cancel_token().reason().unwrap_or(CancelReason::User)))
        }
    }
}

/// Lowers the thread a part of the search runs on, gently and once (rule 52): the search's own thread and the workers of the
/// shared walk and map, which start their threads themselves and do not pass on the class of the thread that asked.
fn lowered(_part: &'static str) {
    dyno_platform::priority::lower_current_thread_once();
    #[cfg(all(test, target_os = "macos"))]
    tests::saw(_part, dyno_platform::priority::current_qos_class());
}

/// What the walk found.
struct Walk {
    files: Vec<Walked>,
    scanned: u32,
    unreadable: u32,
    limit: Option<FinderLimit>,
}

/// Walks `root` on `workers` threads and collects the files of at least `min_bytes` (path and size, sorted by path), counting every
/// file found as it goes. Stops at a limit and says which; stops with an error when cancelled.
fn walk(ctx: &JobContext, root: &Path, min_bytes: u64, limits: Limits, workers: Workers) -> Result<Walk, JobError> {
    ctx.phase(Phase::discovering("walk", "Listing files"));
    let seen = Arc::new(AtomicUsize::new(0));
    let too_many = Arc::new(AtomicBool::new(false));
    let too_deep = Arc::new(AtomicBool::new(false));
    let (s, many, deep, base, max_files, max_depth) = (
        seen.clone(),
        too_many.clone(),
        too_deep.clone(),
        root.to_path_buf(),
        limits.files,
        limits.depth,
    );
    let options = WalkOptions {
        workers,
        symlinks: SymlinkPolicy::Ignore,
        // Folders more than `depth` levels down are not read; the filter flags that one was left out.
        max_depth: Some(max_depth as usize),
        include_dirs: false,
        with_size: true,
        with_modified: true,
        issue_cap: 0,
        ..WalkOptions::default()
    }
    .with_filter(move |e| {
        lowered("walk");
        if s.fetch_add(1, Ordering::Relaxed) >= max_files {
            many.store(true, Ordering::Relaxed);
            return Decision::SkipSubtree;
        }
        if e.kind == EntryKind::Dir && e.path.strip_prefix(&base).map_or(0, |p| p.components().count()) > max_depth as usize {
            deep.store(true, Ordering::Relaxed);
        }
        Decision::Include
    });
    let found = par_walk(root, &options, ctx.cancel_token(), ctx)?;
    let files = found
        .entries
        .into_iter()
        .filter(|e| e.kind == EntryKind::File)
        .filter_map(|e| {
            let bytes = e.size.filter(|b| *b >= min_bytes)?;
            Some(Walked {
                path: e.path.to_string_lossy().into_owned(),
                bytes,
                modified: e.modified.map_or(Timestamp(0), timestamp),
            })
        })
        .collect();
    let limit = if too_many.load(Ordering::Relaxed) {
        Some(FinderLimit::Files)
    } else if too_deep.load(Ordering::Relaxed) {
        Some(FinderLimit::Depth)
    } else {
        None
    };
    Ok(Walk {
        files,
        scanned: u32::try_from(seen.load(Ordering::Relaxed).min(max_files)).unwrap_or(u32::MAX),
        unreadable: u32::try_from(found.issues_total).unwrap_or(u32::MAX),
        limit,
    })
}

/// A modification time as a [`Timestamp`].
fn timestamp(t: std::time::SystemTime) -> Timestamp {
    t.duration_since(std::time::UNIX_EPOCH)
        .map_or(Timestamp(0), |d| Timestamp(i64::try_from(d.as_millis()).unwrap_or(i64::MAX)))
}

/// The digest of the start of a file, or `None` when it cannot be read. Only a cancel is an error.
fn head_digest(ctx: &JobContext, path: &Path) -> Result<Option<[u8; 32]>, JobError> {
    let Ok(f) = std::fs::File::open(path) else { return Ok(None) };
    hashed(ctx, f.take(HEAD), false)
}

/// The digest of a whole file, or `None` when it cannot be read. Progress counts the bytes read.
fn full_digest(ctx: &JobContext, path: &Path) -> Result<Option<[u8; 32]>, JobError> {
    let Ok(f) = std::fs::File::open(path) else { return Ok(None) };
    hashed(ctx, f, true)
}

fn hashed<R: Read>(ctx: &JobContext, mut reader: R, count_bytes: bool) -> Result<Option<[u8; 32]>, JobError> {
    let result = if count_bytes {
        copy_hashed(&mut reader, std::io::sink(), ctx.cancel_token(), ctx)
    } else {
        copy_hashed(&mut reader, std::io::sink(), ctx.cancel_token(), &())
    };
    match result {
        Ok((digest, _)) => Ok(Some(digest)),
        Err(e) => match HashingWriter::<std::io::Sink>::cancelled(&e) {
            Some(c) => Err(JobError::Cancelled(c.0)),
            None => Ok(None),
        },
    }
}

/// A file (by its index in the walk) and the digest of its content.
type Digest = (usize, [u8; 32]);

/// Hashes the files that share a size: first their heads, then the whole of those whose heads agree, each on `workers` threads
/// with the results in input order. A file that would take the comparison past `limits.hash_bytes` is skipped (and the limit
/// is reported) while smaller ones after it still count; which are skipped is decided up front from the sizes, so it does not
/// depend on scheduling.
fn find_duplicates(
    ctx: &JobContext,
    files: &[Walked],
    min_bytes: u64,
    limits: Limits,
    workers: Workers,
) -> Result<(Vec<Digest>, Option<FinderLimit>), JobError> {
    let groups = same_size_groups(files, min_bytes);
    let candidates: Vec<usize> = groups.iter().flatten().copied().collect();
    ctx.phase(Phase::items("heads", "Comparing the start of files", candidates.len() as u64));
    let heads = par_map_ordered(candidates, workers, ctx.cancel_token(), ctx, |i| {
        lowered("heads");
        head_digest(ctx, Path::new(&files[i].path)).map(|h| (i, h))
    })?;
    let head_of: std::collections::HashMap<usize, [u8; 32]> = heads.into_iter().filter_map(|(i, h)| h.map(|h| (i, h))).collect();
    // The files whose heads agree with another file of the same size, in the order of the groups.
    let mut same_heads: Vec<usize> = Vec::new();
    for group in &groups {
        let mut by_head: std::collections::BTreeMap<[u8; 32], Vec<usize>> = Default::default();
        for i in group {
            if let Some(h) = head_of.get(i) {
                by_head.entry(*h).or_default().push(*i);
            }
        }
        same_heads.extend(by_head.into_values().filter(|g| g.len() > 1).flatten());
    }
    let mut budget = limits.hash_bytes;
    let mut cut = None;
    let to_read: Vec<usize> = same_heads
        .into_iter()
        .filter(|i| {
            let size = files[*i].bytes;
            if size <= budget {
                budget -= size;
                true
            } else {
                cut = Some(FinderLimit::HashBytes);
                false
            }
        })
        .collect();
    let total: u64 = to_read.iter().map(|i| files[*i].bytes).sum();
    ctx.phase(Phase::bytes("contents", "Comparing contents", Some(total)));
    let digests = par_map_ordered(to_read, workers, ctx.cancel_token(), &(), |i| {
        lowered("contents");
        full_digest(ctx, Path::new(&files[i].path)).map(|h| (i, h))
    })?;
    Ok((digests.into_iter().filter_map(|(i, h)| h.map(|h| (i, h))).collect(), cut))
}

/// Runs the finder as the job `ctx` with `workers` threads reading the folder. `scan_id` names the result. A bad folder is a failed
/// job with what to fix; a folder that does not answer within [`STAT_LIMIT`] is refused with a sentence.
pub fn run(
    ctx: &JobContext,
    query: &FinderQuery,
    scan_id: &str,
    limits: Limits,
    workers: Workers,
    linger: Linger,
) -> Result<FinderResult, JobError> {
    let query = query.clone().validated().map_err(JobError::Failed)?;
    let root = resolve_within(&query.folder, STAT_LIMIT).map_err(JobError::Failed)?;
    let scan_id = scan_id.to_string();
    abandonable(ctx, linger, move |ctx| {
        let walked = walk(ctx, &root, query.min_bytes, limits, workers)?;
        let mut limit = walked.limit;
        let files = walked.files;
        let large = if query.mode == FinderMode::Duplicates {
            Vec::new()
        } else {
            largest(&files, query.min_bytes, &scan_id)
        };
        let duplicates = if query.mode == FinderMode::Large {
            Vec::new()
        } else {
            let (hashed, cut) = find_duplicates(ctx, &files, query.min_bytes, limits, workers)?;
            limit = limit.or(cut);
            duplicate_groups(&files, &hashed, &scan_id)
        };
        let wasted_bytes = duplicates.iter().fold(0u64, |a, g| a.saturating_add(g.wasted_bytes));
        Ok(FinderResult {
            scan_id,
            folder: root.to_string_lossy().into_owned(),
            large,
            duplicates,
            scanned: walked.scanned,
            unreadable: walked.unreadable,
            limit: limit.map(|l| LimitHit::new(l, &limits)),
            wasted_bytes,
        })
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::jobs::testing::Run;
    use paddock_jobs::JobState;

    const MB: usize = 1024 * 1024;

    fn lg() -> Linger {
        Linger::counting(Arc::new(LiveWorkers::default()), 0, 4, 4)
    }

    /// Four threads, as on an SSD.
    fn w(n: usize) -> Workers {
        Workers::new(n)
    }

    fn write(dir: &Path, name: &str, byte: u8, len: usize) -> PathBuf {
        let p = dir.join(name);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(&p, vec![byte; len]).unwrap();
        p
    }

    fn query(folder: &Path, mode: FinderMode) -> FinderQuery {
        FinderQuery {
            folder: folder.to_string_lossy().into_owned(),
            mode,
            min_bytes: 0,
        }
    }

    fn fixture() -> (paddock_testkit::PrivateTemp, PathBuf) {
        let t = paddock_testkit::private_tempdir().unwrap();
        let root = std::fs::canonicalize(t.path()).unwrap().join("stuff");
        write(&root, "big.bin", 1, 5 * MB);
        write(&root, "copy1/a.iso", 7, 2 * MB);
        write(&root, "copy2/a-again.iso", 7, 2 * MB);
        // Same size, different content: not a duplicate.
        write(&root, "other/b.iso", 8, 2 * MB);
        write(&root, "tiny.txt", 1, 10);
        (t, root)
    }

    fn find(root: &Path, mode: FinderMode) -> Result<FinderResult, JobError> {
        Run::new().job(|ctx| run(ctx, &query(root, mode), "s", Limits::default(), w(4), lg()))
    }

    /// The QoS class each part of a search ran at, per thread (every finder test adds to it).
    #[cfg(target_os = "macos")]
    static SEEN: Mutex<Vec<(&'static str, u32)>> = Mutex::new(Vec::new());

    #[cfg(target_os = "macos")]
    pub(super) fn saw(part: &'static str, class: u32) {
        SEEN.lock().unwrap_or_else(std::sync::PoisonError::into_inner).push((part, class));
    }

    /// The person started the search and watches it, so every thread of it (its own, the walk's and the comparison's workers)
    /// is lowered gently, never starved (rule 52): `UTILITY` on macOS.
    #[cfg(target_os = "macos")]
    #[test]
    fn every_thread_of_a_search_runs_at_the_gentle_level() {
        let (_t, root) = fixture();
        assert_eq!(find(&root, FinderMode::Both).unwrap().duplicates.len(), 1);
        let seen = SEEN.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone();
        for part in ["search", "walk", "heads", "contents"] {
            assert!(seen.iter().any(|(p, _)| *p == part), "{part} never ran: {seen:?}");
        }
        assert!(seen.iter().all(|(_, c)| *c == dyno_platform::priority::UTILITY), "{seen:?}");
    }

    #[test]
    fn finds_the_biggest_files_and_only_real_duplicates() {
        let (_t, root) = fixture();
        let r = find(&root, FinderMode::Both).unwrap();
        assert_eq!(r.large[0].path, root.join("big.bin").to_string_lossy());
        assert_eq!(r.large.len(), 4, "the tiny file is below the 1 MiB floor");
        assert_eq!(r.duplicates.len(), 1, "{:#?}", r.duplicates);
        assert_eq!(r.duplicates[0].files.len(), 2);
        assert_eq!(r.wasted_bytes, 2 * MB as u64);
        assert_eq!(r.limit, None);
        let only_large = find(&root, FinderMode::Large).unwrap();
        assert!(only_large.duplicates.is_empty() && !only_large.large.is_empty());
        let only_dups = find(&root, FinderMode::Duplicates).unwrap();
        assert!(only_dups.large.is_empty() && only_dups.duplicates.len() == 1);
    }

    #[test]
    fn bad_folders_say_what_to_fix() {
        assert!(resolve_root("relative/path").unwrap_err().contains("full path"));
        let (_t, root) = fixture();
        // Absolute on every platform (a bare "/x" has no drive on Windows), and not there.
        assert!(resolve_root(&root.join("not").join("here").to_string_lossy())
            .unwrap_err()
            .contains("cannot be opened"));
        assert!(resolve_root(&root.join("big.bin").to_string_lossy())
            .unwrap_err()
            .contains("not a file"));
        let top = if cfg!(windows) { "C:\\" } else { "/" };
        assert!(resolve_root(top).unwrap_err().contains("whole drive"));
        let blank = FinderQuery {
            folder: " ".into(),
            mode: FinderMode::Both,
            min_bytes: 0,
        };
        let out = Run::new().job(|ctx| run(ctx, &blank, "s", Limits::default(), w(4), lg()));
        assert!(matches!(out, Err(JobError::Failed(m)) if m.contains("Choose a folder")));
    }

    #[cfg(unix)]
    #[test]
    fn links_are_never_followed() {
        let (_t, root) = fixture();
        std::os::unix::fs::symlink(&root, root.join("loop")).unwrap();
        std::os::unix::fs::symlink(root.join("big.bin"), root.join("link.bin")).unwrap();
        let r = find(&root, FinderMode::Both).unwrap();
        assert!(r.large.iter().all(|f| !f.path.contains("loop") && !f.path.ends_with("link.bin")));
    }

    #[test]
    fn each_phase_counts_up_from_the_first_report_on_its_own_scale() {
        let (_t, root) = fixture();
        let job = Run::new();
        job.job(|ctx| run(ctx, &query(&root, FinderMode::Both), "s", Limits::default(), w(4), lg()))
            .unwrap();
        let phases = job.phases();
        assert_eq!(
            phases.iter().map(|p| p.id.as_str()).collect::<Vec<_>>(),
            ["walk", "heads", "contents"]
        );
        // Queued, started, then the walk at once: a count with no total (a growing count, never a static 0).
        assert!(
            matches!(job.snapshots()[2].state, JobState::Running { phase: Some(ref p) } if p.phase.id == "walk" && p.phase.total.is_none())
        );
        for p in &phases {
            assert!(p.counts.windows(2).all(|w| w[0] <= w[1]), "{} went backwards: {:?}", p.id, p.counts);
        }
        // The walk counts every file it finds (5); the later phases know their totals: the 3 that share a size, and the 4 MiB of
        // the two whose starts agree.
        assert_eq!(phases[0].counts.last(), Some(&5));
        assert_eq!((phases[1].total, phases[1].counts.last().copied()), (Some(3), Some(3)));
        assert_eq!(
            (phases[2].total, phases[2].counts.last().copied()),
            (Some(4 * MB as u64), Some(4 * MB as u64))
        );
        assert_eq!(job.end_state(), JobState::Done);
    }

    #[test]
    fn the_walk_stops_at_each_limit_and_names_it() {
        let (_t, root) = fixture();
        let q = query(&root, FinderMode::Both);
        let few = Run::new()
            .job(|ctx| {
                run(
                    ctx,
                    &q,
                    "s",
                    Limits {
                        files: 2,
                        ..Limits::default()
                    },
                    w(4),
                    lg(),
                )
            })
            .unwrap();
        assert_eq!((few.limit.map(|l| l.limit), few.scanned), (Some(FinderLimit::Files), 2));
        // Depth 0: the chosen folder's own files are read, the folders below it are left out.
        let shallow = Run::new()
            .job(|ctx| {
                run(
                    ctx,
                    &q,
                    "s",
                    Limits {
                        depth: 0,
                        ..Limits::default()
                    },
                    w(4),
                    lg(),
                )
            })
            .unwrap();
        assert_eq!(shallow.limit.map(|l| l.limit), Some(FinderLimit::Depth));
        assert_eq!(shallow.large.len(), 1);
        // Comparing contents may read 1 MiB at most: the 4 MiB of candidates are over it.
        let small = Run::new()
            .job(|ctx| {
                run(
                    ctx,
                    &q,
                    "s",
                    Limits {
                        hash_bytes: MB as u64,
                        ..Limits::default()
                    },
                    w(4),
                    lg(),
                )
            })
            .unwrap();
        assert_eq!(small.limit.as_ref().map(|l| l.limit), Some(FinderLimit::HashBytes));
        assert!(small.limit.unwrap().message.contains("Some duplicates may be missing"));
        assert!(small.duplicates.is_empty());
        for l in [FinderLimit::Files, FinderLimit::Depth, FinderLimit::HashBytes] {
            let m = l.message(&Limits {
                files: 7,
                depth: 3,
                hash_bytes: 5 * 1024 * 1024 * 1024,
            });
            assert!(m.to_lowercase().contains("choose") && m.contains("Settings"), "{m}");
            assert!(
                m.contains(
                    &["7 files", "3 levels", "5 GiB"]
                        .iter()
                        .find(|x| m.contains(*x))
                        .copied()
                        .unwrap_or("?")
                        .to_string()
                ),
                "the numbers are the scan's own: {m}"
            );
        }
    }

    #[test]
    fn cancel_stops_a_parallel_walk_long_before_it_would_have_finished() {
        // A walker looks at the cancel every `CANCEL_CHECK_ITEMS` entries of a folder (counting them first) and starts no
        // folder after it, so a cancel at the first count leaves at most two such batches per worker counted. The fixture
        // is sized from that bound, not larger: creating files is slow on Windows (16 000 took 30 to 60 s on the CI runner
        // and ran into the test timeout, CI run 7166).
        use paddock_jobs::CANCEL_CHECK_ITEMS;
        const WORKERS: usize = 2;
        const DIRS: usize = 8;
        const PER_DIR: usize = CANCEL_CHECK_ITEMS + CANCEL_CHECK_ITEMS / 4;
        let bound = (WORKERS * 2 * CANCEL_CHECK_ITEMS) as u64;
        let total = (DIRS * PER_DIR) as u64;
        assert!(bound < total / 2, "the fixture is big enough to tell a stop from a finish");
        let t = paddock_testkit::private_tempdir().unwrap();
        let root = std::fs::canonicalize(t.path()).unwrap().join("many");
        for d in 0..DIRS {
            std::fs::create_dir_all(root.join(format!("d{d}"))).unwrap();
            for i in 0..PER_DIR {
                std::fs::write(root.join(format!("d{d}")).join(format!("f{i}")), b"x").unwrap();
            }
        }
        let job = Run::new().cancel_when("walk", 100);
        let out = job.job(|ctx| run(ctx, &query(&root, FinderMode::Both), "s", Limits::default(), w(WORKERS), lg()));
        assert!(matches!(out, Err(JobError::Cancelled(_))));
        let seen = job.phases()[0].counts.last().copied().unwrap();
        assert!(
            seen <= bound,
            "looked at {seen} of {total} entries after the cancel (at most {bound})"
        );
        assert!(matches!(job.end_state(), JobState::Cancelled { .. }));
        assert_eq!(std::fs::read_dir(&root).unwrap().count(), DIRS, "nothing was changed");
    }

    #[test]
    fn the_answer_does_not_depend_on_how_many_threads_read_the_folder() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let root = std::fs::canonicalize(t.path()).unwrap().join("tree");
        for d in 0..6 {
            write(&root, &format!("d{d}/same-a.bin"), 3, 2 * MB);
            write(&root, &format!("d{d}/own-{d}.bin"), d as u8 + 10, MB + d * 1000);
            write(&root, &format!("d{d}/sub/same-b.bin"), 4, MB + 5);
        }
        let by = |n| {
            Run::new()
                .job(|ctx| run(ctx, &query(&root, FinderMode::Both), "s", Limits::default(), w(n), lg()))
                .unwrap()
        };
        let (one, many) = (by(1), by(8));
        assert_eq!(one, many, "same files, same order, same ids");
        assert_eq!(one.duplicates.len(), 2);
        assert!(one.duplicates.iter().all(|g| g.files.len() == 6));
    }

    #[test]
    fn a_file_over_the_comparison_budget_is_skipped_and_the_rest_are_still_compared() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let root = std::fs::canonicalize(t.path()).unwrap().join("budget");
        // The biggest pair is first in the order of the groups and does not fit; the smaller pair after it does.
        write(&root, "big1.bin", 1, 3 * MB);
        write(&root, "big2.bin", 1, 3 * MB);
        write(&root, "small1.bin", 2, MB + 1);
        write(&root, "small2.bin", 2, MB + 1);
        let r = Run::new()
            .job(|ctx| {
                run(
                    ctx,
                    &query(&root, FinderMode::Duplicates),
                    "s",
                    Limits {
                        hash_bytes: 5 * MB as u64 / 2,
                        ..Limits::default()
                    },
                    w(4),
                    lg(),
                )
            })
            .unwrap();
        assert_eq!(r.limit.as_ref().map(|l| l.limit), Some(FinderLimit::HashBytes));
        assert_eq!(r.duplicates.len(), 1, "{:#?}", r.duplicates);
        assert_eq!(r.duplicates[0].bytes_each, MB as u64 + 1);
    }

    #[cfg(unix)]
    #[test]
    fn folders_that_could_not_be_read_are_counted_and_the_rest_is_still_listed() {
        use std::os::unix::fs::PermissionsExt;
        let (_t, root) = fixture();
        let locked = root.join("locked");
        std::fs::create_dir_all(&locked).unwrap();
        std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o000)).unwrap();
        let unreadable_here = std::fs::read_dir(&locked).is_err();
        let r = find(&root, FinderMode::Both).unwrap();
        std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o755)).unwrap();
        // Running as root can read anything; only assert the count when the folder really is closed.
        if unreadable_here {
            assert_eq!(r.unreadable, 1);
        }
        assert_eq!(r.large.len(), 4, "the rest is listed");
        assert_eq!(find(&root, FinderMode::Both).unwrap().unreadable, 0);
    }

    #[test]
    fn cancel_returns_at_once_while_a_call_is_stuck_and_its_threads_count_on_the_host_until_they_return() {
        let live = Arc::new(LiveWorkers::default());
        let door = Arc::new((std::sync::Mutex::new(false), std::sync::Condvar::new()));
        let entered = Arc::new(AtomicBool::new(false));
        let (d, e, l) = (door.clone(), entered.clone(), live.clone());
        let started = std::time::Instant::now();
        let out = Run::new().job(|ctx| {
            let token = ctx.cancel_token().clone();
            let watcher = e.clone();
            std::thread::spawn(move || {
                while !watcher.load(Ordering::SeqCst) {
                    std::thread::yield_now();
                }
                token.cancel();
            });
            abandonable(ctx, Linger::counting(l, 0, 4, 3), move |_ctx| {
                e.store(true, Ordering::SeqCst);
                // The OS call that does not come back until the share does.
                let mut open = d.0.lock().unwrap();
                while !*open {
                    open = d.1.wait(open).unwrap();
                }
                Ok(())
            })
        });
        assert!(matches!(out, Err(JobError::Cancelled(_))), "{out:?}");
        assert!(started.elapsed() < Duration::from_secs(5), "Cancel waited for the stuck call");
        assert_eq!(
            live.count(),
            3,
            "the search's walker threads are counted while they are inside the call"
        );
        *door.0.lock().unwrap() = true;
        door.1.notify_all();
        for _ in 0..500 {
            if live.count() == 0 {
                return;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        panic!("the threads never left the count");
    }

    #[test]
    fn a_search_that_finishes_normally_never_counts_and_one_that_ends_just_after_cancel_does_not_leak_a_count() {
        let live = Arc::new(LiveWorkers::default());
        let out = Run::new().job(|ctx| abandonable(ctx, Linger::counting(live.clone(), 0, 4, 4), |_ctx| Ok(1)));
        assert_eq!(out.unwrap(), 1);
        assert_eq!(live.count(), 0);
    }

    #[test]
    fn a_search_of_a_host_with_too_many_stuck_threads_is_refused_with_the_way_out() {
        let live = Arc::new(LiveWorkers::default());
        let out = Run::new().job(|ctx| abandonable(ctx, Linger::counting(live.clone(), 4, 4, 4), |_ctx| Ok(1)));
        let Err(JobError::Failed(m)) = out else { panic!("{out:?}") };
        assert!(
            m.contains("this computer still has 4 reads") && m.contains("Restarting Dyno clears it."),
            "{m}"
        );
        assert_eq!(
            Run::new()
                .job(|ctx| abandonable(ctx, Linger::counting(live.clone(), 3, 4, 4), |_ctx| Ok(1)))
                .unwrap(),
            1
        );
    }

    fn three_equal_files() -> (paddock_testkit::PrivateTemp, PathBuf, Vec<PathBuf>) {
        let t = paddock_testkit::private_tempdir().unwrap();
        let root = std::fs::canonicalize(t.path()).unwrap().join("dups");
        let paths: Vec<_> = (0..3).map(|i| write(&root, &format!("same{i}.bin"), 9, 6 * MB)).collect();
        (t, root, paths)
    }

    /// One reader thread reports (and so cancels, on its own thread) before its next chunk: it stops at that chunk boundary. The
    /// cancel is not racing other readers, so the count is exact.
    #[test]
    fn cancel_stops_a_reader_at_its_next_chunk_boundary_and_leaves_the_files_alone() {
        let (_t, root, paths) = three_equal_files();
        let job = Run::new().cancel_when("contents", 1);
        let out = job.job(|ctx| run(ctx, &query(&root, FinderMode::Duplicates), "s", Limits::default(), w(1), lg()));
        assert!(matches!(out, Err(JobError::Cancelled(_))), "{out:?}");
        let read = job.phases().last().unwrap().counts.last().copied().unwrap();
        assert_eq!(
            read,
            paddock_jobs::CHUNK as u64,
            "the reader read past the chunk it was cancelled in"
        );
        assert!(paths.iter().all(|p| p.exists()));
        assert!(matches!(job.end_state(), JobState::Cancelled { .. }));
    }

    /// Cancelled before the four readers start (the phase's first event), none of them reads a byte: each checks the token before
    /// its first chunk. Nothing here depends on how fast a thread sees the cancel.
    #[test]
    fn cancel_before_the_readers_start_reads_nothing_on_any_thread() {
        let (_t, root, paths) = three_equal_files();
        let job = Run::new().cancel_when("contents", 0);
        let out = job.job(|ctx| run(ctx, &query(&root, FinderMode::Duplicates), "s", Limits::default(), w(4), lg()));
        assert!(matches!(out, Err(JobError::Cancelled(_))), "{out:?}");
        let read = job.phases().last().unwrap().counts.last().copied().unwrap();
        assert_eq!(read, 0, "a reader read after the cancel");
        assert!(paths.iter().all(|p| p.exists()));
        assert!(matches!(job.end_state(), JobState::Cancelled { .. }));
    }
}

//! SHA-256 of a program's file for "search this file's hash on VirusTotal" (WP-33). The file is read here, in this
//! process, and nothing leaves the machine: the hash is shown first and only the hash goes into the address the browser
//! opens. Results are cached by path, size and modification time, so a repeated click costs nothing.

use dyno_core::weblinks::FileHashInfo;
use paddock_jobs::{copy_hashed, CancelReason, HashingWriter, JobContext, Phase};
use std::collections::HashMap;
use std::io::Read;
use std::path::Path;
use std::sync::{Mutex, MutexGuard};

/// The largest file hashed (a program bigger than this is not a file anyone sends to VirusTotal).
pub const MAX_BYTES: u64 = 2 * 1024 * 1024 * 1024;
/// Hashes remembered.
const CACHE_ENTRIES: usize = 256;

type Key = (String, u64, i64);

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// Why a hash job ended without a hash.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HashError {
    /// Stopped on request.
    Cancelled(CancelReason),
    /// It could not be done; the text says what to do.
    Failed(String),
}

/// The cache and the hasher.
#[derive(Default)]
pub struct FileHasher {
    cache: Mutex<HashMap<Key, String>>,
}

fn millis(t: std::time::SystemTime) -> i64 {
    t.duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| i64::try_from(d.as_millis()).unwrap_or(i64::MAX))
}

impl FileHasher {
    /// A hasher with an empty cache.
    pub fn new() -> FileHasher {
        FileHasher::default()
    }

    /// The hash of the regular file at `path` (an absolute path; links are resolved to the file they point at, which is
    /// what the program is), as the job `ctx`: one phase counting the bytes read, Cancel checked per chunk. A file hashed
    /// before (same path, size and modification time) answers from the cache without reading. The cache is filled only
    /// when the whole file was read, so a cancelled hash leaves nothing behind.
    pub fn hash_job(&self, ctx: &JobContext, path: &str) -> Result<FileHashInfo, HashError> {
        let p = Path::new(path);
        if !p.is_absolute() || dyno_core::disk::has_dot_segment(p) {
            return Err(HashError::Failed("That is not a full path to a file.".into()));
        }
        let real = std::fs::canonicalize(p).map_err(|e| match e.kind() {
            std::io::ErrorKind::NotFound => HashError::Failed("The file is no longer there.".into()),
            _ => HashError::Failed(format!("The file cannot be read: {e}")),
        })?;
        let meta = std::fs::metadata(&real).map_err(|e| HashError::Failed(format!("The file cannot be read: {e}")))?;
        if !meta.is_file() {
            return Err(HashError::Failed("That is not a file.".into()));
        }
        if meta.len() > MAX_BYTES {
            return Err(HashError::Failed("The file is too large to hash (over 2 GB).".into()));
        }
        let shown = real.to_string_lossy().into_owned();
        let key: Key = (shown.clone(), meta.len(), meta.modified().map(millis).unwrap_or(0));
        if let Some(h) = lock(&self.cache).get(&key) {
            return Ok(FileHashInfo {
                path: shown,
                bytes: meta.len(),
                sha256: h.clone(),
            });
        }
        let mut file = std::fs::File::open(&real).map_err(|e| match e.kind() {
            std::io::ErrorKind::PermissionDenied => HashError::Failed("Dyno is not allowed to read that file.".into()),
            _ => HashError::Failed(format!("The file cannot be opened: {e}")),
        })?;
        ctx.phase(Phase::bytes("hash", "Reading the file", Some(meta.len())));
        let mut limited = (&mut file).take(MAX_BYTES + 1);
        let (digest, _) =
            copy_hashed(&mut limited, std::io::sink(), ctx.cancel_token(), ctx).map_err(
                |e| match HashingWriter::<std::io::Sink>::cancelled(&e) {
                    Some(c) => HashError::Cancelled(c.0),
                    None => HashError::Failed(format!("The file could not be read completely: {e}")),
                },
            )?;
        let sha256 = paddock_jobs::hex(&digest);
        let mut c = lock(&self.cache);
        if c.len() >= CACHE_ENTRIES {
            c.clear();
        }
        c.insert(key, sha256.clone());
        Ok(FileHashInfo {
            path: shown,
            bytes: meta.len(),
            sha256,
        })
    }

    /// How many hashes are cached (tests).
    pub fn cached(&self) -> usize {
        lock(&self.cache).len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::jobs::testing::Run;

    const ABC: &str = "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";

    fn hash(h: &FileHasher, path: &str) -> Result<FileHashInfo, String> {
        Run::new().body(|ctx| h.hash_job(ctx, path)).map_err(|e| match e {
            HashError::Failed(m) => m,
            HashError::Cancelled(_) => "cancelled".into(),
        })
    }

    #[test]
    fn a_file_is_hashed_once_and_then_cached() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let f = t.path().join("prog.bin");
        std::fs::write(&f, b"abc").unwrap();
        let h = FileHasher::new();
        let a = hash(&h, f.to_str().unwrap()).unwrap();
        assert_eq!(a.sha256, ABC);
        assert_eq!(a.bytes, 3);
        assert_eq!(h.cached(), 1);
        assert_eq!(hash(&h, f.to_str().unwrap()).unwrap(), a);
        assert_eq!(h.cached(), 1);
        // A changed file (new size) is hashed again.
        std::fs::write(&f, b"abcd").unwrap();
        assert_ne!(hash(&h, f.to_str().unwrap()).unwrap().sha256, a.sha256);
        assert_eq!(h.cached(), 2);
    }

    #[test]
    fn bad_paths_say_what_is_wrong() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let h = FileHasher::new();
        assert!(hash(&h, "relative/file").unwrap_err().contains("full path"));
        assert!(hash(&h, paddock_testkit::path::under(t.path(), "../x").to_str().unwrap())
            .unwrap_err()
            .contains("full path"));
        assert!(hash(&h, t.path().join("missing").to_str().unwrap())
            .unwrap_err()
            .contains("no longer there"));
        assert!(hash(&h, t.path().to_str().unwrap()).unwrap_err().contains("not a file"));
    }

    #[cfg(unix)]
    #[test]
    fn an_unreadable_file_is_reported() {
        use std::os::unix::fs::PermissionsExt;
        let t = paddock_testkit::private_tempdir().unwrap();
        let f = t.path().join("secret");
        std::fs::write(&f, b"x").unwrap();
        std::fs::set_permissions(&f, std::fs::Permissions::from_mode(0o000)).unwrap();
        // Running as root can read anything; only assert the message when the open really fails.
        if std::fs::File::open(&f).is_err() {
            assert!(hash(&FileHasher::new(), f.to_str().unwrap()).unwrap_err().contains("not allowed"));
        }
    }

    #[cfg(unix)]
    #[test]
    fn a_link_is_hashed_as_the_program_it_points_at() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let f = t.path().join("real.bin");
        std::fs::write(&f, b"abc").unwrap();
        let l = t.path().join("link");
        std::os::unix::fs::symlink(&f, &l).unwrap();
        let info = hash(&FileHasher::new(), l.to_str().unwrap()).unwrap();
        assert!(info.path.ends_with("real.bin"));
    }

    #[test]
    fn the_hash_reports_the_bytes_read_and_never_goes_backwards() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let f = t.path().join("big.bin");
        std::fs::write(&f, vec![7u8; 300_000]).unwrap();
        let run = Run::new();
        let info = run.body(|ctx| FileHasher::new().hash_job(ctx, f.to_str().unwrap())).unwrap();
        assert_eq!(info.bytes, 300_000);
        let phases = run.phases();
        assert_eq!(phases.iter().map(|p| p.id.as_str()).collect::<Vec<_>>(), ["hash"]);
        assert_eq!(phases[0].total, Some(300_000));
        assert!(phases[0].counts.windows(2).all(|w| w[0] <= w[1]), "{:?}", phases[0].counts);
        assert_eq!(phases[0].counts.last(), Some(&300_000));
    }

    #[test]
    fn a_cancelled_hash_stops_within_a_chunk_and_caches_nothing() {
        let t = paddock_testkit::private_tempdir().unwrap();
        let f = t.path().join("big.bin");
        std::fs::write(&f, vec![7u8; 4 * 1024 * 1024]).unwrap();
        let h = FileHasher::new();
        let run = Run::new().cancel_when("hash", 64 * 1024);
        let out = run.body(|ctx| h.hash_job(ctx, f.to_str().unwrap()));
        assert!(matches!(out, Err(HashError::Cancelled(_))), "{out:?}");
        assert_eq!(h.cached(), 0, "a cancelled hash fills no cache");
        let read = run.phases()[0].counts.last().copied().unwrap_or(0);
        assert!(read <= 2 * paddock_jobs::CHUNK as u64, "stopped promptly, read {read}");
    }
}

//! What macOS still tells about processes of other users when the full BSD info is refused: `PROC_PIDT_SHORTBSDINFO` gives
//! the owner and the parent, and `sysctl kern.proc.pid` the start time. Read-only.

use dyno_core::process::Pid;

/// The owner and the parent of a process.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ShortInfo {
    /// The user id the process runs as.
    pub uid: u32,
    /// The parent's pid.
    pub parent: Pid,
}

/// The short BSD info of `pid`; `None` when the kernel won't say or the process is gone.
// ADR 0033 WP-9: the parent pid is shown in the process tree without a start-time check (display only).
pub fn short_info(pid: Pid) -> Option<ShortInfo> {
    // SAFETY: `proc_bsdshortinfo` is plain data for which zero is a valid bit pattern.
    let mut info: libc::proc_bsdshortinfo = unsafe { std::mem::zeroed() };
    let size = std::mem::size_of::<libc::proc_bsdshortinfo>() as libc::c_int;
    // SAFETY: `info` is valid for `size` bytes for the duration of the call.
    let got = unsafe {
        libc::proc_pidinfo(
            pid as libc::c_int,
            libc::PROC_PIDT_SHORTBSDINFO,
            0,
            (&mut info as *mut libc::proc_bsdshortinfo).cast(),
            size,
        )
    };
    (got == size && info.pbsi_pid == pid).then_some(ShortInfo {
        uid: info.pbsi_uid,
        parent: info.pbsi_ppid,
    })
}

/// Size of the kernel's `kinfo_proc` on 64-bit macOS.
const KINFO_PROC_SIZE: usize = 648;
/// Offset of `p_pid` inside it (after the 16-byte start time, two pointers, the flags and the state).
const OFF_PID: usize = 40;

/// The start time (seconds since the Unix epoch) from the bytes of a `kinfo_proc` answer for `pid`. The first field is the
/// start time's seconds; the pid in the record must be the one asked for.
pub fn start_secs_from_kinfo(bytes: &[u8], pid: Pid) -> Option<u64> {
    let secs = i64::from_le_bytes(bytes.get(..8)?.try_into().ok()?);
    let got = i32::from_le_bytes(bytes.get(OFF_PID..OFF_PID + 4)?.try_into().ok()?);
    (got == i32::try_from(pid).ok()? && secs > 0).then_some(secs as u64)
}

/// The start time of `pid` from `sysctl kern.proc.pid`; `None` when the kernel won't say.
pub fn start_secs(pid: Pid) -> Option<u64> {
    let mut mib = [libc::CTL_KERN, libc::KERN_PROC, libc::KERN_PROC_PID, pid as libc::c_int];
    let mut buf = vec![0u8; KINFO_PROC_SIZE];
    let mut len = buf.len();
    // SAFETY: `mib` has 4 entries as passed; `buf` is valid for `len` bytes and no new value is set.
    let r = unsafe { libc::sysctl(mib.as_mut_ptr(), 4, buf.as_mut_ptr().cast(), &mut len, std::ptr::null_mut(), 0) };
    (r == 0 && len >= OFF_PID + 4)
        .then(|| start_secs_from_kinfo(&buf[..len], pid))
        .flatten()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn this_process_is_read_back_by_its_short_info_and_start_time() {
        let me = std::process::id();
        let info = short_info(me).expect("own short info");
        assert_eq!(info.uid, unsafe { libc::getuid() });
        assert_eq!(info.parent, std::os::unix::process::parent_id());
        let started = start_secs(me).expect("own start time");
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        assert!(started > 1_000_000_000 && started <= now);
    }

    #[test]
    fn a_pid_that_does_not_exist_gives_nothing() {
        assert_eq!(short_info(u32::MAX >> 1), None);
        assert_eq!(start_secs(u32::MAX >> 1), None);
    }

    #[test]
    fn the_start_time_is_taken_from_the_record_only_when_it_is_the_asked_process() {
        let mut rec = vec![0u8; KINFO_PROC_SIZE];
        rec[..8].copy_from_slice(&1_700_000_000i64.to_le_bytes());
        rec[OFF_PID..OFF_PID + 4].copy_from_slice(&321i32.to_le_bytes());
        assert_eq!(start_secs_from_kinfo(&rec, 321), Some(1_700_000_000));
        assert_eq!(start_secs_from_kinfo(&rec, 322), None);
        assert_eq!(start_secs_from_kinfo(&rec[..20], 321), None);
        rec[..8].copy_from_slice(&0i64.to_le_bytes());
        assert_eq!(start_secs_from_kinfo(&rec, 321), None);
        assert_eq!(start_secs_from_kinfo(&rec, u32::MAX), None);
    }
}

//! `InstallTool` for the helper (ADR 0027 section 7, WP-8): the pin table, and the installer over a small port. The helper never
//! trusts the agent's catalogue: the bytes arrive over the connection, are written create-new into a staging folder while they
//! are hashed, must match the size and SHA-256 compiled in here, and only then does the installer run, with `TEMP`/`TMP` inside
//! the staging folder. Windows only (decision O2); macOS SMART runs in the agent, and there is no upstream Linux binary.
//!
//! The pins are recorded with their evidence in `crates/dyno-helper/tools/smartmontools-7.5.pin.md`.

use crate::runner::{Tool, ToolOutput};
use dyno_core::helper::HelperHost;
use dyno_core::helper_requests::ToolKind;
use dyno_core::helper_wire::ToolStatus;
use dyno_core::ports::PlatformError;
use paddock_jobs::time::Clock;
use sha2::{Digest, Sha256};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

/// How long the NSIS installer may run.
pub const INSTALL_TIMEOUT: Duration = Duration::from_secs(120);

/// One pinned upstream package.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Pin {
    /// The tool.
    pub tool: ToolKind,
    /// Its version.
    pub version: &'static str,
    /// The system it installs on.
    pub host: HelperHost,
    /// The package file's name, used as the staging file (never a caller's name).
    pub file: &'static str,
    /// Exact size in bytes.
    pub size: u64,
    /// SHA-256, lower-case hex.
    pub sha256: &'static str,
}

/// The pins compiled into the helper. A new smartmontools reaches users only with a new helper.
pub const PINS: [Pin; 1] = [Pin {
    tool: ToolKind::Smartmontools,
    version: "7.5",
    host: HelperHost::Windows,
    file: "smartmontools-7.5.win32-setup.exe",
    size: 1_508_408,
    sha256: "896337fcc253220614cf8cdbd5cf2321c5aa326a37a04160a672a281e6104c70",
}];

/// The pin for `tool` on `host`.
pub fn pin_for(tool: ToolKind, host: HelperHost) -> Option<&'static Pin> {
    PINS.iter().find(|p| p.tool == tool && p.host == host)
}

/// The NSIS components that leave no `smartd` service, menu entry, uninstaller key or PATH change (WP-0, measured).
pub const WINDOWS_COMPONENTS: &str = "x64,smartctl,drivedb";

/// The folder the pinned `version` of smartmontools is installed into under the helper's `tools` folder. The installer, the
/// tools list in `Info` and the helper's SMART reader all use this one definition (rule 55).
pub fn install_folder(tools: &Path, version: &str) -> PathBuf {
    tools.join(format!("smartmontools-{version}"))
}

/// The `smartctl.exe` of the pinned `version` inside [`install_folder`].
pub fn smartctl_path(tools: &Path, version: &str) -> PathBuf {
    install_folder(tools, version).join("bin").join("smartctl.exe")
}

/// Where the install happens (the helper's protected folders).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InstallRoots {
    /// The staging folder, `...\tools\.staging`.
    pub staging: String,
    /// The tools folder, `...\tools`.
    pub tools: String,
}

/// What the installer needs from the machine.
pub trait InstallPorts: Send {
    /// Creates `name` in the staging folder, failing if it exists (create-new), and returns a writer.
    fn create_staged(&mut self, name: &str) -> std::io::Result<Box<dyn Write>>;
    /// Runs a program to completion within `timeout`.
    fn run(&mut self, tool: &Tool, timeout: Duration) -> Result<ToolOutput, PlatformError>;
    /// Whether a file exists.
    fn exists(&self, path: &str) -> bool;
    /// Deletes the staging folder's contents.
    fn clear_staging(&mut self);
    /// Deletes the install folder `path` (and what is in it), so a file an earlier install left cannot pass for this one.
    ///
    /// # Errors
    /// The folder is there and could not be removed: the install stops, because a file an earlier install left (or a user
    /// planted) could otherwise pass for the new one.
    fn remove_dir(&mut self, path: &str) -> std::io::Result<()>;
}

/// Why an install did not happen. Each says what to do next.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InstallError {
    /// This system installs nothing through the helper.
    Unsupported(String),
    /// The package is not the size the helper has pinned.
    WrongSize {
        /// The bytes received.
        got: u64,
        /// The pinned size.
        want: u64,
    },
    /// The package's SHA-256 is not the pinned one.
    WrongHash,
    /// The staging file could not be written.
    Staging(String),
    /// The installer ran and failed.
    Installer(String),
}

impl From<InstallError> for PlatformError {
    fn from(e: InstallError) -> Self {
        match e {
            InstallError::Unsupported(m) => PlatformError::Unsupported(m),
            InstallError::WrongSize { got, want } => PlatformError::Failed(format!(
                "The package is {got} bytes but this helper expects {want}. Download it again; nothing was installed."
            )),
            InstallError::WrongHash => PlatformError::Failed(
                "The package does not match the checksum this helper expects. Download it again; nothing was installed.".into(),
            ),
            InstallError::Staging(m) => PlatformError::Failed(format!("The package could not be written: {m}. Nothing was installed.")),
            InstallError::Installer(m) => PlatformError::Failed(m),
        }
    }
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// The installer's command line: the NSIS options are `[/S] [/SO component,...] [/D=INSTDIR]`, and `/D=` must come last.
pub fn windows_command(setup: &str, dest: &str, staging: &str) -> Tool {
    Tool {
        program: setup.to_string(),
        args: vec!["/S".into(), "/SO".into(), WINDOWS_COMPONENTS.into(), format!("/D={dest}")],
        env: vec![("TEMP".into(), staging.to_string()), ("TMP".into(), staging.to_string())],
    }
}

/// Checks `bytes` against the pin, stages them, runs the installer and confirms `bin\smartctl.exe` is there. The staging folder
/// is cleared on every outcome.
pub fn install(
    ports: &mut dyn InstallPorts,
    clock: &Arc<dyn Clock>,
    host: HelperHost,
    tool: ToolKind,
    bytes: &[u8],
    roots: &InstallRoots,
) -> Result<ToolStatus, InstallError> {
    let started = clock.monotonic();
    let ms = |from: Duration| clock.monotonic().saturating_sub(from).as_millis() as u64;
    let Some(pin) = pin_for(tool, host) else {
        let why = match host {
            HelperHost::Macos => "On macOS Dyno reads SMART with its own copy of smartctl; the helper installs nothing.",
            HelperHost::Linux => "Install the smartmontools package of your distribution; Dyno then uses /usr/sbin/smartctl.",
            HelperHost::Windows => "This helper has no pinned package for that tool.",
        };
        log::warn!("InstallTool refused: no pin for this tool on this system");
        return Err(InstallError::Unsupported(why.into()));
    };
    if bytes.len() as u64 != pin.size {
        log::warn!(Got = bytes.len() as u64, Want = pin.size; "InstallTool refused: wrong package size");
        return Err(InstallError::WrongSize {
            got: bytes.len() as u64,
            want: pin.size,
        });
    }
    let result = stage_and_run(ports, clock, pin, bytes, roots);
    ports.clear_staging();
    match &result {
        Ok(_) => log::info!(Version = pin.version, Ms = ms(started); "InstallTool finished"),
        Err(e) => log::warn!(Error = format!("{e:?}").as_str(), Ms = ms(started); "InstallTool failed; staging cleared"),
    }
    result
}

fn stage_and_run(
    ports: &mut dyn InstallPorts,
    clock: &Arc<dyn Clock>,
    pin: &Pin,
    bytes: &[u8],
    roots: &InstallRoots,
) -> Result<ToolStatus, InstallError> {
    let phase = clock.monotonic();
    let mut writer = ports
        .create_staged(pin.file)
        .map_err(|e| InstallError::Staging(e.kind().to_string()))?;
    let mut hasher = Sha256::new();
    for chunk in bytes.chunks(64 * 1024) {
        hasher.update(chunk);
        writer.write_all(chunk).map_err(|e| InstallError::Staging(e.kind().to_string()))?;
    }
    writer.flush().map_err(|e| InstallError::Staging(e.kind().to_string()))?;
    drop(writer);
    if hex(&hasher.finalize()) != pin.sha256 {
        log::warn!("InstallTool refused: the package checksum does not match the pinned one");
        return Err(InstallError::WrongHash);
    }
    log::info!(Ms = clock.monotonic().saturating_sub(phase).as_millis() as u64; "InstallTool: package staged and checked");
    let dest = install_folder(Path::new(&roots.tools), pin.version).to_string_lossy().into_owned();
    let setup = format!("{}\\{}", roots.staging, pin.file);
    let cmd = windows_command(&setup, &dest, &roots.staging);
    ports.remove_dir(&dest).map_err(|e| {
        log::warn!(Dest = dest.as_str(), Error = e.to_string().as_str(); "InstallTool: the older install folder could not be removed");
        InstallError::Installer(format!(
            "The older install folder could not be removed ({}). Nothing was installed; close the programs using it and try again.",
            e.kind()
        ))
    })?;
    let run = clock.monotonic();
    let out = ports
        .run(&cmd, INSTALL_TIMEOUT)
        .map_err(|e| InstallError::Installer(format!("The installer did not finish: {e}")))?;
    log::info!(Ok = out.ok, Dest = dest.as_str(), Stderr = out.error.as_str(), Ms = clock.monotonic().saturating_sub(run).as_millis() as u64; "InstallTool: installer ran");
    if !out.ok {
        return Err(InstallError::Installer(format!(
            "The installer failed ({}). Nothing was kept; try again.",
            if out.error.is_empty() { "no message" } else { out.error.as_str() }
        )));
    }
    let smartctl = smartctl_path(Path::new(&roots.tools), pin.version).to_string_lossy().into_owned();
    let found = ports.exists(&smartctl);
    log::info!(Smartctl = smartctl.as_str(), Found = found; "InstallTool: checked the installed smartctl");
    if !found {
        return Err(InstallError::Installer(
            "The installer finished but smartctl is not where it should be. Try again.".into(),
        ));
    }
    Ok(ToolStatus {
        tool: pin.tool,
        installed: Some(pin.version.to_string()),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use paddock_jobs::time::FakeClock;
    use std::sync::Mutex;

    #[derive(Default)]
    struct Log {
        staged: Vec<(String, Vec<u8>)>,
        runs: Vec<(Tool, Duration)>,
        cleared: usize,
        /// "remove" and "run", in the order they happened.
        events: Vec<&'static str>,
        removed: Vec<String>,
    }
    struct Fake {
        log: Arc<Mutex<Log>>,
        run: Result<ToolOutput, PlatformError>,
        installed: bool,
        stage_fails: bool,
        /// A `smartctl.exe` an earlier install left, which goes when its folder is removed.
        stale: bool,
        /// The older install folder cannot be removed (something holds it).
        remove_fails: bool,
    }
    struct Sink(Arc<Mutex<Log>>, String);
    impl Write for Sink {
        fn write(&mut self, b: &[u8]) -> std::io::Result<usize> {
            let mut l = self.0.lock().unwrap();
            let name = self.1.clone();
            match l.staged.iter_mut().find(|(n, _)| *n == name) {
                Some((_, v)) => v.extend_from_slice(b),
                None => l.staged.push((name, b.to_vec())),
            }
            Ok(b.len())
        }
        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }
    impl InstallPorts for Fake {
        fn create_staged(&mut self, name: &str) -> std::io::Result<Box<dyn Write>> {
            if self.stage_fails || self.log.lock().unwrap().staged.iter().any(|(n, _)| n == name) {
                return Err(std::io::Error::from(std::io::ErrorKind::AlreadyExists));
            }
            Ok(Box::new(Sink(self.log.clone(), name.to_string())))
        }
        fn run(&mut self, t: &Tool, timeout: Duration) -> Result<ToolOutput, PlatformError> {
            let mut l = self.log.lock().unwrap();
            l.runs.push((t.clone(), timeout));
            l.events.push("run");
            self.run.clone()
        }
        fn exists(&self, _: &str) -> bool {
            self.installed || (self.stale && self.log.lock().unwrap().removed.is_empty())
        }
        fn clear_staging(&mut self) {
            self.log.lock().unwrap().cleared += 1;
        }
        fn remove_dir(&mut self, path: &str) -> std::io::Result<()> {
            let mut l = self.log.lock().unwrap();
            if self.remove_fails {
                l.events.push("remove-failed");
                return Err(std::io::Error::from(std::io::ErrorKind::PermissionDenied));
            }
            l.removed.push(path.to_string());
            l.events.push("remove");
            Ok(())
        }
    }

    fn rig(run: Result<ToolOutput, PlatformError>, installed: bool) -> (Fake, Arc<Mutex<Log>>) {
        let log = Arc::new(Mutex::new(Log::default()));
        (
            Fake {
                log: log.clone(),
                run,
                installed,
                stage_fails: false,
                stale: false,
                remove_fails: false,
            },
            log,
        )
    }
    fn good() -> Result<ToolOutput, PlatformError> {
        Ok(ToolOutput {
            ok: true,
            stdout: String::new(),
            error: String::new(),
        })
    }
    fn roots() -> InstallRoots {
        InstallRoots {
            staging: r"C:\PF\Dyno Helper\tools\.staging".into(),
            tools: r"C:\PF\Dyno Helper\tools".into(),
        }
    }
    fn clock() -> Arc<dyn Clock> {
        Arc::new(FakeClock::new())
    }

    /// A package of the pinned size whose hash we cannot match (the real bytes are not in the repo): the hash gate is what
    /// runs here. The accepting path is tested with a test pin below.
    fn pinned_size_junk() -> Vec<u8> {
        vec![7; PINS[0].size as usize]
    }

    #[test]
    fn the_pin_table_has_the_wp0_values_for_windows_only() {
        let p = pin_for(ToolKind::Smartmontools, HelperHost::Windows).unwrap();
        assert_eq!((p.version, p.size, p.sha256.len()), ("7.5", 1_508_408, 64));
        assert!(p.sha256.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)));
        assert!(pin_for(ToolKind::Smartmontools, HelperHost::Macos).is_none());
        assert!(pin_for(ToolKind::Smartmontools, HelperHost::Linux).is_none());
    }

    #[test]
    fn the_command_line_selects_components_puts_dest_last_and_confines_temp() {
        let t = windows_command(r"C:\s\setup.exe", r"C:\t\smartmontools-7.5", r"C:\s");
        assert_eq!(t.args, ["/S", "/SO", "x64,smartctl,drivedb", r"/D=C:\t\smartmontools-7.5"]);
        assert_eq!(
            t.env,
            [("TEMP".to_string(), r"C:\s".to_string()), ("TMP".to_string(), r"C:\s".to_string())]
        );
    }

    #[test]
    fn other_systems_install_nothing_and_say_why() {
        for (host, word) in [(HelperHost::Macos, "own copy"), (HelperHost::Linux, "distribution")] {
            let (mut f, log) = rig(good(), true);
            let e = install(&mut f, &clock(), host, ToolKind::Smartmontools, &[1], &roots()).unwrap_err();
            assert!(matches!(&e, InstallError::Unsupported(m) if m.contains(word)), "{e:?}");
            assert!(log.lock().unwrap().staged.is_empty() && log.lock().unwrap().runs.is_empty());
        }
    }

    #[test]
    fn one_byte_over_or_under_the_pinned_size_is_refused_before_anything_is_written() {
        for len in [PINS[0].size - 1, PINS[0].size + 1, 0] {
            let (mut f, log) = rig(good(), true);
            let bytes = vec![0; len as usize];
            let e = install(&mut f, &clock(), HelperHost::Windows, ToolKind::Smartmontools, &bytes, &roots()).unwrap_err();
            assert_eq!(
                e,
                InstallError::WrongSize {
                    got: len,
                    want: PINS[0].size
                }
            );
            assert!(log.lock().unwrap().staged.is_empty());
        }
    }

    #[test]
    fn a_wrong_hash_is_refused_after_staging_and_the_installer_never_runs() {
        let (mut f, log) = rig(good(), true);
        let e = install(
            &mut f,
            &clock(),
            HelperHost::Windows,
            ToolKind::Smartmontools,
            &pinned_size_junk(),
            &roots(),
        )
        .unwrap_err();
        assert_eq!(e, InstallError::WrongHash);
        let l = log.lock().unwrap();
        assert!(l.runs.is_empty());
        assert_eq!(l.cleared, 1, "staging is cleared on every outcome");
        assert!(matches!(PlatformError::from(InstallError::WrongHash), PlatformError::Failed(m) if m.contains("nothing was installed")));
    }

    #[test]
    fn a_second_install_cannot_overwrite_a_staged_file() {
        let (mut f, _) = rig(good(), true);
        f.log.lock().unwrap().staged.push((PINS[0].file.to_string(), vec![]));
        let e = install(
            &mut f,
            &clock(),
            HelperHost::Windows,
            ToolKind::Smartmontools,
            &pinned_size_junk(),
            &roots(),
        )
        .unwrap_err();
        assert!(matches!(e, InstallError::Staging(_)));
    }

    #[test]
    fn the_folder_the_installer_logs_is_the_folder_the_tools_list_and_the_reader_use() {
        let bytes = vec![1u8; 1000];
        let sha: &'static str = Box::leak(hex(&Sha256::digest(&bytes)).into_boxed_str());
        let pin = Pin {
            size: 1000,
            sha256: sha,
            file: "standin-setup.exe",
            ..PINS[0]
        };
        let (mut f, log) = rig(good(), true);
        let r = InstallRoots {
            staging: "S".into(),
            tools: "T".into(),
        };
        stage_and_run(&mut f, &clock(), &pin, &bytes, &r).unwrap();
        let l = log.lock().unwrap();
        let folder = install_folder(Path::new("T"), "7.5");
        assert_eq!(l.removed, [folder.to_string_lossy()]);
        assert!(l.runs[0].0.args.last().unwrap().ends_with(&*folder.to_string_lossy()));
        assert!(smartctl_path(Path::new("T"), "7.5").starts_with(&folder));
    }

    #[test]
    fn a_file_an_earlier_install_left_is_removed_first_and_cannot_pass_for_this_install() {
        let bytes = vec![1u8; 1000];
        let sha: &'static str = Box::leak(hex(&Sha256::digest(&bytes)).into_boxed_str());
        let pin = Pin {
            size: 1000,
            sha256: sha,
            file: "standin-setup.exe",
            ..PINS[0]
        };
        // The installer "succeeds" but writes nothing: only the stale file would be there.
        let (mut f, log) = rig(good(), false);
        f.stale = true;
        let got = stage_and_run(&mut f, &clock(), &pin, &bytes, &roots());
        assert!(matches!(got, Err(InstallError::Installer(_))), "{got:?}");
        let l = log.lock().unwrap();
        assert_eq!(l.events, ["remove", "run"], "the old folder goes before the installer runs");
        assert!(l.removed[0].ends_with("smartmontools-7.5"), "{:?}", l.removed);
    }

    #[test]
    fn an_older_install_folder_that_cannot_be_removed_stops_the_install_before_the_installer_runs() {
        let bytes = vec![1u8; 1000];
        let sha: &'static str = Box::leak(hex(&Sha256::digest(&bytes)).into_boxed_str());
        let pin = Pin {
            size: 1000,
            sha256: sha,
            file: "standin-setup.exe",
            ..PINS[0]
        };
        // A smartctl.exe the old folder still holds would pass for the new install if the installer ran over it.
        let (mut f, log) = rig(good(), true);
        f.remove_fails = true;
        let got = stage_and_run(&mut f, &clock(), &pin, &bytes, &roots());
        assert!(
            matches!(&got, Err(InstallError::Installer(m)) if m.contains("could not be removed")),
            "{got:?}"
        );
        assert_eq!(log.lock().unwrap().events, ["remove-failed"], "the installer never ran");
    }

    #[test]
    fn a_matching_package_runs_the_installer_in_staging_and_reports_the_version() {
        // Hash a stand-in package and run the same stage-and-run path with a pin for it.
        let bytes = vec![1u8; 1000];
        let sha = hex(&Sha256::digest(&bytes));
        let sha: &'static str = Box::leak(sha.into_boxed_str());
        let pin = Pin {
            size: 1000,
            sha256: sha,
            file: "standin-setup.exe",
            ..PINS[0]
        };
        for (run, installed, ok) in [
            (good(), true, true),
            (good(), false, false),
            (
                Ok(ToolOutput {
                    ok: false,
                    stdout: String::new(),
                    error: "exit 2".into(),
                }),
                true,
                false,
            ),
            (Err(PlatformError::Timeout("took 120 s".into())), true, false),
        ] {
            let (mut f, log) = rig(run, installed);
            let got = stage_and_run(&mut f, &clock(), &pin, &bytes, &roots());
            assert_eq!(got.is_ok(), ok, "{got:?}");
            let l = log.lock().unwrap();
            assert_eq!(l.staged[0].1, bytes, "the staged file holds exactly the streamed bytes");
            let (cmd, timeout) = &l.runs[0];
            assert_eq!(*timeout, INSTALL_TIMEOUT);
            assert!(cmd.program.ends_with("standin-setup.exe") && cmd.args.last().unwrap().ends_with("smartmontools-7.5"));
            if ok {
                assert_eq!(
                    got.unwrap(),
                    ToolStatus {
                        tool: ToolKind::Smartmontools,
                        installed: Some("7.5".into())
                    }
                );
            }
        }
    }
}

//! The OS side of the disk map's volume list: the mounts, their capacity and what is known about the medium. Everything
//! that decides what a mount *is* lives in `dyno_core::disk::volume`; the parsers here are pure and tested with invented
//! data on every OS, the calls into the OS are small and tested against the machine where they can be.
#![allow(unsafe_code)]

use dyno_core::disk::volume::{MediaTraits, RawMount};
use std::path::Path;

/// macOS: the user's data volume, joined to the sealed system volume at `/` by firmlinks.
pub const MACOS_DATA: &str = "/System/Volumes/Data";

/// macOS: drops plumbing and shows the Data volume as the startup disk at `/`, scanned from the Data volume's own mount
/// (`/` is the read-only sealed system volume; its folders reach the data through firmlinks).
pub fn tidy_macos(mounts: Vec<RawMount>) -> Vec<RawMount> {
    let has_data = mounts.iter().any(|m| m.mount == MACOS_DATA);
    mounts
        .into_iter()
        .filter(|m| !dyno_core::disk::volume::is_plumbing_mount(&m.mount) && !(has_data && m.mount == "/"))
        .map(|mut m| {
            if m.mount == MACOS_DATA {
                m.mount = "/".into();
                m.scan_root = Some(MACOS_DATA.into());
                m.read_only = false;
            }
            m
        })
        .collect()
}

/// The name macOS shows for the startup disk: the `/Volumes` entry that is a link to `/`.
pub fn macos_startup_name(volumes_dir: &Path) -> Option<String> {
    for e in std::fs::read_dir(volumes_dir).ok()?.flatten() {
        if std::fs::canonicalize(e.path()).is_ok_and(|p| p == Path::new("/")) && e.path().is_symlink() {
            return e.file_name().to_str().map(str::to_string);
        }
    }
    None
}

/// Reads the answer of `diskutil info -plist <mount>` (macOS) into traits.
pub fn parse_diskutil_info(bytes: &[u8]) -> Option<MediaTraits> {
    let v = plist::Value::from_reader(std::io::Cursor::new(bytes)).ok()?;
    let d = v.as_dictionary()?;
    let internal = d.get("Internal").and_then(plist::Value::as_boolean);
    let removable = d.get("RemovableMediaOrExternalDevice").and_then(plist::Value::as_boolean);
    Some(MediaTraits {
        internal,
        removable: removable.filter(|_| internal != Some(true)),
        rotational: d.get("SolidState").and_then(plist::Value::as_boolean).map(|ssd| !ssd),
        bus: d.get("BusProtocol").and_then(plist::Value::as_string).map(str::to_string),
        identity: d.get("VolumeUUID").and_then(plist::Value::as_string).map(str::to_string),
    })
}

/// Linux: removable, rotational and bus of the block device `major:minor`, from sysfs under `sys_root` (`/sys`).
pub fn linux_traits(sys_root: &Path, device: &str) -> MediaTraits {
    let Ok(dir) = std::fs::canonicalize(sys_root.join("dev").join("block").join(device)) else {
        return MediaTraits::default();
    };
    // A partition keeps `removable` and `queue/` in its parent disk's folder.
    let flag = |rel: &str| {
        [dir.join(rel), dir.join("..").join(rel)]
            .iter()
            .find_map(|p| std::fs::read_to_string(p).ok())
            .map(|t| t.trim() == "1")
    };
    // The device path runs through its USB port: `.../usb1/1-1/...`.
    let bus = dir
        .components()
        .any(|c| {
            let n = c.as_os_str().to_string_lossy();
            n.strip_prefix("usb")
                .is_some_and(|d| !d.is_empty() && d.bytes().all(|b| b.is_ascii_digit()))
        })
        .then(|| "USB".to_string());
    MediaTraits {
        internal: None,
        removable: flag("removable").filter(|r| *r).or(bus.as_ref().map(|_| true)),
        rotational: flag("queue/rotational"),
        bus,
        identity: None,
    }
}

/// Windows: the identity of a volume from its GUID path and its serial number. The GUID path survives a reformat (the partition
/// keeps it), the serial changes with it, so both together tell a reformatted disk from the one that was scanned. Built here (not
/// in the Windows module) so every OS tests the composition.
pub fn compose_windows_identity(guid_path: &str, serial: Option<u32>) -> String {
    match serial {
        Some(s) => format!("{guid_path}|{s:08x}"),
        None => guid_path.to_string(),
    }
}

/// Linux: the file system UUID of the device `source` (`/dev/sda1`), from the links in `by_uuid` (`/dev/disk/by-uuid`), each of
/// which points at the device that holds that UUID. `None` for a device without one (or an unreadable folder).
pub fn linux_identity(by_uuid: &Path, source: &str) -> Option<String> {
    let want = std::fs::canonicalize(source).ok()?;
    std::fs::read_dir(by_uuid).ok()?.flatten().find_map(|e| {
        let target = std::fs::canonicalize(e.path()).ok()?;
        (target == want).then(|| e.file_name().to_string_lossy().into_owned())
    })
}

// The field types of `statvfs` differ per OS (32 or 64 bits), so the widening is needed on some and a no-op on others.
#[cfg(unix)]
#[allow(clippy::useless_conversion)]
fn statvfs(path: &Path) -> Option<(u64, u64)> {
    use std::os::unix::ffi::OsStrExt;
    let c = std::ffi::CString::new(path.as_os_str().as_bytes()).ok()?;
    // SAFETY: an all-zero `statvfs` is a valid value to be overwritten; `c` is a NUL-terminated path.
    let mut s: libc::statvfs = unsafe { std::mem::zeroed() };
    // SAFETY: `c` and `s` are valid for the duration of the call.
    if unsafe { libc::statvfs(c.as_ptr(), &mut s) } != 0 {
        return None;
    }
    let unit = u64::from(s.f_frsize);
    Some((
        u64::from(s.f_blocks).saturating_mul(unit),
        u64::from(s.f_bavail).saturating_mul(unit),
    ))
}

/// The space of one volume as the person means it: what is free to write, counting what the OS gives back on demand.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Space {
    /// Capacity in bytes.
    pub total: u64,
    /// Free bytes by the one definition every Dyno view shares (on macOS Finder's "available": purgeable space counts as free).
    pub free: u64,
    /// Bytes the OS would give back when asked (macOS purgeable space: local snapshots, caches); `None` where there is no such notion.
    pub purgeable: Option<u64>,
}

/// Picks the free bytes from what macOS can report, best first: the "important usage" figure (Finder's), the plain available
/// figure, then `statvfs`'s `f_bavail` (which leaves purgeable space out). A missing or zero figure falls through to the next
/// (zero is what a volume that cannot say reports), and the pick never exceeds the capacity.
pub fn choose_free(important: Option<u64>, available: Option<u64>, bavail: Option<u64>, total: u64) -> Option<u64> {
    [important, available, bavail]
        .into_iter()
        .flatten()
        .find(|v| *v > 0)
        .or(bavail)
        .map(|v| v.min(total))
}

/// Capacity and free bytes of the volume mounted at `mount`, by the one definition of free (see [`Space`]); `None` when the OS
/// will not say. May block on a dead network mount: callers on a network mount run it on an abandonable thread.
pub fn space(mount: &str) -> Option<Space> {
    #[cfg(target_os = "macos")]
    {
        let (total, bavail) = statvfs(Path::new(mount)).map_or((None, None), |(t, b)| (Some(t), Some(b)));
        let q = macos_space::read(mount);
        let total = q.as_ref().and_then(|q| q.total).filter(|t| *t > 0).or(total)?;
        let free = choose_free(
            q.as_ref().and_then(|q| q.important),
            q.as_ref().and_then(|q| q.available),
            bavail,
            total,
        )?;
        let purgeable = q
            .as_ref()
            .and_then(|q| Some(q.important?.saturating_sub(q.available?)))
            .filter(|p| *p > 0);
        Some(Space { total, free, purgeable })
    }
    #[cfg(all(unix, not(target_os = "macos")))]
    {
        statvfs(Path::new(mount)).map(|(total, free)| Space {
            total,
            free,
            purgeable: None,
        })
    }
    #[cfg(windows)]
    {
        win::capacity(mount).map(|(total, free)| Space {
            total,
            free,
            purgeable: None,
        })
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = mount;
        None
    }
}

/// Capacity and free bytes of the volume mounted at `mount` (see [`space`]).
pub fn capacity(mount: &str) -> Option<(u64, u64)> {
    space(mount).map(|s| (s.total, s.free))
}

/// macOS volume figures from CoreFoundation. A fresh URL is made for every read: a URL object caches the resource values it
/// has been asked for, so a long-lived one would show the first answer forever.
#[cfg(target_os = "macos")]
mod macos_space {
    use std::ffi::c_void;
    use std::os::unix::ffi::OsStrExt;

    type CFTypeRef = *const c_void;

    #[link(name = "CoreFoundation", kind = "framework")]
    extern "C" {
        static kCFURLVolumeTotalCapacityKey: CFTypeRef;
        static kCFURLVolumeAvailableCapacityKey: CFTypeRef;
        static kCFURLVolumeAvailableCapacityForImportantUsageKey: CFTypeRef;
        fn CFURLCreateFromFileSystemRepresentation(alloc: CFTypeRef, buf: *const u8, len: isize, is_dir: u8) -> CFTypeRef;
        fn CFURLCopyResourcePropertyForKey(url: CFTypeRef, key: CFTypeRef, value: *mut CFTypeRef, error: *mut CFTypeRef) -> u8;
        fn CFNumberGetValue(number: CFTypeRef, kind: isize, out: *mut i64) -> u8;
        fn CFGetTypeID(cf: CFTypeRef) -> usize;
        fn CFNumberGetTypeID() -> usize;
        fn CFRelease(cf: CFTypeRef);
    }

    /// kCFNumberSInt64Type.
    const SINT64: isize = 4;

    /// What the OS said; each figure is `None` when it did not say.
    pub struct Figures {
        pub total: Option<u64>,
        pub available: Option<u64>,
        pub important: Option<u64>,
    }

    fn number(url: CFTypeRef, key: CFTypeRef) -> Option<u64> {
        let mut value: CFTypeRef = std::ptr::null();
        let mut error: CFTypeRef = std::ptr::null();
        // SAFETY: `url` and `key` are live CF objects; the out pointers are valid. Both outputs are released below when set.
        let ok = unsafe { CFURLCopyResourcePropertyForKey(url, key, &mut value, &mut error) } != 0;
        if !error.is_null() {
            // SAFETY: the call returned an owned error object.
            unsafe { CFRelease(error) };
        }
        if !ok || value.is_null() {
            return None;
        }
        let mut out = 0i64;
        // SAFETY: `value` is an owned CF object; it is read only as a CFNumber after its type is checked, then released.
        let got = unsafe { CFGetTypeID(value) == CFNumberGetTypeID() && CFNumberGetValue(value, SINT64, &mut out) != 0 };
        // SAFETY: balances the copy above.
        unsafe { CFRelease(value) };
        got.then(|| u64::try_from(out).ok()).flatten()
    }

    /// The three figures of the volume holding `mount`; `None` when the URL could not be made.
    pub fn read(mount: &str) -> Option<Figures> {
        let bytes = std::path::Path::new(mount).as_os_str().as_bytes();
        // SAFETY: `bytes` is valid for its length; the null allocator is the default one.
        let url = unsafe { CFURLCreateFromFileSystemRepresentation(std::ptr::null(), bytes.as_ptr(), bytes.len() as isize, 1) };
        if url.is_null() {
            return None;
        }
        // SAFETY: the keys are CoreFoundation's own constants, valid for the life of the process.
        let figures = unsafe {
            Figures {
                total: number(url, kCFURLVolumeTotalCapacityKey),
                available: number(url, kCFURLVolumeAvailableCapacityKey),
                important: number(url, kCFURLVolumeAvailableCapacityForImportantUsageKey),
            }
        };
        // SAFETY: balances the create above.
        unsafe { CFRelease(url) };
        Some(figures)
    }
}

/// Every mount the OS lists (before [`dyno_core::disk::volume::is_listed`] filters them).
pub fn mounts() -> Vec<RawMount> {
    #[cfg(target_os = "macos")]
    {
        tidy_macos(macos_mounts())
    }
    #[cfg(target_os = "linux")]
    {
        std::fs::read_to_string("/proc/self/mountinfo")
            .map(|t| dyno_core::disk::volume::parse_mountinfo(&t))
            .unwrap_or_default()
    }
    #[cfg(windows)]
    {
        win::mounts()
    }
    #[cfg(not(any(target_os = "macos", target_os = "linux", windows)))]
    {
        Vec::new()
    }
}

/// What the OS knows about the medium behind `m`.
pub fn media_traits(m: &RawMount) -> MediaTraits {
    #[cfg(target_os = "macos")]
    {
        let mut cmd = crate::process::command("/usr/sbin/diskutil");
        cmd.args(["info", "-plist", m.scan_root.as_deref().unwrap_or(&m.mount)]);
        crate::process::run_with_timeout(cmd, std::time::Duration::from_secs(5))
            .ok()
            .filter(|o| o.status.success())
            .and_then(|o| parse_diskutil_info(&o.stdout))
            .unwrap_or_default()
    }
    #[cfg(target_os = "linux")]
    {
        let mut t = m.device.as_deref().map(|d| linux_traits(Path::new("/sys"), d)).unwrap_or_default();
        t.identity = linux_identity(Path::new("/dev/disk/by-uuid"), &m.source);
        t
    }
    #[cfg(windows)]
    {
        win::traits(m)
    }
    #[cfg(not(any(target_os = "macos", target_os = "linux", windows)))]
    {
        let _ = m;
        MediaTraits::default()
    }
}

/// The mounts as `getfsstat` lists them.
#[cfg(target_os = "macos")]
fn macos_mounts() -> Vec<RawMount> {
    read_fsstat(Path::new("/Volumes"), |buf, bytes| {
        // SAFETY: `buf` is null with `bytes` 0 (only the count is asked) or valid for `bytes` bytes, as `read_fsstat` makes it.
        unsafe { libc::getfsstat(buf, bytes, libc::MNT_NOWAIT) }
    })
}

/// Reads the mount table through `fsstat` (`getfsstat`: called once for the count, once to fill a buffer of that many
/// entries). An empty or failing table is an empty list.
#[cfg(target_os = "macos")]
fn read_fsstat(volumes_dir: &Path, fsstat: impl Fn(*mut libc::statfs, i32) -> i32) -> Vec<RawMount> {
    let count = fsstat(std::ptr::null_mut(), 0);
    let Ok(n) = usize::try_from(count) else { return Vec::new() };
    if n == 0 {
        return Vec::new();
    }
    // SAFETY: `statfs` is plain data; zero is a valid bit pattern.
    let mut buf: Vec<libc::statfs> = vec![unsafe { std::mem::zeroed() }; n];
    let bytes = i32::try_from(n * std::mem::size_of::<libc::statfs>()).unwrap_or(i32::MAX);
    let got = fsstat(buf.as_mut_ptr(), bytes);
    let got = usize::try_from(got).unwrap_or(0).min(n);
    mounts_from_statfs(&buf[..got], volumes_dir)
}

#[cfg(target_os = "macos")]
fn mounts_from_statfs(entries: &[libc::statfs], volumes_dir: &Path) -> Vec<RawMount> {
    let text = |a: &[libc::c_char]| {
        let b: Vec<u8> = a.iter().take_while(|c| **c != 0).map(|c| *c as u8).collect();
        String::from_utf8_lossy(&b).into_owned()
    };
    let mut out: Vec<RawMount> = entries
        .iter()
        .map(|s| RawMount {
            source: text(&s.f_mntfromname),
            mount: text(&s.f_mntonname),
            fs: text(&s.f_fstypename),
            read_only: s.f_flags & (libc::MNT_RDONLY as u32) != 0,
            hidden: s.f_flags & (libc::MNT_DONTBROWSE as u32) != 0 && text(&s.f_mntonname) != MACOS_DATA,
            ..RawMount::default()
        })
        .collect();
    // The startup disk carries the name of the `/Volumes` link that points at `/`.
    if let Some(root) = out.iter_mut().find(|m| m.mount == MACOS_DATA) {
        root.name = Some(macos_startup_name(volumes_dir).unwrap_or_else(|| "Macintosh HD".into()));
    }
    out
}

#[cfg(windows)]
mod win {
    use super::{MediaTraits, RawMount};
    use windows::core::{PCWSTR, PWSTR};
    use windows::Win32::NetworkManagement::WNet::WNetGetConnectionW;
    use windows::Win32::Storage::FileSystem::{
        GetDiskFreeSpaceExW, GetDriveTypeW, GetLogicalDriveStringsW, GetVolumeInformationW, GetVolumeNameForVolumeMountPointW,
    };

    // The `GetDriveTypeW` results (winbase.h).
    const DRIVE_REMOVABLE: u32 = 2;
    const DRIVE_FIXED: u32 = 3;
    const DRIVE_REMOTE: u32 = 4;
    const DRIVE_RAMDISK: u32 = 6;

    fn wide(s: &str) -> Vec<u16> {
        s.encode_utf16().chain(std::iter::once(0)).collect()
    }

    fn text(buf: &[u16]) -> String {
        String::from_utf16_lossy(&buf[..buf.iter().position(|c| *c == 0).unwrap_or(buf.len())])
    }

    pub(super) fn capacity(mount: &str) -> Option<(u64, u64)> {
        let root = wide(mount);
        let (mut free, mut total) = (0u64, 0u64);
        // SAFETY: `root` is NUL-terminated and both out pointers are valid for the call.
        unsafe { GetDiskFreeSpaceExW(PCWSTR(root.as_ptr()), Some(&mut free), Some(&mut total), None) }.ok()?;
        Some((total, free))
    }

    pub(super) fn mounts() -> Vec<RawMount> {
        let mut buf = vec![0u16; 512];
        // SAFETY: the buffer is valid for its length.
        let n = unsafe { GetLogicalDriveStringsW(Some(&mut buf)) } as usize;
        if n == 0 || n > buf.len() {
            return Vec::new();
        }
        buf[..n]
            .split(|c| *c == 0)
            .filter(|d| !d.is_empty())
            .filter_map(|d| {
                let mount = String::from_utf16_lossy(d);
                let root = wide(&mount);
                // SAFETY: `root` is NUL-terminated.
                let kind = unsafe { GetDriveTypeW(PCWSTR(root.as_ptr())) };
                if kind != DRIVE_FIXED && kind != DRIVE_REMOVABLE && kind != DRIVE_REMOTE && kind != DRIVE_RAMDISK {
                    return None;
                }
                let mut fs = [0u16; 64];
                // SAFETY: `root` is NUL-terminated; the buffer is valid for its length.
                let fs_name = unsafe { GetVolumeInformationW(PCWSTR(root.as_ptr()), None, None, None, None, Some(&mut fs)) }
                    .map(|()| text(&fs))
                    .unwrap_or_default();
                let mut source = mount.clone();
                if kind == DRIVE_REMOTE {
                    let local = wide(mount.trim_end_matches('\\'));
                    let mut remote = [0u16; 512];
                    let mut len = remote.len() as u32;
                    // SAFETY: `local` is NUL-terminated; `remote` is valid for `len` units.
                    if unsafe { WNetGetConnectionW(PCWSTR(local.as_ptr()), Some(PWSTR(remote.as_mut_ptr())), &mut len) }.0 == 0 {
                        source = text(&remote);
                    }
                }
                Some(RawMount {
                    source,
                    mount,
                    // A mapped drive is a network volume whatever its file system says.
                    fs: if kind == DRIVE_REMOTE {
                        "smb".into()
                    } else {
                        fs_name.to_ascii_lowercase()
                    },
                    ..RawMount::default()
                })
            })
            .collect()
    }

    /// The volume GUID path (`\\?\Volume{...}\`) of the volume mounted at `mount`: it stays the same for a disk whatever
    /// drive letter it gets, and differs between disks.
    pub(super) fn identity(mount: &str) -> Option<String> {
        let root = wide(mount);
        let mut buf = [0u16; 64];
        // SAFETY: `root` is NUL-terminated; the buffer is valid for its length.
        unsafe { GetVolumeNameForVolumeMountPointW(PCWSTR(root.as_ptr()), &mut buf) }.ok()?;
        let guid = Some(text(&buf)).filter(|t| !t.is_empty())?;
        let mut raw_serial = 0u32;
        // SAFETY: `root` is NUL-terminated and the serial out pointer is valid for the call.
        let read = unsafe {
            GetVolumeInformationW(
                PCWSTR(root.as_ptr()),
                None,
                Some(std::ptr::addr_of_mut!(raw_serial)),
                None,
                None,
                None,
            )
        };
        Some(super::compose_windows_identity(&guid, read.ok().map(|()| raw_serial)))
    }

    pub(super) fn traits(m: &RawMount) -> MediaTraits {
        let root = wide(&m.mount);
        // SAFETY: `root` is NUL-terminated.
        let kind = unsafe { GetDriveTypeW(PCWSTR(root.as_ptr())) };
        MediaTraits {
            internal: (kind == DRIVE_FIXED).then_some(true),
            removable: (kind == DRIVE_REMOVABLE).then_some(true),
            identity: if kind == DRIVE_REMOTE { None } else { identity(&m.mount) },
            ..MediaTraits::default()
        }
    }
}

