                events: vec![m.kind.clone()],
                ..cfg("n", ntfy("not a url", "t\n", None))
            },
            ChannelConfig {
                events: vec![m.kind.clone()],
                ..cfg("m", email(vec!["bad address"]))
            },
        ],
    });
    let r = d.dispatch(&m, &MemorySecrets::new().with("smtp-pw", "x"));
    assert_eq!(r.len(), 3);
    assert!(r.iter().all(|(_, res)| res.is_err()));
}

