//! Runner-scoped resource use: the CPU and resident memory of a runner process and everything it started (the job's
//! shells, compilers, test processes, browsers), as opposed to the whole machine (ADR 0007).
//!
//! Everything here is pure. The service reads a process table from the OS ([`ProcessInfo`]) on every probe tick,
//! [`tree_members`] picks the runner's processes, [`UsageTracker`] turns the change in their cumulative CPU time into
//! a share of the machine's capacity, and [`UsageAcc`] averages the ticks of one sample period (and later the
//! buckets of the history tiers).
//!
//! # What counts as "the runner's processes"
//!
//! The runner process, every descendant by parent pid, and every process in the runner's process group (Pitcrew
//! starts runners as group leaders on macOS and Linux, so a job process that was reparented to `init` when its
//! parent exited is still counted). A process that leaves the group *and* loses its parent (a daemon that calls
//! `setsid`) is not counted: it is no longer the job's, and following it would mean guessing.

use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};

/// Most processes counted for one runner; a fork bomb must not make the sampler slow or the result huge.
pub const MAX_TREE_PROCESSES: usize = 4096;

/// One row of the OS process table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProcessInfo {
    /// Process id.
    pub pid: u32,
    /// Parent process id, when known.
    pub ppid: Option<u32>,
    /// Process group id (Unix), when known.
    pub pgid: Option<u32>,
    /// Cumulative CPU time (user + system) in milliseconds.
    pub cpu_time_ms: u64,
    /// Resident memory in bytes.
    pub rss_bytes: u64,
}

/// The processes that belong to the runner with process id `root`: the root, its descendants and its process group,
/// at most [`MAX_TREE_PROCESSES`]. Empty when `root` is not in the table (the runner is gone) or is a system pid.
// ADR 0033 WP-6: a tree by parent pids without start times; skip a child older than its parent (paddock_proc::descendants)
pub fn tree_members(root: u32, table: &[ProcessInfo]) -> Vec<ProcessInfo> {
    if root <= 1 || !table.iter().any(|p| p.pid == root) {
        return Vec::new();
    }
    let by_pid: HashMap<u32, usize> = table.iter().enumerate().map(|(i, p)| (p.pid, i)).collect();
    let mut children: HashMap<u32, Vec<usize>> = HashMap::new();
    for (i, p) in table.iter().enumerate() {
        if let Some(parent) = p.ppid {
            if parent != p.pid {
                children.entry(parent).or_default().push(i);
            }
        }
    }
    let mut seen: HashSet<u32> = HashSet::new();
    let mut out: Vec<ProcessInfo> = Vec::new();
    let mut queue: Vec<u32> = vec![root];
    queue.extend(table.iter().filter(|p| p.pgid == Some(root)).map(|p| p.pid));
    while let Some(pid) = queue.pop() {
        if out.len() >= MAX_TREE_PROCESSES {
            break;
        }
        if !seen.insert(pid) {
            continue;
        }
        if let Some(&i) = by_pid.get(&pid) {
            out.push(table[i]);
        }
        if let Some(kids) = children.get(&pid) {
            queue.extend(kids.iter().map(|&i| table[i].pid));
        }
    }
    out
}

/// What a set of processes used. As a tick it is instantaneous (peak = value); as a sample or a bucket it is the
/// average with the peak next to it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct Usage {
    /// CPU time used, per mille of the whole machine's capacity (all cores = 1000), averaged.
    pub cpu_permille: u32,
    /// The highest CPU share seen.
    pub cpu_peak_permille: u32,
    /// Resident memory, averaged.
    pub mem_bytes: u64,
    /// The highest resident memory seen.
    pub mem_peak_bytes: u64,
    /// Most processes counted at one moment.
    pub processes: u32,
}

impl Usage {
    /// An instantaneous reading.
    pub fn tick(cpu_permille: u32, mem_bytes: u64, processes: u32) -> Self {
        Usage {
            cpu_permille,
            cpu_peak_permille: cpu_permille,
            mem_bytes,
            mem_peak_bytes: mem_bytes,
            processes,
        }
    }

    /// The readings of several runners at the same moment added up.
    pub fn sum<'a>(items: impl IntoIterator<Item = &'a Usage>) -> Usage {
        let mut t = Usage::default();
        for u in items {
            t.cpu_permille = t.cpu_permille.saturating_add(u.cpu_permille);
            t.cpu_peak_permille = t.cpu_peak_permille.saturating_add(u.cpu_peak_permille);
            t.mem_bytes = t.mem_bytes.saturating_add(u.mem_bytes);
            t.mem_peak_bytes = t.mem_peak_bytes.saturating_add(u.mem_peak_bytes);
            t.processes = t.processes.saturating_add(u.processes);
        }
        t
    }
}

/// Accumulates [`Usage`] values into their average and peaks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
pub struct UsageAcc {
    n: u64,
    cpu: u64,
    cpu_peak: u32,
    mem: u128,
    mem_peak: u64,
    processes: u32,
}

impl UsageAcc {
    /// Adds a value.
    pub fn add(&mut self, u: &Usage) {
        self.n += 1;
        self.cpu += u64::from(u.cpu_permille);
        self.cpu_peak = self.cpu_peak.max(u.cpu_peak_permille).max(u.cpu_permille);
        self.mem += u128::from(u.mem_bytes);
        self.mem_peak = self.mem_peak.max(u.mem_peak_bytes).max(u.mem_bytes);
        self.processes = self.processes.max(u.processes);
    }

    /// Whether nothing was added.
    pub fn is_empty(&self) -> bool {
        self.n == 0
    }

    /// The average with the peaks; all zero when empty.
    pub fn mean(&self) -> Usage {
        let n = self.n.max(1);
        Usage {
            cpu_permille: u32::try_from(self.cpu / n).unwrap_or(u32::MAX),
            cpu_peak_permille: self.cpu_peak,
            mem_bytes: u64::try_from(self.mem / u128::from(n)).unwrap_or(u64::MAX),
            mem_peak_bytes: self.mem_peak,
            processes: self.processes,
        }
    }

    /// The average, and a fresh accumulator in its place.
    pub fn take(&mut self) -> Option<Usage> {
        let out = (!self.is_empty()).then(|| self.mean());
        *self = UsageAcc::default();
        out
    }
}

/// Turns cumulative CPU times into a share of the machine: one tracker per runner.
#[derive(Debug, Clone, Default)]
pub struct UsageTracker {
    previous: HashMap<u32, u64>,
    at_ms: Option<u64>,
    /// Each process's share of the machine at the last reading, per mille.
    shares: HashMap<u32, u32>,
}

impl UsageTracker {
    /// A tracker with no history.
    pub fn new() -> Self {
        Self::default()
    }

    /// Forgets the history (the runner stopped); the next reading has no CPU share.
    pub fn reset(&mut self) {
        self.previous.clear();
        self.at_ms = None;
        self.shares.clear();
    }

    /// The CPU share (per mille of the machine) of one process at the last reading; 0 when unknown.
    pub fn share_of(&self, pid: u32) -> u32 {
        self.shares.get(&pid).copied().unwrap_or(0)
    }

    /// The use of `members` at `now_ms` on a machine with `cpus` logical cores.
    ///
    /// CPU is the CPU time the members gained since the previous reading, divided by `elapsed × cpus`. A process
    /// seen for the first time counts all of its CPU time (it started within the interval), except in the very
    /// first reading, which only sets the baseline. Processes that exited between readings take their last
    /// interval's time with them: that is a small under-count, preferred to guessing.
    pub fn observe(&mut self, now_ms: u64, members: &[ProcessInfo], cpus: usize) -> Usage {
        let mem: u64 = members.iter().fold(0, |a, p| a.saturating_add(p.rss_bytes));
        let processes = u32::try_from(members.len()).unwrap_or(u32::MAX);
        let cpu = match self.at_ms {
            Some(before) if now_ms > before => {
                let gained: u64 = members.iter().fold(0u64, |a, p| {
                    a.saturating_add(p.cpu_time_ms.saturating_sub(self.previous.get(&p.pid).copied().unwrap_or(0)))
                });
                let capacity = u128::from(now_ms - before) * cpus.max(1) as u128;
                u32::try_from((u128::from(gained) * 1000 / capacity).min(1000)).unwrap_or(1000)
            }
            _ => 0,
        };
        self.shares = match self.at_ms {
            Some(before) if now_ms > before => {
                let capacity = u128::from(now_ms - before) * cpus.max(1) as u128;
                members
                    .iter()
                    .map(|p| {
                        let gained = p.cpu_time_ms.saturating_sub(self.previous.get(&p.pid).copied().unwrap_or(0));
                        (
                            p.pid,
                            u32::try_from((u128::from(gained) * 1000 / capacity).min(1000)).unwrap_or(1000),
                        )
                    })
                    .collect()
            }
            _ => HashMap::new(),
        };
        if self.at_ms.is_none_or(|before| now_ms > before) {
            self.at_ms = Some(now_ms);
            self.previous = members.iter().map(|p| (p.pid, p.cpu_time_ms)).collect();
        }
        Usage::tick(cpu, mem, processes)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn p(pid: u32, ppid: Option<u32>, pgid: Option<u32>, cpu: u64, rss: u64) -> ProcessInfo {
        ProcessInfo {
            pid,
            ppid,
            pgid,
            cpu_time_ms: cpu,
            rss_bytes: rss,
        }
    }

    fn pids(v: &[ProcessInfo]) -> Vec<u32> {
        let mut x: Vec<u32> = v.iter().map(|p| p.pid).collect();
        x.sort_unstable();
        x
    }

    #[test]
    fn the_tree_is_descendants_and_group_members() {
        let table = [
            p(1, None, None, 0, 0),
            p(100, Some(1), Some(100), 0, 10),
            p(101, Some(100), Some(100), 0, 10),
            p(102, Some(101), Some(102), 0, 10), // grandchild in its own group
            p(103, Some(1), Some(100), 0, 10),   // reparented to init, still in the runner's group
            p(104, Some(103), Some(104), 0, 10), // child of that orphan
            p(200, Some(1), Some(200), 0, 10),   // another runner
            p(201, Some(200), Some(200), 0, 10),
        ];
        assert_eq!(pids(&tree_members(100, &table)), vec![100, 101, 102, 103, 104]);
        assert_eq!(pids(&tree_members(200, &table)), vec![200, 201]);
    }

    #[test]
    fn a_missing_or_system_root_has_no_members() {
        let table = [p(1, None, None, 0, 0), p(5, Some(1), None, 0, 0)];
        assert!(tree_members(999, &table).is_empty());
        assert!(tree_members(1, &table).is_empty());
        assert!(tree_members(0, &table).is_empty());
        assert!(tree_members(5, &[]).is_empty());
    }

    #[test]
    fn cycles_and_self_parents_terminate() {
        let table = [
            p(10, Some(10), None, 0, 0),
            p(11, Some(12), None, 0, 0),
            p(12, Some(11), None, 0, 0),
        ];
        assert_eq!(pids(&tree_members(10, &table)), vec![10]);
        let loop_table = [
            p(10, Some(12), None, 0, 0),
            p(11, Some(10), None, 0, 0),
            p(12, Some(11), None, 0, 0),
        ];
        assert_eq!(pids(&tree_members(10, &loop_table)), vec![10, 11, 12]);
    }

    #[test]
    fn the_tree_is_bounded() {
        let mut table = vec![p(10, Some(1), None, 0, 0)];
        for i in 0..(MAX_TREE_PROCESSES as u32 + 100) {
            table.push(p(1000 + i, Some(10), None, 0, 0));
        }
        assert_eq!(tree_members(10, &table).len(), MAX_TREE_PROCESSES);
    }

    #[test]
    fn cpu_is_a_share_of_the_machine() {
        let mut t = UsageTracker::new();
        let first = t.observe(0, &[p(10, None, None, 5_000, 100), p(11, None, None, 1_000, 50)], 4);
        assert_eq!((first.cpu_permille, first.mem_bytes, first.processes), (0, 150, 2), "baseline only");
        // 5 s later: process 10 gained 5 s (one core of four = 25%), process 11 gained 1 s (5%).
        let u = t.observe(5_000, &[p(10, None, None, 10_000, 120), p(11, None, None, 2_000, 60)], 4);
        assert_eq!(u.cpu_permille, 300);
        assert_eq!(u.cpu_peak_permille, 300);
        assert_eq!(u.mem_bytes, 180);
        assert_eq!(u.mem_peak_bytes, 180);
    }

    #[test]
    fn new_processes_count_and_exited_ones_drop_out() {
        let mut t = UsageTracker::new();
        t.observe(0, &[p(10, None, None, 100, 1)], 2);
        // A compiler appears with 4 s of CPU in a 5 s interval on 2 cores: 40%, plus 0 for the runner.
        let u = t.observe(5_000, &[p(10, None, None, 100, 1), p(20, None, None, 4_000, 500)], 2);
        assert_eq!((u.cpu_permille, u.processes, u.mem_bytes), (400, 2, 501));
        // It exits: gone from the count, and a new process reusing nothing else starts from zero again.
        let u = t.observe(10_000, &[p(10, None, None, 100, 1)], 2);
        assert_eq!((u.cpu_permille, u.processes, u.mem_bytes), (0, 1, 1));
    }

    #[test]
    fn cpu_is_clamped_and_time_going_backwards_is_ignored() {
        let mut t = UsageTracker::new();
        t.observe(10_000, &[p(10, None, None, 0, 1)], 1);
        let u = t.observe(11_000, &[p(10, None, None, 50_000, 1)], 1);
        assert_eq!(u.cpu_permille, 1000, "never above the machine");
        let same = t.observe(11_000, &[p(10, None, None, 99_000, 1)], 1);
        assert_eq!(same.cpu_permille, 0, "no time passed");
        let back = t.observe(5_000, &[p(10, None, None, 99_000, 1)], 1);
        assert_eq!(back.cpu_permille, 0, "clock went back");
        // A counter that went backwards (pid reuse) is not negative CPU.
        let after = t.observe(12_000, &[p(10, None, None, 10, 1)], 1);
        assert_eq!(after.cpu_permille, 0);
        // Zero cores is treated as one.
        let mut z = UsageTracker::new();
        z.observe(0, &[p(1, None, None, 0, 0)], 0);
        assert_eq!(z.observe(1_000, &[p(1, None, None, 500, 0)], 0).cpu_permille, 500);
    }

    #[test]
    fn reset_forgets_the_baseline() {
        let mut t = UsageTracker::new();
        t.observe(0, &[p(10, None, None, 0, 1)], 1);
        t.reset();
        assert_eq!(t.observe(5_000, &[p(10, None, None, 4_000, 1)], 1).cpu_permille, 0);
    }

    #[test]
    fn accumulation_averages_and_keeps_peaks() {
        let mut a = UsageAcc::default();
        assert!(a.is_empty());
        assert_eq!(a.mean(), Usage::default());
        assert_eq!(a.take(), None);
        a.add(&Usage::tick(100, 1000, 2));
        a.add(&Usage::tick(300, 3000, 5));
        let u = a.mean();
        assert_eq!(
            (u.cpu_permille, u.cpu_peak_permille, u.mem_bytes, u.mem_peak_bytes, u.processes),
            (200, 300, 2000, 3000, 5)
        );
        assert_eq!(a.take(), Some(u));
        assert!(a.is_empty(), "taking starts a new period");
    }

    #[test]
    fn sums_add_up_and_saturate() {
        let a = Usage::tick(100, 10, 1);
        let b = Usage::tick(250, 20, 3);
        assert_eq!(Usage::sum([&a, &b]), Usage::tick(350, 30, 4));
        assert_eq!(Usage::sum([]), Usage::default());
        let big = Usage::tick(u32::MAX, u64::MAX, u32::MAX);
        assert_eq!(Usage::sum([&big, &big]), big);
    }

    #[test]
    fn old_json_without_new_fields_loads() {
        let u: Usage = serde_json::from_str("{}").unwrap();
        assert_eq!(u, Usage::default());
    }

    #[test]
    fn each_process_gets_its_own_share() {
        let mut t = UsageTracker::new();
        let first = [p(10, None, None, 1000, 5), p(11, Some(10), None, 0, 5)];
        t.observe(0, &first, 4);
        assert_eq!(t.share_of(10), 0, "the first reading only sets the baseline");
        // 1 s later on 4 cores: process 10 used 2 s of CPU (500 per mille of the machine), 11 used 1 s, 12 is new.
        let second = [
            p(10, None, None, 3000, 5),
            p(11, Some(10), None, 1000, 5),
            p(12, Some(10), None, 400, 5),
        ];
        let u = t.observe(1000, &second, 4);
        assert_eq!(t.share_of(10), 500);
        assert_eq!(t.share_of(11), 250);
        assert_eq!(t.share_of(12), 100);
        assert_eq!(t.share_of(99), 0);
        assert_eq!(u.cpu_permille, 850, "the shares add up to the total");
        t.reset();
        assert_eq!(t.share_of(10), 0);
    }
}

//! A stand-in for `gitea-runner` in the service's integration tests (`tests/supervision.rs`). Never shipped.
//!
//! Behaviour comes from `fake.txt` next to the configuration file (one `key=value` per line), so parallel tests
//! don't share environment variables:
//!
//! - `mode=ok` (default): declares itself and idles; `exit` exits with `code` after declaring; `stall` logs
//!   "failed to fetch task" lines every 100 ms; `job` logs "task started" and runs a child process for `job_secs`;
//!   `silent` never declares (an update that is not accepted).
//! - `leftover`: like `job`, but the job's shell also starts background processes that outlive it (`leftovers`, a
//!   comma-separated list of `sleep:<seconds>` or program names, default `sleep:600`); `job_secs` is how long the job
//!   itself lasts. They stay in the runner's process group, as a Gradle daemon would.
//! - `job_secs=hold` (in `job` and `leftover` mode): the job lasts until the test creates a file `release` next to the
//!   configuration file, so a test decides when a job ends instead of racing a real-time job against a loaded machine.
//! - Once a job's processes run (and a `leftover` job's background processes run their own programs), it writes
//!   `job.started` next to the configuration file.
//! - `spawn_delay_ms` (in `job` and `leftover` mode): the job's process starts this long after the "task started" line,
//!   as on a loaded machine; a test that takes the line for the process sees the race every time.
//! - The labels it declares are the names under `runner.labels` in its `config.yaml` (default `x`); `declare=a,b` in
//!   `fake.txt` declares those instead (a runner whose registration disagrees with the file).
//! - `--version` prints `gitea-runner version v<version>`, where the version is the text after `FAKEVER:` at the end
//!   of the executable file (tests append it to their copy), else 5.2.0.
//! - Writes `PATH` and `CI_FLAG` from its environment to `env.txt` next to the configuration file.
//! - Ctrl+Break / SIGTERM: logs the shutdown line and exits 0 (waiting for a running job first, a held one until it is
//!   released).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::disallowed_methods, missing_docs)]

use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

fn log(msg: &str, extra: &str) {
    let mut out = std::io::stdout().lock();
    let _ = writeln!(out, r#"time="2026-10-22T06:57:19+08:00" level=info msg="{msg}"{extra}"#);
    let _ = out.flush();
}

fn own_version() -> String {
    let exe = std::env::current_exe().unwrap();
    let bytes = std::fs::read(exe).unwrap_or_default();
    let tail = &bytes[bytes.len().saturating_sub(64)..];
    let text = String::from_utf8_lossy(tail);
    text.rsplit_once("FAKEVER:")
        .map(|(_, v)| v.trim().to_string())
        .unwrap_or_else(|| "5.2.0".into())
}

fn settings(config: Option<&str>) -> std::collections::HashMap<String, String> {
    let dir = config
        .and_then(|c| std::path::Path::new(c).parent().map(|p| p.to_path_buf()))
        .unwrap_or_else(|| ".".into());
    std::fs::read_to_string(dir.join("fake.txt"))
        .unwrap_or_default()
        .lines()
        .filter_map(|l| l.split_once('='))
        .map(|(k, v)| (k.trim().to_string(), v.trim().to_string()))
        .collect()
}

/// The label names under `labels:` in the runner's configuration file.
fn labels_from_config(config: Option<&str>) -> Vec<String> {
    let text = config.and_then(|c| std::fs::read_to_string(c).ok()).unwrap_or_default();
    let mut out = vec![];
    let mut inside = false;
    for line in text.lines() {
        let t = line.trim();
        if t.starts_with("labels:") {
            inside = true;
        } else if inside && t.starts_with('-') {
            let v = t.trim_start_matches('-').trim().trim_matches(['"', '\'']);
            out.push(v.split(':').next().unwrap_or(v).to_string());
        } else if inside && !t.is_empty() && !t.starts_with('#') {
            inside = false;
        }
    }
    if out.is_empty() {
        out.push("x".into());
    }
    out
}

/// How long the job lasts, in seconds; `hold` keeps it running until the test releases it.
fn job_secs(s: &std::collections::HashMap<String, String>, default: &str) -> String {
    match s.get("job_secs").map(String::as_str) {
        Some("hold") => "100000".into(),
        Some(v) => v.into(),
        None => default.into(),
    }
}

/// Waits `spawn_delay_ms` before the job's process starts.
fn spawn_delay(s: &std::collections::HashMap<String, String>) {
    if let Some(ms) = s.get("spawn_delay_ms").and_then(|v| v.parse().ok()) {
        std::thread::sleep(Duration::from_millis(ms));
    }
}

/// Marks the job's processes as started (`job.started` next to the configuration file): a test waits for it before
/// it lets the supervisor look, so the first look sees them.
fn job_started(config: Option<&str>) {
    if let Some(dir) = config.and_then(|c| std::path::Path::new(c).parent()) {
        std::fs::write(dir.join("job.started"), "").unwrap();
    }
}

/// Whether process `pid` runs its own program now (no longer the shell that forked it), or is gone.
fn exec_done(pid: &str) -> bool {
    if pid.is_empty() {
        return true;
    }
    let out = std::process::Command::new("ps").args(["-o", "comm=", "-p", pid]).output().unwrap();
    let comm = String::from_utf8_lossy(&out.stdout);
    let comm = comm.trim();
    comm.is_empty() || !(comm == "sh" || comm.ends_with("/sh"))
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let config = args.iter().position(|a| a == "--config").and_then(|i| args.get(i + 1)).cloned();
    match args
        .iter()
        .find(|a| !a.starts_with('-') && Some(*a) != config.as_ref())
        .map(String::as_str)
    {
        Some("generate-config") => {
            println!("log:\n  level: info\ncache:\n  enabled: true\n  dir: \"\"\nhost:\n  workdir_parent:\n");
            return;
        }
        Some("register") => {
            let token = args
                .iter()
                .position(|a| a == "--token")
                .and_then(|i| args.get(i + 1))
                .cloned()
                .unwrap_or_default();
            if token == "bad" {
                eprintln!("level=error msg=\"registration failed: token {token} is not valid\"");
                std::process::exit(1);
            }
            std::fs::write(".runner", "{\"fake\":true}").unwrap();
            println!("Runner registered successfully.");
            return;
        }
        Some("daemon") => {}
        _ => {
            if args.iter().any(|a| a == "--version") {
                println!("gitea-runner version v{}", own_version());
            }
            return;
        }
    }

    let s = settings(config.as_deref());
    // The environment it was started with, for tests of what the service passes (`PATH`, `CI_FLAG`).
    if let Some(dir) = config.as_deref().and_then(|c| std::path::Path::new(c).parent()) {
        let dump: String = ["PATH", "CI_FLAG"]
            .iter()
            .map(|k| format!("{k}={}\n", std::env::var(k).unwrap_or_default()))
            .collect();
        let _ = std::fs::write(dir.join("env.txt"), dump);
        let _ = std::fs::remove_file(dir.join("job.started"));
    }
    let mode = s.get("mode").cloned().unwrap_or_else(|| "ok".into());
    let stop = Arc::new(AtomicBool::new(false));
    let flag = stop.clone();
    ctrlc::set_handler(move || flag.store(true, Ordering::SeqCst)).unwrap();
    log("Starting runner daemon", "");
    if mode != "silent" {
        let labels = s
            .get("declare")
            .map(|d| d.split(',').map(str::to_string).collect())
            .unwrap_or_else(|| labels_from_config(config.as_deref()));
        log(
            &format!(
                "runner: fake, with version: v5.2.0, with labels: [{}], declare successfully",
                labels.join(" ")
            ),
            "",
        );
    }
    if mode == "exit" {
        std::thread::sleep(Duration::from_millis(200));
        std::process::exit(s.get("code").and_then(|c| c.parse().ok()).unwrap_or(3));
    }
    let mut child = None;
    if mode == "leftover" && !cfg!(windows) {
        log(
            "task started",
            " address=\"https://git.example.com\" job=build job_id=7 repository=owner/app run_id=9 run_number=3 task_id=11",
        );
        let secs = job_secs(&s, "2");
        let leftovers = s.get("leftovers").cloned().unwrap_or_else(|| "sleep:600".into());
        let mut script = String::new();
        let mut count = 0;
        for l in leftovers.split(',') {
            match l.split_once(':') {
                Some(("sleep", n)) => script.push_str(&format!("sleep {n} >/dev/null 2>&1 & echo $!; ")),
                _ => script.push_str(&format!("{l} -f /dev/null >/dev/null 2>&1 & echo $!; ")),
            }
            count += 1;
        }
        // `exec`: the job's shell becomes its last step, so ending a held job ends that one process.
        script.push_str(&format!("exec sleep {secs} >/dev/null"));
        let mut cmd = std::process::Command::new("sh");
        cmd.args(["-c", &script]).stdout(std::process::Stdio::piped());
        spawn_delay(&s);
        let mut c = cmd.spawn().unwrap();
        // The leftovers' ids; each counts as started once it runs its own program (a process seen between its fork
        // and its exec keeps the shell's name in the process table).
        let mut lines = std::io::BufRead::lines(std::io::BufReader::new(c.stdout.take().unwrap()));
        for _ in 0..count {
            let pid = lines.next().and_then(Result::ok).unwrap_or_default();
            while !exec_done(pid.trim()) {
                std::thread::sleep(Duration::from_millis(10));
            }
        }
        child = Some(c);
        job_started(config.as_deref());
    }
    if mode == "job" {
        log(
            "task started",
            " address=\"https://git.example.com\" job=build job_id=7 repository=owner/app run_id=9 run_number=3 task_id=11",
        );
        let secs = job_secs(&s, "3");
        let mut cmd = if cfg!(windows) {
            let mut c = std::process::Command::new("ping");
            c.args(["-n", &(secs.parse::<u32>().unwrap_or(3) + 1).to_string(), "127.0.0.1"]);
            c
        } else {
            let mut c = std::process::Command::new("sleep");
            c.arg(&secs);
            c
        };
        cmd.stdout(std::process::Stdio::null());
        spawn_delay(&s);
        child = Some(cmd.spawn().unwrap());
        job_started(config.as_deref());
    }
    let held = s.get("job_secs").is_some_and(|v| v == "hold");
    let release = config
        .as_deref()
        .and_then(|c| std::path::Path::new(c).parent())
        .unwrap_or_else(|| std::path::Path::new("."))
        .join("release");
    let mut stopping = false;
    loop {
        if held && release.exists() {
            if let Some(mut c) = child.take() {
                let _ = c.kill();
                let _ = c.wait();
            }
        }
        if stop.load(Ordering::SeqCst) && !stopping {
            stopping = true;
            log(
                "runner: fake shutdown initiated, waiting 0s for running jobs to complete before shutting down",
                "",
            );
        }
        if stopping && child.is_none() {
            std::process::exit(0);
        }
        if mode == "stall" {
            let _ = writeln!(
                std::io::stdout(),
                r#"time="2026-10-22T06:57:19+08:00" level=error msg="failed to fetch task" error="deadline_exceeded: context deadline exceeded""#
            );
            let _ = std::io::stdout().flush();
        }
        if let Some(c) = child.as_mut() {
            if let Ok(Some(_)) = c.try_wait() {
                child = None;
            }
        }
        std::thread::sleep(Duration::from_millis(100));
    }
}

//! macOS: start the runner as its own *responsible process* (ADR 0020).
//!
//! macOS attributes a process's access to protected folders (Documents, Desktop, Downloads, removable volumes...) to its
//! *responsible process*, by default the app that started it. The runner and every CI job are started by Pitcrew's
//! service from the Pitcrew.app bundle, so a job that reads `~/Documents` made macOS ask "Pitcrew.app would like to
//! access files in your Documents folder", although Pitcrew itself never touches it. Terminal, iTerm2 and VS Code avoid
//! this with `responsibility_spawnattrs_setdisclaim(attr, 1)` (a private but long-stable libSystem function) on the
//! `posix_spawn` attributes: the child, and so its descendants, are their own responsible processes.
//!
//! `std::process::Command` offers no hook into the spawn attributes, so this module spawns with `posix_spawn` itself,
//! keeping what the std path gave: a pipe each for standard output and error, no standard input, its own process group
//! (graceful stop and tree kill use the group), the working folder, the environment, `SIGPIPE` back to its default and
//! no inherited descriptors. The function is looked up with `dlsym`; if it is missing the runner is started the old way
//! (still without the disclaim) and the supervisor logs that once.
//!
//! This is the one place on macOS with `unsafe` (FFI to libSystem); every block says why it is sound.
#![allow(unsafe_code)]

use std::ffi::{c_int, CString};
use std::fs::File;
use std::os::fd::{AsRawFd, FromRawFd, IntoRawFd, OwnedFd};
use std::path::Path;

/// `int responsibility_spawnattrs_setdisclaim(posix_spawnattr_t *attr, int disclaim)`.
pub type DisclaimFn = unsafe extern "C" fn(*mut libc::posix_spawnattr_t, c_int) -> c_int;

/// The disclaim function of libSystem, when this macOS has it.
pub fn find_disclaim() -> Option<DisclaimFn> {
    // SAFETY: `dlsym` with RTLD_DEFAULT and a NUL-terminated name only reads the symbol table. The symbol, when present,
    // has the C signature above (it is what Terminal and VS Code call); a null result is mapped to `None`.
    unsafe {
        let p = libc::dlsym(libc::RTLD_DEFAULT, c"responsibility_spawnattrs_setdisclaim".as_ptr());
        if p.is_null() {
            None
        } else {
            Some(std::mem::transmute::<*mut libc::c_void, DisclaimFn>(p))
        }
    }
}

/// Whether this macOS lets the runner be started as its own responsible process.
pub fn disclaim_supported() -> bool {
    find_disclaim().is_some()
}

/// A process started by [`spawn`].
pub struct Spawned {
    /// Its process id (also its process group).
    pub pid: i32,
    /// Its standard output.
    pub stdout: File,
    /// Its standard error.
    pub stderr: File,
    /// The disclaim was applied to the spawn attributes.
    pub disclaimed: bool,
}

fn cstring(s: &std::ffi::OsStr) -> Result<CString, String> {
    use std::os::unix::ffi::OsStrExt;
    CString::new(s.as_bytes()).map_err(|_| "a program, argument or variable contains a NUL character".to_string())
}

fn check(rc: c_int, what: &str) -> Result<(), String> {
    if rc == 0 {
        Ok(())
    } else {
        Err(format!("{what} failed: {}", std::io::Error::from_raw_os_error(rc)))
    }
}

fn pipe() -> Result<(OwnedFd, OwnedFd), String> {
    nix::unistd::pipe().map_err(|e| format!("a pipe could not be made: {e}"))
}

/// Starts `program args` in `dir` with `env` over the service's own environment. `disclaim` is the function to apply
/// (`find_disclaim()` in production, a recorder in tests, `None` for the old behaviour).
pub fn spawn(
    program: &Path,
    args: &[String],
    dir: &Path,
    env: &[(String, String)],
    disclaim: Option<DisclaimFn>,
) -> Result<Spawned, String> {
    use std::os::unix::ffi::OsStrExt;
    let prog = cstring(program.as_os_str())?;
    let mut argv_c = vec![prog.clone()];
    for a in args {
        argv_c.push(cstring(std::ffi::OsStr::new(a))?);
    }
    let mut vars: std::collections::BTreeMap<std::ffi::OsString, std::ffi::OsString> = std::env::vars_os().collect();
    for (k, v) in env {
        vars.insert(k.into(), v.into());
    }
    let mut envp_c = Vec::with_capacity(vars.len());
    for (k, v) in &vars {
        let mut kv = k.as_bytes().to_vec();
        kv.push(b'=');
        kv.extend_from_slice(v.as_bytes());
        envp_c.push(CString::new(kv).map_err(|_| "a variable contains a NUL character".to_string())?);
    }
    let dir_c = cstring(dir.as_os_str())?;

    let (out_r, out_w) = pipe()?;
    let (err_r, err_w) = pipe()?;

    // SAFETY: attr and actions are initialised before use and destroyed on every path; all pointers passed to
    // posix_spawn (argv, envp, strings) outlive the call; the descriptors are valid until after it returns.
    unsafe {
        let mut attr: libc::posix_spawnattr_t = std::ptr::null_mut();
        check(libc::posix_spawnattr_init(&mut attr), "posix_spawnattr_init")?;
        let mut actions: libc::posix_spawn_file_actions_t = std::ptr::null_mut();
        if let Err(e) = check(libc::posix_spawn_file_actions_init(&mut actions), "posix_spawn_file_actions_init") {
            libc::posix_spawnattr_destroy(&mut attr);
            return Err(e);
        }
        let result = (|| -> Result<(i32, bool), String> {
            // Own process group; SIGPIPE back to the default (the service ignores it, and "ignored" is inherited); an
            // empty signal mask; no descriptors beyond the ones set up below.
            let mut default_sigs: libc::sigset_t = std::mem::zeroed();
            libc::sigemptyset(&mut default_sigs);
            libc::sigaddset(&mut default_sigs, libc::SIGPIPE);
            let mut mask: libc::sigset_t = std::mem::zeroed();
            libc::sigemptyset(&mut mask);
            check(
                libc::posix_spawnattr_setsigdefault(&mut attr, &default_sigs),
                "posix_spawnattr_setsigdefault",
            )?;
            check(libc::posix_spawnattr_setsigmask(&mut attr, &mask), "posix_spawnattr_setsigmask")?;
            check(libc::posix_spawnattr_setpgroup(&mut attr, 0), "posix_spawnattr_setpgroup")?;
            let flags = libc::POSIX_SPAWN_SETPGROUP
                | libc::POSIX_SPAWN_SETSIGDEF
                | libc::POSIX_SPAWN_SETSIGMASK
                | libc::POSIX_SPAWN_CLOEXEC_DEFAULT;
            check(
                libc::posix_spawnattr_setflags(&mut attr, flags as libc::c_short),
                "posix_spawnattr_setflags",
            )?;
            let mut disclaimed = false;
            if let Some(f) = disclaim {
                // The runner and its jobs become their own responsible processes (see the module comment).
                check(f(&mut attr, 1), "responsibility_spawnattrs_setdisclaim")?;
                disclaimed = true;
            }
            check(
                libc::posix_spawn_file_actions_addopen(&mut actions, 0, c"/dev/null".as_ptr(), libc::O_RDONLY, 0),
                "stdin",
            )?;
            check(libc::posix_spawn_file_actions_adddup2(&mut actions, out_w.as_raw_fd(), 1), "stdout")?;
            check(libc::posix_spawn_file_actions_adddup2(&mut actions, err_w.as_raw_fd(), 2), "stderr")?;
            check(
                libc::posix_spawn_file_actions_addchdir_np(&mut actions, dir_c.as_ptr()),
                "the working folder",
            )?;
            let mut argv: Vec<*mut libc::c_char> = argv_c.iter().map(|c| c.as_ptr().cast_mut()).collect();
            argv.push(std::ptr::null_mut());
            let mut envp: Vec<*mut libc::c_char> = envp_c.iter().map(|c| c.as_ptr().cast_mut()).collect();
            envp.push(std::ptr::null_mut());
            let mut pid: libc::pid_t = 0;
            check(
                libc::posix_spawn(&mut pid, prog.as_ptr(), &actions, &attr, argv.as_ptr(), envp.as_ptr()),
                "posix_spawn",
            )?;
            Ok((pid, disclaimed))
        })();
        libc::posix_spawn_file_actions_destroy(&mut actions);
        libc::posix_spawnattr_destroy(&mut attr);
        let (pid, disclaimed) = result.map_err(|e| format!("{} could not be started: {e}", program.display()))?;
        drop((out_w, err_w));
        // SAFETY: the read ends are valid descriptors we own; `File` takes over closing them.
        let stdout = File::from_raw_fd(out_r.into_raw_fd());
        let stderr = File::from_raw_fd(err_r.into_raw_fd());
        Ok(Spawned {
            pid,
            stdout,
            stderr,
            disclaimed,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Read;
    use std::sync::atomic::{AtomicI32, Ordering};

    static SEEN: AtomicI32 = AtomicI32::new(-1);

    unsafe extern "C" fn recorder(_attr: *mut libc::posix_spawnattr_t, disclaim: c_int) -> c_int {
        SEEN.store(disclaim, Ordering::SeqCst);
        0
    }

    fn run(f: Option<DisclaimFn>, script: &str, env: &[(String, String)], dir: &Path) -> (String, String, i32, bool) {
        let mut s = spawn(Path::new("/bin/sh"), &["-c".into(), script.into()], dir, env, f).unwrap();
        let (mut out, mut err) = (String::new(), String::new());
        s.stdout.read_to_string(&mut out).unwrap();
        s.stderr.read_to_string(&mut err).unwrap();
        let st = nix::sys::wait::waitpid(nix::unistd::Pid::from_raw(s.pid), None).unwrap();
        let code = match st {
            nix::sys::wait::WaitStatus::Exited(_, c) => c,
            _ => -1,
        };
        (out, err, code, s.disclaimed)
    }

    #[test]
    fn the_disclaim_attribute_is_applied_when_the_function_exists_and_the_child_runs_as_configured() {
        let dir = paddock_testkit::boot_volume::boot_volume_temp();
        let script = "echo out:$PWD; echo err >&2; echo var:$PITCREW_TEST_VAR; read x < /dev/stdin; echo stdin:[$x]; ps -o pgid= -p $$ | tr -d ' ' ; exit 7";
        SEEN.store(-1, Ordering::SeqCst);
        let (out, err, code, disclaimed) = run(Some(recorder), script, &[("PITCREW_TEST_VAR".into(), "yes".into())], &dir);
        assert_eq!(SEEN.load(Ordering::SeqCst), 1, "disclaim=1 was set on the attributes");
        assert!(disclaimed);
        assert_eq!(code, 7);
        assert_eq!(err.trim(), "err");
        assert!(out.contains("var:yes") && out.contains("stdin:[]"), "{out}");
        let canon = dir.canonicalize().unwrap();
        assert!(
            out.contains(&format!("out:{}", canon.display())) || out.contains(&format!("out:{}", dir.display())),
            "{out}"
        );
    }

    #[test]
    fn without_the_function_the_runner_still_starts_just_not_disclaimed() {
        let (out, _, code, disclaimed) = run(None, "echo hi", &[], &paddock_testkit::boot_volume::boot_volume_temp());
        assert_eq!((out.trim(), code, disclaimed), ("hi", 0, false));
    }

    #[test]
    fn the_real_function_exists_on_this_macos_and_works() {
        assert!(disclaim_supported(), "libSystem has responsibility_spawnattrs_setdisclaim");
        let (out, _, code, disclaimed) = run(find_disclaim(), "echo real", &[], &paddock_testkit::boot_volume::boot_volume_temp());
        assert_eq!((out.trim(), code, disclaimed), ("real", 0, true));
    }

    #[test]
    #[cfg_attr(
        unix,
        expect(
            clippy::disallowed_methods,
            reason = "ADR 0033 WP-6 (test): killpg on a recorded pid; use paddock_proc"
        )
    )]
    fn the_child_leads_its_own_process_group_and_a_bad_program_is_an_error() {
        let mut s = spawn(
            Path::new("/bin/sh"),
            &["-c".into(), "sleep 30".into()],
            &paddock_testkit::boot_volume::boot_volume_temp(),
            &[],
            find_disclaim(),
        )
        .unwrap();
        assert_eq!(
            nix::unistd::getpgid(Some(nix::unistd::Pid::from_raw(s.pid))).unwrap().as_raw(),
            s.pid
        );
        nix::sys::signal::killpg(nix::unistd::Pid::from_raw(s.pid), nix::sys::signal::Signal::SIGKILL).unwrap();
        let _ = nix::sys::wait::waitpid(nix::unistd::Pid::from_raw(s.pid), None);
        let mut sink = String::new();
        let _ = s.stdout.read_to_string(&mut sink);
        let err = spawn(
            Path::new("/nonexistent/program"),
            &[],
            &paddock_testkit::boot_volume::boot_volume_temp(),
            &[],
            None,
        )
        .err()
        .unwrap();
        assert!(err.contains("could not be started"), "{err}");
        let nul = spawn(
            Path::new("/bin/sh"),
            &["a\0b".into()],
            &paddock_testkit::boot_volume::boot_volume_temp(),
            &[],
            None,
        )
        .err()
        .unwrap();
        assert!(nul.contains("NUL"));
    }
}

//! Starting a runner process with its standard output and error piped to the service, and stopping it.
//!
//! - Every line the runner writes goes to a [`LineSink`] (the supervisor: log file, tail, classifier). Lines are cut
//!   at `MAX_LINE_LEN` and decoded lossily; nothing the runner writes can make the service allocate without limit.
//! - Graceful stop: on Unix SIGTERM to the runner's own process group; on Windows Ctrl+Break to its process group,
//!   sent by a short-lived helper (`pitcrew-service ctrl-break <pid>`) that attaches to the runner's hidden console,
//!   since a service has no console of its own (ADR 0003). The runner then stops polling and finishes a running job.
//! - Kill (only after the stop timeout and only while no job runs): the whole process tree.

use crate::process::quiet_command;
#[cfg(windows)]
use crate::process::run_with_timeout;
use pitcrew_core::logline::MAX_LINE_LEN;
use std::io::Read;
use std::path::PathBuf;
use std::process::{Child, Stdio};
use std::sync::Arc;
#[cfg(windows)]
use std::time::Duration;

/// Receives the runner's output, one line at a time (from reader threads).
pub type LineSink = Arc<dyn Fn(String) + Send + Sync>;

/// What to start.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchSpec {
    /// The program.
    pub program: PathBuf,
    /// Its arguments.
    pub args: Vec<String>,
    /// Its working directory.
    pub dir: PathBuf,
    /// Variables set (over the service's own environment) for the process: the login shell's `PATH` on macOS and
    /// Linux, then the runner's `env` table.
    pub env: Vec<(String, String)>,
}

/// A running runner process.
pub trait RunnerProcess: Send {
    /// Its process id.
    fn pid(&self) -> u32;
    /// `None` while it runs; `Some(code)` once it exited.
    fn try_wait(&mut self) -> Option<Option<i32>>;
    /// Asks it to stop gracefully.
    fn stop_gracefully(&mut self) -> Result<(), String>;
    /// Ends it and its children.
    fn kill(&mut self);
}

/// Reads `stream` line by line on a thread until it closes.
pub fn read_lines(stream: impl Read + Send + 'static, sink: LineSink) {
    let spawned = std::thread::Builder::new().name("runner-output".into()).spawn(move || {
        let mut stream = stream;
        let mut buf = [0u8; 8192];
        let mut line: Vec<u8> = Vec::with_capacity(256);
        let mut overflow = false;
        let flush = |line: &mut Vec<u8>, overflow: &mut bool| {
            if line.last() == Some(&b'\r') {
                line.pop();
            }
            sink(String::from_utf8_lossy(line).into_owned());
            line.clear();
            *overflow = false;
        };
        loop {
            let n = match stream.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => n,
            };
            for &b in &buf[..n] {
                if b == b'\n' {
                    flush(&mut line, &mut overflow);
                } else if line.len() < MAX_LINE_LEN {
                    line.push(b);
                } else {
                    overflow = true;
                }
            }
        }
        if !line.is_empty() || overflow {
            flush(&mut line, &mut overflow);
        }
    });
    // A thread that cannot be spawned only loses output; the process itself is still supervised.
    drop(spawned);
}

/// A runner started as an ordinary child of the service (service account, or the user's own session when the
/// service runs as that user: macOS, development).
pub struct ChildProcess {
    child: Started,
}

/// How the process was started: `std::process` everywhere, `posix_spawn` with the responsibility disclaim on macOS
/// (`crate::disclaim`, ADR 0020).
enum Started {
    Std(Child),
    #[cfg(target_os = "macos")]
    Spawned {
        pid: u32,
        reaped: bool,
    },
}

impl Started {
    fn id(&self) -> u32 {
        match self {
            Started::Std(c) => c.id(),
            #[cfg(target_os = "macos")]
            Started::Spawned { pid, .. } => *pid,
        }
    }

    fn try_wait(&mut self) -> std::io::Result<Option<Option<i32>>> {
        match self {
            Started::Std(c) => Ok(c.try_wait()?.map(|s| s.code())),
            #[cfg(target_os = "macos")]
            Started::Spawned { pid, reaped } => {
                use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
                if *reaped {
                    return Ok(Some(None));
                }
                match waitpid(
                    nix::unistd::Pid::from_raw(i32::try_from(*pid).unwrap_or(0)),
                    Some(WaitPidFlag::WNOHANG),
                ) {
                    Ok(WaitStatus::StillAlive) => Ok(None),
                    Ok(WaitStatus::Exited(_, code)) => {
                        *reaped = true;
                        Ok(Some(Some(code)))
                    }
                    // Killed by a signal: no exit code.
                    Ok(_) | Err(nix::errno::Errno::ECHILD) => {
                        *reaped = true;
                        Ok(Some(None))
                    }
                    Err(e) => Err(std::io::Error::from_raw_os_error(e as i32)),
                }
            }
        }
    }

    // The bare-pid kill exists only in the macOS `Spawned` arm, so the expectation is fulfilled only there.
    #[cfg_attr(
        target_os = "macos",
        expect(
            clippy::disallowed_methods,
            reason = "ADR 0033 WP-6: kills a spawned runner without the reaped guard; use paddock_proc"
        )
    )]
    fn kill(&mut self) {
        match self {
            Started::Std(c) => {
                let _ = c.kill();
            }
            #[cfg(target_os = "macos")]
            Started::Spawned { pid, .. } => {
                if let Ok(p) = i32::try_from(*pid) {
                    let _ = nix::sys::signal::kill(nix::unistd::Pid::from_raw(p), nix::sys::signal::Signal::SIGKILL);
                }
            }
        }
    }
}

/// Whether runners are started as their own responsible processes (macOS: so a job that reads `~/Documents` does not
/// make macOS ask about Pitcrew.app; always false elsewhere, where nothing like it exists).
pub fn disclaim_supported() -> bool {
    #[cfg(target_os = "macos")]
    {
        crate::disclaim::disclaim_supported()
    }
    #[cfg(not(target_os = "macos"))]
    {
        false
    }
}

/// Starts `spec` as a child with piped output, in its own process group, without a console window.
pub fn spawn_child(spec: &LaunchSpec, sink: LineSink) -> Result<ChildProcess, String> {
    #[cfg(target_os = "macos")]
    {
        let s = crate::disclaim::spawn(&spec.program, &spec.args, &spec.dir, &spec.env, crate::disclaim::find_disclaim())?;
        read_lines(s.stdout, sink.clone());
        read_lines(s.stderr, sink);
        Ok(ChildProcess {
            child: Started::Spawned {
                pid: u32::try_from(s.pid).unwrap_or(0),
                reaped: false,
            },
        })
    }
    #[cfg(not(target_os = "macos"))]
    spawn_std(spec, sink)
}

/// The portable start: `std::process`.
#[cfg_attr(target_os = "macos", allow(dead_code))]
fn spawn_std(spec: &LaunchSpec, sink: LineSink) -> Result<ChildProcess, String> {
    let mut cmd = quiet_command(&spec.program);
    cmd.args(&spec.args)
        .current_dir(&spec.dir)
        .envs(spec.env.iter().map(|(k, v)| (k, v)));
    cmd.stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(crate::process::CREATE_NO_WINDOW | crate::process::CREATE_NEW_PROCESS_GROUP);
    }
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }
    let mut child = cmd
        .spawn()
        .map_err(|e| format!("{} could not be started: {e}", spec.program.display()))?;
    if let Some(out) = child.stdout.take() {
        read_lines(out, sink.clone());
    }
    if let Some(err) = child.stderr.take() {
        read_lines(err, sink);
    }
    Ok(ChildProcess {
        child: Started::Std(child),
    })
}

impl RunnerProcess for ChildProcess {
    fn pid(&self) -> u32 {
        self.child.id()
    }

    fn try_wait(&mut self) -> Option<Option<i32>> {
        match self.child.try_wait() {
            Ok(Some(code)) => Some(code),
            Ok(None) => None,
            // The handle is unusable: treat the process as gone so supervision goes on.
            Err(_) => Some(None),
        }
    }

    fn stop_gracefully(&mut self) -> Result<(), String> {
        graceful_stop(self.child.id(), None)
    }

    fn kill(&mut self) {
        kill_tree(self.child.id());
        self.child.kill();
    }
}

static STOP_HELPER: std::sync::OnceLock<PathBuf> = std::sync::OnceLock::new();

/// Uses `exe` as the Ctrl+Break helper instead of the running executable (tests run from a test binary).
pub fn set_stop_helper(exe: PathBuf) {
    let _ = STOP_HELPER.set(exe);
}

/// Asks process `pid` (a group leader) to stop. On Windows `session` is the user session it runs in, if any.
#[cfg_attr(
    unix,
    expect(
        clippy::disallowed_methods,
        reason = "ADR 0033 WP-6: kill_tree signals a recorded pid (adopted runners); kill by ProcessId"
    )
)]
pub fn graceful_stop(pid: u32, session: Option<u32>) -> Result<(), String> {
    #[cfg(unix)]
    {
        let _ = session;
        let pid = i32::try_from(pid).map_err(|_| "process id out of range".to_string())?;
        nix::sys::signal::killpg(nix::unistd::Pid::from_raw(pid), nix::sys::signal::Signal::SIGTERM)
            .map_err(|e| format!("the stop signal could not be sent: {e}"))
    }
    #[cfg(windows)]
    {
        let exe = match STOP_HELPER.get() {
            Some(p) => p.clone(),
            None => std::env::current_exe().map_err(|e| format!("the service's own program cannot be found: {e}"))?,
        };
        let args = vec!["ctrl-break".to_string(), pid.to_string()];
        match session {
            Some(s) => crate::platform::win_session::run_in_session(s, &exe, &args, Duration::from_secs(15)),
            None => {
                let mut cmd = quiet_command(&exe);
                cmd.args(&args);
                let out = run_with_timeout(cmd, Duration::from_secs(15)).map_err(|e| e.to_string())?;
                if out.success {
                    Ok(())
                } else {
                    Err(format!("the stop request failed: {}", out.stderr.trim()))
                }
            }
        }
    }
    #[cfg(not(any(unix, windows)))]
    {
        let _ = (pid, session);
        Err("stopping runners is not supported on this platform".into())
    }
}

/// Ends `pid` and every process it started.
#[cfg_attr(
    unix,
    expect(
        clippy::disallowed_methods,
        reason = "ADR 0033 WP-6: kill_tree signals a recorded pid (adopted runners); kill by ProcessId"
    )
)]
pub fn kill_tree(pid: u32) {
    #[cfg(unix)]
    {
        if let Ok(p) = i32::try_from(pid) {
            let _ = nix::sys::signal::killpg(nix::unistd::Pid::from_raw(p), nix::sys::signal::Signal::SIGKILL);
        }
    }
    #[cfg(windows)]
    {
        let mut cmd = quiet_command(&crate::process::taskkill_exe());
        cmd.args(["/PID", &pid.to_string(), "/T", "/F"]);
        let _ = run_with_timeout(cmd, Duration::from_secs(20));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;
    use std::time::Duration;

    fn collect() -> (LineSink, Arc<Mutex<Vec<String>>>) {
        let got = Arc::new(Mutex::new(vec![]));
        let g = got.clone();
        (Arc::new(move |l| g.lock().unwrap().push(l)), got)
    }

    fn wait_for(got: &Arc<Mutex<Vec<String>>>, n: usize) -> Vec<String> {
        for _ in 0..400 {
            if got.lock().unwrap().len() >= n {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        got.lock().unwrap().clone()
    }

    #[test]
    fn splits_lines_and_bounds_them() {
        let (sink, got) = collect();
        let mut data = b"one\r\ntwo\n".to_vec();
        data.extend(vec![b'x'; MAX_LINE_LEN + 10]);
        data.extend(b"\nlast \xff");
        read_lines(std::io::Cursor::new(data), sink);
        let lines = wait_for(&got, 4);
        assert_eq!(lines[0], "one");
        assert_eq!(lines[1], "two");
        assert_eq!(lines[2].len(), MAX_LINE_LEN);
        assert_eq!(lines[3], "last \u{fffd}");
    }

    #[test]
    fn runs_a_child_and_reads_both_streams() {
        let (sink, got) = collect();
        let spec = if cfg!(windows) {
            LaunchSpec {
                program: "cmd.exe".into(),
                args: vec!["/d".into(), "/c".into(), "echo out && echo err 1>&2".into()],
                dir: paddock_testkit::boot_volume::boot_volume_temp(),
                env: vec![],
            }
        } else {
            LaunchSpec {
                program: "/bin/sh".into(),
                args: vec!["-c".into(), "echo out; echo err 1>&2".into()],
                dir: paddock_testkit::boot_volume::boot_volume_temp(),
                env: vec![],
            }
        };
        let mut p = spawn_child(&spec, sink).unwrap();
        assert!(p.pid() > 0);
        let mut code = None;
        for _ in 0..500 {
            if let Some(c) = p.try_wait() {
                code = Some(c);
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(code, Some(Some(0)));
        let mut lines = wait_for(&got, 2);
        lines.iter_mut().for_each(|l| *l = l.trim().to_string());
        lines.sort();
        assert_eq!(lines, vec!["err", "out"]);
        p.kill();
    }

    #[test]
    fn a_missing_binary_is_a_message() {
        let (sink, _) = collect();
        let err = spawn_child(
            &LaunchSpec {
                program: "/no/such/gitea-runner".into(),
                args: vec![],
                dir: paddock_testkit::boot_volume::boot_volume_temp(),
                env: vec![],
            },
            sink,
        )
        .err()
        .unwrap();
        assert!(err.contains("could not be started"), "{err}");
    }
}

//! Windows session FFI (ADR 0003): the logged-on user's session (at the console or over Remote Desktop), starting a runner in that user's session
//! with their token, and the Ctrl+Break helper. This is the crate's one module of Win32 calls; every `unsafe` block
//! says why it is sound.
//!
//! - `WTSQueryUserToken` needs LocalSystem. When the service runs as an ordinary user (development, `run` in a
//!   console) it fails with `ERROR_PRIVILEGE_NOT_HELD`; the caller then starts runners as plain children, which run
//!   in that user's session anyway.
//! - The runner's output goes through an anonymous pipe. Only the pipe's write end and a `NUL` handle are inherited
//!   (`PROC_THREAD_ATTRIBUTE_HANDLE_LIST`), so the runner never receives other handles of the service.
//! - The process is created hidden (`CREATE_NO_WINDOW`) in its own process group on `winsta0\default` with the
//!   user's environment block.
#![allow(unsafe_code)]

use crate::launch::{read_lines, LaunchSpec, LineSink, RunnerProcess};
use std::ffi::c_void;
use std::fs::File;
use std::os::windows::io::{FromRawHandle, RawHandle};
use std::time::{Duration, Instant};
use windows::core::{PCWSTR, PWSTR};
use windows::Win32::Foundation::{CloseHandle, SetHandleInformation, HANDLE, HANDLE_FLAGS, HANDLE_FLAG_INHERIT, WAIT_OBJECT_0};
use windows::Win32::Security::{DuplicateTokenEx, SecurityIdentification, TokenPrimary, SECURITY_ATTRIBUTES, TOKEN_ALL_ACCESS};
use windows::Win32::Storage::FileSystem::{
    CreateFileW, FILE_ATTRIBUTE_NORMAL, FILE_GENERIC_READ, FILE_SHARE_READ, FILE_SHARE_WRITE, OPEN_EXISTING,
};
use windows::Win32::System::Console::{AttachConsole, FreeConsole, GenerateConsoleCtrlEvent, SetConsoleCtrlHandler, CTRL_BREAK_EVENT};
use windows::Win32::System::Environment::{CreateEnvironmentBlock, DestroyEnvironmentBlock};
use windows::Win32::System::Pipes::CreatePipe;
use windows::Win32::System::RemoteDesktop::{
    WTSActive, WTSDisconnected, WTSEnumerateSessionsW, WTSFreeMemory, WTSGetActiveConsoleSessionId, WTSQueryUserToken,
    WTS_CURRENT_SERVER_HANDLE, WTS_SESSION_INFOW,
};
use windows::Win32::System::Threading::{
    CreateProcessAsUserW, DeleteProcThreadAttributeList, GetExitCodeProcess, InitializeProcThreadAttributeList, TerminateProcess,
    UpdateProcThreadAttribute, WaitForSingleObject, CREATE_NEW_PROCESS_GROUP, CREATE_NO_WINDOW, CREATE_UNICODE_ENVIRONMENT,
    EXTENDED_STARTUPINFO_PRESENT, LPPROC_THREAD_ATTRIBUTE_LIST, PROCESS_INFORMATION, PROC_THREAD_ATTRIBUTE_HANDLE_LIST,
    STARTF_USESHOWWINDOW, STARTF_USESTDHANDLES, STARTUPINFOEXW,
};

const ERROR_PRIVILEGE_NOT_HELD: i32 = 1314;
const NO_SESSION: u32 = 0xFFFF_FFFF;

/// Who is at the console.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConsoleUser {
    /// Nobody is logged on.
    Nobody,
    /// A user is logged on in this session.
    Session(u32),
    /// The service is not LocalSystem (development): it runs as the user, so plain children are in their session.
    NotSystem,
}

/// An owned Win32 handle, closed on drop.
struct Owned(HANDLE);

impl Drop for Owned {
    fn drop(&mut self) {
        if !self.0.is_invalid() {
            // SAFETY: the handle is owned by this value and closed exactly once.
            unsafe {
                let _ = CloseHandle(self.0);
            }
        }
    }
}

// SAFETY: process and token handles may be used and closed from any thread.
unsafe impl Send for Owned {}

/// The logged-on user's session (see [`pitcrew_core::session::pick_user_session`]): the console's, or a Remote
/// Desktop session when the user works over Remote Desktop and the console shows the sign-in screen.
pub fn console_user() -> ConsoleUser {
    // SAFETY: no arguments; returns a session id or 0xFFFFFFFF.
    let console = unsafe { WTSGetActiveConsoleSessionId() };
    let console = (console != NO_SESSION).then_some(console);
    let mut candidates = Vec::new();
    let mut info: *mut WTS_SESSION_INFOW = std::ptr::null_mut();
    let mut count = 0u32;
    // SAFETY: valid out pointers; the array is read below and freed with WTSFreeMemory exactly once.
    if unsafe { WTSEnumerateSessionsW(Some(WTS_CURRENT_SERVER_HANDLE), 0, 1, &mut info, &mut count) }.is_ok() && !info.is_null() {
        // SAFETY: WTSEnumerateSessionsW returned `count` entries at `info`.
        let sessions = unsafe { std::slice::from_raw_parts(info, count as usize) };
        candidates.extend(
            sessions
                .iter()
                .filter(|s| s.State == WTSActive || s.State == WTSDisconnected)
                .map(|s| (s.SessionId, s.State == WTSActive)),
        );
        // SAFETY: `info` was allocated by WTSEnumerateSessionsW.
        unsafe { WTSFreeMemory(info.cast()) };
    } else if let Some(c) = console {
        candidates.push((c, true));
    }
    let mut users = Vec::new();
    for (id, active) in candidates {
        let mut token = HANDLE::default();
        // SAFETY: `token` is a valid out pointer; the handle is closed by `Owned`.
        match unsafe { WTSQueryUserToken(id, &mut token) } {
            Ok(()) => {
                drop(Owned(token));
                users.push(pitcrew_core::session::UserSession { id, active });
            }
            Err(e) if e.code().0 & 0xFFFF == ERROR_PRIVILEGE_NOT_HELD => return ConsoleUser::NotSystem,
            // No user in this session (the sign-in screen) or it went away meanwhile.
            Err(_) => {}
        }
    }
    match pitcrew_core::session::pick_user_session(console, &users) {
        Some(s) => ConsoleUser::Session(s),
        None => ConsoleUser::Nobody,
    }
}

/// Quotes one argument for a Windows command line (the rules `CommandLineToArgvW` and the C runtime parse).
pub fn quote_arg(arg: &str) -> String {
    if !arg.is_empty() && !arg.contains([' ', '\t', '\n', '"']) {
        return arg.to_string();
    }
    let mut out = String::from("\"");
    let mut backslashes = 0;
    for c in arg.chars() {
        match c {
            '\\' => backslashes += 1,
            '"' => {
                out.push_str(&"\\".repeat(backslashes * 2 + 1));
                out.push('"');
                backslashes = 0;
            }
            _ => {
                out.push_str(&"\\".repeat(backslashes));
                out.push(c);
                backslashes = 0;
            }
        }
    }
    out.push_str(&"\\".repeat(backslashes * 2));
    out.push('"');
    out
}

fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain(std::iter::once(0)).collect()
}

fn os_err(what: &str, e: windows::core::Error) -> String {
    format!("{what} failed: {}", e.message())
}

/// A process started in a user's session.
struct Started {
    process: Owned,
    pid: u32,
    output: Option<File>,
}

/// Starts `program args` in `session` with that user's token. With `capture`, standard output and error come back
/// as one pipe.
fn start_in_session(
    session: u32,
    program: &std::path::Path,
    args: &[String],
    dir: Option<&std::path::Path>,
    capture: bool,
) -> Result<Started, String> {
    let mut user = HANDLE::default();
    // SAFETY: valid out pointer; owned below.
    unsafe { WTSQueryUserToken(session, &mut user) }.map_err(|e| os_err("Getting the logged-on user's token", e))?;
    let user = Owned(user);
    let mut primary = HANDLE::default();
    // SAFETY: `user.0` is a valid token; `primary` is a valid out pointer, owned below.
    unsafe { DuplicateTokenEx(user.0, TOKEN_ALL_ACCESS, None, SecurityIdentification, TokenPrimary, &mut primary) }
        .map_err(|e| os_err("Preparing the user's token", e))?;
    let primary = Owned(primary);

    let mut env: *mut c_void = std::ptr::null_mut();
    // SAFETY: valid out pointer and token; the block is destroyed below.
    unsafe { CreateEnvironmentBlock(&mut env, Some(primary.0), false) }.map_err(|e| os_err("Building the user's environment", e))?;
    struct Env(*mut c_void);
    impl Drop for Env {
        fn drop(&mut self) {
            // SAFETY: created by CreateEnvironmentBlock and destroyed once.
            unsafe {
                let _ = DestroyEnvironmentBlock(self.0);
            }
        }
    }
    let env = Env(env);

    let inheritable = SECURITY_ATTRIBUTES {
        nLength: std::mem::size_of::<SECURITY_ATTRIBUTES>() as u32,
        lpSecurityDescriptor: std::ptr::null_mut(),
        bInheritHandle: true.into(),
    };
    // stdin: NUL.
    let nul = wide("NUL");
    // SAFETY: `nul` is NUL-terminated and outlives the call; the handle is owned below.
    let null_in = unsafe {
        CreateFileW(
            PCWSTR(nul.as_ptr()),
            FILE_GENERIC_READ.0,
            FILE_SHARE_READ | FILE_SHARE_WRITE,
            Some(&inheritable),
            OPEN_EXISTING,
            FILE_ATTRIBUTE_NORMAL,
            None,
        )
    }
    .map_err(|e| os_err("Opening NUL", e))?;
    let null_in = Owned(null_in);

    let (read_end, write_end) = if capture {
        let mut r = HANDLE::default();
        let mut w = HANDLE::default();
        // SAFETY: valid out pointers; both handles are owned below.
        unsafe { CreatePipe(&mut r, &mut w, Some(&inheritable), 64 * 1024) }.map_err(|e| os_err("Creating the output pipe", e))?;
        let (r, w) = (Owned(r), Owned(w));
        // The service's end must not be inherited.
        // SAFETY: `r.0` is a valid handle owned by `r`.
        unsafe { SetHandleInformation(r.0, HANDLE_FLAG_INHERIT.0, HANDLE_FLAGS(0)) }.map_err(|e| os_err("Preparing the output pipe", e))?;
        (Some(r), Some(w))
    } else {
        (None, None)
    };
    let out_handle = write_end.as_ref().map_or(null_in.0, |w| w.0);
    let handles: Vec<HANDLE> = if write_end.is_some() {
        vec![null_in.0, out_handle]
    } else {
        vec![null_in.0]
    };

    // The attribute list restricting inheritance to `handles`.
    let mut size = 0usize;
    // SAFETY: the first call only computes the size (it fails with ERROR_INSUFFICIENT_BUFFER by design).
    let _ = unsafe { InitializeProcThreadAttributeList(None, 1, None, &mut size) };
    let mut list_buf = vec![0u8; size.max(64)];
    let list = LPPROC_THREAD_ATTRIBUTE_LIST(list_buf.as_mut_ptr().cast());
    // SAFETY: `list_buf` has the size the first call asked for and outlives the list's use.
    unsafe { InitializeProcThreadAttributeList(Some(list), 1, None, &mut size) }
        .map_err(|e| os_err("Preparing the process attributes", e))?;
    struct List(LPPROC_THREAD_ATTRIBUTE_LIST);
    impl Drop for List {
        fn drop(&mut self) {
            // SAFETY: initialised above and deleted once, before its buffer is freed.
            unsafe { DeleteProcThreadAttributeList(self.0) }
        }
    }
    let list_guard = List(list);
    // SAFETY: `handles` outlives CreateProcessAsUserW below; the size is that of the array.
    unsafe {
        UpdateProcThreadAttribute(
            list,
            0,
            PROC_THREAD_ATTRIBUTE_HANDLE_LIST as usize,
            Some(handles.as_ptr().cast()),
            std::mem::size_of_val(handles.as_slice()),
            None,
            None,
        )
    }
    .map_err(|e| os_err("Limiting the inherited handles", e))?;

    let mut desktop = wide("winsta0\\default");
    let mut si = STARTUPINFOEXW::default();
    si.StartupInfo.cb = std::mem::size_of::<STARTUPINFOEXW>() as u32;
    si.StartupInfo.lpDesktop = PWSTR(desktop.as_mut_ptr());
    si.StartupInfo.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.StartupInfo.wShowWindow = 0; // SW_HIDE
    si.StartupInfo.hStdInput = null_in.0;
    si.StartupInfo.hStdOutput = out_handle;
    si.StartupInfo.hStdError = out_handle;
    si.lpAttributeList = list;

    let app = wide(&program.display().to_string());
    let mut line: Vec<u16> = wide(
        &std::iter::once(quote_arg(&program.display().to_string()))
            .chain(args.iter().map(|a| quote_arg(a)))
            .collect::<Vec<_>>()
            .join(" "),
    );
    let cwd = dir.map(|d| wide(&d.display().to_string()));
    let mut pi = PROCESS_INFORMATION::default();
    // SAFETY: every pointer refers to a buffer that lives until the call returns; `si` is a STARTUPINFOEXW with
    // EXTENDED_STARTUPINFO_PRESENT; the command line buffer is mutable as the API requires.
    unsafe {
        CreateProcessAsUserW(
            Some(primary.0),
            PCWSTR(app.as_ptr()),
            Some(PWSTR(line.as_mut_ptr())),
            None,
            None,
            true,
            CREATE_UNICODE_ENVIRONMENT | CREATE_NO_WINDOW | CREATE_NEW_PROCESS_GROUP | EXTENDED_STARTUPINFO_PRESENT,
            Some(env.0),
            cwd.as_ref().map_or(PCWSTR::null(), |c| PCWSTR(c.as_ptr())),
            &si.StartupInfo,
            &mut pi,
        )
    }
    .map_err(|e| os_err(&format!("Starting {} in the user's session", program.display()), e))?;
    drop(list_guard);
    drop(Owned(pi.hThread));
    // Our copy of the write end must close, or the reader never sees the end of the output.
    drop(write_end);
    let output = read_end.map(|r| {
        let raw = r.0 .0 as RawHandle;
        std::mem::forget(r);
        // SAFETY: the read end is a valid pipe handle whose ownership moves into the File.
        unsafe { File::from_raw_handle(raw) }
    });
    Ok(Started {
        process: Owned(pi.hProcess),
        pid: pi.dwProcessId,
        output,
    })
}

/// A runner running in a user's session.
pub struct SessionProcess {
    started: Started,
    session: u32,
    exited: Option<Option<i32>>,
}

/// Starts a runner in `session`, its output going to `sink`.
pub fn spawn_in_session(session: u32, spec: &LaunchSpec, sink: LineSink) -> Result<SessionProcess, String> {
    let mut started = start_in_session(session, &spec.program, &spec.args, Some(&spec.dir), true)?;
    if let Some(out) = started.output.take() {
        read_lines(out, sink);
    }
    Ok(SessionProcess {
        started,
        session,
        exited: None,
    })
}

fn exit_code(h: HANDLE) -> Option<Option<i32>> {
    // SAFETY: `h` is a valid process handle owned by the caller.
    unsafe {
        if WaitForSingleObject(h, 0) != WAIT_OBJECT_0 {
            return None;
        }
        let mut code = 0u32;
        Some(GetExitCodeProcess(h, &mut code).ok().map(|_| code as i32))
    }
}

impl RunnerProcess for SessionProcess {
    fn pid(&self) -> u32 {
        self.started.pid
    }

    fn try_wait(&mut self) -> Option<Option<i32>> {
        if self.exited.is_none() {
            self.exited = exit_code(self.started.process.0);
        }
        self.exited
    }

    fn stop_gracefully(&mut self) -> Result<(), String> {
        crate::launch::graceful_stop(self.started.pid, Some(self.session))
    }

    fn kill(&mut self) {
        crate::launch::kill_tree(self.started.pid);
        // SAFETY: valid process handle; failure (already gone) is ignored.
        unsafe {
            // conformance: pid-kill — a process handle we own (the process object cannot be handed on while it is open)
            let _ = TerminateProcess(self.started.process.0, 1);
        }
    }
}

/// Runs a short helper in `session` and waits for it (at most `timeout`).
pub fn run_in_session(session: u32, program: &std::path::Path, args: &[String], timeout: Duration) -> Result<(), String> {
    let started = start_in_session(session, program, args, None, false)?;
    let deadline = Instant::now() + timeout;
    loop {
        match exit_code(started.process.0) {
            Some(Some(0)) => return Ok(()),
            Some(code) => return Err(format!("the stop helper failed (exit code {code:?})")),
            None if Instant::now() >= deadline => {
                // SAFETY: valid process handle.
                unsafe {
                    // conformance: pid-kill — a process handle we own (the process object cannot be handed on while it is open)
                    let _ = TerminateProcess(started.process.0, 1);
                }
                return Err("the stop helper did not finish in time".into());
            }
            None => std::thread::sleep(Duration::from_millis(50)),
        }
    }
}

/// The helper's work (`pitcrew-service ctrl-break <pid>`): attach to the runner's console and send Ctrl+Break to
/// its process group, ignoring the event ourselves.
pub fn send_ctrl_break(pid: u32) -> Result<(), String> {
    // SAFETY: plain console calls on this process; the handler routine is NULL with "ignore" = TRUE.
    unsafe {
        let _ = FreeConsole();
        AttachConsole(pid).map_err(|e| os_err("Attaching to the runner's console", e))?;
        SetConsoleCtrlHandler(None, true).map_err(|e| os_err("Ignoring Ctrl+Break in the helper", e))?;
        let sent = GenerateConsoleCtrlEvent(CTRL_BREAK_EVENT, pid);
        let _ = FreeConsole();
        sent.map_err(|e| os_err("Sending Ctrl+Break", e))
    }
}

