//! What the service looks up about processes and the machine: whether a runner has job processes, whether a runner
//! binary already runs outside Pitcrew, the machine's CPU, memory and free disk, and the service's own cost.
//!
//! One `sysinfo` snapshot is refreshed per supervision tick (every few seconds), not per question.

use crate::process_watch::Seen;
use pitcrew_core::jobs::is_job_process;
use pitcrew_core::metrics::{permille, MachineSample};
use pitcrew_core::process_track::ProcessMeta;
use pitcrew_core::time::Timestamp;
use pitcrew_core::usage::{ProcessInfo, Usage, UsageTracker};
use std::path::Path;

/// Most processes of one runner described with names and command lines per tick (the rest still count in the usage).
pub const MAX_DESCRIBED: usize = 512;
use pitcrew_core::disk_guard::SpaceCache;
use sysinfo::{Disks, Pid, ProcessRefreshKind, ProcessesToUpdate, RefreshKind, System, UpdateKind};

/// The process and machine snapshot.
pub struct Probe {
    /// `None` when sysinfo could not start (logged once): the process table is then empty and the machine reads zero.
    sys: Option<System>,
    /// `None` when the volume list could not be read (logged): free space is then unknown.
    disks: Option<Disks>,
    space: SpaceCache,
    cpus: usize,
}

impl Default for Probe {
    fn default() -> Self {
        Self::new()
    }
}

impl Probe {
    /// A probe with a first snapshot.
    pub fn new() -> Self {
        let sys = System::new_with_specifics(RefreshKind::nothing())
            .inspect_err(|why| {
                eprintln!("pitcrew-service: warning: the OS process table is unavailable (sysinfo): {why}; no process is seen")
            })
            .ok();
        let disks = Disks::new_with_refreshed_list()
            .inspect_err(|why| {
                eprintln!("pitcrew-service: warning: the volume list is unavailable (sysinfo): {why}; free space is unknown")
            })
            .ok();
        let mut p = Probe {
            sys,
            disks,
            space: SpaceCache::default(),
            cpus: std::thread::available_parallelism().map_or(1, std::num::NonZero::get),
        };
        p.refresh_processes();
        p
    }

    /// Refreshes the process list (names, parents, executables, CPU).
    pub fn refresh_processes(&mut self) {
        let Some(sys) = self.sys.as_mut() else { return };
        sys.refresh_processes_specifics(
            ProcessesToUpdate::All,
            true,
            ProcessRefreshKind::nothing()
                .with_exe(UpdateKind::OnlyIfNotSet)
                .with_cpu()
                .with_memory(),
        );
    }

    /// The processes of the last refresh, without threads: on Linux sysinfo lists every thread (task) as an entry of
    /// its own, with the process's executable and parent, so a thread id could be taken for a process id (and
    /// signalled, adopted or counted twice).
    fn processes(&self) -> impl Iterator<Item = (&Pid, &sysinfo::Process)> {
        // Threads are not processes (Linux lists them), and a zombie has already exited: it only waits for its parent
        // to reap it (in a container without an init it may never be), so it uses nothing and must never be stopped
        // or counted again.
        self.sys
            .iter()
            .flat_map(|sys| sys.processes().iter())
            .filter(|(_, p)| p.thread_kind().is_none() && p.status() != sysinfo::ProcessStatus::Zombie)
    }

    /// Logical cores of the machine (the denominator of every CPU share).
    pub fn cpus(&self) -> usize {
        self.cpus
    }

    /// The process table as of the last refresh: ids, parents, process groups, CPU time and resident memory.
    pub fn process_table(&self) -> Vec<ProcessInfo> {
        self.processes()
            .map(|(pid, p)| ProcessInfo {
                pid: pid.as_u32(),
                ppid: p.parent().map(Pid::as_u32),
                pgid: process_group(pid.as_u32()),
                cpu_time_ms: p.accumulated_cpu_time(),
                rss_bytes: p.memory(),
            })
            .collect()
    }

    /// Names, executables, command lines and start times of the runner's `members` (the runner itself first), at most
    /// [`MAX_DESCRIBED`]. Command lines are read once per process (`OnlyIfNotSet`), for these processes only.
    pub fn process_metas(&mut self, runner_pid: u32, members: &[ProcessInfo], usage: &UsageTracker) -> Vec<ProcessMeta> {
        let mut ordered: Vec<&ProcessInfo> = members.iter().collect();
        ordered.sort_by_key(|p| (p.pid != runner_pid, p.pid));
        ordered.truncate(MAX_DESCRIBED);
        let pids: Vec<Pid> = ordered.iter().map(|p| Pid::from_u32(p.pid)).collect();
        let Some(sys) = self.sys.as_mut() else {
            return Vec::new();
        };
        sys.refresh_processes_specifics(
            ProcessesToUpdate::Some(&pids),
            false,
            ProcessRefreshKind::nothing()
                .with_exe(UpdateKind::OnlyIfNotSet)
                .with_cmd(UpdateKind::OnlyIfNotSet),
        );
        ordered
            .into_iter()
            .map(|info| {
                let p = sys.process(Pid::from_u32(info.pid));
                // The exact start the OS gives for this pid now (rule 53): the identity a later stop compares again before it
                // signals. sysinfo's whole seconds are not used for identity.
                let started = paddock_proc::ProcessId::of(info.pid).map(|id| id.started().as_micros());
                ProcessMeta {
                    pid: info.pid,
                    ppid: info.ppid,
                    name: p.map_or_else(String::new, |p| p.name().to_string_lossy().into_owned()),
                    exe: p.and_then(|p| p.exe()).map(|e| e.display().to_string()),
                    command: p.map_or_else(String::new, |p| {
                        p.cmd().iter().map(|a| a.to_string_lossy()).collect::<Vec<_>>().join(" ")
                    }),
                    started_ms: started.map(|us| us / 1000),
                    started_micros: started,
                    cpu_permille: usage.share_of(info.pid),
                    mem_bytes: info.rss_bytes,
                }
            })
            .collect()
    }

    /// What the process `id` is now: [`Seen::Same`] only when its pid still belongs to it (the pid's holder started at the
    /// held time), [`Seen::Gone`] when nothing runs under it, a zombie, or the pid was handed on, and [`Seen::Unverified`]
    /// when the OS could not say (the process table or the holder's start time could not be read). Unknown counts as alive:
    /// a process is never ended because a read failed.
    pub fn seen(&self, id: paddock_proc::ProcessId) -> Seen {
        seen_from(id.presence())
    }

    /// Whether `pid` has child processes that belong to a job (its console host does not).
    // ADR 0033 WP-6: children found by parent pid without start times; use paddock_proc::descendants
    pub fn has_job_children(&self, pid: u32) -> bool {
        let parent = Pid::from_u32(pid);
        self.processes()
            .any(|(_, p)| p.parent() == Some(parent) && is_job_process(&p.name().to_string_lossy()))
    }

    /// A running process (other than `except`) whose executable is `exe`.
    pub fn running_binary(&self, exe: &Path, except: Option<u32>) -> Option<u32> {
        let want = normalise(exe);
        self.processes()
            .filter(|(pid, _)| Some(pid.as_u32()) != except)
            .find(|(_, p)| p.exe().is_some_and(|e| normalise(e) == want))
            .map(|(pid, _)| pid.as_u32())
    }

    /// A machine sample (without the runners' share, which the supervisor adds); `disk_of` names a folder on the disk to report.
    pub fn machine(&mut self, now: Timestamp, disk_of: &Path) -> MachineSample {
        let (cpu, mem_used_bytes, mem_total_bytes) = match self.sys.as_mut() {
            Some(sys) => {
                sys.refresh_cpu_usage();
                sys.refresh_memory();
                (permille(sys.global_cpu_usage() / 100.0), sys.used_memory(), sys.total_memory())
            }
            None => (permille(0.0), 0, 0),
        };
        let (free, total) = self.disk_space(disk_of, now).unwrap_or((0, 0));
        MachineSample {
            at: now,
            cpu_permille: cpu,
            cpu_peak_permille: cpu,
            mem_used_bytes,
            mem_total_bytes,
            disk_free_bytes: free,
            disk_total_bytes: total,
            runners: Usage::default(),
        }
    }

    /// Free and total bytes of the disk holding `path`. The OS is asked at most once a minute per disk
    /// ([`SpaceCache`]); in between the last reading is returned.
    pub fn disk_space(&mut self, path: &Path, now: Timestamp) -> Option<(u64, u64)> {
        let disks = self.disks.as_mut()?;
        let key = path.to_string_lossy().to_string();
        self.space.get(&key, now, || {
            disks.refresh(true);
            let target = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
            let target = normalise(&target);
            disks
                .iter()
                .filter(|d| target.starts_with(&normalise(d.mount_point())))
                .max_by_key(|d| d.mount_point().as_os_str().len())
                .map(|d| (d.available_space(), d.total_space()))
        })
    }

    /// The service's own CPU (per mille of the whole machine) and memory.
    pub fn own_usage(&self) -> (u32, u64) {
        let me = Pid::from_u32(std::process::id());
        let Some(sys) = self.sys.as_ref() else {
            return (0, 0);
        };
        let cpus = sys.cpus().len().max(1) as f32;
        sys.process(me)
            .map(|p| (permille(p.cpu_usage() / 100.0 / cpus), p.memory()))
            .unwrap_or((0, 0))
    }
}

/// The process group of `pid` (Unix); `None` when it is gone or the platform has no groups.
#[cfg(unix)]
fn process_group(pid: u32) -> Option<u32> {
    let pid = i32::try_from(pid).ok()?;
    nix::unistd::getpgid(Some(nix::unistd::Pid::from_raw(pid)))
        .ok()
        .and_then(|g| u32::try_from(g.as_raw()).ok())
}

/// Windows has no process groups; the tree is the parent-pid tree there.
#[cfg(not(unix))]
fn process_group(_pid: u32) -> Option<u32> {
    None
}

/// A path for comparison: `\\?\` dropped, separators unified, case-insensitive on Windows.
fn normalise(p: &Path) -> String {
    let s = p.display().to_string();
    let s = s.strip_prefix(r"\\?\").unwrap_or(&s).replace('\\', "/");
    if cfg!(windows) {
        s.to_lowercase()
    } else {
        s
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[allow(
        clippy::disallowed_methods,
        reason = "a test builds its scratch path from the OS temp folder and removes it"
    )]
    fn sees_its_own_process_and_the_machine() {
        let mut p = Probe::new();
        // Other processes may run this test binary at the same time (nextest runs every test in its own process), so
        // the binary is found running, and the excluded process is never the answer.
        let exe = std::env::current_exe().unwrap();
        assert!(p.running_binary(&exe, None).is_some());
        assert_ne!(p.running_binary(&exe, Some(std::process::id())), Some(std::process::id()));
        assert!(!p.has_job_children(u32::MAX));
        let m = p.machine(Timestamp(1), &std::env::temp_dir());
        assert!(m.mem_total_bytes > 0);
        assert!(m.disk_total_bytes > 0, "{m:?}");
        let (_, mem) = p.own_usage();
        assert!(mem > 0);
        assert!(p.cpus() >= 1);
        let me = std::process::id();
        let mine = p
            .process_table()
            .into_iter()
            .find(|r| r.pid == me)
            .expect("this process is in the table");
        assert!(mine.rss_bytes > 0 && mine.ppid.is_some());
        if cfg!(unix) {
            assert!(mine.pgid.is_some());
        }
    }

    #[test]
    fn paths_compare_loosely() {
        assert_eq!(normalise(Path::new(r"\\?\C:\x\y")), normalise(Path::new("C:/x/y")));
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn threads_are_not_processes() {
        // Regression: on Linux sysinfo lists each thread as an entry with the same exe; `running_binary` returned a
        // thread id and the usage tree counted a process once per thread.
        let (stop, rx) = std::sync::mpsc::channel::<()>();
        let rx = std::sync::Arc::new(std::sync::Mutex::new(rx));
        let threads: Vec<_> = (0..4)
            .map(|_| {
                let rx = rx.clone();
                std::thread::spawn(move || {
                    let _ = rx.lock().map(|r| r.recv());
                })
            })
            .collect();
        std::thread::sleep(std::time::Duration::from_millis(100));
        let me = std::process::id();
        let tids: Vec<u32> = std::fs::read_dir("/proc/self/task")
            .unwrap()
            .filter_map(|e| e.ok()?.file_name().to_str()?.parse().ok())
            .filter(|t| *t != me)
            .collect();
        assert!(tids.len() >= 4, "{tids:?}");
        let probe = Probe::new();
        let table = probe.process_table();
        assert_eq!(table.iter().filter(|p| p.pid == me).count(), 1);
        assert!(table.iter().all(|p| !tids.contains(&p.pid)), "a thread is listed as a process");
        let exe = std::env::current_exe().unwrap();
        let found = probe.running_binary(&exe, None).unwrap();
        assert!(!tids.contains(&found), "{found} is a thread id");
        drop(stop);
        for t in threads {
            let _ = t.join();
        }
    }
}

/// What the OS's look at a held identity says ([`paddock_proc::ProcessId::presence`]): the pid's holder is compared with
/// the held start time exactly, so no tolerance of any size is involved.
fn seen_from(look: paddock_proc::Presence) -> Seen {
    match look {
        paddock_proc::Presence::Running => Seen::Same,
        paddock_proc::Presence::Gone => Seen::Gone,
        paddock_proc::Presence::Unknown => Seen::Unverified,
    }
}

#[cfg(test)]
mod seen_tests {
    use super::*;
    use paddock_proc::{Presence, ProcessId, StartTime};

    #[test]
    fn the_looks_map_to_what_the_service_does_next() {
        assert_eq!(seen_from(Presence::Running), Seen::Same);
        assert_eq!(seen_from(Presence::Gone), Seen::Gone);
        assert_eq!(
            seen_from(Presence::Unknown),
            Seen::Unverified,
            "a failed read is never taken for gone"
        );
    }

    /// The held identity is compared exactly: this test process is the same process, the same pid with another start is a
    /// recycled pid, and a pid nobody holds is gone.
    #[test]
    fn a_held_identity_is_the_same_process_only_by_its_exact_start() {
        let me = ProcessId::of(std::process::id()).unwrap();
        assert_eq!(seen_from(me.presence()), Seen::Same);
        let micros = me.started().as_micros();
        for off in [1_000_000, 1] {
            let other = ProcessId::new(me.pid(), StartTime::from_micros(micros + off));
            assert_eq!(seen_from(other.presence()), Seen::Gone, "{off} µs off is another process");
        }
        assert_eq!(
            seen_from(ProcessId::new(u32::MAX, StartTime::from_micros(micros)).presence()),
            Seen::Gone
        );
    }
}

//! Child processes: every external program runs without a console window and with a timeout.

use crate::error::Error;
use std::io::Read;
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

/// Most output kept from a short-lived tool (e.g. `gitea-runner --version`).
pub const MAX_TOOL_OUTPUT: usize = 64 * 1024;

/// Windows process creation flag: no console window.
pub use paddock_proc::CREATE_NO_WINDOW;
/// Windows process creation flag: a new process group (so Ctrl+Break reaches the runner only).
pub const CREATE_NEW_PROCESS_GROUP: u32 = 0x0000_0200;

/// A command that opens no console window on Windows ([`paddock_proc::command`], the canonical constructor).
pub fn quiet_command(program: &Path) -> Command {
    paddock_proc::command(program)
}

/// The finished tool's output (bounded) and whether it succeeded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolOutput {
    /// Exit status was success.
    pub success: bool,
    /// Its exit code, when it had one.
    pub code: Option<i32>,
    /// Standard output, at most [`MAX_TOOL_OUTPUT`] bytes, lossily decoded.
    pub stdout: String,
    /// Standard error, at most [`MAX_TOOL_OUTPUT`] bytes, lossily decoded.
    pub stderr: String,
}

type Drain = Option<std::thread::JoinHandle<Vec<u8>>>;

fn drain(stream: Option<impl Read + Send + 'static>) -> Drain {
    stream.map(|out| {
        std::thread::spawn(move || {
            let mut buf = Vec::new();
            let mut limited = out.take(MAX_TOOL_OUTPUT as u64);
            let _ = limited.read_to_end(&mut buf);
            // Keep reading (and dropping) so the child never blocks on a full pipe.
            let mut rest = limited.into_inner();
            let _ = std::io::copy(&mut rest, &mut std::io::sink());
            buf
        })
    })
}

/// Runs `cmd` to completion, stopping it after `timeout`, together with every program it started (a login shell's
/// `~/.zshrc`, `cmd /c`). Error messages name the program only, never its arguments (a registration token is an
/// argument).
pub fn run_with_timeout(cmd: Command, timeout: Duration) -> Result<ToolOutput, Error> {
    let started = Instant::now();
    run_until(cmd, timeout.as_secs(), |_| started.elapsed() >= timeout)
}

/// Runs `cmd` to completion unless `give_up(pid)` says to stop first; then the tool and every program it started are
/// ended and `TimedOut` (naming `secs`) is returned. The tool runs in a session of its own on Unix (it leads its process
/// group and has no controlling terminal, so an interactive login shell started from a terminal is not stopped by
/// `SIGTTIN`) and in a kill-on-close job object on Windows (which also holds helpers that left its tree).
///
/// After a tool finishes normally, helpers it left running differ by platform: on Windows closing the job ends them;
/// on Unix they survive (only a timeout signals the group), as they would when the tool ran from a shell.
pub(crate) fn run_until(mut cmd: Command, secs: u64, mut give_up: impl FnMut(u32) -> bool) -> Result<ToolOutput, Error> {
    let program = Path::new(cmd.get_program())
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    cmd.stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    tree::own_session(&mut cmd);
    let mut child = cmd.spawn().map_err(|e| Error::Os {
        what: "starting a program",
        reason: format!("{program}: {e}"),
    })?;
    let tree = tree::Tree::of(&child);
    let out = drain(child.stdout.take());
    let err = drain(child.stderr.take());
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) if give_up(child.id()) => {
                tree.end(&mut child);
                return Err(Error::TimedOut { program, secs });
            }
            Ok(None) => std::thread::sleep(Duration::from_millis(25)),
            Err(e) => {
                tree.end(&mut child);
                return Err(Error::Os {
                    what: "waiting for a program",
                    reason: e.to_string(),
                });
            }
        }
    };
    // On Windows, closing the job ends helpers the tool left running; their pipes then close.
    tree.close();
    let text = |h: Drain| String::from_utf8_lossy(&h.and_then(|h| h.join().ok()).unwrap_or_default()).into_owned();
    Ok(ToolOutput {
        success: status.success(),
        code: status.code(),
        stdout: text(out),
        stderr: text(err),
    })
}

/// `taskkill.exe` in the system folder, by full path (never whatever `taskkill` the `PATH` finds first).
#[cfg(windows)]
pub fn taskkill_exe() -> std::path::PathBuf {
    let root = std::env::var_os("SystemRoot").unwrap_or_else(|| "C:\\Windows".into());
    std::path::PathBuf::from(root).join("System32").join("taskkill.exe")
}

/// A tool's process tree: its own session on Unix, a kill-on-close job object on Windows.
mod tree {
    #![allow(unsafe_code)]
    use std::process::{Child, Command};

    /// Makes the tool start a session of its own (`setsid`): it leads a new process group, so `killpg` reaches every
    /// program it starts, and it has no controlling terminal to be stopped by.
    #[cfg(unix)]
    pub fn own_session(cmd: &mut Command) {
        use std::os::unix::process::CommandExt;
        // SAFETY: the closure runs between fork and exec and only calls setsid, which is async-signal-safe and touches no
        // memory of the parent.
        unsafe {
            #[expect(
                clippy::disallowed_methods,
                reason = "setsid is the child's own call; it cannot be made from the parent"
            )]
            cmd.pre_exec(|| nix::unistd::setsid().map(|_| ()).map_err(std::io::Error::from));
        }
    }

    #[cfg(not(unix))]
    pub fn own_session(_cmd: &mut Command) {}

    /// What ends the tree.
    pub struct Tree {
        #[cfg(windows)]
        job: Option<windows::Win32::Foundation::HANDLE>,
    }

    impl Tree {
        /// The tree of a just-started tool. On Windows the tool joins a kill-on-close job (a program it starts later
        /// joins too); when that fails (an old Windows, a job that forbids it) `taskkill /T` is the fallback. The tool
        /// joins the job only after `spawn` returned: a program it started in that moment (before its own start-up
        /// code ran, so in practice never) would be outside the job, which is why `end` also runs `taskkill /T`.
        #[cfg(windows)]
        pub fn of(child: &Child) -> Tree {
            Tree { job: job_for(child) }
        }

        #[cfg(not(windows))]
        pub fn of(_child: &Child) -> Tree {
            Tree {}
        }

        /// The tool finished: on Windows the job is closed, which ends any helper it left running.
        pub fn close(self) {}

        /// Ends the tool and everything it started, and reaps the tool.
        #[cfg_attr(
            unix,
            expect(
                clippy::disallowed_methods,
                reason = "ADR 0033 WP-6: killpg before reaping; move to paddock_proc::Supervised"
            )
        )]
        pub fn end(&self, child: &mut Child) {
            #[cfg(unix)]
            {
                // The tool leads its own process group (`own_session`).
                if let Ok(pid) = i32::try_from(child.id()) {
                    let _ = nix::sys::signal::killpg(nix::unistd::Pid::from_raw(pid), nix::sys::signal::Signal::SIGKILL);
                }
            }
            #[cfg(windows)]
            match self.job {
                Some(job) => {
                    // SAFETY: a job handle this value owns and has not closed.
                    unsafe {
                        // conformance: pid-kill — a job handle we own: no pid is looked up
                        let _ = windows::Win32::System::JobObjects::TerminateJobObject(job, 1);
                    }
                    // Anything that escaped the job (see `of`) and is still in the tool's tree.
                    taskkill_tree(child.id());
                }
                None => taskkill_tree(child.id()),
            }
            let _ = child.kill();
            let _ = child.wait();
        }
    }

    #[cfg(windows)]
    impl Drop for Tree {
        fn drop(&mut self) {
            if let Some(job) = self.job.take() {
                // SAFETY: the handle is owned here and closed once; closing it ends what is left in the job.
                unsafe {
                    let _ = windows::Win32::Foundation::CloseHandle(job);
                }
            }
        }
    }

    /// A new kill-on-close job holding `child`, or `None` when Windows refuses.
    #[cfg(windows)]
    fn job_for(child: &Child) -> Option<windows::Win32::Foundation::HANDLE> {
        use std::os::windows::io::AsRawHandle;
        use windows::Win32::Foundation::{CloseHandle, HANDLE};
        use windows::Win32::System::JobObjects::{
            AssignProcessToJobObject, CreateJobObjectW, JobObjectExtendedLimitInformation, SetInformationJobObject,
            JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
        };
        // SAFETY: no attributes and no name; the handle is closed below on failure or owned by the `Tree`.
        let job = unsafe { CreateJobObjectW(None, windows::core::PCWSTR::null()) }.ok()?;
        let mut info = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        // SAFETY: `info` is a valid structure of the size passed, for the class passed; both handles are valid while
        // `child` lives.
        let ok = unsafe {
            SetInformationJobObject(
                job,
                JobObjectExtendedLimitInformation,
                (&raw const info).cast(),
                u32::try_from(std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>()).unwrap_or(0),
            )
            .and_then(|()| AssignProcessToJobObject(job, HANDLE(child.as_raw_handle())))
        };
        if ok.is_err() {
            // SAFETY: the job was created above and is not used again.
            unsafe {
                let _ = CloseHandle(job);
            }
            return None;
        }
        Some(job)
    }

    /// `taskkill /PID n /T /F`, run directly (not through `run_with_timeout`, which would recurse) and waited for a few
    /// seconds at most.
    #[cfg(windows)]
    fn taskkill_tree(pid: u32) {
        use std::process::Stdio;
        use std::time::{Duration, Instant};
        let mut kill = super::quiet_command(&super::taskkill_exe());
        kill.args(["/PID", &pid.to_string(), "/T", "/F"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        if let Ok(mut k) = kill.spawn() {
            let deadline = Instant::now() + Duration::from_secs(10);
            while matches!(k.try_wait(), Ok(None)) && Instant::now() < deadline {
                std::thread::sleep(Duration::from_millis(25));
            }
            let _ = k.kill();
            let _ = k.wait();
        }
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;

    pub(crate) fn shell(script: &str) -> Command {
        if cfg!(windows) {
            let mut c = quiet_command(Path::new("cmd.exe"));
            c.args(["/d", "/c", script]);
            c
        } else {
            let mut c = quiet_command(Path::new("/bin/sh"));
            c.args(["-c", script]);
            c
        }
    }

    #[test]
    fn captures_output_of_a_finished_tool() {
        let out = run_with_timeout(shell("echo gitea-runner version v5.2.0 && echo oops 1>&2"), Duration::from_secs(20)).unwrap();
        assert!(out.success);
        assert_eq!(out.code, Some(0));
        assert!(out.stdout.contains("v5.2.0"), "{out:?}");
        assert!(out.stderr.contains("oops"), "{out:?}");
    }

    #[test]
    fn stops_a_tool_that_hangs() {
        let hang = if cfg!(windows) { "ping -n 30 127.0.0.1 >nul" } else { "sleep 30" };
        let started = Instant::now();
        let err = run_with_timeout(shell(hang), Duration::from_millis(500)).unwrap_err();
        assert!(matches!(err, Error::TimedOut { .. }), "{err}");
        assert!(started.elapsed() < Duration::from_secs(15));
    }

    /// A tool that started programs of its own (a login shell running `~/.zshrc`, `cmd /c`) is stopped with all of
    /// them: killing only the tool left its children running, holding its output pipes open. The test gives up on the
    /// tool once its tree is complete (no time budget), then waits until every member is gone.
    #[test]
    fn a_tool_that_hangs_is_stopped_with_the_programs_it_started() {
        // Unix: `; wait` keeps the shell from replacing itself with `sleep`, so the tool has a child of its own.
        // Windows: `start /b` runs a second ping beside the first, both children of `cmd`.
        let script = if cfg!(windows) {
            "start /b ping -n 300 127.0.0.1 >nul & ping -n 300 127.0.0.1 >nul"
        } else {
            "sleep 300 & wait"
        };
        // The shell and its sleep; on Windows `cmd` and its two pings.
        let complete = if cfg!(windows) { 3 } else { 2 };
        let guard = Instant::now() + HANG_GUARD;
        let mut members = vec![];
        let err = run_until(shell(script), 0, |pid| {
            members = tree_members(pid);
            members.len() >= complete || Instant::now() > guard
        })
        .unwrap_err();
        assert!(matches!(err, Error::TimedOut { .. }), "{err}");
        assert!(members.len() >= complete, "the tool started its programs: {members:?}");
        let gone = eventually_gone(&members);
        if !gone {
            // Only processes that are still the tool's own: a pid reused by an unrelated process is never touched.
            for m in &members {
                if running(*m) {
                    kill_pid(m.pid);
                }
            }
        }
        assert!(gone, "the tool's tree outlived it: {members:?}");
    }

    /// Ends a hung test, never a product interval.
    const HANG_GUARD: Duration = Duration::from_secs(60);

    /// One process of the tool's tree, with what identifies it beyond its pid: the tool's process group on Unix, its
    /// start time on Windows.
    #[derive(Debug, Clone, Copy)]
    struct Member {
        pid: u32,
        mark: u64,
    }

    /// The tool `pid` and its programs: its process group on Unix, its descendants on Windows.
    #[cfg(unix)]
    fn tree_members(pid: u32) -> Vec<Member> {
        let out = quiet_command(Path::new("pgrep")).args(["-g", &pid.to_string()]).output().unwrap();
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .filter_map(|l| l.trim().parse().ok())
            .map(|p| Member {
                pid: p,
                mark: u64::from(pid),
            })
            .collect()
    }

    #[cfg(windows)]
    // ADR 0033 WP-6 (test): a tree by parent pids without start times; use paddock_proc::descendants
    fn tree_members(pid: u32) -> Vec<Member> {
        use sysinfo::{Pid, ProcessRefreshKind, ProcessesToUpdate, System};
        let mut sys = System::new().expect("a System");
        sys.refresh_processes_specifics(ProcessesToUpdate::All, true, ProcessRefreshKind::nothing());
        let mut tree = vec![Pid::from_u32(pid)];
        loop {
            let before = tree.len();
            for (p, proc_) in sys.processes() {
                if !tree.contains(p) && proc_.parent().is_some_and(|pp| tree.contains(&pp)) {
                    tree.push(*p);
                }
            }
            if tree.len() == before {
                break;
            }
        }
        // `cmd` gets a console host of its own, which is not one of the tool's programs.
        tree.into_iter()
            .filter_map(|p| sys.process(p).map(|q| (p, q)))
            .filter(|(_, q)| !q.name().to_string_lossy().eq_ignore_ascii_case("conhost.exe"))
            .map(|(p, q)| Member {
                pid: p.as_u32(),
                mark: q.start_time(),
            })
            .collect()
    }

    /// Whether every one of `members` is gone (a zombie counts as gone), waiting on that condition up to the hang guard.
    fn eventually_gone(members: &[Member]) -> bool {
        let guard = Instant::now() + HANG_GUARD;
        loop {
            if members.iter().all(|m| !running(*m)) {
                return true;
            }
            if Instant::now() > guard {
                return false;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
    }

    /// Whether the member still runs and is still the tool's (same process group).
    #[cfg(unix)]
    fn running(m: Member) -> bool {
        let out = quiet_command(Path::new("ps"))
            .args(["-o", "stat=,pgid=", "-p", &m.pid.to_string()])
            .output()
            .unwrap();
        let text = String::from_utf8_lossy(&out.stdout);
        let mut fields = text.split_whitespace();
        match (fields.next(), fields.next().and_then(|g| g.parse::<u64>().ok())) {
            (Some(stat), Some(pgid)) => !stat.starts_with('Z') && pgid == m.mark,
            _ => false,
        }
    }

    /// Whether the member still runs and is still the same process (same start time).
    #[cfg(windows)]
    fn running(m: Member) -> bool {
        use sysinfo::{Pid, ProcessRefreshKind, ProcessesToUpdate, System};
        let mut sys = System::new().expect("a System");
        let pid = Pid::from_u32(m.pid);
        sys.refresh_processes_specifics(ProcessesToUpdate::Some(&[pid]), true, ProcessRefreshKind::nothing());
        sys.process(pid).is_some_and(|p| p.start_time() == m.mark)
    }

    #[cfg(unix)]
    #[cfg_attr(
        unix,
        expect(
            clippy::disallowed_methods,
            reason = "ADR 0033 WP-6 (test): kills tree members found by parent pids; use paddock_proc"
        )
    )]
    fn kill_pid(pid: u32) {
        if let Ok(p) = i32::try_from(pid) {
            let _ = nix::sys::signal::kill(nix::unistd::Pid::from_raw(p), nix::sys::signal::Signal::SIGKILL);
        }
    }

    #[cfg(windows)]
    fn kill_pid(pid: u32) {
        let _ = quiet_command(&taskkill_exe()).args(["/PID", &pid.to_string(), "/F"]).output();
    }

    #[test]
    fn a_missing_program_is_an_error_that_names_no_arguments() {
        let mut cmd = quiet_command(Path::new("pitcrew-no-such-program"));
        cmd.args(["--token", "SECRET"]);
        let err = run_with_timeout(cmd, Duration::from_secs(5)).unwrap_err();
        assert!(matches!(err, Error::Os { .. }));
        assert!(!err.to_string().contains("SECRET"));
    }
}

//! The supervisor end to end with a fake runner (`examples/fake_runner.rs`): real processes, pipes, logs and
//! graceful stops; a controllable clock so backoff and the job grace period take no real time.
//!
//! Nothing here depends on how fast the machine is: jobs are held (`job_secs=hold`) until the test releases them, a
//! test waits for what the supervisor has *seen* (a job's processes in its usage, not only the "task started" line),
//! and every wait is on a condition. A real-time job length or a fixed number of fake-clock steps that must fit into
//! one real job made these tests fail or time out on a loaded runner (CI run 6628).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::disallowed_methods, missing_docs)]

use paddock_testkit::TestCommand;
use pitcrew_core::health::RunnerStatus;
use pitcrew_core::history::HistoryEvent;
use pitcrew_core::history::HistoryKind;
use pitcrew_core::names::RunnerName;
use pitcrew_core::process_track::ATTRIBUTION_SLACK;
use pitcrew_core::protocol::{Request, Response, RunnerSnapshot, Secret};
use pitcrew_core::time::Timestamp;
use pitcrew_core::update::{LocalMoment, TimeOfDay, Weekday};
use pitcrew_service::launcher::OsLauncher;
use pitcrew_service::supervisor::{Env, Msg, Supervisor};
use pitcrew_service::work::Sources;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::mpsc::Receiver;
use std::sync::Arc;
use std::time::{Duration, Instant};

const EXE: &str = std::env::consts::EXE_SUFFIX;

fn fake_runner() -> PathBuf {
    static BUILT: std::sync::OnceLock<PathBuf> = std::sync::OnceLock::new();
    BUILT
        .get_or_init(|| {
            // Both build-folder layouts (cargo before 1.100 and after), or a loud refusal (CI run 8027).
            let path = paddock_testkit::cargo_layout::example_bin("fake_runner");
            // `cargo test` and `cargo nextest run` build examples, `cargo test --test supervision` does not. Build it only
            // when it is missing: nextest runs every test in a process of its own, and one `cargo build` per test queued
            // on cargo's build lock until the tests ran out of time (and missed a build folder set by `--config`).
            if !path.exists() {
                let status = TestCommand::new(env!("CARGO"))
                    .cargo_build()
                    .args(["build", "--quiet", "-p", "pitcrew-service", "--example", "fake_runner"])
                    .status()
                    .unwrap();
                assert!(status.success(), "the fake runner could not be built");
            }
            assert!(path.exists(), "the fake runner is missing: {}", path.display());
            path
        })
        .clone()
}

/// The folder the harness puts each test's runner in. The runner is started disclaimed, so it is its own responsible
/// process (ADR 0020), and macOS (TCC, Removable Volumes) asked "gitea-runner would like to access files on a removable
/// volume" once per test when `TMPDIR` was on an external disk: each test copies the fake runner to a new path, and TCC keys
/// an unbundled ad-hoc program by its path (docs/lessons.md, 2026-11-04 and 2026-11-11). The shared rule keeps it on the
/// boot volume.
fn runner_temp_root() -> PathBuf {
    paddock_testkit::boot_volume::boot_volume_temp()
}

struct Harness {
    sup: Supervisor,
    rx: Receiver<Msg>,
    clock: Arc<AtomicU64>,
    root: PathBuf,
    runner_dir: PathBuf,
    name: RunnerName,
    exe: Arc<AtomicU64>,
}

impl Harness {
    fn new(test: &str, fake: &str, registered: bool) -> Harness {
        Harness::with_runner_toml(test, fake, registered, "")
    }

    /// `runner_toml` is appended to the runner's table (e.g. an `[runners.env]` table).
    fn with_runner_toml(test: &str, fake: &str, registered: bool, runner_toml: &str) -> Harness {
        Harness::build(test, fake, registered, runner_toml, None)
    }

    /// `state_json` is written as the service's `state.json` before it starts.
    #[allow(
        clippy::disallowed_methods,
        reason = "a test builds its scratch path from the OS temp folder and removes it"
    )]
    fn build(test: &str, fake: &str, registered: bool, runner_toml: &str, state_json: Option<&str>) -> Harness {
        pitcrew_service::launch::set_stop_helper(PathBuf::from(env!("CARGO_BIN_EXE_pitcrew-service")));
        let root = runner_temp_root().join(format!("pitcrew-it-{test}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let data = root.join("data");
        let runner_dir = root.join("runner");
        std::fs::create_dir_all(runner_dir.join("bin")).unwrap();
        std::fs::create_dir_all(&data).unwrap();
        std::fs::copy(fake_runner(), runner_dir.join("bin").join(format!("gitea-runner{EXE}")))
            .expect("build the example: cargo test builds it");
        std::fs::write(runner_dir.join("fake.txt"), fake).unwrap();
        std::fs::write(runner_dir.join("config.yaml"), "log:\n  level: info\n").unwrap();
        if registered {
            std::fs::write(runner_dir.join(".runner"), "{}").unwrap();
        }
        let toml = format!(
            "schema_version = 1\n[defaults.update]\nmode = \"manual\"\n[defaults.cleanup]\nautomatic = false\n[[runners]]\nname = \"{test}\"\nkind = \"gitea-runner\"\ndir = '{}'\nsession = \"service\"\nlabels = [\"x\"]\n{runner_toml}",
            runner_dir.display()
        );
        std::fs::write(data.join("pitcrew.toml"), toml).unwrap();
        if let Some(state) = state_json {
            std::fs::write(data.join("state.json"), state).unwrap();
        }
        let clock = Arc::new(AtomicU64::new(pitcrew_service::cleanup::now().0));
        let c = clock.clone();
        let exe = Arc::new(AtomicU64::new(1));
        let exe2 = exe.clone();
        let env = Env {
            data_dir: data,
            launcher: Box::new(OsLauncher),
            sources: Sources::public(),
            platform: pitcrew_core::platform::Platform::current().unwrap(),
            exe_stamp: Arc::new(move || {
                Some(pitcrew_core::self_update::BinaryStamp {
                    len: exe2.load(Ordering::SeqCst),
                    modified_ms: 0,
                })
            }),
            base_path: Arc::new(|| Some("/pitcrew/test-path:/usr/bin:/bin".to_string())),
            clock: Arc::new(move || Timestamp(c.load(Ordering::SeqCst))),
            local: Arc::new(|_| {
                (
                    LocalMoment {
                        weekday: Weekday::Mon,
                        time: TimeOfDay::new(12, 0).unwrap(),
                    },
                    0,
                )
            }),
        };
        let (tx, rx) = std::sync::mpsc::channel();
        let sup = Supervisor::new(env, tx);
        Harness {
            sup,
            rx,
            clock,
            root,
            runner_dir,
            name: RunnerName::parse(test).unwrap(),
            exe,
        }
    }

    fn now(&self) -> Timestamp {
        Timestamp(self.clock.load(Ordering::SeqCst))
    }

    /// Ends every process the test started: anything running from or inside the harness folder, and their descendants.
    fn kill_leftover_processes(&self) {
        use sysinfo::{Pid, ProcessRefreshKind, ProcessesToUpdate, System};
        let mut sys = System::new().expect("a System");
        sys.refresh_processes_specifics(
            ProcessesToUpdate::All,
            true,
            ProcessRefreshKind::nothing()
                .with_exe(sysinfo::UpdateKind::Always)
                .with_cwd(sysinfo::UpdateKind::Always),
        );
        let root = self.root.canonicalize().unwrap_or_else(|_| self.root.clone());
        let mut doomed: std::collections::HashSet<Pid> = sys
            .processes()
            .iter()
            .filter(|(_, p)| {
                let inside = |q: Option<&std::path::Path>| q.is_some_and(|q| q.starts_with(&self.root) || q.starts_with(&root));
                let cmd = p.cmd().iter().map(|a| a.to_string_lossy()).collect::<Vec<_>>().join(" ");
                inside(p.exe()) || inside(p.cwd()) || cmd.contains(&*self.root.to_string_lossy())
            })
            .map(|(pid, _)| *pid)
            .collect();
        loop {
            let before = doomed.len();
            for (pid, p) in sys.processes() {
                if p.parent().is_some_and(|pp| doomed.contains(&pp)) {
                    doomed.insert(*pid);
                }
            }
            if doomed.len() == before {
                break;
            }
        }
        let me = Pid::from_u32(std::process::id());
        for pid in doomed.into_iter().filter(|p| *p != me) {
            if let Some(p) = sys.process(pid) {
                p.kill();
            }
        }
    }

    /// Advances the fake clock by `step`, processes everything that arrived (waiting briefly for the first message, so
    /// the runner's output and processes can move on between steps) and ticks once.
    fn pump(&mut self, step: Duration) {
        self.clock.fetch_add(step.as_millis() as u64, Ordering::SeqCst);
        if let Ok(m) = self.rx.recv_timeout(Duration::from_millis(30)) {
            self.sup.handle(m);
        }
        while let Ok(m) = self.rx.try_recv() {
            self.sup.handle(m);
        }
        self.sup.tick(self.now());
    }

    /// Ends the held job (`job_secs=hold`): the fake runner ends the job's process when this file appears.
    fn release_job(&self) {
        let _ = std::fs::write(self.runner_dir.join("release"), "");
    }

    /// Runs until the supervisor has recorded the released job as finished. The clock has to move: a job ends
    /// `IDLE_CONFIRM` after its processes were last seen, and every step is one look at them.
    fn until_job_finished(&mut self) {
        self.until("the job is recorded as finished", PROBE_STEP, |h| {
            count(&h.history(), |k| matches!(k, HistoryKind::JobFinished { .. })) >= 1
        });
    }

    /// Waits until the supervisor has seen the job's processes, not only its "task started" line: a job counts as
    /// running past the line's grace period (`IDLE_CONFIRM`) only while its processes are seen. On a loaded machine the
    /// process starts well after the line (`spawn_delay_ms` in the fake makes that so every time).
    ///
    /// Until the processes run the clock follows the real one: the job's start is the clock's time when its line is
    /// read, and its processes' start times come from the real clock, so a clock running ahead (or falling behind)
    /// while the machine is slow would put them outside the job (`ATTRIBUTION_SLACK`) and its leftovers would never be
    /// found (CI run 6628 timed out so). One probe step then shows them to the supervisor.
    fn until_job_processes_seen(&mut self) {
        // The line itself, not only a job: a look at the processes can find the job before its line is read (CI job
        // 21879), and the job is named only by the line.
        self.until_real("the job's line is read", |h| {
            h.status().current_job.is_some_and(|j| j.info.repository.is_some())
        });
        let started = self.status().current_job.unwrap().started_at;
        let ahead = started.0.saturating_sub(pitcrew_service::cleanup::now().0);
        assert!(
            Duration::from_millis(ahead) < ATTRIBUTION_SLACK,
            "the job's start ({ahead} ms ahead of the real clock) must be within ATTRIBUTION_SLACK of its processes' start"
        );
        let marker = self.runner_dir.join("job.started");
        self.until_real("the job's processes run", |_| marker.exists());
        // The runner alone is one process; on Windows its console host (`conhost.exe`) makes two.
        let base = if cfg!(windows) { 2 } else { 1 };
        self.pump(PROBE_STEP);
        let s = self.status();
        assert!(
            s.current_job.is_some() && s.usage.is_some_and(|u| u.processes > base),
            "the probe after the job's processes started sees them: {s:?}"
        );
    }

    /// Runs until cleanup has stopped the leftover `pid`. The clock moves in steps of `step` while the stop cannot be
    /// due yet (before the leftover's `StopsAt` time), then one probe step at a time until the stop begins (the time
    /// has come and the runner is idle: the probe tick that sees both asks the process to stop), and then holds still
    /// until the stop is recorded: with the clock moving, a process slower to exit than the stop timeout's few clock
    /// steps would be ended by force instead.
    #[cfg(unix)]
    fn until_stopped(&mut self, what: &str, step: Duration, pid: u32) {
        let events_before = self.process_events().len();
        let at = match self
            .processes()
            .entries
            .iter()
            .find(|e| e.pid == pid)
            .and_then(|e| e.leftover.clone())
        {
            Some(pitcrew_core::process_track::Leftover {
                fate: Fate::StopsAt { at },
                ..
            }) => at,
            other => panic!("{pid} is not a leftover with a stop time: {other:?}"),
        };
        while self.now().0 + (step.as_millis() as u64) < at.0 {
            self.pump(step);
        }
        self.until(what, PROBE_STEP, |h| {
            (h.now() >= at && h.processes().idle) || h.process_events().len() > events_before
        });
        self.until(what, Duration::ZERO, |h| h.process_events().len() > events_before);
        // A look at the processes after the stop, so the list and the counts show it.
        self.pump(PROBE_STEP);
    }

    /// Pumps in steps of `step` until `f` holds.
    fn until(&mut self, what: &str, step: Duration, f: impl FnMut(&mut Harness) -> bool) {
        self.wait(what, Some(step), f);
    }

    /// Like [`Harness::until`], with the clock following the real one (never behind it, never ahead by more than it
    /// was): for waits on real processes whose start times the supervisor compares with its clock. The clock still
    /// moves while it waits, so a job whose processes nobody has seen ends after `IDLE_CONFIRM` (20 s) of real time:
    /// use it only for waits the fake runner ends promptly (its line, its `job.started` marker).
    fn until_real(&mut self, what: &str, f: impl FnMut(&mut Harness) -> bool) {
        self.wait(what, None, f);
    }

    fn wait(&mut self, what: &str, step: Option<Duration>, mut f: impl FnMut(&mut Harness) -> bool) {
        let deadline = Instant::now() + Duration::from_secs(40);
        while !f(self) {
            assert!(
                Instant::now() < deadline,
                "timed out waiting for: {what}; status {:?}",
                self.status()
            );
            match step {
                Some(step) => self.pump(step),
                None => {
                    self.clock.fetch_max(pitcrew_service::cleanup::now().0, Ordering::SeqCst);
                    self.pump(Duration::ZERO);
                }
            }
        }
    }

    fn ask(&mut self, req: Request) -> Response {
        let (tx, mut rx) = tokio::sync::oneshot::channel();
        self.sup.handle(Msg::Request(Box::new(req), tx));
        let deadline = Instant::now() + Duration::from_secs(60);
        loop {
            if let Ok(r) = rx.try_recv() {
                return r;
            }
            assert!(Instant::now() < deadline, "no answer");
            self.pump(Duration::from_millis(100));
        }
    }

    fn status(&mut self) -> RunnerSnapshot {
        let (tx, mut rx) = tokio::sync::oneshot::channel();
        self.sup.handle(Msg::Request(Box::new(Request::Status), tx));
        match rx.try_recv().unwrap() {
            Response::Status { runners, .. } => runners.into_iter().next().unwrap(),
            other => panic!("{other:?}"),
        }
    }

    fn history(&mut self) -> Vec<HistoryEvent> {
        match self.ask(Request::History {
            runner: self.name.clone(),
            days: 1,
            utc_offset_minutes: 0,
        }) {
            Response::History { events, .. } => events,
            other => panic!("{other:?}"),
        }
    }

    fn log(&self) -> String {
        std::fs::read_to_string(self.runner_dir.join("logs").join("runner.log")).unwrap_or_default()
    }

    fn finish_stopped_usage(mut self) {
        let _ = self.ask(Request::Stop { runner: self.name.clone() });
        self.until("stopped", Duration::from_secs(6), |h| h.status().running_since.is_none());
        self.pump(Duration::from_secs(6));
        assert!(self.status().usage.is_none(), "a stopped runner uses nothing");
        let _ = std::fs::remove_dir_all(&self.root);
    }

    fn finish(mut self) {
        let _ = self.ask(Request::Stop { runner: self.name.clone() });
        let deadline = Instant::now() + Duration::from_secs(20);
        while self.status().running_since.is_some() && Instant::now() < deadline {
            self.pump(Duration::from_secs(30));
        }
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

impl Drop for Harness {
    /// A failing test never leaves its fake runner (or the processes it started) running: everything whose program,
    /// working folder or command line is in this test's folder is killed with its descendants, then the folder goes.
    fn drop(&mut self) {
        // A held job ends first, so the fake runner never leaves its `sleep 100000` behind.
        self.release_job();
        self.kill_leftover_processes();
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

/// One clock step that is sure to include a look at the processes.
const PROBE_STEP: Duration = pitcrew_service::supervisor::PROBE_EVERY;

fn count(h: &[HistoryEvent], f: impl Fn(&HistoryKind) -> bool) -> usize {
    h.iter().filter(|e| f(&e.kind)).count()
}

#[test]
fn a_runner_that_exits_is_restarted_after_the_backoff() {
    let mut h = Harness::new("crashy", "mode=exit\ncode=3\n", true);
    h.until("first exit", Duration::from_millis(100), |h| {
        let hist = h.history();
        count(&hist, |k| {
            matches!(
                k,
                HistoryKind::Exited {
                    code: Some(3),
                    expected: false
                }
            )
        }) == 1
    });
    let s = h.status();
    assert!(s.next_start_at.is_some(), "a restart is scheduled: {s:?}");
    assert_eq!(s.restarts_24h, 1);
    assert!(h.log().contains("supervisor: the runner exited with code 3"));
    assert!(h.log().contains("declare successfully"), "the runner's own output is in the log");
    // Ten seconds of backoff pass in one step.
    h.pump(Duration::from_secs(11));
    h.until("second start", Duration::from_millis(100), |h| {
        count(&h.history(), |k| *k == HistoryKind::Started) >= 2
    });
    h.finish();
}

#[test]
fn runners_start_with_the_login_path_and_their_own_env() {
    let mut h = Harness::with_runner_toml("envy", "mode=ok\n", true, "[runners.env]\nCI_FLAG = \"yes\"\n");
    let dump = h.runner_dir.join("env.txt");
    // Wait for the line that is asserted, not just for the file: the runner may still be writing it.
    h.until("the runner wrote its environment", Duration::from_millis(100), |_| {
        std::fs::read_to_string(&dump).is_ok_and(|t| t.contains("CI_FLAG=yes\n"))
    });
    let text = std::fs::read_to_string(&dump).unwrap();
    assert!(text.contains("PATH=/pitcrew/test-path:/usr/bin:/bin\n"), "{text}");
    assert!(text.contains("CI_FLAG=yes\n"), "{text}");
    h.finish();
    // A runner's own PATH replaces the login one.
    let mut h = Harness::with_runner_toml("envy2", "mode=ok\n", true, "[runners.env]\nPATH = \"/only/this\"\n");
    let dump = h.runner_dir.join("env.txt");
    h.until("the runner wrote its environment", Duration::from_millis(100), |_| {
        std::fs::read_to_string(&dump).is_ok_and(|t| t.contains("PATH=/only/this\n"))
    });
    assert!(std::fs::read_to_string(&dump).unwrap().contains("PATH=/only/this\n"));
    h.finish();
}

#[test]
fn a_stalled_runner_is_stopped_gracefully_and_restarted() {
    let mut h = Harness::new("stally", "mode=stall\n", true);
    h.until("stall", Duration::from_millis(200), |h| {
        count(&h.history(), |k| matches!(k, HistoryKind::Stalled { .. })) == 1
    });
    h.until("graceful exit", Duration::from_millis(200), |h| {
        count(&h.history(), |k| matches!(k, HistoryKind::Exited { expected: true, .. })) == 1
    });
    // The runner's output comes through a reader thread, so its last line can reach the log after the supervisor has
    // seen the exit: wait for the line (the real clock, no clock step), do not assume it came first.
    h.until("the runner's shutdown line is logged", Duration::ZERO, |h| {
        h.log().contains("shutdown initiated")
    });
    assert!(h.log().contains("supervisor: runner stalled"));
    h.pump(Duration::from_secs(11));
    h.until("restart", Duration::from_millis(200), |h| {
        count(&h.history(), |k| *k == HistoryKind::Started) >= 2
    });
    h.finish();
}

#[test]
fn stop_waits_for_the_running_job() {
    // The job runs until the test releases it, however slow the machine is.
    let mut h = Harness::new("busy", "mode=job\njob_secs=hold\n", true);
    h.until_job_processes_seen();
    let s = h.status();
    assert_eq!(s.status, RunnerStatus::Busy);
    assert_eq!(s.current_job.unwrap().info.repository.as_deref(), Some("owner/app"));
    assert_eq!(h.ask(Request::Stop { runner: h.name.clone() }), Response::Ok);
    assert_eq!(h.status().status, RunnerStatus::Draining, "it finishes the job first");
    // While the job's process lives, nothing is stopped however much time passes.
    for _ in 0..5 {
        h.pump(Duration::from_secs(60));
        assert!(h.status().running_since.is_some());
        assert_eq!(h.status().status, RunnerStatus::Draining);
    }
    h.release_job();
    h.until_job_finished();
    // The stop request went out on the tick that saw the job end; the clock holds still while the runner exits.
    h.until("stopped after the job", Duration::ZERO, |h| {
        h.status().status == RunnerStatus::Stopped
    });
    let hist = h.history();
    assert_eq!(count(&hist, |k| matches!(k, HistoryKind::JobFinished { .. })), 1);
    assert_eq!(count(&hist, |k| matches!(k, HistoryKind::Exited { expected: true, .. })), 1);
    let _ = std::fs::remove_dir_all(&h.root);
}

#[test]
fn usage_follows_the_runner_and_the_processes_it_started() {
    let mut h = Harness::new("meter", "mode=job\njob_secs=hold\n", true);
    // The runner alone is one process; on Windows its console host (`conhost.exe`) makes two.
    let base = if cfg!(windows) { 2 } else { 1 };
    // The job's child (the stand-in for a compiler) is counted with the runner.
    h.until_job_processes_seen();
    let during = h.status().usage.unwrap();
    assert!(during.mem_bytes > 0, "{during:?}");
    assert!(during.cpu_permille <= 1000);
    // It exits, and drops out of the count while the runner stays. On Windows the runner also has its console host,
    // which stays.
    h.release_job();
    h.until("the exited child is no longer counted", Duration::from_secs(20), |h| {
        h.status().usage.is_some_and(|u| u.processes == base)
    });
    // The history has the runner's series and the machine series carries the runners' share.
    let name = h.name.clone();
    h.until("a usage sample is stored", Duration::from_secs(31), |h| {
        match h.ask(Request::Metrics {
            runner: Some(name.clone()),
            range_hours: 1,
        }) {
            Response::Metrics { usage, .. } => !usage.is_empty(),
            other => panic!("{other:?}"),
        }
    });
    let Response::Metrics { machine, usage, .. } = h.ask(Request::Metrics {
        runner: Some(name),
        range_hours: 1,
    }) else {
        panic!("metrics")
    };
    assert!(usage.iter().all(|p| p.usage.mem_bytes > 0));
    assert!(
        machine.last().unwrap().runners.mem_bytes > 0,
        "the machine point holds the runners' share"
    );
    // Stopped: no usage is reported for it.
    h.finish_stopped_usage();
}

#[test]
fn an_unregistered_runner_is_registered_from_the_app() {
    let mut h = Harness::new("fresh", "mode=ok\n", false);
    h.pump(Duration::from_secs(1));
    assert_eq!(h.status().status, RunnerStatus::NotRegistered);
    let bad = h.ask(Request::Register {
        runner: h.name.clone(),
        server_url: "https://git.example.com".into(),
        token: Secret::new("bad").unwrap(),
        display_name: None,
    });
    let Response::Error(e) = bad else { panic!("{bad:?}") };
    assert!(e.message.contains("refused to register"), "{}", e.message);
    assert!(!e.message.contains(" bad "), "the token never appears in messages: {}", e.message);
    let ok = h.ask(Request::Register {
        runner: h.name.clone(),
        server_url: "https://git.example.com/".into(),
        token: Secret::new("good-token").unwrap(),
        display_name: Some("Fresh runner".into()),
    });
