    fn write_at(path: &Path, text: &str, secs: u64) {
        write(path, text);
        let f = std::fs::OpenOptions::new().write(true).open(path).unwrap();
        f.set_modified(std::time::UNIX_EPOCH + std::time::Duration::from_secs(secs))
