            Err(Refusal::OtherOwner { uid: 9 })
        ));
        assert_eq!(sys::file_decision(f(5, 0o600), 5), Ok(()));
        assert!(matches!(
            sys::file_decision(f(5, 0o640), 5),
            Err(Refusal::OpenToOthers { .. })
        ));
        assert!(matches!(
            sys::file_decision(f(5, 0o604), 5),
            Err(Refusal::OpenToOthers { .. })
