        std::fs::create_dir(&attacker).unwrap();
        assert!(
            std::fs::rename(&outer, t.path().join("moved")).is_err(),
            "no FILE_SHARE_DELETE on the held chain"
        );
        assert!(std::fs::remove_dir_all(&outer).is_err());
        held.write_atomic("secret", b"s").unwrap();
        assert_eq!(std::fs::read_dir(&attacker).unwrap().count(), 0);
        assert_eq!(
            std::fs::read(outer.join("inner").join("secret")).unwrap(),
            b"s"
        );
    }

    #[test]
    fn a_parent_where_others_can_delete_entries_is_refused() {
        let t = temp();
        let parent = t.path().join("parent");
        std::fs::create_dir(&parent).unwrap();
        let p = parent.join("d");
        PrivateDir::create_all(&p).unwrap();
        icacls(&parent, &["/grant", &format!("*{EVERYONE}:(DC)")]);
        let r = refusal(PrivateDir::open(&p, Links::Refuse).unwrap_err());
        assert!(
            matches!(&r, Refusal::Parent(inner) if matches!(**inner, Refusal::OpenToOthersAcl { .. })),
            "{r:?}"
        );
        assert!(PrivateDir::create_all(&p).is_err());
    }

    #[test]
    fn a_file_others_can_read_or_that_is_not_ours_or_not_a_file_is_refused_on_windows() {
        let t = temp();
        let d = PrivateDir::create_all(&t.path().join("d")).unwrap();
        d.write_atomic("f", b"x").unwrap();
        assert!(d.open_file("f").is_ok());
        icacls(&d.path().join("f"), &["/grant", &format!("*{EVERYONE}:R")]);
        assert!(matches!(
            refusal(d.open_file("f").unwrap_err()),
            Refusal::OpenToOthersAcl { .. }
        ));
        std::fs::create_dir(d.path().join("sub")).unwrap();
        assert_eq!(refusal(d.open_file("sub").unwrap_err()), Refusal::NotAFile);
        let other = PrivateDir {
            dir: Dir::open_path(d.path(), false).unwrap(),
            path: d.path().to_path_buf(),
            who: EVERYONE.to_owned(),
        };
        d.write_atomic("g", b"x").unwrap();
        assert!(matches!(
            refusal(other.open_file("g").unwrap_err()),
            Refusal::OtherOwnerAccount { .. }
        ));
    }

    #[test]
    fn a_failed_replace_reports_and_removes_the_temporary_file() {
        let t = temp();
        let d = PrivateDir::create_all(&t.path().join("d")).unwrap();
        std::fs::create_dir(d.path().join("f")).unwrap();
        let e = d.write_atomic("f", b"x").unwrap_err();
        assert!(matches!(&e, PrivateError::Io { op: "replace", .. }), "{e}");
        let names: Vec<_> = std::fs::read_dir(d.path())
            .unwrap()
            .map(|e| e.unwrap().file_name())
            .collect();
        assert_eq!(
            names,
            vec![OsStr::new("f")],
            "the temporary file is removed"
        );
    }

    #[test]
    fn a_taken_temporary_name_is_retried() {
        let t = temp();
        let d = PrivateDir::create_all(&t.path().join("d")).unwrap();
        let pid = std::process::id();
        std::fs::write(d.path().join(format!(".f.{pid}-0.tmp")), b"planted").unwrap();
        let e = d
            .create_temp_with("f", d.path(), || 0)
            .map(|_| ())
            .unwrap_err();
        assert!(
            matches!(&e, PrivateError::Io { source, .. } if source.kind() == std::io::ErrorKind::AlreadyExists),
            "{e}"
        );
        let mut n = 0;
        let (name, _file) = d
            .create_temp_with("f", d.path(), || {
                n += 1;
                n - 1
            })
            .unwrap();
        assert!(name.ends_with("-1.tmp"), "{name}");
    }

    #[test]
    fn the_root_has_no_folder_above_it() {
        let e = PrivateDir::create_all(Path::new("C:\\")).unwrap_err();
        assert!(
            matches!(e, PrivateError::Io { .. } | PrivateError::Refused { .. }),
            "{e}"
        );
    }

    /// Review P2-2, Windows half: an existing child with an Everyone ACL is refused by `child`.
    #[test]
    fn an_existing_child_with_an_everyone_acl_is_refused() {
        let t = temp();
        let d = PrivateDir::create_all(&t.path().join("d")).unwrap();
        d.child("c").unwrap();
        icacls(
            &d.path().join("c"),
            &["/grant", &format!("*{EVERYONE}:(OI)(CI)F")],
        );
        assert_eq!(
            refusal(d.child("c").unwrap_err()),
            Refusal::OpenToOthersAcl {
                who: EVERYONE.to_owned()
            }
        );
    }

    /// Review P2-5: a held reader of the file must not make the replace fail, and keeps reading the old content.
    #[test]
    fn a_held_reader_does_not_stop_a_replace() {
        let t = temp();
        let d = PrivateDir::create_all(&t.path().join("d")).unwrap();
        d.write_atomic("f", b"old").unwrap();
        let reader = d.open_file("f").unwrap();
        d.write_atomic("f", b"new").unwrap();
        assert_eq!(d.read("f", 10).unwrap(), b"new");
        assert_eq!(reader.read_to_vec(10).unwrap(), b"old");
    }

    /// The plain `FileRenameInformation` class, which the replace falls back to on a system without the Ex class.
    #[test]
    fn the_plain_rename_class_replaces_too() {
        let t = temp();
        let d = PrivateDir::create_all(&t.path().join("d")).unwrap();
        d.write_atomic("f", b"old").unwrap();
        let (tmp, mut file) = d.create_temp("f", d.path()).unwrap();
        std::io::Write::write_all(&mut file, b"new").unwrap();
        d.dir.rename_plain(&file, OsStr::new("f")).unwrap();
        drop(file);
        assert_eq!(d.read("f", 10).unwrap(), b"new");
        assert!(!d.path().join(tmp).exists());
    }
}

//! The `ETXTBSY` retry (CI run 8174): its bound, its one error, and the two real refusals it exists for.

use paddock_env::text_busy::{self, MAX_RETRIES, is_text_busy, retry};
use std::io;

fn busy() -> io::Error {
    io::Error::from(io::ErrorKind::ExecutableFileBusy)
}

#[test]
fn a_busy_file_is_tried_again_until_it_is_free() {
    let mut calls = 0;
    let got = retry("busy-then-free", || {
        calls += 1;
        if calls < 4 { Err(busy()) } else { Ok(calls) }
    });
    assert_eq!(got.unwrap(), 4);
    assert_eq!(text_busy::retries_for("busy-then-free"), 3);
}

#[test]
fn any_other_error_returns_at_once() {
    let mut calls = 0;
    let got: io::Result<()> = retry("test", || {
        calls += 1;
        Err(io::Error::from(io::ErrorKind::PermissionDenied))
    });
    assert_eq!(got.unwrap_err().kind(), io::ErrorKind::PermissionDenied);
    assert_eq!(calls, 1);
}

#[test]
fn a_file_that_stays_busy_fails_after_the_bound_with_the_same_error() {
    let mut calls = 0;
    let got: io::Result<()> = retry("test", || {
        calls += 1;
        Err(busy())
    });
    assert!(is_text_busy(&got.unwrap_err()));
    assert_eq!(calls, MAX_RETRIES + 1);
}

// Linux only: macOS lets a file that is open for writing be executed and a running program be written (the probes below
// would fail there, which is how this was found).
#[cfg(target_os = "linux")]
mod real {
    use super::*;
    use std::fs::OpenOptions;
    use std::io::Write;
    use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
    use std::process::Command;
    use std::sync::mpsc;

    fn script(dir: &std::path::Path, body: &str) -> std::path::PathBuf {
        let path = dir.join("prog.sh");
        let mut f = OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .mode(0o755)
            .open(&path)
            .unwrap();
        f.write_all(format!("#!/bin/sh\n{body}\n").as_bytes())
            .unwrap();
        drop(f);
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).unwrap();
        path
    }

    /// The first refusal: executing a file that something holds open for writing (what a child forked in the middle of a write
    /// holds). The write handle is let go only after the first attempt failed, so the retry is what makes the start succeed.
    #[test]
    fn a_program_whose_write_handle_is_still_held_starts_after_the_retry() {
        let dir = tempfile::tempdir().unwrap();
        let path = script(dir.path(), "exit 0");
        let writer = OpenOptions::new().write(true).open(&path).unwrap();
        // The precondition (ER-33): without the retry this start really is refused.
        let raw = Command::new(&path).spawn();
        assert!(
            raw.as_ref().is_err_and(is_text_busy),
            "the held write handle must make the start fail with ETXTBSY, got {raw:?}"
        );
        let (failed_tx, failed_rx) = mpsc::channel();
        let releaser = std::thread::spawn(move || {
            failed_rx.recv().unwrap();
            drop(writer);
        });
        let mut cmd = Command::new(&path);
        let mut child = retry("start the script", || {
            let r = cmd.spawn();
            if r.as_ref().is_err_and(is_text_busy) {
                failed_tx.send(()).ok();
            }
            r
        })
        .unwrap();
        releaser.join().unwrap();
        assert!(child.wait().unwrap().success());
    }

    /// Ends its child on every path out of a test, a failed assertion included (no zombie).
    struct Reap(Option<std::process::Child>);

    impl Reap {
        fn end(&mut self) {
            if let Some(mut c) = self.0.take() {
                c.kill().unwrap();
                c.wait().unwrap();
            }
        }
    }

    impl Drop for Reap {
        fn drop(&mut self) {
            if let Some(mut c) = self.0.take() {
                drop(c.kill());
                drop(c.wait());
            }
        }
    }

    /// The second refusal: writing a file whose program is running (a copy of `sleep`: only a binary the kernel maps is busy,
    /// a script is only read by its shell). The program is ended only after the first write failed, so what the retry waits
    /// out is the end of the program.
    #[test]
    fn a_program_that_still_runs_can_be_written_again_once_it_has_ended() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("prog");
        std::fs::copy("/bin/sleep", &path).unwrap();
        let mut cmd = Command::new(&path);
        cmd.arg("600");
        let mut child = Reap(Some(retry("start the program", || cmd.spawn()).unwrap()));
        let raw = std::fs::write(&path, b"#!/bin/sh\nexit 0\n");
        assert!(
            raw.as_ref().is_err_and(is_text_busy),
            "a running program must refuse a write with ETXTBSY, got {raw:?}"
        );
        let mut ended = false;
        retry("replace the program", || {
            let r = std::fs::write(&path, b"#!/bin/sh\nexit 0\n");
            if r.as_ref().is_err_and(is_text_busy) && !ended {
                child.end();
                ended = true;
            }
            r
        })
        .unwrap();
        assert!(
            ended,
            "the first retried write must have met the running program"
        );
    }
}

//! The OS measurements of ADR 0072 WP-0 (rule 48; results in docs/benchmarks.md): what a client reads when the other side
//! closes with unread received data, whether a pipe closed with `CloseHandle` still delivers what was written before it,
//! what a client waiting in a listener's backlog sees when the listener closes, and the baseline of an ordered close
//! (close-to-release time, refusals per second). It uses only the OS's own APIs, not paddock-ipc, so it measures the platform.
//!
//! Run: `cargo run --release -p paddock-ipc --example os_endings`. Each line is `RESULT <what> <key=value>...`. Nothing
//! sleeps: the orchestration waits on the data itself (`MSG_PEEK` until it arrived), and every read has a hang guard.
#![allow(unsafe_code, clippy::unwrap_used, clippy::expect_used, missing_docs)]

use std::collections::BTreeMap;
use std::io::{ErrorKind, Read, Write};
use std::net::{Shutdown, TcpListener, TcpStream};
use std::time::{Duration, Instant};

const REPS: usize = 200;
const TIMING_REPS: usize = 500;
const GUARD: Duration = Duration::from_secs(10);

/// How a read-to-end finished, as a class.
fn classify(bytes: &[u8], end: Result<(), ErrorKind>, expect: &[u8]) -> String {
    let got = bytes.starts_with(expect);
    match (got, end) {
        (true, Ok(())) => "reason+eof".into(),
        (true, Err(k)) => format!("reason+error({k:?})"),
        (false, Ok(())) => "eof-without-reason".into(),
        (false, Err(k)) => format!("error({k:?})-without-reason"),
    }
}

fn read_end(r: &mut impl Read) -> (Vec<u8>, Result<(), ErrorKind>) {
    let mut bytes = Vec::new();
    let mut buf = [0u8; 4096];
    loop {
        match r.read(&mut buf) {
            Ok(0) => return (bytes, Ok(())),
            Ok(n) => bytes.extend_from_slice(&buf[..n]),
            Err(e) if e.kind() == ErrorKind::Interrupted => {}
            Err(e) => return (bytes, Err(e.kind())),
        }
    }
}

fn report(what: &str, counts: &BTreeMap<String, usize>) {
    let line: Vec<String> = counts.iter().map(|(k, v)| format!("{k}={v}")).collect();
    println!("RESULT {what} reps={REPS} {}", line.join(" "));
}

fn tcp_pair(l: &TcpListener) -> (TcpStream, TcpStream) {
    let c = TcpStream::connect(l.local_addr().unwrap()).unwrap();
    let (s, _) = l.accept().unwrap();
    // Set before anything closes: macOS refuses setsockopt on a socket the peer has reset.
    c.set_read_timeout(Some(GUARD)).unwrap();
    (s, c)
}

/// Waits until `s` holds `n` unread bytes (a condition, not a pause).
fn tcp_wait_unread(s: &TcpStream, n: usize) {
    let mut buf = vec![0u8; n];
    let end = Instant::now() + GUARD;
    while s.peek(&mut buf).unwrap() < n {
        assert!(Instant::now() < end, "the data never arrived");
        std::thread::yield_now();
    }
}

fn tcp_unread() {
    let l = TcpListener::bind("127.0.0.1:0").unwrap();
    let mut counts = BTreeMap::new();
    for _ in 0..REPS {
        let (mut s, mut c) = tcp_pair(&l);
        c.write_all(&[7u8; 4096]).unwrap();
        tcp_wait_unread(&s, 4096);
        s.write_all(b"REASON\n").unwrap();
        drop(s);
        let (bytes, end) = read_end(&mut c);
        *counts.entry(classify(&bytes, end, b"REASON")).or_insert(0) += 1;
    }
    report("tcp-close-with-unread-input", &counts);
}

fn tcp_ordered() {
    // The ordered close: reason, half-close, read what the peer sent, then release.
    let l = TcpListener::bind("127.0.0.1:0").unwrap();
    let mut counts = BTreeMap::new();
    for _ in 0..REPS {
        let (mut s, mut c) = tcp_pair(&l);
        c.write_all(&[7u8; 4096]).unwrap();
        tcp_wait_unread(&s, 4096);
        s.write_all(b"REASON\n").unwrap();
        s.shutdown(Shutdown::Write).unwrap();
        let (bytes, end) = read_end(&mut c);
        drop(c);
        let (drained, _) = read_end(&mut s);
        let class = format!(
            "{}+drained{}",
            classify(&bytes, end, b"REASON"),
            drained.len()
        );
        *counts.entry(class).or_insert(0) += 1;
    }
    report("tcp-ordered-close-with-unread-input", &counts);
}

fn tcp_backlog() {
    let mut counts = BTreeMap::new();
    for _ in 0..REPS {
        let l = TcpListener::bind("127.0.0.1:0").unwrap();
        let mut c = TcpStream::connect(l.local_addr().unwrap()).unwrap();
        c.set_read_timeout(Some(GUARD)).unwrap();
        // conformance: freed-port — the case measured is a closed listener with a client in its backlog; nothing connects to the port again
        drop(l);
        let wrote = c
            .write_all(b"HELLO\n")
            .map_or_else(|e| format!("write-{:?}", e.kind()), |()| "write-ok".into());
        let (bytes, end) = read_end(&mut c);
        *counts
            .entry(format!("{wrote}:{}", classify(&bytes, end, b"REASON")))
            .or_insert(0) += 1;
    }
    report("tcp-listener-closed-with-client-in-backlog", &counts);
}

