    pub fn timing() {
        let p = path("d");
        let _ = std::fs::remove_file(&p);
        let l = UnixListener::bind(&p).unwrap();
        let mut times = Vec::new();
        for _ in 0..TIMING_REPS {
            let mut c = UnixStream::connect(&p).unwrap();
            let (mut s, _) = l.accept().unwrap();
            let t = Instant::now();
            s.write_all(b"REASON\n").unwrap();
            s.shutdown(Shutdown::Write).unwrap();
            let mut buf = [0u8; 16];
            let n = c.read(&mut buf).unwrap();
            assert_eq!(&buf[..n], b"REASON\n");
            drop(c);
            let (_, _) = read_end(&mut s);
            times.push(t.elapsed());
        }
        percentiles("unix-close-to-release", times);
        let t = Instant::now();
        for _ in 0..TIMING_REPS {
            let mut c = UnixStream::connect(&p).unwrap();
            let (mut s, _) = l.accept().unwrap();
            s.write_all(b"REASON\n").unwrap();
            s.shutdown(Shutdown::Write).unwrap();
            let _ = read_end(&mut c);
            drop(c);
            let _ = read_end(&mut s);
        }
        println!(
            "RESULT unix-refusals-per-second reps={TIMING_REPS} per_second={:.0}",
            TIMING_REPS as f64 / t.elapsed().as_secs_f64()
        );
        let _ = std::fs::remove_file(&p);
    }
}

fn percentiles(what: &str, mut times: Vec<Duration>) {
    times.sort();
    let at = |q: f64| times[((times.len() as f64 - 1.0) * q) as usize].as_micros();
    println!(
        "RESULT {what} reps={} p50_us={} p99_us={} max_us={}",
        times.len(),
        at(0.5),
        at(0.99),
        times[times.len() - 1].as_micros()
    );
}

fn tcp_timing() {
    let l = TcpListener::bind("127.0.0.1:0").unwrap();
    let mut times = Vec::new();
    for _ in 0..TIMING_REPS {
        let (mut s, mut c) = tcp_pair(&l);
        let t = Instant::now();
        s.write_all(b"REASON\n").unwrap();
        s.shutdown(Shutdown::Write).unwrap();
        let mut buf = [0u8; 16];
        let n = c.read(&mut buf).unwrap();
        assert_eq!(&buf[..n], b"REASON\n");
        drop(c);
        let _ = read_end(&mut s);
        times.push(t.elapsed());
    }
    percentiles("tcp-close-to-release", times);
    let t = Instant::now();
    for _ in 0..TIMING_REPS {
        let (mut s, mut c) = tcp_pair(&l);
        s.write_all(b"REASON\n").unwrap();
        s.shutdown(Shutdown::Write).unwrap();
        let _ = read_end(&mut c);
        drop(c);
        let _ = read_end(&mut s);
    }
    println!(
        "RESULT tcp-refusals-per-second reps={TIMING_REPS} per_second={:.0}",
        TIMING_REPS as f64 / t.elapsed().as_secs_f64()
    );
}

#[cfg(windows)]
mod pipes {
    use super::*;
    use windows_sys::Win32::Foundation::{
        CloseHandle, ERROR_BROKEN_PIPE, ERROR_PIPE_CONNECTED, GENERIC_READ, GENERIC_WRITE,
        GetLastError, HANDLE, INVALID_HANDLE_VALUE,
    };
    use windows_sys::Win32::Storage::FileSystem::{
        CreateFileW, FILE_ATTRIBUTE_NORMAL, OPEN_EXISTING, ReadFile, WriteFile,
    };
    use windows_sys::Win32::System::Pipes::{
        ConnectNamedPipe, CreateNamedPipeW, DisconnectNamedPipe, PIPE_READMODE_BYTE,
        PIPE_REJECT_REMOTE_CLIENTS, PIPE_TYPE_BYTE, PIPE_WAIT,
    };

    const ACCESS_DUPLEX: u32 = 3;
    static NEXT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

    fn wide(s: &str) -> Vec<u16> {
        s.encode_utf16().chain(std::iter::once(0)).collect()
    }

    fn name() -> Vec<u16> {
        wide(&format!(
            r"\\.\pipe\os-end-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
        ))
    }

    fn server(name: &[u16]) -> HANDLE {
        let h = unsafe {
            CreateNamedPipeW(
                name.as_ptr(),
                ACCESS_DUPLEX,
                PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT | PIPE_REJECT_REMOTE_CLIENTS,
                1,
                65536,
                65536,
                0,
                std::ptr::null(),
            )
        };
        assert_ne!(h, INVALID_HANDLE_VALUE, "CreateNamedPipeW: {}", unsafe {
            GetLastError()
        });
        h
    }

    fn client(name: &[u16]) -> HANDLE {
        let h = unsafe {
            CreateFileW(
                name.as_ptr(),
                GENERIC_READ | GENERIC_WRITE,
                0,
                std::ptr::null(),
                OPEN_EXISTING,
                FILE_ATTRIBUTE_NORMAL,
                std::ptr::null_mut(),
            )
        };
        assert_ne!(h, INVALID_HANDLE_VALUE, "CreateFileW: {}", unsafe {
            GetLastError()
        });
        h
    }

    fn connected() -> (HANDLE, HANDLE) {
        let n = name();
        let s = server(&n);
        let c = client(&n);
        let ok = unsafe { ConnectNamedPipe(s, std::ptr::null_mut()) };
        assert!(ok != 0 || unsafe { GetLastError() } == ERROR_PIPE_CONNECTED);
        (s, c)
    }

    fn write(h: HANDLE, bytes: &[u8]) {
        let mut n = 0u32;
        assert_ne!(
            unsafe {
                WriteFile(
                    h,
                    bytes.as_ptr(),
                    bytes.len() as u32,
                    &mut n,
                    std::ptr::null_mut(),
                )
            },
            0,
            "WriteFile: {}",
            unsafe { GetLastError() }
        );
    }

    /// Reads to the end: `Ok` at ERROR_BROKEN_PIPE (the end of a pipe), else the Win32 error.
    fn read_end(h: HANDLE) -> (Vec<u8>, Result<(), u32>) {
        let mut bytes = Vec::new();
        let mut buf = [0u8; 4096];
        loop {
            let mut n = 0u32;
            let ok = unsafe {
                ReadFile(
                    h,
                    buf.as_mut_ptr(),
                    buf.len() as u32,
                    &mut n,
                    std::ptr::null_mut(),
                )
            };
            if ok == 0 {
                let e = unsafe { GetLastError() };
                return (
                    bytes,
                    if e == ERROR_BROKEN_PIPE {
                        Ok(())
                    } else {
                        Err(e)
                    },
                );
            }
            bytes.extend_from_slice(&buf[..n as usize]);
        }
    }

    fn class(bytes: &[u8], end: Result<(), u32>) -> String {
        let got = bytes.starts_with(b"REASON");
        match (got, end) {
            (true, Ok(())) => "reason+broken-pipe(109)".into(),
            (true, Err(e)) => format!("reason+win32({e})"),
            (false, Ok(())) => "broken-pipe(109)-without-reason".into(),
            (false, Err(e)) => format!("win32({e})-without-reason"),
        }
    }

    pub fn unread(disconnect: bool) {
        let mut counts = BTreeMap::new();
        for _ in 0..REPS {
            let (s, c) = connected();
            write(c, &[7u8; 4096]);
            write(s, b"REASON\n");
            unsafe {
                if disconnect {
                    DisconnectNamedPipe(s);
                }
                CloseHandle(s);
            }
            let (bytes, end) = read_end(c);
            unsafe { CloseHandle(c) };
            *counts.entry(class(&bytes, end)).or_insert(0) += 1;
        }
        report(
            if disconnect {
                "pipe-disconnectnamedpipe-with-unread-input"
            } else {
                "pipe-closehandle-with-unread-input"
            },
            &counts,
        );
    }

    /// The pending instance of a listener is closed with a client connected to it that was never accepted.
    pub fn backlog() {
        let mut counts = BTreeMap::new();
        for _ in 0..REPS {
            let n = name();
            let s = server(&n);
            let c = client(&n);
            unsafe { CloseHandle(s) };
            let mut wrote = 0u32;
            let w =
                unsafe { WriteFile(c, b"HELLO\n".as_ptr(), 6, &mut wrote, std::ptr::null_mut()) };
            let wrote = if w != 0 {
                "write-ok".to_string()
            } else {
                format!("write-win32({})", unsafe { GetLastError() })
            };
            let (bytes, end) = read_end(c);
            unsafe { CloseHandle(c) };
            *counts
                .entry(format!("{wrote}:{}", class(&bytes, end)))
                .or_insert(0) += 1;
        }
        report("pipe-listener-closed-with-client-not-accepted", &counts);
    }

    pub fn timing() {
        let mut times = Vec::new();
        for _ in 0..TIMING_REPS {
            let (s, c) = connected();
            let t = Instant::now();
            write(s, b"REASON\n");
            let mut buf = [0u8; 16];
            let mut n = 0u32;
            assert_ne!(
                unsafe { ReadFile(c, buf.as_mut_ptr(), 16, &mut n, std::ptr::null_mut()) },
                0
            );
            unsafe { CloseHandle(c) };
            let (_, _) = read_end(s);
            unsafe { CloseHandle(s) };
            times.push(t.elapsed());
        }
        percentiles("pipe-close-to-release", times);
        let t = Instant::now();
        for _ in 0..TIMING_REPS {
            let (s, c) = connected();
            write(s, b"REASON\n");
            unsafe { CloseHandle(s) };
            let _ = read_end(c);
            unsafe { CloseHandle(c) };
        }
        println!(
            "RESULT pipe-refusals-per-second reps={TIMING_REPS} per_second={:.0}",
            TIMING_REPS as f64 / t.elapsed().as_secs_f64()
        );
    }
}

fn main() {
    println!(
        "RESULT platform os={} arch={}",
        std::env::consts::OS,
        std::env::consts::ARCH
    );
    tcp_unread();
    tcp_ordered();
    tcp_backlog();
    tcp_timing();
    #[cfg(unix)]
    {
        unix::unread();
        unix::ordered();
        unix::backlog();
        unix::timing();
    }
    #[cfg(windows)]
    {
        pipes::unread(false);
        pipes::unread(true);
        pipes::backlog();
        pipes::timing();
    }
}

//! The one child loop (ADR 0001, Debrief ADR 0017 §2): a child process' `main` calls [`serve`], which
//!
//! 1. reads its [`Bootstrap`] (one JSON line on stdin, at most 64 KiB);
//! 2. connects to the host and authenticates with the token, speaking its protocol version;
//! 3. answers the host's calls with its handler until the connection closes, then returns (the process exits).
//!
//! It also ends as soon as its stdin closes ([`lifeline_closing`]): when the host stops it or dies, nothing is left behind.
//! It ends through **one** exit: the lifeline closes the connection, `main` returns and is the only `exit` (Rust guards two
//! `exit`s only on Linux; on macOS two threads ran the `atexit` handlers and a database's static destructors together).
#![cfg_attr(
    not(test),
    deny(
        clippy::let_underscore_must_use,
        clippy::let_underscore_future,
        clippy::let_underscore_untyped
    )
)]

use crate::error::IpcError;
use crate::frame::{FrameLimit, ProtocolVersion};
use crate::handshake::{Client, Connection};
use crate::launch::Bootstrap;
use crate::peer::{Handler, Peer, PeerOptions};
use crate::token::Token;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::sync::{Arc, Condvar, Mutex};
use std::time::Duration;

/// What a child's exit phase may take once its host is gone or stops it: the child's own stop budget. A parent that stops
/// a child waits at least this plus [`STOP_MARGIN`] before it kills it, so a child that stops within its budget is never
/// killed in the middle of it.
pub const STOP_BUDGET: Duration = Duration::from_millis(1250);

/// Covers the parent's kill and reap, and a child's last log lines, on top of [`STOP_BUDGET`].
pub const STOP_MARGIN: Duration = Duration::from_millis(250);

/// Who ends the process: the child's `main` (past the connection) or, after a bound, the lifeline. One claim wins, under
/// one lock, so the two never both run an exit.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Exit {
    Serving,
    MainExiting,
    LifelineExiting,
}

struct Phase {
    state: Mutex<Exit>,
    wake: Condvar,
}

static PHASE: Phase = Phase {
    state: Mutex::new(Exit::Serving),
    wake: Condvar::new(),
};

impl Phase {
    #[cfg(test)]
    fn new() -> Phase {
        Phase {
            state: Mutex::new(Exit::Serving),
            wake: Condvar::new(),
        }
    }

    /// `main` claims the exit; false when the lifeline claimed it first (this `main` must then park: the lifeline ends the
    /// process).
    fn claim_main(&self) -> bool {
        let mut st = self.state.lock().unwrap_or_else(|p| p.into_inner());
        if *st == Exit::LifelineExiting {
            return false;
        }
        *st = Exit::MainExiting;
        self.wake.notify_all();
        true
    }

    /// Waits at most `max` for `main` to claim the exit; if it has not by then, the lifeline claims it and this says true.
    fn claim_fallback(&self, max: Duration) -> bool {
        let g = self.state.lock().unwrap_or_else(|p| p.into_inner());
        let mut g = self
            .wake
            .wait_timeout_while(g, max, |st| *st == Exit::Serving)
            .map(|(g, _)| g)
            .unwrap_or_else(|p| p.into_inner().0);
        if *g == Exit::Serving {
            *g = Exit::LifelineExiting;
            return true;
        }
        false
    }
}

/// Says that this child's exit phase has begun: its `main` is past the connection and ends the process itself. A child
/// whose `main` calls [`serve`] never calls this (it does); one that runs its own loop with [`lifeline_closing`] calls it
/// when its own `wait_closed` returns. If the lifeline's fallback already took the exit (a `main` that was too late), this
/// waits at most [`STOP_MARGIN`] for the lifeline to end the process, then ends it itself.
pub fn exit_phase_begun() {
    begin_exit(&PHASE, STOP_MARGIN, || end_without_destructors(0));
}

/// `main`'s claim on `phase`; when the lifeline's fallback holds it, see [`main_lost_claim`].
fn begin_exit(phase: &Phase, wait: Duration, end: impl FnOnce()) {
    if !phase.claim_main() {
        main_lost_claim(wait, end);
    }
}

/// A `main` that finds the lifeline's fallback already took the exit: waits at most `wait` for the lifeline to end the
/// process, then calls `end` itself (never parks for good: the lifeline may have died, and this `main` holds what the child
/// holds).
fn main_lost_claim(wait: Duration, end: impl FnOnce()) {
    std::thread::park_timeout(wait);
    end();
}

/// Ends this process at once without running `atexit` handlers or static destructors (`_exit`, `TerminateProcess` on
/// itself): for a child whose exit phase overran or was taken by the lifeline's fallback. Stdio is not flushed.
#[cfg(unix)]
#[rustfmt::skip]
pub fn end_without_destructors(code: i32) -> ! { /* SAFETY: `_exit` takes no pointers and never returns. */ unsafe { libc::_exit(code) } }

/// [`end_without_destructors`] on Windows (`TerminateProcess` on this process).
#[cfg(windows)]
pub fn end_without_destructors(code: i32) -> ! {
    use windows_sys::Win32::System::Threading::{GetCurrentProcess, TerminateProcess};
    // SAFETY: the pseudo-handle of this process; `TerminateProcess` notifies no DLL.
    unsafe {
        // conformance: pid-kill — this process itself (`GetCurrentProcess`), not a pid read earlier
        TerminateProcess(GetCurrentProcess(), code as u32);
    }
    std::process::abort()
}

/// Largest bootstrap line read from stdin.
pub const MAX_BOOTSTRAP: u64 = 64 * 1024;

/// Reads the bootstrap line from `input` (at most [`MAX_BOOTSTRAP`] bytes).
pub fn read_bootstrap(input: impl Read) -> io::Result<Bootstrap> {
    let mut line = String::new();
    BufReader::new(input.take(MAX_BOOTSTRAP)).read_line(&mut line)?;
    serde_json::from_str(line.trim())
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("bad bootstrap: {e}")))
}

/// Connects to the host named in `bootstrap`, speaking `protocol`.
pub fn connect(bootstrap: &Bootstrap, protocol: ProtocolVersion) -> Result<Connection, IpcError> {
    let token = Token::from_hex(&bootstrap.token)
        .ok_or_else(|| IpcError::Auth("the bootstrap token is not 64 hex digits".into()))?;
    Client::connect(
        &bootstrap.endpoint,
        &token,
        FrameLimit::new(bootstrap.max_frame),
        protocol,
    )
}

/// The lifeline of a child that has no connection to close: when the host closes stdin (or dies), exit at once. Once the
/// peer is up use [`lifeline_closing`]: two threads in `exit` crashed the store worker.
pub fn lifeline() {
    paddock_proc::cleanup::logged(
        "starting the lifeline thread (the child will not exit when its host dies)",
        std::thread::Builder::new()
            .name("paddock-ipc-lifeline".into())
            .spawn(|| {
                let mut sink = [0u8; 256];
                while matches!(io::stdin().read(&mut sink), Ok(n) if n > 0) {}
                std::process::exit(0);
            }),
    );
}

/// The lifeline of a child whose connection is up: when the host closes stdin (or dies) it **closes the connection**, so
/// the child's `main` (past `wait_closed`) is the only exit. If the exit phase has not begun within [`STOP_BUDGET`] plus
/// [`STOP_MARGIN`] (a `main` that hangs would keep what the child holds, a database lock for one), it ends the process
/// itself. Call [`exit_phase_begun`] from a `main` that does not go through [`serve`].
pub fn lifeline_closing(peer: &Peer) {
    let peer = peer.clone();
    paddock_proc::cleanup::logged(
        "starting the lifeline thread (the child will not exit when its host dies)",
        std::thread::Builder::new()
            .name("paddock-ipc-lifeline".into())
            .spawn(move || {
                let mut sink = [0u8; 256];
                while matches!(io::stdin().read(&mut sink), Ok(n) if n > 0) {}
                let end = || end_without_destructors(0);
                lifeline_end(&peer, &PHASE, LIFELINE_WAIT, &mut io::stderr(), end);
            }),
    );
}

/// What the lifeline does once stdin is closed: close `peer`, wait for `main` to claim the exit, and if it does not within
/// the child's stop budget plus margin, say so on `err` and `end` the process.
fn lifeline_end(
    peer: &Peer,
    phase: &Phase,
    wait: Duration,
    err: &mut dyn Write,
    end: impl FnOnce(),
) {
    close_then_end(peer, phase, wait, || end_after_fallback(err, end));
}

/// The last steps of the lifeline's fallback: say why, then `end`. Nothing before `end` may stop it: a broken stderr (the
/// host is gone) or a writer that panics must not keep the process alive, holding what the child holds.
fn end_after_fallback(err: &mut dyn Write, end: impl FnOnce()) {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        writeln!(
            err,
            "the exit phase did not begin within {} ms of the host going away; ending the process (exit code 0)",
            (STOP_BUDGET + STOP_MARGIN).as_millis()
        )
        .ok();
    }))
    .ok();
    end();
}

/// How long the lifeline waits for `main` to claim the exit after the host went away.
const LIFELINE_WAIT: Duration = STOP_BUDGET.saturating_add(STOP_MARGIN);

/// Closes `peer`, then waits at most `wait` for `phase` to begin; `fallback` runs when it does not.
fn close_then_end(peer: &Peer, phase: &Phase, wait: Duration, fallback: impl FnOnce()) {
    peer.close();
    if phase.claim_fallback(wait) {
        fallback();
    }
}

/// A child process' `main`; see the module docs. `make` builds the handler once the bootstrap is known (it may look at
/// [`Bootstrap::role`] or [`Bootstrap::extra`]); `connected` runs once the connection is up (e.g. to start pushing).
pub fn serve(
    label: &str,
    protocol: ProtocolVersion,
    make: impl FnOnce(&Bootstrap) -> Arc<dyn Handler>,
    connected: impl FnOnce(&Bootstrap, &Peer),
) -> Result<(), IpcError> {
    let bootstrap = read_bootstrap(io::stdin().lock())?;
    let conn = connect(&bootstrap, protocol)?;
    let peer = Peer::start(conn, make(&bootstrap), PeerOptions::new(label))?;
    connected(&bootstrap, &peer);
    lifeline_closing(&peer);
    peer.wait_closed(None);
    exit_phase_begun();
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::endpoint;
    use crate::peer::NoCalls;
    use crate::peer::PeerOptions;

    fn a_peer() -> (Peer, endpoint::Stream) {
        let (ours, theirs) = endpoint::pair().unwrap();
        let peer = Peer::start(
            crate::handshake::Connection::raw(ours, FrameLimit::default()),
            Arc::new(NoCalls),
            PeerOptions::new("test"),
        )
        .unwrap();
        // The other end stays open for the test's length.
        (peer, theirs)
    }

    #[test]
    fn the_lifeline_closes_the_peer_and_leaves_the_exit_to_main_once_the_phase_begins() {
        let (peer, _other) = a_peer();
        let phase = Arc::new(Phase::new());
        let t = {
            let (peer, phase) = (peer.clone(), phase.clone());
            std::thread::spawn(move || {
                let mut said = Vec::new();
                lifeline_end(&peer, &phase, LIFELINE_WAIT, &mut said, || panic!("took"));
                said
            })
        };
        // `main` sees the connection close and begins the phase.
        assert!(peer.wait_closed(Some(Duration::from_secs(30))));
        assert!(phase.claim_main());
        assert!(
            t.join().unwrap().is_empty(),
            "the lifeline left the exit to main and said nothing"
        );
    }

    #[test]
    fn the_lifeline_says_why_and_ends_when_main_never_claims_the_exit() {
        let (peer, _other) = a_peer();
        let (mut said, mut ended) = (Vec::new(), false);
        let wait = Duration::from_millis(30);
        lifeline_end(&peer, &Phase::new(), wait, &mut said, || ended = true);
        assert!(ended && String::from_utf8(said).unwrap().contains("did not begin"));
    }

    #[test]
    fn a_main_that_lost_the_claim_goes_through_begin_exit() {
        let phase = Phase::new();
        assert!(phase.claim_fallback(Duration::ZERO));
        let mut ended = false;
        begin_exit(&phase, Duration::from_millis(30), || ended = true);
        assert!(ended, "a main that lost the claim ends the process itself");
        let mut kept = false;
        begin_exit(&Phase::new(), Duration::from_millis(30), || kept = true);
        assert!(!kept, "a main that wins the claim does not");
    }

    struct Broken;
    impl Write for Broken {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            Err(io::ErrorKind::BrokenPipe.into())
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    struct Panicking;
    impl Write for Panicking {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            panic!("a writer that panics")
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    #[test]
    fn the_fallback_ends_the_process_whatever_its_message_does() {
        let mut said = Vec::new();
        let mut ended = 0;
        end_after_fallback(&mut said, || ended += 1);
        assert_eq!(
            (
                ended,
                String::from_utf8(said).unwrap().contains("did not begin")
            ),
            (1, true)
        );
        // The host is gone: a broken pipe, and a writer that panics, still end it.
        end_after_fallback(&mut Broken, || ended += 1);
        end_after_fallback(&mut Panicking, || ended += 1);
        assert_eq!(ended, 3);
        Broken.flush().unwrap();
        Panicking.flush().unwrap();
    }

    #[test]
    fn a_main_that_lost_the_claim_ends_the_process_within_the_bound() {
        // On a thread, so a `main` that parked for good fails this test instead of hanging it.
        let (done, ended) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            main_lost_claim(Duration::from_millis(30), || done.send(()).unwrap())
        });
        assert!(
            ended.recv_timeout(Duration::from_secs(30)).is_ok(),
            "the late main did not end the process"
        );
    }

    #[test]
    fn the_lifeline_ends_the_process_itself_when_the_phase_never_begins() {
        let (peer, _other) = a_peer();
        let phase = Phase::new();
        let mut ended = false;
        close_then_end(&peer, &phase, Duration::from_millis(50), || ended = true);
        assert!(peer.closed().is_some(), "it closed the peer first");
        assert!(ended, "after the bound it falls back to ending the process");
        // A `main` that comes late finds the exit taken: it must park, never run a second exit.
        assert!(!phase.claim_main(), "the lifeline owns the exit now");
    }
}

//! Reading, verifying, building and extracting `.paddockplugin` files.
//!
//! A package is a zip archive with exactly these entries (directories `bin/` and `bin/<target>/` may also appear):
//!
//! ```text
//! manifest.toml                         the manifest (crate::manifest)
//! bin/<target>/<binary>[.exe]           one program per target the manifest lists
//! SHA256SUMS                            "<sha256>  <path>" for manifest.toml and every program, sorted by path
//! signature                             optional: key, public key and Ed25519 signature of the digest
//! ```
//!
//! Reading is bounded and never trusts the archive ([`Limits`]): the file size, the number of entries, each entry's size
//! (counted while reading, not taken from the header) and the total are capped; names must be exactly the listed ones (no
//! traversal, links, encrypted or duplicate entries), and each entry is hashed as it streams. Every hash must equal the
//! one in `SHA256SUMS`, which must list exactly the manifest and the programs. The **digest** is the SHA-256 of a canonical
//! text with the hash of the manifest and the hash of the `SHA256SUMS` bytes ([`Package::digest`]); the signature covers
//! that digest, so changing any byte of the manifest, the sums or a program breaks it. After installing,
//! [`verify_installed`] detects a program that changed on disk.

use crate::PackageError;
use crate::keys::{PublicKey, SecretKey, from_hex, to_hex};
use crate::manifest::{MAX_MANIFEST_BYTES, Manifest};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::io::{Read, Seek, Write};
use std::path::Path;

/// Largest package file (256 MiB).
pub const MAX_PACKAGE_BYTES: u64 = 256 << 20;
/// Largest program in a package (128 MiB).
pub const MAX_BINARY_BYTES: u64 = 128 << 20;
/// Largest total of all entries, uncompressed (512 MiB).
pub const MAX_TOTAL_BYTES: u64 = 512 << 20;
/// Largest `signature` file.
pub const MAX_SIGNATURE_BYTES: u64 = 4096;
/// Largest `SHA256SUMS` file.
pub const MAX_SUMS_BYTES: u64 = 16 * 1024;
/// Most entries (files and directories).
pub const MAX_ENTRIES: usize = 64;
/// The manifest's entry name.
pub const MANIFEST: &str = "manifest.toml";
/// The checksum list's entry name.
pub const SUMS: &str = "SHA256SUMS";
/// The signature's entry name.
pub const SIGNATURE: &str = "signature";
/// First line of the canonical digest text; its version changes with the digest's definition.
const DIGEST_HEADER: &str = "paddock-plugin-package-v1\n";

/// The size limits applied while reading a package ([`Limits::default`] is what the constants say).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Limits {
    /// Largest package file.
    pub package: u64,
    /// Largest program.
    pub binary: u64,
    /// Largest total of all entries, uncompressed.
    pub total: u64,
    /// Most entries.
    pub entries: usize,
}

impl Default for Limits {
    fn default() -> Limits {
        Limits {
            package: MAX_PACKAGE_BYTES,
            binary: MAX_BINARY_BYTES,
            total: MAX_TOTAL_BYTES,
            entries: MAX_ENTRIES,
        }
    }
}

/// The `signature` file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SignatureFile {
    /// Format of this file (1).
    pub format: u32,
    /// The signing key's id (must equal the manifest's `plugin.key`).
    pub key: String,
    /// The signing public key, text form ([`PublicKey::to_text`]).
    pub public_key: String,
    /// The Ed25519 signature of the digest, hex.
    pub signature: String,
}

/// One checksummed file of a package.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    /// Its name in the archive.
    pub path: String,
    /// Its size in bytes.
    pub size: u64,
    /// Its SHA-256.
    pub sha256: [u8; 32],
}

impl Entry {
    /// The SHA-256 as hexadecimal.
    pub fn sha256_hex(&self) -> String {
        to_hex(&self.sha256)
    }
}

/// Whether and by whom a package is signed (its signature is valid; a broken one is [`PackageError::Tampered`]).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Signature {
    /// No signature.
    Unsigned,
    /// A valid signature by `key`.
    Signed {
        /// The signing key.
        key: PublicKey,
    },
}

/// A read and verified package (the programs stay in the file; [`Package::extract`] copies one out).
#[derive(Debug, Clone)]
pub struct Package {
    /// The manifest.
    pub manifest: Manifest,
    /// The checksummed files, by name (the manifest and each program).
    pub entries: BTreeMap<String, Entry>,
    /// The signature, verified against [`Package::digest`].
    pub signature: Signature,
    digest: [u8; 32],
}

fn not_a_package(e: impl std::fmt::Display) -> PackageError {
    PackageError::NotAPackage(e.to_string())
}

fn tampered(m: &str) -> PackageError {
    PackageError::Tampered(m.to_string())
}

/// Reads `r` to its end through SHA-256, refusing more than `limit` bytes; `sink` receives the bytes.
fn hash_bounded(
    mut r: impl Read,
    limit: u64,
    what: &str,
    mut sink: impl FnMut(&[u8]) -> std::io::Result<()>,
) -> Result<(u64, [u8; 32]), PackageError> {
    let mut hasher = Sha256::new();
    let mut total = 0u64;
    let mut buf = vec![0u8; 64 * 1024];
    loop {
        let n = r
            .read(&mut buf)
            .map_err(|e| not_a_package(format!("{what}: {e}")))?;
        if n == 0 {
            break;
        }
        total += n as u64;
        if total > limit {
            return Err(PackageError::TooLarge {
                what: what.into(),
                limit,
            });
        }
        hasher.update(&buf[..n]);
        sink(&buf[..n])?;
    }
    Ok((total, hasher.finalize().into()))
}

/// The `SHA256SUMS` text for `entries`: `<sha256>  <path>` lines sorted by path.
pub fn sums_text<'a>(entries: impl IntoIterator<Item = &'a Entry>) -> String {
    let mut sorted: Vec<&Entry> = entries.into_iter().collect();
    sorted.sort_by(|a, b| a.path.cmp(&b.path));
    sorted
        .iter()
        .map(|e| format!("{}  {}\n", e.sha256_hex(), e.path))
        .collect()
}

fn parse_sums(text: &str) -> Option<BTreeMap<String, [u8; 32]>> {
    let mut out = BTreeMap::new();
    for line in text.lines() {
        let (hash, path) = line.split_once("  ")?;
        if hash.len() != 64 || hash.bytes().any(|b| b.is_ascii_uppercase()) {
            return None;
        }
        if out
            .insert(path.to_string(), from_hex::<32>(hash)?)
            .is_some()
        {
            return None;
        }
    }
    Some(out)
}

/// The canonical digest the signature covers: the hash of the manifest bytes and of the `SHA256SUMS` bytes.
pub fn digest_of(manifest: &[u8], sums: &[u8]) -> [u8; 32] {
    let text = format!(
        "{DIGEST_HEADER}manifest {}\nsums {}\n",
        to_hex(&Sha256::digest(manifest)),
        to_hex(&Sha256::digest(sums))
    );
    Sha256::digest(text.as_bytes()).into()
}

/// Whether `name` is a directory entry the layout allows (`bin/`, `bin/<target>/`).
fn allowed_dir(name: &str, m: &Manifest) -> bool {
    name == "bin/" || m.targets.iter().any(|t| name == format!("bin/{t}/"))
}

impl Package {
    /// Reads and verifies the package at `path` with the default [`Limits`]: layout, limits, manifest, checksums and
    /// signature (a signature or checksum that does not match is [`PackageError::Tampered`]). Whether the signer is trusted
    /// is [`crate::trust`]'s question.
    pub fn open(path: &Path) -> Result<Package, PackageError> {
        Package::open_with(path, &Limits::default())
    }

    /// [`Package::open`] with other limits.
    pub fn open_with(path: &Path, limits: &Limits) -> Result<Package, PackageError> {
        let file = std::fs::File::open(path)
            .map_err(|e| PackageError::Io(format!("cannot open {}: {e}", path.display())))?;
        let len = file.metadata()?.len();
        if len > limits.package {
            return Err(PackageError::TooLarge {
                what: "the package".into(),
                limit: limits.package,
            });
        }
        Package::read_with(std::io::BufReader::new(file), limits)
    }

    /// [`Package::open`] for a package in memory or any seekable reader.
    pub fn read(r: impl Read + Seek) -> Result<Package, PackageError> {
        Package::read_with(r, &Limits::default())
    }

    /// [`Package::read`] with other limits.
    pub fn read_with(r: impl Read + Seek, limits: &Limits) -> Result<Package, PackageError> {
        let mut zip = zip::ZipArchive::new(r).map_err(not_a_package)?;
        if zip.len() > limits.entries {
            return Err(PackageError::TooLarge {
                what: format!("the package's list of {} entries", zip.len()),
                limit: limits.entries as u64,
            });
        }
        // The manifest first: it says which other entries may exist.
        let manifest_bytes = {
            let mut e = zip.by_name(MANIFEST).map_err(|e| match e {
                zip::result::ZipError::FileNotFound => PackageError::MissingFile(MANIFEST.into()),
                other => not_a_package(other),
            })?;
            let mut bytes = Vec::new();
            hash_bounded(&mut e, MAX_MANIFEST_BYTES, MANIFEST, |b| {
                bytes.extend_from_slice(b);
                Ok(())
            })?;
            bytes
        };
        let manifest = Manifest::parse(
            std::str::from_utf8(&manifest_bytes)
                .map_err(|_| PackageError::InvalidManifest("not UTF-8 text".into()))?,
        )?;
        let programs: Vec<String> = manifest
            .targets
            .iter()
            .map(|t| manifest.binary_path(t))
            .collect();
        let mut entries: BTreeMap<String, Entry> = BTreeMap::new();
        let (mut sums_bytes, mut signature_bytes) = (None, None);
        let mut total = 0u64;
        for i in 0..zip.len() {
            let mut e = zip.by_index(i).map_err(not_a_package)?;
            let name = e.name().map_err(not_a_package)?.into_owned();
            if e.is_dir() {
                if allowed_dir(&name, &manifest) {
                    continue;
                }
                return Err(PackageError::UnlistedFile(name));
            }
            if e.encrypted() || e.is_symlink() {
                return Err(PackageError::UnsafeEntry(name));
            }
            let limit = if name == MANIFEST {
                MAX_MANIFEST_BYTES
            } else if name == SIGNATURE {
                MAX_SIGNATURE_BYTES
            } else if name == SUMS {
                MAX_SUMS_BYTES
            } else if programs.contains(&name) {
                limits.binary
            } else {
                return Err(
                    if name.contains("..")
                        || name.starts_with('/')
                        || name.contains('\\')
                        || name.contains(':')
                    {
                        PackageError::UnsafeEntry(name)
                    } else {
                        PackageError::UnlistedFile(name)
                    },
                );
            };
            let mut kept = Vec::new();
            let keep = name == SIGNATURE || name == SUMS;
            let (size, sha256) = hash_bounded(
                &mut e,
                limit.min(limits.total.saturating_sub(total)),
                &name,
                |b| {
                    if keep {
                        kept.extend_from_slice(b);
                    }
                    Ok(())
                },
            )?;
            total += size;
            match name.as_str() {
                SIGNATURE => signature_bytes = Some(kept),
                SUMS => sums_bytes = Some(kept),
                _ => {
                    entries.insert(
                        name.clone(),
                        Entry {
                            path: name,
                            size,
                            sha256,
                        },
                    );
                }
            }
        }
        for p in &programs {
            if !entries.contains_key(p) {
                return Err(PackageError::MissingFile(p.clone()));
            }
        }
        let sums_bytes = sums_bytes.ok_or_else(|| PackageError::MissingFile(SUMS.into()))?;
        check_sums(&entries, &sums_bytes)?;
        let digest = digest_of(&manifest_bytes, &sums_bytes);
        let signature_text = signature_bytes
            .map(|b| String::from_utf8(b).map_err(|_| tampered("the signature is not text")))
            .transpose()?;
        let signature = verify(&manifest, signature_text.as_deref(), &digest)?;
        Ok(Package {
            manifest,
            entries,
            signature,
            digest,
        })
    }

    /// The canonical digest the signature covers, hex (also what the user approved: install compares it again).
    pub fn digest(&self) -> String {
        to_hex(&self.digest)
    }

    /// The program for `target`, when the package has one.
    pub fn program(&self, target: &str) -> Option<&Entry> {
        self.entries.get(&self.manifest.binary_path(target))
    }

    /// Copies the program for `target` out of the package at `path` into `dest`, checking that it is still the program
    /// [`Package::open`] verified (the file may have changed since). Returns the program's SHA-256, which the host records to
    /// check the installed file later with [`verify_installed`].
    pub fn extract(
        &self,
        path: &Path,
        target: &str,
        dest: &Path,
    ) -> Result<[u8; 32], PackageError> {
        let Some(expected) = self.program(target).cloned() else {
            return Err(PackageError::WrongTarget {
                target: target.into(),
                supported: self.manifest.targets.join(", "),
            });
        };
        let file = std::fs::File::open(path)
            .map_err(|e| PackageError::Io(format!("cannot open {}: {e}", path.display())))?;
        let mut zip = zip::ZipArchive::new(std::io::BufReader::new(file)).map_err(not_a_package)?;
        let entry = zip
            .by_name(&expected.path)
            .map_err(|_| PackageError::MissingFile(expected.path.clone()))?;
        let mut out = std::fs::File::create(dest)
            .map_err(|e| PackageError::Io(format!("cannot write {}: {e}", dest.display())))?;
        let result = hash_bounded(entry, expected.size.max(1), &expected.path, |b| {
            out.write_all(b)
        });
        let finished = result.and_then(|r| out.sync_all().map(|()| r).map_err(PackageError::from));
        drop(out);
        match finished {
            Ok((size, sha256)) if size == expected.size && sha256 == expected.sha256 => {
                // The program runs: on Unix it needs its execute bit (only for the user; Windows has none).
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt;
                    std::fs::set_permissions(dest, std::fs::Permissions::from_mode(0o700))?;
                }
                Ok(sha256)
            }
            other => {
                let _ = std::fs::remove_file(dest);
                match other {
                    Err(e) => Err(e),
                    Ok(_) => Err(PackageError::Tampered(format!(
                        "{} changed while it was being installed",
                        expected.path
                    ))),
                }
            }
        }
    }
}

/// Whether the installed program at `installed` is still the one that was verified and installed: its SHA-256 must equal
/// `expected` (what [`Package::extract`] returned, or [`Entry::sha256`]). A changed or replaced binary is
/// [`PackageError::Tampered`], which the host treats as a quarantine-grade fault; a deleted one is
/// [`PackageError::MissingFile`]. Bounded: a file larger than [`MAX_BINARY_BYTES`] is refused without reading it all.
pub fn verify_installed(installed: &Path, expected: &[u8; 32]) -> Result<(), PackageError> {
    verify_installed_with(installed, expected, MAX_BINARY_BYTES)
}

fn verify_installed_with(
    installed: &Path,
    expected: &[u8; 32],
    max: u64,
) -> Result<(), PackageError> {
    let file = match std::fs::File::open(installed) {
        Ok(f) => f,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            return Err(PackageError::MissingFile(installed.display().to_string()));
        }
        Err(e) => {
            return Err(PackageError::Io(format!(
                "cannot open {}: {e}",
                installed.display()
            )));
        }
    };
    let (_, sha256) = hash_bounded(file, max, &installed.display().to_string(), |_| Ok(()))
        .map_err(|e| match e {
            PackageError::TooLarge { .. } => tampered(&format!(
                "{} grew beyond the size of any plugin program",
                installed.display()
            )),
            other => other,
        })?;
    if &sha256 == expected {
        Ok(())
    } else {
        Err(PackageError::Tampered(format!(
            "{} is not the program that was installed: it changed after installation",
            installed.display()
        )))
    }
}

/// `SHA256SUMS` must list exactly the checksummed files, with the hashes just computed.
fn check_sums(entries: &BTreeMap<String, Entry>, sums: &[u8]) -> Result<(), PackageError> {
    let listed = std::str::from_utf8(sums)
        .ok()
        .and_then(parse_sums)
        .ok_or_else(|| tampered("SHA256SUMS is not a list of \"<sha256>  <path>\" lines"))?;
    if listed.len() != entries.len()
        || entries
            .iter()
            .any(|(p, e)| listed.get(p) != Some(&e.sha256))
    {
        return Err(PackageError::Tampered(
            "a file does not match SHA256SUMS (the manifest or a program was changed)".into(),
        ));
    }
    Ok(())
}

/// Checks the signature file against the manifest and the digest.
fn verify(
    manifest: &Manifest,
    signature: Option<&str>,
    digest: &[u8; 32],
) -> Result<Signature, PackageError> {
    let (text, key_id) = match (signature, &manifest.key) {
        (None, None) => return Ok(Signature::Unsigned),
        (None, Some(_)) => {
            return Err(tampered(
                "the manifest names a signing key but the package has no signature",
            ));
        }
        (Some(_), None) => {
            return Err(tampered(
                "the package has a signature but its manifest names no signing key",
            ));
        }
        (Some(t), Some(k)) => (t, k),
    };
    let file: SignatureFile =
        toml::from_str(text).map_err(|_| tampered("the signature file is not valid"))?;
    if file.format != 1 {
        return Err(tampered("the signature file has an unknown format"));
    }
    let key = PublicKey::parse(&file.public_key)
        .map_err(|_| tampered("the signature's public key is not valid"))?;
    if key.id() != file.key || &file.key != key_id {
        return Err(tampered(
            "the signature's key is not the key the manifest names",
        ));
    }
    let sig =
        from_hex::<64>(&file.signature).ok_or_else(|| tampered("the signature is not valid"))?;
    if !key.verifies(digest, &sig) {
        return Err(tampered("the signature does not match the contents"));
    }
    Ok(Signature::Signed { key })
}

/// What [`build`] packs.
#[derive(Debug, Clone)]
pub struct Build<'a> {
    /// The manifest; its `key` is set from `sign` (or cleared without it).
    pub manifest: Manifest,
    /// The program for each target the manifest lists.
    pub programs: Vec<(String, &'a Path)>,
    /// Sign with this key.
    pub sign: Option<&'a SecretKey>,
}

/// Writes a package to `out`: the manifest, one program per target, `SHA256SUMS` and, with a key, the signature. The archive
/// is deterministic (fixed times, sorted entries). Returns the package's digest (hex).
pub fn build(b: Build, out: &Path) -> Result<String, PackageError> {
    build_with(b, out, MAX_BINARY_BYTES)
}

fn build_with(b: Build, out: &Path, max_binary: u64) -> Result<String, PackageError> {
    let mut manifest = b.manifest;
    manifest.key = b.sign.map(|k| k.public().id());
    let text = manifest.to_toml();
    // The result must read back: validate what is written.
    let manifest = Manifest::parse(&text)?;
    let manifest_bytes = text.into_bytes();
    let mut files: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    for t in &manifest.targets {
        let Some((_, path)) = b.programs.iter().find(|(target, _)| target == t) else {
            return Err(PackageError::MissingFile(format!("the program for {t}")));
        };
        let len = std::fs::metadata(path)
            .map_err(|e| PackageError::Io(format!("{}: {e}", path.display())))?
            .len();
        if len > max_binary {
            return Err(PackageError::TooLarge {
                what: path.display().to_string(),
                limit: max_binary,
            });
        }
        let bytes = std::fs::read(path)
            .map_err(|e| PackageError::Io(format!("{}: {e}", path.display())))?;
        files.insert(manifest.binary_path(t), bytes);
    }
    if let Some((t, _)) = b
        .programs
        .iter()
        .find(|(t, _)| !manifest.targets.contains(t))
    {
        return Err(PackageError::UnlistedFile(format!(
            "a program for {t}, which the manifest does not list"
        )));
    }
    files.insert(MANIFEST.into(), manifest_bytes.clone());
    let entries: Vec<Entry> = files
        .iter()
        .map(|(path, bytes)| Entry {
            path: path.clone(),
            size: bytes.len() as u64,
            sha256: Sha256::digest(bytes).into(),
        })
        .collect();
    let sums = sums_text(&entries).into_bytes();
    let digest = digest_of(&manifest_bytes, &sums);
    files.insert(SUMS.into(), sums);
    if let Some(key) = b.sign {
        let sig = SignatureFile {
            format: 1,
            key: key.public().id(),
            public_key: key.public().to_text(),
            signature: to_hex(&key.sign(&digest)),
        };
        files.insert(
            SIGNATURE.into(),
            toml::to_string(&sig).unwrap_or_default().into_bytes(),
        );
    }
    let tmp = out.with_extension("paddockplugin.part");
    let written = (|| -> Result<(), PackageError> {
        let file = std::fs::File::create(&tmp)
            .map_err(|e| PackageError::Io(format!("cannot write {}: {e}", tmp.display())))?;
        let mut zip = zip::ZipWriter::new(file);
        let opts = zip::write::SimpleFileOptions::default()
            .compression_method(zip::CompressionMethod::Deflated)
            .last_modified_time(zip::DateTime::default())
            .unix_permissions(0o755);
        for (name, bytes) in &files {
            zip.start_file(name.as_str(), opts)
                .map_err(|e| PackageError::Io(e.to_string()))?;
            zip.write_all(bytes)?;
        }
        zip.finish()
            .map_err(|e| PackageError::Io(e.to_string()))?
            .sync_all()?;
        Ok(())
    })();
    if let Err(e) = written {
        let _ = std::fs::remove_file(&tmp);
        return Err(e);
    }
    std::fs::rename(&tmp, out)
        .map_err(|e| PackageError::Io(format!("cannot write {}: {e}", out.display())))?;
    Ok(to_hex(&digest))
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use crate::manifest::tests::SAMPLE;

    pub(crate) const WIN: &str = "x86_64-pc-windows-msvc";
    pub(crate) const LINUX: &str = "x86_64-unknown-linux-gnu";

    /// A package of the sample manifest with tiny programs, written to a temp folder.
    pub(crate) fn sample(dir: &Path, key: Option<&SecretKey>) -> std::path::PathBuf {
        let win = dir.join("kv-lines.exe");
        let lin = dir.join("kv-lines");
        std::fs::write(&win, b"MZ windows program").unwrap();
        std::fs::write(&lin, b"\x7fELF linux program").unwrap();
        let out = dir.join("kv.paddockplugin");
        build(
            Build {
                manifest: Manifest::parse(SAMPLE).unwrap(),
                programs: vec![(WIN.into(), &win), (LINUX.into(), &lin)],
                sign: key,
            },
            &out,
        )
        .unwrap();
        out
    }

    /// Rewrites the zip at `path` with `edit` applied to its (name, bytes) list.
    pub(crate) fn rewrite(path: &Path, edit: impl FnOnce(&mut Vec<(String, Vec<u8>)>)) {
        let mut zip = zip::ZipArchive::new(std::fs::File::open(path).unwrap()).unwrap();
        let mut files = Vec::new();
        for i in 0..zip.len() {
            let mut e = zip.by_index(i).unwrap();
            let mut b = Vec::new();
            e.read_to_end(&mut b).unwrap();
            files.push((e.name().unwrap().into_owned(), b));
        }
        drop(zip);
        edit(&mut files);
        let mut w = zip::ZipWriter::new(std::fs::File::create(path).unwrap());
        for (n, b) in files {
            w.start_file(n, zip::write::SimpleFileOptions::default())
                .unwrap();
            w.write_all(&b).unwrap();
        }
        w.finish().unwrap();
    }

    type Files = Vec<(String, Vec<u8>)>;

    fn file<'a>(f: &'a mut [(String, Vec<u8>)], name: &str) -> &'a mut Vec<u8> {
        &mut f.iter_mut().find(|(n, _)| n == name).unwrap().1
    }

    #[test]
    fn a_signed_package_builds_reads_back_and_verifies() {
        let t = tempfile::tempdir().unwrap();
        let key = SecretKey::generate().unwrap();
        let p = sample(t.path(), Some(&key));
        let pkg = Package::open(&p).unwrap();
        assert_eq!(pkg.signature, Signature::Signed { key: key.public() });
        assert_eq!(
            pkg.manifest.key.as_deref(),
            Some(key.public().id().as_str())
        );
        assert_eq!(pkg.entries.len(), 3, "{:?}", pkg.entries.keys());
        assert_eq!(pkg.digest().len(), 64);
        let dest = t.path().join("out.exe");
        let sha = pkg.extract(&p, WIN, &dest).unwrap();
        assert_eq!(std::fs::read(&dest).unwrap(), b"MZ windows program");
        assert_eq!(sha, pkg.program(WIN).unwrap().sha256);
        assert_eq!(pkg.program(WIN).unwrap().sha256_hex().len(), 64);
        // Regression (Linux CI): installed programs had no execute bit and failed with "Permission denied".
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                std::fs::metadata(&dest).unwrap().permissions().mode() & 0o777,
                0o700
            );
        }
        assert_eq!(
            pkg.extract(&p, "aarch64-apple-darwin", &dest)
                .unwrap_err()
                .code(),
            "wrongTarget"
        );
        // Deterministic: the same inputs give the same bytes.
        let first = std::fs::read(&p).unwrap();
        let again = sample(t.path(), Some(&key));
        assert_eq!(std::fs::read(again).unwrap(), first);
        // The sums file is sha256sum style and lists the manifest and both programs.
        let z = std::fs::read(&p).unwrap();
        let mut zip = zip::ZipArchive::new(std::io::Cursor::new(z)).unwrap();
        let mut sums = String::new();
        zip.by_name(SUMS)
            .unwrap()
            .read_to_string(&mut sums)
            .unwrap();
        assert_eq!(sums.lines().count(), 3);
        assert!(
            sums.contains("  manifest.toml\n")
                && sums.contains(&format!("  bin/{LINUX}/kv-lines\n")),
            "{sums}"
        );
    }

    #[test]
    fn an_unsigned_package_is_unsigned() {
        let t = tempfile::tempdir().unwrap();
        let pkg = Package::open(&sample(t.path(), None)).unwrap();
        assert_eq!(pkg.signature, Signature::Unsigned);
        assert_eq!(pkg.manifest.key, None);
    }

    #[test]
    fn a_tampered_binary_fails_verification() {
        let t = tempfile::tempdir().unwrap();
        let key = SecretKey::generate().unwrap();
        let p = sample(t.path(), Some(&key));
        rewrite(&p, |f| file(f, &format!("bin/{WIN}/kv-lines.exe")).push(0));
        let e = Package::open(&p).unwrap_err();
        assert_eq!(e.code(), "tampered", "{e}");
        assert!(e.to_string().contains("SHA256SUMS"), "{e}");
        // The attacker also fixes the sums: the signature over them no longer matches.
        let p = sample(t.path(), Some(&key));
        rewrite(&p, |f| {
            file(f, &format!("bin/{LINUX}/kv-lines")).push(0);
            let entries: Vec<Entry> = f
                .iter()
                .filter(|(n, _)| n != SUMS && n != SIGNATURE)
                .map(|(n, b)| Entry {
                    path: n.clone(),
                    size: b.len() as u64,
                    sha256: Sha256::digest(b).into(),
                })
                .collect();
            *file(f, SUMS) = sums_text(&entries).into_bytes();
        });
        let e = Package::open(&p).unwrap_err();
        assert_eq!(e.code(), "tampered", "{e}");
        assert!(e.to_string().contains("signature does not match"), "{e}");
    }

    #[test]
    fn tampering_with_the_manifest_the_sums_or_the_signature_is_detected() {
        let t = tempfile::tempdir().unwrap();
        let key = SecretKey::generate().unwrap();
        let tamper = |edit: &dyn Fn(&mut Files), says: &str| {
            let p = sample(t.path(), Some(&key));
            rewrite(&p, edit);
            let e = Package::open(&p).unwrap_err();
            assert_eq!(e.code(), "tampered", "{e}");
            assert!(e.to_string().contains(says), "{e}");
        };
        tamper(
            &|f| {
                let m = file(f, MANIFEST);
                *m = String::from_utf8(m.clone())
                    .unwrap()
                    .replace("1.2.0", "9.9.9")
                    .into_bytes();
            },
            "SHA256SUMS",
        );
        // Removing the signature but keeping the manifest's key.
        tamper(&|f| f.retain(|(n, _)| n != SIGNATURE), "no signature");
        // A signature by another key, with the manifest pointing at it: still the wrong signature.
        tamper(
            &|f| {
                let s = file(f, SIGNATURE);
                let mut sf: SignatureFile =
                    toml::from_str(std::str::from_utf8(s).unwrap()).unwrap();
                sf.public_key = SecretKey::generate().unwrap().public().to_text();
                *s = toml::to_string(&sf).unwrap().into_bytes();
            },
            "not the key the manifest names",
        );
        // The key names match but the signature bytes are another key's.
        tamper(
            &|f| {
                let s = file(f, SIGNATURE);
                let mut sf: SignatureFile =
                    toml::from_str(std::str::from_utf8(s).unwrap()).unwrap();
                sf.signature = to_hex(&SecretKey::generate().unwrap().sign(b"x"));
                *s = toml::to_string(&sf).unwrap().into_bytes();
            },
            "signature does not match",
        );
        let edit_sig = |edit: fn(&mut SignatureFile)| {
            move |f: &mut Vec<(String, Vec<u8>)>| {
                let s = file(f, SIGNATURE);
                let mut sf: SignatureFile =
                    toml::from_str(std::str::from_utf8(s).unwrap()).unwrap();
                edit(&mut sf);
                *s = toml::to_string(&sf).unwrap().into_bytes();
            }
        };
        tamper(&edit_sig(|s| s.format = 2), "unknown format");
        tamper(
            &edit_sig(|s| s.public_key = "junk".into()),
            "public key is not valid",
        );
        tamper(
            &edit_sig(|s| s.signature = "00".into()),
            "signature is not valid",
        );
        tamper(
            &|f| *file(f, SIGNATURE) = b"not = [toml".to_vec(),
            "signature file is not valid",
        );
        tamper(&|f| *file(f, SIGNATURE) = vec![0xff, 0xfe], "not text");
        // A signature with an unsigned manifest.
        let p = sample(t.path(), None);
        let signed = sample(
            &paddock_env::winpath::real_verbatim(&t.path().join("..")).unwrap(),
            Some(&key),
        );
        let mut sig = Vec::new();
        zip::ZipArchive::new(std::fs::File::open(&signed).unwrap())
            .unwrap()
            .by_name(SIGNATURE)
            .unwrap()
            .read_to_end(&mut sig)
            .unwrap();
        rewrite(&p, |f| f.push((SIGNATURE.into(), sig)));
        assert!(
            Package::open(&p)
                .unwrap_err()
                .to_string()
                .contains("names no signing key")
        );
    }

    #[test]
    fn bad_sums_files_are_refused() {
        let t = tempfile::tempdir().unwrap();
        for (edit, says) in [
            (
                Box::new(|s: &str| s.replace("  ", " ")) as Box<dyn Fn(&str) -> String>,
