        );
        assert_eq!(big.unwrap_err().code(), "tooLarge");
        // An invalid manifest never reaches the archive.
        let mut bad = m.clone();
        bad.binary = "../x".into();
        let e = build(
            Build {
                manifest: bad,
                programs: vec![],
                sign: None,
            },
            &t.path().join("d.paddockplugin"),
