#[test]
fn a_contract_is_routed_by_namespace_and_refuses_a_newer_minor() {
    let h = host();
    assert_eq!(
        h.extension::<FixtureContract>(1, &FixtureRequest::Add(2, 3))
            .unwrap(),
        FixtureReply::Sum(5)
    );
    assert_eq!(
        h.extension::<FixtureContract>(0, &FixtureRequest::Echo("e".into()))
            .unwrap(),
        FixtureReply::Text("e".into())
    );
    assert_eq!(
        h.extension::<FixtureContract>(1, &FixtureRequest::Twice("ab".into()))
            .unwrap(),
        FixtureReply::Text("abab".into())
    );
    // The platform never decoded the body: the plugin's own typed failure and panic arrive as they are.
    let failed = h.extension::<FixtureContract>(1, &FixtureRequest::Fail);
    assert_eq!(
        (
            remote(&failed).code.as_str(),
            remote(&failed).message.as_str()
        ),
        ("fixture.failed", "the fixture's contract failed on purpose")
    );
    assert_eq!(
        remote(&h.extension::<FixtureContract>(1, &FixtureRequest::Panic)).code,
        codes::PANIC
    );
    // A newer minor than the plugin was built for: it must be updated, and the text says so.
    let newer = h.extension::<FixtureContract>(2, &FixtureRequest::Add(1, 1));
    assert_eq!(remote(&newer).code, codes::VERSION);
    assert_eq!(
        remote(&newer).message,
        "plugin net.example.fixture was built for an older contract (\"paddock.fixture.v1\" version 1, asked for 2); update it"
    );
    assert_eq!(
        h.extension::<FixtureContract>(1, &FixtureRequest::Big(10))
            .unwrap(),
        FixtureReply::Bytes(vec![1; 10])
    );
}

