};

/// `ERROR_NOT_ALL_ASSIGNED`: `AdjustTokenPrivileges` succeeded but the token does not hold the privilege.
const ERROR_NOT_ALL_ASSIGNED: u32 = 1300;
/// `RM_INVALID_TS_SESSION`.
const RM_INVALID_TS_SESSION: u32 = u32::MAX;

fn wide(s: &OsStr) -> Vec<u16> {
    s.encode_wide().chain(std::iter::once(0)).collect()
}

fn from_wide(buf: &[u16]) -> String {
    let end = buf.iter().position(|&c| c == 0).unwrap_or(buf.len());
    String::from_utf16_lossy(&buf[..end])
}

/// The real machine. It remembers whether `SeDebugPrivilege` was already enabled when it was asked to enable it, and puts the
/// token back in that state (an elevated shell may have it on).
#[derive(Debug, Default)]
pub struct WindowsMachine {
    was_enabled: bool,
}

/// A Restart Manager session over some files, ended on drop.
struct RmSession(u32);

impl RmSession {
    fn start(files: &[PathBuf]) -> Result<RmSession, StopError> {
        let mut handle = 0u32;
        let mut key = [0u16; CCH_RM_SESSION_KEY as usize + 1];
        // SAFETY: both out-pointers are valid for the sizes the API documents.
        let rc = unsafe { RmStartSession(&raw mut handle, 0, key.as_mut_ptr()) };
        if rc != ERROR_SUCCESS {
            return Err(StopError::RestartManager {
                call: "RmStartSession",
                code: rc,
            });
        }
        let session = RmSession(handle);
        let names: Vec<Vec<u16>> = files.iter().map(|f| wide(f.as_os_str())).collect();
        let ptrs: Vec<*const u16> = names.iter().map(|n| n.as_ptr()).collect();
        let count = u32::try_from(ptrs.len()).unwrap_or(u32::MAX);
        // SAFETY: `ptrs` points at `count` NUL-terminated wide strings that outlive the call.
        let rc = unsafe {
            RmRegisterResources(
                handle,
                count,
                ptrs.as_ptr(),
                0,
                std::ptr::null(),
                0,
                std::ptr::null(),
            )
        };
        if rc != ERROR_SUCCESS {
            return Err(StopError::RestartManager {
                call: "RmRegisterResources",
                code: rc,
            });
        }
        Ok(session)
    }

    fn list(&self) -> Result<Vec<RmProcess>, StopError> {
        let mut needed = 0u32;
        let mut have = 0u32;
        let mut reasons = 0u32;
        // SAFETY: a size query: no buffer, the counters are valid.
        let rc = unsafe {
            RmGetList(
                self.0,
                &raw mut needed,
                &raw mut have,
                std::ptr::null_mut(),
                &raw mut reasons,
            )
        };
        if rc == ERROR_SUCCESS && needed == 0 {
            return Ok(Vec::new());
        }
        if rc != ERROR_MORE_DATA && rc != ERROR_SUCCESS {
            return Err(StopError::RestartManager {
                call: "RmGetList",
                code: rc,
            });
        }
        // The list can grow between the two calls; ask again with room to spare, a few times.
        let mut room = needed.saturating_add(8);
        for _ in 0..5 {
            // SAFETY: an all-zero RM_PROCESS_INFO is a valid (empty) value.
            let mut infos: Vec<RM_PROCESS_INFO> =
                vec![unsafe { std::mem::zeroed() }; room as usize];
            have = room;
            // SAFETY: `infos` has `have` writable entries.
            let rc = unsafe {
                RmGetList(
                    self.0,
                    &raw mut needed,
                    &raw mut have,
                    infos.as_mut_ptr(),
                    &raw mut reasons,
                )
            };
            if rc == ERROR_MORE_DATA {
                room = needed.saturating_add(8);
                continue;
            }
            if rc != ERROR_SUCCESS {
                return Err(StopError::RestartManager {
                    call: "RmGetList",
                    code: rc,
                });
            }
            return Ok(infos
                .iter()
                .take(have as usize)
                .filter_map(|i| {
                    let ft = (u64::from(i.Process.ProcessStartTime.dwHighDateTime) << 32)
                        | u64::from(i.Process.ProcessStartTime.dwLowDateTime);
                    let started = crate::identity::micros_from_filetime(ft)?;
                    Some(RmProcess {
                        id: ProcessId::new(i.Process.dwProcessId, StartTime::from_micros(started)),
                        session: (i.TSSessionId != RM_INVALID_TS_SESSION).then_some(i.TSSessionId),
                        name: from_wide(&i.strAppName),
                        image: image_name_of(i.Process.dwProcessId),
                    })
                })
                .collect());
        }
        Err(StopError::RestartManager {
            call: "RmGetList",
            code: ERROR_MORE_DATA,
        })
    }
}

impl Drop for RmSession {
    fn drop(&mut self) {
        // SAFETY: the handle came from RmStartSession and is ended once.
        unsafe { RmEndSession(self.0) };
    }
}

/// The program's file name of `pid`, read by opening the pid again (needs the privilege for another user's process); the
/// caller holds no handle on it, so only a name that is compared against listed images is taken from here, never an identity.
fn image_name_of(pid: u32) -> Option<String> {
    // SAFETY: plain values; the handle is closed below.
    let h = unsafe { OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, pid) };
    if h.is_null() {
        return None;
    }
    let mut buf = [0u16; 1024];
    let mut len = buf.len() as u32;
    // SAFETY: `buf` is writable for `len` characters.
    let ok = unsafe { QueryFullProcessImageNameW(h, 0, buf.as_mut_ptr(), &raw mut len) } != 0;
    // SAFETY: opened above.
    unsafe { CloseHandle(h) };
    ok.then(|| from_wide(&buf[..len as usize]))
        .and_then(|p| p.rsplit(['\\', '/']).next().map(str::to_owned))
}

/// A process held open by handle, closed on drop.
pub struct HeldProcess {
    handle: HANDLE,
    id: ProcessId,
    image: Option<PathBuf>,
    session: Option<u32>,
}

impl Held for HeldProcess {
    fn id(&self) -> ProcessId {
        self.id
    }
    fn image(&self) -> Option<&Path> {
        self.image.as_deref()
    }
    fn session(&self) -> Option<u32> {
        self.session
    }
}

impl Drop for HeldProcess {
    fn drop(&mut self) {
        // SAFETY: the handle was opened by `open` and is closed once.
        unsafe { CloseHandle(self.handle) };
    }
}

/// Whether the token holds `luid` enabled now. (`AdjustTokenPrivileges` reports the previous state only for a privilege it
/// changed, so asking it is no way to learn whether one was already on.)
fn privilege_is_enabled(token: HANDLE, luid: &windows_sys::Win32::Foundation::LUID) -> bool {
    use windows_sys::Win32::Security::{GetTokenInformation, TokenPrivileges};
    let mut needed = 0u32;
    // SAFETY: a size query: no buffer.
    unsafe {
        GetTokenInformation(
            token,
            TokenPrivileges,
            std::ptr::null_mut(),
            0,
            &raw mut needed,
        )
    };
    if needed == 0 {
        return false;
    }
    let mut buf = vec![0u8; needed as usize];
    // SAFETY: `buf` has `needed` writable bytes.
    if unsafe {
        GetTokenInformation(
            token,
            TokenPrivileges,
            buf.as_mut_ptr().cast(),
            needed,
            &raw mut needed,
        )
    } == 0
    {
        return false;
    }
    // SAFETY: the buffer starts with a TOKEN_PRIVILEGES header followed by `PrivilegeCount` entries (unaligned reads).
    unsafe {
        let count = std::ptr::read_unaligned(buf.as_ptr().cast::<u32>()) as usize;
        let first = buf.as_ptr().add(4).cast::<LUID_AND_ATTRIBUTES>();
        (0..count).any(|i| {
            let e = std::ptr::read_unaligned(first.add(i));
            e.Luid.LowPart == luid.LowPart
                && e.Luid.HighPart == luid.HighPart
                && e.Attributes & SE_PRIVILEGE_ENABLED != 0
        })
    }
}

/// Sets `SeDebugPrivilege` in this process's token on or off; returns whether it was enabled before.
fn token_privilege(enable: bool) -> Result<bool, StopError> {
    let mut token: HANDLE = std::ptr::null_mut();
    // SAFETY: the current-process pseudo handle and a valid out-pointer.
    if unsafe {
        OpenProcessToken(
            GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY,
            &raw mut token,
        )
    } == 0
    {
        return Err(StopError::Privilege(unsafe { GetLastError() }));
    }
    let name = wide(OsStr::new("SeDebugPrivilege"));
    // SAFETY: an all-zero LUID is valid; the name is NUL-terminated.
    let mut luid = unsafe { std::mem::zeroed() };
    let result =
        if unsafe { LookupPrivilegeValueW(std::ptr::null(), name.as_ptr(), &raw mut luid) } == 0 {
            Err(StopError::Privilege(unsafe { GetLastError() }))
        } else {
            let tp = TOKEN_PRIVILEGES {
                PrivilegeCount: 1,
                Privileges: [LUID_AND_ATTRIBUTES {
                    Luid: luid,
                    Attributes: if enable { SE_PRIVILEGE_ENABLED } else { 0 },
                }],
            };
            let was_enabled = privilege_is_enabled(token, &luid);
            // SAFETY: `tp` is one fully initialised privilege entry; the token has TOKEN_ADJUST_PRIVILEGES.
            let ok = unsafe {
                AdjustTokenPrivileges(token, 0, &tp, 0, std::ptr::null_mut(), std::ptr::null_mut())
            };
            let last = unsafe { GetLastError() };
            if ok == 0 {
                Err(StopError::Privilege(last))
            } else if last == ERROR_NOT_ALL_ASSIGNED {
                // Succeeded, but the token does not hold the privilege (a policy removed it).
                Err(StopError::Privilege(ERROR_NOT_ALL_ASSIGNED))
            } else {
                Ok(was_enabled)
            }
        };
    // SAFETY: the token handle was opened above.
    unsafe { CloseHandle(token) };
    result
}

impl Machine for WindowsMachine {
    type Held = HeldProcess;

    fn rm_list(&mut self, files: &[PathBuf]) -> Result<Vec<RmProcess>, StopError> {
        RmSession::start(files)?.list()
    }

    fn processes(&mut self) -> Result<Vec<Candidate>, StopError> {
        // SAFETY: a plain snapshot call.
        let snap = unsafe { CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0) };
        if snap == INVALID_HANDLE_VALUE {
            return Err(StopError::Table(unsafe { GetLastError() }));
        }
        // SAFETY: an all-zero PROCESSENTRY32W with dwSize set is what the API wants.
        let mut e: PROCESSENTRY32W = unsafe { std::mem::zeroed() };
        e.dwSize = std::mem::size_of::<PROCESSENTRY32W>() as u32;
        let mut out = Vec::new();
        // SAFETY: `snap` is a valid snapshot and `e` is sized.
        let mut ok = unsafe { Process32FirstW(snap, &raw mut e) };
        while ok != 0 {
            out.push(Candidate {
                pid: e.th32ProcessID,
                image: from_wide(&e.szExeFile),
            });
            // SAFETY: as above.
            ok = unsafe { Process32NextW(snap, &raw mut e) };
        }
        // SAFETY: the snapshot handle was created above.
        unsafe { CloseHandle(snap) };
        Ok(out)
    }

    fn enable_privilege(&mut self) -> Result<(), StopError> {
        self.was_enabled = token_privilege(true)?;
        Ok(())
    }

    fn drop_privilege(&mut self) {
        // Back to the state it was in: a token that had it enabled keeps it.
        if !self.was_enabled
            && let Err(e) = token_privilege(false)
        {
            log::warn!("SeDebugPrivilege could not be disabled again: {e}");
        }
    }

    fn open(&mut self, pid: u32, for_end: bool) -> Result<HeldProcess, OpenFailure> {
        let access = PROCESS_QUERY_LIMITED_INFORMATION
            | PROCESS_SYNCHRONIZE
            | if for_end { PROCESS_TERMINATE } else { 0 };
        // SAFETY: plain values; the handle is owned by the returned HeldProcess.
        let handle = unsafe { OpenProcess(access, 0, pid) };
        if handle.is_null() {
            let code = unsafe { GetLastError() };
            return Err(if code == ERROR_INVALID_PARAMETER {
                OpenFailure::Gone
            } else {
                OpenFailure::Denied(code)
            });
        }
        let Some(started) = crate::sys::creation_time(handle) else {
            // The error code first: CloseHandle may overwrite it.
            let code = unsafe { GetLastError() };
            // SAFETY: opened above.
            unsafe { CloseHandle(handle) };
            return Err(OpenFailure::Denied(code));
        };
        let mut buf = [0u16; 1024];
        let mut len = buf.len() as u32;
        // SAFETY: `buf` is writable for `len` characters.
        let image =
            (unsafe { QueryFullProcessImageNameW(handle, 0, buf.as_mut_ptr(), &raw mut len) } != 0)
                .then(|| PathBuf::from(from_wide(&buf[..len as usize])));
        let mut session = 0u32;
        // SAFETY: a valid out-pointer.
        let session =
            (unsafe { ProcessIdToSessionId(pid, &raw mut session) } != 0).then_some(session);
        Ok(HeldProcess {
            handle,
            id: ProcessId::new(pid, started),
            image,
            session,
        })
    }

    fn request_close(&mut self, held: &HeldProcess) -> bool {
        struct Ask {
            pid: u32,
            asked: bool,
        }
        unsafe extern "system" fn each(hwnd: HWND, lparam: LPARAM) -> i32 {
            // SAFETY: `lparam` is the address of the `Ask` on the caller's stack, alive for the whole enumeration.
            let ask = unsafe { &mut *(lparam as *mut Ask) };
            let mut pid = 0u32;
            // SAFETY: a window handle from the enumeration and a valid out-pointer.
            unsafe { GetWindowThreadProcessId(hwnd, &raw mut pid) };
            // SAFETY: as above; a message posted to a window that vanished is ignored by the system.
            if pid == ask.pid && unsafe { PostMessageW(hwnd, WM_CLOSE, 0, 0) } != 0 {
                ask.asked = true;
            }
            1
        }
        let mut ask = Ask {
            pid: held.id.pid(),
            asked: false,
        };
        // SAFETY: the callback only touches `ask`, which outlives the call.
        unsafe { EnumWindows(Some(each), &raw mut ask as LPARAM) };
        ask.asked
    }

    fn terminate(&mut self, held: &HeldProcess) -> Result<(), StopError> {
        // SAFETY: the handle was opened with PROCESS_TERMINATE.
        // conformance: pid-kill — a process handle held since the identity (pid and start time) was verified: no pid is looked up here
        if unsafe { TerminateProcess(held.handle, 1) } == 0 {
            return Err(StopError::Terminate(unsafe { GetLastError() }));
        }
        Ok(())
    }

    fn wait_exit(&mut self, held: &HeldProcess, bound: Duration) -> (bool, Duration) {
        let ms = u32::try_from(bound.as_millis()).unwrap_or(u32::MAX - 1);
        let t = std::time::Instant::now();
        // SAFETY: the handle was opened with SYNCHRONIZE.
        let exited = unsafe { WaitForSingleObject(held.handle, ms) == WAIT_OBJECT_0 };
        (exited, t.elapsed())
    }
}

/// The pids of the processes that started `own`, nearest first, as far as the parent links hold: a parent counts only if it
/// started before its child (a pid freed and reused is newer than the process that names it as its parent).
fn ancestors_of(own: ProcessId) -> Vec<u32> {
    let Some(table) = crate::sys::process_parents() else {
        return Vec::new();
    };
    let mut out = Vec::new();
    let (mut pid, mut started) = (own.pid(), own.started());
    while let Some(&(_, parent)) = table.iter().find(|(p, _)| *p == pid) {
        let Some(id) = ProcessId::of(parent) else {
            break;
        };
        if id.started() >= started || out.contains(&parent) || out.len() >= 16 {
            break;
        }
        out.push(parent);
        (pid, started) = (parent, id.started());
    }
    out
}

/// The session of this process.
fn own_session_id() -> Option<u32> {
    let mut id = 0u32;
    // SAFETY: a valid out-pointer.
    (unsafe { ProcessIdToSessionId(std::process::id(), &raw mut id) } != 0).then_some(id)
}

/// Stops every listed program that runs from `dir` in any session, as this process (which it never ends), with the real
/// Windows machine. `images` are file names in `dir`; the calling program's own file is left out of the Restart Manager
/// registration.
pub fn stop_all_here(dir: &Path, images: &[String], bounds: &Bounds) -> StopReport {
    // One canonical folder (long names, no 8.3 form, no verbatim prefix needed by the callers): the folder of a running
    // program is read from its handle in that form, and the two are compared by components.
    #[expect(
        clippy::disallowed_methods,
        reason = "Windows only: the folder is compared by components through installed.rs `parts` (which handles the verbatim prefix), not text-stripped; it moves to winpath in WP-P2 (row 12) of the ADR 0021 amendment 2026-11-11"
    )]
    let dir = std::fs::canonicalize(dir).unwrap_or_else(|_| dir.to_path_buf());
    let own = ProcessId::of(std::process::id())
        .unwrap_or_else(|| ProcessId::new(std::process::id(), StartTime::from_micros(0)));
    let own_image = std::env::current_exe().ok();
    let own_session = own_session_id();
    let spare = ancestors_of(own);
    let req = Request {
        dir: &dir,
        images,
        own,
        own_image: own_image.as_deref(),
        own_session,
        spare: &spare,
    };
    super::stop_all(&mut WindowsMachine::default(), &req, bounds)
}

//! Windows: every supervised child goes into a job object of its own with `JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE` (plan
//! X54). The job's handle lives in the [`Supervised`](crate::Supervised) value, so when it is dropped, or when the app
//! exits or crashes and Windows closes its handles, every process in the job ends: the child and the helpers it started,
//! even those that left its process tree (an orphan's parent pid no longer leads back to the child, so `taskkill /T`
//! cannot find it, but the job still holds it). From Dyno's `dyno-ipc` `job.rs`.
#![cfg_attr(
    not(test),
    deny(
        clippy::let_underscore_must_use,
        clippy::let_underscore_future,
        clippy::let_underscore_untyped
    )
)]
#![allow(unsafe_code)]

use std::io;
use std::os::windows::io::{AsRawHandle, FromRawHandle, OwnedHandle};
use std::process::Child;
use std::ptr::null;
use windows_sys::Win32::Foundation::ERROR_MORE_DATA;
use windows_sys::Win32::System::JobObjects::{
    AssignProcessToJobObject, CreateJobObjectW, JOB_OBJECT_LIMIT_DIE_ON_UNHANDLED_EXCEPTION,
    JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE, JOB_OBJECT_LIMIT_PROCESS_MEMORY,
    JOBOBJECT_BASIC_PROCESS_ID_LIST, JOBOBJECT_EXTENDED_LIMIT_INFORMATION,
    JobObjectBasicProcessIdList, JobObjectExtendedLimitInformation, QueryInformationJobObject,
    SetInformationJobObject, TerminateJobObject,
};

/// A kill-on-close job; closing its handle (on drop) ends every process in it.
pub(crate) struct Job(OwnedHandle);

/// How one query of the job's id list ended.
pub(crate) enum Query {
    /// The list fit the buffer.
    Done,
    /// More processes than the buffer holds (the buffer has the first ones).
    MoreData,
    /// The job could not be queried.
    Failed,
}

/// Reads the id list through `query`, which fills the given buffer (header, then ids). A full buffer is not a failure: the
/// ids that were filled count (a tree of more than [`crate::MAX_TREE`] processes is measured by its first ones).
pub(crate) fn pids_with(query: impl FnOnce(&mut [u64]) -> Query) -> Option<Vec<u32>> {
    // The list header is two u32 and then the ids (usize); a u64 buffer is aligned for it.
    let mut buf = vec![0u64; 1 + crate::MAX_TREE];
    match query(&mut buf) {
        Query::Failed => return None,
        Query::Done | Query::MoreData => {}
    }
    let list = buf.as_ptr().cast::<JOBOBJECT_BASIC_PROCESS_ID_LIST>();
    // SAFETY: the buffer is at least as large and as aligned as the list header; the query wrote the count of ids it filled,
    // and the count is clamped to the room the buffer has.
    unsafe {
        let n = ((*list).NumberOfProcessIdsInList as usize).min(crate::MAX_TREE);
        let ids = (&raw const (*list).ProcessIdList).cast::<usize>();
        Some((0..n).map(|i| *ids.add(i) as u32).collect())
    }
}

impl Job {
    /// The ids of the processes in the job (the child and every helper it started, even orphans), read from the job itself:
    /// no walk of the machine's process list. At most [`crate::MAX_TREE`] ids; `None` when the job cannot be queried.
    pub(crate) fn pids(&self) -> Option<Vec<u32>> {
        let handle = self.0.as_raw_handle();
        pids_with(|buf| {
            // SAFETY: `buf` is a live u64 buffer of the size passed; the job handle is valid while `self` lives.
            let ok = unsafe {
                QueryInformationJobObject(
                    handle,
                    JobObjectBasicProcessIdList,
                    buf.as_mut_ptr().cast(),
                    std::mem::size_of_val(buf) as u32,
                    std::ptr::null_mut(),
                )
            };
            if ok != 0 {
                Query::Done
            } else if io::Error::last_os_error().raw_os_error() == Some(ERROR_MORE_DATA as i32) {
                Query::MoreData
            } else {
                Query::Failed
            }
        })
    }

    /// The members of the job by identity: each id of [`Job::pids`] whose process, opened by handle, is still in the job
    /// (a member that ended and whose pid was handed on is left out). `None` when the job cannot be queried.
    pub(crate) fn members(&self) -> Option<Vec<crate::ProcessId>> {
        let job = self.0.as_raw_handle();
        Some(
            self.pids()?
                .into_iter()
                .filter_map(|pid| crate::sys::identity_in_job(pid, job))
                .collect(),
        )
    }

    /// Puts `child` into a new kill-on-close job. Processes it starts afterwards join the job too (nested jobs: Windows 8
    /// and later, also when the app itself runs in a job).
    pub(crate) fn assign(child: &Child, commit_limit: Option<u64>) -> io::Result<Job> {
        // SAFETY: no attributes, no name; the handle is owned below.
        let h = unsafe { CreateJobObjectW(null(), null()) };
        if h.is_null() {
            return Err(io::Error::last_os_error());
        }
        // SAFETY: a fresh, valid handle nobody else owns.
        let job = unsafe { OwnedHandle::from_raw_handle(h) };
        let mut info = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        // A crash in the child ends it rather than waiting on a Windows Error Reporting dialog nobody sees.
        info.BasicLimitInformation.LimitFlags =
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE | JOB_OBJECT_LIMIT_DIE_ON_UNHANDLED_EXCEPTION;
        if let Some(limit) = commit_limit {
            // An allocation past the limit fails in the child at once (Rust aborts it), however fast it allocates.
            info.BasicLimitInformation.LimitFlags |= JOB_OBJECT_LIMIT_PROCESS_MEMORY;
            info.ProcessMemoryLimit = usize::try_from(limit).unwrap_or(usize::MAX);
        }
        // SAFETY: `info` is a valid structure of the size passed, for the class passed.
        let set = unsafe {
            SetInformationJobObject(
                job.as_raw_handle(),
                JobObjectExtendedLimitInformation,
                (&raw const info).cast(),
                std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
            )
        };
        if set == 0 {
            return Err(io::Error::last_os_error());
        }
        // SAFETY: both handles are valid; the child's stays open while `child` lives.
        if unsafe { AssignProcessToJobObject(job.as_raw_handle(), child.as_raw_handle()) } == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Job(job))
    }
}

impl Job {
    /// Ends every process in the job now, through the job's handle: no pid is looked up, so none can have been handed on
    /// (ADR 0033). The job stays open; closing it later ends whatever joined since.
    pub(crate) fn terminate(&self) {
        // SAFETY: a valid job handle owned by `self`.
        // conformance: pid-kill — a job handle this value owns: no pid is looked up
        if unsafe { TerminateJobObject(self.0.as_raw_handle(), 1) } == 0 {
            log::warn!(
                "Could not end the job of a child: {}",
                io::Error::last_os_error()
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Writes a list header with `count` ids that are `1..=count` (as the kernel does) into `buf`.
    fn fill(buf: &mut [u64], count: usize) {
        buf[0] = (count as u64) << 32 | count as u64;
        for (i, slot) in buf.iter_mut().skip(1).take(count).enumerate() {
            *slot = i as u64 + 1;
        }
    }

    #[test]
    fn a_full_buffer_gives_the_ids_that_were_filled_and_a_failure_gives_none() {
        let ids = pids_with(|b| {
            fill(b, crate::MAX_TREE);
            Query::MoreData
        })
        .unwrap();
        assert_eq!(ids.len(), crate::MAX_TREE);
        assert_eq!(ids.first(), Some(&1));
        let few = pids_with(|b| {
            fill(b, 3);
            Query::Done
        });
        assert_eq!(few, Some(vec![1, 2, 3]));
        assert_eq!(pids_with(|_| Query::Failed), None);
    }
}

//! A supervised child: its whole process tree is ended on drop, on [`Supervised::terminate`] and when it exceeds a
//! memory cap, so nothing leaks. A [`Registry`] knows every supervised tree, so [`end_all`] can end them at shutdown or
//! in a panic hook even when the owners never get to drop them.
#![cfg_attr(
    not(test),
    deny(
        clippy::let_underscore_must_use,
        clippy::let_underscore_future,
        clippy::let_underscore_untyped
    )
)]

use crate::identity::ProcessId;
use crate::tree::{self, Terminated, kill_child_tree, kill_tree};
use crate::usage;
use crate::watch::{MemoryEvent, MemoryListener, MemoryWatch, Verdict};
use std::collections::BTreeSet;
use std::process::{Child, ChildStderr, ChildStdin, ChildStdout, Command, ExitStatus};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::mpsc::{self, RecvTimeoutError};
use std::sync::{Arc, Mutex, MutexGuard, OnceLock};
use std::time::{Duration, Instant};

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|p| p.into_inner())
}

/// The roots of the trees that are being supervised, by identity (a root that ended and was reaped has a pid the OS may
/// hand on; [`Registry::end_all`] leaves such a pid alone). Cheap to clone; clones share the list.
#[derive(Debug, Clone, Default)]
pub struct Registry(Arc<Mutex<BTreeSet<ProcessId>>>);

impl Registry {
    /// An empty registry.
    pub fn new() -> Registry {
        Registry::default()
    }

    fn add(&self, id: ProcessId) {
        lock(&self.0).insert(id);
    }

    fn remove(&self, id: ProcessId) {
        lock(&self.0).remove(&id);
    }

    /// The pids of the roots of the trees still supervised.
    pub fn pids(&self) -> Vec<u32> {
        lock(&self.0).iter().map(|id| id.pid()).collect()
    }

    /// Ends every registered tree now and forgets them; returns how many were registered. The owning [`Supervised`]
    /// values still reap their children when they are dropped or waited for.
    pub fn end_all(&self) -> usize {
        let roots = std::mem::take(&mut *lock(&self.0));
        for root in &roots {
            kill_tree(*root);
        }
        roots.len()
    }
}

/// The registry [`Supervised::spawn`] uses.
pub fn global_registry() -> &'static Registry {
    static GLOBAL: OnceLock<Registry> = OnceLock::new();
    GLOBAL.get_or_init(Registry::new)
}

/// Ends every tree supervised through [`Supervised::spawn`]: call it from the app's exit and panic paths.
pub fn end_all() -> usize {
    global_registry().end_all()
}

/// How memory is measured for a cap: bytes used by the tree rooted at the pid. Defaults to real memory
/// ([`usage::tree_memory`]); tests and hosts with a better figure pass their own.
pub type Sampler = Arc<dyn Fn(u32) -> u64 + Send + Sync>;

/// A memory cap for a supervised child: the whole tree's memory (real memory per OS, rule 26: PSS on Linux so shared pages count once, the physical footprint on macOS) may not
/// exceed `limit`; it is warned at 80% and ended over the cap (rule 26: a 17 GB idle browser).
#[derive(Clone)]
pub struct MemoryCap {
    /// Bytes.
    pub limit: u64,
    /// Names the child in events: "the browser", `plugin "x"`.
    pub label: String,
    /// Hears the warning, the stop and the peak at the end.
    pub listener: Option<MemoryListener>,
    /// How often the memory is looked at.
    pub every: Duration,
    /// Another way to measure; `None` uses [`usage::tree_memory`].
    pub sampler: Option<Sampler>,
    /// Windows: also give the child's job object a hard per-process commit limit of `limit` (`JOB_OBJECT_LIMIT_PROCESS_MEMORY`),
    /// so an allocation past it fails in the child at once and a polling watcher cannot be outrun. Ignored elsewhere.
    pub hard_commit: bool,
}

impl MemoryCap {
    /// A cap of `limit` bytes, looked at every 200 ms.
    pub fn new(limit: u64, label: impl Into<String>) -> MemoryCap {
        MemoryCap {
            limit,
            label: label.into(),
            listener: None,
            every: Duration::from_millis(200),
            sampler: None,
            hard_commit: false,
        }
    }

    /// Also enforce `limit` as a hard commit limit of the job object (Windows; see [`MemoryCap::hard_commit`]).
    #[must_use]
    pub fn hard_commit(mut self) -> MemoryCap {
        self.hard_commit = true;
        self
    }

    /// Tells `listener` what the watcher sees.
    pub fn listener(mut self, listener: MemoryListener) -> MemoryCap {
        self.listener = Some(listener);
        self
    }
}

impl std::fmt::Debug for MemoryCap {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("MemoryCap")
            .field("limit", &self.limit)
            .field("label", &self.label)
            .finish_non_exhaustive()
    }
}

/// What the memory watcher shares with its [`Supervised`].
#[derive(Default)]
struct Shared {
    /// The cap the tree was ended over, once it was (0 = not).
    over: AtomicU64,
    /// The most memory the watcher saw.
    peak: AtomicU64,
}

/// The sampler of a cap without one of its own: the tree's memory, walked by identity from the root (ADR 0033). On Windows a
/// child in a job is measured through the job's member list, which needs no scan of the machine and follows no parent pid.
#[cfg(windows)]
fn default_sampler(root: ProcessId, job: Option<Arc<crate::job::Job>>) -> Sampler {
    if let Some(job) = job {
        return Arc::new(move |_| match job.pids() {
            Some(pids) => usage::tree_memory_of(&usage::OsSource::default(), &pids),
            None => usage::tree_memory_from(&usage::OsSource::default(), root),
        });
    }
    Arc::new(move |_| usage::tree_memory_from(&usage::OsSource::default(), root))
}

#[cfg(not(windows))]
fn default_sampler(root: ProcessId) -> Sampler {
    Arc::new(move |_| usage::tree_memory_from(&usage::OsSource::default(), root))
}

struct Watcher {
    stop: mpsc::Sender<()>,
    thread: Option<std::thread::JoinHandle<()>>,
}

impl Watcher {
    fn start(
        id: ProcessId,
        cap: MemoryCap,
        shared: Arc<Shared>,
        #[cfg(windows)] job: Option<Arc<crate::job::Job>>,
    ) -> Watcher {
        let pid = id.pid();
        let (stop, stopped) = mpsc::channel::<()>();
        let thread = std::thread::Builder::new()
            .name("paddock-proc-memory".into())
            .spawn(move || {
                #[cfg(windows)]
                let fallback = default_sampler(id, job.clone());
                #[cfg(not(windows))]
                let fallback = default_sampler(id);
                let sample = cap.sampler.clone().unwrap_or(fallback);
                let tell = |e: MemoryEvent| {
                    if let Some(l) = &cap.listener {
                        l.tell(&cap.label, e);
                    }
                };
                let mut watch = MemoryWatch::new(cap.limit);
                let mut last = 0;
                loop {
                    // pace: how often the memory is looked at; it bounds nothing
                    match stopped.recv_timeout(cap.every) {
                        Err(RecvTimeoutError::Timeout) => {}
                        // Told to stop, or the Supervised is gone.
                        Ok(()) | Err(RecvTimeoutError::Disconnected) => {
                            return tell(MemoryEvent::Ended(watch.ended(last)));
                        }
                    }
                    last = sample(pid);
                    let verdict = watch.observe(last);
                    shared.peak.store(watch.peak(), Ordering::Relaxed);
                    match verdict {
                        Verdict::Fine => {}
                        Verdict::Warn(u) => tell(MemoryEvent::Warning(u)),
                        Verdict::Stop(u) => {
                            shared.over.store(cap.limit.max(1), Ordering::Relaxed);
                            // Windows: through the job first (by handle); then by identity, since the owner may have
                            // reaped the child meanwhile.
                            #[cfg(windows)]
                            if let Some(j) = &job {
                                j.terminate();
                            }
                            kill_tree(id);
                            return tell(MemoryEvent::Stopped(u));
                        }
                    }
                }
            })
            .map_err(|e| log::error!("the memory watcher thread could not be started, so the cap is not enforced: {e}"))
            .ok();
        Watcher { stop, thread }
    }

    fn finish(mut self) {
        // silent: the watcher thread has already ended when its receiver is gone (it stopped the child itself)
        #[allow(clippy::let_underscore_must_use, clippy::let_underscore_untyped)]
        let _ = self.stop.send(());
        if let Some(t) = self.thread.take()
            && crate::cleanup::join("the memory watcher thread", t)
        {
            log::warn!("the memory watcher thread panicked while it was being stopped");
        }
    }
}

/// A child that is killed with its whole tree when dropped.
pub struct Supervised {
    child: Option<Child>,
    /// Windows: the kill-on-close job the child runs in (`None` when Windows refused one; the tree kill still applies).
    #[cfg(windows)]
    job: Option<Arc<crate::job::Job>>,
    /// The child's pid, kept after it was reaped for the registry and the log.
    pid: u32,
    /// The root by identity; `None` only when the OS would not say when the child started.
    process: Option<ProcessId>,
    registry: Registry,
    watcher: Option<Watcher>,
    shared: Arc<Shared>,
    /// Unix: the child's registration with this process's orphan guardian, which ends the child's group (and removes its
    /// folder) if this process dies without ending it ([`crate::guardian`]); dropped after the tree is ended here.
    #[cfg(unix)]
    pub(crate) guard: Option<crate::guardian::Registration>,
}

impl Supervised {
    /// Starts `cmd` in its own process group (Unix), registered in the [`global_registry`].
    pub fn spawn(cmd: Command) -> std::io::Result<Supervised> {
        Supervised::spawn_in(global_registry(), cmd, None)
    }

    /// Like [`Supervised::spawn`] with a memory cap.
    pub fn spawn_capped(cmd: Command, cap: MemoryCap) -> std::io::Result<Supervised> {
        Supervised::spawn_in(global_registry(), cmd, Some(cap))
    }

    /// Starts `cmd` registered in `registry`, optionally under a memory cap.
    pub fn spawn_in(
        registry: &Registry,
        cmd: Command,
        cap: Option<MemoryCap>,
    ) -> std::io::Result<Supervised> {
        Supervised::spawn_identified(registry, cmd, cap, ProcessId::of, None)
    }

    /// Like [`Supervised::spawn`], optionally with a memory cap, for a child that works in `folder` (a throwaway browser
    /// profile): if this process dies without ending the child (a SIGKILL, a crash), the child's group is ended and then
    /// `folder` is removed (Unix, [`crate::guardian`]). Every child gets the group end; only this start removes a folder.
    pub fn spawn_owning_folder(
        cmd: Command,
        cap: Option<MemoryCap>,
        folder: &std::path::Path,
    ) -> std::io::Result<Supervised> {
        Supervised::spawn_identified(global_registry(), cmd, cap, ProcessId::of, Some(folder))
    }

    /// [`Supervised::spawn_in`] with the way the child's identity is read (tests: a child whose start time is unknown).
    fn spawn_identified(
        registry: &Registry,
        mut cmd: Command,
        cap: Option<MemoryCap>,
        identify: fn(u32) -> Option<ProcessId>,
        folder: Option<&std::path::Path>,
    ) -> std::io::Result<Supervised> {
        crate::sys::own_group(&mut cmd);
        let child = crate::command::spawn_retrying(&mut cmd)?;
        let pid = child.id();
        // Not reaped yet, so the pid is still this child's.
        let process = identify(pid);
        // Not reaped yet, so its group is still its own.
        #[cfg(unix)]
        let guard = crate::guardian::register(pid, folder);
        // Windows: the kill-on-close job ends the tree when this process dies; the folder is the caller's to sweep.
        #[cfg(not(unix))]
        let _: Option<&std::path::Path> = folder;
        #[cfg(windows)]
        let job = {
            let hard = cap.as_ref().filter(|c| c.hard_commit).map(|c| c.limit);
            match crate::job::Job::assign(&child, hard) {
                Ok(job) => Some(Arc::new(job)),
                // A hard limit that cannot be set must not become a child without one: the launch fails.
                Err(e) if hard.is_some() => {
                    let mut child = child;
                    crate::cleanup::logged(
                        "killing the child whose hard limit failed",
                        child.kill(),
                    );
                    crate::cleanup::logged(
                        "reaping the child whose hard limit failed",
                        child.wait(),
                    );
                    log::error!(
                        "The hard memory limit of child {pid} could not be set in its job object, so it was not started: {e}"
                    );
                    return Err(std::io::Error::new(
                        e.kind(),
                        format!("cannot set the hard memory limit in the child's job object: {e}"),
                    ));
                }
                Err(_) => None,
            }
        };
        let shared = Arc::new(Shared::default());
        if process.is_none() {
            log::warn!(
                "The start time of child {pid} could not be read: it is ended through its handle and its process group only, \
                 without the registry, the tree walk or a memory cap"
            );
        }
        let watcher = process.and_then(|id| {
            registry.add(id);
            #[cfg(windows)]
            let w = cap.map(|c| Watcher::start(id, c, shared.clone(), job.clone()));
            #[cfg(not(windows))]
            let w = cap.map(|c| Watcher::start(id, c, shared.clone()));
            w
        });
        Ok(Supervised {
            child: Some(child),
            #[cfg(windows)]
            job,
            pid,
            process,
            registry: registry.clone(),
            watcher,
            shared,
            #[cfg(unix)]
            guard,
        })
    }

    /// Lowers the child's priority (Unix; Windows lowered it at the start, see [`crate::lower_priority`]). Done through the
    /// held child right after the spawn, so no fork window is needed. Only a child that has not ended is touched (an ended one
    /// may be reaped and its pid reused, rule 53). False when it is gone or the OS refused.
    pub fn lower_priority(&mut self) -> bool {
        self.child
            .as_mut()
            .is_some_and(|c| matches!(c.try_wait(), Ok(None)) && crate::sys::lower_child(c))
    }

    /// Whether the child runs in a kill-on-close job object (Windows; always false elsewhere, where the process group
    /// plays that part).
    pub fn in_job(&self) -> bool {
        #[cfg(windows)]
        {
            self.job.is_some()
        }
        #[cfg(not(windows))]
        {
            false
        }
    }

    /// The process id while the child has not been killed or waited for.
    pub fn id(&self) -> Option<u32> {
        self.child.as_ref().map(Child::id)
    }

    /// The child by identity while it has not been killed or waited for.
    pub fn process(&self) -> Option<ProcessId> {
        self.child.as_ref().and(self.process)
    }

    /// The child's piped standard input, once.
    pub fn take_stdin(&mut self) -> Option<ChildStdin> {
        self.child.as_mut()?.stdin.take()
    }

    /// The child's piped standard output, once.
    pub fn take_stdout(&mut self) -> Option<ChildStdout> {
        self.child.as_mut()?.stdout.take()
    }

    /// The child's piped standard error, once.
    pub fn take_stderr(&mut self) -> Option<ChildStderr> {
        self.child.as_mut()?.stderr.take()
    }

    /// Whether the process still runs.
    pub fn is_running(&mut self) -> bool {
        self.child
            .as_mut()
            .is_some_and(|c| matches!(c.try_wait(), Ok(None)))
    }

    /// The most memory the watcher has seen (0 without a cap).
    pub fn memory_peak(&self) -> u64 {
        self.shared.peak.load(Ordering::Relaxed)
    }

    /// The cap the tree was ended over, if it was.
    pub fn stopped_over_memory(&self) -> Option<u64> {
        match self.shared.over.load(Ordering::Relaxed) {
            0 => None,
            cap => Some(cap),
        }
    }

    /// The exit status of a child that has ended, without taking it over: on Unix the root may be reaped, but the guard,
    /// the job and the registry entry are kept, so [`Supervised::kill`] or [`Supervised::terminate`] afterwards still end
    /// the rest of its group (helpers it left behind). `None` while it runs, after [`Supervised::wait`] or
    /// [`Supervised::kill`] took the child, or when the OS cannot say. Repeated calls give the same status.
    pub fn exit_status(&mut self) -> Option<ExitStatus> {
        self.child.as_mut()?.try_wait().ok().flatten()
    }

    /// Waits for the child to end (a memory stop or [`Supervised::kill`] from elsewhere ends it too), reaps it and
    /// forgets the tree. `None` if it was already reaped.
    pub fn wait(&mut self) -> Option<ExitStatus> {
        let mut c = self.child.take()?;
        let status = c.wait().ok();
        self.release();
        status
    }

    /// Asks the process to quit (SIGTERM; Windows has no polite equivalent without a window), waits up to `grace` for it,
    /// then ends the tree. For browsers, where an abrupt kill during start-up can leave a copy of the app behind on
    /// macOS. Idempotent.
    pub fn terminate(&mut self, grace: Duration) -> Terminated {
        if !self.is_running() {
            self.kill();
            return Terminated::Gone;
        }
        if self.process.is_some_and(tree::ask) {
            let end = Instant::now().checked_add(grace);
            while self.is_running() && end.is_some_and(|e| Instant::now() < e) {
                std::thread::sleep(Duration::from_millis(25));
            }
        }
        let how = if self.is_running() {
            Terminated::Killed
        } else {
            Terminated::Gracefully
        };
        self.kill();
        how
    }

    /// Ends the whole process tree now and reaps it. Idempotent.
    pub fn kill(&mut self) {
        if let Some(mut c) = self.child.take() {
            // Windows: the job's members are the tree (each identified through a handle that checks it is in the job), and
            // the job ends them all at once, by handle, with no pid to go stale.
            #[cfg(windows)]
            let members = self.job.as_ref().and_then(|job| {
                let members = job.members();
                job.terminate();
                members
            });
            #[cfg(not(windows))]
            let members = None;
            // Not reaped yet (`try_wait` reaps one that has ended): its pid and group are still its own. On Windows the
            // `Child`'s handle pins the pid until it is dropped, reaped or not.
            let unreaped = matches!(c.try_wait(), Ok(None)) || cfg!(windows);
            match self.process {
                Some(id) if unreaped => {
                    kill_child_tree(id, members);
                }
                Some(id) => {
                    kill_tree(id);
                }
                None if unreaped => {
                    // No start time, but an unreaped child is ours by definition (ADR 0033 decision 4): its group too.
                    log::warn!(
                        "Ending child {} without its identity: through its handle and its process group only",
                        self.pid
                    );
                    crate::tree::end_unreaped_group(self.pid);
                }
                None => {}
            }
            crate::cleanup::logged("killing the child", c.kill());
            crate::cleanup::logged("reaping the child", c.wait());
        }
        self.release();
    }

    fn release(&mut self) {
        // After the tree was ended (or the child ended by itself): the guardian forgets the group and its keeper ends.
        #[cfg(unix)]
        drop(self.guard.take());
        // Windows: closing the job ends whatever of the tree is left (helpers that left it included).
        #[cfg(windows)]
        drop(self.job.take());
        if let Some(id) = self.process {
            self.registry.remove(id);
        }
        if let Some(w) = self.watcher.take() {
            w.finish();
        }
    }
}

impl Drop for Supervised {
    fn drop(&mut self) {
        self.kill();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::testchild::{Mode, child, lines};
    use std::io::{BufRead, BufReader, Read};
    use std::process::Stdio;
    use std::sync::Mutex;

    fn piped(mode: Mode) -> Command {
        let mut c = child(mode);
        c.stdout(Stdio::piped());
        c
    }

    fn pid_line(r: &mut impl BufRead) -> u32 {
        let mut l = String::new();
        loop {
            l.clear();
            assert!(
                r.read_line(&mut l).unwrap() > 0,
                "the child ended before telling its grandchild"
            );
            if let Some(p) = lines(&l).first().and_then(|p| p.strip_prefix("pid ")) {
                return p.trim().parse().unwrap();
            }
        }
    }

    /// The root exits and its status is read, leaving a sleeping grandchild: the status stays, and `kill` afterwards still
    /// ends the grandchild (reading the status releases nothing).
    #[test]
    fn exit_status_is_stable_and_leaves_the_group_and_job_to_kill() {
        let mut s = Supervised::spawn_in(&Registry::new(), piped(Mode::Leave), None).unwrap();
        let mut r = BufReader::new(s.take_stdout().unwrap());
        let grand = pid_line(&mut r);
        // conformance: hang-guard — the root exits at once; the bound only keeps a broken run from hanging
        let end = Instant::now() + Duration::from_secs(60);
        let status = loop {
            if let Some(st) = s.exit_status() {
                break st;
            }
            assert!(Instant::now() < end, "the child did not exit");
            std::thread::yield_now();
        };
        assert!(status.code().is_some(), "{status:?}");
        assert_eq!(s.exit_status(), Some(status), "the status stays");
        s.kill();
        assert!(s.exit_status().is_none(), "kill took the child");
        let mut rest = Vec::new();
        r.read_to_end(&mut rest).unwrap();
        assert!(
            crate::testchild::is_gone(grand),
            "the grandchild survived kill after exit_status"
        );
        let mut running = Supervised::spawn(child(Mode::Sleep)).unwrap();
        assert!(
            running.exit_status().is_none(),
            "a running child has no status"
        );
        running.kill();
    }

    #[test]
    fn a_windows_child_runs_in_a_kill_on_close_job() {
        let mut s = Supervised::spawn_in(&Registry::new(), piped(Mode::Sleep), None).unwrap();
        assert_eq!(s.in_job(), cfg!(windows));
        s.kill();
        assert!(!s.in_job(), "the job closed with the tree");
    }

    /// The child starts a helper and exits: the helper is an orphan no tree walk finds, but the job still holds it.
    #[cfg(windows)]
    #[test]
    fn closing_the_job_ends_an_orphaned_helper() {
        let mut s = Supervised::spawn_in(&Registry::new(), piped(Mode::Leave), None).unwrap();
        let mut r = BufReader::new(s.take_stdout().unwrap());
        let grand = pid_line(&mut r);
        assert!(s.wait().is_some());
        let mut rest = Vec::new();
        r.read_to_end(&mut rest).unwrap();
        assert!(
            crate::testchild::is_gone(grand),
            "the orphaned helper leaked"
        );
    }

    #[test]
    fn drop_ends_the_child_and_its_grandchild() {
        let reg = Registry::new();
        let mut s = Supervised::spawn_in(&reg, piped(Mode::Tree), None).unwrap();
        let mut r = BufReader::new(s.take_stdout().unwrap());
        let grand = pid_line(&mut r);
        let pid = s.id().unwrap();
        // conformance: pid-liveness — a test of the raw-pid answer itself or of a child this test owns
        assert!(s.is_running() && (crate::presence(grand) == crate::Presence::Running));
        assert_eq!(reg.pids(), vec![pid]);
        drop(s);
        // The pipe is shared with the grandchild: EOF means every holder is dead.
        let mut rest = Vec::new();
        r.read_to_end(&mut rest).unwrap();
        assert!(crate::testchild::is_gone(pid), "the child leaked");
        assert!(crate::testchild::is_gone(grand), "the grandchild leaked");
        assert!(reg.pids().is_empty(), "a dropped child leaves the registry");
    }

    /// macOS P1 (ADR 0033): a setuid child (`/usr/bin/top`, owned by root) runs under another effective user, which
    /// `proc_pidinfo` refuses; its identity comes from the sysctl, so it is registered, capped and ended with its group.
    #[cfg(target_os = "macos")]
    #[test]
    fn a_setuid_child_has_an_identity_and_is_supervised() {
        let mut cmd = crate::command("/usr/bin/top");
        cmd.args(["-l", "0", "-s", "60"])
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let reg = Registry::new();
        let mut s = Supervised::spawn_in(&reg, cmd, Some(MemoryCap::new(u64::MAX, "top"))).unwrap();
        let id = s.process().expect("a setuid child has an identity");
        assert_eq!(reg.pids(), vec![id.pid()]);
        assert!(s.watcher.is_some(), "the memory cap watches it");
        s.kill();
        assert!(
            crate::testchild::is_gone(id.pid()),
            "the setuid child was ended"
        );
        assert!(reg.pids().is_empty());
    }

    /// The child exits and is reaped (`is_running` reaps), leaving a helper in its process group: `kill` then finds the root
    /// gone with no new holder of its pid, so the group is still the root's and is signalled.
    #[cfg(unix)]
    #[test]
    fn a_reaped_childs_helper_is_ended_through_its_group() {
        let mut s = Supervised::spawn_in(&Registry::new(), piped(Mode::Leave), None).unwrap();
        let mut r = BufReader::new(s.take_stdout().unwrap());
        let grand = pid_line(&mut r);
        // conformance: hang-guard — the child exits at once; the bound only keeps a broken run from hanging
        let end = Instant::now() + Duration::from_secs(60);
        while s.is_running() {
            assert!(Instant::now() < end, "the child did not exit");
            std::thread::yield_now();
        }
        assert!(
            // conformance: pid-liveness — a test of the raw-pid answer itself or of a child this test owns
            (crate::presence(grand) == crate::Presence::Running),
            "the helper outlived the child"
        );
        s.kill();
        let mut rest = Vec::new();
        r.read_to_end(&mut rest).unwrap();
        assert!(
            crate::testchild::is_gone(grand),
            "the helper in the group was ended"
        );
    }

    /// A child whose start time could not be read is still ours while unreaped: it is ended with its process group, and is
    /// in no registry and under no cap.
    #[cfg(unix)]
    #[test]
    fn a_child_without_an_identity_is_ended_through_its_group_and_its_handle() {
        let reg = Registry::new();
        let cap = MemoryCap::new(u64::MAX, "x");
        let mut s =
            Supervised::spawn_identified(&reg, piped(Mode::Tree), Some(cap), |_| None, None)
                .unwrap();
        let mut r = BufReader::new(s.take_stdout().unwrap());
        let grand = pid_line(&mut r);
        assert!(s.process().is_none() && reg.pids().is_empty() && s.watcher.is_none());
        s.kill();
        let mut rest = Vec::new();
        r.read_to_end(&mut rest).unwrap();
        assert!(
            crate::testchild::is_gone(grand),
            "the grandchild in its group was ended"
        );
        // Reaped and without an identity: nothing more is signalled.
        let mut gone =
            Supervised::spawn_identified(&reg, child(Mode::Exit3), None, |_| None, None).unwrap();
        // conformance: hang-guard — the child exits at once; the bound only keeps a broken run from hanging
        let end = Instant::now() + Duration::from_secs(60);
        while gone.is_running() {
            assert!(Instant::now() < end, "the child did not exit");
            std::thread::yield_now();
        }
        gone.kill();
        assert_eq!(gone.wait(), None);
    }

    #[test]
    fn end_all_ends_every_registered_tree() {
        let reg = Registry::new();
        let mut a = Supervised::spawn_in(&reg, piped(Mode::Tree), None).unwrap();
        let mut b = Supervised::spawn_in(&reg, piped(Mode::Sleep), None).unwrap();
        let mut r = BufReader::new(a.take_stdout().unwrap());
        let grand = pid_line(&mut r);
        assert_eq!(reg.pids().len(), 2);
        assert_eq!(reg.end_all(), 2);
        assert!(reg.pids().is_empty());
        assert!(a.wait().is_some_and(|s| !s.success()));
        assert!(b.wait().is_some_and(|s| !s.success()));
        let mut rest = Vec::new();
        r.read_to_end(&mut rest).unwrap();
        assert!(crate::testchild::is_gone(grand));
        assert_eq!(reg.end_all(), 0);
    }

