    fn ready(s: &mut Supervised) {
        let out = s.take_stdout().unwrap();
        let mut r = BufReader::new(out);
        let mut l = String::new();
        loop {
            l.clear();
            assert!(
                r.read_line(&mut l).unwrap() > 0,
                "child ended before it was ready"
            );
            if lines(&l) == ["ready"] {
                return;
            }
        }
    }

