    #[test]
    fn descendants_are_found_by_walking_the_process_table() {
        let mut c = child(Mode::Tree);
        c.stdout(Stdio::piped());
        let mut s = Supervised::spawn(c).unwrap();
        let mut r = BufReader::new(s.take_stdout().unwrap());
