            "--signature",
            &sig,
            "--version",
            "9.9.9",
            "--restart",
        ],
    );
    assert_eq!(c, 4, "a pipe path is a usage error");
    // UNC, device and namespace paths.
    for hostile in [
        r"\\localhost\C$\Windows\System32\cmd.exe",
        r"\\?\C:\Windows\System32\cmd.exe",
        r"\\.\C:\x",
        r"C:\Windows\System32\cmd.exe:evil",
        r"C:\NUL",
    ] {
        let (c, _) = run(
            &site.setup(),
            &[
                "apply-update",
                "--file",
                hostile,
                "--signature",
                &sig,
                "--version",
                "9.9.9",
                "--restart",
            ],
        );
        assert_eq!(c, 4, "{hostile}");
