/// `stop-all` over the real stopper (a build with `paddock_proc::installed` in the tree, `PADDOCK_SETUP_EXE_STOP`): a listed program that
/// runs from the folder is ended; a program with the same file name from another folder is not.
#[test]
#[ignore = "Windows test VM only: PADDOCK_SETUP_VM=1 (ER-14)"]
fn stop_all_ends_a_listed_program_from_the_folder_and_leaves_a_namesake_alone() {
    let site = Site::with_exe("stopall", "PADDOCK_SETUP_EXE_STOP");
    let other = Site::new("stopall-other");
    let ping = PathBuf::from(std::env::var("SystemRoot").expect("SystemRoot"))
        .join("System32")
        .join("PING.EXE");
    let mine = site.0.join("paddocktarget.exe");
    let theirs = other.0.join("paddocktarget.exe");
    std::fs::copy(&ping, &mine).unwrap();
    std::fs::copy(&ping, &theirs).unwrap();
    // `ping -t` runs until it is ended; both children are made and ended by this test only.
    let mut child_mine = Command::new(&mine)
        .args(["-t", "127.0.0.1"])
        .stdout(std::process::Stdio::null())
        .spawn()
        .expect("start the listed program");
    let mut child_theirs = Command::new(&theirs)
        .args(["-t", "127.0.0.1"])
        .stdout(std::process::Stdio::null())
        .spawn()
        .expect("start the namesake");
    let (code, _) = run(
        &site.setup(),
        &[
            "stop-all",
            "--dir",
            &site.0.to_string_lossy(),
            "--images",
            "paddocktarget.exe",
        ],
    );
    let mine_ended = child_mine.try_wait().unwrap().is_some();
    let theirs_running = child_theirs.try_wait().unwrap().is_none();
    let _ = child_mine.kill();
    let _ = child_theirs.kill();
    let _ = child_mine.wait();
    let _ = child_theirs.wait();
    let log = site.log();
    assert_eq!((code, mine_ended, theirs_running), (0, true, true), "{log}");
    assert!(
        log.contains("phase=process image=paddocktarget.exe pid="),
        "{log}"
    );
    assert!(log.contains("phase=exit code=0"), "{log}");
}

/// `guard`: a per-user uninstall key in the installer account's hive blocks a fresh install (exit 2, the message on the
/// first stdout line); without the key, or when an HKLM key exists, it does not.
#[test]
#[ignore = "Windows test VM only: PADDOCK_SETUP_VM=1 (ER-14)"]
fn guard_blocks_on_the_installer_accounts_uninstall_key_only() {
    const KEY: &str = r"HKCU\Software\Microsoft\Windows\CurrentVersion\Uninstall\PaddockSetupTest";
    let site = Site::new("guard");
    let dir = site.0.to_string_lossy().into_owned();
    let args = [
        "guard",
        "--product",
        "PaddockSetupTest",
        "--main",
        "paddock-setup.exe",
        "--dir",
        dir.as_str(),
    ];
    let p = exe("PADDOCK_SETUP_EXE");
    assert_eq!(run(&p, &args).0, 0, "no key: nothing blocks");
    assert!(reg(&[
        "add",
        KEY,
        "/v",
        "UninstallString",
        "/t",
        "REG_SZ",
        "/d",
        r#""C:\Nowhere\PaddockSetupTest\uninstall.exe""#,
        "/f"
    ]));
    let (code, out) = run(&p, &args);
    let mut with_restart = args.to_vec();
    with_restart.extend(["--update", "--restart"]);
    let (code2, out2) = run(&p, &with_restart);
    reg(&["delete", KEY, "/f"]);
    assert_eq!(code, 2, "{out}");
    let lines: Vec<&str> = out.lines().collect();
    assert_eq!(
        lines,
        [
            "Uninstall the older PaddockSetupTest first (Settings > Apps), then run this installer again."
        ]
    );
    assert_eq!(code2, 2);
    assert!(
        out2.lines()
            .next()
            .unwrap()
            .ends_with("Then start PaddockSetupTest again."),
        "{out2}"
    );
    assert!(
        !out2.contains("RESTART:"),
        "the program is not there, so nothing is started"
    );
    assert!(
        site.log()
            .contains("phase=guard hit role=installer key=yes file=no (blocks)"),
        "{}",
        site.log()
    );
    assert_eq!(run(&p, &args).0, 0, "the key is gone again");
}

/// An installer that ends without ever running `hold-installing` is its own exit code (31): the app's Failed path relaunches.
#[test]
#[ignore = "Windows test VM only: PADDOCK_SETUP_VM=1 (ER-14)"]
fn an_installer_that_ends_before_it_holds_the_lock_is_exit_31_and_what_is_left_is_protected_and_cleaned()
 {
    let site = Site::with_exe("ended", "PADDOCK_SETUP_EXE_E2E");
    let (installer, good, _other) = e2e_files();
    let (code, out) = apply(&site, &installer, &good, "9.9.9");
    assert_eq!(code, 31, "{out}\n{}", site.log());
    assert!(out.contains("stopped before it finished"), "{out}");
    assert!(
        site.log()
            .contains("the installer ended before it held the lock"),
        "{}",
        site.log()
    );
    // The program that just ended can still hold its image for a moment, so the run folder may not be removable yet: it is
    // renamed or left, readable by Administrators and SYSTEM only, and the next clean-up removes it (bounded wait on the
    // condition, not a fixed sleep).
    for left in leftovers(&site) {
        assert_eq!(
            acl_identities(&site.updates().join(&left)),
            ["BUILTIN\\Administrators", "NT AUTHORITY\\SYSTEM"],
            "{left}"
        );
    }
    let _ = paddock_testkit::retry_within(std::time::Duration::from_secs(30), RETRY_EVERY, || {
        if leftovers(&site).is_empty() {
            return true;
        }
        let _ = run(
            &site.setup(),
            &["clean-staging", "--dir", &site.0.to_string_lossy()],
        );
        leftovers(&site).is_empty()
    });
    assert_eq!(leftovers(&site), Vec::<String>::new(), "{}", site.log());
}

/// While a hand-off is running a second `apply-update` is busy (21) and run 1's folder is untouched; after it ends a third
/// one goes through. The standard-user side of the same hand-off is observed by `handoff-user.ps1`.
#[test]
#[ignore = "Windows test VM only: PADDOCK_SETUP_VM=1 (ER-14)"]
fn a_second_update_during_a_hand_off_is_busy_and_does_not_touch_the_first_run() {
    let site = Site::with_exe("second", "PADDOCK_SETUP_EXE_E2E");
    let (installer, good, _other) = e2e_files();
    let holder = site.setup().to_string_lossy().into_owned();
    let env = [
        ("PADDOCK_FAKE_HOLD", holder.as_str()),
        ("PADDOCK_FAKE_SECONDS", "10"),
    ];
    let (code, out) = apply_env(&site.setup(), &installer, &good, "9.9.9", &env);
    assert_eq!(code, 0, "{out}\n{}", site.log());
    // apply-update returned because hold-installing holds the lock; the fake installer is still alive for about ten seconds.
    let runs = |site: &Site| -> Vec<String> {
        let mut v: Vec<String> = std::fs::read_dir(site.updates())
            .unwrap()
            .filter_map(|e| e.ok())
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.starts_with("run-"))
            .collect();
        v.sort();
        v
    };
    let first = runs(&site);
    assert_eq!(first.len(), 1, "{first:?}");
    let (busy, out) = apply_env(&site.setup(), &installer, &good, "9.9.9", &env);
    assert_eq!(
        busy,
        21,
        "a second update during a hand-off is busy: {out}\n{}",
        site.log()
    );
    assert_eq!(
        runs(&site),
        first,
        "the first run's folder is untouched, and the refused run left none"
    );
    assert!(
        site.updates()
            .join(&first[0])
            .join("update-9.9.9.exe")
            .is_file()
    );
    // The first installer ends (its parent, the fake, exits): the lock and the signal go with it, then an update goes through.
    let mut third = (busy, String::new());
    let _ = paddock_testkit::retry_within(std::time::Duration::from_secs(60), RETRY_EVERY, || {
        third = apply_env(
            &site.setup(),
            &installer,
            &good,
            "9.9.9",
            &[
                ("PADDOCK_FAKE_HOLD", &holder),
                ("PADDOCK_FAKE_SECONDS", "1"),
            ],
        );
        third.0 != 21
    });
    assert_eq!(third.0, 0, "{}\n{}", third.1, site.log());
}

//! The plugin on Tauri's mock runtime (no window reaches the desktop, nothing is written outside temp folders): every
//! shell command is registered as `plugin:paddock-shell|<command>`, the generated permission sets resolve through
//! Tauri's own ACL per window class, the guard narrows dialogs to their contracts, and the shell's parts work through
//! the plugin (version, window notices to every window, update preferences on the settings).

use paddock_commands::WindowClass;
use paddock_shell::{AppIdentity, Builder, COMMANDS, PLUGIN_NAME, VERSION};
use paddock_updater::tauri::UpdatesBuilder;
#[cfg(feature = "mock-runtime")]
use paddock_window::launch::LaunchArgs;
use serde_json::{Value, json};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use tauri::ipc::{CallbackFn, InvokeBody};
use tauri::test::{
    INVOKE_KEY, MockRuntime, get_ipc_response, mock_builder, mock_context, noop_assets,
};
use tauri::webview::InvokeRequest;
use tauri::{App, Listener, Manager, WebviewUrl, WebviewWindow, WebviewWindowBuilder};
use tauri_utils::acl::capability::Capability;
use tauri_utils::acl::manifest::{Manifest, PermissionFile};
use tauri_utils::acl::resolved::Resolved;

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// Every permission file of the plugin: Tauri's per-command ones and the generated sets.
fn permission_files() -> Vec<PermissionFile> {
    let mut paths = vec![crate_dir().join("permissions/window-classes.toml")];
    let commands = crate_dir().join("permissions/autogenerated/commands");
    for e in std::fs::read_dir(commands).unwrap() {
        paths.push(e.unwrap().path());
    }
    paths
        .iter()
        .map(|p| toml::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
        .collect()
}

/// The app's capabilities as an app grants the shell: one set per window class.
fn capabilities(sets: &[(&str, &[&str], &str)]) -> BTreeMap<String, Capability> {
    sets.iter()
        .map(|(id, windows, permission)| {
            let c: Capability = serde_json::from_value(json!({
                "identifier": id,
                "windows": windows,
                "permissions": [permission],
            }))
            .unwrap();
            (id.to_string(), c)
        })
        .collect()
}

const CLASSES: [(&str, &[&str], &str); 4] = [
    ("main", &["main", "w-*"], "paddock-shell:default"),
    ("popout", &["p-*"], "paddock-shell:popout"),
    ("dialog", &["d-*"], "paddock-shell:dialog"),
    ("tray", &["tray", "tray-*"], "paddock-shell:tray"),
];

fn context() -> tauri::Context<MockRuntime> {
    let mut ctx = mock_context(noop_assets());
    let acl = BTreeMap::from([(
        PLUGIN_NAME.to_string(),
        Manifest::new(permission_files(), None),
    )]);
    let resolved = Resolved::resolve(
        &acl,
        capabilities(&CLASSES),
        tauri_utils::platform::Target::current(),
    )
    .unwrap();
    *ctx.runtime_authority_mut() = tauri::runtime_authority!(acl, resolved);
    ctx
}

fn identity() -> AppIdentity {
    AppIdentity::new("demo", "Shell Demo", "1.2.3")
}

fn app(builder: Builder<MockRuntime>) -> App<MockRuntime> {
    mock_builder()
        .plugin(builder.build())
        .build(context())
        .unwrap()
}

fn window(app: &App<MockRuntime>, label: &str) -> WebviewWindow<MockRuntime> {
    WebviewWindowBuilder::new(app, label, WebviewUrl::default())
        .build()
        .unwrap()
}

fn invoke(w: &WebviewWindow<MockRuntime>, cmd: &str, args: Value) -> Result<Value, Value> {
    let request = InvokeRequest {
        cmd: format!("plugin:{PLUGIN_NAME}|{cmd}"),
        callback: CallbackFn(0),
        error: CallbackFn(1),
        url: if cfg!(windows) {
            "http://tauri.localhost"
        } else {
            "tauri://localhost"
        }
        .parse()
        .unwrap(),
        body: InvokeBody::Json(args),
        headers: Default::default(),
        invoke_key: INVOKE_KEY.to_string(),
    };
    get_ipc_response(w, request).map(|b| b.deserialize::<Value>().unwrap())
}

fn text(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

/// A label of each class (a dialog under `main`).
fn label_of(class: WindowClass) -> &'static str {
    match class {
        WindowClass::Main => "main",
        WindowClass::Popout => "p-main-1",
        WindowClass::Dialog => "d-main-1",
        WindowClass::Tray => "tray",
    }
}

/// Commands that would act on the test process itself (quit, restart); they are reached with a call that is refused
/// before they act (no arguments where they need some, or no state).
const SIDE_EFFECTS: [&str; 2] = ["app_quit", "updates_restart"];

#[test]
fn every_shell_command_is_registered_and_reaches_its_handler_from_a_window_it_is_open_to() {
    let app = app(Builder::new(identity()).in_memory().native_menu(false));
    let windows: BTreeMap<&str, WebviewWindow<MockRuntime>> = WindowClass::ALL
        .iter()
        .map(|c| (label_of(*c), window(&app, label_of(*c))))
        .collect();
    assert!(
        COMMANDS.specs().len() >= 40,
        "the table holds every shell crate's commands"
    );
    for spec in COMMANDS.specs() {
        if SIDE_EFFECTS.contains(&spec.name()) {
            continue;
        }
        // From a window the table does not open it to the guard never runs: Tauri's ACL refuses first.
        let class = spec.windows().classes()[0];
        let w = &windows[label_of(class)];
        let answer = invoke(w, spec.name(), json!({}));
        let said = answer.as_ref().map_or_else(text, text);
        assert!(!said.contains("not found"), "{}: {said}", spec.name());
        assert!(
            !said.contains("not allowed"),
            "{} from {}: {said}",
            spec.name(),
            w.label()
        );
    }
}

#[test]
fn the_permission_sets_open_each_command_to_exactly_the_classes_of_the_table() {
    let app = app(Builder::new(identity()).in_memory().native_menu(false));
    let windows: Vec<(WindowClass, WebviewWindow<MockRuntime>)> = WindowClass::ALL
        .iter()
        .map(|c| (*c, window(&app, label_of(*c))))
        .collect();
    for spec in COMMANDS.specs() {
        if SIDE_EFFECTS.contains(&spec.name()) {
            continue;
        }
        for (class, w) in &windows {
            let said = invoke(w, spec.name(), json!({})).map_or_else(|e| text(&e), |v| text(&v));
            let refused = said.contains("not allowed");
            assert_eq!(
                refused,
                !spec.windows().contains(*class),
                "{} from {}: {said}",
                spec.name(),
                w.label()
            );
        }
    }
    // A webview outside the label scheme has no capability at all.
    let stray = window(&app, "stray");
    assert!(text(&invoke(&stray, "shell_version", json!({})).unwrap_err()).contains("not allowed"));
}

#[test]
fn a_dialog_reaches_only_what_its_contract_declares() {
    paddock_dialogs::dialogs! {
        static SETTINGS;
        "sd.settings" => Tool { commands: &[paddock_shell::dialog_commands::settings::settings_overview] },
    }
    let app = app(Builder::new(identity())
        .in_memory()
        .native_menu(false)
        .dialogs(&[&SETTINGS]));
    // The dialog layer does not know this window: the ACL lets the dialog set through, the guard refuses.
    let unknown = window(&app, "d-main-1");
    let e = invoke(&unknown, "settings_overview", json!({})).unwrap_err();
    assert_eq!(
        (e["code"].as_str(), e["command"].as_str()),
        (Some("denied"), Some("settings_overview")),
