    let mut acq = Acquirer::new(&a.h, req("X")).unwrap();
    assert_eq!(acquire(&mut acq, &a.h, 10), Poll::Held);
}

#[test]
fn a_ticket_that_cannot_be_written_gives_up_clearly() {
    let rig = Rig::new();
    let a = rig.agent(11);
