        panic!("expected Err")
    };
    assert!(msg.contains("queue ticket"), "{msg}");
    assert!(!rig.lock_dir().exists());
}

#[test]
fn a_write_that_succeeds_but_leaves_an_empty_owner_is_never_published() {
    let rig = Rig::new();
