    for text in [
        "Sat 31 Oct 23:29:50 2026",
        "sam. 31 oct. 23:29:50 2026",
        "2026年10月31日",
        "",
        "UTC+9 whatever",
    ] {
        let _ = fs::remove_dir_all(rig.lock_dir());
