//! C53: nothing is ended by a bare pid (ADR 0033, rule 53). The OS hands a freed pid on (Windows at once), so a pid kept from a
//! snapshot, a file or a parent link can name another program by the time it is signalled. Every kill goes through
//! `paddock_proc` with a `ProcessId` or through a handle or job object this process owns. The main check is Clippy's
//! `disallowed-methods`; this one covers what Clippy cannot see, in any Rust file outside the one implementation
//! (`crates/paddock-proc/src/sys.rs`) and vendored third-party code:
//!
//! - programs that kill by pid, named in string literals: `taskkill`, `Stop-Process`, `/bin/kill`, a `kill` or `pkill` command;
//! - Win32 calls: `TerminateProcess(`, `TerminateJobObject(`;
//! - a blanket `#![allow(clippy::disallowed_methods)]` (also inside `#![cfg_attr(.., allow(..))]);
//! - open follow-ups: a comment or `#[expect]` reason naming `ADR 0033 WP-<n>`; each needs a dated waiver in
//!   `paddock.waivers.toml`.
//!
//! A justified site carries `// conformance: pid-kill — <reason>` on the line or the line above.
//!
//! The JavaScript check (`C53-pid-kills.mjs`) was retired with pair P3 (ADR 0022 amendment 2026-11-19); `tests/it/check.rs` holds this one to the answers it recorded. Positions are
//! UTF-16 offsets, as in the JavaScript, so a hit orders the same way next to non-ASCII text.

use super::finding::Finding;
use super::inline_waiver::{CommentView, InlineWaiver, Kind};
use super::jsre::{Positions, rx};
use super::mask::mask_rust;
use super::record::Precondition;
use super::{Check, CheckOutput, Control, Ctx};
use regex::Regex;
use std::sync::LazyLock;

/// The one place that may signal a pid: it does so right after the identity check.
const IMPLEMENTATION: [&str; 1] = ["crates/paddock-proc/src/sys.rs"];

/// The marker up to its dashes; a reason must follow ([`has_reason`]).
static VENDORED: LazyLock<Regex> = LazyLock::new(|| rx(r"^apps/[^/]+/vendor/"));
static PREFILTER: LazyLock<Regex> =
    LazyLock::new(|| rx(r"kill|Stop-Process|Terminate(?:Process|JobObject)|ADR 0033 WP-|disallowed_methods")); // conformance: pid-kill — a pattern that finds these words in source text; nothing here ends a process
static BLANKET: LazyLock<Regex> = LazyLock::new(|| rx(r"#!\[(?:cfg_attr\([^\]]*?)?allow\([^\]]*\bclippy::disallowed_methods\b"));
static FOLLOW_UP: LazyLock<Regex> = LazyLock::new(|| rx(r"ADR 0033 (WP-\d+)"));
static WIN32: LazyLock<[(Regex, &str); 2]> = LazyLock::new(|| {
    [
        (rx(r"\bTerminateProcess\s*\("), "ends a process with `TerminateProcess`"),
        (rx(r"\bTerminateJobObject\s*\("), "ends a job with `TerminateJobObject`"),
    ]
});
/// Programs that kill by pid, matched on the unmasked text, since their names are string literals. The flag: the quote to check
/// is the match's start (false) or its last `"` (true).
static PROGRAMS: LazyLock<[(Regex, bool); 4]> = LazyLock::new(|| {
    [
        (rx(r#""(taskkill)(?:\.exe)?""#), false),
        // conformance: pid-kill — a pattern that finds `Stop-Process` in source text; this file ends no process
        (rx(r#""[^"\n]*\b(Stop-Process)\b[^"\n]*""#), false),
        (rx(r#""(/(?:usr/)?bin/kill)""#), false),
        (rx(r#"\b(?:command|Command::new)\s*\(\s*"(kill|pkill)""#), true),
    ]
});

/// One pid kill in a Rust source.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PidKill {
    /// The 1-based line.
    pub line: usize,
    /// What it does, in a sentence.
    pub what: String,
    /// The waiver comment: `Some(true)` with a reason, `Some(false)` without one, `None` for no comment (a follow-up marker never has one).
    pub waived: InlineWaiver,
}

struct Hit {
    index: usize,
    line: usize,
    what: String,
    follow_up: bool,
}

/// The pid kills in one Rust source.
pub fn pid_kills(text: &str) -> Vec<PidKill> {
    // `mask_units` of the text as text and as units, without the round trip through UTF-16 and back (`text` is valid UTF-8).
    let masked = mask_rust(text);
    let mask_u: Vec<u16> = masked.encode_utf16().collect();
    let view = CommentView::of(text, Kind::Rust);
    // JavaScript indexes and lines of the hits, each text counted once and only when it has a hit (not once per hit: quadratic).
    let (in_masked, in_text) = (Positions::new(&masked), Positions::new(text));
    let mut hits: Vec<Hit> = Vec::new();
    for (re, what) in WIN32.iter() {
        for m in re.find_iter(&masked) {
            hits.push(Hit {
                index: in_masked.unit(m.start()),
                line: in_masked.line(m.start()),
                what: (*what).into(),
                follow_up: false,
            });
        }
    }
    for (re, last_quote) in PROGRAMS.iter() {
        for m in re.captures_iter(text) {
            let whole = m.get(0).map_or(0..0, |w| w.range());
            // Only a literal in code: in a comment or inside another string the mask has blanked the quote.
            let q = if *last_quote {
                whole.start + text[whole.clone()].rfind('"').unwrap_or(0)
            } else {
                whole.start
            };
            if mask_u.get(in_text.unit(q)) == Some(&(b'"' as u16)) {
                hits.push(Hit {
                    index: in_text.unit(whole.start),
                    line: in_text.line(whole.start),
                    what: format!("runs `{}`, which ends processes by pid", &m[1]),
                    follow_up: false,
                });
            }
        }
    }
    for m in BLANKET.find_iter(&masked) {
        hits.push(Hit {
            index: in_masked.unit(m.start()),
            line: in_masked.line(m.start()),
            what: "allows `clippy::disallowed_methods` for a whole crate or module, which hides bare-pid kills from Clippy".into(),
            follow_up: false,
        });
    }
    for m in FOLLOW_UP.captures_iter(text) {
        let start = m.get(0).map_or(0, |w| w.start());
        hits.push(Hit {
            index: in_text.unit(start),
            line: in_text.line(start),
            what: format!("an open ADR 0033 follow-up ({}): a known bare-pid kill or parent-pid walk", &m[1]),
            follow_up: true,
        });
    }
    hits.sort_by_key(|h| h.index);
    hits.into_iter()
        .map(|h| {
            // A follow-up marker is waived only in paddock.waivers.toml (dated), never inline.
            let waived = if h.follow_up {
                InlineWaiver::No
            } else {
                view.waiver(h.line, "pid-kill")
            };
            PidKill {
                line: h.line,
                what: h.what,
                waived,
            }
        })
        .collect()
}

/// The check.
pub struct C53;

impl Check for C53 {
    fn id(&self) -> &'static str {
        "C53"
    }

    fn rule(&self) -> u32 {
        53
    }

    fn title(&self) -> &'static str {
        "Nothing is ended by a bare pid"
    }

    fn control(&self) -> Control {
        Control {
            files: vec![
                (
                    "crates/c/src/bad.rs",
                    "fn a(h: HANDLE) {\n    unsafe { TerminateProcess(h, 1) };\n}\n",
                ),
                (
                    "crates/c/src/good.rs",
                    "fn a(c: &mut Child) {\n    let _ = c.kill();\n}\n// \"taskkill\"\n",
                ),
                (
                    "crates/paddock-proc/src/sys.rs",
                    "fn a(h: HANDLE) {\n    unsafe { TerminateProcess(h, 1) };\n}\n",
                ),
                (
                    "apps/x/vendor/d/src/w.rs",
                    "fn a(h: HANDLE) {\n    unsafe { TerminateProcess(h, 1) };\n}\n",
                ),
            ],
            expect: vec![("crates/c/src/bad.rs", 2)],
        }
    }

    fn run(&self, ctx: &Ctx) -> CheckOutput {
        let fix = "End it through `paddock_proc` with a `ProcessId` (`kill_tree`, `end`, `terminate`; `Supervised` for a child), or through a handle or job object this process owns (ADR 0033). A justified case carries `// conformance: pid-kill — <reason>`.";
        let mut findings = Vec::new();
        let mut probes = 0;
        let mut completed = true;
        for f in ctx.files().iter() {
            if !f.ends_with(".rs") || IMPLEMENTATION.contains(&f.as_str()) || VENDORED.is_match(f) {
                continue;
            }
            let Some(text) = ctx.read(f) else {
                completed = false;
                continue;
            };
            if text.is_empty() {
                continue;
            }
            probes += 1;
            if !PREFILTER.is_match(&text) {
                continue;
            }
            for k in pid_kills(&text) {
                let site = if k.what.starts_with("an open") || k.what.starts_with("allows") {
                    Finding::error(
                        "C53",
                        53,
                        f,
                        k.line,
                        k.what,
                        "Fix the site through paddock_proc (ADR 0033), or give it a dated waiver in paddock.waivers.toml.",
                    )
                } else {
                    Finding::error(
                        "C53",
                        53,
                        f,
                        k.line,
                        format!("{}: the pid may belong to another process by now", k.what),
                        fix,
                    )
                };
                findings.push(k.waived.apply(site, || {
                    Finding::error(
                        "C53",
                        53,
                        f,
                        k.line,
                        "the pid-kill waiver gives no reason",
                        "Write `// conformance: pid-kill — <why this pid cannot have been handed on>`.",
                    )
                }));
            }
        }
        let live = super::c53_liveness::liveness_findings(ctx);
        findings.extend(live.findings);
        let has_rs = ctx.tree_files().iter().any(|f| f.ends_with(".rs"));
        let (met, detail) = if live.stale_unmeasured {
            (
                false,
                format!(
                    "{} is in a scoped run, which cannot tell which of its entries are stale: run the whole tree (no --files)",
                    super::c53_liveness::LIVENESS_BASELINE
                ),
            )
        } else {
            (has_rs, "the tree has a .rs file".into())
        };
        CheckOutput {
            findings,
            probes: probes + usize::from(live.baseline_probe),
            completed,
            precondition: Precondition { met, detail },
        }
    }
}

#[cfg(test)]
mod tests {
    /// Each text is counted once, not once per hit (by the bytes walked, not by time, ER-12; the C122 lesson of 2026-11-18).
    #[test]
    fn a_file_with_many_hits_is_counted_once_not_once_per_hit() {
        let text: String = (0..2000)
            .map(|i| format!("    TerminateProcess(h{i}, 1);\n    let s = \"taskkill\";\n"))
            .collect();
        crate::check::jsre::WALKED.with(|w| w.set(0));
        assert_eq!(super::pid_kills(&text).len(), 4000);
        let walked = crate::check::jsre::WALKED.with(|w| w.get());
        assert!(
            walked <= 4 * text.len(),
            "walked {walked} bytes of a {}-byte file: counted once per hit, not once per file",
            text.len()
        );
    }
}

//! `dev ci guardian-as-user`: runs the orphan guardian's acting tests as a non-root user (the port of
//! `conformance/ci/guardian-as-user.sh`; ADR 0076 amendment 2026-11-09; docs/plans/ci-in-rust.md, WP-5). The Linux CI containers run as
//! root, and the guardian is off for root, so the crates job alone never runs the guardian's Linux code (`exe_of` through `/proc`,
//! `owner_holds_pipe`) in acting mode: as root those tests assert the root behaviour instead.
//!
//! Run from `crates/`: builds the `paddock-proc` and `paddock-chromium` unit tests (all features), then runs the guardian tests and
//! `paddock-chromium`'s owner-killed test as `PADDOCK_TEST_UID` (default 65534, nobody) through `setpriv`, with a private `TMPDIR` and
//! `HOME`. As root it drops to that user; run by a user it runs the tests directly. Each failure prints one `::error::` line with the
//! command, its exit code and the next step (ER-27); the job summary says what ran.
//!
//! Everything that starts a program, asks who runs it or changes an owner sits behind [`Machine`], so the root path (which a test cannot
//! take: it would need `sudo`) is tested with a fake that records the command lines. Both programs run with a limit (ER-32): the build
//! `PADDOCK_GUARDIAN_BUILD_TIMEOUT` seconds (default 600), each test run `PADDOCK_GUARDIAN_TEST_TIMEOUT` (default 300). The basis is
//! the Linux crates job's recent runs: 193 s p90 for the whole job, 5 s median for this step (docs/benchmarks.md, "Orphan guardian
//! step"); the shell had no limit, so these only end a hang.

use super::Step;
use crate::ci_tool::{Output, Ran, ToolCall};
use clap::Args as ClapArgs;
use std::collections::HashMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

/// `dev ci guardian-as-user` (no arguments: `PADDOCK_TEST_UID` and the job's summary file come from the environment).
#[derive(ClapArgs, Debug)]
pub struct GuardianAsUserArgs {}

/// The short name the CLI uses.
pub type Args = GuardianAsUserArgs;

const NAME: &str = "guardian-as-user";

/// What the step needs from the machine.
pub trait Machine {
    /// The effective user id of this process.
    fn euid(&self) -> Result<u32, String>;
    /// Whether `program` is on `PATH`.
    fn has_program(&self, program: &str) -> bool;
    /// Runs a program (its `run:` and `ran:` lines go to `log`).
    fn run(&self, call: &ToolCall, log: &mut dyn Write) -> Result<Ran, String>;
    /// Gives a folder to a user and group id.
    fn chown(&self, path: &Path, uid: u32) -> Result<(), String>;
}

/// The machine this process runs on.
pub struct Real<'a> {
    /// The job's environment.
    pub env: &'a HashMap<String, String>,
}

impl Machine for Real<'_> {
    fn euid(&self) -> Result<u32, String> {
        let ran = ToolCall::new("id")
            .args(["-u"])
            .timeout(Duration::from_secs(20))
            .run(self.env, &mut std::io::sink())?;
        ran.stdout
            .trim()
            .parse()
            .map_err(|_| format!("`id -u` said '{}'", ran.stdout.trim()))
    }

    fn has_program(&self, program: &str) -> bool {
        super::on_path(self.env, program)
    }

    fn run(&self, call: &ToolCall, log: &mut dyn Write) -> Result<Ran, String> {
        call.run(self.env, log)
    }

    fn chown(&self, path: &Path, uid: u32) -> Result<(), String> {
        #[cfg(unix)]
        {
            std::os::unix::fs::chown(path, Some(uid), Some(uid)).map_err(|e| e.to_string())
        }
        #[cfg(not(unix))]
        {
            let _ = (path, uid);
            Err("changing an owner is not done on this OS".to_string())
        }
    }
}

/// What the build and the tests may see besides the base list: the gates' list (`pre_push::exec::PASS`: the toolchain, the compile cache,
/// the temp folder), without its `PADDOCK_*` (the job's `PADDOCK_DEV_TOKEN` matches it, and no program here needs it), plus what this step
/// reads: the image's `DUCKDB_*` and `CHROMIUM_TEST_PATH` (the owner-killed test starts a real browser), the sandbox opt-in of the job
/// (the container runs as root) and the settings of the step itself, `RUSTDOCFLAGS` and `RUSTC_WORKSPACE_WRAPPER` as cargo's cache key
/// reads them.
pub fn child_pass() -> Vec<&'static str> {
    const EXTRA: &[&str] = &[
        "DUCKDB_*",
        "CHROMIUM_TEST_PATH",
        "RUSTDOCFLAGS",
        "RUSTC_WORKSPACE_WRAPPER",
        "PADDOCK_BROWSER_NO_SANDBOX",
        "PADDOCK_TEST_UID",
        "PADDOCK_PROC_*",
        "PADDOCK_CI_*",
    ];
    crate::pre_push::exec::PASS
        .iter()
        .copied()
        .filter(|n| *n != "PADDOCK_*")
        .chain(EXTRA.iter().copied())
        .collect()
}

/// The test binary of a unit-test target in cargo's `--no-run` output: the last `Executable unittests src/lib.rs (<path>/<crate>-<hash>)`.
pub fn exe_of(build_output: &str, krate: &str) -> Option<String> {
    let re = regex::Regex::new(&format!(
        r"(?m)Executable unittests src/lib\.rs \((.*/{}-[0-9a-f]*)\)\s*$",
        regex::escape(krate)
    ))
    .ok()?;
    re.captures_iter(build_output).last().map(|c| c[1].to_string())
}

fn seconds(env: &HashMap<String, String>, key: &str, default: u64) -> Duration {
    Duration::from_secs(
        env.get(key)
            .and_then(|v| v.parse::<u64>().ok())
            .filter(|n| *n > 0)
            .unwrap_or(default),
    )
}

/// A private folder (mode 0700) under the temp folder that is removed at the end.
struct Private(PathBuf);

impl Private {
    fn make(base: &Path) -> std::io::Result<Private> {
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| d.subsec_nanos());
        let dir = base.join(format!("guardian-as-user.{}.{nanos}", std::process::id()));
        #[cfg(unix)]
        {
            use std::os::unix::fs::DirBuilderExt;
            std::fs::DirBuilder::new().recursive(true).mode(0o700).create(&dir)?;
        }
        #[cfg(not(unix))]
        std::fs::create_dir_all(&dir)?;
        Ok(Private(dir))
    }
}

impl Drop for Private {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

/// The command over the real machine.
pub fn run(env: &HashMap<String, String>, out: &mut dyn Write) -> i32 {
    run_with(&Real { env }, env, out)
}

/// The command over a machine (tests).
pub fn run_with(machine: &dyn Machine, env: &HashMap<String, String>, out: &mut dyn Write) -> i32 {
    let mut step = Step {
        env,
        out,
        windows: false,
        name: NAME,
    };
    let mut uid: u32 = match step.var("PADDOCK_TEST_UID").map(str::parse) {
        None => 65534,
        Some(Ok(u)) => u,
        Some(Err(_)) => {
            return step.fail(
                format!(
                    "PADDOCK_TEST_UID is '{}', not a user id.",
                    step.var("PADDOCK_TEST_UID").unwrap_or("")
                ),
                "set it to a number, or leave it unset (65534, nobody).",
            );
        }
    };
    let summary = PathBuf::from(step.var("GITHUB_STEP_SUMMARY").unwrap_or("/dev/null"));
    let euid = match machine.euid() {
        Ok(u) => u,
        Err(e) => {
            return step.fail(
                format!("cannot tell who runs this step: {e}."),
                "check that `id` is installed in the image.",
            );
        }
    };
    let as_user: Vec<String> = if euid == 0 {
        if !machine.has_program("setpriv") {
            return step.fail(
                format!("setpriv (util-linux) is missing, so the tests cannot run as uid {uid}."),
                "install util-linux in the image.",
            );
        }
        [
            "setpriv".to_string(),
            format!("--reuid={uid}"),
            format!("--regid={uid}"),
            "--clear-groups".into(),
            "--no-new-privs".into(),
            "--".into(),
        ]
        .to_vec()
    } else {
        uid = euid;
        Vec::new()
    };

    step.say("Building the paddock-proc and paddock-chromium unit tests");
    let Some(temp) = super::temp_folder(env) else {
        return step.fail(
            "no temp folder (TMPDIR, RUNNER_TEMP, TEMP or TMP) is set.",
            "run this step in a runner job.",
        );
    };
    let private = match Private::make(&temp) {
        Ok(p) => p,
        Err(e) => {
            return step.fail(
                format!("cannot make a private folder under {}: {e}.", temp.display()),
                "make the temp folder writable.",
            );
        }
    };
    let build_log = private.0.join("build.log");
    // The build log lives in the private folder of the user's tests too, so the private folder is made first and handed over after.
    let mut log = Vec::new();
    let build = ToolCall::new("cargo")
        .args(["test", "--no-run", "--all-features", "-p", "paddock-proc", "-p", "paddock-chromium"])
        .pass(child_pass())
        .timeout(seconds(env, "PADDOCK_GUARDIAN_BUILD_TIMEOUT", 600))
        .output(Output::File(build_log.clone()));
    let ran = machine.run(&build, &mut log);
    flush(&mut step, &mut log);
    let ran = match ran {
        Ok(r) => r,
        Err(e) => {
            return step.fail(
                format!("cargo could not be started: {e}"),
                "check that cargo is on PATH in the image.",
            );
        }
    };
    if !ran.success {
        // The shell's output, line for line (it stays the reference until WP-11 deletes it): the last lines of the build log
        // unindented (`tail -n 40`), then its one error line, whose next step is the sentence after the semicolon.
        let lines: Vec<&str> = ran.stderr.lines().collect();
        for l in &lines[lines.len().saturating_sub(crate::ci_tool::TAIL_LINES)..] {
            step.say(l);
        }
        step.say("::error::guardian-as-user: cargo test --no-run failed (output above); fix the build first");
        return 1;
    }
    let (Some(proc_bin), Some(chromium_bin)) = (exe_of(&ran.stderr, "paddock_proc"), exe_of(&ran.stderr, "paddock_chromium")) else {
        return step.fail(
            format!(
                "the unit test binaries were not found in cargo's output; see {}.",
                build_log.display()
            ),
            "check that both packages have unit tests in src/lib.rs.",
        );
    };

    if euid == 0
        && let Err(e) = machine.chown(&private.0, uid)
    {
        return step.fail(
            format!("cannot give {} to uid {uid}: {e}.", private.0.display()),
            "check the image's users.",
        );
    }
    let guardian_log = private.0.join("guardian.log");
    let mut text = String::from("### Orphan guardian as a user\n\n| Tests | As | Result | Time |\n|---|---|---|---|\n");
    let mut results = Vec::new();
    for (bin, filter) in [
        (&proc_bin, "guardian::"),
        (&chromium_bin, "launch::tests::a_browser_whose_owner_is_killed"),
    ] {
        let mut argv = as_user.clone();
        argv.extend([
            "env".to_string(),
            format!("TMPDIR={}", private.0.display()),
            format!("HOME={}", private.0.display()),
            format!("PADDOCK_PROC_GUARDIAN_LOG={}", guardian_log.display()),
            bin.clone(),
            filter.to_string(),
        ]);
        step.say(format!("Running as uid {uid}: {}", argv.join(" ")));
        let started = Instant::now();
        let call = ToolCall::new(argv[0].clone())
            .args(argv[1..].iter().cloned())
            .pass(child_pass())
            .timeout(seconds(env, "PADDOCK_GUARDIAN_TEST_TIMEOUT", 300))
            .output(Output::Stream);
        let mut log = Vec::new();
        let ran = machine.run(&call, &mut log);
        flush(&mut step, &mut log);
        let took = started.elapsed().as_secs();
        let failure = match ran {
            Ok(r) if r.success => None,
            Ok(r) => Some(r.how),
            Err(e) => Some(e),
        };
        if let Some(how) = failure {
            match std::fs::read_to_string(&guardian_log) {
                Ok(t) => {
                    step.say("The guardian's log:");
                    step.say(t.trim_end());
                }
                Err(_) => step.say(format!("The guardian wrote no log ({})", guardian_log.display())),
            }
            results.push(format!("| `{filter}` | uid {uid} | failed ({how}) | {took} s |\n"));
            text.push_str(&results.join(""));
            write_summary(&summary, &text);
            return step.fail(
                format!("`{filter}` failed as uid {uid} ({how}, {took} s): {}.", argv.join(" ")),
                "run the same command in the CI image to see it.",
            );
        }
        results.push(format!("| `{filter}` | uid {uid} | passed | {took} s |\n"));
    }
    text.push_str(&results.join(""));
    write_summary(&summary, &text);
    step.say(format!("The guardian's acting tests passed as uid {uid}"));
    0
}

fn flush(step: &mut Step<'_>, log: &mut Vec<u8>) {
    for l in String::from_utf8_lossy(log).lines() {
        step.say(l);
    }
    log.clear();
}

/// Appends to the job's summary file (`/dev/null` without one); a summary that cannot be written never fails the step.
fn write_summary(path: &Path, text: &str) {
    if let Ok(mut f) = std::fs::OpenOptions::new().append(true).create(true).open(path) {
        let _ = f.write_all(text.as_bytes());
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;

    // conformance: layout-guess — a sample of cargo's own output, or the test binary it names; not a computed layout
    const BUILD: &str = "   Compiling paddock-proc v0.1.0\n  Executable unittests src/lib.rs (target/debug/deps/paddock_proc-0123abcd)\n  Executable tests/it/main.rs (target/debug/deps/it-ff)\n  Executable unittests src/lib.rs (target/debug/deps/paddock_chromium-9f8e7d)\n";

    /// A scripted machine: who runs it, what the programs say, what was started.
    struct Fake {
        euid: u32,
        setpriv: bool,
        build_ok: bool,
        fail_filter: Option<&'static str>,
        started: Mutex<Vec<String>>,
        chowned: Mutex<Vec<(PathBuf, u32)>>,
        build_text: &'static str,
    }

    impl Fake {
        fn new(euid: u32) -> Fake {
            Fake {
                euid,
                setpriv: true,
                build_ok: true,
                fail_filter: None,
                started: Mutex::new(Vec::new()),
                chowned: Mutex::new(Vec::new()),
                build_text: BUILD,
            }
        }
    }

    impl Machine for Fake {
        fn euid(&self) -> Result<u32, String> {
            Ok(self.euid)
        }
        fn has_program(&self, program: &str) -> bool {
            program != "setpriv" || self.setpriv
        }
        fn run(&self, call: &ToolCall, _: &mut dyn Write) -> Result<Ran, String> {
            self.started.lock().unwrap().push(call.display());
            let cargo = call.display().starts_with("cargo ");
            let failed = self.fail_filter.is_some_and(|f| call.display().ends_with(f)) || (cargo && !self.build_ok);
            Ok(Ran {
                success: !failed,
                how: if failed { "exit 101".into() } else { "exit 0".into() },
                stdout: String::new(),
                stderr: if cargo { self.build_text.to_string() } else { String::new() },
            })
        }
        fn chown(&self, path: &Path, uid: u32) -> Result<(), String> {
            self.chowned.lock().unwrap().push((path.to_path_buf(), uid));
            Ok(())
        }
    }

    fn env(dir: &Path) -> HashMap<String, String> {
        [
            ("TMPDIR".to_string(), dir.display().to_string()),
            ("GITHUB_STEP_SUMMARY".to_string(), dir.join("summary").display().to_string()),
        ]
        .into()
    }

    fn go(f: &Fake, extra: &[(&str, &str)]) -> (i32, String, String) {
        let dir = super::super::canonical_tempdir();
        let mut e = env(dir.path());
        e.extend(extra.iter().map(|(k, v)| (k.to_string(), v.to_string())));
        let mut out = Vec::new();
        let code = run_with(f, &e, &mut out);
        (
            code,
            String::from_utf8(out).unwrap(),
            std::fs::read_to_string(dir.path().join("summary")).unwrap_or_default(),
        )
    }

