        );
        for (i, filter) in [(1, "guardian::"), (2, "launch::tests::a_browser_whose_owner_is_killed")] {
            assert!(
                started[i].starts_with("setpriv --reuid=4242 --regid=4242 --clear-groups --no-new-privs -- env TMPDIR="),
                "{}",
