    #[test]
    fn as_a_user_the_tests_run_directly_as_that_user_and_the_default_uid_is_nobody() {
        let f = Fake::new(501);
        let (code, out, _) = go(&f, &[("PADDOCK_TEST_UID", "4242")]);
        assert_eq!(code, 0, "{out}");
        let started = f.started.lock().unwrap().clone();
        assert!(started[1].starts_with("env TMPDIR="), "no setpriv: {}", started[1]);
        assert!(out.contains("Running as uid 501: env "), "{out}");
        assert!(f.chowned.lock().unwrap().is_empty());
        let (_, out, _) = go(&Fake::new(0), &[]);
        assert!(out.contains("Running as uid 65534: setpriv --reuid=65534"), "{out}");
    }

    #[test]
    fn every_failure_is_one_error_line_with_the_command_and_the_next_step() {
        let mut no_setpriv = Fake::new(0);
        no_setpriv.setpriv = false;
        let (code, out, _) = go(&no_setpriv, &[]);
        assert_eq!(code, 1);
        assert_eq!(
            out,
            "::error::guardian-as-user: setpriv (util-linux) is missing, so the tests cannot run as uid 65534. Next step: install util-linux in the image.\n"
        );
        let mut broken = Fake::new(501);
        broken.build_ok = false;
        let (code, out, _) = go(&broken, &[]);
        assert_eq!(code, 1);
        assert_eq!(out.lines().filter(|l| l.starts_with("::error::")).count(), 1, "{out}");
        assert!(
            out.contains("::error::guardian-as-user: cargo test --no-run failed (output above); fix the build first"),
            "{out}"
        );
        let mut lost = Fake::new(501);
        lost.build_text = "Compiling only\n";
        let (code, out, _) = go(&lost, &[]);
        assert_eq!(code, 1);
        assert!(
            out.contains("the unit test binaries were not found in cargo's output; see "),
            "{out}"
        );
        let mut red = Fake::new(501);
        red.fail_filter = Some("guardian::");
        let (code, out, summary) = go(&red, &[]);
        assert_eq!(code, 1);
        assert!(out.contains("The guardian wrote no log ("), "{out}");
        assert!(
            out.contains("::error::guardian-as-user: `guardian::` failed as uid 501 (exit 101, "),
            "{out}"
        );
        assert!(out.contains("run the same command in the CI image to see it."), "{out}");
        assert!(summary.contains("| `guardian::` | uid 501 | failed (exit 101) |"), "{summary}");
        let (code, out, _) = go(&Fake::new(501), &[("PADDOCK_TEST_UID", "nobody")]);
        assert_eq!(code, 1);
        assert!(out.contains("PADDOCK_TEST_UID is 'nobody', not a user id."), "{out}");
    }
}

//! `dev ci kept-clone`: the kept clone of a host job (the port of `conformance/ci/kept-clone.sh` and the action `.gitea/actions/kept-clone`;
//! ADR 0025, "Kept clones"; docs/plans/ci-in-rust.md, WP-5).
//!
//! A host runner checks out into a per-job folder that is deleted afterwards, so every job paid for a full fetch and a write of the whole
//! tree. Instead each job slot keeps ONE git clone in its own kept folder (`ci isolation path src <name>`), brought to the job's exact
//! commit by a fetch of that commit and a checkout, so only what changed since the slot's last job crosses the network or the disk, and a
//! profile (`conformance/ci/checkout-profiles.txt`) leaves out the paths the job never reads.
//!
//! The caller first runs `actions/checkout` sparse and partial (the bootstrap folders). This step then:
//!
//! 1. resolves the slot's kept folder (per slot, so concurrent jobs never share a clone);
//! 2. makes the clone (no checkout, `blob:none`, depth 1) when it is missing, broken, of another repository, marked by nobody, carries a
//!    git config key this step did not write, or is larger than `PADDOCK_KEPT_CLONE_MAX_MIB` (default 3072); a tag run (`--fresh`) always
//!    makes it again;
//! 3. cleans a reused clone, fetches the exact commit, writes the profile's sparse patterns, checks the commit out and re-applies them;
//! 4. verifies: HEAD is the commit, the tree has no change or stray file, no excluded path exists;
//! 5. exports `PADDOCK_WORKSPACE` and, off Windows, leaves a link at the work folder.
//!
//! Every phase is bounded (`PADDOCK_KEPT_CLONE_TIMEOUT` seconds, default 900; one phase's own limit `PADDOCK_KEPT_CLONE_TIMEOUT_<ID>`) and logs its duration (ER-27). A clone that cannot be made
//! never fails the job, and neither does a phase that hangs: a phase that fails is retried once on a new clone (stale `.git` locks removed
//! first), and then the work folder is expanded to the profile instead (one `::warning::`; only the compile cache of the workspace crates
//! is lost). The clone's `.git` survives between jobs and is shared by every job of the slot, so nothing in it is trusted: every git
//! command runs with `core.hooksPath` on an empty folder this step owns, `.git/hooks` is emptied, `info/attributes`, `info/exclude` and
//! `refs/replace` are removed, and a local config key outside an allow-list makes the clone be made again.
//! The checkout's credentials (its http extra header) reach git through the environment, never a command line, never kept.

use super::phase::{ClockMark, Held, Phase, bounded_marked};
use super::{Step, folder_name, isolation_full};
use crate::ci_isolation::home;
use crate::ci_tool::{NETWORK_ENV, ToolCall};
use crate::safe_remove;
use clap::Args as ClapArgs;
use std::collections::HashMap;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// `dev ci kept-clone`.
#[derive(ClapArgs, Debug)]
pub struct KeptCloneArgs {
    /// Folder name under the CI home's `src/` (the job's slot is appended): one per repository and job.
    #[arg(long)]
    pub name: String,
    /// The checkout profile of `conformance/ci/checkout-profiles.txt` (`full` leaves nothing out).
    #[arg(long)]
    pub profile: String,
    /// Never reuse the slot's clone, make it again (a tag run).
    #[arg(long)]
    pub fresh: bool,
    /// The profile file (default: `KEPT_CLONE_PROFILES`, else `conformance/ci/checkout-profiles.txt` of the action's checkout).
    #[arg(long)]
    pub profiles: Option<PathBuf>,
}

/// The short name the CLI uses.
pub type Args = KeptCloneArgs;

const NAME: &str = "kept-clone";

/// Local config keys a clone of this step may carry: what git itself writes for a partial, shallow clone, the remote, and the sparse
/// settings this step sets. A key such as `core.autocrlf`, `core.fsmonitor`, `core.sshCommand`, `credential.helper` or an include changes
/// what a git command does, so the clone that carries one is not reused.
const ALLOWED_KEYS: &str = r"^(core\.(repositoryformatversion|filemode|bare|logallrefupdates|ignorecase|precomposeunicode|symlinks|sparsecheckout|sparsecheckoutcone)|extensions\.(partialclone|objectformat)|remote\.origin\.(url|fetch|tagopt|promisor|partialclonefilter)|branch\.[^.=]+\.(remote|merge))$";

/// Tests only: a file the test's hanging git writes; each phase's limit counts from it (ADR 0103, "Hang-point signal").
const CLOCK_MARK: &str = "PADDOCK_KEPT_CLONE_CLOCK_MARK";

/// The bound of a git command outside a phase (reading the work folder, the health probe, the fallback's expansion): the default phase
/// limit. `PADDOCK_KEPT_CLONE_TIMEOUT` is seconds per phase; the shell runs these reads unbounded, so a short phase limit must not end
/// them (it failed the job under load with the hung-phase test's 1 s limit, where the shell went on).
const OUTSIDE_PHASE_LIMIT: Duration = Duration::from_secs(900);

thread_local! {
    /// Set on a phase's own thread: its git commands get that phase's limit.
    static IN_PHASE: std::cell::Cell<Option<Duration>> = const { std::cell::Cell::new(None) };
}

/// The phases, each with its own limit `PADDOCK_KEPT_CLONE_TIMEOUT_<ID>` over the general `PADDOCK_KEPT_CLONE_TIMEOUT` (the shell's
/// `phase <ID>`): a job (or a test) can bound one phase tightly without the others meeting that bound.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PhaseId {
    Resolve,
    Create,
    Clean,
    Fetch,
    Checkout,
    Verify,
    Link,
}

impl PhaseId {
    /// The variable of the phase's own limit.
    fn var(self) -> &'static str {
        match self {
            PhaseId::Resolve => "PADDOCK_KEPT_CLONE_TIMEOUT_RESOLVE",
            PhaseId::Create => "PADDOCK_KEPT_CLONE_TIMEOUT_CREATE",
            PhaseId::Clean => "PADDOCK_KEPT_CLONE_TIMEOUT_CLEAN",
            PhaseId::Fetch => "PADDOCK_KEPT_CLONE_TIMEOUT_FETCH",
            PhaseId::Checkout => "PADDOCK_KEPT_CLONE_TIMEOUT_CHECKOUT",
            PhaseId::Verify => "PADDOCK_KEPT_CLONE_TIMEOUT_VERIFY",
            PhaseId::Link => "PADDOCK_KEPT_CLONE_TIMEOUT_LINK",
        }
    }
}

/// The phase's limit: its own variable when it is a whole number above 0 (digits, no leading zero, as the shell tests it), else
/// `general`.
fn phase_limit(env: &HashMap<String, String>, id: PhaseId, general: Duration) -> Duration {
    env.get(id.var())
        .filter(|v| !v.is_empty() && !v.starts_with('0') && v.bytes().all(|b| b.is_ascii_digit()))
        .and_then(|v| v.parse::<u64>().ok())
        .map_or(general, Duration::from_secs)
}

/// What one phase writes (what the shell's `$scratch/err` and the `run:` lines were), and whether one of its git commands ended at its
/// limit. Each phase writes to its own, set on the phase's own thread ([`PHASE_OUT`]): a phase abandoned at its bound can still finish
/// a git command later, and that command then writes only here, where nobody reads any more. With one shared state it set the next
/// phase's flag, and that phase (`create the clone`) reported a hang it never had (1 of 80 parity runs under load, 2026-11-15).
#[derive(Default)]
struct PhaseOut {
    /// The error output.
    err: Mutex<String>,
    /// `run:` and `ran:` lines of the noisy git commands, flushed to the job log after the phase.
    log: Mutex<Vec<u8>>,
    /// A git command ended at its limit (the phase is then reported as one that did not finish, as the shell's `bounded` did).
    timed_out: AtomicBool,
    /// The phase was abandoned at its bound: its thread may still run, but it starts no git command, removes nothing and writes no
    /// file any more ([`Kc::live`]), because the next phase may already be removing or making the same folder. The shell's `bounded`
    /// ends the whole function's process tree instead.
    abandoned: AtomicBool,
}

thread_local! {
    /// Set on a phase's own thread: where its git commands and notes write.
    static PHASE_OUT: std::cell::RefCell<Option<Arc<PhaseOut>>> = const { std::cell::RefCell::new(None) };
    /// Set on a phase's own thread: the programs its git commands start, which the phase ends if it is abandoned.
    static PHASE_HELD: std::cell::RefCell<Option<Arc<Held>>> = const { std::cell::RefCell::new(None) };
}

/// What the phases share: the job's environment, the credentials for git, the folders, and the step's own output: what was written
/// outside any phase, and what the last phase wrote once it ended or was abandoned (`last_lines` reads it).
struct Kc {
    env: HashMap<String, String>,
    windows: bool,
    limit: Duration,
    /// The checkout's `http.*.extraheader` value, for git's environment only.
    header: Option<String>,
    /// An empty folder this step owns: `core.hooksPath` of every git command.
    hooks: PathBuf,
    home: Option<PathBuf>,
    /// The step's output outside the phases, and the last phase's error output (cleared at the start of each phase).
    own: Arc<PhaseOut>,
}

impl Kc {
    /// Where this thread writes: its phase's output on a phase's thread, else the step's own.
    fn out(&self) -> Arc<PhaseOut> {
        PHASE_OUT.with(|p| p.borrow().clone()).unwrap_or_else(|| self.own.clone())
    }

    /// Takes a phase's output as the step's: its error output replaces the last phase's, its log lines are appended. A command the
    /// phase still runs writes into `phase` only, after this.
    fn adopt(&self, phase: &PhaseOut) {
        let err = phase.err.lock().map(|e| e.clone()).unwrap_or_default();
        if let Ok(mut e) = self.own.err.lock() {
            *e = err;
        }
        let log = phase.log.lock().map(|mut l| std::mem::take(&mut *l)).unwrap_or_default();
        if let Ok(mut l) = self.own.log.lock() {
            l.extend_from_slice(&log);
        }
    }

    /// The error output so far (outside a phase, or the last phase's).
    fn err_text(&self) -> String {
        self.own.err.lock().map(|e| e.clone()).unwrap_or_default()
    }

    /// `Err` once this thread's phase was abandoned: every git command, removal and file write of a phase asks first.
    fn live(&self) -> Result<(), String> {
        if self.out().abandoned.load(Ordering::SeqCst) {
            Err("the phase was abandoned".into())
        } else {
            Ok(())
        }
    }

    fn note(&self, text: impl AsRef<str>) {
        // A command that wrote nothing (a git ended at its limit) adds nothing, as the shell's `$scratch/err` (no blank line).
        if text.as_ref().is_empty() {
            return;
        }
        if let Ok(mut e) = self.out().err.lock() {
            e.push_str(text.as_ref());
            if !text.as_ref().ends_with('\n') {
                e.push('\n');
            }
        }
    }

    /// The last four whole, non-blank lines of the phase's error output on one line (never cut in the middle of a path).
    fn last_lines(&self) -> String {
        let text = self.err_text();
        let lines: Vec<&str> = text.split('\n').filter(|l| !l.trim().is_empty()).collect();
        let from = lines.len().saturating_sub(4);
        lines[from..].join("\n").replace(['\r', '\n'], " ")
    }

    /// One git command with this step's guard: no hooks, no replace objects, no prompts, the credentials through the environment.
    /// `noisy`: the command is logged and a failure names it in the phase's error output (the shell's `g`; `gq` is the quiet probe).
    /// `Ok` is standard output without the trailing newlines; `Err` is how it ended.
    fn git(&self, noisy: bool, args: &[&str]) -> Result<String, String> {
        self.live()?;
        let mut call = ToolCall::new("git")
            .args(["-c".to_string(), format!("core.hooksPath={}", self.hooks.display())])
            .args(args.iter().map(|a| a.to_string()))
            .pass(NETWORK_ENV.iter().copied())
            .pass(["GIT_CONFIG_NOSYSTEM", "GIT_CONFIG_GLOBAL", "GIT_SSL_CAINFO", "GIT_SSL_CAPATH"])
            .env("GIT_TERMINAL_PROMPT", "0")
            .env("GIT_NO_REPLACE_OBJECTS", "1")
            .held_by(PHASE_HELD.with(|h| h.borrow().clone()).unwrap_or_default())
            .timeout(IN_PHASE.with(std::cell::Cell::get).unwrap_or(OUTSIDE_PHASE_LIMIT));
        if let Some(h) = &self.header {
            call = call
                .env("GIT_CONFIG_COUNT", "1")
                .env("GIT_CONFIG_KEY_0", "http.extraheader")
                .env("GIT_CONFIG_VALUE_0", h.clone())
                .secret(h.clone());
        }
        let sub = subcommand(args);
        // The `run:` lines go to a buffer of this command, then to the thread's log: a command never holds the log while it runs (a hung
        // one would block whoever reads the log next).
        let ran = if noisy {
            let mut buf = Vec::new();
            let ran = call.run(&self.env, &mut buf);
            if let Ok(mut log) = self.out().log.lock() {
                log.extend_from_slice(&buf);
            }
            ran
        } else {
            call.run(&self.env, &mut io::sink())
        };
        match ran {
            Ok(r) => {
                self.note(&r.stderr);
                if r.success {
                    return Ok(r.stdout.trim_end_matches(['\n', '\r']).to_string());
                }
                if noisy {
                    self.note(format!("{NAME}: git {sub} failed ({})", r.how));
                }
                if r.how.starts_with("timed out") {
                    self.out().timed_out.store(true, Ordering::SeqCst);
                }
                Err(r.how)
            }
            Err(e) => {
                self.note(&e);
                Err(e)
            }
        }
    }

    /// `rm -rf target`, guarded: only strictly under `root`, a link as a link ([`safe_remove`]).
    fn remove(&self, root: &Path, target: &Path) -> Result<(), String> {
        self.live()?;
        safe_remove::remove_under(root, target, self.home.as_deref())
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
}

/// The git subcommand: the first word that is not `-C <dir>` or `-c <key=value>` (for the failure line).
fn subcommand(args: &[&str]) -> String {
    let mut skip = false;
    for a in args {
        if skip {
            skip = false;
            continue;
        }
        match *a {
            "-C" | "-c" => skip = true,
            x if x.starts_with('-') => {}
            x => return x.to_string(),
        }
    }
    String::new()
}

/// What the profile file leaves out for `profile`: the paths of its `exclude <profile> <path> ...` lines, a trailing `/` dropped.
pub fn excludes_of(text: &str, profile: &str) -> Vec<String> {
    text.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| {
            let mut w = l.split_whitespace();
            let (kind, prof, path) = (w.next()?, w.next()?, w.next()?);
            (kind == "exclude" && prof == profile).then(|| path.trim_end_matches('/').to_string())
        })
        .collect()
}

/// One path segment pattern against a name: `*` is any run of characters, every other character stands for itself; a name that starts with
/// a dot is matched only by a pattern that starts with one (a shell glob without `dotglob`).
fn segment_matches(pattern: &str, name: &str) -> bool {
    if name.starts_with('.') && !pattern.starts_with('.') {
        return false;
    }
    let (p, n): (Vec<char>, Vec<char>) = (pattern.chars().collect(), name.chars().collect());
    let (mut pi, mut ni, mut star, mut mark) = (0, 0, None, 0);
    while ni < n.len() {
        if pi < p.len() && p[pi] == '*' {
            star = Some(pi);
            mark = ni;
            pi += 1;
        } else if pi < p.len() && p[pi] == n[ni] {
            pi += 1;
            ni += 1;
        } else if let Some(s) = star {
            pi = s + 1;
            mark += 1;
            ni = mark;
        } else {
            return false;
        }
    }
    p[pi..].iter().all(|c| *c == '*')
}

/// The paths under `base` that `pattern` (folder names, `*` inside a name) names and that exist (`compgen -G`).
pub fn glob_expand(base: &Path, pattern: &str) -> Vec<PathBuf> {
    let mut found = vec![base.to_path_buf()];
    for seg in pattern.split('/').filter(|s| !s.is_empty()) {
        let mut next = Vec::new();
        for dir in &found {
            if seg.contains('*') {
                let Ok(rd) = std::fs::read_dir(dir) else { continue };
                let mut names: Vec<String> = rd
                    .flatten()
                    .filter_map(|e| e.file_name().into_string().ok())
                    .filter(|n| segment_matches(seg, n))
                    .collect();
                names.sort();
                next.extend(names.into_iter().map(|n| dir.join(n)));
            } else {
                let p = dir.join(seg);
                if std::fs::symlink_metadata(&p).is_ok() {
                    next.push(p);
                }
            }
        }
        found = next;
    }
    found
}

/// The keys of `git config --local --list` output that this step did not write: the first one, lower-cased (empty when there is none).
fn foreign_key_of(list: &str) -> String {
    // A pattern that cannot be built (it can not, a test builds it) would count every key as foreign: the clone is made again.
    let Ok(allowed) = regex::Regex::new(ALLOWED_KEYS) else {
        return "(the allow-list)".to_string();
    };
    list.lines()
        .map(|l| l.split('=').next().unwrap_or("").to_lowercase())
        .find(|k| !allowed.is_match(k))
        .unwrap_or_default()
}

/// The size of a clone in KiB from `git count-objects -v` (the sum of `size:` and `size-pack:`).
fn clone_kib_of(counts: &str) -> u64 {
    counts
        .lines()
        .filter(|l| l.starts_with("size: ") || l.starts_with("size-pack: "))
        .filter_map(|l| l.split_whitespace().nth(1)?.parse::<u64>().ok())
        .sum()
}

/// The `.angular/cache` links of a clone (a symlink, a junction on Windows) up to six levels deep, outside `node_modules` and `.git`.
/// They point to a kept folder outside the clone and are removed by themselves first: a clean must never reach the target through them.
fn angular_cache_links(stable: &Path) -> Vec<PathBuf> {
    fn is_link(p: &Path, meta: &std::fs::Metadata) -> bool {
        meta.file_type().is_symlink() || (cfg!(windows) && std::fs::read_link(p).is_ok())
    }
    fn walk(dir: &Path, depth: usize, out: &mut Vec<PathBuf>) {
        let Ok(rd) = std::fs::read_dir(dir) else { return };
        for e in rd.flatten() {
            let p = e.path();
            let Ok(meta) = std::fs::symlink_metadata(&p) else { continue };
            let name = e.file_name();
            if name == "cache" && dir.file_name().is_some_and(|d| d == ".angular") && is_link(&p, &meta) {
                out.push(p.clone());
            }
            if depth < 6 && meta.is_dir() && !is_link(&p, &meta) && name != "node_modules" && name != ".git" {
                walk(&p, depth + 1, out);
            }
        }
    }
    let mut out = Vec::new();
    walk(stable, 1, &mut out);
    out
}

/// The command over the real machine.
pub fn run(env: &HashMap<String, String>, windows: bool, args: &Args, out: &mut dyn Write, err: &mut dyn Write) -> i32 {
    let mut step = Step {
        env,
        out,
        windows,
        name: NAME,
    };
    let Some(os) = step.var("RUNNER_OS").map(str::to_string) else {
        return step.fail("RUNNER_OS is not set.", "run this step in a runner job.");
    };
    // Linux jobs run in a container with a fixed workspace.
    if os == "Linux" {
        return 0;
    }
    let started = Instant::now();
    let limit = Duration::from_secs(
        env.get("PADDOCK_KEPT_CLONE_TIMEOUT")
            .and_then(|v| v.parse::<u64>().ok())
            .filter(|n| *n > 0)
            .unwrap_or(900),
    );
    let max_mib: u64 = env.get("PADDOCK_KEPT_CLONE_MAX_MIB").and_then(|v| v.parse().ok()).unwrap_or(3072);
    let profile = args.profile.clone();
    let profiles: PathBuf = args
        .profiles
        .clone()
        .or_else(|| step.var("KEPT_CLONE_PROFILES").map(PathBuf::from))
        .or_else(|| {
            step.var("GITHUB_ACTION_PATH")
                .map(|p| Path::new(p).join("../../../conformance/ci/checkout-profiles.txt"))
        })
        .unwrap_or_else(|| {
            PathBuf::from(step.var("GITHUB_WORKSPACE").unwrap_or("."))
                .join("conformance")
                .join("ci")
                .join("checkout-profiles.txt")
        });
    let hint = "list and end processes using the CI home's src folder on the runner (a git or an editor left from an earlier job), then re-run the job.";

    // --- the profile ---
    let excludes = excludes_of(&std::fs::read_to_string(&profiles).unwrap_or_default(), &profile);
    if profile != "full" && excludes.is_empty() {
        return step.fail(
            format!(
                "profile '{profile}' is not declared in {} (an `exclude {profile} <path>` line).",
                profiles.display()
            ),
            "declare it there, or use 'full'.",
        );
    }

    // --- what the plain checkout left ---
    let Some(work) = step.var("GITHUB_WORKSPACE").map(str::to_string) else {
        return step.fail(
            "GITHUB_WORKSPACE is not set.",
            "run this step in a runner job, after actions/checkout.",
        );
    };
    let ws = match paddock_env::winpath::real(Path::new(&work)) {
        Ok(p) => p,
        Err(e) => {
            return step.fail(
                format!("cannot read the work folder {work}: {e}."),
                "check the runner's work folder.",
            );
        }
    };
    let ws_text = ws.display().to_string();
    // The empty hooks folder goes in the job's temp folder; without one in the environment, beside the work folder (the runner's own
    // per-job folder, which is writable).
    let Some(temp_root) = super::temp_folder(env).or_else(|| ws.parent().map(Path::to_path_buf)) else {
        return step.fail(
            "no folder for the empty hooks folder (no temp variable is set and the work folder has no parent).",
            "run this step in a runner job.",
        );
    };
    let hooks = temp_root.join(format!("paddock-kept-clone-{}", std::process::id()));
    if let Err(e) = std::fs::create_dir_all(&hooks) {
        return step.fail(
            format!("cannot make the empty hooks folder {}: {e}.", hooks.display()),
            "make the runner's temp folder writable.",
        );
    }
    let kc = Arc::new(Kc {
        env: env.clone(),
        windows,
        limit,
        header: None,
        hooks: hooks.clone(),
        home: env.get("HOME").or_else(|| env.get("USERPROFILE")).map(PathBuf::from),
        own: Default::default(),
    });
    let code = run_inner(
        &mut step, kc, args, &profile, &excludes, &ws, &ws_text, started, limit, max_mib, hint, err,
    );
    let _ = std::fs::remove_dir(&hooks);
    code
}

#[allow(clippy::too_many_arguments)]
fn run_inner(
    step: &mut Step<'_>,
    kc: Arc<Kc>,
    args: &Args,
    profile: &str,
    excludes: &[String],
    ws: &Path,
    ws_text: &str,
    started: Instant,
    limit: Duration,
    max_mib: u64,
    hint: &str,
    err: &mut dyn Write,
) -> i32 {
    let git_ws = |kc: &Kc, rest: &[&str]| -> Result<String, String> {
        let mut a = vec!["-C", ws_text];
        a.extend_from_slice(rest);
        kc.git(true, &a)
    };
    let (sha, url) = match (git_ws(&kc, &["rev-parse", "HEAD"]), git_ws(&kc, &["remote", "get-url", "origin"])) {
        (Ok(s), Ok(u)) => (s, u),
        (a, b) => {
            let why = a.err().or(b.err()).unwrap_or_default();
            let _ = write!(err, "{}", kc.err_text());
            return step.fail(
                format!("cannot read the commit and the origin of the work folder {ws_text} ({why})."),
                "run this step after actions/checkout, in the job's checkout.",
            );
        }
    };
    // The checkout's credential header, passed through the environment (git >= 2.31), never on a command line. Read with the quiet
    // probe: a checkout without one is fine.
    let header = kc
        .git(
            false,
            &["-C", ws_text, "config", "--local", "--get-regexp", r"^http\..*\.extraheader$"],
        )
        .ok()
        .and_then(|t| t.lines().next().map(str::to_string))
        .and_then(|l| l.split_once(' ').map(|(_, v)| v.to_string()))
        .filter(|v| !v.is_empty());
    // The shared context is made again with the header (it is immutable behind the Arc).
    let kc = Arc::new(Kc {
        env: kc.env.clone(),
        windows: kc.windows,
        limit: kc.limit,
        header,
        hooks: kc.hooks.clone(),
        home: kc.home.clone(),
        own: Default::default(),
    });
    let mut flow = Flow {
        kc,
        ws: ws.to_path_buf(),
        ws_text: ws_text.to_string(),
        stable: PathBuf::new(),
        sha,
        url,
        excludes: excludes.to_vec(),
        limit,
        hint: hint.to_string(),
    };

    // fallback <why>: build from the work folder, expanded to the profile; never fails the job for lack of a clone.
    macro_rules! fallback {
        ($why:expr) => {{
            step.warn(format!(
                "{}; building from the work folder (the compile cache misses the workspace crates).",
                $why
            ));
            flow.apply_profile(&flow.ws.clone()).ok();
            match flow.kc.git(true, &["-C", &flow.ws_text, "read-tree", "-mu", "HEAD"]) {
                Ok(t) => {
                    if !t.is_empty() {
                        step.say(t);
                    }
                }
                Err(_) => {
                    flow.flush(step);
                    step.say(flow.kc.err_text().trim_end().to_string());
                    step.warn("could not expand the work folder to the profile; steps that read paths outside the bootstrap will fail.");
                }
            }
            flow.flush(step);
            return 0;
        }};
    }

    // --- the slot's kept folder ---
    let folder = folder_name(&args.name);
    let resolved = {
        let (env2, win) = (flow.kc.env.clone(), flow.kc.windows);
        flow.phase(step, PhaseId::Resolve, "resolve the job slot's kept folder", move |_| {
            let (code, o, e) = isolation_full(&env2, win, &["path", "src", &folder]);
            if code == 0 { Ok((o, e)) } else { Err(e) }
        })
    };
    let stable_text = match resolved {
        Ok((path, notes)) => {
            if !notes.is_empty() {
                let _ = writeln!(err, "{notes}");
            }
            path
        }
        Err(Failed(why)) => {
            let _ = writeln!(err, "{why}");
            fallback!("no kept folder of this job's slot (see the message above)");
        }
        Err(Hung) => {
            fallback!("no kept folder of this job's slot (see the message above)");
        }
    };
    let stable = PathBuf::from(&stable_text);
    flow.stable = stable.clone();

    // --- the clone ---
    let mut mode_created = args.fresh;
    if !mode_created && flow.healthy() {
        let kib = flow
            .kc
            .git(false, &["-C", &stable_text, "count-objects", "-v"])
            .map(|t| clone_kib_of(&t))
            .unwrap_or(0);
        let bad = flow.foreign_key();
        if !bad.is_empty() {
            step.warn(format!(
                "the clone at {stable_text} carries the local git config key '{bad}', which this script did not write; starting again."
            ));
            mode_created = true;
        } else if kib > max_mib * 1024 {
            step.say(format!(
                "{NAME}: the clone at {stable_text} is {} MiB, larger than {max_mib} MiB; starting again.",
                kib / 1024
            ));
            mode_created = true;
        }
    } else {
        mode_created = true;
    }
    if mode_created && flow.create(step, err).is_err() {
        fallback!(format!("could not create the clone at {stable_text} ({})", flow.kc.last_lines()));
    }

    // bring_up: clean (a reused clone), fetch, check out, verify; each phase bounded.
    if !flow.bring_up(step, mode_created) {
        step.warn(format!(
            "the clone at {stable_text} could not be brought to {} ({}); removing its locks and making it again.",
            flow.sha,
            flow.kc.last_lines()
        ));
        flow.remove_locks();
        mode_created = true;
        if flow.create(step, err).is_err() {
            fallback!(format!(
                "could not make the clone again at {stable_text} ({})",
                flow.kc.last_lines()
            ));
        }
        if !flow.bring_up(step, mode_created) {
            fallback!(format!(
                "the clone at {stable_text} could not be brought to {} ({})",
                flow.sha,
                flow.kc.last_lines()
            ));
        }
    }
    let files = flow
        .kc
        .git(true, &["-C", &stable_text, "ls-files", "-v"])
        .map(|t| t.lines().filter(|l| !l.starts_with('S')).count())
        .unwrap_or(0);
    flow.flush(step);

    // --- hand over ---
    // RUNNER_OS decides, as in the shell (the runner's OS, not the host's semantics).
    let runner_windows = step.var("RUNNER_OS") == Some("Windows");
    let shown = if runner_windows {
        home::native(&stable_text)
    } else {
        stable_text.clone()
    };
    if let Err(e) = step.append_to("GITHUB_ENV", &format!("PADDOCK_WORKSPACE={shown}")) {
        return step.fail(
            format!("could not export PADDOCK_WORKSPACE: {e}."),
            "run this step in a runner job.",
        );
    }
    // Where the work folder can be replaced (not under act on Windows, which holds it open) a link keeps every path that names it valid.
    if !runner_windows {
        let (ws2, stable2) = (flow.ws.clone(), stable.clone());
        let label = format!("link {ws_text} to {stable_text}");
        if flow
            .phase(step, PhaseId::Link, &label, move |kc| link_work_folder(kc, &ws2, &stable2))
            .is_err()
        {
            step.warn(format!(
                "could not link {ws_text} to {stable_text} ({}); steps build from PADDOCK_WORKSPACE.",
                flow.kc.last_lines()
            ));
        }
    }
    step.say(format!(
        "{NAME}: ready: {} ({}, profile {profile}, {files} files) in {} s",
        flow.sha,
        if mode_created { "created" } else { "reused" },
        started.elapsed().as_secs()
    ));
    0
}

/// Rename, then link, then delete the old folder: a folder held open (or a failed link) leaves the work folder where it was.
fn link_work_folder(kc: &Kc, ws: &Path, stable: &Path) -> Result<(), String> {
    let parent = ws.parent().ok_or("the work folder has no parent")?;
    let old = PathBuf::from(format!("{}.old-{}", ws.display(), std::process::id()));
    kc.live()?;
    std::fs::rename(ws, &old).map_err(|e| {
        kc.note(format!("cannot move {} aside: {e}", ws.display()));
        e.to_string()
    })?;
    let linked = super::links::OsLinks {
        env: &kc.env,
        windows: kc.windows,
    };
    if let Err(e) = kc.live().and_then(|()| super::links::Links::link_dir(&linked, stable, ws)) {
        let _ = std::fs::rename(&old, ws);
        kc.note(format!("cannot link {} to {}: {e}", ws.display(), stable.display()));
        return Err(e);
    }
    if let Err(e) = kc.remove(parent, &old) {
        kc.note(format!("{NAME}: could not delete the replaced work folder {}: {e}", old.display()));
    }
    Ok(())
}

/// Why a soft phase gave no value.
enum Soft {
    /// It failed with this message.
    Failed(String),
    /// It did not finish in time (the warning is already printed).
    Hung,
}
use Soft::{Failed, Hung};

/// The kept clone's state through the phases.
struct Flow {
    kc: Arc<Kc>,
    ws: PathBuf,
    ws_text: String,
    /// The kept folder (set once resolved).
    stable: PathBuf,
    sha: String,
    url: String,
    excludes: Vec<String>,
    limit: Duration,
    hint: String,
}

impl Flow {
    fn stable_text(&self) -> String {
        self.stable.display().to_string()
    }

    /// Moves the `run:` lines of the noisy git commands to the job log.
    fn flush(&self, step: &mut Step<'_>) {
        let text = self
            .kc
            .own
            .log
            .lock()
            .map(|mut l| String::from_utf8_lossy(&std::mem::take(&mut *l)).into_owned())
            .unwrap_or_default();
        for line in text.lines() {
            step.say(line);
        }
    }

    /// A bounded phase that never fails the job (the shell's `BOUNDED_SOFT=1`): a failure is the caller's to handle, a timeout is one
    /// `::warning::` naming the phase, the last output and the next step.
    fn phase<T: Send + 'static>(
        &self,
        step: &mut Step<'_>,
        id: PhaseId,
        label: &str,
        f: impl FnOnce(&Kc) -> Result<T, String> + Send + 'static,
    ) -> Result<T, Soft> {
        let limit = phase_limit(&self.kc.env, id, self.limit);
        if let Ok(mut e) = self.kc.own.err.lock() {
            e.clear();
        }
        let out = Arc::new(PhaseOut::default());
        let (kc, mine) = (self.kc.clone(), out.clone());
        // A git command ends itself at the limit (and its whole process tree with it); the phase waits one second longer so that it is
        // the git command's end that is seen first, and a phase that hangs elsewhere (a file call) is abandoned after that. The phase's
        // thread writes only to `out`: what it wrote by now becomes the step's, anything it writes after that goes nowhere.
        // With a clock mark (tests only, `PADDOCK_KEPT_CLONE_CLOCK_MARK`, the shell's `clock_mark`) that bound counts from the mark the
        // test's hanging git writes, and until then the general limit bounds the phase. A git command's own limit needs no mark: it
        // counts from that command's start, and the hanging git writes the mark as it starts.
        let mark_file = self.kc.env.get(CLOCK_MARK).filter(|v| !v.is_empty()).map(PathBuf::from);
        let mark = mark_file.as_deref().map(|file| ClockMark { file, wait: self.limit });
        let bound = limit + Duration::from_secs(1);
        let (r, before_mark) = bounded_marked(step, label, bound, Some(&out.timed_out), mark, move |held| {
            IN_PHASE.with(|p| p.set(Some(limit)));
            PHASE_HELD.with(|h| *h.borrow_mut() = Some(held));
            PHASE_OUT.with(|p| *p.borrow_mut() = Some(mine));
            f(&kc)
        });
        // The line names the phase's limit, or the general one when the phase ended before its clock mark.
        let shown = if before_mark { self.limit } else { limit };
        if matches!(r, Err(Phase::Timeout)) {
            // Its thread may still be running: from now on it changes nothing (`Kc::live`), and writes only to `out`.
            out.abandoned.store(true, Ordering::SeqCst);
        }
        self.kc.adopt(&out);
        self.flush(step);
        match r {
            Ok(v) => Ok(v),
            Err(Phase::Failed(e)) => Err(Failed(e)),
            Err(Phase::Timeout) => {
                step.warn(format!(
                    "'{label}' did not finish within {} s. Last output: {}. Next step: {}",
                    shown.as_secs(),
                    self.kc.last_lines(),
                    self.hint
                ));
                Err(Hung)
            }
        }
    }

    /// The sparse patterns of the profile (everything but the excluded paths) for the tree's git.
    fn apply_profile(&self, tree: &Path) -> Result<(), String> {
        let t = tree.display().to_string();
        self.kc
            .git(true, &["-C", &t, "config", "core.sparseCheckout", "true"])
            .map_err(|e| e.to_string())?;
        self.kc
            .git(true, &["-C", &t, "config", "core.sparseCheckoutCone", "false"])
            .map_err(|e| e.to_string())?;
        let info = tree.join(".git").join("info");
        self.kc.live()?;
        std::fs::create_dir_all(&info).map_err(|e| e.to_string())?;
        let mut text = String::from("/*\n");
        for p in &self.excludes {
            text.push_str(&format!("!/{p}/\n"));
        }
        self.kc.live()?;
        std::fs::write(info.join("sparse-checkout"), text).map_err(|e| e.to_string())
    }

    /// Exit 0 when the kept folder holds a usable clone of this repository, made by this step (the marker).
    fn healthy(&self) -> bool {
        let t = self.stable_text();
        self.stable.join(".git").join("paddock-kept-clone").is_file()
            && self.kc.git(false, &["-C", &t, "rev-parse", "--git-dir"]).is_ok()
            && self
                .kc
                .git(false, &["-C", &t, "config", "remote.origin.url"])
                .is_ok_and(|u| u == self.url)
    }

    /// The first local config key outside the allow-list (empty when there is none).
    fn foreign_key(&self) -> String {
        let t = self.stable_text();
        self.kc
            .git(false, &["-C", &t, "config", "--local", "--list"])
            .map(|l| foreign_key_of(&l))
            .unwrap_or_default()
    }

    /// Nothing a job could have planted in `.git` is left to act: hooks (also never run: core.hooksPath), attributes, excludes, replace
    /// objects.
    fn sanitize(&self) -> Result<(), String> {
        let dotgit = self.stable.join(".git");
        self.kc.remove(&dotgit, &dotgit.join("hooks"))?;
        self.kc.live()?;
        std::fs::create_dir_all(dotgit.join("hooks")).map_err(|e| e.to_string())?;
        self.kc.remove(&dotgit, &dotgit.join("info").join("attributes"))?;
        self.kc.remove(&dotgit, &dotgit.join("info").join("exclude"))?;
        self.kc.remove(&dotgit, &dotgit.join("refs").join("replace"))
    }

    /// A job's `.angular/cache` is a link to a kept folder outside the clone; each link is removed by itself before a clean.
    fn unlink_caches(&self) {
        for l in angular_cache_links(&self.stable) {
            if self.kc.live().is_err() {
                return;
            }
            // `remove_file` on a symlink, `remove_dir` on a junction (removes only the junction).
            if std::fs::remove_file(&l).or_else(|_| std::fs::remove_dir(&l)).is_err() {
                self.kc.note(format!("{NAME}: could not remove the link {}", l.display()));
            }
        }
    }

    /// Makes the clone: no checkout, no tags, depth 1, no blobs; the marker says this step made it.
    fn create(&self, step: &mut Step<'_>, err: &mut dyn Write) -> Result<(), Soft> {
        let (stable, url) = (self.stable.clone(), self.url.clone());
        let flow = Flow {
            kc: self.kc.clone(),
            ws: self.ws.clone(),
            ws_text: self.ws_text.clone(),
            stable: self.stable.clone(),
            sha: self.sha.clone(),
            url: self.url.clone(),
            excludes: self.excludes.clone(),
            limit: self.limit,
            hint: self.hint.clone(),
        };
        let r = self.phase(step, PhaseId::Create, "create the clone", move |kc| {
            flow.unlink_caches();
            let parent = stable.parent().ok_or("the kept folder has no parent")?.to_path_buf();
            kc.remove(&parent, &stable)?;
            kc.live()?;
            std::fs::create_dir_all(&parent).map_err(|e| e.to_string())?;
            let s = stable.display().to_string();
            kc.git(
                true,
                &[
                    "clone",
                    "-q",
                    "--no-checkout",
                    "--no-tags",
                    "--depth=1",
                    "--filter=blob:none",
                    &url,
                    &s,
                ],
            )
            .map_err(|e| e.to_string())?;
            kc.live()?;
            std::fs::write(stable.join(".git").join("paddock-kept-clone"), "1\n").map_err(|e| e.to_string())
        });
        if r.is_err() {
            let _ = write!(err, "{}", self.kc.err_text());
        }
        r
    }

    /// Clean (a reused clone), fetch, check out, verify; each phase bounded. `true` when the clone is at the commit.
    fn bring_up(&self, step: &mut Step<'_>, created: bool) -> bool {
        let t = self.stable_text();
        let make = |f: fn(&Flow) -> Result<(), String>| {
            let flow = Flow {
                kc: self.kc.clone(),
                ws: self.ws.clone(),
                ws_text: self.ws_text.clone(),
                stable: self.stable.clone(),
                sha: self.sha.clone(),
                url: self.url.clone(),
                excludes: self.excludes.clone(),
                limit: self.limit,
                hint: self.hint.clone(),
            };
            move |_: &Kc| f(&flow)
        };
        // A reused clone is cleaned first; a clone just created has nothing to clean (its patterns come first: before them, a reset
        // would write the whole tree of the clone's branch, run 7808).
        if !created && self.phase(step, PhaseId::Clean, "clean", make(Flow::clean)).is_err() {
            return false;
        }
        let _ = &t;
        self.phase(step, PhaseId::Fetch, &format!("fetch {}", self.sha), make(Flow::fetch))
            .is_ok()
            && self.phase(step, PhaseId::Checkout, "check out", make(Flow::checkout)).is_ok()
            && self.phase(step, PhaseId::Verify, "verify", make(Flow::verify)).is_ok()
    }

    /// The shell's `clean_clone` is not a chain: `set -e` does not act inside a function that runs under `||`, so only the status of its
    /// last command, `git clean`, is the phase's. The steps before it note their failure and go on (a reset that fails on a lock is then
    /// found by the check-out, which names it); the port keeps that, so a clone is not made again for what a later step repairs.
    fn clean(&self) -> Result<(), String> {
        let t = self.stable_text();
        if let Err(e) = self.sanitize() {
            self.kc.note(format!("{NAME}: {e}"));
        }
        self.unlink_caches();
        if let Err(e) = self.apply_profile(&self.stable) {
            self.kc.note(format!("{NAME}: {e}"));
        }
        if self.kc.git(false, &["-C", &t, "rev-parse", "--verify", "-q", "HEAD"]).is_ok() {
            // A failure is named in the phase's error output by the command's own line.
            let _ = self.kc.git(true, &["-C", &t, "reset", "-q", "--hard", "HEAD"]);
        }
        // conformance: scoped-cleanup — the kept clone is this step's own folder (a slot's src/<name>-<slot>): nothing else lives in it, and a clean of the whole clone is its job
        self.kc.git(true, &["-C", &t, "clean", "-q", "-ffdx"]).map(|_| ())
    }

    fn fetch(&self) -> Result<(), String> {
        let t = self.stable_text();
        self.kc.git(
            true,
            &[
                "-C",
                &t,
                "fetch",
                "-q",
                "--depth=1",
                "--no-tags",
                "--filter=blob:none",
                "origin",
                &self.sha,
            ],
        )?;
        let head = self.kc.git(true, &["-C", &t, "rev-parse", "FETCH_HEAD"])?;
        if head == self.sha {
            Ok(())
        } else {
            Err(format!("FETCH_HEAD is {head}"))
        }
    }

    fn checkout(&self) -> Result<(), String> {
        let t = self.stable_text();
        self.sanitize()?;
        self.apply_profile(&self.stable)?;
        self.kc.git(
            true,
            &[
                "-C",
                &t,
                "-c",
                "advice.detachedHead=false",
                "checkout",
                "-q",
                "-f",
                "--detach",
                &self.sha,
            ],
        )?;
        self.kc.git(true, &["-C", &t, "read-tree", "-mu", "HEAD"])?;
        // conformance: scoped-cleanup — the kept clone is this step's own folder (a slot's src/<name>-<slot>): nothing else lives in it, and a clean of the whole clone is its job
        self.kc.git(true, &["-C", &t, "clean", "-q", "-ffdx"])?;
        // git clean leaves untracked files outside the sparse patterns alone (git 2.34+), so a file a job wrote into an excluded folder
        // would stay for ever: the excluded paths are removed by name.
        for p in &self.excludes {
            for d in glob_expand(&self.stable, p) {
                self.kc.remove(&self.stable, &d)?;
            }
        }
        Ok(())
    }

    fn verify(&self) -> Result<(), String> {
        let t = self.stable_text();
        let fail = |msg: String| {
            self.kc.note(&msg);
            Err(msg)
        };
        let bad = self.foreign_key();
        if !bad.is_empty() {
            return fail(format!("the local git config key '{bad}' is not one this script writes"));
        }
        let head = self.kc.git(true, &["-C", &t, "rev-parse", "HEAD"])?;
        if head != self.sha {
            return fail(format!("HEAD is {head}, not the job's commit {}", self.sha));
        }
        let status = self.kc.git(true, &["-C", &t, "status", "--porcelain", "--untracked-files=all"])?;
        if !status.is_empty() {
            let first: Vec<&str> = status.lines().take(3).collect();
            return fail(format!("the tree is not clean: {} ", first.join(" ")));
        }
        for p in &self.excludes {
            if !glob_expand(&self.stable, p).is_empty() {
                return fail(format!("excluded path {p} exists"));
            }
        }
        Ok(())
    }

    /// Stale `.git` locks (an earlier job's git that died), at most three levels deep.
    fn remove_locks(&self) {
        fn walk(dir: &Path, depth: usize, out: &mut Vec<PathBuf>) {
            let Ok(rd) = std::fs::read_dir(dir) else { return };
            for e in rd.flatten() {
                let p = e.path();
                let Ok(m) = std::fs::symlink_metadata(&p) else { continue };
                if m.is_file() && p.extension().is_some_and(|x| x == "lock") {
                    out.push(p);
                } else if m.is_dir() && !m.file_type().is_symlink() && depth < 3 {
                    walk(&p, depth + 1, out);
                }
            }
        }
        let dotgit = self.stable.join(".git");
        let mut locks = Vec::new();
        walk(&dotgit, 1, &mut locks);
        for l in locks {
            let _ = self.kc.remove(&dotgit, &l);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const ALL: [PhaseId; 7] = [
        PhaseId::Resolve,
        PhaseId::Create,
        PhaseId::Clean,
        PhaseId::Fetch,
        PhaseId::Checkout,
        PhaseId::Verify,
        PhaseId::Link,
    ];

    /// The step's shared context with a `git` of the test's own (a script in `bin`) first on PATH.
    fn kc_with_git(bin: &Path, env: &[(&str, &str)]) -> Arc<Kc> {
        let mut env: HashMap<String, String> = env.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect();
        let mut path = vec![bin.to_path_buf()];
        if cfg!(unix) {
            path.extend(["/usr/bin", "/bin"].map(PathBuf::from));
        }
        env.insert("PATH".into(), std::env::join_paths(path).unwrap().to_string_lossy().into_owned());
        Arc::new(Kc {
            env,
            windows: false,
            limit: Duration::from_secs(900),
            header: None,
            hooks: bin.join("no-hooks"),
            home: None,
            own: Default::default(),
        })
    }

    fn flow_of(kc: Arc<Kc>) -> Flow {
        Flow {
            kc,
            ws: PathBuf::new(),
            ws_text: String::new(),
            stable: PathBuf::new(),
            sha: String::new(),
            url: String::new(),
            excludes: Vec::new(),
            limit: Duration::from_secs(900),
            hint: "h".into(),
        }
    }

    #[cfg(unix)]
    #[test]
    fn a_phase_abandoned_at_its_bound_writes_nothing_into_the_next_phase() {
        use std::sync::mpsc;
        // The fetch phase (own limit 1 s, bound 2 s) runs one git, which ends at its limit (a git that logs its call and sleeps), and is
        // then held until it is abandoned. While the next phase runs, the held phase goes on: its second git must not start (the next
        // phase may be removing or making the same folder), the next phase must not be reported as hung, and its error output must not
        // carry the abandoned phase's lines.
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("bin");
        std::fs::create_dir_all(&bin).unwrap();
        // A git that logs its call and sleeps (the stand-in records every call's arguments and stays for 30 s).
        let git = paddock_testkit::StandIn::new(&bin, "git")
            .records_args()
            .sleeps(Duration::from_secs(30))
            .install()
            .unwrap();
        let kc = kc_with_git(&bin, &[(PhaseId::Fetch.var(), "1")]);
        let flow = flow_of(kc);
        let mut out = Vec::new();
        let mut step = Step {
            env: &flow.kc.env.clone(),
            out: &mut out,
            windows: false,
            name: NAME,
        };
        let (go_tx, go_rx) = mpsc::channel::<()>();
        let (done_tx, done_rx) = mpsc::channel::<()>();
        let first = flow.phase(&mut step, PhaseId::Fetch, "fetch", move |kc| {
            let _ = kc.git(true, &["fetch", "first"]); // ends at its 1 s limit
            go_rx.recv().ok(); // held past the phase's bound (limit + 1 s)
            let r = kc.git(true, &["fetch", "late"]);
            done_tx.send(()).ok();
            r
        });
        assert!(matches!(first, Err(Hung)), "the held phase is abandoned at its bound");
        let second = flow.phase(&mut step, PhaseId::Checkout, "check out", move |_| {
            go_tx.send(()).ok();
            done_rx.recv().ok(); // the abandoned phase's git has ended at its limit and written what it writes
            Ok(())
        });
        let text = String::from_utf8_lossy(&out).into_owned();
        assert!(second.is_ok(), "the next phase did not hang; it was reported as hung: {text}");
        assert!(
            !flow.kc.last_lines().contains("git fetch failed"),
            "the next phase's error output carries the abandoned phase's line: {:?}",
            flow.kc.last_lines()
        );
        assert!(!text.contains("'check out' did not finish"), "{text}");
        let ran: Vec<String> = git.calls().unwrap().iter().map(|c| c.join(" ")).collect();
        assert_eq!(
            ran.into_iter().filter(|l| l.contains("fetch")).collect::<Vec<_>>(),
            vec!["-c core.hooksPath=".to_string() + &bin.join("no-hooks").display().to_string() + " fetch first"],
            "the abandoned phase started no git after it was abandoned"
        );
    }

    #[test]
    fn a_phase_abandoned_at_its_bound_leaves_no_program_of_its_own_running() {
        // The git command ends itself at the phase's limit, one second before the phase's bound; but ending it takes time (a loaded
        // machine), and when it outlasts that second the phase is abandoned with its git still running, and the step ends with it:
        // the program outlives the step (the reaper's "below a child", run 2026-11-18 of
        // `kept_clone_the_create_phase_is_bounded_by_its_own_limit`). Stood in here by a git whose own limit is far past the bound, with
        // a program below it (a `git fetch` has helpers); both must be gone when `phase` returns.
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("bin");
        std::fs::create_dir_all(&bin).unwrap();
        let pid_file = dir.path().join("below.pid");
        paddock_testkit::StandIn::new(&bin, "sleeper")
            .sleeps(Duration::from_secs(30))
            .install()
            .unwrap();
        paddock_testkit::StandIn::new(&bin, "git")
            .spawns(&paddock_testkit::Spawn::new("sleeper").pid_file(&pid_file))
            .sleeps(Duration::from_secs(30))
            .install()
            .unwrap();
        let kc = kc_with_git(&bin, &[(PhaseId::Fetch.var(), "1")]);
        let flow = flow_of(kc);
        let mut out = Vec::new();
        let mut step = Step {
            env: &flow.kc.env.clone(),
            out: &mut out,
            windows: false,
            name: NAME,
        };
        let r = flow.phase(&mut step, PhaseId::Fetch, "fetch", move |kc| {
            IN_PHASE.with(|p| p.set(Some(Duration::from_secs(60)))); // the git's own limit is not what ends it
            kc.git(true, &["fetch"])
        });
        assert!(matches!(r, Err(Hung)), "the phase is abandoned at its bound");
        let below = paddock_testkit_start::recorded::read_pid_file(&pid_file, "the program below the abandoned phase's git");
        assert!(
            below.has_ended(),
            "a program below the abandoned phase's git ({}) still runs when the phase returns",
            below.pid()
        );
    }

    #[test]
    fn each_phase_reads_only_its_own_limit_and_falls_back_to_the_general_one() {
        let general = Duration::from_secs(900);
        for id in ALL {
            let env = HashMap::from([(id.var().to_string(), "7".to_string())]);
            for other in ALL {
                let want = if other == id { Duration::from_secs(7) } else { general };
                assert_eq!(phase_limit(&env, other, general), want, "{id:?} set, {other:?} read");
            }
        }
        // As the shell's `^[1-9][0-9]*$`: anything else is the general limit.
        for bad in ["", "0", "07", "-1", "+5", "1.5", " 5", "x"] {
            let env = HashMap::from([(PhaseId::Fetch.var().to_string(), bad.to_string())]);
            assert_eq!(phase_limit(&env, PhaseId::Fetch, general), general, "{bad:?}");
        }
    }
}

//! The prune steps: `dev ci prune-folder`, `prune-build-folder` and `prune-agent-builds` (the ports of
//! `tools/prune-build-folders.sh`, `tools/prune-ci-build-folder.sh` and `tools/prune-build-folders.ps1`).
//!
//! - **`prune-folder <folder> <max-gb>`**: a persistent CI build folder (host runners) stays within a cap so nothing piles up on the
//!   owner's machines. Over the cap the incremental-compilation caches go first (the bulk, and cheap to rebuild); still over, the
//!   folder is deleted. A missing folder, or a link, is fine and untouched (links are never followed). The size is the larger of
//!   the allocated size and the length of the files: a file system that allocates late (ZFS, btrfs, a compressed volume) reports
//!   next to nothing allocated for data written a moment ago, which once kept a full folder under the cap.
//!   `PADDOCK_PRUNE_UNIT=kb` makes the cap kilobytes instead of gigabytes (tests).
//! - **`prune-build-folder --max-gb <n> [--drop-bundles]`**: the CI form. Only the job's own kept build folder
//!   (`$PADDOCK_BUILD_FOLDER`), and only when `ci isolation owns <folder> target` says it is a `target-<name>-<slot>` folder of this
//!   job's slot directly in the CI home: a link, `$HOME`, `/`, a project folder, a path outside the CI home and another slot's folder
//!   (a concurrent job's) are refused with a notice. `--drop-bundles` first removes `<folder>/dist/bundle` (installers already
//!   uploaded). Always exits 0.
//! - **`prune-agent-builds --app <id> [--remove] [--keep <suffix>]...`**: lists the build folders agents left (`~/.<app>-target*` and
//!   `<repo>/target/*` except debug, release, rust-analyzer, doc, tmp and flycheck*) with their sizes; with `--remove` deletes those
//!   not kept (a `--keep 6c` keeps `~/.<app>-target-6c*` and `target/agent-6c*`). Ends with the free space of the repository's drive.
//!
//! Deletions go through [`safe_remove`](crate::safe_remove): only under the folder being capped, never through a link.

// conformance: file-layout-guess — the prune code never names `deps`; its tests use it only as filler data for a build folder to prune
use super::Step;
use crate::safe_remove::{self, RemoveError};
use clap::Args as ClapArgs;
use std::collections::{HashMap, HashSet};
use std::io::Write;
use std::path::{Path, PathBuf};

/// `dev ci prune-folder`.
#[derive(ClapArgs, Debug)]
pub struct FolderArgs {
    /// The folder to cap.
    pub folder: PathBuf,
    /// The cap in whole gigabytes (kilobytes with `PADDOCK_PRUNE_UNIT=kb`).
    pub max_gb: String,
}

/// `dev ci prune-build-folder`.
#[derive(ClapArgs, Debug)]
pub struct CiArgs {
    /// The cap in whole gigabytes.
    #[arg(long, default_value = "20")]
    pub max_gb: String,
    /// First removes `<folder>/dist/bundle` (installers already uploaded as artifacts).
    #[arg(long)]
    pub drop_bundles: bool,
}

/// `dev ci prune-agent-builds`.
#[derive(ClapArgs, Debug)]
pub struct AgentArgs {
    /// The app id (lower-case letters, digits, dashes).
    #[arg(long)]
    pub app: String,
    /// The repository (default: the current folder).
    #[arg(long)]
    pub repo: Option<PathBuf>,
    /// Delete the folders not kept; without it only list them.
    #[arg(long)]
    pub remove: bool,
    /// Suffixes of build folders still in use (`6c` keeps `~/.<app>-target-6c*` and `target/agent-6c*`); repeat or comma-separate.
    #[arg(long, value_delimiter = ',')]
    pub keep: Vec<String>,
}

/// The size of a folder: the allocated bytes and the length of the regular files, both counted once per file (a hard link is one
/// file). Links are never followed. Folder and link lengths are not content and are not counted: GNU `du --apparent-size` counts
/// folders as 0 and BSD `du -A` counts them rounded up per entry, so `tools/prune-build-folders.sh` sums the file lengths itself, as
/// this does. Folders take no allocated bytes here either: ext4 gives each one 4 KiB, which made a folder of empty folders
/// 20 KiB (CI run 8138).
pub fn sizes(dir: &Path) -> (u64, u64) {
    let mut seen: HashSet<(u64, u64)> = HashSet::new();
    let (mut allocated, mut apparent) = (0u64, 0u64);
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        let Ok(meta) = std::fs::symlink_metadata(&d) else { continue };
        count(Entry::of(&meta), &mut seen, &mut allocated, &mut apparent);
        if meta.is_dir() && !meta.file_type().is_symlink() {
            let Ok(entries) = std::fs::read_dir(&d) else { continue };
            for e in entries.flatten() {
                stack.push(e.path());
            }
        }
    }
    (allocated, apparent)
}

/// What [`sizes`] reads of one entry: a plain value, so a test can give a folder the 8 blocks ext4 gives it on any file system.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Entry {
    /// A regular file (not a folder, a link or anything else).
    is_file: bool,
    /// A folder.
    is_dir: bool,
    /// The allocated bytes: 512-byte blocks times 512 on Unix; the length on Windows, which reports no block count.
    allocated: u64,
    /// The length.
    len: u64,
    /// The number of names of the file (1 where the platform does not say).
    nlink: u64,
    /// The device and inode (`(0, 0)` where the platform does not say).
    id: (u64, u64),
}

impl Entry {
    fn of(meta: &std::fs::Metadata) -> Entry {
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            Entry {
                is_file: meta.is_file(),
                is_dir: meta.is_dir(),
                allocated: meta.blocks() * 512,
                len: meta.len(),
                nlink: meta.nlink(),
                id: (meta.dev(), meta.ino()),
            }
        }
        #[cfg(not(unix))]
        {
            Entry {
                is_file: meta.is_file(),
                is_dir: meta.is_dir(),
                allocated: meta.len(),
                len: meta.len(),
                nlink: 1,
                id: (0, 0),
            }
        }
    }
}

/// Adds one entry: only a regular file counts, once however many names it has. A folder's blocks and length are not content
/// (ext4 gives each folder 4 KiB, CI run 8138).
fn count(e: Entry, seen: &mut HashSet<(u64, u64)>, allocated: &mut u64, apparent: &mut u64) {
    if e.nlink > 1 && !e.is_dir && !seen.insert(e.id) {
        return;
    }
    if e.is_file {
        *allocated += e.allocated;
        *apparent += e.len;
    }
}

/// The folder's size in the cap's unit: the larger of the allocated size and the length of the files, in whole units (rounded
/// down, as the script's integer division was). `kb` counts kilobytes, else gigabytes of 1 048 576 KB.
pub fn size_in_units(dir: &Path, kb: bool) -> u64 {
    let (allocated, apparent) = sizes(dir);
    let kib = |b: u64| b.div_ceil(1024);
    let used = kib(allocated).max(kib(apparent));
    used / if kb { 1 } else { 1_048_576 }
}

fn cap_in_units(env: &HashMap<String, String>) -> bool {
    env.get("PADDOCK_PRUNE_UNIT").is_some_and(|u| u == "kb")
}

fn home_of(env: &HashMap<String, String>) -> Option<PathBuf> {
    env.get("HOME")
        .or_else(|| env.get("USERPROFILE"))
        .filter(|h| !h.is_empty())
        .map(PathBuf::from)
}

/// Every folder named `incremental` below `dir` (not looking inside one), never through a link.
fn incremental_folders(dir: &Path) -> Vec<PathBuf> {
    let mut found = Vec::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&d) else { continue };
        for e in entries.flatten() {
            let Ok(t) = e.file_type() else { continue };
            if !t.is_dir() {
                continue;
            }
            if e.file_name() == "incremental" {
                found.push(e.path());
            } else {
                stack.push(e.path());
            }
        }
    }
    found.sort();
    found
}

/// The cap itself: messages on `out`, `Err` only for a refusal of the guard.
pub fn cap_folder(env: &HashMap<String, String>, dir: &Path, max: u64, out: &mut dyn Write) -> Result<(), RemoveError> {
    let kb = cap_in_units(env);
    let home = home_of(env);
    let md = std::fs::symlink_metadata(dir);
    if !md.is_ok_and(|m| m.is_dir() && !m.file_type().is_symlink()) {
        return Ok(());
    }
    let size = size_in_units(dir, kb);
    if size >= max {
        let _ = writeln!(out, "prune: {} is {size} (cap {max}); removing incremental caches", dir.display());
        for f in incremental_folders(dir) {
            if let Err(e) = safe_remove::remove_under(dir, &f, home.as_deref()) {
                let _ = writeln!(out, "::warning::prune: could not remove {}: {e}", f.display());
            }
        }
    }
    let size = size_in_units(dir, kb);
    if size >= max {
        let _ = writeln!(out, "prune: still {size}; removing {}", dir.display());
        let parent = dir.parent().unwrap_or(Path::new(""));
        safe_remove::remove_under(parent, dir, home.as_deref())?;
    }
    Ok(())
}

/// `dev ci prune-folder`.
pub fn run_folder(env: &HashMap<String, String>, a: &FolderArgs, out: &mut dyn Write, err: &mut dyn Write) -> i32 {
    let Ok(max) = a.max_gb.parse::<u64>().map_err(|_| ()).and_then(|n| {
        if a.max_gb.bytes().all(|b| b.is_ascii_digit()) {
            Ok(n)
        } else {
            Err(())
        }
    }) else {
        let _ = writeln!(err, "prune: the cap must be a whole number, got '{}'", a.max_gb);
        return 2;
    };
    match cap_folder(env, &a.folder, max, out) {
        Ok(()) => 0,
        Err(e) => {
            let _ = writeln!(out, "::warning::prune: {} was not removed: {e}", a.folder.display());
            0
        }
    }
}

/// `dev ci prune-build-folder`: the CI form; always 0.
pub fn run_ci(env: &HashMap<String, String>, windows: bool, a: &CiArgs, out: &mut dyn Write) -> i32 {
    let mut step = Step {
        env,
        out,
        windows,
        name: "prune",
    };
    let Some(dir) = step.var("PADDOCK_BUILD_FOLDER").map(str::to_string) else {
        step.say("prune: no build folder was set in this job; nothing to prune");
        return 0;
    };
    let max = match a.max_gb.parse::<u64>() {
        Ok(n) if a.max_gb.bytes().all(|b| b.is_ascii_digit()) => n,
        _ => {
            step.say(format!(
                "prune: the cap must be a whole number, got '{}'; nothing to prune",
                a.max_gb
            ));
            return 0;
        }
    };
    if step.isolation(&["owns", &dir, "target"]).is_err() {
        let slot = step.var("PADDOCK_CI_SLOT").unwrap_or("<slot>").to_string();
        step.say(format!(
            "prune: {dir} is not a kept build folder of this job's slot (target-<name>-{slot} in the CI home); leaving it alone"
        ));
        return 0;
    }
    let real = match paddock_env::winpath::real(Path::new(&dir)) {
        Ok(p) => p,
        Err(e) => {
            step.say(format!("prune: cannot read {dir} ({e}); nothing to prune"));
            return 0;
        }
    };
    let home = home_of(env);
    if a.drop_bundles
        && let Err(e) = safe_remove::remove_under(&real, &real.join("dist").join("bundle"), home.as_deref())
    {
        step.say(format!("::warning::prune: could not remove the bundles: {e}"));
    }
    if let Err(e) = cap_folder(env, &real, max, step.out) {
        step.say(format!("::warning::prune: {} was not removed: {e}", real.display()));
    }
    0
}

/// The match of a name against a prefix pattern, ignoring case (PowerShell's `-like 'prefix*'`).
fn like_prefix(name: &str, prefix: &str) -> bool {
    name.to_lowercase().starts_with(&prefix.to_lowercase())
}

/// The folders agents left, from the home folder and the repository's `target`.
pub fn agent_candidates(home: &Path, repo: &Path, app: &str) -> Vec<(PathBuf, PathBuf)> {
    const PROTECTED: [&str; 5] = ["debug", "release", "rust-analyzer", "doc", "tmp"];
    let mut found = Vec::new();
    let dirs = |root: &Path| -> Vec<PathBuf> {
        let mut v: Vec<PathBuf> = std::fs::read_dir(root)
            .into_iter()
            .flatten()
            .flatten()
            .filter(|e| e.path().is_dir())
            .map(|e| e.path())
            .collect();
        v.sort();
        v
    };
    let prefix = format!(".{app}-target");
    for d in dirs(home) {
        if d.file_name().is_some_and(|n| like_prefix(&n.to_string_lossy(), &prefix)) {
            found.push((home.to_path_buf(), d));
        }
    }
    let target = repo.join("target");
    for d in dirs(&target) {
        let n = d.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
        if !PROTECTED.contains(&n.as_str()) && !like_prefix(&n, "flycheck") {
            found.push((target.clone(), d));
        }
    }
    found
}

/// Whether `name` belongs to a build still in use.
pub fn is_kept(name: &str, app: &str, keep: &[String]) -> bool {
    keep.iter()
        .any(|k| like_prefix(name, &format!(".{app}-target-{k}")) || like_prefix(name, &format!("agent-{k}")))
}

/// `dev ci prune-agent-builds`.
pub fn run_agent(env: &HashMap<String, String>, a: &AgentArgs, out: &mut dyn Write, err: &mut dyn Write) -> i32 {
    let valid = a.app.chars().next().is_some_and(|c| c.is_ascii_lowercase())
        && a.app.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
    if !valid {
        let _ = writeln!(
            err,
            "prune-agent-builds: --app must be lower-case letters, digits and dashes, starting with a letter, got '{}'",
            a.app
        );
        return 2;
    }
    let Some(home) = home_of(env) else {
        let _ = writeln!(err, "prune-agent-builds: HOME is not set");
        return 2;
    };
    let repo = a.repo.clone().unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
    let mut code = 0;
    for (root, dir) in agent_candidates(&home, &repo, &a.app) {
        let (_, apparent) = sizes(&dir);
        let gb = apparent as f64 / 1_073_741_824.0;
        let name = dir.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
        let keep = is_kept(&name, &a.app, &a.keep);
        let action = if !a.remove {
            "found"
        } else if keep {
            "kept"
        } else {
            "removing"
        };
        let _ = writeln!(out, "{gb:>8.1} GB  {action:<9} {}", dir.display());
        if a.remove && !keep {
            // The candidates are direct children of the home folder named `.<app>-target*` or of the repository's target folder,
            // so the home check is off for this one command (its root is the home folder).
            if let Err(e) = safe_remove::remove_under(&root, &dir, None) {
                let _ = writeln!(err, "::warning::prune-agent-builds: could not remove {}: {e}", dir.display());
                code = 1;
            }
        }
    }
    match free_gb(&repo) {
        Some(g) => {
            let _ = writeln!(out, "Free on {}: {g:.1} GB", repo.display());
        }
        None => {
            let _ = writeln!(out, "Free on {}: unknown", repo.display());
        }
    }
    code
}

/// The free space of the drive `p` is on, in GB (1 073 741 824 bytes); `None` where it cannot be read.
#[cfg(unix)]
#[allow(unsafe_code)] // one FFI call with a zeroed struct of the documented type
pub fn free_gb(p: &Path) -> Option<f64> {
    use std::os::unix::ffi::OsStrExt;
    let c = std::ffi::CString::new(p.as_os_str().as_bytes()).ok()?;
    // SAFETY: an all-zero statvfs is a valid value to pass for output; `c` is a live NUL-terminated path.
    let mut s: libc::statvfs = unsafe { std::mem::zeroed() };
    // SAFETY: both pointers are valid for the call.
    let ok = unsafe { libc::statvfs(c.as_ptr(), &mut s) };
    (ok == 0).then(|| s.f_bavail as f64 * s.f_frsize as f64 / 1_073_741_824.0)
}

/// The free space of the drive `p` is on, in GB; `None` where it cannot be read.
#[cfg(windows)]
#[allow(unsafe_code)] // one FFI call with documented out-pointers
pub fn free_gb(p: &Path) -> Option<f64> {
    use std::os::windows::ffi::OsStrExt;
    use windows_sys::Win32::Storage::FileSystem::GetDiskFreeSpaceExW;
    let wide: Vec<u16> = p.as_os_str().encode_wide().chain(std::iter::once(0)).collect();
    let mut free: u64 = 0;
    // SAFETY: `wide` is a live NUL-terminated string and `free` a live u64; the other two out-pointers may be null.
    let ok = unsafe { GetDiskFreeSpaceExW(wide.as_ptr(), &mut free, std::ptr::null_mut(), std::ptr::null_mut()) };
    (ok != 0).then(|| free as f64 / 1_073_741_824.0)
}

/// Not Unix or Windows: not known.
#[cfg(not(any(unix, windows)))]
pub fn free_gb(_: &Path) -> Option<f64> {
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A folder with ext4's 8 blocks and 4 KiB of length adds nothing; a file adds its blocks and length; a second name of a hard
    /// link adds nothing (CI run 8138: the folders' blocks made a folder of empty folders 20 KiB).
    #[test]
    fn a_folder_adds_nothing_a_file_its_own_blocks_and_a_hard_link_once() {
        let folder = Entry {
            is_file: false,
            is_dir: true,
            allocated: 8 * 512,
            len: 4096,
            nlink: 2,
            id: (1, 10),
        };
        let file = Entry {
            is_file: true,
            is_dir: false,
            allocated: 8 * 512,
            len: 3000,
            nlink: 2,
            id: (1, 11),
        };
        let (mut seen, mut allocated, mut apparent) = (HashSet::new(), 0, 0);
        for e in [folder, folder, file, file] {
            count(e, &mut seen, &mut allocated, &mut apparent);
        }
        assert_eq!((allocated, apparent), (4096, 3000));
    }

    fn big(root: &Path, path: &str, kb: usize) {
        let dir = root.join(path);
        std::fs::create_dir_all(&dir).unwrap();
        // Distinct bytes: a file system that compresses makes a run of equal bytes nearly free in the allocated size.
        let data: Vec<u8> = (0..kb * 1024).map(|i| (i.wrapping_mul(2_654_435_761usize) >> 7) as u8).collect();
        std::fs::write(dir.join("blob"), data).unwrap();
    }

    fn scratch() -> (tempfile::TempDir, PathBuf) {
        let d = crate::ci_host::canonical_tempdir();
        let root = d.path().join("ci").join("build");
        std::fs::create_dir_all(&root).unwrap();
        (d, root)
    }

    fn kb_env() -> HashMap<String, String> {
        [("PADDOCK_PRUNE_UNIT".to_string(), "kb".to_string())].into()
    }

    fn prune(dir: &Path, cap: &str) -> (i32, String, String) {
        let (mut o, mut e) = (Vec::new(), Vec::new());
        let code = run_folder(
            &kb_env(),
            &FolderArgs {
                folder: dir.to_path_buf(),
                max_gb: cap.into(),
            },
            &mut o,
            &mut e,
        );
        (code, String::from_utf8(o).unwrap(), String::from_utf8(e).unwrap())
    }

    #[test]
    fn under_the_cap_nothing_is_touched() {
        let (_d, dir) = scratch();
        big(&dir, "debug/incremental", 100);
        let (code, out, _) = prune(&dir, "100000");
        assert_eq!((code, out.as_str()), (0, ""));
        assert!(dir.join("debug/incremental/blob").exists());
    }

    #[test]
    fn over_the_cap_the_incremental_caches_go_first_and_the_rest_stays() {
        let (_d, dir) = scratch();
        big(&dir, "debug/incremental", 400);
        big(&dir, "debug/deps", 50);
        let (code, out, _) = prune(&dir, "300");
        assert_eq!(code, 0, "{out}");
        assert!(out.contains("removing incremental caches"), "{out}");
        assert!(!dir.join("debug/incremental").exists());
        assert!(dir.join("debug/deps/blob").exists());
    }

    #[cfg(unix)]
    #[test]
    fn the_length_of_the_files_counts_not_only_the_blocks_the_file_system_has_allocated_so_far() {
        let (_d, dir) = scratch();
        std::fs::create_dir_all(dir.join("debug/incremental")).unwrap();
        // A sparse file: 400 KB long, nothing allocated (a file system that allocates late reports the same).
        let f = std::fs::File::create(dir.join("debug/incremental/blob")).unwrap();
        f.set_len(400 * 1024).unwrap();
        big(&dir, "debug/deps", 1);
        let (code, out, _) = prune(&dir, "300");
        assert_eq!(code, 0);
        assert!(out.contains("removing incremental caches"), "{out}");
        assert!(!dir.join("debug/incremental").exists());
    }

    #[test]
    fn still_over_after_that_the_folder_is_removed() {
        let (_d, dir) = scratch();
        big(&dir, "debug/incremental", 10);
        big(&dir, "debug/deps", 400);
        let (_, out, _) = prune(&dir, "300");
        assert!(out.contains("prune: still ") && out.contains("; removing "), "{out}");
        assert!(!dir.exists());
    }

    #[cfg(unix)]
    #[test]
    fn a_missing_folder_is_fine_a_link_is_never_followed_and_a_bad_cap_is_refused() {
        let (d, dir) = scratch();
        assert_eq!(prune(&d.path().join("nope"), "1").0, 0);
        big(&dir, "incremental", 500);
        let link = d.path().join("ci/link");
        std::os::unix::fs::symlink(&dir, &link).unwrap();
        assert_eq!(prune(&link, "1").0, 0);
        assert!(dir.join("incremental/blob").exists(), "the target of a link is left alone");
        for bad in ["many", "-1", "+5", ""] {
