        assert_eq!(at_base, expected_hash(&f.exec, &f.root, "HEAD").unwrap());
        std::fs::write(f.root.join("tools/paddock-dev/new.rs"), "fn main() {}\n").unwrap();
        git(&f, &["add", "-A"]);
        git(&f, &["commit", "-q", "-m", "change an input"]);
