//! `./dev merge check`: did a merge silently drop one side's work? (Rule 48 / the 2026-11-05 merge check, ported from
//! `scripts/merge-regression-check.mjs` and extended on 2026-11-10.) Four detectors read the merge's parents and its result
//! tree:
//!
//! 1. files that go backwards against the first parent ([`backwards`], the port): a stale tree brought an old blob back
//!    (b48df1818), or the merge changed a file the branch never touched; answered by `Reverted: <path>: <reason>`;
//! 2. hunks a parent added since the merge base that the result lacks ([`hunks`]); answered by `Hunks-dropped: <path>: <reason>`;
//! 3. tests a parent has that the result lacks, three-way ([`lost_tests`]); answered by `Tests-removed: <name>: <reason>`;
//! 4. files taken whole from one parent although the other changed them too ([`whole_file`]); answered by `Hunks-dropped`;
//!    (and, report-only, a member built on a merge the target reverted: [`reverted_base`], a `::warning::` per merge);
//! 5. a stale workspace-hack, which no merge message can excuse ([`hakari`]): the fix is `cargo hakari generate` (the check compares the
//!    generated file only; refreshing the lockfiles is the author's step and is not verified).
//!
//! What it covers. 087570da4 restored what merge f94934ec5 dropped: a merge-level drop, found by detectors 2 and 3 (and 1 for
//! two of its files). 85f326139, 439861fcf and 359be91b4 are commit-level drops (single-parent commits that restored work an
//! earlier commit lost) and b48df1818 is a commit built on a stale tree: this check looks at a merge's parents against its
//! result, so a per-commit run covers the first three; the last is caught when its branch is merged (detector 1).
//!
//! Rule for filters: a filter may only remove findings for paths git reports as cleanly merged (not in the conflicted list of
//! `git merge-tree --write-tree`, and equal to its tree), and git's own merge is the arbiter for every detector that has a
//! filter: a conflicted path is never skipped, whatever its blob (a binary conflict taken as ours has parent 1's blob).
//!
//! Principle: every judgement is a three-way content judgement (base, mine, other, result), never a name or a count alone, and
//! each mechanism is tested with the others switched off (a test per detector that the others cannot satisfy). Git's own merge
//! of the two parents is the arbiter where one is needed: a file whose result equals it was merged, not taken.
//!
//! The gate must also run per commit, not only per merge: 85f326139, 439861fcf and 359be91b4 are commit-level drops that a
//! merge-level check cannot see.
//!
//! Octopus merges are not supported: they are reported as not measured (git has no automatic merge of more than two parents to
//! ask, and the history has none).
//!
//! Outcomes follow ADR 0089: clean, findings (exit 5, an error object in JSON mode) and not measured (a missing parent, a
//! shallow clone, an unparsable file, a git failure). Never a silent pass: whatever the check could not read is reported as
//! not measured. Generated files ([`generated`]) are skipped by all three detectors. Not done: `git cat-file --batch` (the
//! shared process runner closes standard input).

mod backwards;
mod diff;
mod gates;
mod generated;
mod generator_step;
pub(crate) mod git;
mod hakari;
mod hunks;
mod lost_tests;
mod other_os;
mod reland;
mod reverted_base;
mod stale_base;
pub mod sync_member;
mod testnames;
mod trailers;
mod whole_file;

use git::{AutoMerge, Git, short};
use paddock_cli::outcome::{Sha, TreeId};
use paddock_cli::{CheckId, CliError, Exit, Outcome, Reason, Report, Subject, ToolVersion, UnixSeconds, Unmeasured, measure};
use serde_json::json;
use std::path::PathBuf;

/// What kind of problem a finding is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    /// A file goes backwards against the first parent (a stale tree, a revert).
    Backwards,
    /// A parent's hunk is missing from the result.
    DroppedHunk,
    /// A parent's test is missing from the result.
    LostTest,
    /// The result is one parent's version of a file the other parent changed too.
    WholeFile,
    /// `crates/paddock-workspace-hack` is not what `cargo hakari generate` writes for the result.
    WorkspaceHack,
}

impl Kind {
    fn name(self) -> &'static str {
        match self {
            Kind::Backwards => "backwards",
            Kind::DroppedHunk => "dropped-hunk",
            Kind::LostTest => "lost-test",
            Kind::WholeFile => "whole-file",
            Kind::WorkspaceHack => "workspace-hack",
        }
    }
}

/// One thing the merge lost.
#[derive(Debug, Clone)]
pub struct Finding {
    /// The detector.
    pub kind: Kind,
    /// The file, or the test name.
    pub subject: String,
    /// What is wrong and how to give a reason.
    pub detail: String,
    /// Lines that show it (where a dropped hunk was, and what it said); empty when the detail says it all.
    pub excerpts: Vec<String>,
}

/// A check's result: the shared [`Outcome`] (ADR 0089; a pass is made only by `measure`, with evidence about the merge) and the
/// merge-specific findings behind it, which carry what the shared finding does not (kind, file, excerpts).
#[derive(Debug)]
pub struct Analysis {
    /// Clean or findings with evidence, or not measured, or broken.
    pub outcome: Outcome,
    /// The findings, in the order of the detectors (empty unless the outcome is `Findings`).
    pub found: Vec<Finding>,
}

/// A merge to check: its parents (first parent first), the result tree and the message that may carry reasons.
#[derive(Debug)]
pub struct Merge {
    /// Parent commits.
    pub parents: Vec<String>,
    /// The tree of the merge result.
    pub tree: String,
    /// The merge commit's message (empty when checking a branch before merging).
    pub message: String,
    /// A name for output.
    pub label: String,
    /// The merge commit, when it exists (a branch checked before it is merged has none).
    pub commit: Option<String>,
    /// What to call the first parent (the target) and the second (the member) in messages: their names, or short hashes.
    pub target_name: String,
    /// See `target_name`.
    pub member_name: String,
}

impl Merge {
    /// A merge of `parents` (first parent first) with result `tree`: no message, no merge commit yet, and the parents' short ids as
    /// their names. Every construction site starts here and sets what it knows with the `with_*` methods, so a new field gets its
    /// default in one place and no site breaks.
    pub fn new(parents: Vec<String>, tree: impl Into<String>, label: impl Into<String>) -> Self {
        let name_of = |i: usize| parents.get(i).map(|p| short(p).to_string()).unwrap_or_default();
        let (target_name, member_name) = (name_of(0), name_of(1));
        Merge {
            parents,
            tree: tree.into(),
            message: String::new(),
            label: label.into(),
            commit: None,
            target_name,
            member_name,
        }
    }

    /// The merge commit's message.
    pub fn with_message(mut self, message: impl Into<String>) -> Self {
        self.message = message.into();
        self
    }

    /// The merge commit, when it exists.
    pub fn with_commit(mut self, commit: Option<String>) -> Self {
        self.commit = commit;
        self
    }

    /// The names of the target (first parent) and the member (second parent) for messages.
    pub fn with_names(mut self, target: impl Into<String>, member: impl Into<String>) -> Self {
        self.target_name = target.into();
        self.member_name = member.into();
        self
    }

    /// What a check of this merge is about: the merge commit and its tree, or (before it exists) the two parents joined by `+`.
    pub fn subject(&self) -> Subject {
        let sha = self.commit.clone().unwrap_or_else(|| self.parents.join("+"));
        Subject::Commit {
            sha: Sha::new(sha),
            tree: TreeId::new(self.tree.clone()),
        }
    }
}

/// What every detector reads: the repository, the merge's parents, its result tree and message, and the generated files.
pub struct Ctx<'a> {
    git: &'a Git<'a>,
    parents: &'a [String],
    tree: &'a str,
    message: &'a str,
    generated: &'a generated::Generated,
    /// The diff from each parent to the result, in parent order.
    diffs: &'a [Vec<diff::FileDiff>],
    /// Git's own merge of the two parents, and the result's files.
    auto: &'a AutoMerge,
    result_blobs: &'a std::collections::HashMap<String, String>,
}

impl Ctx<'_> {
    /// Whether git merged `path` cleanly and the result is exactly that: nothing a parent added can be missing from it. A path
    /// git lists as conflicted is never clean, whatever its blob is (a binary conflict's blob is parent 1's).
    fn merged_cleanly(&self, path: &str) -> bool {
        !self.auto.conflicted.contains(path) && self.auto.blobs.get(path) == self.result_blobs.get(path)
    }
}

/// Runs the detectors over `merge`, as one measurement: the shared outcome comes only from `measure`, so a merge is clean only
/// when every detector ran, and the findings (and a panic, which is a broken check) cannot be turned into a pass.
pub fn analyze(git: &Git, merge: &Merge) -> Analysis {
    let found = std::cell::RefCell::new(Vec::new());
    let outcome = measure(
        CheckId::new("merge-check"),
        merge.subject(),
        ToolVersion::new(concat!("paddock-dev ", env!("CARGO_PKG_VERSION"))),
        UnixSeconds::now(),
        || {
            let list = run(git, merge).map_err(|why| Unmeasured::NotMeasured(Reason::new(why)))?;
            let shared = list
                .iter()
                .map(|f| paddock_cli::Finding::failing(format!("[{}] {}: {}", f.kind.name(), f.subject, f.detail)))
                .collect();
            *found.borrow_mut() = list;
            Ok(shared)
        },
    );
    Analysis {
        outcome,
        found: found.into_inner(),
    }
}

fn run(git: &Git, merge: &Merge) -> Result<Vec<Finding>, String> {
    if merge.parents.len() > 2 {
        return Err("octopus merges are not supported (git has no automatic merge of more than two parents to ask)".into());
    }
    // A shallow clone's history is cut: a parent, a merge base or an earlier blob may be missing, and what is missing cannot
    // be told from what is not there.
    if git.is_shallow()? {
        return Err("this clone is shallow, so parents, merge bases and earlier blobs may be missing (run `git fetch --unshallow`)".into());
    }
    for p in &merge.parents {
        git.text(&["cat-file", "-e", &format!("{p}^{{commit}}")])
            .map_err(|e| format!("a parent is not in this clone (a shallow clone? run `git fetch --unshallow`): {e}"))?;
    }
    let first = merge.parents.first().ok_or("the merge has no parents")?;
    let tree = merge.tree.as_str();
    // One diff per parent, shared by the three detectors; the first parent's also serves the port.
    let diffs = merge.parents.iter().map(|p| diff_of(git, p, tree)).collect::<Result<Vec<_>, _>>()?;
    let paths: std::collections::BTreeSet<String> = diffs
        .iter()
        .flatten()
        .flat_map(|f| [f.path.clone(), f.old().to_string()])
        .filter(|p| !generated::by_name(p))
        .collect();
    let generated = generated::Generated::load(git, tree, &paths.into_iter().collect::<Vec<_>>())?;
    let mut out = Vec::new();
    let blobs = merge.parents.iter().map(|p| git.blob_ids(p)).collect::<Result<Vec<_>, _>>()?;
    let result_blobs = git.blob_ids(tree)?;
    // Git's own merge of two parents: what a file is when nothing but the three-way merge decides it.
    let auto = git.auto_merge(&merge.parents[0], &merge.parents[1])?;
    let cx = Ctx {
        git,
        parents: &merge.parents,
        tree,
        message: &merge.message,
        generated: &generated,
        diffs: &diffs,
        auto: &auto,
        result_blobs: &result_blobs,
    };
    for (i, parent) in merge.parents.iter().enumerate() {
        // The merge base of the first parent with the second; of a later parent with the first (an octopus has one per parent).
        let other = merge.parents.get(if i == 0 { 1 } else { i }).ok_or("the merge has one parent")?;
        let base = git
            .text(&["merge-base", first, other])
            .map_err(|e| format!("no merge base for parent {}: {e}", i + 1))?;
        let base = base.trim();
        let base_blobs = git.blob_ids(base)?;
        let listings = whole_file::Listings {
            parents: &blobs,
            base: &base_blobs,
            result: &result_blobs,
            auto: &auto,
        };
        out.extend(whole_file::check(&merge.parents, i, &listings, &merge.message, &generated));
        if i > 0 {
            out.extend(backwards::check(&cx, parent, base, &diffs[0])?);
        }
        out.extend(hunks::check(&cx, i, base, &diffs[i])?);
        out.extend(lost_tests::check(&cx, i, base, &diffs[i])?);
    }
    // Not a merge's own loss but a result that no longer generates: every merged branch can be right and the sum stale.
    match hakari::check(git, tree, &result_blobs, &hakari_program()) {
        Ok(found) => out.extend(found),
        // Alone, what hakari could not say is the merge's not-measured (exit 6); beside the detectors' findings (which fail, 5) it
        // is reported with them, never as a pass (ADR 0089).
        Err(why) if out.is_empty() => return Err(why),
        Err(why) => out.push(Finding {
            kind: Kind::WorkspaceHack,
            subject: "cargo hakari generate --diff".into(),
            detail: format!("NOT MEASURED: {why}"),
            excerpts: Vec::new(),
        }),
    }
    Ok(out)
}

/// The program that runs `hakari`: `cargo`, or `PADDOCK_MERGE_CHECK_CARGO` (tests point it at a stand-in).
fn hakari_program() -> String {
    std::env::var("PADDOCK_MERGE_CHECK_CARGO").unwrap_or_else(|_| "cargo".into())
}

fn diff_of(git: &Git, from: &str, to: &str) -> Result<Vec<diff::FileDiff>, String> {
    let mut args = vec!["diff"];
    args.extend(diff::DIFF_FLAGS);
    args.extend([from, to]);
    diff::parse(&git.text(&args)?)
}

/// Command line of `./dev merge check`.
pub struct Request {
    /// The repository root (default: found from the current folder).
    pub root: Option<PathBuf>,
    /// A merge commit.
    pub commit: Option<String>,
    /// A branch about to be merged, with `target`.
    pub branch: Option<String>,
    /// The branch it would be merged into.
    pub target: Option<String>,
    /// Run the generator checks of `docs/generators.toml` that the merge makes due (the commit form only; the checkout must be
    /// the merge result). `--no-generators` turns it off.
    pub generators: bool,
    /// Run the member gate (`./dev check --pre-push --member-gate --base <merge>^1`) on the merge (the commit form only; the checkout must be
    /// the merge result). ADR 0098 WP-1; report-only until its first green run ([`gates::ENFORCED`]).
    pub gates: bool,
    /// Write the merge message with the `Reverted:` lines a re-land explains to this file ([`reland`]; findings only).
    pub write_reverted: Option<PathBuf>,
}

/// The step for `--write-reverted`: the lines a re-land explains, written with the message to `file`; says plainly when it tied none.
fn write_reverted_step(git: &Git, merge: &Merge, found: &[Finding], file: &std::path::Path) -> generator_step::Step {
    let step = |text: Vec<String>, data: serde_json::Value, exit| generator_step::Step { text, data, exit };
    let lines = match reland::lines(git, merge, found) {
        Ok(l) => l,
        Err(why) => {
            return step(
                vec![format!(
                    "::warning::--write-reverted could not read the history: {why}. Next step: write the `Reverted:` lines by hand."
                )],
                json!({"outcome": "not measured", "why": why}),
                Exit::Ok,
            );
        }
    };
    if lines.is_empty() {
        return step(
            vec![format!(
                "--write-reverted: no finding ties to a re-land of this member (a commit `revert: reapply ...` or `Reapply \"...\"` that undoes a revert of the target and changes the file); nothing written to {}.",
                file.display()
            )],
            json!({"outcome": "none", "lines": []}),
            Exit::Ok,
        );
    }
    let head = if merge.commit.is_some() {
        merge.message.trim_end().to_string()
    } else {
        format!("Merge branch '{}' into {}", merge.member_name, merge.target_name)
    };
    let text = format!("{head}\n\n{}\n", lines.join("\n"));
    if let Err(e) = std::fs::write(file, &text) {
        return step(
            vec![format!(
                "::error::--write-reverted could not write {}: {e}. Next step: choose a folder you can write to.",
                file.display()
            )],
            json!({"outcome": "not measured", "why": e.to_string()}),
            Exit::NotMeasured,
        );
    }
    let left = found.len() - lines.len().min(found.len());
    let mut out = vec![format!(
        "--write-reverted: {} of {} finding(s) are the re-land's own; message with their `Reverted:` lines written to {} (use it with `git commit --amend -F` or `git merge -F`, then run the check again; the other {left} need a person):",
        lines.len(),
        found.len(),
        file.display()
    )];
    out.extend(lines.iter().map(|l| format!("  {l}")));
    step(
        out,
        json!({"outcome": "written", "file": file.display().to_string(), "lines": lines}),
        Exit::Ok,
    )
}

fn resolve(git: &Git, req: &Request) -> Result<Merge, CliError> {
    let gap = |e: String| CliError::new(Exit::NotMeasured, not_measured(&e));
    match (&req.commit, &req.branch, &req.target) {
        (Some(c), None, None) => {
            let line = git.text(&["rev-list", "--parents", "-n", "1", c]).map_err(gap)?;
            let ids: Vec<String> = line.split_whitespace().skip(1).map(str::to_string).collect();
            if ids.len() < 2 {
                let shallow = git.text(&["rev-parse", "--is-shallow-repository"]).map_err(gap)?;
                if shallow.trim() == "true" {
                    return Err(gap(format!(
                        "{c} shows no parents because this clone is shallow (run `git fetch --unshallow`)"
                    )));
                }
                return Err(CliError::usage(format!("{c} is not a merge commit."))
                    .with_hint("Give a merge commit, or --branch <b> --target <t> before merging."));
            }
            let tree = git.text(&["rev-parse", &format!("{c}^{{tree}}")]).map_err(gap)?.trim().to_string();
            let message = git.text(&["show", "-s", "--format=%B", c]).map_err(gap)?;
            let commit = git
                .text(&["rev-parse", &format!("{c}^{{commit}}")])
                .ok()
                .map(|t| t.trim().to_string());
            Ok(Merge::new(ids, tree, format!("merge {}", short(c)))
                .with_message(message)
                .with_commit(commit))
        }
        (None, Some(b), Some(t)) => {
            let first = git
                .text(&["rev-parse", "--verify", &format!("{t}^{{commit}}")])
                .map_err(gap)?
                .trim()
                .to_string();
            let second = git
                .text(&["rev-parse", "--verify", &format!("{b}^{{commit}}")])
                .map_err(gap)?
                .trim()
                .to_string();
            let tree = git
                .text(&["merge-tree", "--write-tree", "--no-messages", &first, &second])
                .map_err(|e| {
                    let mut err = gap(format!("{b} does not merge cleanly into {t}, so there is no result to check: {e}"));
                    // The usual cause is a member built on a merge the target reverted: say so (report-only warnings).
                    let names = reverted_base::Names {
                        target: t,
                        member: b,
                        merged: false,
                    };
                    if let Some(step) = reverted_base::of_refs(git, &format!("{b} into {t}"), &first, &second, &names) {
                        err.message.push('\n');
                        err.message.push_str(&step.text.join("\n"));
                    }
                    err
                })?;
            let tree = tree.lines().next().unwrap_or("").trim().to_string();
            Ok(Merge::new(vec![first, second], tree, format!("{b} into {t}")).with_names(t.clone(), b.clone()))
        }
        _ => Err(CliError::usage("Give one merge commit, or --branch and --target together.")
            .with_hint("`./dev merge check <merge-commit>` or `./dev merge check --branch <b> --target <t>`.")),
    }
}

/// The `::error::` line for a check that could not look (ER-27, ADR 0089).
fn not_measured(why: &str) -> String {
    format!(
        "::error::merge check NOT MEASURED: {why}. Next step: fix what is named, then run it again; a merge that was not measured is not a merge that passed."
    )
}

/// The findings as text: a header, one line per finding in one format, and the `::error::` line with the next step.
fn findings_text(label: &str, found: &[Finding]) -> String {
    let mut lines = vec![format!("merge check: {label}: {} finding(s)", found.len())];
    for f in found {
        lines.push(format!("  [{}] {}: {}", f.kind.name(), f.subject, f.detail));
        lines.extend(f.excerpts.iter().map(|e| format!("      {e}")));
    }
    let hack = found.iter().filter(|f| f.kind == Kind::WorkspaceHack).count();
    let mut next = Vec::new();
    if hack < found.len() {
        next.push("restore what was dropped, or if it was meant, say so in the merge message with `Hunks-dropped: <path>: <reason>`, `Reverted: <path>: <reason>` or `Tests-removed: <name>: <reason>`".to_string());
    }
    if hack > 0 {
        next.push("run `cargo hakari generate` in crates/ and refresh the lockfiles that list a changed crate (a merge message cannot excuse a stale workspace-hack; if cargo-hakari could not run, install it with `cargo install --locked cargo-hakari` and run `cargo hakari generate --diff` yourself)".to_string());
    }
    lines.push(format!(
        "::error::{label}: {} finding(s). Next step: {}, then run it again.",
        found.len(),
        next.join("; and ")
    ));
    lines.join("\n")
}

fn clean_report(label: &str, result: &serde_json::Value) -> Report {
    Report::new(
        json!({"outcome": "clean", "merge": label, "result": result}),
        format!("merge check: {label}: nothing a parent added is missing from the result."),
    )
}

/// The steps after the detectors (the generator checks, the member gate), each under its own key of the JSON.
#[derive(Default)]
struct Steps(Vec<(&'static str, generator_step::Step)>);

impl Steps {
    fn push(&mut self, key: &'static str, step: Option<generator_step::Step>) {
        if let Some(s) = step {
            self.0.push((key, s));
        }
    }

    /// The steps' lines, one after the other.
    fn text(&self) -> Option<String> {
        (!self.0.is_empty()).then(|| self.0.iter().map(|(_, s)| s.text.join("\n")).collect::<Vec<_>>().join("\n"))
    }

    /// A stale file or a failing gate beats a step that could not look; `Ok` when none says more.
    fn exit(&self) -> Exit {
        let all: Vec<Exit> = self.0.iter().map(|(_, s)| s.exit).collect();
        [Exit::Findings, Exit::NotMeasured]
            .into_iter()
            .find(|e| all.contains(e))
            .unwrap_or(Exit::Ok)
    }

    fn data(&self) -> Vec<(&'static str, serde_json::Value)> {
        self.0.iter().map(|(k, s)| (*k, s.data.clone())).collect()
    }
}

/// Runs the check: the merge's label and its findings, or why it could not look.
/// The merge's label, its findings, the steps after the detectors and the outcome as the wire object (with its evidence).
type Checked = (String, Vec<Finding>, Steps, serde_json::Value);

fn check(req: &Request) -> Result<Checked, CliError> {
    let root = crate::gates::command::repo_root(req.root.as_deref())?;
    let git = Git::new(&root);
    let merge = resolve(&git, req)?;
    let analysis = analyze(&git, &merge);
    let result = analysis.outcome.json();
    match analysis.outcome {
        Outcome::NotMeasured(why) => Err(CliError::new(Exit::NotMeasured, not_measured(why.as_str()))),
        Outcome::CheckBroken(why) => Err(CliError::new(Exit::CheckBroken, not_measured(why.as_str()))),
        // Nothing here makes a known commit or a not-applicable result: a merge is always measured by `measure` above.
        Outcome::KnownCommit(_) | Outcome::NotApplicable(_) => Err(CliError::new(
            Exit::NotMeasured,
            not_measured("the merge check returned a result it does not make"),
        )),
        Outcome::Clean(_) | Outcome::Findings(_) => {
            let found = analysis.found;
            // The generated files are checked in the checkout, so only a merge that exists as a commit has one to check.
            let step = if !req.generators {
                Some(generator_step::not_run("--no-generators"))
            } else if req.commit.is_none() {
                Some(generator_step::not_run(
                    "a branch is checked before it is merged, so there is no checkout of the result; run `./dev merge check <merge-commit>` after merging",
                ))
            } else {
                generator_step::run(&root, &git, &merge, &crate::generators::run::Real::new(&root), &|l| {
                    eprintln!("{l}")
                })
            };
            let mut steps = Steps::default();
            steps.push("generators", step);
            // Report-only (ER-41): a member built on a merge the target reverted; never a finding, never an exit code.
            steps.push("reverted-base", reverted_base::run(&git, &merge));
            // Report-only (ER-41, stale_base::ENFORCED): a member that lacks the train's base, and a train with no declared base.
            if let [train, member] = merge.parents.as_slice() {
                match stale_base::problem(&git, train, member, &merge.target_name, &merge.member_name) {
                    Ok(Some(text)) if stale_base::ENFORCED => return Err(CliError::new(Exit::Findings, text)),
                    Ok(Some(text)) => steps.push(
                        "stale-base",
                        Some(generator_step::Step {
                            text: vec![text],
                            data: json!({"outcome": "warning"}),
                            exit: Exit::Ok,
                        }),
                    ),
                    Ok(None) => {}
                    Err(why) => steps.push(
                        "stale-base",
                        Some(generator_step::Step {
                            text: vec![format!(
                                "::warning::stale-base check NOT MEASURED: {why}. Next step: run it again; this check is report-only."
                            )],
                            data: json!({"outcome": "not measured", "why": why}),
                            exit: Exit::Ok,
                        }),
                    ),
                }
            }
            if let Some(Ok(Some(notice))) = merge.parents.first().map(|t| stale_base::unknown(&git, t, &merge.target_name)) {
                steps.push(
                    "stale-base",
                    Some(generator_step::Step {
                        text: vec![notice],
                        data: json!({"outcome": "not run"}),
                        exit: Exit::Ok,
                    }),
                );
            }
            if let (Some(file), false) = (&req.write_reverted, found.is_empty()) {
                steps.push("write-reverted", Some(write_reverted_step(&git, &merge, &found, file)));
            }
            if req.gates {
                steps.push(
                    "gates",
                    Some(if req.commit.is_none() {
                        gates::not_run("a branch is checked before it is merged, so there is no checkout of the result; run `./dev merge check --gates <merge-commit>` after merging")
                    } else {
                        gates::run(&root, &git, &merge, &gates::Real, gates::ENFORCED)
                    }),
                );
                steps.push(
                    "other_os",
                    Some(if req.commit.is_none() {
                        other_os::not_run("a branch is checked before it is merged, so there is no checkout of the result")
                    } else {
                        other_os::run_real(&root, &git, &merge, other_os::ENFORCED)
                    }),
                );
            }
            Ok((merge.label, found, steps, result))
        }
    }
}

/// `./dev merge check`. Detector findings are an error (exit 5), so the text goes to standard error like every other failure.
/// A stale generated file is exit 5 and a generator check that could not look is exit 6, both with their `::error::` lines; the
/// member gate (`--gates`) adds its own rows and, once enforced, the same two exits.
pub fn command(req: &Request) -> Result<Report, CliError> {
    let (label, found, steps, result) = check(req)?;
    let lines = steps.text();
    let exit = steps.exit();
    if !found.is_empty() {
        let mut text = findings_text(&label, &found);
        if let Some(l) = lines {
            text.push('\n');
            text.push_str(&l);
        }
        return Err(CliError::new(Exit::Findings, text));
    }
    let mut report = clean_report(&label, &result);
    if let Some(l) = lines {
        report.text.push('\n');
        report.text.push_str(&l);
    }
    for (k, v) in steps.data() {
        report.data[k] = v;
    }
    Ok(if exit == Exit::Ok { report } else { report.with_exit(exit) })
}

/// `./dev merge check --json`: one object on standard output. Findings are `"ok": false, "kind": "findings"` with the
/// structured list (`kind`, `subject`, `detail`), and the text goes to standard error as without `--json`. `"generators"` holds
/// the generator checks' results when they ran, `"gates"` the member gate's.
pub fn command_json(req: &Request, out: &mut dyn std::io::Write, err: &mut dyn std::io::Write) -> i32 {
    match check(req) {
        Err(e) => paddock_cli::finish(paddock_cli::Format::Json, Err(e), out, err).code(),
        Ok((label, found, steps, result)) if found.is_empty() => {
            let exit = steps.exit();
            let mut report = clean_report(&label, &result);
            if let Some(l) = steps.text() {
                report.text.push('\n');
                report.text.push_str(&l);
            }
            for (k, v) in steps.data() {
                report.data[k] = v;
            }
            let report = if exit == Exit::Ok { report } else { report.with_exit(exit) };
            paddock_cli::finish(paddock_cli::Format::Json, Ok(report), out, err).code()
        }
        Ok((label, found, steps, result)) => {
            let mut text = findings_text(&label, &found);
            if let Some(l) = steps.text() {
                text.push('\n');
                text.push_str(&l);
            }
            let mut object = json!({
                "ok": false,
                "kind": "findings",
                "exit": Exit::Findings.code(),
                "merge": label,
                "result": result,
                "error": text,
                "findings": found.iter().map(|f| json!({"kind": f.kind.name(), "subject": f.subject, "detail": f.detail, "excerpts": f.excerpts})).collect::<Vec<_>>(),
                "generators": serde_json::Value::Null,
            });
            for (k, v) in steps.data() {
                object[k] = v;
            }
            let _ = writeln!(out, "{object}");
            let _ = writeln!(err, "error: {text}");
            Exit::Findings.code()
        }
    }
}

#[cfg(test)]
mod merge_tests {
    use super::Merge;

    #[test]
    fn a_new_merge_names_its_parents_by_short_id_and_has_no_message_or_commit() {
        let m = Merge::new(vec!["1111111111111111".into(), "22222".into()], "tree", "label");
        assert_eq!((m.target_name.as_str(), m.member_name.as_str()), ("111111111", "22222"));
        assert_eq!(
            (m.message.as_str(), m.commit.as_deref(), m.tree.as_str(), m.label.as_str()),
            ("", None, "tree", "label")
        );
    }

    #[test]
    fn the_with_methods_set_only_their_own_field() {
        let m = Merge::new(vec!["a".into(), "b".into()], "t", "l")
            .with_message("msg")
            .with_commit(Some("c".into()))
            .with_names("main", "feat/x");
        assert_eq!((m.message.as_str(), m.commit.as_deref()), ("msg", Some("c")));
        assert_eq!((m.target_name.as_str(), m.member_name.as_str()), ("main", "feat/x"));
        assert_eq!(m.parents, ["a", "b"]);
    }
}

// ci-runs-reader: the member gate (other-os) reads the jobs and the triage rows of ONE partial member run (a base dispatch, which ci verdict refuses by design) for a report-only row per OS; it never says a commit may land or be tagged: that verdict stays ./dev ci verdict
//! The `other-os` member gate of `./dev merge check --gates` (train 14, early-catch item 1; ADR 0087 amendment of 2026-11-16): a
//! member's affected tests run on Linux and Windows BEFORE the member joins a train, **on the real CI runners**, as merge queues and
//! merge trains do. The user decided this on 2026-11-16 after the first version (a container on the Arm Mac and the Windows test VM)
//! gave false findings: 22 `paddock-dev` tests failed on the VM on a base where the real runner is green.
//!
//! The step does no selection and no running of its own:
//! 1. **Selection is the plan's** (`./dev plan <train before> <merge>`, the planner CI uses; rule 55: one copy of "what does a
//!    change reach"). A member that reaches no project says `not run (<why>)`.
//! 2. The merge commit is pushed to a short-lived ref `trial/member-<sha>` (the `trial/*` namespace of ADR 0098 WP-4, which
//!    `./dev ci trial-prune` also cleans), and `ci.yml` is dispatched on it with `base` = the train before, so CI's own planner runs
//!    only the affected jobs. The dispatch waits for a busy single-machine runner (ER-24, D-1: one train's CI per runner class at a
//!    time), bounded; a runner that stays busy is `not measured`.
//! 3. One bounded wait on the run (`./dev wait --ci-run`), then the jobs and the triage are read: **only NEW failures fail a
//!    row** (`./dev ci triage` compares with the last main run and the flake history; a failure also on main is listed, not blamed).
//!
//! Every OS gets a row made with the shared [`measure`] and [`Outcome`] types (C124): `Clean` with evidence for this run, `Findings`
//! (the NEW failures), `NotMeasured` (the reason) or `NotApplicable` (no job of the plan ran on that OS). Never a silent skip
//! (ER-33). **Report-only until its first green run is recorded (ER-41)**: [`ENFORCED`] is false, so the exit code is unchanged.
//! The pass/fail reading of a PARTIAL run is this module's; `ci verdict` stays the one reader of FULL runs (it refuses a base
//! dispatch by design), so it is not asked here.

use super::generator_step::Step;
use super::{Merge, git::Git, short};
use crate::ci_runs::client::{Client, TimedJob};
use crate::ci_runs::{dispatch, reservation, time, triage, trial};
use crate::queue::ports::{Blame, Failure, Sent};
use crate::queue::real::{Child, GitTrain, failures_of};
use crate::wait::{CurlHttp, Http};
use paddock_cli::outcome::{CheckId, Finding, Outcome, Reason, RunId, Sha, Subject, ToolVersion, UnixSeconds, measure};
use paddock_cli::{Exit, Severity};
use paddock_proc::{Limits, command, run_bounded};
use serde_json::{Value, json};
use std::path::{Path, PathBuf};
use std::time::Duration;

/// Whether a failing or unmeasured row changes the exit code. False until the first green report-only run on a real train is
/// recorded in the ADR 0087 amendment of 2026-11-16 (ER-41); the change that records it flips this.
pub const ENFORCED: bool = false;

/// The workflow the member's run uses: the plan's own jobs.
pub const WORKFLOW: &str = "ci.yml";

/// How long the dispatch may wait for a busy single-machine runner (ER-24).
const MAX_DISPATCH_WAIT: &str = "45m";
/// How long the run may take once it is dispatched (a full affected plan on the real runners).
const MAX_RUN_WAIT: &str = "2h";

/// An operating system a row is about.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Os {
    /// The Linux jobs of the run (`ubuntu-latest`, the CI image).
    Linux,
    /// The Windows jobs of the run (`windows-latest`, the real runner).
    Windows,
}

impl Os {
    /// The name in rows and in the JSON.
    pub fn name(self) -> &'static str {
        match self {
            Os::Linux => "linux",
            Os::Windows => "windows",
        }
    }

    /// The OS a job of ci.yml's matrix belongs to, from its name (`paddock-dev (windows-latest)`); `None` for a job that names none
    /// (the plan, the conformance job) or another OS (macOS is the integrator's own machine).
    pub fn of_job(name: &str) -> Option<Os> {
        let n = name.to_ascii_lowercase();
        if n.contains("windows") {
            Some(Os::Windows)
        } else if n.contains("ubuntu") || n.contains("linux") {
            Some(Os::Linux)
        } else {
            None
        }
    }
}

/// One job of the member's run.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JobRow {
    /// The job's display name.
    pub name: String,
    /// `success`, `failure`, `cancelled`, `skipped` or empty while unfinished.
    pub conclusion: String,
}

/// How the wait on the run ended.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RunEnd {
    /// The run finished (any conclusion).
    Finished,
    /// The run was still going when the bound ended.
    StillRunning,
}

/// What the plan said about the member's own change.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Reach {
    /// At least one project is affected.
    Projects,
    /// Nothing but documentation (or nothing) is affected.
    Nothing,
}

/// The real CI as this step needs it. The real one is [`Gitea`]; tests give a table.
pub trait Runs {
    /// Whether the plan reaches any project for `base..head`; `Err` when it could not be asked.
    fn reaches(&mut self, base: &str, head: &str) -> Result<Reach, String>;
    /// Pushes `commit` to `git_ref` (a short-lived scratch ref).
    fn publish(&mut self, commit: &str, git_ref: &str) -> Result<(), String>;
    /// Dispatches [`WORKFLOW`] on `git_ref` with `base`.
    fn dispatch(&mut self, git_ref: &str, base: &str) -> Result<Sent, String>;
    /// The id of the run on `commit`, once it exists.
    fn find_run(&mut self, commit: &str) -> Result<Option<u64>, String>;
    /// Waits for the run, at most [`MAX_RUN_WAIT`].
    fn wait(&mut self, run: u64) -> Result<RunEnd, String>;
    /// The jobs of the run.
    fn jobs(&mut self, run: u64) -> Result<Vec<JobRow>, String>;
    /// The failures of the finished run, each blamed by `ci triage`.
    fn failures(&mut self, run: u64) -> Result<Vec<Failure>, String>;
    /// Deletes the scratch ref (best effort: `ci trial-prune` catches the rest).
    fn delete(&mut self, git_ref: &str);
}

/// The plan's answer as a [`Reach`]: any project flag true, an app named, or `all`.
pub fn reach_of(plan: &Value) -> Reach {
    let flag = |k: &str| plan.get(k).and_then(Value::as_bool).unwrap_or(false);
    let any = [
        "all",
        "crates",
        "ui",
        "eslint",
        "conformance",
        "c99",
        "tools",
        "icons",
        "ciImage",
        "paddockDev",
    ]
    .iter()
    .any(|k| flag(k))
        || plan.get("apps").and_then(Value::as_array).is_some_and(|a| !a.is_empty());
    if any { Reach::Projects } else { Reach::Nothing }
}

/// One OS's row: the shared outcome, the jobs it is made of and the failures that were already on main.
#[derive(Debug)]
pub struct Row {
    /// The OS.
    pub os: Os,
    /// The outcome (C124).
    pub outcome: Outcome,
    /// The jobs of the run on this OS.
    pub jobs: Vec<String>,
    /// Failures that triage found also on main: listed, not blamed.
    pub known: Vec<String>,
}

fn tool() -> ToolVersion {
    ToolVersion::new(concat!("paddock-dev merge check other-os ", env!("CARGO_PKG_VERSION")))
}

/// The job a failure belongs to: its `what` is `<job>: <test>`.
fn job_of(f: &Failure) -> &str {
    f.what.split(": ").next().unwrap_or("")
}

/// The rows of a finished run: for each OS, `NotApplicable` when the plan ran no job there, `NotMeasured` when a job did not finish
/// or a failure cannot be blamed, `Findings` for NEW (and flaky: still red, ER-12) failures only, and `Clean` otherwise (failures
/// also on main are `known`).
pub fn rows(run: u64, sha: &str, jobs: &[JobRow], failures: &[Failure]) -> Vec<Row> {
    let subject = || Subject::CiRun {
        workflow: WORKFLOW.into(),
        run: RunId(run),
        sha: Sha::new(sha),
    };
    [Os::Linux, Os::Windows]
        .into_iter()
        .map(|os| {
            let mine: Vec<&JobRow> = jobs.iter().filter(|j| Os::of_job(&j.name) == Some(os)).collect();
            let names: Vec<String> = mine.iter().map(|j| j.name.clone()).collect();
            let fails: Vec<&Failure> = failures.iter().filter(|f| Os::of_job(job_of(f)) == Some(os)).collect();
            let known: Vec<String> = fails
                .iter()
                .filter(|f| matches!(f.blame, Blame::OnMain))
                .map(|f| f.what.clone())
                .collect();
            let outcome = if mine.is_empty() {
                Outcome::NotApplicable(Reason::new(format!("the plan ran no job on {} for this member", os.name())))
            } else if let Some(j) = mine
                .iter()
                .find(|j| !matches!(j.conclusion.as_str(), "success" | "failure" | "skipped"))
            {
                Outcome::NotMeasured(Reason::new(format!(
                    "job `{}` ended `{}` (cancelled or unfinished), so nothing can be said about {}",
                    j.name,
                    if j.conclusion.is_empty() { "unfinished" } else { &j.conclusion },
                    os.name()
                )))
            } else if let Some(j) = mine
                .iter()
                .find(|j| j.conclusion == "failure" && !fails.iter().any(|f| job_of(f) == j.name))
            {
                Outcome::NotMeasured(Reason::new(format!(
                    "job `{}` failed but triage read no failing test of it (nothing proves it is the member's)",
                    j.name
                )))
            } else if let Some(f) = fails.iter().find(|f| matches!(f.blame, Blame::Unknown)) {
                Outcome::NotMeasured(Reason::new(format!(
                    "`{}` failed and nothing proves whether it also fails on main (triage: unknown)",
                    f.what
                )))
            } else {
                let new: Vec<Finding> = fails
                    .iter()
                    .filter(|f| matches!(f.blame, Blame::New | Blame::Flaky))
                    .map(|f| Finding::failing(f.what.clone()))
                    .collect();
                measure(
                    CheckId::new(format!("member-gate-other-os:{}", os.name())),
                    subject(),
                    tool(),
                    UnixSeconds::now(),
                    || Ok(new),
                )
            };
            Row {
                os,
                outcome,
                jobs: names,
                known,
            }
        })
        .collect()
}

/// What a row costs: nothing while report-only; once enforced, failing findings are the findings exit and an unmeasured row the
/// not-measured exit.
fn cost(enforced: bool, outcome: &Outcome) -> Exit {
    match (enforced, outcome) {
        (false, _) => Exit::Ok,
        (true, Outcome::Findings(f)) if f.findings().as_slice().iter().any(|x| x.severity == Severity::Failing) => Exit::Findings,
        (true, Outcome::NotMeasured(_) | Outcome::CheckBroken(_)) => Exit::NotMeasured,
        (true, _) => Exit::Ok,
    }
}

fn worst(a: Exit, b: Exit) -> Exit {
    if a == Exit::Findings || b == Exit::Findings {
        Exit::Findings
    } else if a == Exit::NotMeasured || b == Exit::NotMeasured {
        Exit::NotMeasured
    } else {
        Exit::Ok
    }
}

fn wording(enforced: bool) -> (&'static str, &'static str) {
    if enforced {
        ("::error", "")
    } else {
        (
            "::warning",
            " REPORT-ONLY until its first green run on a real train is recorded in the ADR 0087 amendment of 2026-11-16 (ER-41): the exit code is unchanged.",
        )
    }
}

/// The step for the rows of a run.
pub fn step_of(rows: &[Row], run: u64, git_ref: &str, base: &str, enforced: bool) -> Step {
    let (level, report_only) = wording(enforced);
    let mut text = vec![format!(
        "member gate other-os (base {base}, run {run} on {git_ref}, real CI runners):"
    )];
    let mut exit = Exit::Ok;
    let mut data = Vec::new();
    for r in rows {
        let also = if r.known.is_empty() {
            String::new()
        } else {
            format!("; {} failure(s) also on main, not blamed", r.known.len())
        };
        text.push(format!("  {}: {} ({} jobs){also}", r.os.name(), r.outcome.name(), r.jobs.len()));
        match &r.outcome {
            Outcome::Findings(f) => {
                for x in f.findings().as_slice() {
                    text.push(format!("    NEW: {}", x.message));
                }
                text.push(format!(
                    "{level}::member gate other-os FAILED on {}: the member's run has failures that are not on main. Next step: take the member out and send it back to its author with the failures above; do not fix it on the train.{report_only}",
                    r.os.name()
                ));
            }
            Outcome::NotMeasured(why) | Outcome::CheckBroken(why) => text.push(format!(
                "{level}::member gate other-os NOT MEASURED on {}: {}. Next step: read run {run} yourself (`./dev ci triage {run}`); a member whose other-OS tests did not give a verdict is not a member that passed.{report_only}",
                r.os.name(),
                why.as_str()
            )),
            _ => {}
        }
        exit = worst(exit, cost(enforced, &r.outcome));
        data.push(json!({
            "os": r.os.name(),
            "outcome": r.outcome.json(),
            "jobs": r.jobs,
            "alsoOnMain": r.known,
        }));
    }
    let word = if rows.iter().any(|r| matches!(r.outcome, Outcome::Findings(_))) {
        "failed"
    } else if rows
        .iter()
        .any(|r| matches!(r.outcome, Outcome::NotMeasured(_) | Outcome::CheckBroken(_)))
    {
        "not measured"
    } else if rows.iter().any(|r| matches!(r.outcome, Outcome::Clean(_))) {
        "passed"
    } else {
        "not run"
    };
    Step {
        text,
        data: json!({"outcome": word, "base": base, "run": run, "ref": git_ref, "enforced": enforced, "rows": data}),
        exit,
    }
}

/// Said out loud when the step was not asked for or cannot apply; not a failure.
pub fn not_run(why: &str) -> Step {
    Step {
        text: vec![format!("member gate other-os: not run ({why})")],
        data: json!({"outcome": "not run", "why": why}),
        exit: Exit::Ok,
    }
}

/// The step when nothing could be measured: report-only keeps the exit, enforced is the not-measured exit.
pub fn unmeasured(enforced: bool, why: &str) -> Step {
    let (level, report_only) = wording(enforced);
    Step {
        text: vec![format!(
            "{level}::member gate other-os NOT MEASURED: {why}. Next step: dispatch `ci.yml` on the member yourself (`./dev ci dispatch ci.yml --trial <branch> --max 45m`); a member whose other-OS tests did not run is not a member that passed.{report_only}"
        )],
        data: json!({"outcome": "not measured", "why": why, "enforced": enforced}),
        exit: if enforced { Exit::NotMeasured } else { Exit::Ok },
    }
}

/// The scratch ref of a merge commit.
pub fn scratch_ref(commit: &str) -> String {
    format!("trial/member-{}", commit.get(..12).unwrap_or(commit))
}

/// Runs the gate for a merge: plan, push, dispatch, wait, read, rows. The scratch ref is deleted whatever happens.
pub fn run(merge: &Merge, runs: &mut dyn Runs, enforced: bool) -> Step {
    let (Some(base), Some(commit)) = (merge.parents.first(), merge.commit.as_deref()) else {
        return not_run("the merge has no parents or no commit");
    };
    match runs.reaches(base, commit) {
        Err(e) => return unmeasured(enforced, &format!("the plan could not be asked: {e}")),
        Ok(Reach::Nothing) => return not_run("the plan reaches no project for this member (documentation only)"),
        Ok(Reach::Projects) => {}
    }
    let git_ref = scratch_ref(commit);
    let step = measure_on_runners(runs, commit, base, &git_ref, enforced);
    runs.delete(&git_ref);
    step
}

fn measure_on_runners(runs: &mut dyn Runs, commit: &str, base: &str, git_ref: &str, enforced: bool) -> Step {
    if let Err(e) = runs.publish(commit, git_ref) {
        return unmeasured(enforced, &format!("the merge could not be pushed to {git_ref}: {e}"));
    }
    match runs.dispatch(git_ref, base) {
        Err(e) => return unmeasured(enforced, &format!("ci.yml could not be dispatched on {git_ref}: {e}")),
        Ok(Sent::Busy(last)) => {
            return unmeasured(
                enforced,
                &format!("the runner stayed busy for {MAX_DISPATCH_WAIT} ({last}); one train's CI per runner class at a time (ER-24)"),
            );
        }
        Ok(Sent::Yes) => {}
    }
    let run = match runs.find_run(commit) {
        Ok(Some(id)) => id,
        Ok(None) => return unmeasured(enforced, &format!("no run of ci.yml appeared for {git_ref}")),
        Err(e) => return unmeasured(enforced, &format!("the run could not be found: {e}")),
    };
    match runs.wait(run) {
        Err(e) => return unmeasured(enforced, &format!("run {run} could not be waited for: {e}")),
        Ok(RunEnd::StillRunning) => return unmeasured(enforced, &format!("run {run} was still going after {MAX_RUN_WAIT}")),
        Ok(RunEnd::Finished) => {}
    }
    let jobs = match runs.jobs(run) {
        Ok(j) => j,
        Err(e) => return unmeasured(enforced, &format!("the jobs of run {run} could not be read: {e}")),
    };
    let failures = match runs.failures(run) {
        Ok(f) => f,
        Err(e) => return unmeasured(enforced, &format!("the failures of run {run} could not be triaged: {e}")),
    };
    step_of(&rows(run, commit, &jobs, &failures), run, git_ref, short(base), enforced)
}

/// The real CI: Gitea's API with `GITEA_TOKEN`, the tool's own git for the push, the tool's own planner and waiter.
pub struct Gitea {
    root: PathBuf,
    server: String,
    repo: String,
    token: String,
    scratch: PathBuf,
    http: CurlHttp,
}

impl Gitea {
    /// Reads the settings from the environment: `GITEA_TOKEN` (write access: it pushes the scratch ref) and `PADDOCK_TRIAL_DIR`
    /// (a folder for the askpass program, like `ci dispatch --trial`). `Err` says what is missing.
    pub fn from_env(root: &Path) -> Result<Gitea, String> {
        let token = std::env::var("GITEA_TOKEN")
            .ok()
            .filter(|t| !t.is_empty())
            .ok_or("GITEA_TOKEN is not set (it needs write access)")?;
        let scratch = std::env::var_os("PADDOCK_TRIAL_DIR")
            .map(PathBuf::from)
            .ok_or("PADDOCK_TRIAL_DIR is not set (a folder on a data drive, like `ci dispatch --trial`)")?;
        std::fs::create_dir_all(&scratch).map_err(|e| format!("cannot create {}: {e}", scratch.display()))?;
        Ok(Gitea {
            root: root.to_path_buf(),
            server: "https://dev.decryptology.net".into(),
            repo: "decryp7/paddock".into(),
            token,
            scratch,
            http: CurlHttp,
        })
    }

    fn git(&self) -> GitTrain {
        GitTrain {
            root: self.root.clone(),
            trusted: None,
            url: format!("{}/{}.git", self.server, self.repo),
            token: Some(self.token.clone()),
            authed_fetch: false,
            allow_file: false,
            scratch: self.scratch.clone(),
            merge_check: crate::merge_check::command,
            planner: crate::queue::real::run_planner,
            timeout: crate::queue::real::GIT_TIMEOUT,
        }
    }

    fn me() -> Result<PathBuf, String> {
        crate::tool_cache::self_exe().map_err(|e| format!("this program cannot be found: {e}"))
    }
}

impl Runs for Gitea {
    fn reaches(&mut self, base: &str, head: &str) -> Result<Reach, String> {
        let mut cmd = command(Self::me()?);
        cmd.args(["plan", base, head]).current_dir(&self.root);
        let out = run_bounded(cmd, Limits::new(Duration::from_secs(300))).map_err(|e| format!("`dev plan` could not run: {e}"))?;
        if !out.success() {
            return Err(format!("`dev plan {base} {head}` failed: {}", out.stderr_text().trim()));
        }
        let text = out.stdout_text();
        let plan: Value = text
            .lines()
            .find(|l| l.starts_with('{'))
            .and_then(|l| serde_json::from_str(l).ok())
            .ok_or("`dev plan` printed no JSON")?;
        Ok(reach_of(&plan))
    }

    fn publish(&mut self, commit: &str, git_ref: &str) -> Result<(), String> {
        let g = self.git();
        let (ok, out) = g.run_git(
            Child::Authed,
            &["push", "--quiet", "--force", "origin", &format!("{commit}:refs/heads/{git_ref}")],
        )?;
        if ok { Ok(()) } else { Err(out.trim().to_string()) }
    }

    fn dispatch(&mut self, git_ref: &str, base: &str) -> Result<Sent, String> {
        // The train always goes first: a member run never takes the gap between two workflows of a train's CI sequence.
        match reservation::wait_real(Duration::from_secs(45 * 60), &mut std::io::stderr())? {
            reservation::Free::Yes { .. } => {}
            reservation::Free::StillHeld { holder } => return Ok(Sent::Busy(format!("a train's CI sequence holds the runners: {holder}"))),
        }
        let req = dispatch::parse_request(WORKFLOW, git_ref, &[format!("base={base}")], MAX_DISPATCH_WAIT, None)?;
        let root = self.root.clone();
        let read = move |name: &str| std::fs::read_to_string(root.join(".gitea/workflows").join(name)).ok();
        let mut clock = dispatch::system_clock();
        let target = dispatch::Target {
            server: &self.server,
            repo: &self.repo,
            token: &self.token,
        };
        match dispatch::run(&mut self.http, &target, &req, &read, &mut clock, &mut std::io::stderr())? {
            dispatch::Dispatched::Yes { .. } => Ok(Sent::Yes),
            dispatch::Dispatched::StillBusy { last } => Ok(Sent::Busy(last)),
        }
    }

    fn find_run(&mut self, commit: &str) -> Result<Option<u64>, String> {
        // The run exists within seconds of the dispatch; ask for up to two minutes (bounded: ER-32).
        for attempt in 0..12 {
            let mut c = Client::new(&mut self.http, &self.server, &self.repo, &self.token);
            let page = c.runs_page_where(1, &format!("head_sha={commit}"))?;
            if let Some(r) = page
                .runs
                .iter()
                .filter(|r| r.workflow() == WORKFLOW && r.head_sha == commit)
                .map(|r| r.id)
                .max()
            {
                return Ok(Some(r));
            }
            if attempt < 11 {
                std::thread::sleep(Duration::from_secs(10));
            }
        }
        Ok(None)
    }

    fn wait(&mut self, run: u64) -> Result<RunEnd, String> {
        let mut cmd = command(Self::me()?);
        cmd.args(["wait", "--ci-run", &run.to_string(), "--max", MAX_RUN_WAIT]);
        // The wait ends at its own --max; the outer bound only ends a hang (ER-32). What decides is the run's own state.
        let _ = run_bounded(cmd, Limits::new(Duration::from_secs(2 * 3600 + 300))).map_err(|e| format!("`dev wait` could not run: {e}"))?;
        let mut c = Client::new(&mut self.http, &self.server, &self.repo, &self.token);
        match c.run(run)? {
            Some(r) if r.finished() => Ok(RunEnd::Finished),
            Some(_) => Ok(RunEnd::StillRunning),
            None => Err(format!("run {run} is not listed")),
        }
    }

    fn jobs(&mut self, run: u64) -> Result<Vec<JobRow>, String> {
        let mut c = Client::new(&mut self.http, &self.server, &self.repo, &self.token);
        let jobs: Vec<TimedJob> = c.timed_jobs(run)?.ok_or_else(|| format!("run {run} has no job list"))?;
        Ok(jobs
            .into_iter()
            .filter(|j| !j.is_caller())
            .map(|j| JobRow {
                name: j.name,
                conclusion: j.conclusion,
            })
            .collect())
    }

    fn failures(&mut self, run: u64) -> Result<Vec<Failure>, String> {
        let report = {
            let mut c = Client::new(&mut self.http, &self.server, &self.repo, &self.token);
            let req = triage::Request {
                run,
                against: None,
                app: None,
                days: 14,
                history: true,
                repo: self.repo.clone(),
                now_secs: time::now_secs(),
            };
            triage::collect(&mut c, &req, &mut |l| eprintln!("{l}"))?
        };
        let http: &mut dyn Http = &mut self.http;
        Ok(failures_of(&report, run, http, &self.server, &self.repo, &self.token))
    }

    fn delete(&mut self, git_ref: &str) {
        if let Err(e) = trial::delete(&self.git(), git_ref) {
            eprintln!("::warning::other-os: {git_ref} could not be deleted ({e}); run `./dev ci trial-prune`");
        }
    }
}

/// The real step for `merge check --gates`: a missing token or scratch folder is `not measured`, with what to set.
pub fn run_real(root: &Path, _git: &Git, merge: &Merge, enforced: bool) -> Step {
    match Gitea::from_env(root) {
        Err(why) => unmeasured(enforced, &why),
        Ok(mut g) => run(merge, &mut g, enforced),
    }
}

