    assert!(w.comments_of(1).join("\n").contains("a hunk of the other side is missing"));
    assert!(
        !git(&w.repos.origin, &["ls-tree", "-r", "--name-only", &head])
            .lines()
            .any(|l| l == "bad.txt"),
        "the flagged merge is not in the train"
    );
}

