}
fn reaches_nothing(_: &Path, _: &str, _: &str) -> Result<serde_json::Value, String> {
    Ok(serde_json::json!({"apps": [], "crates": true}))
}
fn reaches_everything(_: &Path, _: &str, _: &str) -> Result<serde_json::Value, String> {
