            on_top: Some("evil.txt"),
            ..forged_default(vec![plain("feat/pr1", &pr_head)])
        },
    );
    git(
        &w.repos.author,
        &["push", "--quiet", "origin", &format!("{forged}:refs/heads/main")],
    );
    let t = w.tick();
    assert!(!matches!(t, Tick::Landed { .. }), "{t:?}");
    assert!(!w.labels_of(1).contains(&"state/landed".to_string()));
}

