/// A failure of the train gates job that names `files`.
fn gate(files: &[&str]) -> Failure {
    Failure {
        what: "train gates (...): the job failed outside any test".into(),
        projects: set(&["traingate"]),
        files: files.iter().map(|s| s.to_string()).collect(),
        blame: Blame::New,
    }
}

