        ("scripts/a.sh", "x\n".to_string()),
        ("scripts/b.sh", "x\n".to_string()),
    ]);
    let d = tree.path();
    git(d, &["init", "-q", "-b", "main"]);
    git(d, &["add", "-A"]);
    git(d, &["commit", "-q", "-m", "base"]);
    git(d, &["checkout", "-q", "-b", "work"]);
    std::fs::write(d.join(EXCEPTIONS), list(&[("scripts/a.sh", "E5"), ("dev", "E3")])).unwrap();
    git(d, &["commit", "-q", "-am", "widen"]);
