        "{grew:?}"
    );
}

/// A control is hermetic (ER-21 class: a check's own control read the real repository): an in-memory tree has no git history, so the
/// control must hold whatever base ref the process has and whatever repository it is in. Here the process stands in a repository
/// whose lists differ from the control's; reaching for git would report the control's entries as added and fail the control.
#[test]
fn a_control_holds_in_a_repository_whose_lists_differ_from_its_own() {
    let repo = tree_of(&[
        (BASELINE, "{\"files\":[{\"path\":\"other.sh\",\"lines\":1}]}".to_string()),
        (
            EXCEPTIONS,
            "{\"exceptions\":[{\"path\":\"other\",\"id\":\"E1\",\"reason\":\"it must start first\",\"owner\":\"plan\"}]}".to_string(),
        ),
        ("other.sh", "x\n".to_string()),
    ]);
    git(repo.path(), &["init", "-q", "-b", "main"]);
    git(repo.path(), &["add", "-A"]);
    git(repo.path(), &["commit", "-q", "-m", "base"]);
    git(repo.path(), &["checkout", "-q", "-b", "work"]);
    std::fs::write(repo.path().join("other.sh"), "x\ny\n").unwrap();
    git(repo.path(), &["commit", "-q", "-am", "edit"]);
    // The process's working folder is changed and not restored: nextest runs every test in its own process, so no other test sees it.
    std::env::set_current_dir(repo.path()).unwrap();
    // the ref a control would compare with by default (origin/main) exists here, with lists that differ from the control's
    git(repo.path(), &["update-ref", "refs/remotes/origin/main", "main"]);
    let elsewhere = tree_of(&[
        (BASELINE, "{\"files\":[]}".to_string()),
        (EXCEPTIONS, "{\"exceptions\":[]}".to_string()),
        ("a.txt", "x\n".to_string()),
    ]);
    for id in ["C129", "C53"] {
        let o = RunOptions {
            only: Some(vec![id.into()]),
            base_ref: None,
            ..options(elsewhere.path(), "fixture")
        };
        let r = run_checks(&o, &registry()).unwrap();
        assert_eq!(
            r.json()["runs"][0]["control"],
            json!(true),
            "{id}'s control read the repository the process stands in"
        );
    }
}

/// The regeneration tool (`./dev check shell-baseline`, the port of the retired `paddock-shell-baseline.mjs`): no flag lists and writes
/// nothing, `--shrink` removes stale entries and lowers counts and never adds or raises, `--init` writes from every file.
#[test]
#[allow(clippy::disallowed_methods, reason = "a test starts the built binary; it ends it itself")]
fn the_shell_baseline_tool_lists_shrinks_and_inits() {
    let tree = tree_of(&[
        (
            BASELINE,
            "{\"files\":[{\"path\":\"a.sh\",\"lines\":4},{\"path\":\"gone.sh\",\"lines\":9},{\"path\":\"b.sh\",\"lines\":2}]}".to_string(),
        ),
        (EXCEPTIONS, "{\"exceptions\":[]}".to_string()),
        ("a.sh", "x\n".repeat(2)),
        ("b.sh", "x\n".repeat(5)),
        ("new.sh", "x\n".to_string()),
    ]);
    let run = |flag: Option<&str>| {
        let mut c = crate::dev_bin::command();
        c.args(["check", "shell-baseline", "--root"]).arg(tree.path());
        if let Some(f) = flag {
            c.arg(f);
        }
        let o = c.output().unwrap();
        assert!(
            o.status.success(),
            "{flag:?}: {}{}",
            String::from_utf8_lossy(&o.stdout),
            String::from_utf8_lossy(&o.stderr)
        );
        String::from_utf8_lossy(&o.stdout).into_owned()
    };
    let before = std::fs::read_to_string(tree.path().join(BASELINE)).unwrap();
    let listed = run(None);
    assert!(
        listed.contains("2\ta.sh") && listed.contains("1\tnew.sh") && listed.contains("3 shell files, 8 lines"),
        "{listed}"
    );
    assert_eq!(
        std::fs::read_to_string(tree.path().join(BASELINE)).unwrap(),
        before,
        "listing writes nothing"
    );
    let shrunk = run(Some("--shrink"));
    assert!(
        shrunk.contains("removed: gone.sh") && shrunk.contains("1 removed; 1 shell files are not in the baseline and were not added"),
        "{shrunk}"
    );
    let after: Value = serde_json::from_str(&std::fs::read_to_string(tree.path().join(BASELINE)).unwrap()).unwrap();
    assert_eq!(
        after["files"],
        json!([{"path": "a.sh", "lines": 2}, {"path": "b.sh", "lines": 2}]),
        "a.sh is lowered from 4 to 2, b.sh is not raised from 2 to 5, new.sh is not added, gone.sh is removed"
    );
    run(Some("--init"));
    let init: Value = serde_json::from_str(&std::fs::read_to_string(tree.path().join(BASELINE)).unwrap()).unwrap();
    assert_eq!(init["files"].as_array().unwrap().len(), 3, "--init writes every shell file");
}

//! The conformance engine of the Rust host (WP-10 batch 1) against the answers the JavaScript host gave (recorded in
//! `tests/fixtures/check/recorded`, `engine-*`, before the checks it ran were retired, pair P3): the same command line gives the same
//! stdout, the same `--out` and `--summary` files and the same exit code, over fixture trees, including the inline waivers of every
//! ported check; this working tree's findings are held to the recorded ones as a ceiling.
#![allow(clippy::unwrap_used, clippy::expect_used)]

use paddock_dev::check::{self, Check, CheckOutput, Control, Ctx, RunOptions, record::Precondition, run_checks};
use serde_json::{Value, json};
use std::path::{Path, PathBuf};

fn repo() -> PathBuf {
    crate::full_tree(&paddock_env::winpath::real(&Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")).unwrap())
}

/// What a host printed and left behind.
#[derive(Debug, PartialEq, Eq)]
struct Ran {
    code: Option<i32>,
    stdout: String,
    stderr: String,
    out: Option<String>,
    summary: Option<String>,
}

fn run_host(args: &[&str], scratch: &Path) -> Ran {
    let (out, summary) = (scratch.join("out.json"), scratch.join("summary.md"));
    let mut c = crate::dev_bin::command();
    c.arg("conformance");
    c.args(args)
        .arg("--out")
        .arg(&out)
        .arg("--summary")
        .arg(&summary)
        .current_dir(repo())
        .env_remove("PADDOCK_BASE_REF")
        .env_remove("GITHUB_STEP_SUMMARY");
    let o = c.output().expect("the host must run: the oracle cannot be skipped");
    let read = |p: &Path| std::fs::read_to_string(p).ok();
    let ran = Ran {
        code: o.status.code(),
        stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&o.stderr).into_owned(),
        out: read(&out),
        summary: read(&summary),
    };
    let _ = std::fs::remove_file(out);
    let _ = std::fs::remove_file(summary);
    ran
}

/// A run as recorded data, with the scratch folder and the tree's root named `<scratch>` and `<root>` (no machine in a recording, ER-46).
fn ran_json(r: &Ran, scratch: &Path, root: &str) -> Value {
    let scrub = |t: &str| {
        let t = t.replace(scratch.to_str().unwrap(), "<scratch>");
        if root.is_empty() { t } else { t.replace(root, "<root>") }
    };
    json!({
        "code": r.code,
        "stdout": scrub(&r.stdout),
        "stderr": scrub(&r.stderr),
        "out": r.out.as_deref().map(scrub),
        "summary": r.summary.as_deref().map(scrub),
    })
}

/// The Rust host over `args`, held to the answer the JS host recorded for `case` (stdout, `--out`, `--summary`, exit status and
/// standard error, byte for byte); returns the Rust answer.
fn same(case: &str, args: &[&str]) -> Ran {
    let b = tempfile::tempdir().unwrap();
    let rust = run_host(args, b.path());
    let root = args
        .iter()
        .position(|a| *a == "--root")
        .and_then(|i| args.get(i + 1))
        .copied()
        .unwrap_or("");
    let got = ran_json(&rust, b.path(), root);
    let want = crate::recorded::expect(case, &got);
    for k in ["code", "stdout", "out", "summary", "stderr"] {
        assert_eq!(got[k], want[k], "{k} of {args:?} ({case})");
    }
    rust
}

const PORTED: &str = "C39,C53,C119,C120";

fn tree(files: &[(&str, &str)]) -> tempfile::TempDir {
    let d = tempfile::tempdir().unwrap();
    for (p, t) in files {
        let f = d.path().join(p);
        std::fs::create_dir_all(f.parent().unwrap()).unwrap();
        std::fs::write(f, t).unwrap();
    }
    d
}

#[test]
fn this_working_tree_gives_the_report_files_within_what_the_js_host_gave() {
    let root = repo();
    // The tree changes under the tests: its findings are held to the recorded JS answer as a ceiling (`recorded::assert_tree_within`),
    // the shape of the report and its files exactly.
    let scratch = tempfile::tempdir().unwrap();
    let args = ["--app", "paddock", "--root", root.to_str().unwrap(), "--only", PORTED];
    let r = run_host(&args, scratch.path());
    crate::recorded::assert_tree_within(
        "engine-real-tree",
        &serde_json::from_str::<Value>(r.out.as_deref().unwrap()).unwrap(),
    );
    assert!(r.stdout.contains("paddock: 4 checks"), "{}", r.stdout);
    let out: Value = serde_json::from_str(r.out.as_deref().unwrap()).unwrap();
    assert_eq!(out["checks"], json!(["C39", "C53", "C119", "C120"]));
    assert!(
        out["waived"].as_array().unwrap().iter().any(|w| w["waiver"]["expires"] == "inline"),
        "the inline waivers of the tree are listed under waived"
    );
}

