    // conformance: layout-guess — a shell fixture for the strict-mode test, not a layout this code computes
    let bad = tree(&[("scripts/x.sh", "#!/bin/sh\nd=$(dirname \"$0\")/../deps\ncd \"$d\"\n")]);
    let loose = same(
