    git(&root, &["commit", "-q", "-m", "chore: gates"]);
    git(&root, &["checkout", "-q", "main"]);
    assert_eq!(dev(&root, &[]).1["id"], "C91", "a gates.toml id on another branch");
}

/// A git that returns nothing for `cat-file` must fail the scan: a skipped blob would hand out a taken id.
struct NoCatFile;
impl Exec for NoCatFile {
    fn run(&self, program: &str, args: &[&str], cwd: &Path, stdin: Option<&[u8]>) -> Result<String, paddock_cli::CliError> {
        if args.first() == Some(&"cat-file") {
            Ok(String::new())
        } else {
            Real.run(program, args, cwd, stdin)
        }
    }
}

#[test]
fn a_blob_that_cat_file_does_not_return_is_an_error() {
    let d = repo();
    let root = d.path().join("work");
    let err = command_with(&NoCatFile, Some(root.clone()), None, "2026-11-13").unwrap_err();
    assert!(err.to_string().contains("git cat-file returned nothing"), "{err}");
    assert!(command_with(&Real, Some(root), None, "2026-11-13").is_ok());
}

#[test]
fn the_parsers_read_each_shape() {
    assert_eq!(id_of_path("conformance/src/checks/C121-name.mjs"), Some(121));
    assert_eq!(id_of_path("conformance/src/checks/index.mjs"), None);
    assert_eq!(id_of_path("conformance/src/other/C9-x.mjs"), None);
    assert_eq!(ids_of_index("import C3 from './C3-a.mjs';\nimport x from 'y';\n"), vec![3]);
    assert_eq!(ids_of_readme("| C102 | a | |\n|---|---|\n| not | b |\n"), vec![102]);
    assert_eq!(id_of_path("tools/paddock-dev/src/check/c119.rs"), Some(119));
    assert_eq!(id_of_path("tools/paddock-dev/src/check/c53_liveness.rs"), Some(53));
    assert_eq!(id_of_path("tools/paddock-dev/src/check/mod.rs"), None);
    assert_eq!(id_of_path("conformance/reserved/C121-feat-x"), Some(121));
    assert_eq!(ids_of_gates("[[a]]\nid = \"C7\"\nid = \"other\"\nreason = \"id = C8\"\n"), vec![7]);
    assert_eq!(slug("Feat/New_thing"), "feat-new-thing");
}

fn clone_of(d: &Path, name: &str) -> std::path::PathBuf {
    let c = d.join(name);
    git(d, &["clone", "-q", d.join("origin.git").to_str().unwrap(), name]);
    c
}

/// ER-21: two agents reserving before either pushes a branch (C130 taken twice, 2026-11-16) get different ids, because the server
/// decides: the reservation is a ref created on origin, which a second push to the same ref cannot do.
#[test]
fn concurrent_reservations_from_two_clones_get_different_ids() {
    let d = repo();
    let (a, b) = (clone_of(d.path(), "ca"), clone_of(d.path(), "cb"));
    let mut ids = Vec::new();
    for _round in 0..5 {
        let (ra, rb) = (a.clone(), b.clone());
        let ta = std::thread::spawn(move || dev(&ra, &["--reserve", &format!("feat/a{}", std::process::id())]));
        let tb = std::thread::spawn(move || dev(&rb, &["--reserve", &format!("feat/b{}", std::process::id())]));
        let (ra, rb) = (ta.join().unwrap(), tb.join().unwrap());
        assert_eq!(ra.0, 0, "{}", ra.2);
        assert_eq!(rb.0, 0, "{}", rb.2);
        ids.push(ra.1["id"].as_str().unwrap().to_string());
        ids.push(rb.1["id"].as_str().unwrap().to_string());
        // A fresh branch name each round: drop the files so the next round reserves again.
        for c in [&a, &b] {
            std::fs::remove_dir_all(c.join(RESERVED_DIR)).unwrap();
        }
        let n = ids.len();
        assert_ne!(ids[n - 1], ids[n - 2], "both clones got {}: {ids:?}", ids[n - 1]);
    }
    let mut all = ids.clone();
    all.sort();
    all.dedup();
    assert_eq!(all.len(), ids.len(), "every reservation is unique: {ids:?}");
}

/// The reservation is on the server at once: a clone that never fetched a branch of the first sees it, and the ref says who took it.
#[test]
fn a_reservation_is_visible_on_origin_before_any_branch_is_pushed() {
    let d = repo();
    let (a, b) = (clone_of(d.path(), "ca"), clone_of(d.path(), "cb"));
    assert_eq!(dev(&a, &["--reserve", "feat/first"]).1["id"], "C41");
    let origin = d.path().join("origin.git");
    let shown = git_out(&origin, &["show", "refs/paddock/check-ids/C41"]);
    assert!(shown.contains("feat/first"), "{shown}");
    // Without --reserve the next id also skips it.
    assert_eq!(dev(&b, &[]).1["id"], "C42");
    assert_eq!(dev(&b, &["--reserve", "feat/second"]).1["id"], "C42");
}

/// A ref that appears between the scan and the push (the race itself) moves the push to the next number.
#[test]
fn a_taken_ref_moves_the_reservation_to_the_next_id() {
    let d = repo();
    let a = clone_of(d.path(), "ca");
    let origin = d.path().join("origin.git");
    let blob = git_out(&origin, &["rev-parse", "main"]).trim().to_string();
    for id in [41, 42] {
        git(&origin, &["update-ref", &format!("refs/paddock/check-ids/C{id}"), &blob]);
    }
    assert_eq!(dev(&a, &["--reserve", "feat/late"]).1["id"], "C43");
}

/// A server that refuses the reservation push (a pre-receive hook, as a rights or policy refusal) is an error that says no id was
/// taken, and no reservation file is written.
#[cfg(unix)]
#[test]
fn a_refusing_server_is_an_error_and_writes_no_file() {
    use std::os::unix::fs::PermissionsExt;
    let d = repo();
    let a = clone_of(d.path(), "ca");
    let hook = d.path().join("origin.git/hooks/pre-receive");
    std::fs::create_dir_all(hook.parent().unwrap()).unwrap();
    std::fs::write(&hook, "#!/bin/sh\necho refused by policy >&2\nexit 1\n").unwrap();
    std::fs::set_permissions(&hook, std::fs::Permissions::from_mode(0o755)).unwrap();
    let (code, _, err) = dev(&a, &["--reserve", "feat/nope"]);
    assert_eq!(code, 1, "{err}");
    assert!(err.contains("::error::") && err.contains("no id was taken"), "{err}");
    assert!(!a.join(RESERVED_DIR).exists(), "no reservation file without a reservation");
}

/// The hand-numbered files of branches that never used the server (C130 and C131 on 2026-11-16) still count, with no ref on origin.
#[test]
fn hand_written_reservation_files_without_a_server_ref_still_count() {
    let d = repo();
    let a = clone_of(d.path(), "ca");
    git(&a, &["checkout", "-q", "-b", "golden", "origin/main"]);
    reserve_file(&a, 131, "feat/golden");
    git(&a, &["add", "-A"]);
    git(&a, &["commit", "-q", "-m", "chore: reserve"]);
    git(&a, &["push", "-q", "origin", "golden"]);
    git(&a, &["checkout", "-q", "main"]);
    let b = clone_of(d.path(), "cb");
    reserve_file(&b, 130, "feat/stand-in");
    assert_eq!(
        dev(&b, &[]).1["id"],
        "C132",
        "a pushed hand-written file and a local one are both counted"
    );
    assert_eq!(dev(&b, &["--reserve", "feat/next"]).1["id"], "C132");
}

//! `dev ci isolation` (the Rust port of the CI kit's job-isolation.sh, RT-1) as a real process, over the real slot holder: acquire,
//! a kept folder, release, and the sweep, plus the layouts of the ADR 0025 amendment of 2026-11-10 (`{src}` and retired layouts),
//! which the shell script does not know. The parity cases against the script live in conformance/test/job-isolation.test.mjs
//! (`ISOLATION_CMD=<this binary>`). Unix only, like isolation.rs: the Windows host jobs run the real thing on every run.
// windows-twin: ci_isolation_windows.rs
#![cfg(unix)]
#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Output;

const AMENDED: &str =
    "target target-{name}-{src}-{slot} slot\nsrc src/{name}-{slot} slot\ntools tools shared\n# retired: target-{name}-{slot} 2026-11-10\n";

struct Host {
    ci: PathBuf,
    home: PathBuf,
    temp: PathBuf,
    env_file: PathBuf,
    tables: PathBuf,
}

impl Host {
    fn new(root: &Path, kept: &str) -> Host {
        let root = paddock_env::winpath::real(root).unwrap();
        let home = root.join("home");
        let temp = root.join("work/0123456789abcdef/tmp");
        let tables = root.join("tables");
        for d in [&home, &temp, &tables] {
            std::fs::create_dir_all(d).unwrap();
        }
        std::fs::write(tables.join("kept-folders.txt"), kept).unwrap();
        std::fs::write(tables.join("ports.txt"), "sccache 4227 1 1\n").unwrap();
        let env_file = root.join("work/0123456789abcdef/github-env");
        std::fs::write(&env_file, "").unwrap();
        Host {
            ci: home.join(".paddock-ci"),
            home,
            temp,
            env_file,
            tables,
        }
    }

    fn exported(&self) -> HashMap<String, String> {
        std::fs::read_to_string(&self.env_file)
            .unwrap()
            .lines()
            .filter_map(|l| l.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
            .collect()
    }

    // Starts the tool under test, git or a helper by program name (a throw-away fixture), never a process by pid (C53).
    #[allow(clippy::disallowed_methods)]
    fn run(&self, args: &[&str], envs: &[(&str, &str)], later: bool) -> Output {
        let mut cmd = crate::dev_bin::command();
        cmd.args(["ci", "isolation"])
            .args(args)
            .env("HOME", &self.home)
            .env("RUNNER_OS", "macOS")
            .env("RUNNER_TEMP", &self.temp)
            .env("GITHUB_ENV", &self.env_file)
            .env("PADDOCK_CI_TABLES", &self.tables)
            .env("PADDOCK_CI_SLOTS", "3")
            .env("PADDOCK_CI_KEEP_SLOTS", "1")
            .env("PADDOCK_CI_MIN_FREE_GB", "0")
            // ER-14: `dev disk check` must not depend on the real disk of the machine running the tests.
            .env("PADDOCK_DISK_WARN_GIB", "0")
            .env("PADDOCK_DISK_REFUSE_GIB", "0")
            .env("PADDOCK_DISK_INDEX", self.home.join("disk-index.sqlite"));
        if later {
            cmd.envs(self.exported());
        }
        cmd.envs(envs.iter().copied());
        cmd.output().unwrap()
    }
}

fn text(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

#[test]
fn acquires_uses_releases_and_sweeps_with_the_real_binary() {
    let d = tempfile::tempdir().unwrap();
    let h = Host::new(d.path(), "target target-{name}-{slot} slot\ntools tools shared\n");
    std::fs::create_dir_all(h.ci.join("target-old-s3")).unwrap();
    let acq = h.run(&["acquire"], &[], false);
    assert!(acq.status.success(), "{}", text(&acq.stderr));
    assert!(acq.stdout.is_empty(), "messages go to stderr");
    let env = h.exported();
    assert_eq!(env.get("PADDOCK_CI_SLOT").map(String::as_str), Some("s1"));
    assert!(env.get("PADDOCK_CI_SLOT_TOKEN").is_some_and(|t| !t.is_empty()));
    assert_eq!(
        env.get("PADDOCK_DEV").map(String::as_str),
        Some(crate::dev_bin::PATH),
        "the job pins this very binary"
    );
    assert!(
        !h.ci.join("target-old-s3").exists(),
        "the sweep removed the idle slot's folder under its lock"
    );
    let st = h.run(&["status"], &[], true);
    assert!(text(&st.stdout).contains("s1 busy: job folder"), "{}", text(&st.stdout));

    let path = h.run(&["path", "target", "x-app"], &[], true);
    assert_eq!(text(&path.stdout).trim(), h.ci.join("target-x-app-s1").to_str().unwrap());
    std::fs::create_dir_all(h.ci.join("target-y-s2")).unwrap();
    let rel = h.run(&["release"], &[], true);
    assert!(rel.status.success(), "{}", text(&rel.stderr));
    assert!(!h.ci.join("target-y-s2").exists());
    assert!(h.ci.join("target-x-app-s1").exists(), "the kept slot's folder stays");
    assert!(text(&h.run(&["status"], &[], false).stdout).contains("s1 free"));
}

/// A stand-in for `heavy` that records its arguments (a throw-away script, never a real queue).
fn fake_heavy(root: &Path, exit: i32) -> (PathBuf, PathBuf) {
    let log = root.join("heavy-calls");
    let bin = root.join("fake-heavy");
    paddock_testkit::exe::write_program(
        &bin,
        format!(
            "#!/bin/sh\necho \"$@\" >> '{}'\necho 'fake heavy says no' >&2\nexit {exit}\n",
            log.display()
        ),
    )
    .unwrap();
    (bin, log)
}

#[test]
fn a_host_job_announces_itself_to_the_agents_heavy_queue_for_as_long_as_it_holds_its_slot() {
    let d = tempfile::tempdir().unwrap();
    let h = Host::new(d.path(), "tools tools shared\n");
    let (bin, calls) = fake_heavy(d.path(), 0);
    let envs = [("PADDOCK_HEAVY_BIN", bin.to_str().unwrap())];
    let acq = h.run(&["acquire"], &envs, false);
    assert!(acq.status.success(), "{}", text(&acq.stderr));
    let holder = std::fs::read_to_string(h.ci.join("slots/s1.owner")).unwrap();
    let pid = holder.lines().find_map(|l| l.strip_prefix("pid=")).unwrap().to_string();
    assert_eq!(std::fs::read_to_string(&calls).unwrap().trim(), format!("mark ci-s1 --pid {pid}"));
    assert!(text(&acq.stderr).contains("announced ci-s1"), "{}", text(&acq.stderr));
    let rel = h.run(&["release"], &envs, true);
    assert!(rel.status.success(), "{}", text(&rel.stderr));
    let all = std::fs::read_to_string(&calls).unwrap();
    assert_eq!(all.lines().last().unwrap(), format!("mark --remove ci-s1 --pid {pid}"), "{all}");
}

