// The per-job narrowing of `.gitea/` and `conformance/ci` changes, made deterministic (the recorded cases and the history
// sample do not reach every job): uncommitted edits in a copy of this repository, the script as the oracle.

/// `plan_gitea::CI_JOBS` is the table `tests/golden/ci-jobs.json` records (it was `CI_JOBS` of `scripts/affected.mjs`): a change of
/// which projects a ci.yml job reaches is a reviewed edit of both.
#[test]
fn the_ci_jobs_table_equals_the_recorded_one() {
    let ours: serde_json::Map<String, Value> = paddock_dev::plan_gitea::CI_JOBS
        .iter()
        .map(|(job, projects)| (job.to_string(), json!(projects)))
        .collect();
    let path = golden_dir().join("ci-jobs.json");
    if bless() {
        record(&path, &Value::Object(ours));
        return;
    }
    let recorded: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert!(
        recorded.as_object().is_some_and(|m| m.len() >= 10),
        "a positive control: the recorded table is not empty"
    );
    assert_eq!(Value::Object(ours), recorded, "{REGENERATE}");
}

/// Adds a comment line to `rel` in `root` (inside the job `job` of a workflow, right under its key, when one is named).
fn touch(root: &Path, rel: &str, job: Option<&str>) {
    let path = root.join(rel);
    let text = std::fs::read_to_string(&path).unwrap();
    let edited = match job {
        Some(job) => {
            let key = regex::Regex::new(&format!(r"(?m)^  {}:[^\n]*\n", regex::escape(job))).unwrap();
            let m = key.find(&text).unwrap_or_else(|| panic!("job {job} in {rel}"));
            format!("{}    # touched by the narrowing test\n{}", &text[..m.end()], &text[m.end()..])
        }
        None if rel.ends_with(".mjs") => format!("{text}\n// touched by the narrowing test\n"),
        None => format!("{text}\n# touched by the narrowing test\n"),
    };
    std::fs::write(path, edited).unwrap();
}

/// A fresh one-commit repository in `dst` holding the files of `src` that are present on disk, as stored (LF for text).
///
/// Not `git clone`: CI checks out a depth-1, blob-less, sparse clone, in which a local clone must fetch blobs from a promisor
/// remote that is not there ("lazy fetching disabled"). The files this test reads are on disk in every kind of checkout.
/// Ignore rules do not apply: the index is built from `src`'s, so tracked files that a rule matches stay in the graph, as in the
/// real repository.
///
/// Cheap by design (both live narrowing tests run it at once, on a loaded Windows host too): the copy borrows `src`'s object store
/// (`objects/info/alternates`) and takes its index entries, so no file is hashed or compressed again, and git writes each file
/// once, as stored (LF for text). The blob of every file on disk is in that store, a blob-less clone's included: checking a file out fetched it.
/// Only files edited in `src` (`ls-files -m`, none in CI) are hashed, from their content on disk.
fn copy_checked_out_files(src: &Path, dst: &Path) {
    use std::io::Write;
    use std::process::Stdio;
    let git = |dir: &Path, args: &[&str]| {
        let out = Command::new("git").arg("-C").arg(dir).args(args).output().unwrap();
        assert!(out.status.success(), "git {args:?}: {}", String::from_utf8_lossy(&out.stderr));
        out.stdout
    };
    let git_with_input = |dir: &Path, args: &[&str], input: Vec<u8>| {
        let mut child = Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        // The input is written from its own thread while this one drains stdout and stderr, so neither side can stall on a full pipe.
        let mut stdin = child.stdin.take().unwrap();
        let writer = std::thread::spawn(move || stdin.write_all(&input));
        let out = child.wait_with_output().unwrap();
        writer.join().unwrap().unwrap();
        assert!(out.status.success(), "git {args:?}: {}", String::from_utf8_lossy(&out.stderr));
    };
    let on_disk = |rel: &str| std::fs::symlink_metadata(src.join(rel)).is_ok_and(|m| m.is_file());
    // `<mode> <blob> <stage>\t<path>` per entry. Files outside a sparse checkout are listed but not on disk (and their blobs are
    // not in a blob-less clone's store); a symlink is not a regular file here (conformance C57).
    let staged = git(src, &["ls-files", "--stage", "-z"]);
    let mut entries = Vec::new();
    for entry in staged.split(|b| *b == 0).filter(|r| !r.is_empty()) {
        let text = std::str::from_utf8(entry).unwrap();
        let (_, rel) = text.split_once('\t').unwrap_or_else(|| panic!("ls-files --stage entry {text:?}"));
        if on_disk(rel) {
            entries.extend_from_slice(entry);
            entries.push(0);
        }
    }
    let common = String::from_utf8(git(src, &["rev-parse", "--git-common-dir"])).unwrap();
    let objects = paddock_env::winpath::real(&src.join(common.trim()).join("objects")).unwrap();
    std::fs::create_dir_all(dst).unwrap();
    git(dst, &["init", "-q"]);
    // `input` stores LF whatever the host's checkout wrote, and checkouts in the copy write what is stored: LF.
    git(dst, &["config", "core.autocrlf", "input"]);
    git(dst, &["config", "core.eol", "lf"]);
    // No automatic packing: the copy's own objects stay as written (and the mechanism test counts loose and packed alike).
    git(dst, &["config", "gc.auto", "0"]);
    // `canonicalize` on Windows returns a verbatim path: `\\?\C:\...` for a drive, `\\?\UNC\server\share\...` for a share. Git
    // reads `C:/...` and `//server/share/...`.
    let objects = paddock_testkit::path::text(&objects);
    std::fs::write(dst.join(".git/objects/info/alternates"), format!("{objects}\n")).unwrap();
    git_with_input(dst, &["update-index", "-z", "--index-info"], entries);
    // A fresh index has no file on disk to keep: every entry is written, and `-u` records what was written.
    git(dst, &["checkout-index", "--all", "--force", "--quiet", "-u"]);
    let edited: Vec<String> = modified_files(src).into_iter().filter(|rel| on_disk(rel)).collect();
    if !edited.is_empty() {
        for rel in &edited {
            std::fs::copy(src.join(rel), dst.join(rel)).unwrap_or_else(|e| panic!("copy {rel}: {e}"));
        }
        let list: Vec<u8> = edited.iter().flat_map(|rel| rel.bytes().chain([0])).collect();
        git_with_input(
            dst,
            &[
                "-c",
                "core.safecrlf=false",
                "add",
                "-f",
                "--pathspec-from-file=-",
                "--pathspec-file-nul",
            ],
            list.clone(),
        );
        // The edited files as stored (LF), as the rest.
        for rel in &edited {
            std::fs::remove_file(dst.join(rel)).unwrap();
        }
        git_with_input(dst, &["checkout-index", "--force", "--quiet", "-u", "-z", "--stdin"], list);
    }
    git(
        dst,
        &[
            "-c",
            "user.name=test",
            "-c",
            "user.email=test@example.invalid",
            "commit",
            "-q",
            "--no-verify",
            "-m",
            "copy",
        ],
    );
}

/// Tracked files of `src` whose content on disk differs from the index (`git ls-files -m`).
fn modified_files(src: &Path) -> Vec<String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(src)
        .args(["ls-files", "-m", "-z"])
        .output()
        .unwrap();
    assert!(out.status.success(), "git ls-files -m: {}", String::from_utf8_lossy(&out.stderr));
    out.stdout
        .split(|b| *b == 0)
        .filter(|r| !r.is_empty())
        .map(|r| String::from_utf8(r.to_vec()).unwrap())
        .collect()
}

/// Objects in `repo`'s own store, loose and packed (`count` plus `in-pack` of `git count-objects -v`; its alternates are not
/// counted). Both, because `gc --auto` may pack loose objects at any time.
fn own_objects(repo: &Path) -> usize {
    let out = Command::new("git")
        .arg("-C")
        .arg(repo)
        .args(["count-objects", "-v"])
        .output()
        .unwrap();
    assert!(out.status.success(), "git count-objects: {}", String::from_utf8_lossy(&out.stderr));
    String::from_utf8(out.stdout)
        .unwrap()
        .lines()
        .filter_map(|l| l.strip_prefix("count: ").or_else(|| l.strip_prefix("in-pack: ")))
        .map(|n| n.trim().parse::<usize>().unwrap())
        .sum()
}

/// The live narrowing tests each copy this repository, at the same time. Hashing and compressing every checked-out file into a new
/// object store (`git add -A` of the about 11,000 files of CI's lean checkout, then a full rewrite) took most of their 240 s budget on the Windows
/// host runner with the host to itself (run 7881: 183 s and 236 s) and passed it when another job shared the host (runs 7879,
/// 7893). The copy borrows the source's objects instead and hashes only files that differ from them: its own store holds the
/// trees a sparse checkout changes, the commit and those few files.
#[test]
fn the_repository_copy_reuses_the_source_objects_instead_of_hashing_every_file() {
    let dir = tempfile::tempdir().unwrap();
    let copy = dir.path().join("copy");
    copy_checked_out_files(&repo_root(), &copy);
    let listed = Command::new("git")
        .arg("-C")
        .arg(&copy)
        .args(["ls-files", "-z"])
        .output()
        .unwrap()
        .stdout;
    let files: Vec<&Path> = listed
        .split(|b| *b == 0)
        .filter(|r| !r.is_empty())
        .map(|r| Path::new(std::str::from_utf8(r).unwrap()))
        .collect();
    let folders: std::collections::BTreeSet<&Path> = files.iter().flat_map(|f| f.ancestors().skip(1)).collect();
    assert!(
        files.len() > 1000,
        "a positive control: the copy holds the checked-out files ({})",
        files.len()
    );
    let own = own_objects(&copy);
    let budget = folders.len() + 1 + modified_files(&repo_root()).len();
    assert!(
        own <= budget,
        "the copy wrote {own} objects of its own for {} files in {} folders (at most {budget} expected): it hashed the files \
         instead of borrowing the source's objects",
        files.len(),
        folders.len()
    );
}

// It copies the checked-out files and runs the script and the planner for every edit. ADR 0103: the edits are split over a few
// copies that run side by side (`run_cases`); one copy, one edit after the other, took 21 s at load 27 and 80-121 s on the loaded CI
// Mac (runs 8060, 8066, 8099, SLOW lines).
#[test]
fn workflow_action_and_script_edits_narrow_the_plan() {
    // The jobs of ci.yml that CI_JOBS names; one action, one reusable workflow, one script of conformance/ci and a helper it imports.
    let jobs: Vec<&str> = paddock_dev::plan_gitea::CI_JOBS.iter().map(|(j, _)| *j).collect();
    let ci = std::fs::read_to_string(repo_root().join(".gitea/workflows/ci.yml")).unwrap();
    let mut edits: Vec<(String, Option<String>)> = jobs
        .iter()
        .filter(|j| ci.contains(&format!("\n  {j}:")))
        .map(|j| (".gitea/workflows/ci.yml".to_string(), Some(j.to_string())))
        .collect();
    assert!(edits.len() >= 10, "ci.yml has the jobs CI_JOBS names: {edits:?}");
    for rel in [
        ".gitea/actions/node-caches/action.yml",
        ".gitea/workflows/app-fuzz.yml",
        "conformance/ci/install-test-browser.mjs",
        "conformance/ci/runtime-catalogue.mjs",
        "conformance/ci/build-folder.sh",
    ] {
        edits.push((rel.to_string(), None));
    }
    let narrowed = std::sync::atomic::AtomicUsize::new(0);
    let per = edits.len().div_ceil(paddock_testkit::cases::case_threads().min(4));
    let cases = edits
        .chunks(per)
        .enumerate()
        .map(|(n, chunk)| {
            let narrowed = &narrowed;
            paddock_testkit::case(format!("copy {n} ({} edits)", chunk.len()), move || {
                edits_on_a_copy(chunk, narrowed)
            })
        })
        .collect();
    paddock_testkit::run_cases("the workflow, action and script edits", cases);
    let narrowed = narrowed.into_inner();
    assert!(
        narrowed >= 10,
        "a positive control: most of these edits narrow the plan ({narrowed} of {})",
        edits.len()
    );
}

/// One case of [`workflow_action_and_script_edits_narrow_the_plan`]: a copy of its own, then each edit
/// in turn (the edits share the copy, so they run one after the other here), counting the plans that narrowed.
fn edits_on_a_copy(edits: &[(String, Option<String>)], narrowed: &std::sync::atomic::AtomicUsize) {
    let dir = tempfile::tempdir().unwrap();
    let copy = dir.path().join("copy");
    let started = Instant::now();
    copy_checked_out_files(&repo_root(), &copy);
    eprintln!("copy of the checked-out files: {:.1} s", started.elapsed().as_secs_f64());
    // LF checkout on every host: the workflow split reads LF text (a CRLF checkout cannot be split by either planner).
    assert!(
        !std::fs::read_to_string(copy.join(".gitea/workflows/ci.yml"))
            .unwrap()
            .contains('\r'),
        "the copy's ci.yml has CRLF line endings: the workflow split reads LF text, so every edit would mark everything"
    );
    let history = GitHistory::new(&copy, Duration::from_secs(60));
    // The edits change the text of tracked files, never which files or manifests exist: one reading of the graph serves all.
    let started = Instant::now();
    let graph = read_graph(&copy, &history).unwrap();
    eprintln!("read_graph: {:.1} s", started.elapsed().as_secs_f64());
    for (rel, job) in edits {
        touch(&copy, rel, job.as_deref());
        let req = Request {
            files: vec![rel.clone()],
            all: false,
            explain: true,
            root: None,
            base: None,
            head: "HEAD".into(),
        };
        let started = Instant::now();
        let got = canonical(plan_on_graph(&copy, &history, &req, &graph).unwrap());
        eprintln!("edit of {rel} (job {job:?}): plan {:.1} s", started.elapsed().as_secs_f64());
        // A job edit reaches exactly the projects CI_JOBS names for it, plus conformance (in every plan); an action or script edit
        // is narrowed, never everything. (`plan` wires every other job, so its edit is everything by design.)
        match job {
            Some(job) => {
                let projects = paddock_dev::plan_gitea::CI_JOBS.iter().find(|(j, _)| j == job).unwrap().1;
                if projects == ["everything"] {
                    assert_eq!(got["all"], true, "an edit of the plan job reaches everything");
                } else {
                    assert_eq!(got["all"], false, "an edit of job {job} is narrowed");
                    let mut want: std::collections::BTreeSet<String> = projects.iter().map(|p| p.to_string()).collect();
                    want.insert("conformance".into());
                    let mut have: std::collections::BTreeSet<String> = [
                        ("crates", "crates"),
                        ("ui", "ui"),
                        ("eslint", "eslint"),
                        ("conformance", "conformance"),
                        ("c99", "c99"),
                        ("tools", "tools"),
                        ("icons", "icons"),
                        ("ciImage", "ci-image"),
                        ("paddockDev", "paddock-dev"),
                    ]
                    .iter()
                    .filter(|(k, _)| got[k] == true)
                    .map(|(_, p)| p.to_string())
                    .collect();
                    if got["apps"].as_array().is_some_and(|a| !a.is_empty()) {
                        have.insert("apps".into());
                    }
                    assert_eq!(have, want, "projects reached by an edit of job {job} of {rel}");
                }
            }
            None => assert_eq!(got["all"], false, "an edit of {rel} is narrowed"),
        }
        narrowed.fetch_add(usize::from(got["all"] == false), std::sync::atomic::Ordering::Relaxed);
        let restored = Command::new("git")
            .arg("-C")
            .arg(&copy)
            .args(["checkout", "-q", "--", rel])
            .status()
            .unwrap();
        assert!(restored.success());
    }
}

#[test]
fn guard_edits_mark_conformance() {
    let dir = tempfile::tempdir().unwrap();
    let copy = dir.path().join("copy");
    let started = Instant::now();
    copy_checked_out_files(&repo_root(), &copy);
    eprintln!("copy of the checked-out files: {:.1} s", started.elapsed().as_secs_f64());
    let history = GitHistory::new(&copy, Duration::from_secs(60));
    let started = Instant::now();
    let graph = read_graph(&copy, &history).unwrap();
    eprintln!("read_graph: {:.1} s", started.elapsed().as_secs_f64());
    // A new Rust test with an ignore and a TypeScript spec with an environment guard, and a comment-only edit of each (no mark).
    let edits: [(&str, &str, bool); 4] = [
        (
            "crates/paddock-cli/src/lib.rs",
            "\n#[test]\n#[ignore]\nfn skipped_by_the_guard_test() {}\n",
            true,
        ),
        ("crates/paddock-cli/src/lib.rs", "\n// a comment\n", false),
        (
            "ui/projects/paddock-ui/src/public-api.ts",
            "\nit('guarded', () => { void process.env.X; });\n",
            true,
        ),
        ("ui/projects/paddock-ui/src/public-api.ts", "\n// a comment\n", false),
    ];
    for (rel, add, marks) in edits {
        let path = copy.join(rel);
        let original = std::fs::read_to_string(&path).unwrap();
        std::fs::write(&path, format!("{original}{add}")).unwrap();
        let req = Request {
            files: vec![rel.to_string()],
            all: false,
            explain: true,
            root: None,
            base: None,
            head: "HEAD".into(),
        };
        let started = Instant::now();
        let got = canonical(plan_on_graph(&copy, &history, &req, &graph).unwrap());
        eprintln!("guard edit of {rel} ({add:?}): plan {:.1} s", started.elapsed().as_secs_f64());
        let reasons = got["why"]["conformance"].as_array().cloned().unwrap_or_default();
        let marked = reasons
            .iter()
            .any(|r| r.as_str().is_some_and(|r| r.starts_with("C100: an ignore attribute")));
        assert_eq!(marked, marks, "the content rule on {rel} with {add:?}");
        std::fs::write(&path, original).unwrap();
    }
}

//! The host steps of `dev ci` against the shell they replace (docs/plans/ci-in-rust.md, WP-4): `stable-workspace`, `node-caches`,
//! `host-tools`, `sccache-stats`, `build-folder`, `prune-folder`, `prune-build-folder` and `host-cleanup` run once as the shell does
//! (`conformance/ci/host/*.sh`, `build-folder.sh`, `tools/prune-*.sh`, `tools/host-cleanup.sh`, under the runner's `bash -e -o
//! pipefail`) and once as the Rust command, each on its own copy of the same fixture folder, and must agree on everything that
//! reaches the job: the exit code, standard output, `$GITHUB_ENV`, `$GITHUB_PATH`, the calls of the wrapped programs and the state of
//! the folders afterwards. Spellings that differ on purpose are normalised before the comparison: durations, the scratch folder, the
//! `run:`/`ran:` lines of the wrapper contract, `ci isolation`'s own messages (standard error in the script) and the `Next step:` the Rust errors add to the shell's cause (ER-27). Every case
//! runs under a scratch folder (ER-14: never the machine's CI home, temp folders or processes). Unix only: Windows jobs run the real
//! thing, and `host_steps_golden.rs` keeps the answers as literals for every OS.
// windows-twin: host_steps_golden.rs
#![cfg(unix)]
#![allow(clippy::unwrap_used, clippy::expect_used)]

use paddock_testkit::TestCommand;
use std::path::{Path, PathBuf};
use std::process::Stdio;

fn repo() -> PathBuf {
    paddock_env::winpath::real(&Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")).unwrap()
}

/// One fixture: a scratch folder with the runner's folders in it.
struct Fx {
    dir: tempfile::TempDir,
}

impl Fx {
    fn root(&self) -> PathBuf {
        paddock_env::winpath::real(self.dir.path()).unwrap()
    }

    fn p(&self, rel: &str) -> PathBuf {
        self.root().join(rel)
    }

    fn write(&self, rel: &str, text: &str) {
        let p = self.p(rel);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, text).unwrap();
    }

    fn script(&self, rel: &str, body: &str) {
        let p = self.p(rel);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        paddock_testkit::exe::write_program(p, format!("#!/bin/sh\n{body}\n")).unwrap();
    }

    /// A program on the front of PATH that records its call (arguments, and what it saw of the job's token) in `calls`.
    fn shim(&self, name: &str, body: &str) {
        let calls = self.p("calls");
        self.script(
            &format!("bin/{name}"),
            &format!("echo \"{name} $* token=${{GITHUB_TOKEN:-}}\" >> '{}'\n{body}", calls.display()),
        );
    }

    fn big(&self, rel: &str, kb: usize) {
        let data: Vec<u8> = (0..kb * 1024).map(|i| (i.wrapping_mul(2_654_435_761usize) >> 7) as u8).collect();
        self.write(
            &format!("{rel}/blob"),
            &String::from_utf8_lossy(&data.iter().map(|b| b % 26 + b'a').collect::<Vec<u8>>()),
        );
    }
}

fn fixture() -> Fx {
    // The scratch folder is `$TMPDIR` (a folder of the agent's own when the tests run under an agent), never the machine's own.
    let fx = Fx {
        dir: tempfile::Builder::new().prefix("paddock-hs-").tempdir().unwrap(),
    };
    std::fs::create_dir_all(fx.p("home")).unwrap();
    std::fs::create_dir_all(fx.p("bin")).unwrap();
    std::fs::create_dir_all(fx.p("work/abc/hostexecutor")).unwrap();
    fx.write("work/abc/hostexecutor/Cargo.toml", "x");
    fx
}

/// What a run leaves: the exit code, the normalised output and the files the job reads, and the folders' state.
#[derive(Debug, PartialEq, Eq)]
struct Seen {
    code: i32,
    stdout: String,
    github_env: String,
    github_path: String,
    calls: String,
    tree: Vec<String>,
}

/// The text with the fixture's folder, durations and the spellings that differ on purpose normalised.
fn norm(text: &str, fx: &Fx) -> String {
    let root = fx.root().display().to_string();
    let dur = regex::Regex::new(r" in \d+ s\b").unwrap();
    let private = regex::Regex::new(r"<ROOT>/tmp/(tmp\.[A-Za-z0-9]+|guardian-as-user\.[0-9]+\.[0-9]+)").unwrap();
    let secs_cell = regex::Regex::new(r"\| \d+ s \|").unwrap();
    let sizes = regex::Regex::new(r"(is|still) \d+( \(cap|;)").unwrap();
    let bash_killed = regex::Regex::new(r": line \d+: +\d+ Killed ").unwrap();
    let timed_out_last = regex::Regex::new(r"Last output: kept-clone: git [a-z-]+ failed \(timed out after \d+ s\)\.").unwrap();
    let timed_out_why = regex::Regex::new(r"\(kept-clone: git [a-z-]+ failed \(timed out after \d+ s\)\)").unwrap();
    let timed_out_line = regex::Regex::new(r"^kept-clone: git [a-z-]+ failed \(timed out after \d+ s\)$").unwrap();
    // The Rust phase says how many programs of an abandoned phase it ended and how long that took (ER-27); the shell's `bounded` ends
    // the function's tree and says nothing.
    let ended_line = regex::Regex::new(r": ended \d+ program\(s\) of the abandoned phase in \d+ ms$").unwrap();
    text.replace(&root, "<ROOT>")
        .lines()
        // The wrapper contract's lines, and the one line per pattern the Rust clean-up adds (ER-27).
        // The shim's `kit:` lines name the implementation it chose; they are not the step's output.
        .filter(|l| {
            !l.starts_with("run: ")
                && !l.starts_with("ran: ")
                && !l.starts_with("host-cleanup: pattern ")
                && !l.starts_with("kit: ")
                // bash's own note about the phase it killed at its limit (a job-control message, not the step's): macOS bash 3.2
                // says `Killed: 9`, Linux bash 5 `<script>: line N: <pid> Killed  <command>`.
                && !l.contains(" Killed: 9 ")
                && !bash_killed.is_match(l)
                // The Rust phase's error output names the git it ended at its limit; the shell's is empty (it killed the process).
                && !timed_out_line.is_match(l)
                && !ended_line.is_match(l)
        })
        .map(|l| {
            let l = dur.replace_all(l, " in N s").to_string();
            // The guardian step's private folder: `mktemp -d` in the shell, `guardian-as-user.<pid>.<n>` in Rust.
            let l = private.replace_all(&l, "<PRIVATE>").to_string();
            let l = secs_cell.replace_all(&l, "| N s |").to_string();
            // The shell says `cargo test --no-run failed`, the Rust command quotes the command (backticks) and names how it ended.
            let l = l.replace(
                "`cargo test --no-run` failed (exit 101; output above).",
                "cargo test --no-run failed (output above)",
            );
            let l = l.replace("cargo test --no-run failed (exit 101)", "cargo test --no-run failed (output above)");
            // The shell's `bounded` prints the exit status of the phase's last command; the Rust phase has one failure, `exit 1`.
            let l = l.replace(" failed (exit 128) in N s", " failed (exit 1) in N s");
            // A git that hangs: the Rust tool names the command in the last output (the shell's was empty, it ended the process itself).
            let l = timed_out_last.replace_all(&l, "Last output: .").to_string();
            let l = timed_out_why.replace_all(&l, "()").to_string();
            // The shell's last-output text ends with a space (the `tr` of the tail's last newline); the Rust text does not.
            let l = l.replace(" ); ", "); ").replace(") )", "))");
            // `du`'s directory blocks and ours differ by a kilobyte or two: the size in a prune line is not compared.
            let l = sizes
                .replace_all(&l, "$1 N$2")
                .to_string()
                .replace(" (.gitea/actions/host-tools)", "");
            // The guardian shell ends its error with the next step as a plain sentence; the Rust line says `Next step:`, cut below.
            let l = l.replace(
                ". Run the same command in the CI image to see it",
                ". Next step: run the same command in the CI image to see it.",
            );
            match (l.starts_with("::error::"), l.find(" Next step: ")) {
                (true, Some(at)) => l[..at].to_string(),
                _ => l,
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        .trim_end_matches('\n')
        .to_string()
}

/// Every file, folder and link below the fixture's `work`, `home`, `ws`, `mount` and `tmp` folders (the job's own files `github-*` and `calls` are
/// compared separately): `kind path` or `l path -> target`.
/// Left out: `.paddock-owner.toml`, which the Rust kit writes through dev-disk's slot paths and the shell fallback (deleted at WP-11) does not.
fn tree(fx: &Fx) -> Vec<String> {
    let mut out = Vec::new();
    let root = fx.root();
    let written = regex::Regex::new(r"(?m)^# Written by .*$").unwrap();
    let mut stack = vec![root.clone()];
    while let Some(d) = stack.pop() {
        // A folder the test made unreadable is listed as such (a step that removed it would leave no line).
        let Ok(listing) = std::fs::read_dir(&d) else {
            out.push(format!("unreadable {}", d.strip_prefix(&root).unwrap().display()));
            continue;
        };
        let mut entries: Vec<_> = listing.flatten().collect();
        entries.sort_by_key(|e| e.file_name());
        for e in entries {
            let p = e.path();
            let rel = p.strip_prefix(&root).unwrap().display().to_string();
            if matches!(rel.as_str(), "bin" | "calls" | "github-env" | "github-path") || rel.starts_with("bin/") {
                continue;
            }
            // The owner record `./dev disk` reads (feat/dev-disk): the Rust kit's slot paths write it, the shell fallback does not.
            // It is not part of what a step does, so the parity of the two compares everything else.
            if e.file_name() == ".paddock-owner.toml" {
                continue;
            }
            let t = e.file_type().unwrap();
            if t.is_symlink() {
                let target = std::fs::read_link(&p)
                    .unwrap()
                    .display()
                    .to_string()
                    .replace(&root.display().to_string(), "<ROOT>");
                out.push(format!("l {rel} -> {target}"));
            } else if t.is_dir() {
                out.push(format!("d {rel}"));
                stack.push(p);
            } else {
                // The size of a file is its content: a blob compares by length, text by text.
                let len = std::fs::metadata(&p).unwrap().len();
                let content = if len < 400 {
                    let text = std::fs::read_to_string(&p)
                        .unwrap_or_default()
                        .replace(&root.display().to_string(), "<ROOT>");
                    written.replace_all(&text, "# Written by <the step>").to_string()
                } else {
                    format!("{len} bytes")
                };
                out.push(format!("f {rel} {content:?}"));
            }
        }
    }
    out.sort();
    out
}

/// How to run one step: the shell form and the Rust form, with `<ROOT>` in any argument or variable replaced by the fixture's folder.
struct Step {
    shell: Vec<&'static str>,
    shell_env: Vec<(&'static str, String)>,
    rust: Vec<&'static str>,
    env: Vec<(&'static str, String)>,
    cwd: Option<&'static str>,
}

fn fill(s: &str, fx: &Fx) -> String {
    s.replace("<ROOT>", &fx.root().display().to_string())
}

fn base_env(fx: &Fx) -> Vec<(String, String)> {
    vec![
        ("PATH".into(), format!("{}:/usr/bin:/bin", fx.p("bin").display())),
        ("HOME".into(), fx.p("home").display().to_string()),
        ("PADDOCK_CI_TABLES".into(), repo().join("conformance/ci").display().to_string()),
        // A secret of the job that no step has any use for: the Rust command never passes it on.
        ("GITHUB_TOKEN".into(), "tok-secret".into()),
        ("GITHUB_ENV".into(), fx.p("github-env").display().to_string()),
        ("GITHUB_PATH".into(), fx.p("github-path").display().to_string()),
    ]
}

fn run_one(fx: &Fx, step: &Step, rust: bool) -> Seen {
    // Standard error joins standard output in the order written (`exec 2>&1`): `ci isolation`'s own messages go to standard error in
    // the script, and the step prints them with its own lines, so the two are compared as the job log shows them.
    let mut cmd = TestCommand::new("sh");
    cmd.args(["-c", "exec 2>&1; exec \"$@\"", "sh"]);
    if rust {
        cmd.arg(crate::dev_bin::PATH);
        cmd.arg("ci").args(step.rust.iter().map(|a| fill(a, fx)));
    } else {
        cmd.arg("bash");
        // The script's own path is the repository's; the arguments after it are the fixture's.
        let script = repo().join(step.shell[0]);
        cmd.args(["-e", "-o", "pipefail"])
            .arg(script)
            .args(step.shell[1..].iter().map(|a| fill(a, fx)));
    }
    let cwd = step.cwd.map_or_else(repo, |c| fx.p(c));
    cmd.current_dir(cwd);
    for (k, v) in base_env(fx)
        .into_iter()
        .chain(step.env.iter().map(|(k, v)| (k.to_string(), fill(v, fx))))
    {
        cmd.env(k, v);
    }
    if !rust {
        for (k, v) in &step.shell_env {
            cmd.env(k, fill(v, fx));
        }
    }
    // ADR 0103: every process the step starts ends with it. The step runs in a group of the reaper's with its token; the reaper ends
    // anything of the step still running (a hung git shim's `sleep`, a holder a phase limit left), and the test fails on a leak
    // (ER-14). The order matters: wait for the step itself, then reap, then read the pipes to their end, so a leaked process that
    // still holds a pipe cannot keep the read (and the test) waiting.
    let reaper = paddock_testkit_start::Reaper::new("a host step");
    cmd.stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = reaper.spawn_test(cmd).unwrap();
    let drain = |pipe: Option<Box<dyn std::io::Read + Send>>| {
        std::thread::spawn(move || {
            let mut buf = Vec::new();
            if let Some(mut p) = pipe {
                let _ = std::io::Read::read_to_end(&mut p, &mut buf);
            }
            buf
        })
    };
    let stdout = drain(child.stdout.take().map(|p| Box::new(p) as Box<dyn std::io::Read + Send>));
    let stderr = drain(child.stderr.take().map(|p| Box::new(p) as Box<dyn std::io::Read + Send>));
    let status = child.wait().unwrap();
    let left = reaper.reap();
    let out = std::process::Output {
        status,
        stdout: stdout.join().expect("the stdout reader panicked"),
        stderr: stderr.join().expect("the stderr reader panicked"),
    };
    assert!(
        left.is_empty(),
        "the {} step left processes running after it ended: {left:?}",
        if rust { "Rust" } else { "shell" }
    );
    let read = |rel: &str| std::fs::read_to_string(fx.p(rel)).unwrap_or_default();
    // The shell passes the whole environment to the programs it runs, so its shims see the job's token; the Rust command never lets
    // it through (ToolCall). The shell's side is read without it so every other difference shows, and a Rust leak shows as one.
    let calls = if rust {
        read("calls")
    } else {
        read("calls").replace("token=tok-secret", "token=")
    };
    // The raw output, before `norm`: the harness shows it only for a failing test, where a normalised line (a filtered job-control
    // note, a replaced spelling) could otherwise hide what the step really printed (ER-27).
    eprintln!(
        "---- {} raw output (exit {:?}) ----\n{}",
        if rust { "Rust" } else { "shell" },
        out.status,
        String::from_utf8_lossy(&out.stdout)
    );
    Seen {
        code: out.status.code().unwrap_or(-1),
        stdout: norm(&String::from_utf8_lossy(&out.stdout), fx),
        github_env: norm(&read("github-env"), fx),
        github_path: norm(&read("github-path"), fx),
        calls: norm(&calls, fx),
        tree: tree(fx),
    }
}

/// Runs both on a fresh fixture each (made by `setup`) and demands they agree; returns what the Rust command left.
fn same(setup: &(dyn Fn(&Fx) + Sync), step: &Step) -> Seen {
    // The two implementations share nothing, so they run side by side (ADR 0103): the test takes the slower one, not the sum.
    let (shell, rust) = paddock_testkit::both(
        || {
            let a = fixture();
            setup(&a);
            run_one(&a, step, false)
        },
        || {
            let b = fixture();
            setup(&b);
            run_one(&b, step, true)
        },
    );
    assert_eq!(shell, rust, "the shell (left) and the Rust command (right) differ");
    rust
}

