const PIN: &str = "0.9.149";

fn host_tools(os: &'static str) -> Step {
    Step {
        shell: vec!["conformance/ci/host/host-tools.sh"],
        shell_env: vec![],
        rust: vec!["host-tools"],
        env: vec![("RUNNER_OS", os.to_string()), ("PADDOCK_CI_SLOT", "s1".into())],
