        &step,
        &|fx| {
            fx.write("home/.paddock-ci/src/decryp7_paddock-crate-s1/crates/a/untracked.rs", "x");
            fx.write("home/.paddock-ci/src/decryp7_paddock-crate-s1/target/ignored.bin", "x");
