#[test]
fn kept_fixture_repos_start_no_background_git_maintenance() {
    // `git commit`, `fetch` and a push's `receive-pack` start `git maintenance run --auto --detach`, which holds
    // `objects/maintenance.lock` after the command returns. `git clone --bare work-repo origin.git` copies the objects folder file by
    // file, the lock with it when the commit's maintenance still runs: under load one fixture's origin then carried the lock and the
    // other's did not (or the copy failed on the vanishing lock), and the parity of the two trees failed. Measured with the fixture's
    // commit-then-clone, 8 loops in parallel: 104 of 1200 clones copied the lock, 0 of 1200 with `maintenance.auto=false`.
    let fx = fixture();
    kept_fixture(&fx);
    // conformance: test-steps — eight `git config --get` reads in all: milliseconds, not a sum of jobs
    for (dir, path) in [
        ("work-repo", "/usr/bin:/bin"),
        ("origin.git", "/usr/bin:/bin"),
        ("work/abc/hostexecutor", "/usr/bin:/bin"),
        ("work-repo", &std::env::var("PATH").unwrap()),
    ] {
        // The step's environment (a cleared one, the fixture's HOME) and the fixture's own git (the test's PATH).
        let get = |key: &str| {
            let mut git = paddock_proc::command("git");
            git.args(["config", "--get", key]).current_dir(fx.p(dir));
            paddock_proc::clean_env(&mut git, &[]);
            let out = git
                .env("PATH", path)
                .env("HOME", fx.p("home"))
                .env("GIT_CONFIG_NOSYSTEM", "1")
                .output()
                .unwrap();
            String::from_utf8_lossy(&out.stdout).trim().to_string()
        };
        assert_eq!(
            (get("maintenance.auto"), get("gc.auto")),
            ("false".to_string(), "0".to_string()),
            "{dir} (PATH {path}): git would start background maintenance in the fixture's repositories"
        );
    }
}

/// `bounded.sh` with a fake clock: `SECONDS` is a plain variable that the fake `sleep` (the poll's wait) moves one second per call,
/// `pgrep` names a fixed process tree (100 -> 101 -> 102) and `kill` records whom it ends. Prints what the script under test did.
fn bounded_sh(body: &str) -> String {
    let script = format!(
        "unset SECONDS; SECONDS=0\nsleep() {{ SECONDS=$((SECONDS + 1)); }}\n. '{}'\n{body}",
        repo().join("conformance/ci/bounded.sh").display()
    );
    let fx = fixture();
    fx.script("bin/pgrep", "case \"$2\" in 100) echo 101;; 101) echo 102;; esac");
    let out = TestCommand::new("bash")
        .args(["-c", &script])
        .env("PATH", format!("{}:/usr/bin:/bin", fx.p("bin").display()))
        .env("SCRATCH", fx.p("work"))
        .output()
        .unwrap();
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

#[test]
fn bounded_sh_never_ends_a_phase_before_its_limit() {
    // `SECONDS` counts whole seconds: a phase that starts at 0.9 s reads 1 s elapsed at 1.0 s. Ending it at `elapsed >= limit` ended
    // phases of 0.2 to 1 s as "did not finish within 1 s" (measured: 9 of 20 phases of 0.5 s); `elapsed > limit` means more than
    // `limit` seconds really passed.
    let out = bounded_sh(
        "tool=t limit=3 hint=h scratch=\"$SCRATCH\" BOUNDED_SOFT=1\nhang() { exec /bin/sleep 30; }\nbounded hang hang; echo \"rc=$? ticks=$SECONDS\"",
    );
    assert!(
        out.ends_with("rc=124 ticks=4"),
        "the phase must outlive its limit (3) by the clock's whole second: {out}"
    );
}

#[test]
fn bounded_sh_counts_the_limit_from_the_clock_mark() {
    // The phase does work before its hang (real time, while the fake clock races ahead with every poll), then writes the clock mark
    // and hangs. A stale mark from before the phase is removed when the phase starts. The limit (3) counts from the mark: the phase is ended only after the mark, 4 ticks after it was seen. Without the
    // mark the limit would have ended the phase in its work, before the mark (the kept-clone parity failure under load).
    let out = bounded_sh(
        "tool=t limit=3 hint=h scratch=\"$SCRATCH\" BOUNDED_SOFT=1 clock_mark=\"$SCRATCH/mark\" clock_wait=100000000\n\
         echo stale > \"$SCRATCH/mark\"\n\
         hang() { /bin/sleep 0.5; echo hang > \"$SCRATCH/mark\"; exec /bin/sleep 30; }\n\
         bounded hang hang; rc=$?; [ \"$(cat \"$SCRATCH/mark\" 2>/dev/null)\" = hang ] && m=after-mark || m=before-mark\n\
         echo \"rc=$rc $m\"",
    );
    assert!(
        out.ends_with("rc=124 after-mark"),
        "the phase ends at its limit counted from the mark: {out}"
    );
    assert!(out.contains("'hang' did not finish within 3 s"), "{out}");
    // A mark that never appears: the phase is bounded by clock_wait, and the line names that bound.
    let out = bounded_sh(
        "tool=t limit=3 hint=h scratch=\"$SCRATCH\" BOUNDED_SOFT=1 clock_mark=\"$SCRATCH/mark\" clock_wait=5\n\
         hang() { exec /bin/sleep 30; }\nbounded hang hang; echo \"rc=$? ticks=$SECONDS\"",
    );
    assert!(
        out.ends_with("rc=124 ticks=6"),
        "without its mark the phase ends at clock_wait (5): {out}"
    );
    assert!(out.contains("'hang' did not finish within 5 s"), "{out}");
}

#[test]
fn bounded_sh_ends_a_process_tree_parent_first() {
    // Ending the children first let the phase's shell see its child killed and write bash's `Killed: 9` note into the phase's error
    // output, which then stood in the warning's `Last output` (seen under load: 3 of 180 runs of the hung-phase test).
    let out = bounded_sh("kill() { echo \"killed $2\"; }\nkill_tree 100");
    assert_eq!(out, "killed 100\nkilled 101\nkilled 102", "a parent is ended before its children");
}

// ---- boot-volume ----

/// What a Mac's `df`, `diskutil` and `getconf` answer, by folder: a path under `ext` is on the external volume `/Volumes/Ext Disk`, any
/// other on `/`. The programs are shims (the test never asks the machine it runs on); their answers are fixed by the fixture, not by the
/// environment, as the tool starts them with a cleared one.
struct Mac {
    /// `df` names no mount.
    no_mount: bool,
    /// `diskutil` fails.
    no_plist: bool,
    /// What `getconf DARWIN_USER_TEMP_DIR` prints (`<ROOT>` filled in); empty: it fails.
    getconf: &'static str,
}

const MAC: Mac = Mac {
    no_mount: false,
    no_plist: false,
    getconf: "<ROOT>/home/internal-temp/",
};

fn boot_machine(fx: &Fx, mac: &Mac) {
    for d in ["ext/tmp", "home/internal-temp"] {
        std::fs::create_dir_all(fx.p(d)).unwrap();
    }
    let header = "echo 'Filesystem 512-blocks Used Available Capacity Mounted on'";
    let df = if mac.no_mount {
        header.to_string()
    } else {
        format!("case \"$2\" in */ext|*/ext/*) m='/Volumes/Ext Disk';; *) m='/';; esac\n{header}\necho \"/dev/disk9s1 100 1 99 1% $m\"")
    };
    fx.script("bin/df", &df);
    let plist = if mac.no_plist {
        "exit 1".to_string()
    } else {
        "case \"$*\" in *Ext*) v='<false/>';; *) v='<true/>';; esac\nprintf '<dict>\\n\\t<key>Internal</key>\\n\\t%s\\n</dict>\\n' \"$v\""
            .to_string()
    };
    fx.script("bin/diskutil", &plist);
    let getconf = if mac.getconf.is_empty() {
        "exit 1".to_string()
    } else {
        format!("printf '%s\\n' '{}'", fill(mac.getconf, fx))
    };
    fx.script("bin/getconf", &getconf);
}

fn boot(args: &[&'static str], extra: Vec<(&'static str, String)>) -> Step {
    let mut shell = vec!["conformance/ci/boot-volume.sh"];
    shell.extend_from_slice(args);
    let mut rust = vec!["boot-volume"];
    rust.extend_from_slice(args);
    Step {
        shell,
        shell_env: vec![],
        rust,
        env: extra,
        cwd: None,
    }
}

#[test]
fn boot_volume_says_which_volume_a_folder_is_on_and_where_the_boot_volumes_temp_folder_is() {
    let mac = |m: Mac| move |fx: &Fx| boot_machine(fx, &m);
    // `external`: by the exit code; a folder that is not made yet sits on the volume of its nearest parent.
    for (folder, code) in [
        ("<ROOT>/ext/tmp", 0),
        ("<ROOT>/home", 1),
        ("<ROOT>/ext/not/yet/made", 0),
        ("<ROOT>/home/not/yet/made", 1),
    ] {
        let seen = same(&mac(MAC), &boot(&["external", folder], vec![]));
        assert_eq!(seen.code, code, "{folder}: {seen:?}");
    }
    // `temp`: an internal folder stays (a trailing slash goes), an external one moves to the user's temp folder of the boot volume.
    let kept = same(&mac(MAC), &boot(&["temp", "<ROOT>/home/"], vec![]));
    assert_eq!(kept.stdout, "<ROOT>/home");
    let moved = same(&mac(MAC), &boot(&["temp", "<ROOT>/ext/tmp"], vec![]));
    assert!(moved.stdout.ends_with("\n<ROOT>/home/internal-temp"), "{moved:?}");
    assert!(
        moved
            .stdout
            .contains("boot-volume: using <ROOT>/home/internal-temp instead of <ROOT>/ext/tmp: "),
        "{moved:?}"
    );
    // No folder given: $TMPDIR.
    let from_env = same(&mac(MAC), &boot(&["temp"], vec![("TMPDIR", "<ROOT>/ext/tmp".into())]));
    assert!(from_env.stdout.ends_with("\n<ROOT>/home/internal-temp"), "{from_env:?}");
    // getconf fails, names a relative folder, a missing one, or an external one: the folder stays, with the warning.
    for getconf in ["", "relative", "<ROOT>/missing/", "<ROOT>/ext/tmp"] {
        let seen = same(&mac(Mac { getconf, ..MAC }), &boot(&["temp", "<ROOT>/ext/tmp"], vec![]));
        assert!(seen.stdout.ends_with("\n<ROOT>/ext/tmp"), "{getconf}: {seen:?}");
        assert!(
            seen.stdout.contains(
                "::warning::boot-volume: <ROOT>/ext/tmp is on an external volume and getconf DARWIN_USER_TEMP_DIR gave no internal folder ("
            ),
            "{getconf}: {seen:?}"
        );
    }
    // What cannot be judged is internal, with the reason on standard error; a failing diskutil is internal without one.
    let nomount = same(&mac(Mac { no_mount: true, ..MAC }), &boot(&["external", "<ROOT>/ext/tmp"], vec![]));
    assert_eq!(nomount.code, 1);
    assert!(nomount.stdout.contains("df names no mount; treated as internal"), "{nomount:?}");
    let noplist = same(&mac(Mac { no_plist: true, ..MAC }), &boot(&["external", "<ROOT>/ext/tmp"], vec![]));
    assert_eq!((noplist.code, noplist.stdout.as_str()), (1, ""));
}

// ---- guardian-as-user ----

/// A `crates` folder with a `cargo` that builds two unit-test binaries (fake programs) and a private temp folder. `proc_exit` is what
/// the paddock-proc test binary exits with; a failing one leaves the guardian's log, as the real tests do.
fn guardian_machine(fx: &Fx, proc_exit: i32) {
    std::fs::create_dir_all(fx.p("tmp")).unwrap();
    fx.shim(
        "cargo",
        concat!(
            "echo '   Compiling paddock-proc v0.1.0'\n",
            // conformance: layout-guess — a sample of cargo's own output, or the test binary it names; not a computed layout
            "echo '  Executable unittests src/lib.rs (target/debug/deps/paddock_proc-0123abcd)' >&2\n",
            // conformance: layout-guess — a sample of cargo's own output, or the test binary it names; not a computed layout
            "echo '  Executable tests/it/main.rs (target/debug/deps/it-ff)' >&2\n",
            // conformance: layout-guess — a sample of cargo's own output, or the test binary it names; not a computed layout
            "echo '  Executable unittests src/lib.rs (target/debug/deps/paddock_chromium-9f8e7d)' >&2"
        ),
    );
    fx.script(
        // conformance: layout-guess — a sample of cargo's own output, or the test binary it names; not a computed layout
        "crates/target/debug/deps/paddock_proc-0123abcd",
        &format!(
            "echo \"proc tests: $*\"\n\
             [ {proc_exit} = 0 ] || {{ echo 'guardian said no' > \"$PADDOCK_PROC_GUARDIAN_LOG\"; exit {proc_exit}; }}"
        ),
    );
    // conformance: layout-guess — a sample of cargo's own output, or the test binary it names; not a computed layout
    fx.script("crates/target/debug/deps/paddock_chromium-9f8e7d", "echo \"chromium tests: $*\"");
}

fn guardian() -> Step {
    Step {
        shell: vec!["conformance/ci/guardian-as-user.sh"],
        shell_env: vec![],
        rust: vec!["guardian-as-user"],
        // The summary file is read as `github-path` so the comparison sees it.
        env: vec![
            ("TMPDIR", "<ROOT>/tmp".into()),
            ("GITHUB_STEP_SUMMARY", "<ROOT>/github-path".into()),
        ],
        cwd: Some("crates"),
    }
}

/// bash before 4.4 (macOS ships 3.2) fails `"${as_user[@]}"` of an empty array under `set -u`: the script is for the Linux image (bash 5).
fn bash_too_old_for_the_script() -> bool {
    let out = TestCommand::new("bash")
        .args(["-c", "echo $((BASH_VERSINFO[0] * 100 + BASH_VERSINFO[1]))"])
        .output()
        .unwrap();
    String::from_utf8_lossy(&out.stdout).trim().parse::<u32>().unwrap_or(0) < 404
}

/// The Rust command alone on a fixture (the checks of its own output).
fn guardian_rust(setup: &dyn Fn(&Fx)) -> Seen {
    let fx = fixture();
    setup(&fx);
    run_one(&fx, &guardian(), true)
}

fn guardian_broken_build(fx: &Fx) {
    guardian_machine(fx, 0);
    fx.shim("cargo", "echo 'error[E0425]: nothing here' >&2; exit 101");
}

/// The script against the command on the same three fixtures. On a bash older than 4.4 the shell side cannot run, so the case is not
/// measured: it returns early with the reason printed (an env-gated test in the gate register, like the repo's other environment-gated
/// tests) unless `PADDOCK_REQUIRE_SHELL_PARITY` is set, which turns "not measured" into a failure (a Linux leg sets it).
#[test]
fn guardian_as_user_matches_the_shell() {
    if bash_too_old_for_the_script() {
        assert!(
            std::env::var_os("PADDOCK_REQUIRE_SHELL_PARITY").is_none(),
            "NOT MEASURED: bash is older than 4.4 and PADDOCK_REQUIRE_SHELL_PARITY demands the shell side"
        );
        eprintln!(
            "NOT MEASURED: guardian-as-user.sh parity (bash < 4.4: empty-array expansion under set -u); set PADDOCK_REQUIRE_SHELL_PARITY=1 to fail instead"
        );
        return;
    }
    same(&|fx| guardian_machine(fx, 0), &guardian());
    same(&|fx| guardian_machine(fx, 3), &guardian());
    same(&guardian_broken_build, &guardian());
}

#[test]
fn guardian_as_user_builds_the_unit_tests_and_runs_the_two_guardian_cases_as_the_calling_user() {
    // Run by a user (the test is not root: no setpriv, no sudo, ER-14), the tests run directly; the root path is the unit tests' (a fake
    // machine records the setpriv command line).
    let seen = guardian_rust(&|fx| guardian_machine(fx, 0));
    assert_eq!(seen.code, 0, "{seen:?}");
    assert!(
        seen.stdout.contains("Building the paddock-proc and paddock-chromium unit tests"),
        "{seen:?}"
    );
    assert!(seen.stdout.contains("proc tests: guardian::"), "{seen:?}");
    assert!(
        seen.stdout
            .contains("chromium tests: launch::tests::a_browser_whose_owner_is_killed"),
        "{seen:?}"
    );
    assert!(seen.stdout.contains("The guardian's acting tests passed as uid "), "{seen:?}");
    assert!(seen.github_path.contains("| `guardian::` | uid "), "{seen:?}");
    assert!(
        seen.calls
            .starts_with("cargo test --no-run --all-features -p paddock-proc -p paddock-chromium"),
        "{seen:?}"
    );
    // A failing test: its guardian log, one error line with the command, the summary row.
    let red = guardian_rust(&|fx| guardian_machine(fx, 3));
    assert_eq!(red.code, 1, "{red:?}");
    assert!(red.stdout.contains("The guardian's log:\nguardian said no"), "{red:?}");
    assert_eq!(red.stdout.lines().filter(|l| l.starts_with("::error::")).count(), 1, "{red:?}");
    assert!(
        red.stdout.contains("::error::guardian-as-user: `guardian::` failed as uid "),
        "{red:?}"
    );
    assert!(red.github_path.contains("failed (exit 3)"), "{red:?}");
    // A build that fails: its last lines, then one error line.
    let broken = guardian_rust(&guardian_broken_build);
    assert_eq!(broken.code, 1);
    assert!(broken.stdout.contains("error[E0425]: nothing here"), "{broken:?}");
    assert!(
        broken.stdout.contains("::error::guardian-as-user: cargo test --no-run failed"),
        "{broken:?}"
    );
}

//! The Windows twin of `host_steps.rs` (and a golden of the Rust output on every OS): the host steps of `dev ci` as real processes
//! with the exact lines and files the shell gave for the same inputs. The parity cases in `host_steps.rs` prove the equality on
//! Unix, where the scripts run; this file keeps the answers as literals so the Windows and Linux legs check them too (ER-9,
//! docs/plans/ci-in-rust.md section 7). The Windows spellings that cannot run elsewhere (junction, drive paths) are checked by the
//! unit tests of `ci_host` with an injected link maker and by the Windows jobs themselves.
#![allow(clippy::unwrap_used, clippy::expect_used)]

// conformance: file-layout-guess — the prune code never names `deps`; its tests use it only as filler data for a build folder to prune
use std::path::{Path, PathBuf};

struct Run {
    code: i32,
    stdout: String,
    github_env: String,
}

/// Starts the tool under test with a cleared environment (what the runner gives a step, no more) inside `dir`.
#[allow(clippy::disallowed_methods)]
fn dev(dir: &Path, args: &[&str], vars: &[(&str, String)]) -> Run {
    let env_file: PathBuf = dir.join("github-env");
    let mut cmd = crate::dev_bin::command();
    cmd.arg("ci").args(args).current_dir(dir).env_clear();
    for key in [
        "PATH",
        "SystemRoot",
        "SYSTEMROOT",
        "TEMP",
        "TMP",
        "NUMBER_OF_PROCESSORS",
        "COMSPEC",
        "PATHEXT",
    ] {
        if let Ok(v) = std::env::var(key) {
            cmd.env(key, v);
        }
    }
    cmd.env("GITHUB_ENV", &env_file)
        .env("HOME", dir.join("home"))
        .env("USERPROFILE", dir.join("home"));
    cmd.env(
        "PADDOCK_CI_TABLES",
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../conformance/ci"),
    );
    cmd.envs(vars.iter().map(|(k, v)| (*k, v)));
    let out = cmd.output().unwrap();
    Run {
        code: out.status.code().unwrap_or(-1),
        stdout: String::from_utf8_lossy(&out.stdout).replace("\r\n", "\n"),
        github_env: std::fs::read_to_string(&env_file).unwrap_or_default().replace("\r\n", "\n"),
    }
}

fn scratch() -> (tempfile::TempDir, PathBuf) {
    let d = tempfile::tempdir().unwrap();
    let root = paddock_env::winpath::real(d.path()).unwrap();
    // `canonicalize` gives `\\?\C:\...` on Windows; the tool prints plain paths.
    let root = PathBuf::from(root.display().to_string().trim_start_matches(r"\\?\"));
    std::fs::create_dir_all(root.join("home")).unwrap();
    (d, root)
}

fn forward(p: &Path) -> String {
    paddock_testkit::path::text(p)
}

#[test]
fn a_linux_container_leaves_the_workspace_and_a_missing_mount_is_a_notice() {
    let (_d, root) = scratch();
    let linux = [("RUNNER_OS", "Linux".to_string()), ("GITHUB_WORKSPACE", forward(&root))];
    let r = dev(&root, &["stable-workspace", "--name", "x"], &linux);
    assert_eq!((r.code, r.stdout.as_str()), (0, ""));
    let mut vars = linux.to_vec();
    vars.push(("PADDOCK_CI_MOUNT", forward(&root.join("no-mount"))));
    let r = dev(&root, &["node-caches", "--angular-dir", "ui", "--name", "e2e-1"], &vars);
    assert_eq!(r.code, 0);
    assert_eq!(
        r.stdout,
        "::notice::no /sccache mount in this container; the npm and Angular caches live and die with the job.\n"
    );
    assert_eq!(r.github_env, "", "nothing is exported without the mount");
}

#[test]
fn build_folder_in_a_container_builds_in_target_and_a_config_without_the_include_is_refused() {
