    assert_eq!(r.stdout, format!("build folder: {canon}/target\n"));
    std::fs::write(ws.join(".cargo/config.toml"), "[alias]\n").unwrap();
    let r = dev(&root, &["build-folder", &wsarg, "spotter-rust"], &[("RUNNER_OS", "Linux".into())]);
