        r.stdout
    );
    let r = dev(&root, &["build-folder", &wsarg, "a b"], &[("RUNNER_OS", "Linux".into())]);
    assert_eq!(r.code, 1);
    assert!(r.stdout.contains("may only hold letters, digits"), "{}", r.stdout);
}

#[test]
fn prune_folder_caps_a_folder_incremental_caches_first_and_refuses_a_bad_cap() {
    let (_d, root) = scratch();
