//! `inputs.txt` lists exactly what decides the binary: the tool's folder, the folders of its path dependencies (normal and
//! build dependencies only; dev-dependencies change the hash only through Cargo.lock) and the files that configure the build.
#![allow(clippy::disallowed_methods, clippy::unwrap_used, clippy::expect_used)]
use paddock_testkit::TestCommand;
use serde_json::Value;
use std::collections::BTreeSet;
use std::path::Path;

/// Files outside the dependency folders that cargo reads for this build.
const EXTRAS: [&str; 3] = ["tools/paddock-dev", "crates/Cargo.toml", ".cargo/config.toml"];
/// The same for `tools/heavy`, which `./dev check --pre-push` builds on demand under its own hash.
const HEAVY_EXTRAS: [&str; 3] = ["tools/heavy", "crates/Cargo.toml", ".cargo/config.toml"];

/// The triple this machine builds for. Metadata is read for it alone: the path dependencies are the same on every platform, and
/// resolving the others would need registry crates (Windows, Android) that an offline machine never downloaded.
fn host_triple() -> String {
    let out = TestCommand::new(std::env::var("RUSTC").unwrap_or_else(|_| "rustc".into()))
        .arg("-vV")
        .output()
        .unwrap();
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .find_map(|l| l.strip_prefix("host: "))
        .expect("rustc -vV prints the host")
        .to_string()
}

fn metadata(tool: &str) -> Value {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join(tool);
    let out = TestCommand::new(env!("CARGO"))
        .args([
            "metadata",
            "--format-version",
            "1",
            "--locked",
            "--offline",
            "--filter-platform",
            &host_triple(),
        ])
        .current_dir(dir)
        .output()
        .unwrap();
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    serde_json::from_slice(&out.stdout).unwrap()
}

/// The folders (relative to the repository root, `/`-separated) of the path dependencies reachable through normal and build edges.
fn path_dependency_folders(meta: &Value) -> BTreeSet<String> {
    let nodes = meta["resolve"]["nodes"].as_array().unwrap();
    let node = |id: &str| nodes.iter().find(|n| n["id"] == id).unwrap();
    let mut seen = BTreeSet::new();
    let mut todo = vec![meta["resolve"]["root"].as_str().unwrap().to_string()];
    while let Some(id) = todo.pop() {
        if !seen.insert(id.clone()) {
            continue;
        }
        for dep in node(&id)["deps"].as_array().unwrap() {
            let wanted = dep["dep_kinds"]
                .as_array()
                .unwrap()
                .iter()
                .any(|k| k["kind"].is_null() || k["kind"] == "build");
            if wanted {
                todo.push(dep["pkg"].as_str().unwrap().to_string());
            }
        }
    }
    let repo = paddock_testkit::path::text(Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(2).unwrap());
    meta["packages"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|p| p["source"].is_null() && seen.contains(p["id"].as_str().unwrap()))
        .map(|p| {
            let manifest = paddock_testkit::path::text(Path::new(p["manifest_path"].as_str().unwrap()));
            let dir = manifest.trim_end_matches("/Cargo.toml");
            dir.strip_prefix(&format!("{repo}/")).unwrap().to_string()
        })
        .collect()
}

/// What to change in an inputs file so it equals the generated set (ER-40, rule 79): the lines to add and the lines to remove, or
/// `None` when they agree. A hand list that must equal generated data names its regenerate step in the failure.
fn regenerate_hint(file: &str, listed: &BTreeSet<String>, expected: &BTreeSet<String>) -> Option<String> {
    let add: Vec<&String> = expected.difference(listed).collect();
    let remove: Vec<&String> = listed.difference(expected).collect();
    if add.is_empty() && remove.is_empty() {
        return None;
    }
    let lines = |v: &[&String]| v.iter().map(|l| format!("  {l}")).collect::<Vec<_>>().join("\n");
    Some(format!(
        "{file} and cargo metadata disagree. Regenerate: add these lines to {file}:\n{}\nand remove these:\n{}\n(one path per line, relative to the repository root)",
        lines(&add),
        lines(&remove)
    ))
}

#[test]
fn the_regenerate_hint_names_the_lines_to_add_and_to_remove() {
    let set = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<BTreeSet<_>>();
    let hint = regenerate_hint("f.txt", &set(&["a", "stale"]), &set(&["a", "crates/paddock-env"])).unwrap();
    assert!(hint.contains("add these lines to f.txt:\n  crates/paddock-env"), "{hint}");
    assert!(hint.contains("remove these:\n  stale"), "{hint}");
    assert!(regenerate_hint("f.txt", &set(&["a"]), &set(&["a"])).is_none());
}

#[test]
fn inputs_txt_matches_cargo_metadata() {
    let listed =
        paddock_dev::input_hash::parse_inputs(&std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("inputs.txt")).unwrap())
            .unwrap();
    let mut expected = path_dependency_folders(&metadata("paddock-dev"));
    expected.extend(EXTRAS.map(String::from));
    let listed_set: BTreeSet<String> = listed.iter().cloned().collect();
    assert_eq!(listed.len(), listed_set.len(), "inputs.txt lists a path twice");
    if let Some(hint) = regenerate_hint("tools/paddock-dev/inputs.txt", &listed_set, &expected) {
        panic!("{hint}");
    }
}

#[test]
fn dev_dependencies_are_not_inputs() {
    let listed = std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("inputs.txt")).unwrap();
    assert!(!listed.contains("paddock-testkit"));
}

#[test]
fn heavy_inputs_txt_matches_cargo_metadata() {
    let text = std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("../heavy/inputs.txt")).unwrap();
    let listed = paddock_dev::input_hash::parse_inputs(&text).unwrap();
    let mut expected = path_dependency_folders(&metadata("heavy"));
    expected.remove("tools/heavy");
    expected.extend(HEAVY_EXTRAS.map(String::from));
    let listed_set: BTreeSet<String> = listed.iter().cloned().collect();
    assert_eq!(listed.len(), listed_set.len(), "tools/heavy/inputs.txt lists a path twice");
    if let Some(hint) = regenerate_hint("tools/heavy/inputs.txt", &listed_set, &expected) {
        panic!("{hint}");
    }
}

//! The CI kit's `conformance/ci/job-isolation.sh` against this real binary (ADR 0025): acquire, a kept folder, release and the
//! disk sweep, with a fake HOME (the CI home is its `.paddock-ci`) and a fake runner job folder, all under a scratch folder
//! (rule 7: never the machine's CI home). Unix only: the script runs under Git bash on Windows, where the CI host jobs
//! themselves exercise it on every run.
// windows-twin: none: it runs the shell script, which the Windows host jobs exercise under Git bash on every run
#![cfg(unix)]
#![allow(clippy::disallowed_methods, clippy::unwrap_used, clippy::expect_used)]

use paddock_slots::{FsLocks, SlotId, SlotLocks};
use paddock_testkit::TestCommand;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Output;

fn script() -> PathBuf {
    crate::full_tree(&Path::new(env!("CARGO_MANIFEST_DIR")).join("../.."));
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../conformance/ci/job-isolation.sh")
}

struct Job {
    home: PathBuf,
    ci: PathBuf,
    temp: PathBuf,
    env_file: PathBuf,
}

impl Job {
    fn new(root: &Path) -> Job {
        let home = root.join("home");
        let temp = root.join("work/0123456789abcdef/tmp");
        std::fs::create_dir_all(&home).unwrap();
        std::fs::create_dir_all(&temp).unwrap();
        let env_file = root.join("work/0123456789abcdef/github-env");
        std::fs::write(&env_file, "").unwrap();
        Job {
            ci: home.join(".paddock-ci"),
            home,
            temp,
            env_file,
        }
    }

    fn exported(&self) -> HashMap<String, String> {
        std::fs::read_to_string(&self.env_file)
            .unwrap()
            .lines()
            .filter_map(|l| l.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
            .collect()
    }

    /// Runs the script as a host job's step: the slots of a CI home of its own, the real paddock-dev, nothing inherited.
    fn run(&self, args: &[&str], later: bool) -> Output {
        let mut cmd = TestCommand::new("bash");
        cmd.arg(script())
            .args(args)
            .env("HOME", &self.home)
            .env("RUNNER_OS", "macOS")
            .env("RUNNER_TEMP", &self.temp)
            .env("GITHUB_ENV", &self.env_file)
            .env("PADDOCK_DEV", crate::dev_bin::PATH)
            .env("PADDOCK_CI_SLOTS", "3")
            .env("PADDOCK_CI_KEEP_SLOTS", "1")
            .env("PADDOCK_CI_MIN_FREE_GB", "0")
            // ER-14: `dev disk check` must not depend on the real disk of the machine running the tests.
            .env("PADDOCK_DISK_WARN_GIB", "0")
            .env("PADDOCK_DISK_REFUSE_GIB", "0")
            .env("PADDOCK_DISK_INDEX", self.home.join("disk-index.sqlite"));
        if later {
            cmd.envs(self.exported());
        }
        cmd.output().unwrap()
    }
}

fn free(ci: &Path, n: u32) -> bool {
    FsLocks::new(ci).try_lock(SlotId::new(n).unwrap()).unwrap().is_some()
}

#[test]
fn job_isolation_sh_acquires_uses_releases_and_sweeps_with_the_real_binary() {
    let d = tempfile::tempdir().unwrap();
    // The CI home is resolved (ci-home.sh), so the scratch root must be too (macOS: /var is /private/var).
    let job = Job::new(&paddock_env::winpath::real(d.path()).unwrap());
    // An idle slot above the kept one, left by an earlier job: due, so the acquire's sweep removes it under its lock.
    std::fs::create_dir_all(job.ci.join("target-old-s3")).unwrap();

    let acq = job.run(&["acquire"], false);
    assert!(acq.status.success(), "{}", String::from_utf8_lossy(&acq.stderr));
    assert!(acq.stdout.is_empty(), "messages go to stderr");
    let env = job.exported();
    assert_eq!(env.get("PADDOCK_CI_SLOT").map(String::as_str), Some("s1"));
    assert!(env.get("PADDOCK_CI_SLOT_TOKEN").is_some_and(|t| !t.is_empty()));
    assert!(!free(&job.ci, 1), "the holder keeps s1 after acquire returned");
    assert!(!job.ci.join("target-old-s3").exists(), "the sweep removed the idle slot's folder");

    let path = job.run(&["path", "target", "x-app"], true);
    assert!(path.status.success());
    assert_eq!(
        String::from_utf8_lossy(&path.stdout).trim(),
        job.ci.join("target-x-app-s1").to_str().unwrap()
    );

    // A folder of s2 (above the one kept slot) and the job's own s1 folder: release frees s1, the sweep takes s2's.
    std::fs::create_dir_all(job.ci.join("target-y-s2")).unwrap();
    let rel = job.run(&["release"], true);
    assert!(rel.status.success(), "{}", String::from_utf8_lossy(&rel.stderr));
    assert!(free(&job.ci, 1), "released");
    assert!(!job.ci.join("target-y-s2").exists());
    assert!(job.ci.join("target-x-app-s1").exists(), "the kept slot's folder stays");
    let status = job.run(&["status"], false);
    assert!(String::from_utf8_lossy(&status.stdout).contains("s1 free"));
}

//! The shared parity corpus (`conformance/test/parity-corpus/variants.json`): every check that had a JavaScript host as well as a Rust
//! one is run over the same file in many spellings (a byte order mark, CRLF, astral characters and emoji, Unicode case-folding
//! letters, no-break spaces, line separators, a very long line) and the Rust findings are compared with what the JavaScript host
//! answered (recorded in `tests/fixtures/check/recorded/corpus-c<n>.json` before the module was retired, pair P3). The seed is the check's own
//! control tree (`Check::control`), so a check with a recorded answer needs one line here: `assert_no_divergence("C1xx")`.
#![allow(clippy::unwrap_used, clippy::expect_used)]
use super::check::repo_root;
use paddock_dev::check::{RunOptions, registry, run_checks};
use serde_json::{Value, json};
use std::path::Path;

/// One way of writing a file.
struct Variant {
    name: String,
    bom: bool,
    eol: Option<String>,
    prefix: String,
    suffix: String,
    nbsp: bool,
    trim: bool,
    /// The variant may take the site away (a different spelling of the code itself): the sites it must keep are then not asserted.
    may_empty: bool,
}

fn variants() -> Vec<Variant> {
    let text = std::fs::read_to_string(repo_root().join("conformance/test/parity-corpus/variants.json")).expect("the corpus");
    let v: Value = serde_json::from_str(&text).expect("the corpus is JSON");
    v["variants"]
        .as_array()
        .expect("variants")
        .iter()
        .map(|e| {
            let get = |k: &str| e[k].as_str().unwrap_or("").to_string();
            let repeat = e["suffixRepeat"]["text"].as_str().map_or(String::new(), |t| {
                t.repeat(e["suffixRepeat"]["times"].as_u64().unwrap_or(0) as usize)
            });
            Variant {
                name: get("name"),
                bom: e["bom"].as_bool().unwrap_or(false),
                eol: e["eol"].as_str().map(String::from),
                prefix: get("prefix"),
                suffix: format!("{}{repeat}", get("suffix")),
                nbsp: e["nbsp"].as_bool().unwrap_or(false),
                trim: e["trim"].as_bool().unwrap_or(false),
                may_empty: e["mayEmptyTree"].as_bool().unwrap_or(false),
            }
        })
        .collect()
}

impl Variant {
    fn apply(&self, text: &str) -> String {
        let mut t = text.to_string();
        if self.nbsp {
            // inside lines only: leading indentation is syntax (YAML), a space after the first word is not
            t = t
                .split('\n')
                .map(|l| {
                    let body = l.trim_start_matches([' ', '\t']);
                    format!("{}{}", &l[..l.len() - body.len()], body.replace(' ', "\u{a0}"))
                })
                .collect::<Vec<_>>()
                .join("\n");
        }
        if self.trim {
            t = t.trim_end_matches('\n').to_string();
        }
        t = format!("{}{t}{}", self.prefix, self.suffix);
        if let Some(eol) = &self.eol {
            t = t.replace('\n', eol);
        }
        if self.bom {
            t.insert(0, '\u{feff}');
        }
        t
    }
}

fn shared(v: &Value) -> Value {
    json!({"findings": v["findings"], "errors": v["errors"], "warnings": v["warnings"], "waived": v["waived"]})
}

fn options(root: &Path, id: &str) -> RunOptions {
    RunOptions {
        root: root.to_path_buf(),
        config: paddock_dev::check::config::Config::bare("paddock"),
        scope: None,
        only: Some(vec![id.to_string()]),
        files: None,
        today: "2026-11-16".into(),
        base_ref: Some("origin/main".into()),
        ci: Some(false),
    }
}

/// A file the corpus adds to the control tree: `(path, text)` with a site on line 1, the position a byte order mark or a different line
/// ending is most likely to move. In the `plain` variant the check must report it, on both hosts.
pub(crate) type Seed = (&'static str, &'static str);

/// What the Rust host is given in place of the file's text (a planted difference, to prove the corpus sees it).
type RustView = fn(&str) -> String;

fn field_difference(rust: &Value, js: &Value) -> Option<String> {
    for field in ["findings", "errors", "warnings", "waived"] {
        if rust[field] != js[field] {
            if field == "findings" {
                let (r, j) = (rust[field].as_array().unwrap(), js[field].as_array().unwrap());
                let first = r.iter().zip(j).find(|(a, b)| a != b).map_or_else(
                    || format!("{} findings in Rust, {} in JavaScript", r.len(), j.len()),
                    |(a, b)| format!("first difference: Rust {a} against JavaScript {b}"),
                );
                return Some(first);
            }
            return Some(format!("`{field}` differs: Rust {} against JavaScript {}", rust[field], js[field]));
        }
    }
    None
}

fn write_tree(files: &[(String, String)]) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    for (rel, body) in files {
        let to = dir.path().join(rel);
        std::fs::create_dir_all(to.parent().unwrap()).unwrap();
        std::fs::write(to, body).unwrap();
    }
    dir
}

/// The variants on which the two hosts of check `id` differ, each with what differs. The seed files are the check's control tree and
/// `seeds` (its allow file is data and is written as it is). Three more things are asserted, so the corpus proves itself: in the `plain`
/// variant the findings are exactly the control's expected ones plus a line-1 finding per seed, and in every other variant (unless it is
/// marked `mayEmptyTree`) each file that holds an expected site still has a finding.
pub(crate) fn divergences_with(id: &str, seeds: &[Seed], rust_view: RustView) -> Vec<String> {
    let reg = registry();
    let check = reg
        .iter()
        .find(|c| c.id() == id)
        .unwrap_or_else(|| panic!("{id} has no Rust twin in the registry"));
    let data = check.allow_list().map(|s| s.file);
    let control = check.control();
    let seed_files: Vec<(&str, &str)> = control.files.iter().copied().chain(seeds.iter().copied()).collect();
    let mut expected: Vec<(String, usize)> = control.expect.iter().map(|(f, l)| (f.to_string(), *l)).collect();
    expected.extend(seeds.iter().map(|(f, _)| (f.to_string(), 1)));
    let mut trees = Vec::new();
    for v in variants() {
        let view = |_: bool, mapper: Option<RustView>| -> Vec<(String, String)> {
            seed_files
                .iter()
                .map(|(rel, text)| {
                    let body = if Some(*rel) == data { (*text).to_string() } else { v.apply(text) };
                    let body = mapper.map_or(body.clone(), |m| m(&body));
                    (rel.to_string(), body)
                })
                .collect()
        };
        trees.push((v.name.clone(), v.may_empty, write_tree(&view(true, Some(rust_view)))));
    }
    let runs: Vec<_> = trees
        .iter()
        .map(|(_, _, rust_dir)| run_checks(&options(rust_dir.path(), id), &registry()).unwrap())
        .collect();
    // What the JS host answered on every variant (recorded before it was retired); a bless takes the Rust answers in their place.
    let ours: serde_json::Map<String, Value> = trees
        .iter()
        .zip(&runs)
        .map(|((n, ..), run)| (n.clone(), shared(&run.json())))
        .collect();
    let js = crate::recorded::expect(&format!("corpus-{}", id.to_lowercase()), &Value::Object(ours));
    let mut out = Vec::new();
    for ((name, may_empty, ..), run) in trees.iter().zip(&runs) {
        let held: Vec<(&str, usize)> = run.findings.iter().map(|f| (f.file.as_str(), f.line)).collect();
        if name == "plain" {
            let mut want: Vec<(&str, usize)> = expected.iter().map(|(f, l)| (f.as_str(), *l)).collect();
            want.sort_unstable();
            let mut got = held.clone();
            got.sort_unstable();
            assert_eq!(
                got, want,
                "{id}: the plain variant must give the control's expected findings and one on line 1 per seed"
            );
        } else if !may_empty {
            for (f, _) in &expected {
                if !held.iter().any(|(g, _)| g == f) {
                    out.push(format!(
                        "{id} variant `{name}`: the Rust host lost the expected site in {f} (mark the variant mayEmptyTree if it rewrites the code itself)"
                    ));
                }
            }
        }
        let rust = shared(&run.json());
        if let Some(why) = field_difference(&rust, &js[name]) {
            out.push(format!("{id} variant `{name}`: {why}"));
        }
    }
    out
}

/// [`divergences_with`] with the same text for both hosts.
pub(crate) fn divergences(id: &str, seeds: &[Seed]) -> Vec<String> {
    divergences_with(id, seeds, str::to_string)
}

/// Fails with the divergences of check `id` from the recorded JS answers (none is parity).
pub(crate) fn assert_no_divergence(id: &str, seeds: &[Seed]) {
    let d = divergences(id, seeds);
    assert!(
        d.is_empty(),
        "the JavaScript and Rust hosts of {id} differ on the shared corpus:\n{}",
        d.join("\n")
    );
}

/// A known divergence, with its measured `cause`: it fails when the hosts agree, so the marker is removed with the fix.
pub(crate) fn assert_known_divergence(id: &str, seeds: &[Seed], cause: &str) {
    let d = divergences(id, seeds);
    assert!(
        !d.is_empty(),
        "{id} now agrees on the shared corpus: remove its known-divergence marker and call assert_no_divergence (cause was: {cause})"
    );
}

/// The corpus sees a planted difference: giving the Rust host the text without its byte order mark removes C124's `bom` divergence.
#[test]
fn the_corpus_sees_a_planted_byte_order_mark_difference() {
    let real = divergences("C124", &[]);
    assert!(
        real.iter().any(|d| d.contains("`bom`")),
        "C124 diverges on the bom variant today: {real:?}"
    );
    let planted = divergences_with("C124", &[], |t| t.trim_start_matches('\u{feff}').to_string());
    assert!(
        !planted.iter().any(|d| d.contains("`bom`")),
        "a Rust host given the text without its BOM sees what JavaScript sees: {planted:?}"
    );
    // and a planted difference in a checked field is named
    let (rust, js) = (
        json!({"findings": [], "errors": 0, "warnings": 1, "waived": 0}),
        json!({"findings": [], "errors": 0, "warnings": 2, "waived": 0}),
    );
    assert_eq!(
        field_difference(&rust, &js).unwrap(),
        "`warnings` differs: Rust 1 against JavaScript 2"
    );
}

