//! The engineering-rules `scripts/worktree.sh` is the oracle for add, list and clean: the same fixture repository goes
//! through both tools and their decisions are compared. The tests run against a pinned copy of the script
//! (`tests/fixtures/worktree-oracle/worktree-sh.txt`, its source commit in the first line); `WORKTREE_SH` names another
//! script instead (for example the current one in engineering-rules). A test that did not run must not pass (ER-33), so
//! there is no skip.
use super::Fixture;
use paddock_testkit::TestCommand;
use std::collections::BTreeMap;
use std::path::PathBuf;

/// The oracle script: `WORKTREE_SH`, else the pinned copy.
fn script() -> PathBuf {
    std::env::var("WORKTREE_SH")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/worktree-oracle/worktree-sh.txt"))
}

#[test]
fn the_pinned_oracle_names_its_source_commit() {
    let text =
        std::fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/worktree-oracle/worktree-sh.txt")).unwrap();
    let first = text.lines().next().unwrap();
    let sha = first
        .split("at commit ")
        .nth(1)
        .and_then(|r| r.split_whitespace().next())
        .unwrap_or("");
    assert!(sha.len() == 40 && sha.bytes().all(|b| b.is_ascii_hexdigit()), "{first}");
    assert_eq!(text.lines().nth(1), Some("#!/bin/bash"), "the script follows its header line");
}

// Starts the tool under test, git or a helper by program name (a throw-away fixture), never a process by pid (C53).
#[allow(clippy::disallowed_methods)]
fn sh(fx: &Fixture, args: &[&str]) -> String {
    let out = TestCommand::new("bash")
        .arg(script())
        .args(args)
        .env("WT_REPO", &fx.primary)
        .env("WT_ROOT", fx.root.join("sh-wt"))
        .env("WT_BUILD_ROOT", fx.root.join("sh-build"))
        .env("GIT_CONFIG_GLOBAL", fx.root.join("gitconfig"))
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .output()
        .unwrap();
    assert!(
        out.status.success(),
        "worktree.sh {args:?}: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8_lossy(&out.stdout).into_owned()
}

/// Branches made by worktree.sh: merged (committed, fast-forwarded into main), unmerged, empty, and merged but dirty.
fn build(fx: &Fixture) -> BTreeMap<&'static str, PathBuf> {
    let mut out = BTreeMap::new();
    for name in ["merged", "unmerged", "empty", "dirtymerged"] {
        sh(fx, &["add", name, "--base", "main"]);
        out.insert(name, paddock_env::winpath::real(&fx.root.join("sh-wt").join(name)).unwrap());
    }
    for name in ["merged", "unmerged", "dirtymerged"] {
        fx.commit_in(&out[name], &format!("{name}.txt"));
    }
    for name in ["merged", "dirtymerged"] {
        fx.git(&fx.primary, &["merge", "-q", "--no-edit", name]);
    }
    std::fs::write(out["dirtymerged"].join("wip.txt"), "x").unwrap();
    out
}

/// worktree.sh's list as (branch, merged, state) by path.
fn sh_list(fx: &Fixture) -> BTreeMap<String, (String, String, String)> {
    sh(fx, &["list", "--base", "main"])
        .lines()
        .skip(1)
        .map(|l| {
            let f: Vec<&str> = l.split_whitespace().collect();
            (
                f[0].to_string(),
                (f[1].to_string(), f[f.len() - 2].to_string(), f[f.len() - 1].to_string()),
            )
        })
        .collect()
}

#[test]
fn list_agrees_with_worktree_sh_on_merged_and_dirty() {
    let fx = Fixture::new();
    let made = build(&fx);
    let theirs = sh_list(&fx);
    assert_eq!(theirs.len(), 4, "{theirs:?}");
    let ours = fx.dev(&["worktree", "list", "--base", "main"]).json;
    for (name, path) in &made {
        let key = path.to_str().unwrap();
        let (branch, merged, state) = &theirs[key];
        let w = ours["worktrees"].as_array().unwrap().iter().find(|w| w["path"] == key).unwrap();
        assert_eq!(w["branch"], branch.as_str(), "{name}");
        assert_eq!(w["merged"], merged.as_str(), "{name}: ours {} theirs {merged}", w["merged"]);
        assert_eq!(w["dirty"], state == "dirty", "{name}");
    }
}

#[test]
fn clean_removes_the_same_worktrees_as_worktree_sh() {
    let fx = Fixture::new();
    let made = build(&fx);
    // worktree.sh trusts "merged into local main"; the tool also wants the commits on a remote (it never removes work no remote
    // has), so the fixture pushes main first, as a landing does.
    fx.git(&fx.primary, &["push", "-q", "origin", "main"]);
    fx.git(&fx.primary, &["fetch", "-q", "origin"]);
    let theirs: Vec<String> = sh(&fx, &["clean", "--base", "main", "--dry-run"])
        .lines()
        .filter_map(|l| l.strip_prefix("would remove "))
        .map(|l| l.split(',').next().unwrap().to_string())
        .collect();
    assert_eq!(
        theirs,
        vec![made["merged"].to_str().unwrap().to_string()],
        "the oracle's own decision"
    );
    let ours = fx.dev(&["worktree", "clean", "--base", "main", "--dry-run"]).json;
    let removed: Vec<String> = ours["removed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v["path"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(removed, theirs);
    let kept: Vec<String> = ours["kept"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v["path"].as_str().unwrap().to_string())
        .collect();
    for name in ["unmerged", "empty", "dirtymerged"] {
        assert!(kept.contains(&made[name].to_str().unwrap().to_string()), "{name} kept: {kept:?}");
    }
    let real = fx.dev(&["worktree", "clean", "--base", "main"]);
    assert_eq!(real.code, 0, "{} {}", real.json, real.err);
    assert!(!made["merged"].exists());
    assert!(["unmerged", "empty", "dirtymerged"].iter().all(|n| made[n].exists()));
}

#[test]
fn add_starts_from_the_same_commit_on_a_new_branch_but_locks_it() {
    let fx = Fixture::new();
    sh(&fx, &["add", "theirs", "--base", "main"]);
    let theirs = paddock_env::winpath::real(&fx.root.join("sh-wt/theirs")).unwrap();
    let path = fx.path("ours");
    let r = fx.dev(&["worktree", "add", "ours", "--base", "main", "--owner", "implementer:x"]);
    assert_eq!(r.code, 0, "{}", r.err);
    assert_eq!(fx.git(&theirs, &["rev-parse", "HEAD"]), fx.git(&path, &["rev-parse", "HEAD"]));
    assert_eq!(fx.git(&path, &["rev-parse", "--abbrev-ref", "HEAD"]), "ours");
    assert!(fx.lock_reason(&path).is_some(), "ours is locked");
    assert!(fx.lock_reason(&theirs).is_none(), "worktree.sh's is not (WP-4 adds --owner there)");
    let again = fx.dev(&["worktree", "add", "ours", "--base", "main", "-b", "x", "--owner", "a:b"]);
    assert_eq!(again.code, 4, "both refuse an existing path: {}", again.err);
}

//! The `./dev` wrapper and `dev self hash` compute one value, in shell and in Rust, from the same inputs.
//!
//! Every child these tests start has CARGO_TARGET_DIR and CARGO_BUILD_TARGET_DIR removed (ER-47, a named clearing): the wrapper warns about
//! them and the toolchain checks fail on that warning, so a test's result would depend on the build folder the agent running it exports.
#![allow(clippy::unwrap_used, clippy::expect_used)]
use paddock_dev::input_hash::{Real, compute, is_hashed_var};
use paddock_testkit::TestCommand;
use std::path::{Path, PathBuf};
use std::process::Command;

fn repo_root() -> PathBuf {
    crate::full_tree(Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(2).unwrap())
}

#[expect(
    clippy::disallowed_methods,
    reason = "a test starts the program under test (git, sh, bash); nothing here ends a process by pid"
)]
fn git(dir: &Path, args: &[&str]) {
    let st = Command::new("git")
        .arg("-C")
        .arg(dir)
        .args([
            "-c",
            "user.name=t",
            "-c",
            "user.email=t@example.invalid",
            "-c",
            "commit.gpgsign=false",
            "-c",
            "core.autocrlf=false",
        ])
        .args(args)
        .status()
        .unwrap();
    assert!(st.success(), "git {args:?}");
}

/// A repository with the real wrapper and input list, and a placeholder for every listed path.
pub(crate) struct Fixture {
    dir: tempfile::TempDir,
    repo: PathBuf,
    pub(crate) cargo_home: tempfile::TempDir,
}

impl Fixture {
    pub(crate) fn new() -> Fixture {
        // The repository sits one folder below the scratch folder, so a test can put a config "above the repository".
        let dir = tempfile::tempdir().unwrap();
        let repo = dir.path().join("repo");
        let root = repo.as_path();
        std::fs::create_dir_all(root.join("tools/paddock-dev/src")).unwrap();
        std::fs::copy(repo_root().join("dev"), root.join("dev")).unwrap();
        let inputs = std::fs::read_to_string(repo_root().join("tools/paddock-dev/inputs.txt")).unwrap();
        std::fs::write(root.join("tools/paddock-dev/inputs.txt"), &inputs).unwrap();
        std::fs::write(root.join("tools/paddock-dev/src/main.rs"), "fn main() {}\n").unwrap();
        for p in paddock_dev::input_hash::parse_inputs(&inputs).unwrap() {
            if p.ends_with(".toml") {
                let f = root.join(&p);
                std::fs::create_dir_all(f.parent().unwrap()).unwrap();
                std::fs::write(f, "# placeholder\n").unwrap();
            } else {
                std::fs::create_dir_all(root.join(&p)).unwrap();
                std::fs::write(root.join(&p).join("keep"), "x\n").unwrap();
            }
        }
        std::fs::write(root.join(".gitignore"), "/tools/paddock-dev/target/\n").unwrap();
        git(root, &["init", "-q", "-b", "main"]);
        git(root, &["add", "."]);
        git(root, &["commit", "-q", "-m", "chore: fixture"]);
        Fixture {
            dir,
            repo: repo.clone(),
            cargo_home: tempfile::tempdir().unwrap(),
        }
    }

    pub(crate) fn root(&self) -> &Path {
        &self.repo
    }

    /// The environment both implementations see (no user config: an empty CARGO_HOME).
    fn env(&self, extra: &[(&str, String)]) -> Vec<(String, String)> {
        let mut v = vec![("CARGO_HOME".to_string(), self.cargo_home.path().display().to_string())];
        v.extend(extra.iter().map(|(k, val)| (k.to_string(), val.clone())));
        v
    }

    fn shell(&self, env: &[(String, String)]) -> (String, bool) {
        let mut cmd = TestCommand::new("sh");
        cmd.arg(self.root().join("dev"))
            .arg("--wrapper-hash")
            .current_dir(self.root().join("tools/paddock-dev/src"))
            .env_remove("RUSTC")
            .env_remove("CARGO_BUILD_RUSTC")
            .env_remove("CARGO_TARGET_DIR")
            .env_remove("CARGO_BUILD_TARGET_DIR");
        // The hash reads the environment: start from none of the variables it uses, as `rust` does.
        paddock_dev::process_env::vars()
            .filter(|(k, _)| is_hashed_var(k))
            .for_each(|(k, _)| {
                cmd.env_remove(k);
            });
        cmd.envs(env.iter().cloned());
        // Tests never touch the user's cache: the wrapper's home is a scratch folder too.
        cmd.env("PADDOCK_DEV_HOME", self.cargo_home.path().join("dev-home"));
        let out = cmd.output().unwrap();
        assert!(
            !self.cargo_home.path().join("dev-home").exists(),
            "--wrapper-hash must not create the cache"
        );
        assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
        let text = String::from_utf8_lossy(&out.stdout).into_owned();
        let mut lines = text.lines();
        (lines.next().unwrap().to_string(), lines.next() == Some("dirty"))
    }

    fn rust(&self, env: &[(String, String)]) -> (String, bool) {
        let get = |k: &str| env.iter().find(|(n, _)| n == k).map(|(_, v)| v.clone());
        let h = compute(&Real, &get, env, self.root()).unwrap();
        (h.hash, h.dirty)
    }

    pub(crate) fn both(&self, extra: &[(&str, String)]) -> (String, bool) {
        let env = self.env(extra);
        let (s, r) = (self.shell(&env), self.rust(&env));
        assert_eq!(s, r, "the wrapper and the tool must agree");
        s
    }
}

/// A "compiler" that prints a chosen `-vV`.
#[cfg(unix)]
pub(crate) fn fake_rustc(dir: &Path, name: &str, release: &str, commit: &str, host: &str) -> String {
    let p = dir.join(name);
    let body = format!(
        "#!/bin/sh\nprintf 'rustc {release}\\nbinary: rustc\\ncommit-hash: {commit}\\ncommit-date: d\\nhost: {host}\\nrelease: {release}\\nLLVM version: 1\\n'\n"
    );
    paddock_testkit::exe::write_program(&p, body).unwrap();
    p.display().to_string()
}

